window.ETS_DB_TESTS["E25_T01"] = [{"q":1,"part":1,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_01.mp3","photo":"web_assets/ets2025/p1/E25_T01_Q01.webp","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_00.webp"],"stem_en":"Look at the picture marked number 1 in your test book.","stem_vi":"Hãy nhìn vào bức tranh số 1 trong sách đề thi của bạn.","options":{"A":{"en":"She's eating in a picnic area.","vi":"Cô ấy đang ăn tại một khu vực dã ngoại."},"B":{"en":"She's waiting in line at a food truck.","vi":"Cô ấy đang xếp hàng chờ trước một xe bán đồ ăn."},"C":{"en":"She's wiping off a bench.","vi":"Cô ấy đang lau một chiếc ghế dài."},"D":{"en":"She's throwing away a plate.","vi":"Cô ấy đang vứt một chiếc đĩa đi."}},"ans":"A","explanation":"Đáp án đúng: (A) Cô ấy đang ăn tại một khu vực dã ngoại — khớp trực tiếp với cảnh người phụ nữ ngồi một mình tại bàn dã ngoại ngoài trời, trước mặt có đĩa giấy đựng thức ăn và tay phải đang đưa đồ ăn lên miệng.\nDẫn chứng: Ảnh chụp một người phụ nữ ngồi tại bàn dã ngoại bằng đá/bê tông trên bãi cỏ ngoài trời, tay trái cầm thức ăn, tay phải đưa về phía miệng, trên bàn có đĩa thức ăn và khăn giấy (phía sau là bãi xe có một chiếc ô tô con và xe cắm trại RV đỗ yên).\nPhân tích bẫy:\n- (B) Sai chủ thể và bối cảnh: Trong ảnh không có hàng người xếp hàng và chiếc xe lớn đỗ phía sau là xe cắm trại (camper RV), không phải xe bán đồ ăn (food truck).\n- (C) Sai hành động: Cô ấy đang ăn từ đĩa thức ăn trên bàn, không cầm khăn hay lau chùi ghế dài.\n- (D) Sai trạng thái đồ vật: Chiếc đĩa giấy vẫn còn nguyên đồ ăn đặt ngay trước mặt cô ấy trên bàn, không có động tác vứt đĩa đi.","lines":[{"speaker":"(A)","en":"She's eating in a picnic area.","vi":"Cô ấy đang ăn tại một khu vực dã ngoại.","units":[{"en":"She's eating in a picnic area.","vi":"Cô ấy đang ăn tại một khu vực dã ngoại."}]},{"speaker":"(B)","en":"She's waiting in line at a food truck.","vi":"Cô ấy đang xếp hàng chờ trước một xe bán đồ ăn.","units":[{"en":"She's waiting in line at a food truck.","vi":"Cô ấy đang xếp hàng chờ trước một xe bán đồ ăn."}]},{"speaker":"(C)","en":"She's wiping off a bench.","vi":"Cô ấy đang lau một chiếc ghế dài.","units":[{"en":"She's wiping off a bench.","vi":"Cô ấy đang lau một chiếc ghế dài."}]},{"speaker":"(D)","en":"She's throwing away a plate.","vi":"Cô ấy đang vứt một chiếc đĩa đi.","units":[{"en":"She's throwing away a plate.","vi":"Cô ấy đang vứt một chiếc đĩa đi."}]}],"vocab":[{"word":"picnic area","pos":"phr","ipa":"/ˈpɪknɪk ˈeriə/","meaning":"khu vực dã ngoại"},{"word":"wait in line","pos":"phr","ipa":"/weɪt ɪn ˈlaɪn/","meaning":"xếp hàng chờ"},{"word":"wipe off","pos":"phr. v","ipa":"/waɪp ˈɔːf/","meaning":"lau sạch, lau chùi bề mặt"},{"word":"throw away","pos":"phr. v","ipa":"/θroʊ əˈweɪ/","meaning":"vứt bỏ, bỏ đi"}],"isScanBacked":false,"grammarType":"Part 1 — Tranh tả 1 người (Hành động & Động tác cụ thể)","formula":"CÔNG THỨC PART 1 (PART 1 THUỘC LÒNG — Tranh 1 người): Quan sát tư thế + hành động tay/mắt + đồ vật trên bàn (PHOTO -> SUBJECT -> ACTION -> SETTING); loại các đáp án gán sai vật thể ở nền ảnh.","optionAnalysis":{"A":"Đúng trực tiếp với ảnh: người phụ nữ ngồi một mình tại bàn dã ngoại ngoài trời và đang đưa thức ăn lên miệng ăn.","B":"Bẫy suy diễn từ xe RV phía sau: không có xe bán đồ ăn (food truck) và cũng không có ai đang xếp hàng chờ.","C":"Sai động tác chính: cô ấy đang cầm thức ăn để ăn, hoàn toàn không có hành động lau chùi bề mặt ghế dài.","D":"Sai hành động với vật thể: đĩa thức ăn vẫn nằm trên bàn trước mặt cô ấy chứ không bị vứt bỏ."},"evDocIdx":0,"evTargets":[{"badge":"Câu 1 · Đáp án A","opt":"A","isCorrect":true,"quote":"She's eating in a picnic area.","viQuote":"Cô ấy đang ăn tại một khu vực dã ngoại."}],"evQuotes":["She's eating in a picnic area."]},{"q":2,"part":1,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_02.mp3","photo":"web_assets/ets2025/p1/E25_T01_Q02.webp","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_00.webp"],"stem_en":"Look at the picture marked number 2 in your test book.","stem_vi":"Hãy nhìn vào bức tranh số 2 trong sách đề thi của bạn.","options":{"A":{"en":"The man is brushing snow off the roof of a car.","vi":"Người đàn ông đang quét tuyết khỏi nóc một chiếc ô tô."},"B":{"en":"The man is standing in the snow beside a car.","vi":"Người đàn ông đang đứng trên nền tuyết bên cạnh một chiếc ô tô."},"C":{"en":"The man is shoveling snow from a walkway.","vi":"Người đàn ông đang xúc tuyết trên lối đi."},"D":{"en":"The man is running through the snow.","vi":"Người đàn ông đang chạy qua lớp tuyết."}},"ans":"B","explanation":"Đáp án đúng: (B) Người đàn ông đang đứng trên nền tuyết bên cạnh một chiếc ô tô — mô tả chính xác tư thế và vị trí của người đàn ông mặc đồ mùa đông đứng giữa tuyết dày ngay sát cửa sau đang mở của chiếc xe phủ đầy tuyết.\nDẫn chứng: Ảnh cho thấy một người đàn ông đội mũ len, mặc áo khoác, đeo găng tay đang đứng trên nền tuyết dày ngay bên cạnh cửa sau mở của một chiếc sedan tối màu bị tuyết phủ dày trên nóc và kính chắn gió; tay phải anh đưa về phía mép cửa xe.\nPhân tích bẫy:\n- (A) Sai vị trí tay và dụng cụ: Tay anh ấy đặt thấp gần cánh cửa bên hông đang mở, không đưa lên nóc xe và không cầm chổi quét tuyết.\n- (C) Bẫy dụng cụ không có thật: Không thấy chiếc xẻng nào trong tay anh ấy và cũng không có lối đi đang được xúc tuyết.\n- (D) Sai động thái: Anh ấy đang đứng tại chỗ bên cạnh cánh cửa xe mở, không phải đang chạy qua lớp tuyết.","lines":[{"speaker":"(A)","en":"The man is brushing snow off the roof of a car.","vi":"Người đàn ông đang quét tuyết khỏi nóc một chiếc ô tô.","units":[{"en":"The man is brushing snow off the roof of a car.","vi":"Người đàn ông đang quét tuyết khỏi nóc một chiếc ô tô."}]},{"speaker":"(B)","en":"The man is standing in the snow beside a car.","vi":"Người đàn ông đang đứng trên nền tuyết bên cạnh một chiếc ô tô.","units":[{"en":"The man is standing in the snow beside a car.","vi":"Người đàn ông đang đứng trên nền tuyết bên cạnh một chiếc ô tô."}]},{"speaker":"(C)","en":"The man is shoveling snow from a walkway.","vi":"Người đàn ông đang xúc tuyết trên lối đi.","units":[{"en":"The man is shoveling snow from a walkway.","vi":"Người đàn ông đang xúc tuyết trên lối đi."}]},{"speaker":"(D)","en":"The man is running through the snow.","vi":"Người đàn ông đang chạy qua lớp tuyết.","units":[{"en":"The man is running through the snow.","vi":"Người đàn ông đang chạy qua lớp tuyết."}]}],"vocab":[{"word":"brush off","pos":"phr. v","ipa":"/brʌʃ ˈɔːf/","meaning":"quét sạch, phủi sạch"},{"word":"beside","pos":"prep","ipa":"/bɪˈsaɪd/","meaning":"ở bên cạnh"},{"word":"shovel","pos":"v","ipa":"/ˈʃʌvəl/","meaning":"xúc (tuyết, đất)"},{"word":"walkway","pos":"n","ipa":"/ˈwɔːkweɪ/","meaning":"lối đi bộ"}],"isScanBacked":false,"grammarType":"Part 1 — Tranh tả 1 người (Trạng thái, Trang phục & Vị trí)","formula":"CÔNG THỨC PART 1 (khảo bài part 1 — Trạng thái & Vị trí): Xác định chính xác vị trí đứng/ngồi của nhân vật so với vật thể lớn ('standing in the snow beside a car') và kiểm tra tay nhân vật có cầm dụng cụ hay không.","optionAnalysis":{"A":"Sai vị trí tác động: tay anh đặt gần cánh cửa hông đang mở và không cầm chổi quét tuyết trên nóc xe.","B":"Đúng hoàn toàn: người đàn ông mặc trang phục mùa đông đang đứng trên nền tuyết ngay cạnh chiếc ô tô.","C":"Bẫy liên tưởng mùa đông: anh ấy không cầm xẻng và không hề thực hiện động tác xúc tuyết trên lối đi.","D":"Sai động tác cơ thể: nhân vật đứng yên cạnh cửa xe mở, không có chuyển động chạy qua tuyết."},"evDocIdx":0,"evTargets":[{"badge":"Câu 2 · Đáp án B","opt":"B","isCorrect":true,"quote":"The man is standing in the snow beside a car.","viQuote":"Người đàn ông đang đứng trên nền tuyết bên cạnh một chiếc ô tô."}],"evQuotes":["The man is standing in the snow beside a car."]},{"q":3,"part":1,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_03.mp3","photo":"web_assets/ets2025/p1/E25_T01_Q03.webp","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_00.webp"],"stem_en":"Look at the picture marked number 3 in your test book.","stem_vi":"Hãy nhìn vào bức tranh số 3 trong sách đề thi của bạn.","options":{"A":{"en":"Some workers are hanging art in a gallery.","vi":"Một vài nhân viên đang treo tranh nghệ thuật trong phòng trưng bày."},"B":{"en":"Two of the people are having a conversation.","vi":"Hai người trong số họ đang trò chuyện với nhau."},"C":{"en":"One of the men is rearranging cushions on a sofa.","vi":"Một trong những người đàn ông đang sắp xếp lại gối tựa trên ghế sofa."},"D":{"en":"One of the men is painting a picture.","vi":"Một trong những người đàn ông đang vẽ một bức tranh."}},"ans":"B","explanation":"Đáp án đúng: (B) Hai người trong số họ đang trò chuyện với nhau — tương ứng với cặp nam nữ đứng ở góc trái phía sau phòng trưng bày, mặt hướng về nhau để trao đổi.\nDẫn chứng: Trong phòng trưng bày tranh lát sàn gỗ có 4 khách tham quan: ở phía trái, một người đàn ông khoanh tay đứng đối diện nói chuyện với một phụ nữ mặc áo kẻ và áo gile tối màu; ở giữa có người ngồi ghế sofa đọc sách và bên phải có người đứng xem tranh treo tường.\nPhân tích bẫy:\n- (A) Bẫy thì tiếp diễn cho trạng thái sẵn có: Tất cả tranh đóng khung đã được treo cố định ngay ngắn trên tường kèm bảng chú thích từ trước, không có nhân viên nào đang treo tranh.\n- (C) Sai chi tiết đồ vật và hành động: Hai chiếc ghế sofa da giữa phòng thiết kế liền khối không có gối tựa rời, và người ngồi trên ghế đang đọc sách chứ không sắp xếp gối.\n- (D) Sai động tác: Các vị khách chỉ đang tham quan, đọc tài liệu và trò chuyện, không ai cầm cọ vẽ tranh.","lines":[{"speaker":"(A)","en":"Some workers are hanging art in a gallery.","vi":"Một vài nhân viên đang treo tranh nghệ thuật trong phòng trưng bày.","units":[{"en":"Some workers are hanging art in a gallery.","vi":"Một vài nhân viên đang treo tranh nghệ thuật trong phòng trưng bày."}]},{"speaker":"(B)","en":"Two of the people are having a conversation.","vi":"Hai người trong số họ đang trò chuyện với nhau.","units":[{"en":"Two of the people are having a conversation.","vi":"Hai người trong số họ đang trò chuyện với nhau."}]},{"speaker":"(C)","en":"One of the men is rearranging cushions on a sofa.","vi":"Một trong những người đàn ông đang sắp xếp lại gối tựa trên ghế sofa.","units":[{"en":"One of the men is rearranging cushions on a sofa.","vi":"Một trong những người đàn ông đang sắp xếp lại gối tựa trên ghế sofa."}]},{"speaker":"(D)","en":"One of the men is painting a picture.","vi":"Một trong những người đàn ông đang vẽ một bức tranh.","units":[{"en":"One of the men is painting a picture.","vi":"Một trong những người đàn ông đang vẽ một bức tranh."}]}],"vocab":[{"word":"gallery","pos":"n","ipa":"/ˈɡæləri/","meaning":"phòng trưng bày nghệ thuật"},{"word":"have a conversation","pos":"phr","ipa":"/hæv ə ˌkɑːnvərˈseɪʃən/","meaning":"trò chuyện, trao đổi"},{"word":"rearrange","pos":"v","ipa":"/ˌriːəˈreɪndʒ/","meaning":"sắp xếp lại"},{"word":"cushion","pos":"n","ipa":"/ˈkʊʃən/","meaning":"gối tựa, đệm ghế"}],"isScanBacked":false,"grammarType":"Part 1 — Tranh tả nhiều người (Hành động & Bối cảnh chung)","formula":"CÔNG THỨC PART 1 (PART 1 THUỘC LÒNG — Tranh nhiều người): Phân biệt hành động đang diễn ra ('having a conversation') với trạng thái hoàn tất của vật thể ('artworks already hung' vs 'are hanging art').","optionAnalysis":{"A":"Bẫy hành động tiếp diễn: các bức tranh đã được treo sẵn trên tường phòng trưng bày, không có nhân viên đang treo.","B":"Đúng với góc trái ảnh: người đàn ông và người phụ nữ đứng đối diện nhau và đang trò chuyện.","C":"Sai cả vật thể lẫn hành động: ghế sofa không có gối tựa rời và người ngồi trên ghế đang cúi đọc sách.","D":"Sai hoạt động bối cảnh: khách tham quan chỉ ngắm tranh hoàn thiện đã đóng khung, không có ai đang vẽ tranh."},"evDocIdx":0,"evTargets":[{"badge":"Câu 3 · Đáp án B","opt":"B","isCorrect":true,"quote":"Two of the people are having a conversation.","viQuote":"Hai người trong số họ đang trò chuyện với nhau."}],"evQuotes":["Two of the people are having a conversation."]},{"q":4,"part":1,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_04.mp3","photo":"web_assets/ets2025/p1/E25_T01_Q04.webp","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_01.webp"],"stem_en":"Look at the picture marked number 4 in your test book.","stem_vi":"Hãy nhìn vào bức tranh số 4 trong sách đề thi của bạn.","options":{"A":{"en":"Vehicles are entering a parking garage.","vi":"Các phương tiện đang đi vào nhà đỗ xe."},"B":{"en":"Clothes hangers are scattered on the ground.","vi":"Những chiếc móc treo quần áo nằm rải rác trên mặt đất."},"C":{"en":"Empty racks are lined up next to a building.","vi":"Những giá treo trống được xếp thành hàng bên cạnh một tòa nhà."},"D":{"en":"Clothing is being displayed under a tent.","vi":"Quần áo đang được trưng bày bên dưới một chiếc lều bạt."}},"ans":"D","explanation":"Đáp án đúng: (D) Quần áo đang được trưng bày bên dưới một chiếc lều bạt — miêu tả chính xác gian hàng ngoài trời với quần áo treo trên các giá đẩy và khung mái bên dưới chiếc lều bạt trắng.\nDẫn chứng: Ảnh chụp khu chợ/bãi bán hàng ngoài trời với hai giá treo kim loại chứa đầy áo phông trên móc cùng ba áo dài tay treo cao hơn trên khung mái bên dưới lều bạt trắng (bên trái có một xe SUV tối màu đỗ yên, bên phải có bàn bày mũ lưỡi trai).\nPhân tích bẫy:\n- (A) Sai chuyển động và địa điểm: Chỉ thấy đầu một chiếc xe SUV/xe tải đỗ tĩnh cạnh gian hàng trên bãi nhựa ngoài trời, không có xe di chuyển vào nhà đỗ xe.\n- (B) Trái ngược thực tế ảnh: Toàn bộ móc áo đang treo quần áo gọn gàng trên giá và khung lều, không có chiếc nào nằm rải rác trên mặt đất.\n- (C) Sai trạng thái và vị trí: Các giá treo chứa chật kín quần áo chứ không trống rỗng, và chúng nằm dưới mái lều ngoài bãi chứ không xếp dọc cạnh tòa nhà.","lines":[{"speaker":"(A)","en":"Vehicles are entering a parking garage.","vi":"Các phương tiện đang đi vào nhà đỗ xe.","units":[{"en":"Vehicles are entering a parking garage.","vi":"Các phương tiện đang đi vào nhà đỗ xe."}]},{"speaker":"(B)","en":"Clothes hangers are scattered on the ground.","vi":"Những chiếc móc treo quần áo nằm rải rác trên mặt đất.","units":[{"en":"Clothes hangers are scattered on the ground.","vi":"Những chiếc móc treo quần áo nằm rải rác trên mặt đất."}]},{"speaker":"(C)","en":"Empty racks are lined up next to a building.","vi":"Những giá treo trống được xếp thành hàng bên cạnh một tòa nhà.","units":[{"en":"Empty racks are lined up next to a building.","vi":"Những giá treo trống được xếp thành hàng bên cạnh một tòa nhà."}]},{"speaker":"(D)","en":"Clothing is being displayed under a tent.","vi":"Quần áo đang được trưng bày bên dưới một chiếc lều bạt.","units":[{"en":"Clothing is being displayed under a tent.","vi":"Quần áo đang được trưng bày bên dưới một chiếc lều bạt."}]}],"vocab":[{"word":"vehicle","pos":"n","ipa":"/ˈviːɪkəl/","meaning":"phương tiện giao thông"},{"word":"scatter","pos":"v","ipa":"/ˈskætər/","meaning":"nằm rải rác, vương vãi"},{"word":"rack","pos":"n","ipa":"/ræk/","meaning":"giá treo (quần áo)"},{"word":"display","pos":"v","ipa":"/dɪˈspleɪ/","meaning":"trưng bày"}],"isScanBacked":false,"grammarType":"Part 1 — Tranh tả vật & Cảnh quan (Bị động trạng thái / Hiện hữu)","formula":"CÔNG THỨC PART 1 (khảo bài part 1 — Tranh tả vật): Nhận diện cấu trúc bị động hiện tại tiếp diễn chỉ trạng thái trưng bày ('is being displayed') và loại bỏ các chi tiết trái ngược trực tiếp với ảnh ('empty racks', 'scattered').","optionAnalysis":{"A":"Sai trạng thái phương tiện: chỉ có một chiếc xe đỗ yên bên trái trên sân nhựa, không phải xe đang chạy vào nhà để xe.","B":"Trái ngược hoàn toàn với ảnh: móc treo đều đang giữ quần áo ngay ngắn trên giá và khung lều, không rơi trên đất.","C":"Sai tính từ mô tả: các giá treo chật kín áo quần chứ không trống ('empty'), và đặt dưới lều chứ không cạnh tòa nhà.","D":"Khớp chính xác cảnh chợ ngoài trời: quần áo được treo gọn trên giá đẩy và khung mái bên dưới lều bạt trắng."},"evDocIdx":0,"evTargets":[{"badge":"Câu 4 · Đáp án D","opt":"D","isCorrect":true,"quote":"Clothing is being displayed under a tent.","viQuote":"Quần áo đang được trưng bày bên dưới một chiếc lều bạt."}],"evQuotes":["Clothing is being displayed under a tent."]},{"q":5,"part":1,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_05.mp3","photo":"web_assets/ets2025/p1/E25_T01_Q05.webp","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_01.webp"],"stem_en":"Look at the picture marked number 5 in your test book.","stem_vi":"Hãy nhìn vào bức tranh số 5 trong sách đề thi của bạn.","options":{"A":{"en":"Potted plants have been suspended from a ceiling.","vi":"Những chậu cây được treo thả từ trần nhà."},"B":{"en":"Chairs have been stacked in front of an entryway.","vi":"Những chiếc ghế đã được xếp chồng lên nhau trước lối vào."},"C":{"en":"A computer station has been set up on a desk.","vi":"Một bộ máy tính làm việc đã được lắp đặt trên bàn."},"D":{"en":"A rug has been rolled up against a wall.","vi":"Một tấm thảm đã được cuộn lại dựng sát tường."}},"ans":"C","explanation":"Đáp án đúng: (C) Một bộ máy tính làm việc đã được lắp đặt trên bàn — khớp trực tiếp với chiếc bàn gỗ ở tiền cảnh đặt đầy đủ màn hình máy tính, bàn phím, chuột, máy in laser trắng và ghế ngồi.\nDẫn chứng: Tiền cảnh giữa sảnh tiếp đón hiện đại là bàn gỗ chữ nhật bố trí thành góc làm việc máy tính gồm màn hình, bàn phím, chuột, máy in trắng bên phải và ghế gỗ kéo sát bàn (bên trái bàn là chậu cây cao đặt trên sàn thảm phẳng).\nPhân tích bẫy:\n- (A) Sai vị trí đặt vật: Chậu cây xanh lớn ở bên trái bàn làm việc đặt vững trên mặt sàn, không phải treo thả từ trần nhà.\n- (B) Sai trạng thái sắp xếp: Ghế bàn làm việc và các ghế sofa/ghế bành ở sảnh đều đặt ngay ngắn trên sàn, không hề bị xếp chồng trước cửa kính ra vào bên phải.\n- (D) Sai trạng thái đồ vật: Tấm thảm họa tiết trải phẳng kín mặt sàn sảnh, không bị cuộn lại dựng sát tường.","lines":[{"speaker":"(A)","en":"Potted plants have been suspended from a ceiling.","vi":"Những chậu cây được treo thả từ trần nhà.","units":[{"en":"Potted plants have been suspended from a ceiling.","vi":"Những chậu cây được treo thả từ trần nhà."}]},{"speaker":"(B)","en":"Chairs have been stacked in front of an entryway.","vi":"Những chiếc ghế đã được xếp chồng lên nhau trước lối vào.","units":[{"en":"Chairs have been stacked in front of an entryway.","vi":"Những chiếc ghế đã được xếp chồng lên nhau trước lối vào."}]},{"speaker":"(C)","en":"A computer station has been set up on a desk.","vi":"Một bộ máy tính làm việc đã được lắp đặt trên bàn.","units":[{"en":"A computer station has been set up on a desk.","vi":"Một bộ máy tính làm việc đã được lắp đặt trên bàn."}]},{"speaker":"(D)","en":"A rug has been rolled up against a wall.","vi":"Một tấm thảm đã được cuộn lại dựng sát tường.","units":[{"en":"A rug has been rolled up against a wall.","vi":"Một tấm thảm đã được cuộn lại dựng sát tường."}]}],"vocab":[{"word":"suspend","pos":"v","ipa":"/səˈspend/","meaning":"treo lơ lửng, treo thả"},{"word":"stack","pos":"v","ipa":"/stæk/","meaning":"xếp chồng lên nhau"},{"word":"entryway","pos":"n","ipa":"/ˈentriweɪ/","meaning":"lối vào"},{"word":"roll up","pos":"phr. v","ipa":"/roʊl ˈʌp/","meaning":"cuộn tròn lại"}],"isScanBacked":false,"grammarType":"Part 1 — Tranh tả vật & Cảnh quan (Bị động trạng thái / Hiện hữu)","formula":"CÔNG THỨC PART 1 (PART 1 THUỘC LÒNG — Bị động hoàn thành): Chú ý cấu trúc 'has/have been + V3' tả kết quả sắp đặt trong sảnh/văn phòng; đối chiếu từng danh từ vị trí ('on a desk' vs 'from a ceiling', 'against a wall').","optionAnalysis":{"A":"Sai giới từ và vị trí: chậu cây xanh đặt trực tiếp trên sàn bên trái bàn, không hề được treo từ trần nhà.","B":"Sai trạng thái đồ vật: các ghế đều đặt bình thường trên sàn sảnh, không bị xếp chồng chắn trước lối ra vào.","C":"Đúng với tiền cảnh bức ảnh: trạm máy tính gồm màn hình, bàn phím, chuột và máy in đã được lắp trên bàn gỗ.","D":"Trái với mặt sàn trong ảnh: tấm thảm họa tiết đang trải phẳng toàn bộ sảnh, không bị cuộn sát tường."},"evDocIdx":0,"evTargets":[{"badge":"Câu 5 · Đáp án C","opt":"C","isCorrect":true,"quote":"A computer station has been set up on a desk.","viQuote":"Một bộ máy tính làm việc đã được lắp đặt trên bàn."}],"evQuotes":["A computer station has been set up on a desk."]},{"q":6,"part":1,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_06.mp3","photo":"web_assets/ets2025/p1/E25_T01_Q06.webp","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_01.webp"],"stem_en":"Look at the picture marked number 6 in your test book.","stem_vi":"Hãy nhìn vào bức tranh số 6 trong sách đề thi của bạn.","options":{"A":{"en":"One of the men is sweeping a patio.","vi":"Một trong những người đàn ông đang quét sân hiên."},"B":{"en":"One of the men is replacing some flooring.","vi":"Một trong những người đàn ông đang thay một phần sàn nhà."},"C":{"en":"A door has been taken off its frame.","vi":"Một cánh cửa đã được tháo rời khỏi khung."},"D":{"en":"A light fixture has been left on the ground.","vi":"Một bộ đèn chiếu sáng được để trên mặt đất."}},"ans":"C","explanation":"Đáp án đúng: (C) Một cánh cửa đã được tháo rời khỏi khung — khớp với khung cửa trống ở bên phải căn phòng đang sửa chữa và cánh cửa màu trắng (còn tay nắm) bị tháo rời dựng tựa vào tường.\nDẫn chứng: Bên phải căn phòng đang cải tạo có một ô cửa trống không cánh, còn cánh cửa màu trắng đứng tách rời tựa sát tường; phía trái có người thợ giơ hai tay giữ bộ đèn trần trên cao và phía sau có người thứ hai đang quét sàn nhà.\nPhân tích bẫy:\n- (A) Sai danh từ địa điểm: Người thợ ở phía sau đang quét mặt sàn phẳng bên trong căn phòng kín có tường sơn tối và len chân tường trắng, không phải sân hiên ngoài trời (patio).\n- (B) Sai hành động chuyên môn: Không có ai đang lắp hay thay ván sàn; một người quét sàn bằng chổi đẩy và người kia giữ đèn ốp trần.\n- (D) Sai vị trí vật thể: Bộ đèn chiếu sáng hình tròn đang được người đàn ông phía trước giơ cả hai tay đỡ áp sát lên trần nhà, không nằm trên mặt đất.","lines":[{"speaker":"(A)","en":"One of the men is sweeping a patio.","vi":"Một trong những người đàn ông đang quét sân hiên.","units":[{"en":"One of the men is sweeping a patio.","vi":"Một trong những người đàn ông đang quét sân hiên."}]},{"speaker":"(B)","en":"One of the men is replacing some flooring.","vi":"Một trong những người đàn ông đang thay một phần sàn nhà.","units":[{"en":"One of the men is replacing some flooring.","vi":"Một trong những người đàn ông đang thay một phần sàn nhà."}]},{"speaker":"(C)","en":"A door has been taken off its frame.","vi":"Một cánh cửa đã được tháo rời khỏi khung.","units":[{"en":"A door has been taken off its frame.","vi":"Một cánh cửa đã được tháo rời khỏi khung."}]},{"speaker":"(D)","en":"A light fixture has been left on the ground.","vi":"Một bộ đèn chiếu sáng được để trên mặt đất.","units":[{"en":"A light fixture has been left on the ground.","vi":"Một bộ đèn chiếu sáng được để trên mặt đất."}]}],"vocab":[{"word":"patio","pos":"n","ipa":"/ˈpætioʊ/","meaning":"sân hiên ngoài trời"},{"word":"flooring","pos":"n","ipa":"/ˈflɔːrɪŋ/","meaning":"vật liệu lát sàn, sàn nhà"},{"word":"frame","pos":"n","ipa":"/freɪm/","meaning":"khung (cửa)"},{"word":"light fixture","pos":"n","ipa":"/laɪt ˈfɪkstʃər/","meaning":"bộ đèn chiếu sáng cố định"}],"isScanBacked":false,"grammarType":"Part 1 — Tranh tả nhiều người (Hành động & Bối cảnh chung)","formula":"CÔNG THỨC PART 1 (khảo bài part 1 — Tranh hỗn hợp người & vật): Khi tranh có người làm việc nhưng đáp án đúng lại tả vật ở dạng bị động hoàn thành ('has been taken off'), hãy quét kỹ phông nền/khung cửa để không bỏ sót chi tiết tĩnh.","optionAnalysis":{"A":"Sai bối cảnh trong nhà/ngoài trời: người thợ phía sau đang quét sàn phòng kín trong nhà, không phải sân hiên (patio).","B":"Sai công việc đang làm: hai người thợ đang quét sàn và đỡ đèn trần, không ai thao tác thay vật liệu sàn nhà.","C":"Đúng với góc phải bức ảnh: cánh cửa trắng đã được tháo khỏi khung cửa trống và dựng tựa vào bức tường.","D":"Sai vị trí thiết bị: bộ đèn tròn đang được người thợ giơ tay giữ sát lên trần nhà chứ không để trên mặt đất."},"evDocIdx":0,"evTargets":[{"badge":"Câu 6 · Đáp án C","opt":"C","isCorrect":true,"quote":"A door has been taken off its frame.","viQuote":"Một cánh cửa đã được tháo rời khỏi khung."}],"evQuotes":["A door has been taken off its frame."]},{"q":7,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_07.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_02.webp"],"stem_en":"How old is this building?","stem_vi":"Tòa nhà này đã bao nhiêu năm tuổi rồi?","options":{"A":{"en":"To ship some materials.","vi":"Để vận chuyển một số vật liệu."},"B":{"en":"About ten years old.","vi":"Khoảng mười năm tuổi rồi."},"C":{"en":"Company offices, I think.","vi":"Tôi nghĩ là các văn phòng công ty."}},"ans":"B","explanation":"Đáp án đúng: (B) Khoảng mười năm tuổi rồi — trả lời trực tiếp cho câu hỏi về tuổi đời của tòa nhà ('How old').\nDẫn chứng: \"How old is this building?\" — \"About ten years old.\" (Tòa nhà này bao nhiêu năm tuổi? — Khoảng mười năm tuổi rồi).\nPhân tích bẫy:\n- (A) Sai dạng câu hỏi: Cụm mục đích 'To ship some materials' chỉ trả lời cho câu hỏi 'Why' hoặc 'What for', không khớp 'How old'.\n- (C) Lạc trọng tâm câu hỏi: 'Company offices' nêu chức năng sử dụng của tòa nhà (hợp với 'What is this building used for?'), không cho biết số tuổi.","lines":[{"speaker":"Q","en":"How old is this building?","vi":"Tòa nhà này đã bao nhiêu năm tuổi rồi?","units":[{"en":"How old is this building?","vi":"Tòa nhà này đã bao nhiêu năm tuổi rồi?"}]},{"speaker":"(A)","en":"To ship some materials.","vi":"Để vận chuyển một số vật liệu.","units":[{"en":"To ship some materials.","vi":"Để vận chuyển một số vật liệu."}]},{"speaker":"(B)","en":"About ten years old.","vi":"Khoảng mười năm tuổi rồi.","units":[{"en":"About ten years old.","vi":"Khoảng mười năm tuổi rồi."}]},{"speaker":"(C)","en":"Company offices, I think.","vi":"Tôi nghĩ là các văn phòng công ty.","units":[{"en":"Company offices, I think.","vi":"Tôi nghĩ là các văn phòng công ty."}]}],"vocab":[{"word":"building","pos":"n","ipa":"/ˈbɪldɪŋ/","meaning":"tòa nhà"},{"word":"ship","pos":"v","ipa":"/ʃɪp/","meaning":"vận chuyển, giao hàng"},{"word":"material","pos":"n","ipa":"/məˈtɪriəl/","meaning":"vật liệu, nguyên liệu"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi How (Cách thức / Số lượng / Đánh giá)","formula":"CÔNG THỨC PART 2 (PART 2 THUỘC LÒNG — Câu hỏi How old): Nghe cụm từ để hỏi 'How old' -> Chốt đáp án nêu số năm tuổi hoặc mốc năm xây dựng ('About ten years old'); loại câu trả lời mục đích (To V) và danh từ chỉ nơi chốn.","optionAnalysis":{"A":"Sai loại câu hỏi: trả lời mục đích bằng 'To V' (dùng cho Why/What for) thay vì cung cấp số năm tuổi.","B":"Đáp án chính xác: cung cấp trực tiếp tuổi đời của tòa nhà là khoảng mười năm ('About ten years old').","C":"Lạc nội dung hỏi: nhắc đến văn phòng công ty (mục đích sử dụng tòa nhà) thay vì trả lời câu hỏi 'How old'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 7 · Câu hỏi","opt":"B","isCorrect":false,"quote":"How old is this building?","viQuote":"Tòa nhà này đã bao nhiêu năm tuổi rồi?"},{"badge":"Câu 7 · Đáp án B","opt":"B","isCorrect":true,"quote":"About ten years old.","viQuote":"Khoảng mười năm tuổi rồi."}],"evQuotes":["How old is this building?","About ten years old."]},{"q":8,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_08.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_02.webp"],"stem_en":"Can you come to my jazz performance tonight?","stem_vi":"Tối nay bạn có thể đến xem buổi biểu diễn nhạc jazz của tôi không?","options":{"A":{"en":"I'm sorry I was late for the meeting.","vi":"Tôi xin lỗi vì đã đến họp muộn."},"B":{"en":"Mostly just local musicians.","vi":"Chủ yếu chỉ có các nhạc công địa phương thôi."},"C":{"en":"Sure, I'll be there!","vi":"Chắc chắn rồi, tôi sẽ đến!"}},"ans":"C","explanation":"Đáp án đúng: (C) Chắc chắn rồi, tôi sẽ đến! — phản hồi nhận lời trực tiếp và tự nhiên cho lời mời tham dự buổi biểu diễn nhạc jazz tối nay.\nDẫn chứng: \"Can you come to my jazz performance tonight?\" — \"Sure, I'll be there!\" (Tối nay bạn đến xem buổi diễn nhạc jazz của tôi được không? — Chắc chắn rồi, tôi sẽ tới!).\nPhân tích bẫy:\n- (A) Sai thì và ngữ cảnh: Dùng quá khứ 'I was late for the meeting' để xin lỗi một cuộc họp đã qua, không liên quan đến lời mời tối nay.\n- (B) Sai từ để hỏi: 'Mostly just local musicians' trả lời cho câu hỏi 'Who' (ai biểu diễn), không đáp lại lời mời 'Can you come to my jazz performance tonight?'.","lines":[{"speaker":"Q","en":"Can you come to my jazz performance tonight?","vi":"Tối nay bạn có thể đến xem buổi biểu diễn nhạc jazz của tôi không?","units":[{"en":"Can you come to my jazz performance tonight?","vi":"Tối nay bạn có thể đến xem buổi biểu diễn nhạc jazz của tôi không?"}]},{"speaker":"(A)","en":"I'm sorry I was late for the meeting.","vi":"Tôi xin lỗi vì đã đến họp muộn.","units":[{"en":"I'm sorry I was late for the meeting.","vi":"Tôi xin lỗi vì đã đến họp muộn."}]},{"speaker":"(B)","en":"Mostly just local musicians.","vi":"Chủ yếu chỉ có các nhạc công địa phương thôi.","units":[{"en":"Mostly just local musicians.","vi":"Chủ yếu chỉ có các nhạc công địa phương thôi."}]},{"speaker":"(C)","en":"Sure, I'll be there!","vi":"Chắc chắn rồi, tôi sẽ đến!","units":[{"en":"Sure, I'll be there!","vi":"Chắc chắn rồi, tôi sẽ đến!"}]}],"vocab":[{"word":"performance","pos":"n","ipa":"/pərˈfɔːrməns/","meaning":"buổi biểu diễn"},{"word":"local","pos":"adj","ipa":"/ˈloʊkəl/","meaning":"thuộc địa phương"},{"word":"musician","pos":"n","ipa":"/mjuˈzɪʃən/","meaning":"nhạc công, nhạc sĩ"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi Yes/No & Đáp án gián tiếp","formula":"CÔNG THỨC PART 2 (khảo bài part 2 — Lời mời Can you come to [event]?): Với câu mời 'Can you come to [sự kiện]?', đáp án đúng thường nhận lời tự nhiên ('Sure, I'll be there!') hoặc từ chối kèm lý do; loại câu sai thì quá khứ và câu trả lời cho 'Who'.","optionAnalysis":{"A":"Sai thì và bối cảnh: xin lỗi vì đến họp muộn trong quá khứ, không trả lời lời mời đi xem nhạc tối nay.","B":"Sai dạng câu hỏi: trả lời đối tượng tham gia (giống câu hỏi Who) thay vì xác nhận có đến dự hay không.","C":"Đáp án chuẩn xác: xác nhận nhận lời tham dự buổi biểu diễn một cách tự nhiên bằng thì tương lai."},"evDocIdx":0,"evTargets":[{"badge":"Câu 8 · Câu hỏi","opt":"C","isCorrect":false,"quote":"Can you come to my jazz performance tonight?","viQuote":"Tối nay bạn có thể đến xem buổi biểu diễn nhạc jazz của tôi không?"},{"badge":"Câu 8 · Đáp án C","opt":"C","isCorrect":true,"quote":"Sure, I'll be there!","viQuote":"Chắc chắn rồi, tôi sẽ đến!"}],"evQuotes":["Can you come to my jazz performance tonight?","Sure, I'll be there!"]},{"q":9,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_09.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_02.webp"],"stem_en":"Which apartment submitted a work order?","stem_vi":"Căn hộ nào đã gửi phiếu yêu cầu sửa chữa vậy?","options":{"A":{"en":"It's what you did for a living.","vi":"Đó là công việc kiếm sống của bạn mà."},"B":{"en":"Submit your assignment here.","vi":"Hãy nộp bài tập của bạn ở đây."},"C":{"en":"It came from the tenants in B23.","vi":"Yêu cầu đó do người thuê ở căn B23 gửi lên."}},"ans":"C","explanation":"Đáp án đúng: (C) Yêu cầu đó do người thuê ở căn B23 gửi lên — chỉ rõ mã căn hộ 'B23' tương ứng với câu hỏi 'Which apartment'.\nDẫn chứng: \"Which apartment submitted a work order?\" — \"It came from the tenants in B23.\" ('It' thay cho 'a work order', 'tenants in B23' xác định chính xác căn hộ nào).\nPhân tích bẫy:\n- (A) Bẫy tách từ 'work': Hiểu nhầm 'work order' (phiếu yêu cầu sửa chữa) sang 'for a living' (nghề nghiệp kiếm sống), lạc nghĩa hoàn toàn.\n- (B) Bẫy lặp từ 'submit': Lặp lại động từ 'Submit' từ câu hỏi nhưng đổi ngữ cảnh sang nộp bài tập ('assignment').","lines":[{"speaker":"Q","en":"Which apartment submitted a work order?","vi":"Căn hộ nào đã gửi phiếu yêu cầu sửa chữa vậy?","units":[{"en":"Which apartment submitted a work order?","vi":"Căn hộ nào đã gửi phiếu yêu cầu sửa chữa vậy?"}]},{"speaker":"(A)","en":"It's what you did for a living.","vi":"Đó là công việc kiếm sống của bạn mà.","units":[{"en":"It's what you did for a living.","vi":"Đó là công việc kiếm sống của bạn mà."}]},{"speaker":"(B)","en":"Submit your assignment here.","vi":"Hãy nộp bài tập của bạn ở đây.","units":[{"en":"Submit your assignment here.","vi":"Hãy nộp bài tập của bạn ở đây."}]},{"speaker":"(C)","en":"It came from the tenants in B23.","vi":"Yêu cầu đó do người thuê ở căn B23 gửi lên.","units":[{"en":"It came from the tenants in B23.","vi":"Yêu cầu đó do người thuê ở căn B23 gửi lên."}]}],"vocab":[{"word":"submit","pos":"v","ipa":"/səbˈmɪt/","meaning":"nộp, gửi lên"},{"word":"work order","pos":"n","ipa":"/wɜːrk ˈɔːrdər/","meaning":"phiếu yêu cầu sửa chữa, bảo trì"},{"word":"tenant","pos":"n","ipa":"/ˈtenənt/","meaning":"người thuê nhà, người thuê căn hộ"},{"word":"assignment","pos":"n","ipa":"/əˈsaɪnmənt/","meaning":"bài tập, nhiệm vụ được giao"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi What / Which (Hỏi thông tin & Lựa chọn cụ thể)","formula":"CÔNG THỨC PART 2 (PART 2 THUỘC LÒNG — Câu hỏi Which): Nghe 'Which apartment + V?' -> Chọn đáp án chỉ rõ số/mã căn hộ hoặc đối tượng tương ứng ('tenants in B23'); cảnh giác bẫy lặp từ 'submit' và biến đổi nghĩa từ 'work'.","optionAnalysis":{"A":"Bẫy chuyển nghĩa từ 'work': nói về công việc kiếm sống thay vì xác định căn hộ đã gửi phiếu sửa chữa.","B":"Bẫy lặp từ 'submit': nhắc lại 'Submit' nhưng chuyển sang yêu cầu nộp bài tập, sai hoàn toàn ngữ cảnh.","C":"Đáp án đúng: dùng mã căn hộ 'B23' và chủ thể 'tenants' để trả lời trực tiếp câu hỏi 'Which apartment'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 9 · Câu hỏi","opt":"C","isCorrect":false,"quote":"Which apartment submitted a work order?","viQuote":"Căn hộ nào đã gửi phiếu yêu cầu sửa chữa vậy?"},{"badge":"Câu 9 · Đáp án C","opt":"C","isCorrect":true,"quote":"It came from the tenants in B23.","viQuote":"Yêu cầu đó do người thuê ở căn B23 gửi lên."}],"evQuotes":["Which apartment submitted a work order?","It came from the tenants in B23."]},{"q":10,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_10.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_02.webp"],"stem_en":"Will you contact the vendor about changing our delivery date?","stem_vi":"Bạn có thể liên hệ với nhà cung cấp về việc thay đổi ngày giao hàng của chúng ta không?","options":{"A":{"en":"Of course, I'll take care of it.","vi":"Tất nhiên rồi, tôi sẽ lo việc này."},"B":{"en":"An e-mail receipt.","vi":"Một biên lai qua email."},"C":{"en":"Could I get change for a dollar?","vi":"Bạn có thể đổi giúp tôi tờ một đô la sang tiền lẻ không?"}},"ans":"A","explanation":"Đáp án đúng: (A) Tất nhiên rồi, tôi sẽ lo việc này — nhận lời thực hiện yêu cầu liên hệ nhà cung cấp để đổi ngày giao hàng.\nDẫn chứng: \"Will you contact the vendor about changing our delivery date?\" — \"Of course, I'll take care of it.\" ('it' quy chiếu hành động liên hệ nhà cung cấp).\nPhân tích bẫy:\n- (B) Sai loại câu hỏi: Đưa ra danh từ chỉ vật ('biên lai qua email') như trả lời cho câu hỏi 'What', không phản hồi lời nhờ vả.\n- (C) Bẫy lặp từ đa nghĩa 'change': Câu hỏi dùng 'changing' nghĩa là 'thay đổi (ngày giao)', còn đáp án (C) dùng 'change' nghĩa là 'tiền lẻ'.","lines":[{"speaker":"Q","en":"Will you contact the vendor about changing our delivery date?","vi":"Bạn có thể liên hệ với nhà cung cấp về việc thay đổi ngày giao hàng của chúng ta không?","units":[{"en":"Will you contact the vendor about changing our delivery date?","vi":"Bạn có thể liên hệ với nhà cung cấp về việc thay đổi ngày giao hàng của chúng ta không?"}]},{"speaker":"(A)","en":"Of course, I'll take care of it.","vi":"Tất nhiên rồi, tôi sẽ lo việc này.","units":[{"en":"Of course, I'll take care of it.","vi":"Tất nhiên rồi, tôi sẽ lo việc này."}]},{"speaker":"(B)","en":"An e-mail receipt.","vi":"Một biên lai qua email.","units":[{"en":"An e-mail receipt.","vi":"Một biên lai qua email."}]},{"speaker":"(C)","en":"Could I get change for a dollar?","vi":"Bạn có thể đổi giúp tôi tờ một đô la sang tiền lẻ không?","units":[{"en":"Could I get change for a dollar?","vi":"Bạn có thể đổi giúp tôi tờ một đô la sang tiền lẻ không?"}]}],"vocab":[{"word":"vendor","pos":"n","ipa":"/ˈvendər/","meaning":"nhà cung cấp, bên bán"},{"word":"delivery date","pos":"n","ipa":"/dɪˈlɪvəri deɪt/","meaning":"ngày giao hàng"},{"word":"take care of","pos":"phr. v","ipa":"/teɪk ker ʌv/","meaning":"phụ trách, lo liệu"},{"word":"receipt","pos":"n","ipa":"/rɪˈsiːt/","meaning":"biên lai, hóa đơn"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi yêu cầu & Xin phép (Request / Permission)","formula":"CÔNG THỨC PART 2 (khảo bài part 2 — Câu nhờ vả Will you + V?): Khi nghe 'Will you + V [tân ngữ]?', đáp án đúng thường nhận lời phụ trách ('Of course, I'll take care of it'); loại đáp án lặp từ đa nghĩa ('change').","optionAnalysis":{"A":"Đáp án đúng: phản hồi tự nhiên nhận lời thực hiện yêu cầu ('I'll take care of it') cho câu nhờ 'Will you contact the vendor?'.","B":"Sai dạng câu hỏi: chỉ nêu một cụm danh từ ('biên lai email'), không đáp lại lời đề nghị hành động.","C":"Bẫy từ đa nghĩa 'change': chuyển từ 'thay đổi ngày giao hàng' sang hỏi đổi tiền lẻ, sai hoàn toàn ý."},"evDocIdx":0,"evTargets":[{"badge":"Câu 10 · Câu hỏi","opt":"A","isCorrect":false,"quote":"Will you contact the vendor about changing our delivery date?","viQuote":"Bạn có thể liên hệ với nhà cung cấp về việc thay đổi ngày giao hàng của chúng ta không?"},{"badge":"Câu 10 · Đáp án A","opt":"A","isCorrect":true,"quote":"Of course, I'll take care of it.","viQuote":"Tất nhiên rồi, tôi sẽ lo việc này."}],"evQuotes":["Will you contact the vendor about changing our delivery date?","Of course, I'll take care of it."]},{"q":11,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_11.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_02.webp"],"stem_en":"Why was the maintenance worker here?","stem_vi":"Tại sao nhân viên bảo trì lại đến đây vậy?","options":{"A":{"en":"No, he didn't.","vi":"Không, anh ấy đã không làm thế."},"B":{"en":"From three o'clock until four.","vi":"Từ ba giờ đến bốn giờ."},"C":{"en":"Because a light needed to be fixed.","vi":"Vì có một chiếc đèn cần được sửa."}},"ans":"C","explanation":"Đáp án đúng: (C) Vì có một chiếc đèn cần được sửa — đưa ra nguyên nhân trực tiếp bằng 'Because' giải thích lý do nhân viên bảo trì có mặt.\nDẫn chứng: \"Why was the maintenance worker here?\" — \"Because a light needed to be fixed.\" (Sao nhân viên bảo trì lại tới đây? — Vì có một chiếc đèn cần sửa).\nPhân tích bẫy:\n- (A) Bẫy Yes/No cho câu hỏi Wh-: Câu hỏi bắt đầu bằng 'Why' không bao giờ trả lời bằng 'No, he didn't'.\n- (B) Sai từ để hỏi: 'From three o'clock until four' trả lời cho 'When' hoặc 'How long' (khung giờ), không trả lời lý do 'Why'.","lines":[{"speaker":"Q","en":"Why was the maintenance worker here?","vi":"Tại sao nhân viên bảo trì lại đến đây vậy?","units":[{"en":"Why was the maintenance worker here?","vi":"Tại sao nhân viên bảo trì lại đến đây vậy?"}]},{"speaker":"(A)","en":"No, he didn't.","vi":"Không, anh ấy đã không làm thế.","units":[{"en":"No, he didn't.","vi":"Không, anh ấy đã không làm thế."}]},{"speaker":"(B)","en":"From three o'clock until four.","vi":"Từ ba giờ đến bốn giờ.","units":[{"en":"From three o'clock until four.","vi":"Từ ba giờ đến bốn giờ."}]},{"speaker":"(C)","en":"Because a light needed to be fixed.","vi":"Vì có một chiếc đèn cần được sửa.","units":[{"en":"Because a light needed to be fixed.","vi":"Vì có một chiếc đèn cần được sửa."}]}],"vocab":[{"word":"maintenance","pos":"n","ipa":"/ˈmeɪntənəns/","meaning":"việc bảo trì, bảo dưỡng"},{"word":"fix","pos":"v","ipa":"/fɪks/","meaning":"sửa chữa"},{"word":"until","pos":"prep","ipa":"/ənˈtɪl/","meaning":"cho đến khi"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi Why (Hỏi nguyên nhân & Mục đích)","formula":"CÔNG THỨC PART 2 (PART 2 THUỘC LÒNG — Câu hỏi Why): Nghe từ để hỏi 'Why' -> Chọn lý do có 'Because / To V' hoặc lý do gián tiếp; loại ngay đáp án 'Yes/No' và cụm chỉ thời lượng ('From X until Y').","optionAnalysis":{"A":"Bẫy Yes/No kinh điển: dùng 'No, he didn't' để trả lời câu hỏi có từ để hỏi 'Why' nên bị loại ngay.","B":"Sai loại thông tin hỏi: đưa ra khung thời gian từ 3 đến 4 giờ (hợp với When/How long) thay vì nguyên nhân.","C":"Đáp án chuẩn: bắt đầu bằng 'Because' nêu đúng mục đích công việc sửa đèn của nhân viên bảo trì."},"evDocIdx":0,"evTargets":[{"badge":"Câu 11 · Câu hỏi","opt":"C","isCorrect":false,"quote":"Why was the maintenance worker here?","viQuote":"Tại sao nhân viên bảo trì lại đến đây vậy?"},{"badge":"Câu 11 · Đáp án C","opt":"C","isCorrect":true,"quote":"Because a light needed to be fixed.","viQuote":"Vì có một chiếc đèn cần được sửa."}],"evQuotes":["Why was the maintenance worker here?","Because a light needed to be fixed."]},{"q":12,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_12.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_03.webp"],"stem_en":"Did management make a hiring decision yet?","stem_vi":"Ban quản lý đã đưa ra quyết định tuyển dụng chưa?","options":{"A":{"en":"Put it on the highest shelf.","vi":"Hãy đặt nó lên kệ cao nhất."},"B":{"en":"The personnel department.","vi":"Phòng nhân sự."},"C":{"en":"Yes, they chose Jacob Borgman.","vi":"Rồi, họ đã chọn Jacob Borgman."}},"ans":"C","explanation":"Đáp án đúng: (C) Rồi, họ đã chọn Jacob Borgman — trả lời 'Yes' và nêu đích danh ứng viên được ban quản lý ('they') chọn.\nDẫn chứng: \"Did management make a hiring decision yet?\" — \"Yes, they chose Jacob Borgman.\" ('management' là danh từ tập hợp quy chiếu thành 'they'; 'chose' đồng nghĩa việc đã chốt quyết định tuyển dụng).\nPhân tích bẫy:\n- (A) Bẫy gần âm: Cặp từ 'hiring' /ˈhaɪərɪŋ/ và 'highest' /ˈhaɪɪst/ phát âm na ná nhau kèm câu mệnh lệnh đặt đồ lên kệ không liên quan.\n- (B) Sai dạng câu hỏi: Đưa ra tên phòng ban ('Phòng nhân sự') như trả lời câu hỏi 'Who / Which department', không trả lời câu hỏi Yes/No 'Did management make a decision yet?'.","lines":[{"speaker":"Q","en":"Did management make a hiring decision yet?","vi":"Ban quản lý đã đưa ra quyết định tuyển dụng chưa?","units":[{"en":"Did management make a hiring decision yet?","vi":"Ban quản lý đã đưa ra quyết định tuyển dụng chưa?"}]},{"speaker":"(A)","en":"Put it on the highest shelf.","vi":"Hãy đặt nó lên kệ cao nhất.","units":[{"en":"Put it on the highest shelf.","vi":"Hãy đặt nó lên kệ cao nhất."}]},{"speaker":"(B)","en":"The personnel department.","vi":"Phòng nhân sự.","units":[{"en":"The personnel department.","vi":"Phòng nhân sự."}]},{"speaker":"(C)","en":"Yes, they chose Jacob Borgman.","vi":"Rồi, họ đã chọn Jacob Borgman.","units":[{"en":"Yes, they chose Jacob Borgman.","vi":"Rồi, họ đã chọn Jacob Borgman."}]}],"vocab":[{"word":"management","pos":"n","ipa":"/ˈmænɪdʒmənt/","meaning":"ban quản lý"},{"word":"hiring","pos":"n","ipa":"/ˈhaɪərɪŋ/","meaning":"việc tuyển dụng"},{"word":"personnel department","pos":"n","ipa":"/ˌpɜːrsəˈnel dɪˈpɑːrtmənt/","meaning":"phòng nhân sự"},{"word":"shelf","pos":"n","ipa":"/ʃelf/","meaning":"kệ, giá đỡ"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi Yes/No & Đáp án gián tiếp","formula":"CÔNG THỨC PART 2 (khảo bài part 2 — Câu hỏi Did + S + V yet?): Với câu hỏi xác nhận kết quả ở quá khứ, chú ý quy chiếu chủ ngữ số nhiều ('management' -> 'they') và bẫy phát âm gần âm ('hiring' vs 'highest').","optionAnalysis":{"A":"Bẫy đồng âm gần âm: dùng 'highest' gần âm với 'hiring' nhưng nội dung đặt đồ lên kệ không liên quan.","B":"Sai loại câu hỏi: nêu tên phòng nhân sự (trả lời Who/Which) thay vì xác nhận đã có quyết định tuyển dụng chưa.","C":"Đáp án chính xác: xác nhận 'Yes' và nêu tên người được chọn (Jacob Borgman), khớp với 'make a hiring decision'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 12 · Câu hỏi","opt":"C","isCorrect":false,"quote":"Did management make a hiring decision yet?","viQuote":"Ban quản lý đã đưa ra quyết định tuyển dụng chưa?"},{"badge":"Câu 12 · Đáp án C","opt":"C","isCorrect":true,"quote":"Yes, they chose Jacob Borgman.","viQuote":"Rồi, họ đã chọn Jacob Borgman."}],"evQuotes":["Did management make a hiring decision yet?","Yes, they chose Jacob Borgman."]},{"q":13,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_13.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_03.webp"],"stem_en":"Do you want to eat here in our cafeteria or go out?","stem_vi":"Bạn muốn ăn ngay tại căng-tin của chúng ta hay đi ăn ngoài?","options":{"A":{"en":"He went there yesterday.","vi":"Anh ấy đã đến đó hôm qua rồi."},"B":{"en":"Well, maybe a sandwich.","vi":"Chắc là một chiếc bánh mì kẹp."},"C":{"en":"Let's eat here.","vi":"Chúng ta ăn ở đây đi."}},"ans":"C","explanation":"Đáp án đúng: (C) Chúng ta ăn ở đây đi — chọn trực tiếp phương án thứ nhất ('eat here') trong hai lựa chọn ăn tại căng-tin hay ra ngoài.\nDẫn chứng: \"Do you want to eat here in our cafeteria or go out?\" — \"Let's eat here.\" (Bạn muốn ăn ở căng-tin hay ra ngoài? — Ăn ở đây đi).\nPhân tích bẫy:\n- (A) Sai chủ ngữ và thì: Câu hỏi hỏi 'you' ở hiện tại/tương lai, nhưng đáp án (A) chuyển sang 'He' và dùng quá khứ 'yesterday'.\n- (B) Lạc trọng tâm lựa chọn: 'Maybe a sandwich' trả lời cho câu hỏi ăn món gì ('What do you want to eat?'), không chọn địa điểm ăn ở đâu.","lines":[{"speaker":"Q","en":"Do you want to eat here in our cafeteria or go out?","vi":"Bạn muốn ăn ngay tại căng-tin của chúng ta hay đi ăn ngoài?","units":[{"en":"Do you want to eat here in our cafeteria or go out?","vi":"Bạn muốn ăn ngay tại căng-tin của chúng ta hay đi ăn ngoài?"}]},{"speaker":"(A)","en":"He went there yesterday.","vi":"Anh ấy đã đến đó hôm qua rồi.","units":[{"en":"He went there yesterday.","vi":"Anh ấy đã đến đó hôm qua rồi."}]},{"speaker":"(B)","en":"Well, maybe a sandwich.","vi":"Chắc là một chiếc bánh mì kẹp.","units":[{"en":"Well, maybe a sandwich.","vi":"Chắc là một chiếc bánh mì kẹp."}]},{"speaker":"(C)","en":"Let's eat here.","vi":"Chúng ta ăn ở đây đi.","units":[{"en":"Let's eat here.","vi":"Chúng ta ăn ở đây đi."}]}],"vocab":[{"word":"cafeteria","pos":"n","ipa":"/ˌkæfəˈtɪriə/","meaning":"căng-tin, nhà ăn tự phục vụ"},{"word":"go out","pos":"phr. v","ipa":"/ɡoʊ ˈaʊt/","meaning":"ra ngoài (ăn uống)"},{"word":"sandwich","pos":"n","ipa":"/ˈsænwɪtʃ/","meaning":"bánh mì kẹp"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi lựa chọn A or B (Choice Question)","formula":"CÔNG THỨC PART 2 (PART 2 THUỘC LÒNG — Câu hỏi lựa chọn A or B): Khi nghe 'Do you want A or B?', chốt đáp án chọn một trong hai phương án (nhắc lại 'here') hoặc chọn phương án thứ ba; loại câu sai chủ ngữ/thì và câu hỏi món ăn.","optionAnalysis":{"A":"Sai chủ ngữ và mốc thời gian: dùng 'He' và quá khứ 'yesterday' không khớp với lời rủ dành cho 'you'.","B":"Lạc trọng tâm câu hỏi: nêu tên món ăn (bánh mì kẹp) thay vì chọn ăn tại căng-tin hay đi ăn ngoài.","C":"Đáp án trực tiếp: chọn rõ ràng phương án 'eat here' từ hai lựa chọn đưa ra trong câu hỏi."},"evDocIdx":0,"evTargets":[{"badge":"Câu 13 · Câu hỏi","opt":"C","isCorrect":false,"quote":"Do you want to eat here in our cafeteria or go out?","viQuote":"Bạn muốn ăn ngay tại căng-tin của chúng ta hay đi ăn ngoài?"},{"badge":"Câu 13 · Đáp án C","opt":"C","isCorrect":true,"quote":"Let's eat here.","viQuote":"Chúng ta ăn ở đây đi."}],"evQuotes":["Do you want to eat here in our cafeteria or go out?","Let's eat here."]},{"q":14,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_14.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_03.webp"],"stem_en":"Didn't you e-mail the employment contract to Mr. Patel yesterday?","stem_vi":"Hôm qua bạn chưa gửi hợp đồng lao động qua email cho ông Patel à?","options":{"A":{"en":"Yes, I would agree.","vi":"Đúng vậy, tôi đồng ý."},"B":{"en":"No, I'll send it now.","vi":"Chưa, tôi sẽ gửi ngay bây giờ."},"C":{"en":"Check the employee manual.","vi":"Hãy xem sổ tay nhân viên."}},"ans":"B","explanation":"Đáp án đúng: (B) Chưa, tôi sẽ gửi ngay bây giờ — xác nhận chưa gửi hợp đồng hôm qua và đưa ra hành động khắc phục ngay lập tức.\nDẫn chứng: \"Didn't you e-mail the employment contract to Mr. Patel yesterday?\" — \"No, I'll send it now.\" ('it' thay cho 'the employment contract'; 'send' paraphrase cho 'e-mail').\nPhân tích bẫy:\n- (A) Lạc ngữ cảnh phản hồi: 'Yes, I would agree' dùng để đồng tình với một quan điểm/đánh giá, không dùng để xác nhận đã gửi email hay chưa.\n- (C) Bẫy biến thể từ cùng gốc: Dùng 'employee' để gài bẫy từ 'employment' trong câu hỏi nhưng nội dung bảo xem sổ tay không giải đáp việc gửi hợp đồng.","lines":[{"speaker":"Q","en":"Didn't you e-mail the employment contract to Mr. Patel yesterday?","vi":"Hôm qua bạn chưa gửi hợp đồng lao động qua email cho ông Patel à?","units":[{"en":"Didn't you e-mail the employment contract to Mr. Patel yesterday?","vi":"Hôm qua bạn chưa gửi hợp đồng lao động qua email cho ông Patel à?"}]},{"speaker":"(A)","en":"Yes, I would agree.","vi":"Đúng vậy, tôi đồng ý.","units":[{"en":"Yes, I would agree.","vi":"Đúng vậy, tôi đồng ý."}]},{"speaker":"(B)","en":"No, I'll send it now.","vi":"Chưa, tôi sẽ gửi ngay bây giờ.","units":[{"en":"No, I'll send it now.","vi":"Chưa, tôi sẽ gửi ngay bây giờ."}]},{"speaker":"(C)","en":"Check the employee manual.","vi":"Hãy xem sổ tay nhân viên.","units":[{"en":"Check the employee manual.","vi":"Hãy xem sổ tay nhân viên."}]}],"vocab":[{"word":"employment contract","pos":"n","ipa":"/ɪmˈplɔɪmənt ˈkɑːntrækt/","meaning":"hợp đồng lao động"},{"word":"employee manual","pos":"n","ipa":"/ɪmˈplɔɪiː ˈmænjuəl/","meaning":"sổ tay nhân viên"},{"word":"agree","pos":"v","ipa":"/əˈɡriː/","meaning":"đồng ý, nhất trí"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi đuôi & Phủ định (Tag / Negative Question)","formula":"CÔNG THỨC PART 2 (khảo bài part 2 — Câu hỏi phủ định Didn't you + V?): Với câu hỏi phủ định, 'Yes' nghĩa là đã làm và 'No' nghĩa là chưa làm; luôn kiểm tra tính logic của vế đi kèm ('No, I'll send it now').","optionAnalysis":{"A":"Sai mục đích giao tiếp: nói 'tôi đồng ý' không hợp với câu hỏi kiểm tra việc đã gửi email hợp đồng hay chưa.","B":"Đáp án logic: phủ nhận chưa gửi hôm qua ('No') và cam kết gửi ngay bây giờ ('I'll send it now').","C":"Bẫy họ từ gần nhau ('employment' - 'employee'): câu mệnh lệnh xem sổ tay không trả lời câu hỏi về email."},"evDocIdx":0,"evTargets":[{"badge":"Câu 14 · Câu hỏi","opt":"B","isCorrect":false,"quote":"Didn't you e-mail the employment contract to Mr. Patel yesterday?","viQuote":"Hôm qua bạn chưa gửi hợp đồng lao động qua email cho ông Patel à?"},{"badge":"Câu 14 · Đáp án B","opt":"B","isCorrect":true,"quote":"No, I'll send it now.","viQuote":"Chưa, tôi sẽ gửi ngay bây giờ."}],"evQuotes":["Didn't you e-mail the employment contract to Mr. Patel yesterday?","No, I'll send it now."]},{"q":15,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_15.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_03.webp"],"stem_en":"Our division's picnic is this Saturday, right?","stem_vi":"Buổi dã ngoại của bộ phận chúng ta diễn ra vào thứ Bảy tuần này, đúng không?","options":{"A":{"en":"There's a lot of rain in the forecast.","vi":"Dự báo thời tiết nói sẽ có mưa lớn đấy."},"B":{"en":"Sure, I like salad.","vi":"Chắc chắn rồi, tôi thích món salad."},"C":{"en":"At the end of this corridor.","vi":"Ở cuối hành lang này."}},"ans":"A","explanation":"Đáp án đúng: (A) Dự báo thời tiết nói sẽ có mưa lớn đấy — đáp án gián tiếp ngụ ý buổi dã ngoại thứ Bảy có thể bị ảnh hưởng hoặc khó diễn ra như kế hoạch.\nDẫn chứng: \"Our division's picnic is this Saturday, right?\" — \"There's a lot of rain in the forecast.\" (Buổi dã ngoại của bộ phận mình vào thứ Bảy này đúng không? — Dự báo có mưa to đấy).\nPhân tích bẫy:\n- (B) Bẫy liên tưởng ngữ cảnh: Từ 'picnic' khiến thí sinh liên tưởng tới đồ ăn ('salad'), nhưng trả lời 'Sure, I like salad' không ăn nhập với câu hỏi xác nhận ngày tổ chức.\n- (C) Sai dạng câu hỏi: 'At the end of this corridor' trả lời cho câu hỏi 'Where', không xác nhận lịch diễn ra vào thứ Bảy.","lines":[{"speaker":"Q","en":"Our division's picnic is this Saturday, right?","vi":"Buổi dã ngoại của bộ phận chúng ta diễn ra vào thứ Bảy tuần này, đúng không?","units":[{"en":"Our division's picnic is this Saturday, right?","vi":"Buổi dã ngoại của bộ phận chúng ta diễn ra vào thứ Bảy tuần này, đúng không?"}]},{"speaker":"(A)","en":"There's a lot of rain in the forecast.","vi":"Dự báo thời tiết nói sẽ có mưa lớn đấy.","units":[{"en":"There's a lot of rain in the forecast.","vi":"Dự báo thời tiết nói sẽ có mưa lớn đấy."}]},{"speaker":"(B)","en":"Sure, I like salad.","vi":"Chắc chắn rồi, tôi thích món salad.","units":[{"en":"Sure, I like salad.","vi":"Chắc chắn rồi, tôi thích món salad."}]},{"speaker":"(C)","en":"At the end of this corridor.","vi":"Ở cuối hành lang này.","units":[{"en":"At the end of this corridor.","vi":"Ở cuối hành lang này."}]}],"vocab":[{"word":"division","pos":"n","ipa":"/dɪˈvɪʒən/","meaning":"bộ phận, khối (trong công ty)"},{"word":"forecast","pos":"n","ipa":"/ˈfɔːrkæst/","meaning":"bản dự báo (thời tiết)"},{"word":"corridor","pos":"n","ipa":"/ˈkɔːrɪdɔːr/","meaning":"hành lang"},{"word":"picnic","pos":"n","ipa":"/ˈpɪknɪk/","meaning":"buổi dã ngoại"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi đuôi & Phủ định (Tag / Negative Question)","formula":"CÔNG THỨC PART 2 (PART 2 THUỘC LÒNG — Câu hỏi đuôi [S + V], right?): Với câu hỏi xác nhận sự kiện ngoài trời, đáp án gián tiếp thường nêu yếu tố thời tiết ảnh hưởng ('rain in the forecast'); loại câu bẫy liên tưởng món ăn và câu trả lời vị trí.","optionAnalysis":{"A":"Đáp án gián tiếp chuẩn ETS: cảnh báo dự báo thời tiết có mưa lớn cho thấy kế hoạch dã ngoại ngoài trời đang bấp bênh.","B":"Bẫy liên tưởng chủ đề: gắn chữ 'picnic' với món 'salad', không trả lời câu hỏi xác nhận thời gian thứ Bảy.","C":"Sai thông tin cần hỏi: chỉ vị trí cuối hành lang (hợp với Where) thay vì xác nhận lịch trình sự kiện."},"evDocIdx":0,"evTargets":[{"badge":"Câu 15 · Câu hỏi","opt":"A","isCorrect":false,"quote":"Our division's picnic is this Saturday, right?","viQuote":"Buổi dã ngoại của bộ phận chúng ta diễn ra vào thứ Bảy tuần này, đúng không?"},{"badge":"Câu 15 · Đáp án A","opt":"A","isCorrect":true,"quote":"There's a lot of rain in the forecast.","viQuote":"Dự báo thời tiết nói sẽ có mưa lớn đấy."}],"evQuotes":["Our division's picnic is this Saturday, right?","There's a lot of rain in the forecast."]},{"q":16,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_16.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_03.webp"],"stem_en":"Would you like coffee or tea?","stem_vi":"Bạn muốn dùng cà phê hay trà?","options":{"A":{"en":"Just water, please.","vi":"Cho tôi nước lọc thôi, cảm ơn."},"B":{"en":"For a few dollars more.","vi":"Thêm vài đô la nữa."},"C":{"en":"A fifteen-minute break.","vi":"Một khoảng nghỉ giải lao mười lăm phút."}},"ans":"A","explanation":"Đáp án đúng: (A) Cho tôi nước lọc thôi, cảm ơn — từ chối khéo cả cà phê lẫn trà để chọn đồ uống thứ ba là nước lọc.\nDẫn chứng: \"Would you like coffee or tea?\" — \"Just water, please.\" (Bạn dùng cà phê hay trà? — Cho tôi nước lọc thôi).\nPhân tích bẫy:\n- (B) Sai loại câu hỏi: Đưa ra số tiền phụ trội (hợp với câu hỏi 'How much'), không phải phản hồi lời mời đồ uống.\n- (C) Bẫy liên tưởng ngữ cảnh: Từ việc uống cà phê/trà dễ liên tưởng tới giờ giải lao ('fifteen-minute break'), nhưng cụm danh từ này trả lời cho 'How long', không trả lời lựa chọn đồ uống.","lines":[{"speaker":"Q","en":"Would you like coffee or tea?","vi":"Bạn muốn dùng cà phê hay trà?","units":[{"en":"Would you like coffee or tea?","vi":"Bạn muốn dùng cà phê hay trà?"}]},{"speaker":"(A)","en":"Just water, please.","vi":"Cho tôi nước lọc thôi, cảm ơn.","units":[{"en":"Just water, please.","vi":"Cho tôi nước lọc thôi, cảm ơn."}]},{"speaker":"(B)","en":"For a few dollars more.","vi":"Thêm vài đô la nữa.","units":[{"en":"For a few dollars more.","vi":"Thêm vài đô la nữa."}]},{"speaker":"(C)","en":"A fifteen-minute break.","vi":"Một khoảng nghỉ giải lao mười lăm phút.","units":[{"en":"A fifteen-minute break.","vi":"Một khoảng nghỉ giải lao mười lăm phút."}]}],"vocab":[{"word":"would like","pos":"phr","ipa":"/wʊd laɪk/","meaning":"muốn, thích dùng (lịch sự)"},{"word":"break","pos":"n","ipa":"/breɪk/","meaning":"giờ nghỉ giải lao"},{"word":"dollar","pos":"n","ipa":"/ˈdɑːlər/","meaning":"đồng đô la"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi lựa chọn A or B (Choice Question)","formula":"CÔNG THỨC PART 2 (khảo bài part 2 — Lựa chọn A or B kiểu mở): Khi nghe 'Would you like A or B?', ngoài việc chọn A hoặc B, đáp án rất hay chọn phương án thứ ba thay thế ('Just water, please').","optionAnalysis":{"A":"Đáp án đúng kiểu lựa chọn thứ ba: lịch sự chọn nước lọc thay cho cả hai lựa chọn cà phê hoặc trà.","B":"Sai loại câu hỏi: đề cập mức giá ('vài đô la nữa') không liên quan đến lời mời chọn đồ uống.","C":"Bẫy liên tưởng bối cảnh nghỉ ngơi: nhắc thời lượng giải lao 15 phút thay vì chọn loại thức uống muốn dùng."},"evDocIdx":0,"evTargets":[{"badge":"Câu 16 · Câu hỏi","opt":"A","isCorrect":false,"quote":"Would you like coffee or tea?","viQuote":"Bạn muốn dùng cà phê hay trà?"},{"badge":"Câu 16 · Đáp án A","opt":"A","isCorrect":true,"quote":"Just water, please.","viQuote":"Cho tôi nước lọc thôi, cảm ơn."}],"evQuotes":["Would you like coffee or tea?","Just water, please."]},{"q":17,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_17.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_04.webp"],"stem_en":"We achieved our sales targets this month.","stem_vi":"Tháng này chúng ta đã đạt được chỉ tiêu doanh số rồi.","options":{"A":{"en":"That's excellent news!","vi":"Thật là một tin tuyệt vời!"},"B":{"en":"A few times a day.","vi":"Vài lần mỗi ngày."},"C":{"en":"To the end of April.","vi":"Đến hết tháng Tư."}},"ans":"A","explanation":"Đáp án đúng: (A) Thật là một tin tuyệt vời! — lời cảm thán khen ngợi tự nhiên trước thông tin bộ phận đã đạt chỉ tiêu doanh số tháng này.\nDẫn chứng: \"We achieved our sales targets this month.\" — \"That's excellent news!\" (Tháng này chúng ta đạt chỉ tiêu doanh số rồi. — Tin tuyệt vời quá!).\nPhân tích bẫy:\n- (B) Sai mẫu câu: 'A few times a day' là cụm trả lời tần suất cho câu hỏi 'How often', không hợp với câu trần thuật báo thành tích.\n- (C) Sai loại thông tin: 'To the end of April' là mốc thời gian kết thúc (trả lời 'Until when'), không liên quan đến phản hồi tin vui.","lines":[{"speaker":"Q","en":"We achieved our sales targets this month.","vi":"Tháng này chúng ta đã đạt được chỉ tiêu doanh số rồi.","units":[{"en":"We achieved our sales targets this month.","vi":"Tháng này chúng ta đã đạt được chỉ tiêu doanh số rồi."}]},{"speaker":"(A)","en":"That's excellent news!","vi":"Thật là một tin tuyệt vời!","units":[{"en":"That's excellent news!","vi":"Thật là một tin tuyệt vời!"}]},{"speaker":"(B)","en":"A few times a day.","vi":"Vài lần mỗi ngày.","units":[{"en":"A few times a day.","vi":"Vài lần mỗi ngày."}]},{"speaker":"(C)","en":"To the end of April.","vi":"Đến hết tháng Tư.","units":[{"en":"To the end of April.","vi":"Đến hết tháng Tư."}]}],"vocab":[{"word":"achieve","pos":"v","ipa":"/əˈtʃiːv/","meaning":"đạt được (mục tiêu, thành tựu)"},{"word":"sales target","pos":"n","ipa":"/seɪlz ˈtɑːrɡɪt/","meaning":"chỉ tiêu doanh số"},{"word":"excellent","pos":"adj","ipa":"/ˈeksələnt/","meaning":"tuyệt vời, xuất sắc"},{"word":"a few times","pos":"phr","ipa":"/ə fjuː taɪmz/","meaning":"vài lần"}],"isScanBacked":false,"grammarType":"Part 2 — Câu trần thuật giao tiếp (Statement & Phản hồi tự nhiên)","formula":"CÔNG THỨC PART 2 (PART 2 THUỘC LÒNG — Câu trần thuật tin vui): Khi nghe câu trần thuật thông báo thành tích ('achieved our sales targets'), chọn lời chúc mừng hoặc đánh giá tích cực ('That's excellent news!'); loại đáp án chỉ tần suất hay mốc thời gian.","optionAnalysis":{"A":"Đáp án phản hồi tự nhiên: bày tỏ sự phấn khởi trước thành tích đạt chỉ tiêu doanh số tháng.","B":"Bẫy mẫu trả lời câu hỏi Wh-: đưa ra tần suất 'vài lần mỗi ngày' hoàn toàn lệch với câu thông báo kết quả.","C":"Sai loại phản hồi: đưa ra mốc thời hạn cuối tháng Tư thay vì phản ứng trước thông báo hoàn thành mục tiêu."},"evDocIdx":0,"evTargets":[{"badge":"Câu 17 · Câu hỏi","opt":"A","isCorrect":false,"quote":"We achieved our sales targets this month.","viQuote":"Tháng này chúng ta đã đạt được chỉ tiêu doanh số rồi."},{"badge":"Câu 17 · Đáp án A","opt":"A","isCorrect":true,"quote":"That's excellent news!","viQuote":"Thật là một tin tuyệt vời!"}],"evQuotes":["We achieved our sales targets this month.","That's excellent news!"]},{"q":18,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_18.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_04.webp"],"stem_en":"How often do you travel for your job?","stem_vi":"Bạn có thường xuyên đi công tác không?","options":{"A":{"en":"It turned out well.","vi":"Kết quả diễn ra rất tốt đẹp."},"B":{"en":"Yes, I did find one.","vi":"Có, tôi đã tìm thấy một cái rồi."},"C":{"en":"About once a month.","vi":"Khoảng một lần mỗi tháng."}},"ans":"C","explanation":"Đáp án đúng: (C) Khoảng một lần mỗi tháng — nêu trực tiếp tần suất đi công tác để trả lời cho 'How often'.\nDẫn chứng: \"How often do you travel for your job?\" — \"About once a month.\" ('once a month' là cụm tần suất chuẩn cho câu hỏi 'How often').\nPhân tích bẫy:\n- (A) Sai dạng 'How': 'It turned out well' trả lời cho câu hỏi đánh giá kết quả sự việc đã qua (kiểu 'How did it go?'), không nêu tần suất.\n- (B) Bẫy Yes/No và sai thì: Câu hỏi 'How often' không trả lời bằng 'Yes', đồng thời 'did find' chia quá khứ không khớp thói quen hiện tại.","lines":[{"speaker":"Q","en":"How often do you travel for your job?","vi":"Bạn có thường xuyên đi công tác không?","units":[{"en":"How often do you travel for your job?","vi":"Bạn có thường xuyên đi công tác không?"}]},{"speaker":"(A)","en":"It turned out well.","vi":"Kết quả diễn ra rất tốt đẹp.","units":[{"en":"It turned out well.","vi":"Kết quả diễn ra rất tốt đẹp."}]},{"speaker":"(B)","en":"Yes, I did find one.","vi":"Có, tôi đã tìm thấy một cái rồi.","units":[{"en":"Yes, I did find one.","vi":"Có, tôi đã tìm thấy một cái rồi."}]},{"speaker":"(C)","en":"About once a month.","vi":"Khoảng một lần mỗi tháng.","units":[{"en":"About once a month.","vi":"Khoảng một lần mỗi tháng."}]}],"vocab":[{"word":"travel","pos":"v","ipa":"/ˈtrævəl/","meaning":"đi công tác, đi lại"},{"word":"turn out","pos":"phr. v","ipa":"/tɜːrn ˈaʊt/","meaning":"hóa ra, diễn ra (kết quả)"},{"word":"once a month","pos":"phr","ipa":"/ˈwʌns ə mʌnθ/","meaning":"mỗi tháng một lần"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi How (Cách thức / Số lượng / Đánh giá)","formula":"CÔNG THỨC PART 2 (khảo bài part 2 — Câu hỏi How often): Nghe 'How often + trợ động từ?' -> Chốt ngay cụm chỉ tần suất ('About once a month', 'twice a week'); loại đáp án Yes/No và câu đánh giá kết quả ('How did it go?').","optionAnalysis":{"A":"Nhầm sang loại câu hỏi đánh giá: nói 'kết quả diễn ra tốt đẹp' thay vì cho biết mức độ thường xuyên.","B":"Bẫy Yes/No trên câu hỏi Wh-: vừa trả lời 'Yes' sai quy tắc vừa lệch sang việc đã tìm thấy đồ trong quá khứ.","C":"Đáp án chuẩn mực: đưa ra đúng tần suất đi công tác là khoảng một lần mỗi tháng."},"evDocIdx":0,"evTargets":[{"badge":"Câu 18 · Câu hỏi","opt":"C","isCorrect":false,"quote":"How often do you travel for your job?","viQuote":"Bạn có thường xuyên đi công tác không?"},{"badge":"Câu 18 · Đáp án C","opt":"C","isCorrect":true,"quote":"About once a month.","viQuote":"Khoảng một lần mỗi tháng."}],"evQuotes":["How often do you travel for your job?","About once a month."]},{"q":19,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_19.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_04.webp"],"stem_en":"We should hike the Wildflower Trail today.","stem_vi":"Hôm nay chúng ta nên đi bộ đường dài trên tuyến đường mòn Wildflower Trail.","options":{"A":{"en":"This seat is available.","vi":"Chỗ ngồi này vẫn còn trống."},"B":{"en":"I didn't bring boots.","vi":"Tôi không mang theo giày bốt."},"C":{"en":"At the visitors' center.","vi":"Tại trung tâm du khách."}},"ans":"B","explanation":"Đáp án đúng: (B) Tôi không mang theo giày bốt — lời từ chối gián tiếp hợp lý vì đi bộ đường mòn (hike) đòi hỏi phải có giày bốt phù hợp.\nDẫn chứng: \"We should hike the Wildflower Trail today.\" — \"I didn't bring boots.\" (Hôm nay chúng ta nên đi đường mòn Wildflower Trail. — Tôi lại không mang theo giày bốt).\nPhân tích bẫy:\n- (A) Lạc chủ đề giao tiếp: 'This seat is available' nói về chỗ ngồi trống (trên xe hoặc phòng chờ), không liên quan lời rủ đi leo núi.\n- (C) Sai dạng phản hồi: 'At the visitors' center' trả lời cho câu hỏi 'Where', không đáp lại lời đề nghị cùng hành động.","lines":[{"speaker":"Q","en":"We should hike the Wildflower Trail today.","vi":"Hôm nay chúng ta nên đi bộ đường dài trên tuyến đường mòn Wildflower Trail.","units":[{"en":"We should hike the Wildflower Trail today.","vi":"Hôm nay chúng ta nên đi bộ đường dài trên tuyến đường mòn Wildflower Trail."}]},{"speaker":"(A)","en":"This seat is available.","vi":"Chỗ ngồi này vẫn còn trống.","units":[{"en":"This seat is available.","vi":"Chỗ ngồi này vẫn còn trống."}]},{"speaker":"(B)","en":"I didn't bring boots.","vi":"Tôi không mang theo giày bốt.","units":[{"en":"I didn't bring boots.","vi":"Tôi không mang theo giày bốt."}]},{"speaker":"(C)","en":"At the visitors' center.","vi":"Tại trung tâm du khách.","units":[{"en":"At the visitors' center.","vi":"Tại trung tâm du khách."}]}],"vocab":[{"word":"hike","pos":"v","ipa":"/haɪk/","meaning":"đi bộ đường dài, leo núi"},{"word":"trail","pos":"n","ipa":"/treɪl/","meaning":"đường mòn"},{"word":"available","pos":"adj","ipa":"/əˈveɪləbəl/","meaning":"còn trống, sẵn có"},{"word":"visitors' center","pos":"n","ipa":"/ˈvɪzɪtərz ˈsentər/","meaning":"trung tâm thông tin du khách"}],"isScanBacked":false,"grammarType":"Part 2 — Lời đề nghị & Gợi ý (Suggestion / Offer)","formula":"CÔNG THỨC PART 2 (PART 2 THUỘC LÒNG — Lời gợi ý We should + V): Với lời rủ 'We should + V', đáp án gián tiếp hay từ chối bằng một trở ngại thực tế ('I didn't bring boots'); loại câu sai chủ đề và câu chỉ vị trí.","optionAnalysis":{"A":"Lạc hoàn toàn ngữ cảnh: thông báo chỗ ngồi còn trống, không phản hồi gì cho gợi ý đi bộ đường mòn.","B":"Đáp án gián tiếp khéo léo: nêu lý do thiếu trang bị (giày bốt) để từ chối hoặc tỏ ý e ngại kế hoạch đi bộ đường dài.","C":"Sai loại phản hồi: đưa ra một địa điểm ('tại trung tâm du khách') như trả lời câu hỏi Where thay vì lời gợi ý."},"evDocIdx":0,"evTargets":[{"badge":"Câu 19 · Câu hỏi","opt":"B","isCorrect":false,"quote":"We should hike the Wildflower Trail today.","viQuote":"Hôm nay chúng ta nên đi bộ đường dài trên tuyến đường mòn Wildflower Trail."},{"badge":"Câu 19 · Đáp án B","opt":"B","isCorrect":true,"quote":"I didn't bring boots.","viQuote":"Tôi không mang theo giày bốt."}],"evQuotes":["We should hike the Wildflower Trail today.","I didn't bring boots."]},{"q":20,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_20.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_04.webp"],"stem_en":"You've booked a hotel in London, haven't you?","stem_vi":"Bạn đã đặt khách sạn ở London rồi, phải không?","options":{"A":{"en":"Very enjoyable, thanks.","vi":"Rất thú vị, cảm ơn bạn."},"B":{"en":"He usually takes the train.","vi":"Anh ấy thường đi tàu hỏa."},"C":{"en":"Yes, I made a reservation last week.","vi":"Đúng rồi, tôi đã đặt phòng từ tuần trước."}},"ans":"C","explanation":"Đáp án đúng: (C) Đúng rồi, tôi đã đặt phòng từ tuần trước — xác nhận 'Yes' và dùng cụm đồng nghĩa 'made a reservation' tương ứng với 'booked a hotel'.\nDẫn chứng: \"You've booked a hotel in London, haven't you?\" — \"Yes, I made a reservation last week.\" ('booked a hotel' được paraphrase thành 'made a reservation').\nPhân tích bẫy:\n- (A) Lạc thì và nội dung: 'Very enjoyable, thanks' dùng để trả lời cảm nhận sau chuyến đi ('How was your trip?'), trong khi câu hỏi chỉ hỏi đã đặt phòng chưa.\n- (B) Sai chủ ngữ và lạc hướng: Đổi từ ngôi 'You' sang 'He' và chuyển chủ đề sang đi tàu hỏa ('takes the train').","lines":[{"speaker":"Q","en":"You've booked a hotel in London, haven't you?","vi":"Bạn đã đặt khách sạn ở London rồi, phải không?","units":[{"en":"You've booked a hotel in London, haven't you?","vi":"Bạn đã đặt khách sạn ở London rồi, phải không?"}]},{"speaker":"(A)","en":"Very enjoyable, thanks.","vi":"Rất thú vị, cảm ơn bạn.","units":[{"en":"Very enjoyable, thanks.","vi":"Rất thú vị, cảm ơn bạn."}]},{"speaker":"(B)","en":"He usually takes the train.","vi":"Anh ấy thường đi tàu hỏa.","units":[{"en":"He usually takes the train.","vi":"Anh ấy thường đi tàu hỏa."}]},{"speaker":"(C)","en":"Yes, I made a reservation last week.","vi":"Đúng rồi, tôi đã đặt phòng từ tuần trước.","units":[{"en":"Yes, I made a reservation last week.","vi":"Đúng rồi, tôi đã đặt phòng từ tuần trước."}]}],"vocab":[{"word":"book","pos":"v","ipa":"/bʊk/","meaning":"đặt trước (phòng khách sạn, vé)"},{"word":"make a reservation","pos":"phr","ipa":"/meɪk ə ˌrezərˈveɪʃən/","meaning":"đặt chỗ trước, đặt phòng trước"},{"word":"enjoyable","pos":"adj","ipa":"/ɪnˈdʒɔɪəbəl/","meaning":"thú vị, dễ chịu"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi đuôi & Phủ định (Tag / Negative Question)","formula":"CÔNG THỨC PART 2 (khảo bài part 2 — Câu hỏi đuôi thì HTHT): Nghe 'You've + V3, haven't you?' -> Chốt đáp án xác nhận 'Yes/No' dùng từ đồng nghĩa ('booked a hotel' = 'made a reservation'); loại câu sai chủ ngữ ('He') và câu đánh giá trải nghiệm.","optionAnalysis":{"A":"Sai trọng tâm hỏi: trả lời đánh giá trải nghiệm dễ chịu sau chuyến đi, không xác nhận việc đã đặt khách sạn.","B":"Sai chủ ngữ và chủ đề: đổi sang nói về thói quen đi tàu hỏa của 'He' thay vì xác nhận đặt phòng của 'You'.","C":"Đáp án đúng: xác nhận 'Yes' kèm cụm đồng nghĩa 'made a reservation' thay cho 'booked a hotel'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 20 · Câu hỏi","opt":"C","isCorrect":false,"quote":"You've booked a hotel in London, haven't you?","viQuote":"Bạn đã đặt khách sạn ở London rồi, phải không?"},{"badge":"Câu 20 · Đáp án C","opt":"C","isCorrect":true,"quote":"Yes, I made a reservation last week.","viQuote":"Đúng rồi, tôi đã đặt phòng từ tuần trước."}],"evQuotes":["You've booked a hotel in London, haven't you?","Yes, I made a reservation last week."]},{"q":21,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_21.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_04.webp"],"stem_en":"Are there any tickets left for tonight's concert?","stem_vi":"Buổi hòa nhạc tối nay còn vé không?","options":{"A":{"en":"It's sold out.","vi":"Vé đã bán hết rồi."},"B":{"en":"He's a concert violinist.","vi":"Anh ấy là nghệ sĩ vĩ cầm hòa nhạc."},"C":{"en":"They already left.","vi":"Họ đã rời đi rồi."}},"ans":"A","explanation":"Đáp án đúng: (A) Vé đã bán hết rồi — trả lời gián tiếp cho biết không còn vé nào cho buổi hòa nhạc tối nay.\nDẫn chứng: \"Are there any tickets left for tonight's concert?\" — \"It's sold out.\" ('sold out' trả lời trực diện cho trạng thái 'any tickets left' = không còn vé).\nPhân tích bẫy:\n- (B) Bẫy lặp từ 'concert': Lặp lại danh từ 'concert' nhưng chuyển sang giới thiệu nghề nghiệp một người đàn ông khác ('nghệ sĩ vĩ cầm').\n- (C) Bẫy từ đồng âm khác nghĩa 'left': Câu hỏi dùng 'left' nghĩa là 'còn sót lại', còn (C) dùng động từ 'left' nghĩa là 'đã rời đi' cùng đại từ 'They' lạc ngữ cảnh.","lines":[{"speaker":"Q","en":"Are there any tickets left for tonight's concert?","vi":"Buổi hòa nhạc tối nay còn vé không?","units":[{"en":"Are there any tickets left for tonight's concert?","vi":"Buổi hòa nhạc tối nay còn vé không?"}]},{"speaker":"(A)","en":"It's sold out.","vi":"Vé đã bán hết rồi.","units":[{"en":"It's sold out.","vi":"Vé đã bán hết rồi."}]},{"speaker":"(B)","en":"He's a concert violinist.","vi":"Anh ấy là nghệ sĩ vĩ cầm hòa nhạc.","units":[{"en":"He's a concert violinist.","vi":"Anh ấy là nghệ sĩ vĩ cầm hòa nhạc."}]},{"speaker":"(C)","en":"They already left.","vi":"Họ đã rời đi rồi.","units":[{"en":"They already left.","vi":"Họ đã rời đi rồi."}]}],"vocab":[{"word":"tickets left","pos":"phr","ipa":"/ˈtɪkɪts left/","meaning":"số vé còn lại"},{"word":"concert","pos":"n","ipa":"/ˈkɑːnsərt/","meaning":"buổi hòa nhạc"},{"word":"sold out","pos":"adj","ipa":"/soʊld aʊt/","meaning":"bán hết sạch (vé, hàng)"},{"word":"violinist","pos":"n","ipa":"/ˌvaɪəˈlɪnɪst/","meaning":"nghệ sĩ vĩ cầm"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi Yes/No & Đáp án gián tiếp","formula":"CÔNG THỨC PART 2 (PART 2 THUỘC LÒNG — Yes/No gián tiếp): Với câu hỏi tình trạng còn/hết ('Are there any tickets left?'), đáp án hay bỏ 'Yes/No' và báo trạng thái trực tiếp ('It's sold out'); cảnh giác bẫy lặp từ đa nghĩa ('left' = còn lại vs rời đi).","optionAnalysis":{"A":"Đáp án gián tiếp chuẩn xác: 'sold out' (bán hết vé) trả lời dứt khoát cho câu hỏi có còn vé hay không.","B":"Bẫy lặp từ 'concert': giới thiệu một nghệ sĩ vĩ cầm hòa nhạc, hoàn toàn không trả lời tình trạng vé.","C":"Bẫy từ đa nghĩa 'left': biến 'còn lại' thành động từ 'đã rời đi' với chủ ngữ 'They' không rõ là ai."},"evDocIdx":0,"evTargets":[{"badge":"Câu 21 · Câu hỏi","opt":"A","isCorrect":false,"quote":"Are there any tickets left for tonight's concert?","viQuote":"Buổi hòa nhạc tối nay còn vé không?"},{"badge":"Câu 21 · Đáp án A","opt":"A","isCorrect":true,"quote":"It's sold out.","viQuote":"Vé đã bán hết rồi."}],"evQuotes":["Are there any tickets left for tonight's concert?","It's sold out."]},{"q":22,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_22.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_04.webp"],"stem_en":"Haven't you used this software before?","stem_vi":"Bạn chưa từng sử dụng phần mềm này trước đây sao?","options":{"A":{"en":"Can I take your order?","vi":"Tôi có thể nhận đơn của quý khách ngay bây giờ không?"},"B":{"en":"I haven't had the chance.","vi":"Tôi vẫn chưa có dịp."},"C":{"en":"About 40 dollars.","vi":"Khoảng 40 đô la."}},"ans":"B","explanation":"Đáp án đúng: (B) Tôi vẫn chưa có dịp — câu trả lời phủ định gián tiếp xác nhận người nói chưa từng sử dụng phần mềm này trước đây.\nDẫn chứng: \"Haven't you used this software before?\" — \"I haven't had the chance.\" (Bạn chưa dùng phần mềm này bao giờ à? — Tôi chưa có cơ hội dùng).\nPhân tích bẫy:\n- (A) Lạc hoàn toàn bối cảnh: 'Can I take your order?' là câu phục vụ ở nhà hàng, không ăn nhập gì với câu hỏi về phần mềm.\n- (C) Sai dạng câu hỏi: 'About 40 dollars' trả lời giá tiền ('How much'), không trả lời việc đã dùng phần mềm hay chưa.","lines":[{"speaker":"Q","en":"Haven't you used this software before?","vi":"Bạn chưa từng sử dụng phần mềm này trước đây sao?","units":[{"en":"Haven't you used this software before?","vi":"Bạn chưa từng sử dụng phần mềm này trước đây sao?"}]},{"speaker":"(A)","en":"Can I take your order?","vi":"Tôi có thể nhận đơn của quý khách ngay bây giờ không?","units":[{"en":"Can I take your order?","vi":"Tôi có thể nhận đơn của quý khách ngay bây giờ không?"}]},{"speaker":"(B)","en":"I haven't had the chance.","vi":"Tôi vẫn chưa có dịp.","units":[{"en":"I haven't had the chance.","vi":"Tôi vẫn chưa có dịp."}]},{"speaker":"(C)","en":"About 40 dollars.","vi":"Khoảng 40 đô la.","units":[{"en":"About 40 dollars.","vi":"Khoảng 40 đô la."}]}],"vocab":[{"word":"software","pos":"n","ipa":"/ˈsɔːftwer/","meaning":"phần mềm"},{"word":"have the chance","pos":"phr","ipa":"/hæv ðə tʃæns/","meaning":"có cơ hội, có dịp"},{"word":"take an order","pos":"phr","ipa":"/teɪk ən ˈɔːrdər/","meaning":"nhận gọi món, nhận đơn hàng"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi đuôi & Phủ định (Tag / Negative Question)","formula":"CÔNG THỨC PART 2 (khảo bài part 2 — Câu hỏi phủ định Haven't you + V3?): Với câu hỏi kinh nghiệm ('Haven't you used [item] before?'), đáp án gián tiếp hay diễn đạt việc chưa từng có cơ hội thử ('I haven't had the chance'); loại câu lệch bối cảnh và câu báo giá.","optionAnalysis":{"A":"Sai bối cảnh hoàn toàn: câu mời gọi món tại nhà hàng không liên quan đến việc sử dụng phần mềm.","B":"Đáp án gián tiếp tự nhiên: 'haven't had the chance' diễn đạt khéo léo rằng người nói chưa từng dùng qua phần mềm.","C":"Sai nội dung hỏi: nêu mức giá 40 đô la (hợp với How much) thay vì xác nhận kinh nghiệm sử dụng."},"evDocIdx":0,"evTargets":[{"badge":"Câu 22 · Câu hỏi","opt":"B","isCorrect":false,"quote":"Haven't you used this software before?","viQuote":"Bạn chưa từng sử dụng phần mềm này trước đây sao?"},{"badge":"Câu 22 · Đáp án B","opt":"B","isCorrect":true,"quote":"I haven't had the chance.","viQuote":"Tôi vẫn chưa có dịp."}],"evQuotes":["Haven't you used this software before?","I haven't had the chance."]},{"q":23,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_23.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_05.webp"],"stem_en":"When is the new blender going to be released?","stem_vi":"Khi nào mẫu máy xay sinh tố mới sẽ được ra mắt?","options":{"A":{"en":"Only with fruits and vegetables.","vi":"Chỉ dùng với trái cây và rau củ thôi."},"B":{"en":"In the kitchen cabinet.","vi":"Ở trong tủ bếp."},"C":{"en":"The prototype is still being tested.","vi":"Mẫu thử nghiệm vẫn đang trong quá trình kiểm tra."}},"ans":"C","explanation":"Đáp án đúng: (C) Mẫu thử nghiệm vẫn đang trong quá trình kiểm tra — trả lời gián tiếp cho câu hỏi 'When' bằng cách nêu lý do sản phẩm chưa có ngày ra mắt chính thức.\nDẫn chứng: \"When is the new blender going to be released?\" — \"The prototype is still being tested.\" ('prototype' gắn với sản phẩm mới 'new blender'; đang thử nghiệm nên chưa ra mắt).\nPhân tích bẫy:\n- (A) Bẫy liên tưởng công dụng: Nhắc đến trái cây và rau củ (thứ bỏ vào máy xay) nhưng không trả lời thời điểm phát hành.\n- (B) Sai từ để hỏi: 'In the kitchen cabinet' chỉ địa điểm cất giữ (hợp với 'Where'), không trả lời 'When'.","lines":[{"speaker":"Q","en":"When is the new blender going to be released?","vi":"Khi nào mẫu máy xay sinh tố mới sẽ được ra mắt?","units":[{"en":"When is the new blender going to be released?","vi":"Khi nào mẫu máy xay sinh tố mới sẽ được ra mắt?"}]},{"speaker":"(A)","en":"Only with fruits and vegetables.","vi":"Chỉ dùng với trái cây và rau củ thôi.","units":[{"en":"Only with fruits and vegetables.","vi":"Chỉ dùng với trái cây và rau củ thôi."}]},{"speaker":"(B)","en":"In the kitchen cabinet.","vi":"Ở trong tủ bếp.","units":[{"en":"In the kitchen cabinet.","vi":"Ở trong tủ bếp."}]},{"speaker":"(C)","en":"The prototype is still being tested.","vi":"Mẫu thử nghiệm vẫn đang trong quá trình kiểm tra.","units":[{"en":"The prototype is still being tested.","vi":"Mẫu thử nghiệm vẫn đang trong quá trình kiểm tra."}]}],"vocab":[{"word":"blender","pos":"n","ipa":"/ˈblendər/","meaning":"máy xay sinh tố"},{"word":"release","pos":"v","ipa":"/rɪˈliːs/","meaning":"ra mắt, phát hành"},{"word":"prototype","pos":"n","ipa":"/ˈproʊtətaɪp/","meaning":"mẫu thử nghiệm, nguyên mẫu"},{"word":"cabinet","pos":"n","ipa":"/ˈkæbɪnət/","meaning":"tủ đựng đồ (tủ bếp)"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi When / Thời gian (Mốc thời điểm & Thời lượng)","formula":"CÔNG THỨC PART 2 (PART 2 THUỘC LÒNG — Câu hỏi When gián tiếp): Khi câu hỏi 'When' không có mốc ngày giờ cụ thể trong đáp án, hãy tìm câu giải thích tiến độ hiện tại khiến thời điểm chưa xác định ('The prototype is still being tested').","optionAnalysis":{"A":"Bẫy liên tưởng công năng máy xay: nói về trái cây và rau củ thay vì cho biết thời điểm sản phẩm ra mắt.","B":"Sai từ để hỏi: trả lời vị trí 'trong tủ bếp' (dành cho Where) thay vì mốc thời gian của câu hỏi When.","C":"Đáp án gián tiếp hợp lý: cho biết mẫu thử vẫn đang được kiểm tra nên chưa thể ấn định ngày phát hành."},"evDocIdx":0,"evTargets":[{"badge":"Câu 23 · Câu hỏi","opt":"C","isCorrect":false,"quote":"When is the new blender going to be released?","viQuote":"Khi nào mẫu máy xay sinh tố mới sẽ được ra mắt?"},{"badge":"Câu 23 · Đáp án C","opt":"C","isCorrect":true,"quote":"The prototype is still being tested.","viQuote":"Mẫu thử nghiệm vẫn đang trong quá trình kiểm tra."}],"evQuotes":["When is the new blender going to be released?","The prototype is still being tested."]},{"q":24,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_24.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_05.webp"],"stem_en":"Who's picking up our clients at the airport?","stem_vi":"Ai sẽ ra sân bay đón khách hàng của chúng ta?","options":{"A":{"en":"They decided to drive.","vi":"Họ quyết định tự lái xe đến."},"B":{"en":"At terminal 2.","vi":"Tại nhà ga số 2."},"C":{"en":"It's a marketing position.","vi":"Đó là một vị trí trong bộ phận tiếp thị."}},"ans":"A","explanation":"Đáp án đúng: (A) Họ quyết định tự lái xe đến — giải thích gián tiếp rằng không cần ai ra sân bay đón vì khách hàng ('They') tự lái xe tới.\nDẫn chứng: \"Who's picking up our clients at the airport?\" — \"They decided to drive.\" ('They' quy chiếu cho 'our clients'; tự lái xe đồng nghĩa không cần người đón).\nPhân tích bẫy:\n- (B) Sai từ để hỏi: 'At terminal 2' trả lời vị trí tại sân bay (dành cho 'Where'), không trả lời 'Who' là người đi đón.\n- (C) Sai ngữ cảnh: Nhắc đến một vị trí tuyển dụng trong bộ phận tiếp thị, hoàn toàn không liên quan việc đón khách ở sân bay.","lines":[{"speaker":"Q","en":"Who's picking up our clients at the airport?","vi":"Ai sẽ ra sân bay đón khách hàng của chúng ta?","units":[{"en":"Who's picking up our clients at the airport?","vi":"Ai sẽ ra sân bay đón khách hàng của chúng ta?"}]},{"speaker":"(A)","en":"They decided to drive.","vi":"Họ quyết định tự lái xe đến.","units":[{"en":"They decided to drive.","vi":"Họ quyết định tự lái xe đến."}]},{"speaker":"(B)","en":"At terminal 2.","vi":"Tại nhà ga số 2.","units":[{"en":"At terminal 2.","vi":"Tại nhà ga số 2."}]},{"speaker":"(C)","en":"It's a marketing position.","vi":"Đó là một vị trí trong bộ phận tiếp thị.","units":[{"en":"It's a marketing position.","vi":"Đó là một vị trí trong bộ phận tiếp thị."}]}],"vocab":[{"word":"pick up","pos":"phr. v","ipa":"/pɪk ˈʌp/","meaning":"đón (ai đó)"},{"word":"client","pos":"n","ipa":"/ˈklaɪənt/","meaning":"khách hàng"},{"word":"terminal","pos":"n","ipa":"/ˈtɜːrmɪnəl/","meaning":"nhà ga (sân bay)"},{"word":"marketing position","pos":"n","ipa":"/ˈmɑːrkɪtɪŋ pəˈzɪʃən/","meaning":"vị trí công việc tiếp thị"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi Who (Hỏi người / Vai trò / Trách nhiệm)","formula":"CÔNG THỨC PART 2 (khảo bài part 2 — Câu hỏi Who gián tiếp): Với câu hỏi phân công 'Who's + V-ing?', nếu không có tên riêng, đáp án đúng thường nêu việc đối tượng tự thu xếp phương án khác ('They decided to drive').","optionAnalysis":{"A":"Đáp án gián tiếp chuẩn ETS: khách hàng ('They') quyết định tự lái xe nên không cần ai ra sân bay đón.","B":"Sai từ để hỏi: 'Tại nhà ga số 2' trả lời cho Where, lợi dụng từ khóa 'airport' trong câu hỏi để gây nhiễu.","C":"Lạc hoàn toàn ngữ cảnh: chuyển sang giới thiệu vị trí công việc tiếp thị thay vì việc đón khách hàng."},"evDocIdx":0,"evTargets":[{"badge":"Câu 24 · Câu hỏi","opt":"A","isCorrect":false,"quote":"Who's picking up our clients at the airport?","viQuote":"Ai sẽ ra sân bay đón khách hàng của chúng ta?"},{"badge":"Câu 24 · Đáp án A","opt":"A","isCorrect":true,"quote":"They decided to drive.","viQuote":"Họ quyết định tự lái xe đến."}],"evQuotes":["Who's picking up our clients at the airport?","They decided to drive."]},{"q":25,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_25.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_05.webp"],"stem_en":"Where are the red roses that came in this morning?","stem_vi":"Số hoa hồng đỏ mới nhập về sáng nay đâu rồi?","options":{"A":{"en":"About three liters of water.","vi":"Khoảng ba lít nước."},"B":{"en":"No, I didn't check out the sale.","vi":"Không, tôi không xem đợt giảm giá đó."},"C":{"en":"I needed some for a large bouquet.","vi":"Tôi cần lấy một ít để làm một bó hoa lớn."}},"ans":"C","explanation":"Đáp án đúng: (C) Tôi cần lấy một ít để làm một bó hoa lớn — trả lời gián tiếp giải thích số hoa hồng đỏ không còn ở chỗ cũ vì người nói đã lấy đi cắm bó hoa.\nDẫn chứng: \"Where are the red roses that came in this morning?\" — \"I needed some for a large bouquet.\" ('some' quy chiếu cho 'red roses', 'bouquet' gắn liền ngữ cảnh tiệm hoa).\nPhân tích bẫy:\n- (A) Bẫy liên tưởng: Nghĩ đến hoa tươi cần nước nên gài lượng nước ('About three liters of water'), nhưng cụm này trả lời cho 'How much', không trả lời 'Where'.\n- (B) Bẫy Yes/No trên câu hỏi Wh-: Dùng 'No' trả lời câu hỏi 'Where' và lệch sang đợt giảm giá ('sale').","lines":[{"speaker":"Q","en":"Where are the red roses that came in this morning?","vi":"Số hoa hồng đỏ mới nhập về sáng nay đâu rồi?","units":[{"en":"Where are the red roses that came in this morning?","vi":"Số hoa hồng đỏ mới nhập về sáng nay đâu rồi?"}]},{"speaker":"(A)","en":"About three liters of water.","vi":"Khoảng ba lít nước.","units":[{"en":"About three liters of water.","vi":"Khoảng ba lít nước."}]},{"speaker":"(B)","en":"No, I didn't check out the sale.","vi":"Không, tôi không xem đợt giảm giá đó.","units":[{"en":"No, I didn't check out the sale.","vi":"Không, tôi không xem đợt giảm giá đó."}]},{"speaker":"(C)","en":"I needed some for a large bouquet.","vi":"Tôi cần lấy một ít để làm một bó hoa lớn.","units":[{"en":"I needed some for a large bouquet.","vi":"Tôi cần lấy một ít để làm một bó hoa lớn."}]}],"vocab":[{"word":"come in","pos":"phr. v","ipa":"/kʌm ˈɪn/","meaning":"được nhập về, được giao tới"},{"word":"bouquet","pos":"n","ipa":"/buˈkeɪ/","meaning":"bó hoa"},{"word":"liter","pos":"n","ipa":"/ˈliːtər/","meaning":"lít (đơn vị đo thể tích)"},{"word":"check out","pos":"phr. v","ipa":"/tʃek ˈaʊt/","meaning":"xem qua, kiểm tra"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi Where (Hỏi địa điểm / Phương hướng)","formula":"CÔNG THỨC PART 2 (PART 2 THUỘC LÒNG — Câu hỏi Where gián tiếp): Khi câu hỏi 'Where are [items]?' không có giới từ chỉ nơi chốn ở đáp án, tìm câu giải thích ai đó đã lấy chúng đi làm gì ('I needed some for a large bouquet').","optionAnalysis":{"A":"Bẫy liên tưởng chăm sóc hoa: nêu lượng nước 'ba lít' (hợp với How much) chứ không giải thích hoa đang ở đâu.","B":"Bẫy Yes/No sai quy tắc: dùng 'No' để trả lời câu hỏi Where và nói lệch sang chuyện xem giảm giá.","C":"Đáp án gián tiếp tự nhiên: giải thích người nói đã lấy số hoa hồng để kết một bó hoa lớn."},"evDocIdx":0,"evTargets":[{"badge":"Câu 25 · Câu hỏi","opt":"C","isCorrect":false,"quote":"Where are the red roses that came in this morning?","viQuote":"Số hoa hồng đỏ mới nhập về sáng nay đâu rồi?"},{"badge":"Câu 25 · Đáp án C","opt":"C","isCorrect":true,"quote":"I needed some for a large bouquet.","viQuote":"Tôi cần lấy một ít để làm một bó hoa lớn."}],"evQuotes":["Where are the red roses that came in this morning?","I needed some for a large bouquet."]},{"q":26,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_26.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_05.webp"],"stem_en":"This film has been nominated for several awards.","stem_vi":"Bộ phim này đã được đề cử cho nhiều giải thưởng.","options":{"A":{"en":"Why don't we go see it?","vi":"Sao chúng ta không đi xem thử nhỉ?"},"B":{"en":"After the announcement.","vi":"Sau thông báo."},"C":{"en":"He made a great speech.","vi":"Anh ấy đã có một bài phát biểu rất hay."}},"ans":"A","explanation":"Đáp án đúng: (A) Sao chúng ta không đi xem thử nhỉ? — lời rủ tự nhiên dựa trên thông tin bộ phim vừa được đề cử nhiều giải thưởng.\nDẫn chứng: \"This film has been nominated for several awards.\" — \"Why don't we go see it?\" ('it' quy chiếu cho 'This film'; đề cử giải thưởng tạo động lực đi xem).\nPhân tích bẫy:\n- (B) Sai mẫu câu hỏi: 'After the announcement' là cụm thời gian trả lời cho 'When', không khớp với câu trần thuật giới thiệu phim.\n- (C) Bẫy liên tưởng từ 'awards': Từ giải thưởng gài sang bài phát biểu hay của 'He', trong khi câu gốc không hề nhắc đến nhân vật nam nào.","lines":[{"speaker":"Q","en":"This film has been nominated for several awards.","vi":"Bộ phim này đã được đề cử cho nhiều giải thưởng.","units":[{"en":"This film has been nominated for several awards.","vi":"Bộ phim này đã được đề cử cho nhiều giải thưởng."}]},{"speaker":"(A)","en":"Why don't we go see it?","vi":"Sao chúng ta không đi xem thử nhỉ?","units":[{"en":"Why don't we go see it?","vi":"Sao chúng ta không đi xem thử nhỉ?"}]},{"speaker":"(B)","en":"After the announcement.","vi":"Sau thông báo.","units":[{"en":"After the announcement.","vi":"Sau thông báo."}]},{"speaker":"(C)","en":"He made a great speech.","vi":"Anh ấy đã có một bài phát biểu rất hay.","units":[{"en":"He made a great speech.","vi":"Anh ấy đã có một bài phát biểu rất hay."}]}],"vocab":[{"word":"nominate","pos":"v","ipa":"/ˈnɑːmɪneɪt/","meaning":"đề cử (giải thưởng)"},{"word":"award","pos":"n","ipa":"/əˈwɔːrd/","meaning":"giải thưởng"},{"word":"announcement","pos":"n","ipa":"/əˈnaʊnsmənt/","meaning":"thông báo"},{"word":"speech","pos":"n","ipa":"/spiːtʃ/","meaning":"bài phát biểu"}],"isScanBacked":false,"grammarType":"Part 2 — Câu trần thuật giao tiếp (Statement & Phản hồi tự nhiên)","formula":"CÔNG THỨC PART 2 (khảo bài part 2 — Statement + Đề xuất hành động): Khi người nói khen/giới thiệu sản phẩm hay ('nominated for several awards'), phản hồi tự nhiên thường là gợi ý cùng trải nghiệm ('Why don't we go see it?').","optionAnalysis":{"A":"Đáp án giao tiếp tự nhiên: đề xuất cùng đi xem ('go see it') sau khi nghe bộ phim được đề cử nhiều giải.","B":"Sai loại phản hồi: đưa ra mốc thời gian 'sau thông báo' (hợp với When) không ăn nhập câu khen phim.","C":"Bẫy liên tưởng lễ trao giải: tự thêm chủ ngữ 'He' và bài phát biểu không hề xuất hiện trong câu gốc."},"evDocIdx":0,"evTargets":[{"badge":"Câu 26 · Câu hỏi","opt":"A","isCorrect":false,"quote":"This film has been nominated for several awards.","viQuote":"Bộ phim này đã được đề cử cho nhiều giải thưởng."},{"badge":"Câu 26 · Đáp án A","opt":"A","isCorrect":true,"quote":"Why don't we go see it?","viQuote":"Sao chúng ta không đi xem thử nhỉ?"}],"evQuotes":["This film has been nominated for several awards.","Why don't we go see it?"]},{"q":27,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_27.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_05.webp"],"stem_en":"Who's interested in starting a car pool program?","stem_vi":"Ai quan tâm đến việc khởi xướng chương trình đi chung xe không?","options":{"A":{"en":"Thanks, but I can't swim.","vi":"Cảm ơn, nhưng tôi không biết bơi."},"B":{"en":"Clara's already organizing one.","vi":"Clara đang tổ chức một chương trình như vậy rồi."},"C":{"en":"It's a very interesting article.","vi":"Đó là một bài báo rất thú vị."}},"ans":"B","explanation":"Đáp án đúng: (B) Clara đang tổ chức một chương trình như vậy rồi — cung cấp tên riêng 'Clara' trả lời cho 'Who' và dùng 'one' thay cho 'a car pool program'.\nDẫn chứng: \"Who's interested in starting a car pool program?\" — \"Clara's already organizing one.\" ('Clara' trả lời trực tiếp cho 'Who'; 'one' = 'a car pool program').\nPhân tích bẫy:\n- (A) Bẫy tách nghĩa từ 'pool': Hiểu sai 'car pool' (đi chung xe) thành hồ bơi ('swimming pool') nên mới nói không biết bơi ('can't swim').\n- (C) Bẫy lặp họ từ: Lặp 'interested' thành 'interesting' kèm nhận xét bài báo không liên quan đến chương trình đi chung xe.","lines":[{"speaker":"Q","en":"Who's interested in starting a car pool program?","vi":"Ai quan tâm đến việc khởi xướng chương trình đi chung xe không?","units":[{"en":"Who's interested in starting a car pool program?","vi":"Ai quan tâm đến việc khởi xướng chương trình đi chung xe không?"}]},{"speaker":"(A)","en":"Thanks, but I can't swim.","vi":"Cảm ơn, nhưng tôi không biết bơi.","units":[{"en":"Thanks, but I can't swim.","vi":"Cảm ơn, nhưng tôi không biết bơi."}]},{"speaker":"(B)","en":"Clara's already organizing one.","vi":"Clara đang tổ chức một chương trình như vậy rồi.","units":[{"en":"Clara's already organizing one.","vi":"Clara đang tổ chức một chương trình như vậy rồi."}]},{"speaker":"(C)","en":"It's a very interesting article.","vi":"Đó là một bài báo rất thú vị.","units":[{"en":"It's a very interesting article.","vi":"Đó là một bài báo rất thú vị."}]}],"vocab":[{"word":"car pool","pos":"n","ipa":"/ˈkɑːr puːl/","meaning":"chương trình đi chung xe"},{"word":"organize","pos":"v","ipa":"/ˈɔːrɡənaɪz/","meaning":"tổ chức, điều phối"},{"word":"article","pos":"n","ipa":"/ˈɑːrtɪkəl/","meaning":"bài báo"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi Who (Hỏi người / Vai trò / Trách nhiệm)","formula":"CÔNG THỨC PART 2 (PART 2 THUỘC LÒNG — Câu hỏi Who + từ ghép): Nghe 'Who's interested in + V-ing?' -> Chọn đáp án nêu tên người cụ thể ('Clara's already organizing one'); cảnh giác bẫy tách nghĩa từ ghép ('car pool' vs 'swim') và lặp họ từ ('interested' vs 'interesting').","optionAnalysis":{"A":"Bẫy đồng âm/tách nghĩa từ 'pool': nhầm 'car pool' (đi chung xe) với hồ bơi nên trả lời không biết bơi.","B":"Đáp án đúng: nêu tên người phụ trách ('Clara') và dùng đại từ 'one' thay cho chương trình đi chung xe.","C":"Bẫy họ từ 'interested - interesting': nói về một bài báo thú vị, hoàn toàn lệch khỏi câu hỏi Who."},"evDocIdx":0,"evTargets":[{"badge":"Câu 27 · Câu hỏi","opt":"B","isCorrect":false,"quote":"Who's interested in starting a car pool program?","viQuote":"Ai quan tâm đến việc khởi xướng chương trình đi chung xe không?"},{"badge":"Câu 27 · Đáp án B","opt":"B","isCorrect":true,"quote":"Clara's already organizing one.","viQuote":"Clara đang tổ chức một chương trình như vậy rồi."}],"evQuotes":["Who's interested in starting a car pool program?","Clara's already organizing one."]},{"q":28,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_28.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_06.webp"],"stem_en":"Where will I teach my workshop this month?","stem_vi":"Tháng này tôi sẽ giảng dạy buổi hội thảo của mình ở đâu?","options":{"A":{"en":"We just sent an e-mail to all instructors.","vi":"Chúng tôi vừa gửi một email cho tất cả các giảng viên rồi."},"B":{"en":"Five to seven months.","vi":"Từ năm đến bảy tháng."},"C":{"en":"Yes, it's a beautiful building.","vi":"Đúng vậy, đó là một tòa nhà rất đẹp."}},"ans":"A","explanation":"Đáp án đúng: (A) Chúng tôi vừa gửi một email cho tất cả các giảng viên rồi — đáp án gián tiếp cho biết địa điểm giảng dạy đã được thông báo trong email gửi giảng viên.\nDẫn chứng: \"Where will I teach my workshop this month?\" — \"We just sent an e-mail to all instructors.\" (Người dạy workshop chính là 'instructor', thông tin địa điểm nằm trong email).\nPhân tích bẫy:\n- (B) Bẫy lặp từ 'month': Lặp 'month' thành 'months' nhưng lại trả lời khoảng thời gian (dành cho 'How long'), không phải 'Where'.\n- (C) Bẫy Yes/No cho câu hỏi Wh-: Câu hỏi 'Where' không trả lời bằng 'Yes', dù câu có nhắc đến 'building'.","lines":[{"speaker":"Q","en":"Where will I teach my workshop this month?","vi":"Tháng này tôi sẽ giảng dạy buổi hội thảo của mình ở đâu?","units":[{"en":"Where will I teach my workshop this month?","vi":"Tháng này tôi sẽ giảng dạy buổi hội thảo của mình ở đâu?"}]},{"speaker":"(A)","en":"We just sent an e-mail to all instructors.","vi":"Chúng tôi vừa gửi một email cho tất cả các giảng viên rồi.","units":[{"en":"We just sent an e-mail to all instructors.","vi":"Chúng tôi vừa gửi một email cho tất cả các giảng viên rồi."}]},{"speaker":"(B)","en":"Five to seven months.","vi":"Từ năm đến bảy tháng.","units":[{"en":"Five to seven months.","vi":"Từ năm đến bảy tháng."}]},{"speaker":"(C)","en":"Yes, it's a beautiful building.","vi":"Đúng vậy, đó là một tòa nhà rất đẹp.","units":[{"en":"Yes, it's a beautiful building.","vi":"Đúng vậy, đó là một tòa nhà rất đẹp."}]}],"vocab":[{"word":"workshop","pos":"n","ipa":"/ˈwɜːrkʃɑːp/","meaning":"buổi hội thảo thực hành"},{"word":"instructor","pos":"n","ipa":"/ɪnˈstrʌktər/","meaning":"giảng viên, người hướng dẫn"},{"word":"teach","pos":"v","ipa":"/tiːtʃ/","meaning":"giảng dạy"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi Where (Hỏi địa điểm / Phương hướng)","formula":"CÔNG THỨC PART 2 (khảo bài part 2 — Câu hỏi Where gián tiếp qua nguồn tin): Với 'Where will I + V?', đáp án gián tiếp thường chỉ nguồn thông báo chứa địa điểm ('We just sent an e-mail to all instructors'); loại bẫy lặp từ 'month' và Yes/No.","optionAnalysis":{"A":"Đáp án gián tiếp chuẩn xác: chỉ dẫn người hỏi xem email vừa gửi tới toàn bộ giảng viên để biết địa điểm dạy.","B":"Bẫy lặp từ 'month' và sai từ để hỏi: trả lời khoảng thời gian (5–7 tháng) cho câu hỏi địa điểm Where.","C":"Bẫy Yes/No trên câu hỏi Wh-: mở đầu bằng 'Yes' sai quy tắc và chỉ khen tòa nhà đẹp chứ không chỉ địa điểm."},"evDocIdx":0,"evTargets":[{"badge":"Câu 28 · Câu hỏi","opt":"A","isCorrect":false,"quote":"Where will I teach my workshop this month?","viQuote":"Tháng này tôi sẽ giảng dạy buổi hội thảo của mình ở đâu?"},{"badge":"Câu 28 · Đáp án A","opt":"A","isCorrect":true,"quote":"We just sent an e-mail to all instructors.","viQuote":"Chúng tôi vừa gửi một email cho tất cả các giảng viên rồi."}],"evQuotes":["Where will I teach my workshop this month?","We just sent an e-mail to all instructors."]},{"q":29,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_29.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_06.webp"],"stem_en":"Why are we moving these sweaters to the back of the store?","stem_vi":"Tại sao chúng ta lại chuyển những chiếc áo len này ra phía sau cửa hàng?","options":{"A":{"en":"In the new shopping mall.","vi":"Trong trung tâm thương mại mới."},"B":{"en":"Yes, they come in other colors.","vi":"Có, chúng có cả những màu khác nữa."},"C":{"en":"Our spring merchandise is arriving soon.","vi":"Hàng hóa mùa xuân của chúng ta sắp về rồi."}},"ans":"C","explanation":"Đáp án đúng: (C) Hàng hóa mùa xuân của chúng ta sắp về rồi — nêu trực tiếp nguyên nhân phải dọn áo len (đồ mùa lạnh) ra phía sau cửa hàng để nhường chỗ trưng bày hàng mùa xuân.\nDẫn chứng: \"Why are we moving these sweaters to the back of the store?\" — \"Our spring merchandise is arriving soon.\" (Chuyển áo len ra sau để lấy chỗ cho hàng mùa xuân sắp tới).\nPhân tích bẫy:\n- (A) Sai từ để hỏi: 'In the new shopping mall' trả lời cho 'Where' (ở đâu), không giải thích lý do 'Why'.\n- (B) Bẫy Yes/No trên câu hỏi Wh-: Dùng 'Yes' cho câu hỏi 'Why' và lạc sang chủ đề màu sắc khác của áo.","lines":[{"speaker":"Q","en":"Why are we moving these sweaters to the back of the store?","vi":"Tại sao chúng ta lại chuyển những chiếc áo len này ra phía sau cửa hàng?","units":[{"en":"Why are we moving these sweaters to the back of the store?","vi":"Tại sao chúng ta lại chuyển những chiếc áo len này ra phía sau cửa hàng?"}]},{"speaker":"(A)","en":"In the new shopping mall.","vi":"Trong trung tâm thương mại mới.","units":[{"en":"In the new shopping mall.","vi":"Trong trung tâm thương mại mới."}]},{"speaker":"(B)","en":"Yes, they come in other colors.","vi":"Có, chúng có cả những màu khác nữa.","units":[{"en":"Yes, they come in other colors.","vi":"Có, chúng có cả những màu khác nữa."}]},{"speaker":"(C)","en":"Our spring merchandise is arriving soon.","vi":"Hàng hóa mùa xuân của chúng ta sắp về rồi.","units":[{"en":"Our spring merchandise is arriving soon.","vi":"Hàng hóa mùa xuân của chúng ta sắp về rồi."}]}],"vocab":[{"word":"sweater","pos":"n","ipa":"/ˈswetər/","meaning":"áo len dài tay"},{"word":"merchandise","pos":"n","ipa":"/ˈmɜːrtʃəndaɪs/","meaning":"hàng hóa"},{"word":"arrive","pos":"v","ipa":"/əˈraɪv/","meaning":"về tới, đến nơi"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi Why (Hỏi nguyên nhân & Mục đích)","formula":"CÔNG THỨC PART 2 (PART 2 THUỘC LÒNG — Câu hỏi Why không có Because): Câu hỏi 'Why' rất hay bỏ 'Because' và nêu thẳng sự kiện nguyên nhân ở đáp án ('Our spring merchandise is arriving soon'); loại câu trả lời nơi chốn và Yes/No.","optionAnalysis":{"A":"Sai loại thông tin hỏi: trả lời địa điểm (trong trung tâm thương mại mới) thay vì lý do dời vị trí áo len.","B":"Bẫy Yes/No sai quy tắc: mở đầu bằng 'Yes' cho câu hỏi Why và chuyển sang nói về màu sắc khác của sản phẩm.","C":"Đáp án đúng dạng lược 'Because': giải thích hàng mùa xuân sắp về nên cần dọn áo len ra phía sau."},"evDocIdx":0,"evTargets":[{"badge":"Câu 29 · Câu hỏi","opt":"C","isCorrect":false,"quote":"Why are we moving these sweaters to the back of the store?","viQuote":"Tại sao chúng ta lại chuyển những chiếc áo len này ra phía sau cửa hàng?"},{"badge":"Câu 29 · Đáp án C","opt":"C","isCorrect":true,"quote":"Our spring merchandise is arriving soon.","viQuote":"Hàng hóa mùa xuân của chúng ta sắp về rồi."}],"evQuotes":["Why are we moving these sweaters to the back of the store?","Our spring merchandise is arriving soon."]},{"q":30,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_30.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_06.webp"],"stem_en":"Would you be interested in working on some of these contracts?","stem_vi":"Bạn có muốn tham gia xử lý một số hợp đồng này không?","options":{"A":{"en":"Thank you for meeting me.","vi":"Cảm ơn bạn đã gặp tôi."},"B":{"en":"A contact lens prescription.","vi":"Một đơn kính áp tròng."},"C":{"en":"I have very limited time.","vi":"Quỹ thời gian của tôi rất hạn hẹp."}},"ans":"C","explanation":"Đáp án đúng: (C) Quỹ thời gian của tôi rất hạn hẹp — lời từ chối gián tiếp lịch sự cho đề nghị tham gia xử lý thêm hợp đồng.\nDẫn chứng: \"Would you be interested in working on some of these contracts?\" — \"I have very limited time.\" (Vì không có đủ thời gian nên không thể nhận thêm hợp đồng).\nPhân tích bẫy:\n- (A) Lạc chức năng giao tiếp: 'Thank you for meeting me' là câu chào tạm biệt/cảm ơn khi kết thúc buổi gặp, không trả lời đề nghị nhận việc.\n- (B) Bẫy gần âm: Cặp từ 'contracts' (hợp đồng) và 'contact (lens)' (kính áp tròng) phát âm gần giống nhau nhưng nghĩa hoàn toàn xa lạ.","lines":[{"speaker":"Q","en":"Would you be interested in working on some of these contracts?","vi":"Bạn có muốn tham gia xử lý một số hợp đồng này không?","units":[{"en":"Would you be interested in working on some of these contracts?","vi":"Bạn có muốn tham gia xử lý một số hợp đồng này không?"}]},{"speaker":"(A)","en":"Thank you for meeting me.","vi":"Cảm ơn bạn đã gặp tôi.","units":[{"en":"Thank you for meeting me.","vi":"Cảm ơn bạn đã gặp tôi."}]},{"speaker":"(B)","en":"A contact lens prescription.","vi":"Một đơn kính áp tròng.","units":[{"en":"A contact lens prescription.","vi":"Một đơn kính áp tròng."}]},{"speaker":"(C)","en":"I have very limited time.","vi":"Quỹ thời gian của tôi rất hạn hẹp.","units":[{"en":"I have very limited time.","vi":"Quỹ thời gian của tôi rất hạn hẹp."}]}],"vocab":[{"word":"contract","pos":"n","ipa":"/ˈkɑːntrækt/","meaning":"bản hợp đồng"},{"word":"limited","pos":"adj","ipa":"/ˈlɪmɪtɪd/","meaning":"hạn chế, hạn hẹp"},{"word":"contact lens","pos":"n","ipa":"/ˈkɑːntækt lenz/","meaning":"kính áp tròng"},{"word":"prescription","pos":"n","ipa":"/prɪˈskrɪpʃən/","meaning":"đơn thuốc, đơn kính"}],"isScanBacked":false,"grammarType":"Part 2 — Lời đề nghị & Gợi ý (Suggestion / Offer)","formula":"CÔNG THỨC PART 2 (khảo bài part 2 — Từ chối khéo lời đề nghị): Với lời mời nhận việc 'Would you be interested in + V-ing?', đáp án từ chối lịch sự thường nêu hạn chế thời gian ('I have very limited time'); loại bẫy gần âm 'contracts' vs 'contact'.","optionAnalysis":{"A":"Sai ngữ cảnh giao tiếp: câu cảm ơn vì đã gặp mặt không phản hồi lời mời tham gia xử lý hợp đồng.","B":"Bẫy phát âm gần giống: dùng 'contact lens' (kính áp tròng) để gài bẫy từ 'contracts' (hợp đồng).","C":"Đáp án gián tiếp khéo léo: nêu lý do quỹ thời gian hạn hẹp để từ chối nhận thêm hợp đồng."},"evDocIdx":0,"evTargets":[{"badge":"Câu 30 · Câu hỏi","opt":"C","isCorrect":false,"quote":"Would you be interested in working on some of these contracts?","viQuote":"Bạn có muốn tham gia xử lý một số hợp đồng này không?"},{"badge":"Câu 30 · Đáp án C","opt":"C","isCorrect":true,"quote":"I have very limited time.","viQuote":"Quỹ thời gian của tôi rất hạn hẹp."}],"evQuotes":["Would you be interested in working on some of these contracts?","I have very limited time."]},{"q":31,"part":2,"group_id":null,"audio":"web_assets/ets2025/audio/E25_T01/track_31.mp3","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_06.webp"],"stem_en":"What type of job are you looking for?","stem_vi":"Bạn đang tìm kiếm loại công việc nào?","options":{"A":{"en":"No, at ten A.M.","vi":"Không, vào lúc 10 giờ sáng."},"B":{"en":"I really like working with computers.","vi":"Tôi rất thích làm việc với máy tính."},"C":{"en":"Just a résumé is needed.","vi":"Chỉ cần một bản sơ yếu lý lịch thôi."}},"ans":"B","explanation":"Đáp án đúng: (B) Tôi rất thích làm việc với máy tính — nêu rõ lĩnh vực/tính chất công việc mong muốn (liên quan đến máy tính) để trả lời cho 'What type of job'.\nDẫn chứng: \"What type of job are you looking for?\" — \"I really like working with computers.\" (Bạn đang tìm loại công việc gì? — Tôi thích làm việc với máy tính).\nPhân tích bẫy:\n- (A) Bẫy Yes/No và sai từ để hỏi: Mở đầu bằng 'No' cho câu hỏi 'What' và kèm mốc giờ '10 A.M.' (hợp với 'When/What time').\n- (C) Lạc trọng tâm câu hỏi: 'Just a résumé is needed' trả lời cho câu hỏi về hồ sơ ứng tuyển ('What do I need to submit?'), không nêu loại công việc.","lines":[{"speaker":"Q","en":"What type of job are you looking for?","vi":"Bạn đang tìm kiếm loại công việc nào?","units":[{"en":"What type of job are you looking for?","vi":"Bạn đang tìm kiếm loại công việc nào?"}]},{"speaker":"(A)","en":"No, at ten A.M.","vi":"Không, vào lúc 10 giờ sáng.","units":[{"en":"No, at ten A.M.","vi":"Không, vào lúc 10 giờ sáng."}]},{"speaker":"(B)","en":"I really like working with computers.","vi":"Tôi rất thích làm việc với máy tính.","units":[{"en":"I really like working with computers.","vi":"Tôi rất thích làm việc với máy tính."}]},{"speaker":"(C)","en":"Just a résumé is needed.","vi":"Chỉ cần một bản sơ yếu lý lịch thôi.","units":[{"en":"Just a résumé is needed.","vi":"Chỉ cần một bản sơ yếu lý lịch thôi."}]}],"vocab":[{"word":"look for","pos":"phr. v","ipa":"/lʊk ˈfɔːr/","meaning":"tìm kiếm"},{"word":"type of job","pos":"phr","ipa":"/ˈtaɪp ʌv dʒɑːb/","meaning":"loại công việc, lĩnh vực nghề nghiệp"},{"word":"résumé","pos":"n","ipa":"/ˈrezəmeɪ/","meaning":"sơ yếu lý lịch, hồ sơ xin việc"}],"isScanBacked":false,"grammarType":"Part 2 — Câu hỏi What / Which (Hỏi thông tin & Lựa chọn cụ thể)","formula":"CÔNG THỨC PART 2 (PART 2 THUỘC LÒNG — Câu hỏi What type of job): Khi nghe 'What type of job are you looking for?', chọn đáp án nêu lĩnh vực hoặc sở thích nghề nghiệp ('working with computers'); loại câu Yes/No và câu hỏi thủ tục ứng tuyển.","optionAnalysis":{"A":"Bẫy Yes/No kết hợp sai từ để hỏi: vừa dùng 'No' cho câu hỏi What vừa đưa ra giờ giấc như câu hỏi When.","B":"Đáp án chuẩn xác: chỉ rõ lĩnh vực công việc yêu thích là làm việc với máy tính.","C":"Lạc nội dung hỏi: trả lời giấy tờ cần nộp (sơ yếu lý lịch) thay vì loại công việc đang tìm kiếm."},"evDocIdx":0,"evTargets":[{"badge":"Câu 31 · Câu hỏi","opt":"B","isCorrect":false,"quote":"What type of job are you looking for?","viQuote":"Bạn đang tìm kiếm loại công việc nào?"},{"badge":"Câu 31 · Đáp án B","opt":"B","isCorrect":true,"quote":"I really like working with computers.","viQuote":"Tôi rất thích làm việc với máy tính."}],"evQuotes":["What type of job are you looking for?","I really like working with computers."]},{"q":32,"part":3,"group_id":"E25_T01_G32_34","audio":"web_assets/ets2025/audio/E25_T01/track_32.mp3","graphicImg":null,"transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_07.webp"],"stem_en":"What event does the woman mention?","stem_vi":"Người phụ nữ đề cập đến sự kiện nào?","options":{"A":{"en":"A job fair","vi":"Một hội chợ việc làm"},"B":{"en":"A cooking class","vi":"Một lớp học nấu ăn"},"C":{"en":"A fund-raiser","vi":"Một sự kiện gây quỹ"},"D":{"en":"A company picnic","vi":"Một buổi dã ngoại của công ty"}},"ans":"D","explanation":"Đáp án đúng: (D) Một buổi dã ngoại của công ty — Ngay ở câu mở đầu, người phụ nữ cảm ơn Jingdao vì đã tổ chức buổi dã ngoại thường niên của công ty.\nDẫn chứng: \"Thank you so much for organizing the annual company picnic, Jingdao.\" (Cảm ơn anh rất nhiều vì đã tổ chức buổi dã ngoại thường niên của công ty — khớp trực tiếp với \"A company picnic\").\nPhân tích bẫy:\n- (A) \"A job fair\" (hội chợ việc làm) không hề xuất hiện; hai người đang trò chuyện với tư cách đồng nghiệp cùng công ty sau một buổi dã ngoại.\n- (B) \"A cooking class\" (lớp học nấu ăn) là bẫy suy diễn từ chi tiết nhắc đến món bánh nướng nhân đào và video hướng dẫn làm bánh, không phải sự kiện chính được cảm ơn.\n- (C) \"A fund-raiser\" (sự kiện gây quỹ) hoàn toàn sai bối cảnh; sự kiện được nhắc là hoạt động tri ân nhân viên sau một năm làm việc chăm chỉ (\"working so hard this year\").","lines":[{"speaker":"W-Am","en":"Thank you so much for organizing the annual company picnic, Jingdao. Everybody seemed to enjoy it.","vi":"Cảm ơn anh rất nhiều vì đã tổ chức buổi dã ngoại thường niên của công ty nhé, Jingdao. Có vẻ như mọi người đều rất thích.","units":[{"en":"Thank you so much for organizing the annual company picnic, Jingdao.","vi":"Cảm ơn anh rất nhiều vì đã tổ chức buổi dã ngoại thường niên của công ty nhé, Jingdao."},{"en":"Everybody seemed to enjoy it.","vi":"Có vẻ như mọi người đều rất thích."}]},{"speaker":"M-Au","en":"Well, we deserved it after working so hard this year.","vi":"À, chúng ta xứng đáng được như vậy sau một năm làm việc chăm chỉ mà.","units":[{"en":"Well, we deserved it after working so hard this year.","vi":"À, chúng ta xứng đáng được như vậy sau một năm làm việc chăm chỉ mà."}]},{"speaker":"W-Am","en":"I agree. The food was great, by the way. Especially the peach pie you made. Would you mind sharing the recipe? It was delicious.","vi":"Tôi đồng ý. Nhân tiện thì đồ ăn hôm đó rất tuyệt. Đặc biệt là món bánh nướng nhân đào anh làm. Anh có phiền chia sẻ công thức không? Món đó thật sự rất ngon.","units":[{"en":"I agree.","vi":"Tôi đồng ý."},{"en":"The food was great, by the way.","vi":"Nhân tiện thì đồ ăn hôm đó rất tuyệt."},{"en":"Especially the peach pie you made.","vi":"Đặc biệt là món bánh nướng nhân đào anh làm."},{"en":"Would you mind sharing the recipe?","vi":"Anh có phiền chia sẻ công thức không?"},{"en":"It was delicious.","vi":"Món đó thật sự rất ngon."}]},{"speaker":"M-Au","en":"I found the recipe online. I'll send you a link to the Web page. There's a really helpful video that walks you through all the steps. I recommend you watch it first.","vi":"Tôi tìm thấy công thức đó trên mạng. Tôi sẽ gửi cho chị đường dẫn đến trang web đó. Trên đó có một video rất hữu ích hướng dẫn chi tiết từng bước thực hiện. Tôi khuyên chị nên xem video đó trước.","units":[{"en":"I found the recipe online.","vi":"Tôi tìm thấy công thức đó trên mạng."},{"en":"I'll send you a link to the Web page.","vi":"Tôi sẽ gửi cho chị đường dẫn đến trang web đó."},{"en":"There's a really helpful video that walks you through all the steps.","vi":"Trên đó có một video rất hữu ích hướng dẫn chi tiết từng bước thực hiện."},{"en":"I recommend you watch it first.","vi":"Tôi khuyên chị nên xem video đó trước."}]},{"speaker":"W-Am","en":"All right, thanks.","vi":"Được rồi, cảm ơn anh nhé.","units":[{"en":"All right, thanks.","vi":"Được rồi, cảm ơn anh nhé."}]}],"vocab":[{"word":"annual","pos":"adj","ipa":"/ˈænjuəl/","meaning":"thường niên, hằng năm"},{"word":"organize","pos":"v","ipa":"/ˈɔːrɡənaɪz/","meaning":"tổ chức"},{"word":"fund-raiser","pos":"n","ipa":"/ˈfʌndˌreɪzər/","meaning":"sự kiện gây quỹ"},{"word":"job fair","pos":"n","ipa":"/dʒɑːb fer/","meaning":"hội chợ việc làm"}],"isScanBacked":false,"grammarType":"Part 3 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 3 (Chi tiết mở đầu hội thoại — Lời cảm ơn): Nghe kỹ câu mở đầu chứa cụm \"Thank you for\" để xác định sự kiện vừa diễn ra (\"the annual company picnic\" → \"A company picnic\").","optionAnalysis":{"A":"Sai bối cảnh sự kiện: Không có hội chợ tuyển dụng nào được nhắc tới; hai người là đồng nghiệp nói về buổi dã ngoại thường niên của công ty.","B":"Bẫy liên tưởng từ vựng: Hội thoại có nhắc tới công thức bánh đào và video hướng dẫn từng bước, dễ khiến người nghe nhầm sang lớp học nấu ăn.","C":"Sai mục đích sự kiện: Cuộc hội thoại nói về buổi dã ngoại tự thưởng sau một năm làm việc chăm chỉ, không phải hoạt động gây quỹ.","D":"Chính xác: Người phụ nữ nói rõ \"Thank you so much for organizing the annual company picnic\", khớp hoàn toàn với \"A company picnic\"."},"evDocIdx":0,"evTargets":[{"badge":"Câu 32 · Đáp án D","opt":"D","isCorrect":true,"quote":"Thank you so much for organizing the annual company picnic, Jingdao.","viQuote":"Cảm ơn anh rất nhiều vì đã tổ chức buổi dã ngoại thường niên của công ty nhé, Jingdao."}],"evQuotes":["Thank you so much for organizing the annual company picnic, Jingdao."]},{"q":33,"part":3,"group_id":"E25_T01_G32_34","audio":"web_assets/ets2025/audio/E25_T01/track_32.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the woman ask for?","stem_vi":"Người phụ nữ hỏi xin thứ gì?","options":{"A":{"en":"A guest list","vi":"Một danh sách khách mời"},"B":{"en":"A dessert recipe","vi":"Một công thức làm món tráng miệng"},"C":{"en":"A business card","vi":"Một tấm danh thiếp"},"D":{"en":"A promotional code","vi":"Một mã khuyến mãi"}},"ans":"B","explanation":"Đáp án đúng: (B) Một công thức làm món tráng miệng — Người phụ nữ khen món bánh nướng nhân đào (peach pie) của Jingdao rất ngon và xin công thức làm món bánh này.\nDẫn chứng: \"Especially the peach pie you made. Would you mind sharing the recipe?\" (Đặc biệt là món bánh nướng nhân đào anh làm. Anh có phiền chia sẻ công thức không? — \"peach pie\" là món tráng miệng, được paraphrase thành \"A dessert recipe\").\nPhân tích bẫy:\n- (A) \"A guest list\" (danh sách khách mời) sai vì sự kiện dã ngoại đã diễn ra xong và người phụ nữ không hỏi thông tin khách tham dự.\n- (C) \"A business card\" (danh thiếp) không hợp lý vì hai người đã quen biết và làm cùng công ty với nhau.\n- (D) \"A promotional code\" (mã khuyến mãi) không xuất hiện; người đàn ông chỉ hứa gửi đường dẫn trang web (\"a link to the Web page\") chứ không phải mã giảm giá.","lines":[{"speaker":"W-Am","en":"Thank you so much for organizing the annual company picnic, Jingdao. Everybody seemed to enjoy it.","vi":"Cảm ơn anh rất nhiều vì đã tổ chức buổi dã ngoại thường niên của công ty nhé, Jingdao. Có vẻ như mọi người đều rất thích.","units":[{"en":"Thank you so much for organizing the annual company picnic, Jingdao.","vi":"Cảm ơn anh rất nhiều vì đã tổ chức buổi dã ngoại thường niên của công ty nhé, Jingdao."},{"en":"Everybody seemed to enjoy it.","vi":"Có vẻ như mọi người đều rất thích."}]},{"speaker":"M-Au","en":"Well, we deserved it after working so hard this year.","vi":"À, chúng ta xứng đáng được như vậy sau một năm làm việc chăm chỉ mà.","units":[{"en":"Well, we deserved it after working so hard this year.","vi":"À, chúng ta xứng đáng được như vậy sau một năm làm việc chăm chỉ mà."}]},{"speaker":"W-Am","en":"I agree. The food was great, by the way. Especially the peach pie you made. Would you mind sharing the recipe? It was delicious.","vi":"Tôi đồng ý. Nhân tiện thì đồ ăn hôm đó rất tuyệt. Đặc biệt là món bánh nướng nhân đào anh làm. Anh có phiền chia sẻ công thức không? Món đó thật sự rất ngon.","units":[{"en":"I agree.","vi":"Tôi đồng ý."},{"en":"The food was great, by the way.","vi":"Nhân tiện thì đồ ăn hôm đó rất tuyệt."},{"en":"Especially the peach pie you made.","vi":"Đặc biệt là món bánh nướng nhân đào anh làm."},{"en":"Would you mind sharing the recipe?","vi":"Anh có phiền chia sẻ công thức không?"},{"en":"It was delicious.","vi":"Món đó thật sự rất ngon."}]},{"speaker":"M-Au","en":"I found the recipe online. I'll send you a link to the Web page. There's a really helpful video that walks you through all the steps. I recommend you watch it first.","vi":"Tôi tìm thấy công thức đó trên mạng. Tôi sẽ gửi cho chị đường dẫn đến trang web đó. Trên đó có một video rất hữu ích hướng dẫn chi tiết từng bước thực hiện. Tôi khuyên chị nên xem video đó trước.","units":[{"en":"I found the recipe online.","vi":"Tôi tìm thấy công thức đó trên mạng."},{"en":"I'll send you a link to the Web page.","vi":"Tôi sẽ gửi cho chị đường dẫn đến trang web đó."},{"en":"There's a really helpful video that walks you through all the steps.","vi":"Trên đó có một video rất hữu ích hướng dẫn chi tiết từng bước thực hiện."},{"en":"I recommend you watch it first.","vi":"Tôi khuyên chị nên xem video đó trước."}]},{"speaker":"W-Am","en":"All right, thanks.","vi":"Được rồi, cảm ơn anh nhé.","units":[{"en":"All right, thanks.","vi":"Được rồi, cảm ơn anh nhé."}]}],"vocab":[{"word":"dessert","pos":"n","ipa":"/dɪˈzɜːrt/","meaning":"món tráng miệng"},{"word":"recipe","pos":"n","ipa":"/ˈresəpi/","meaning":"công thức nấu ăn"},{"word":"share","pos":"v","ipa":"/ʃer/","meaning":"chia sẻ"},{"word":"delicious","pos":"adj","ipa":"/dɪˈlɪʃəs/","meaning":"thơm ngon"}],"isScanBacked":false,"grammarType":"Part 3 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 3 (Câu hỏi yêu cầu/xin xỏ — Would you mind + V-ing): Theo dõi từ khóa \"peach pie\" kết hợp cấu trúc đề nghị \"Would you mind sharing the recipe?\" → Paraphrase \"peach pie recipe\" thành \"dessert recipe\".","optionAnalysis":{"A":"Không có trong hội thoại: Buổi dã ngoại đã kết thúc tốt đẹp (\"Everybody seemed to enjoy it\") và không ai nhắc đến danh sách khách mời.","B":"Chính xác: Người phụ nữ hỏi \"Would you mind sharing the recipe?\" ngay sau khi khen món bánh đào (\"peach pie\"), tức là công thức món tráng miệng.","C":"Sai quan hệ giao tiếp: Hai người là đồng nghiệp quen biết tên nhau (\"Jingdao\"), không có tình huống trao đổi hay xin danh thiếp.","D":"Bẫy ngữ cảnh mua sắm/trực tuyến: Người đàn ông nhắc sẽ gửi \"a link to the Web page\" để xem công thức, hoàn toàn không phải mã khuyến mãi."},"evDocIdx":0,"evTargets":[{"badge":"Câu 33 · Đáp án B","opt":"B","isCorrect":true,"quote":"Especially the peach pie you made.","viQuote":"Đặc biệt là món bánh nướng nhân đào anh làm."},{"badge":"Câu 33 · Đáp án B","opt":"B","isCorrect":true,"quote":"Would you mind sharing the recipe?","viQuote":"Anh có phiền chia sẻ công thức không?"}],"evQuotes":["Especially the peach pie you made.","Would you mind sharing the recipe?"]},{"q":34,"part":3,"group_id":"E25_T01_G32_34","audio":"web_assets/ets2025/audio/E25_T01/track_32.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the man recommend doing?","stem_vi":"Người đàn ông khuyên nên làm gì?","options":{"A":{"en":"Returning some merchandise","vi":"Trả lại một số hàng hóa"},"B":{"en":"Watching a video","vi":"Xem một đoạn video"},"C":{"en":"Creating an account","vi":"Tạo một tài khoản"},"D":{"en":"Reading a review","vi":"Đọc một bài đánh giá"}},"ans":"B","explanation":"Đáp án đúng: (B) Xem một đoạn video — Người đàn ông giới thiệu trang web có video hướng dẫn chi tiết từng bước và khuyên người phụ nữ nên xem video đó trước.\nDẫn chứng: \"There's a really helpful video that walks you through all the steps. I recommend you watch it first.\" (Có một video rất hữu ích hướng dẫn từng bước. Tôi khuyên chị nên xem nó trước — \"watch it\" tương ứng với \"Watching a video\").\nPhân tích bẫy:\n- (A) \"Returning some merchandise\" (trả lại hàng hóa) sai hoàn toàn về chủ đề vì hội thoại không nói về mua bán hay đổi trả sản phẩm.\n- (C) \"Creating an account\" (tạo tài khoản) là bẫy suy diễn từ cụm \"found the recipe online\" / \"Web page\"; người đàn ông không yêu cầu đăng ký tài khoản mới xem được.\n- (D) \"Reading a review\" (đọc bài đánh giá) bẫy từ khóa liên quan đến trang web/công thức, nhưng anh ấy khuyên xem video hướng dẫn chứ không phải đọc nhận xét.","lines":[{"speaker":"W-Am","en":"Thank you so much for organizing the annual company picnic, Jingdao. Everybody seemed to enjoy it.","vi":"Cảm ơn anh rất nhiều vì đã tổ chức buổi dã ngoại thường niên của công ty nhé, Jingdao. Có vẻ như mọi người đều rất thích.","units":[{"en":"Thank you so much for organizing the annual company picnic, Jingdao.","vi":"Cảm ơn anh rất nhiều vì đã tổ chức buổi dã ngoại thường niên của công ty nhé, Jingdao."},{"en":"Everybody seemed to enjoy it.","vi":"Có vẻ như mọi người đều rất thích."}]},{"speaker":"M-Au","en":"Well, we deserved it after working so hard this year.","vi":"À, chúng ta xứng đáng được như vậy sau một năm làm việc chăm chỉ mà.","units":[{"en":"Well, we deserved it after working so hard this year.","vi":"À, chúng ta xứng đáng được như vậy sau một năm làm việc chăm chỉ mà."}]},{"speaker":"W-Am","en":"I agree. The food was great, by the way. Especially the peach pie you made. Would you mind sharing the recipe? It was delicious.","vi":"Tôi đồng ý. Nhân tiện thì đồ ăn hôm đó rất tuyệt. Đặc biệt là món bánh nướng nhân đào anh làm. Anh có phiền chia sẻ công thức không? Món đó thật sự rất ngon.","units":[{"en":"I agree.","vi":"Tôi đồng ý."},{"en":"The food was great, by the way.","vi":"Nhân tiện thì đồ ăn hôm đó rất tuyệt."},{"en":"Especially the peach pie you made.","vi":"Đặc biệt là món bánh nướng nhân đào anh làm."},{"en":"Would you mind sharing the recipe?","vi":"Anh có phiền chia sẻ công thức không?"},{"en":"It was delicious.","vi":"Món đó thật sự rất ngon."}]},{"speaker":"M-Au","en":"I found the recipe online. I'll send you a link to the Web page. There's a really helpful video that walks you through all the steps. I recommend you watch it first.","vi":"Tôi tìm thấy công thức đó trên mạng. Tôi sẽ gửi cho chị đường dẫn đến trang web đó. Trên đó có một video rất hữu ích hướng dẫn chi tiết từng bước thực hiện. Tôi khuyên chị nên xem video đó trước.","units":[{"en":"I found the recipe online.","vi":"Tôi tìm thấy công thức đó trên mạng."},{"en":"I'll send you a link to the Web page.","vi":"Tôi sẽ gửi cho chị đường dẫn đến trang web đó."},{"en":"There's a really helpful video that walks you through all the steps.","vi":"Trên đó có một video rất hữu ích hướng dẫn chi tiết từng bước thực hiện."},{"en":"I recommend you watch it first.","vi":"Tôi khuyên chị nên xem video đó trước."}]},{"speaker":"W-Am","en":"All right, thanks.","vi":"Được rồi, cảm ơn anh nhé.","units":[{"en":"All right, thanks.","vi":"Được rồi, cảm ơn anh nhé."}]}],"vocab":[{"word":"recommend","pos":"v","ipa":"/ˌrekəˈmend/","meaning":"khuyên, đề xuất"},{"word":"walk through","pos":"phr. v","ipa":"/wɔːk θruː/","meaning":"hướng dẫn từng bước"},{"word":"merchandise","pos":"n","ipa":"/ˈmɜːrtʃəndaɪs/","meaning":"hàng hóa"}],"isScanBacked":false,"grammarType":"Part 3 — Hành động tiếp theo & Đề xuất (Next Step & Offer/Request)","formula":"CÔNG THỨC PART 3 (Bắt tín hiệu gợi ý \"I recommend\"): Khi câu hỏi có động từ \"recommend\", tập trung vào lời khuyên ở lượt nói cuối của nhân vật (\"I recommend you watch it first\" với \"it\" = \"a really helpful video\").","optionAnalysis":{"A":"Sai chủ đề hội thoại: Không có giao dịch mua hàng hay lỗi sản phẩm nào để phải trả lại hàng hóa trong đoạn đối thoại này.","B":"Chính xác: Người đàn ông nói \"There's a really helpful video\" và khuyên \"I recommend you watch it first\", khớp trực tiếp với \"Watching a video\".","C":"Bẫy suy diễn web: Dù công thức nằm trên \"Web page\", người đàn ông chỉ bảo sẽ gửi đường link chứ không hề khuyên tạo tài khoản.","D":"Bẫy thay thế hành động trên web: Anh ấy khuyên xem video hướng dẫn từng bước (\"walks you through all the steps\"), không phải đọc bài đánh giá."},"evDocIdx":0,"evTargets":[{"badge":"Câu 34 · Đáp án B","opt":"B","isCorrect":true,"quote":"There's a really helpful video that walks you through all the steps.","viQuote":"Trên đó có một video rất hữu ích hướng dẫn chi tiết từng bước thực hiện."},{"badge":"Câu 34 · Đáp án B","opt":"B","isCorrect":true,"quote":"I recommend you watch it first.","viQuote":"Tôi khuyên chị nên xem video đó trước."}],"evQuotes":["There's a really helpful video that walks you through all the steps.","I recommend you watch it first."]},{"q":35,"part":3,"group_id":"E25_T01_G35_37","audio":"web_assets/ets2025/audio/E25_T01/track_33.mp3","graphicImg":null,"transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_07.webp","web_assets/ets2025/tr/E25_T01_tr_08.webp"],"stem_en":"What department do the speakers most likely work in?","stem_vi":"Những người nói có khả năng làm việc ở phòng ban nào nhất?","options":{"A":{"en":"Accounting","vi":"Phòng Kế toán"},"B":{"en":"Research and development","vi":"Phòng Nghiên cứu và Phát triển"},"C":{"en":"Maintenance","vi":"Phòng Bảo trì"},"D":{"en":"Marketing","vi":"Phòng Tiếp thị"}},"ans":"A","explanation":"Đáp án đúng: (A) Phòng Kế toán — Hai người nói đang tính toán báo cáo chi phí tháng và kiểm tra chứng từ hoàn trả công tác phí cho toàn công ty.\nDẫn chứng: \"I'd like to finish calculating the company's expense reports for the month. Have you finished reviewing the travel reimbursement forms from all the departments?\" (Tôi muốn tính xong báo cáo chi phí tháng của công ty. Chị đã xem xét xong biểu mẫu hoàn trả công tác phí từ các phòng ban chưa? — nghiệp vụ đặc trưng của phòng Accounting).\nPhân tích bẫy:\n- (B) \"Research and development\" (Nghiên cứu và Phát triển) sai nghiệp vụ vì không có nội dung nào về phát triển sản phẩm hay thử nghiệm kỹ thuật.\n- (C) \"Maintenance\" (Bảo trì) không liên quan đến việc xử lý hóa đơn khách sạn và báo cáo chi phí công tác.\n- (D) \"Marketing\" (Tiếp thị) là bẫy liên tưởng gần với \"sales representatives\" (nhân viên kinh doanh Moritz Ziegler), nhưng Moritz là người nộp hóa đơn chứ không phải bộ phận của hai người nói.","lines":[{"speaker":"M-Cn","en":"I'd like to finish calculating the company's expense reports for the month. Have you finished reviewing the travel reimbursement forms from all the departments?","vi":"Tôi muốn hoàn tất việc tính toán các báo cáo chi phí trong tháng của công ty. Chị đã xem xét xong các biểu mẫu hoàn trả công tác phí từ tất cả các phòng ban chưa?","units":[{"en":"I'd like to finish calculating the company's expense reports for the month.","vi":"Tôi muốn hoàn tất việc tính toán các báo cáo chi phí trong tháng của công ty."},{"en":"Have you finished reviewing the travel reimbursement forms from all the departments?","vi":"Chị đã xem xét xong các biểu mẫu hoàn trả công tác phí từ tất cả các phòng ban chưa?"}]},{"speaker":"W-Br","en":"I'm almost done, but I have a question about a hotel receipt from one of our employees.","vi":"Tôi sắp làm xong rồi, nhưng tôi có một thắc mắc về hóa đơn khách sạn của một nhân viên công ty mình.","units":[{"en":"I'm almost done, but I have a question about a hotel receipt from one of our employees.","vi":"Tôi sắp làm xong rồi, nhưng tôi có một thắc mắc về hóa đơn khách sạn của một nhân viên công ty mình."}]},{"speaker":"M-Cn","en":"What's the problem?","vi":"Có vấn đề gì vậy?","units":[{"en":"What's the problem?","vi":"Có vấn đề gì vậy?"}]},{"speaker":"W-Br","en":"Well, our policy is for employees to stay at a hotel that's on our list of approved accommodations. This one isn't on the list.","vi":"À, chính sách của công ty quy định nhân viên phải lưu trú tại khách sạn nằm trong danh sách cơ sở lưu trú được phê duyệt. Khách sạn này không có trong danh sách.","units":[{"en":"Well, our policy is for employees to stay at a hotel that's on our list of approved accommodations.","vi":"À, chính sách của công ty quy định nhân viên phải lưu trú tại khách sạn nằm trong danh sách cơ sở lưu trú được phê duyệt."},{"en":"This one isn't on the list.","vi":"Khách sạn này không có trong danh sách."}]},{"speaker":"M-Cn","en":"Who submitted the receipt?","vi":"Ai là người nộp hóa đơn đó?","units":[{"en":"Who submitted the receipt?","vi":"Ai là người nộp hóa đơn đó?"}]},{"speaker":"W-Br","en":"Moritz Ziegler, one of our sales representatives.","vi":"Moritz Ziegler, một trong các đại diện kinh doanh của chúng ta.","units":[{"en":"Moritz Ziegler, one of our sales representatives.","vi":"Moritz Ziegler, một trong các đại diện kinh doanh của chúng ta."}]},{"speaker":"M-Cn","en":"Hmm. He's a new employee and may have forgotten the policy. As a supervisor, I can approve the expense this one time.","vi":"Ừm. Anh ấy là nhân viên mới nên có thể đã quên mất chính sách này. Với tư cách là người giám sát, tôi có thể phê duyệt khoản chi phí này một lần duy nhất.","units":[{"en":"Hmm.","vi":"Ừm."},{"en":"He's a new employee and may have forgotten the policy.","vi":"Anh ấy là nhân viên mới nên có thể đã quên mất chính sách này."},{"en":"As a supervisor, I can approve the expense this one time.","vi":"Với tư cách là người giám sát, tôi có thể phê duyệt khoản chi phí này một lần duy nhất."}]}],"vocab":[{"word":"accounting","pos":"n","ipa":"/əˈkaʊntɪŋ/","meaning":"bộ phận kế toán"},{"word":"calculate","pos":"v","ipa":"/ˈkælkjəleɪt/","meaning":"tính toán"},{"word":"expense report","pos":"n","ipa":"/ɪkˈspens rɪˈpɔːrt/","meaning":"báo cáo chi phí"},{"word":"reimbursement","pos":"n","ipa":"/ˌriːɪmˈbɜːrsmənt/","meaning":"khoản hoàn trả chi phí"}],"isScanBacked":false,"grammarType":"Part 3 — Ngữ cảnh, Địa điểm & Danh tính người nói (Setting & Role)","formula":"CÔNG THỨC PART 3 (Suy luận phòng ban từ chuỗi động từ nghiệp vụ): Các cụm \"calculating expense reports\", \"reviewing travel reimbursement forms\", \"hotel receipt\", \"approve the expense\" là dấu hiệu đặc trưng của phòng Kế toán (Accounting).","optionAnalysis":{"A":"Chính xác: Việc tính toán \"expense reports\" và duyệt \"travel reimbursement forms\" từ tất cả phòng ban là nhiệm vụ cốt lõi của phòng Kế toán.","B":"Sai chuyên môn: Hội thoại hoàn toàn xoay quanh chứng từ tài chính và hóa đơn khách sạn, không liên quan đến nghiên cứu hay phát triển sản phẩm.","C":"Không có dữ kiện: Không hề xuất hiện thiết bị hỏng hóc hay công việc sửa chữa nào thuộc bộ phận Bảo trì.","D":"Bẫy đánh lạc hướng từ chức danh: Hội thoại nhắc tới \"sales representatives\" (nhân viên kinh doanh nộp hóa đơn), nhưng hai người nói xử lý chi phí chung cho mọi phòng ban."},"evDocIdx":0,"evTargets":[{"badge":"Câu 35 · Đáp án A","opt":"A","isCorrect":true,"quote":"I'd like to finish calculating the company's expense reports for the month.","viQuote":"Tôi muốn hoàn tất việc tính toán các báo cáo chi phí trong tháng của công ty."},{"badge":"Câu 35 · Đáp án A","opt":"A","isCorrect":true,"quote":"Have you finished reviewing the travel reimbursement forms from all the departments?","viQuote":"Chị đã xem xét xong các biểu mẫu hoàn trả công tác phí từ tất cả các phòng ban chưa?"}],"evQuotes":["I'd like to finish calculating the company's expense reports for the month.","Have you finished reviewing the travel reimbursement forms from all the departments?"]},{"q":36,"part":3,"group_id":"E25_T01_G35_37","audio":"web_assets/ets2025/audio/E25_T01/track_33.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What problem does the woman mention?","stem_vi":"Người phụ nữ đề cập đến vấn đề gì?","options":{"A":{"en":"A report has not been submitted.","vi":"Một bản báo cáo chưa được nộp."},"B":{"en":"An invoice is not accurate.","vi":"Một hóa đơn không chính xác."},"C":{"en":"A policy has not been followed.","vi":"Một chính sách chưa được tuân thủ."},"D":{"en":"An order has not been delivered.","vi":"Một đơn hàng chưa được giao."}},"ans":"C","explanation":"Đáp án đúng: (C) Một chính sách chưa được tuân thủ — Nhân viên đã ở khách sạn không nằm trong danh sách cơ sở lưu trú được phê duyệt theo quy định của công ty.\nDẫn chứng: \"Well, our policy is for employees to stay at a hotel that's on our list of approved accommodations. This one isn't on the list.\" (Chính sách của công ty yêu cầu nhân viên ở khách sạn trong danh sách được duyệt, nhưng khách sạn này không có trong danh sách — tức chính sách chưa được tuân thủ).\nPhân tích bẫy:\n- (A) \"A report has not been submitted\" (báo cáo chưa được nộp) sai vì hóa đơn và biểu mẫu đã được nộp rồi (\"Who submitted the receipt?\"), chỉ đang chờ kiểm tra duyệt.\n- (B) \"An invoice is not accurate\" (hóa đơn không chính xác) là bẫy gần nghĩa với \"hotel receipt\", nhưng vấn đề không phải sai số tiền trên hóa đơn mà là chọn sai khách sạn ngoài danh sách.\n- (D) \"An order has not been delivered\" (đơn hàng chưa được giao) hoàn toàn không có trong ngữ cảnh xử lý công tác phí.","lines":[{"speaker":"M-Cn","en":"I'd like to finish calculating the company's expense reports for the month. Have you finished reviewing the travel reimbursement forms from all the departments?","vi":"Tôi muốn hoàn tất việc tính toán các báo cáo chi phí trong tháng của công ty. Chị đã xem xét xong các biểu mẫu hoàn trả công tác phí từ tất cả các phòng ban chưa?","units":[{"en":"I'd like to finish calculating the company's expense reports for the month.","vi":"Tôi muốn hoàn tất việc tính toán các báo cáo chi phí trong tháng của công ty."},{"en":"Have you finished reviewing the travel reimbursement forms from all the departments?","vi":"Chị đã xem xét xong các biểu mẫu hoàn trả công tác phí từ tất cả các phòng ban chưa?"}]},{"speaker":"W-Br","en":"I'm almost done, but I have a question about a hotel receipt from one of our employees.","vi":"Tôi sắp làm xong rồi, nhưng tôi có một thắc mắc về hóa đơn khách sạn của một nhân viên công ty mình.","units":[{"en":"I'm almost done, but I have a question about a hotel receipt from one of our employees.","vi":"Tôi sắp làm xong rồi, nhưng tôi có một thắc mắc về hóa đơn khách sạn của một nhân viên công ty mình."}]},{"speaker":"M-Cn","en":"What's the problem?","vi":"Có vấn đề gì vậy?","units":[{"en":"What's the problem?","vi":"Có vấn đề gì vậy?"}]},{"speaker":"W-Br","en":"Well, our policy is for employees to stay at a hotel that's on our list of approved accommodations. This one isn't on the list.","vi":"À, chính sách của công ty quy định nhân viên phải lưu trú tại khách sạn nằm trong danh sách cơ sở lưu trú được phê duyệt. Khách sạn này không có trong danh sách.","units":[{"en":"Well, our policy is for employees to stay at a hotel that's on our list of approved accommodations.","vi":"À, chính sách của công ty quy định nhân viên phải lưu trú tại khách sạn nằm trong danh sách cơ sở lưu trú được phê duyệt."},{"en":"This one isn't on the list.","vi":"Khách sạn này không có trong danh sách."}]},{"speaker":"M-Cn","en":"Who submitted the receipt?","vi":"Ai là người nộp hóa đơn đó?","units":[{"en":"Who submitted the receipt?","vi":"Ai là người nộp hóa đơn đó?"}]},{"speaker":"W-Br","en":"Moritz Ziegler, one of our sales representatives.","vi":"Moritz Ziegler, một trong các đại diện kinh doanh của chúng ta.","units":[{"en":"Moritz Ziegler, one of our sales representatives.","vi":"Moritz Ziegler, một trong các đại diện kinh doanh của chúng ta."}]},{"speaker":"M-Cn","en":"Hmm. He's a new employee and may have forgotten the policy. As a supervisor, I can approve the expense this one time.","vi":"Ừm. Anh ấy là nhân viên mới nên có thể đã quên mất chính sách này. Với tư cách là người giám sát, tôi có thể phê duyệt khoản chi phí này một lần duy nhất.","units":[{"en":"Hmm.","vi":"Ừm."},{"en":"He's a new employee and may have forgotten the policy.","vi":"Anh ấy là nhân viên mới nên có thể đã quên mất chính sách này."},{"en":"As a supervisor, I can approve the expense this one time.","vi":"Với tư cách là người giám sát, tôi có thể phê duyệt khoản chi phí này một lần duy nhất."}]}],"vocab":[{"word":"policy","pos":"n","ipa":"/ˈpɑːləsi/","meaning":"chính sách, quy định"},{"word":"approve","pos":"v","ipa":"/əˈpruːv/","meaning":"phê duyệt, chấp thuận"},{"word":"accommodations","pos":"n","ipa":"/əˌkɑːməˈdeɪʃənz/","meaning":"cơ sở lưu trú, chỗ ở"},{"word":"invoice","pos":"n","ipa":"/ˈɪnvɔɪs/","meaning":"hóa đơn"}],"isScanBacked":false,"grammarType":"Part 3 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 3 (Bắt tín hiệu vấn đề \"What's the problem?\"): Theo sát câu trả lời ngay sau câu hỏi về sự cố; đối chiếu quy định \"our policy is\" với phủ định \"isn't on the list\" → \"A policy has not been followed\".","optionAnalysis":{"A":"Ngược thông tin bài nghe: Hóa đơn đã được nhân viên Moritz Ziegler nộp lên (\"submitted the receipt\"), không phải chưa nộp.","B":"Bẫy chi tiết chứng từ: Người phụ nữ thắc mắc về \"hotel receipt\" do ở ngoài danh sách duyệt, không phải do số liệu trên hóa đơn bị sai.","C":"Chính xác: Nhân viên chọn khách sạn ngoài \"list of approved accommodations\", vi phạm quy định \"our policy is for employees to stay at a hotel that's on our list\".","D":"Sai ngữ cảnh: Hội thoại nói về hoàn trả chi phí lưu trú công tác, không đề cập đến giao nhận hàng hóa hay đơn đặt hàng."},"evDocIdx":0,"evTargets":[{"badge":"Câu 36 · Đáp án C","opt":"C","isCorrect":true,"quote":"Well, our policy is for employees to stay at a hotel that's on our list of approved accommodations.","viQuote":"À, chính sách của công ty quy định nhân viên phải lưu trú tại khách sạn nằm trong danh sách cơ sở lưu trú được phê duyệt."},{"badge":"Câu 36 · Đáp án C","opt":"C","isCorrect":true,"quote":"This one isn't on the list.","viQuote":"Khách sạn này không có trong danh sách."}],"evQuotes":["Well, our policy is for employees to stay at a hotel that's on our list of approved accommodations.","This one isn't on the list."]},{"q":37,"part":3,"group_id":"E25_T01_G35_37","audio":"web_assets/ets2025/audio/E25_T01/track_33.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the man say he will do?","stem_vi":"Người đàn ông nói anh ấy sẽ làm gì?","options":{"A":{"en":"Delete an electronic file","vi":"Xóa một tệp điện tử"},"B":{"en":"Authorize a reimbursement","vi":"Phê duyệt một khoản hoàn trả chi phí"},"C":{"en":"Set up a sales meeting","vi":"Sắp xếp một cuộc họp kinh doanh"},"D":{"en":"Review a spreadsheet","vi":"Xem xét một bảng tính"}},"ans":"B","explanation":"Đáp án đúng: (B) Phê duyệt một khoản hoàn trả chi phí — Với tư cách người giám sát, người đàn ông quyết định du di chấp thuận khoản chi phí khách sạn này cho nhân viên mới.\nDẫn chứng: \"As a supervisor, I can approve the expense this one time.\" (Với tư cách là người giám sát, tôi có thể phê duyệt khoản chi phí này một lần — \"approve the expense\" trong bối cảnh \"travel reimbursement forms\" tương ứng với \"Authorize a reimbursement\").\nPhân tích bẫy:\n- (A) \"Delete an electronic file\" (xóa tệp điện tử) sai hoàn toàn vì anh ấy đồng ý xử lý ngoại lệ chứ không xóa bỏ hồ sơ chi phí.\n- (C) \"Set up a sales meeting\" (sắp xếp cuộc họp kinh doanh) là bẫy bắt từ \"sales representatives\" ở lượt nói trước đó của người phụ nữ.\n- (D) \"Review a spreadsheet\" (xem xét bảng tính) bẫy từ việc anh ấy muốn tính xong \"expense reports\", nhưng việc rà soát biểu mẫu (\"reviewing the travel reimbursement forms\") là phần việc người phụ nữ đang làm, không phải hành động anh ấy hứa ở cuối bài.","lines":[{"speaker":"M-Cn","en":"I'd like to finish calculating the company's expense reports for the month. Have you finished reviewing the travel reimbursement forms from all the departments?","vi":"Tôi muốn hoàn tất việc tính toán các báo cáo chi phí trong tháng của công ty. Chị đã xem xét xong các biểu mẫu hoàn trả công tác phí từ tất cả các phòng ban chưa?","units":[{"en":"I'd like to finish calculating the company's expense reports for the month.","vi":"Tôi muốn hoàn tất việc tính toán các báo cáo chi phí trong tháng của công ty."},{"en":"Have you finished reviewing the travel reimbursement forms from all the departments?","vi":"Chị đã xem xét xong các biểu mẫu hoàn trả công tác phí từ tất cả các phòng ban chưa?"}]},{"speaker":"W-Br","en":"I'm almost done, but I have a question about a hotel receipt from one of our employees.","vi":"Tôi sắp làm xong rồi, nhưng tôi có một thắc mắc về hóa đơn khách sạn của một nhân viên công ty mình.","units":[{"en":"I'm almost done, but I have a question about a hotel receipt from one of our employees.","vi":"Tôi sắp làm xong rồi, nhưng tôi có một thắc mắc về hóa đơn khách sạn của một nhân viên công ty mình."}]},{"speaker":"M-Cn","en":"What's the problem?","vi":"Có vấn đề gì vậy?","units":[{"en":"What's the problem?","vi":"Có vấn đề gì vậy?"}]},{"speaker":"W-Br","en":"Well, our policy is for employees to stay at a hotel that's on our list of approved accommodations. This one isn't on the list.","vi":"À, chính sách của công ty quy định nhân viên phải lưu trú tại khách sạn nằm trong danh sách cơ sở lưu trú được phê duyệt. Khách sạn này không có trong danh sách.","units":[{"en":"Well, our policy is for employees to stay at a hotel that's on our list of approved accommodations.","vi":"À, chính sách của công ty quy định nhân viên phải lưu trú tại khách sạn nằm trong danh sách cơ sở lưu trú được phê duyệt."},{"en":"This one isn't on the list.","vi":"Khách sạn này không có trong danh sách."}]},{"speaker":"M-Cn","en":"Who submitted the receipt?","vi":"Ai là người nộp hóa đơn đó?","units":[{"en":"Who submitted the receipt?","vi":"Ai là người nộp hóa đơn đó?"}]},{"speaker":"W-Br","en":"Moritz Ziegler, one of our sales representatives.","vi":"Moritz Ziegler, một trong các đại diện kinh doanh của chúng ta.","units":[{"en":"Moritz Ziegler, one of our sales representatives.","vi":"Moritz Ziegler, một trong các đại diện kinh doanh của chúng ta."}]},{"speaker":"M-Cn","en":"Hmm. He's a new employee and may have forgotten the policy. As a supervisor, I can approve the expense this one time.","vi":"Ừm. Anh ấy là nhân viên mới nên có thể đã quên mất chính sách này. Với tư cách là người giám sát, tôi có thể phê duyệt khoản chi phí này một lần duy nhất.","units":[{"en":"Hmm.","vi":"Ừm."},{"en":"He's a new employee and may have forgotten the policy.","vi":"Anh ấy là nhân viên mới nên có thể đã quên mất chính sách này."},{"en":"As a supervisor, I can approve the expense this one time.","vi":"Với tư cách là người giám sát, tôi có thể phê duyệt khoản chi phí này một lần duy nhất."}]}],"vocab":[{"word":"authorize","pos":"v","ipa":"/ˈɔːθəraɪz/","meaning":"cho phép, phê duyệt chính thức"},{"word":"supervisor","pos":"n","ipa":"/ˈsuːpərvaɪzər/","meaning":"người giám sát"},{"word":"sales representative","pos":"n","ipa":"/seɪlz ˌreprɪˈzentətɪv/","meaning":"đại diện kinh doanh"},{"word":"spreadsheet","pos":"n","ipa":"/ˈspredʃiːt/","meaning":"bảng tính"}],"isScanBacked":false,"grammarType":"Part 3 — Hành động tiếp theo & Đề xuất (Next Step & Offer/Request)","formula":"CÔNG THỨC PART 3 (Paraphrase cụm động từ cuối bài): Cụm \"As a supervisor, I can approve the expense\" trong ngữ cảnh \"travel reimbursement forms\" được paraphrase trực tiếp thành \"Authorize a reimbursement\" (approve = authorize; expense = reimbursement).","optionAnalysis":{"A":"Sai hành động: Người đàn ông đồng ý phê duyệt khoản chi phí ngoại lệ lần này chứ không hề nhắc đến việc xóa tệp dữ liệu.","B":"Chính xác: \"approve the expense\" (duyệt khoản chi phí từ biểu mẫu \"travel reimbursement\") được diễn đạt lại thành \"Authorize a reimbursement\".","C":"Bẫy lặp/liên tưởng từ: Từ \"sales\" chỉ xuất hiện khi nhắc nghề nghiệp của Moritz (\"sales representatives\"), không có kế hoạch họp kinh doanh.","D":"Bẫy nhầm vai trò hành động: Người phụ nữ là người đang rà soát chứng từ (\"reviewing\"), còn việc người đàn ông nhận làm cuối bài là phê duyệt ngoại lệ."},"evDocIdx":0,"evTargets":[{"badge":"Câu 37 · Đáp án B","opt":"B","isCorrect":true,"quote":"As a supervisor, I can approve the expense this one time.","viQuote":"Với tư cách là người giám sát, tôi có thể phê duyệt khoản chi phí này một lần duy nhất."}],"evQuotes":["As a supervisor, I can approve the expense this one time."]},{"q":38,"part":3,"group_id":"E25_T01_G38_40","audio":"web_assets/ets2025/audio/E25_T01/track_34.mp3","graphicImg":null,"transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_08.webp","web_assets/ets2025/tr/E25_T01_tr_09.webp"],"stem_en":"What industry do the speakers most likely work in?","stem_vi":"Những người nói có khả năng làm việc trong ngành nào nhất?","options":{"A":{"en":"Shipping","vi":"Vận tải hàng hóa"},"B":{"en":"Manufacturing","vi":"Sản xuất"},"C":{"en":"Hospitality","vi":"Dịch vụ nhà hàng - khách sạn"},"D":{"en":"Meteorology","vi":"Khí tượng học"}},"ans":"A","explanation":"Đáp án đúng: (A) Vận tải hàng hóa — Hai người đang nói chuyện trên boong của một con tàu chở hàng đang neo đậu tại cảng chờ lệnh khởi hành.\nDẫn chứng: \"How's everything up here on deck?\" / \"It was an uneventful night, and our cargo ship still hasn't moved yet.\" (Mọi thứ trên boong tàu thế nào rồi? / Tàu chở hàng của chúng ta vẫn chưa di chuyển — \"cargo ship\" thuộc ngành vận tải biển/hàng hóa \"Shipping\").\nPhân tích bẫy:\n- (B) \"Manufacturing\" (Sản xuất) sai vì không có nhà máy, dây chuyền hay hoạt động chế tạo sản phẩm nào.\n- (C) \"Hospitality\" (Nhà hàng - khách sạn) có thể đánh lừa người nghe liên tưởng đến tàu du lịch, nhưng lời thoại nói rõ là \"cargo ship\" (tàu chở hàng), không phải tàu chở khách.\n- (D) \"Meteorology\" (Khí tượng học) là bẫy từ việc hai người nhắc đến \"fog\" (sương mù) và \"weather\" (thời tiết), nhưng họ chỉ là thủy thủ/nhân viên tàu bị ảnh hưởng bởi thời tiết.","lines":[{"speaker":"M-Au","en":"Good morning, Damilola. How's everything up here on deck?","vi":"Chào buổi sáng, Damilola. Mọi thứ trên boong tàu thế nào rồi?","units":[{"en":"Good morning, Damilola.","vi":"Chào buổi sáng, Damilola."},{"en":"How's everything up here on deck?","vi":"Mọi thứ trên boong tàu thế nào rồi?"}]},{"speaker":"W-Br","en":"Hi, Pedro. It was an uneventful night, and our cargo ship still hasn't moved yet.","vi":"Chào Pedro. Đêm qua khá yên ắng không có sự cố gì, và tàu chở hàng của chúng ta vẫn chưa di chuyển.","units":[{"en":"Hi, Pedro.","vi":"Chào Pedro."},{"en":"It was an uneventful night, and our cargo ship still hasn't moved yet.","vi":"Đêm qua khá yên ắng không có sự cố gì, và tàu chở hàng của chúng ta vẫn chưa di chuyển."}]},{"speaker":"M-Au","en":"Hmm, I hope the fog over the harbor lifts soon.","vi":"Ừm, tôi hy vọng lớp sương mù trên bến cảng sẽ sớm tan.","units":[{"en":"Hmm, I hope the fog over the harbor lifts soon.","vi":"Ừm, tôi hy vọng lớp sương mù trên bến cảng sẽ sớm tan."}]},{"speaker":"W-Br","en":"Yeah, me too. The ship won't be able to leave until the weather improves.","vi":"Ừ, tôi cũng vậy. Con tàu sẽ không thể rời cảng cho đến khi thời tiết khá hơn.","units":[{"en":"Yeah, me too.","vi":"Ừ, tôi cũng vậy."},{"en":"The ship won't be able to leave until the weather improves.","vi":"Con tàu sẽ không thể rời cảng cho đến khi thời tiết khá hơn."}]},{"speaker":"M-Au","en":"I hope we won't get too far behind schedule. I'll be sure to call the port authority soon for an update on when we'll be cleared to leave.","vi":"Tôi hy vọng chúng ta sẽ không bị trễ lịch trình quá nhiều. Tôi chắc chắn sẽ sớm gọi cho ban quản lý cảng để cập nhật thời điểm chúng ta được cấp phép rời bến.","units":[{"en":"I hope we won't get too far behind schedule.","vi":"Tôi hy vọng chúng ta sẽ không bị trễ lịch trình quá nhiều."},{"en":"I'll be sure to call the port authority soon for an update on when we'll be cleared to leave.","vi":"Tôi chắc chắn sẽ sớm gọi cho ban quản lý cảng để cập nhật thời điểm chúng ta được cấp phép rời bến."}]},{"speaker":"W-Br","en":"Sounds good.","vi":"Nghe hợp lý đấy.","units":[{"en":"Sounds good.","vi":"Nghe hợp lý đấy."}]}],"vocab":[{"word":"deck","pos":"n","ipa":"/dek/","meaning":"boong tàu"},{"word":"cargo ship","pos":"n","ipa":"/ˈkɑːrɡoʊ ʃɪp/","meaning":"tàu chở hàng"},{"word":"uneventful","pos":"adj","ipa":"/ˌʌnɪˈventfəl/","meaning":"yên ắng, không có sự cố"},{"word":"hospitality","pos":"n","ipa":"/ˌhɑːspɪˈtæləti/","meaning":"ngành dịch vụ nhà hàng - khách sạn"}],"isScanBacked":false,"grammarType":"Part 3 — Ngữ cảnh, Địa điểm & Danh tính người nói (Setting & Role)","formula":"CÔNG THỨC PART 3 (Xác định ngành nghề qua cụm từ khóa không gian): Nghe các từ khóa \"on deck\" (trên boong), \"cargo ship\" (tàu chở hàng), \"harbor\" (cảng), \"port authority\" (ban quản lý cảng) → Chốt ngay ngành Vận tải hàng hóa (\"Shipping\").","optionAnalysis":{"A":"Chính xác: Các chi tiết \"on deck\", \"cargo ship\", \"harbor\" và \"port authority\" khẳng định họ làm việc trong ngành vận tải hàng hóa đường biển (Shipping).","B":"Không có dữ kiện: Bối cảnh diễn ra trên boong tàu ngoài cảng, hoàn toàn không liên quan đến hoạt động sản xuất công nghiệp.","C":"Bẫy nhầm loại tàu: Dù ở trên tàu (\"on deck\"), đây là tàu chở hàng (\"cargo ship\") chứ không phải du thuyền hay dịch vụ lưu trú khách sạn.","D":"Bẫy nhắc từ thời tiết: Hai người có nhắc \"fog\" và \"weather improves\", nhưng chỉ là chờ tan sương để tàu chạy chứ không phải làm nghề khí tượng."},"evDocIdx":0,"evTargets":[{"badge":"Câu 38 · Đáp án A","opt":"A","isCorrect":true,"quote":"How's everything up here on deck?","viQuote":"Mọi thứ trên boong tàu thế nào rồi?"},{"badge":"Câu 38 · Đáp án A","opt":"A","isCorrect":true,"quote":"It was an uneventful night, and our cargo ship still hasn't moved yet.","viQuote":"Đêm qua khá yên ắng không có sự cố gì, và tàu chở hàng của chúng ta vẫn chưa di chuyển."}],"evQuotes":["How's everything up here on deck?","It was an uneventful night, and our cargo ship still hasn't moved yet."]},{"q":39,"part":3,"group_id":"E25_T01_G38_40","audio":"web_assets/ets2025/audio/E25_T01/track_34.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What is the reason for a delay?","stem_vi":"Lý do gây ra sự chậm trễ là gì?","options":{"A":{"en":"A schedule was written incorrectly.","vi":"Một lịch trình đã bị ghi sai."},"B":{"en":"Some equipment is not properly set up.","vi":"Một số thiết bị không được lắp đặt đúng cách."},"C":{"en":"Weather conditions are poor.","vi":"Điều kiện thời tiết xấu."},"D":{"en":"Several staff members are absent.","vi":"Một vài nhân viên vắng mặt."}},"ans":"C","explanation":"Đáp án đúng: (C) Điều kiện thời tiết xấu — Cảng đang bị sương mù bao phủ nên con tàu chưa thể rời bến cho đến khi thời tiết cải thiện.\nDẫn chứng: \"Hmm, I hope the fog over the harbor lifts soon.\" / \"The ship won't be able to leave until the weather improves.\" (Hy vọng sương mù trên cảng sớm tan. / Tàu sẽ không thể rời bến cho tới khi thời tiết khá hơn — \"fog\" & \"until weather improves\" = \"Weather conditions are poor\").\nPhân tích bẫy:\n- (A) \"A schedule was written incorrectly\" (lịch trình bị ghi sai) là bẫy lặp từ \"schedule\" trong câu \"behind schedule\" (bị trễ lịch trình), không phải viết sai lịch.\n- (B) \"Some equipment is not properly set up\" (thiết bị lắp chưa đúng) sai vì đêm qua trôi qua yên ả (\"uneventful night\"), không có sự cố kỹ thuật.\n- (D) \"Several staff members are absent\" (một vài nhân viên vắng mặt) không được nhắc tới trong đoạn hội thoại.","lines":[{"speaker":"M-Au","en":"Good morning, Damilola. How's everything up here on deck?","vi":"Chào buổi sáng, Damilola. Mọi thứ trên boong tàu thế nào rồi?","units":[{"en":"Good morning, Damilola.","vi":"Chào buổi sáng, Damilola."},{"en":"How's everything up here on deck?","vi":"Mọi thứ trên boong tàu thế nào rồi?"}]},{"speaker":"W-Br","en":"Hi, Pedro. It was an uneventful night, and our cargo ship still hasn't moved yet.","vi":"Chào Pedro. Đêm qua khá yên ắng không có sự cố gì, và tàu chở hàng của chúng ta vẫn chưa di chuyển.","units":[{"en":"Hi, Pedro.","vi":"Chào Pedro."},{"en":"It was an uneventful night, and our cargo ship still hasn't moved yet.","vi":"Đêm qua khá yên ắng không có sự cố gì, và tàu chở hàng của chúng ta vẫn chưa di chuyển."}]},{"speaker":"M-Au","en":"Hmm, I hope the fog over the harbor lifts soon.","vi":"Ừm, tôi hy vọng lớp sương mù trên bến cảng sẽ sớm tan.","units":[{"en":"Hmm, I hope the fog over the harbor lifts soon.","vi":"Ừm, tôi hy vọng lớp sương mù trên bến cảng sẽ sớm tan."}]},{"speaker":"W-Br","en":"Yeah, me too. The ship won't be able to leave until the weather improves.","vi":"Ừ, tôi cũng vậy. Con tàu sẽ không thể rời cảng cho đến khi thời tiết khá hơn.","units":[{"en":"Yeah, me too.","vi":"Ừ, tôi cũng vậy."},{"en":"The ship won't be able to leave until the weather improves.","vi":"Con tàu sẽ không thể rời cảng cho đến khi thời tiết khá hơn."}]},{"speaker":"M-Au","en":"I hope we won't get too far behind schedule. I'll be sure to call the port authority soon for an update on when we'll be cleared to leave.","vi":"Tôi hy vọng chúng ta sẽ không bị trễ lịch trình quá nhiều. Tôi chắc chắn sẽ sớm gọi cho ban quản lý cảng để cập nhật thời điểm chúng ta được cấp phép rời bến.","units":[{"en":"I hope we won't get too far behind schedule.","vi":"Tôi hy vọng chúng ta sẽ không bị trễ lịch trình quá nhiều."},{"en":"I'll be sure to call the port authority soon for an update on when we'll be cleared to leave.","vi":"Tôi chắc chắn sẽ sớm gọi cho ban quản lý cảng để cập nhật thời điểm chúng ta được cấp phép rời bến."}]},{"speaker":"W-Br","en":"Sounds good.","vi":"Nghe hợp lý đấy.","units":[{"en":"Sounds good.","vi":"Nghe hợp lý đấy."}]}],"vocab":[{"word":"fog","pos":"n","ipa":"/fɔːɡ/","meaning":"sương mù"},{"word":"harbor","pos":"n","ipa":"/ˈhɑːrbər/","meaning":"bến cảng"},{"word":"lift","pos":"v","ipa":"/lɪft/","meaning":"tan đi (sương mù, mây)"},{"word":"delay","pos":"n","ipa":"/dɪˈleɪ/","meaning":"sự chậm trễ"}],"isScanBacked":false,"grammarType":"Part 3 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 3 (Nguyên nhân trì hoãn — until / fog): Khi câu hỏi hỏi lý do trễ, chú ý mệnh đề nguyên nhân/điều kiện thời tiết (\"fog over the harbor\", \"until the weather improves\") → Paraphrase thành \"Weather conditions are poor\".","optionAnalysis":{"A":"Bẫy lặp từ \"schedule\": Người đàn ông lo bị trễ lịch trình (\"behind schedule\"), chứ không phải lịch trình bị ghi chép sai sót.","B":"Không đúng thực tế bài nghe: Người phụ nữ nói đêm qua bình yên vô sự (\"uneventful night\"), không có lỗi thiết bị nào.","C":"Chính xác: Sương mù dày ở cảng (\"fog over the harbor\") khiến tàu không thể đi \"until the weather improves\", tức thời tiết xấu.","D":"Thông tin bịa đặt: Hội thoại không nhắc đến tình trạng thiếu hụt nhân sự hay có thủy thủ vắng mặt."},"evDocIdx":0,"evTargets":[{"badge":"Câu 39 · Đáp án C","opt":"C","isCorrect":true,"quote":"Hmm, I hope the fog over the harbor lifts soon.","viQuote":"Ừm, tôi hy vọng lớp sương mù trên bến cảng sẽ sớm tan."},{"badge":"Câu 39 · Đáp án C","opt":"C","isCorrect":true,"quote":"The ship won't be able to leave until the weather improves.","viQuote":"Con tàu sẽ không thể rời cảng cho đến khi thời tiết khá hơn."}],"evQuotes":["Hmm, I hope the fog over the harbor lifts soon.","The ship won't be able to leave until the weather improves."]},{"q":40,"part":3,"group_id":"E25_T01_G38_40","audio":"web_assets/ets2025/audio/E25_T01/track_34.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the man say he will do?","stem_vi":"Người đàn ông nói anh ấy sẽ làm gì?","options":{"A":{"en":"Update a shift schedule","vi":"Cập nhật lịch phân ca"},"B":{"en":"Clear a work space","vi":"Dọn dẹp khu vực làm việc"},"C":{"en":"Complete a checklist","vi":"Hoàn thành danh sách kiểm tra"},"D":{"en":"Place a call","vi":"Gọi một cuộc điện thoại"}},"ans":"D","explanation":"Đáp án đúng: (D) Gọi một cuộc điện thoại — Người đàn ông nói anh ấy chắc chắn sẽ sớm gọi cho ban quản lý cảng để hỏi cập nhật giờ tàu được phép rời bến.\nDẫn chứng: \"I'll be sure to call the port authority soon for an update on when we'll be cleared to leave.\" (Tôi chắc chắn sẽ sớm gọi cho ban quản lý cảng để cập nhật khi nào được phép rời đi — \"call\" đồng nghĩa với \"Place a call\").\nPhân tích bẫy:\n- (A) \"Update a shift schedule\" (cập nhật lịch phân ca) là bẫy trộn hai từ khóa riêng lẻ trong bài là \"schedule\" (lịch trình tàu) và \"update\" (cập nhật thông tin từ cảng).\n- (B) \"Clear a work space\" (dọn dẹp khu làm việc) bẫy từ khóa đồng âm/đa nghĩa \"cleared\" trong cụm \"cleared to leave\" (được cấp phép rời bến), hoàn toàn khác nghĩa dọn dẹp.\n- (C) \"Complete a checklist\" (hoàn thành danh sách kiểm tra) không xuất hiện trong lời thoại của người đàn ông.","lines":[{"speaker":"M-Au","en":"Good morning, Damilola. How's everything up here on deck?","vi":"Chào buổi sáng, Damilola. Mọi thứ trên boong tàu thế nào rồi?","units":[{"en":"Good morning, Damilola.","vi":"Chào buổi sáng, Damilola."},{"en":"How's everything up here on deck?","vi":"Mọi thứ trên boong tàu thế nào rồi?"}]},{"speaker":"W-Br","en":"Hi, Pedro. It was an uneventful night, and our cargo ship still hasn't moved yet.","vi":"Chào Pedro. Đêm qua khá yên ắng không có sự cố gì, và tàu chở hàng của chúng ta vẫn chưa di chuyển.","units":[{"en":"Hi, Pedro.","vi":"Chào Pedro."},{"en":"It was an uneventful night, and our cargo ship still hasn't moved yet.","vi":"Đêm qua khá yên ắng không có sự cố gì, và tàu chở hàng của chúng ta vẫn chưa di chuyển."}]},{"speaker":"M-Au","en":"Hmm, I hope the fog over the harbor lifts soon.","vi":"Ừm, tôi hy vọng lớp sương mù trên bến cảng sẽ sớm tan.","units":[{"en":"Hmm, I hope the fog over the harbor lifts soon.","vi":"Ừm, tôi hy vọng lớp sương mù trên bến cảng sẽ sớm tan."}]},{"speaker":"W-Br","en":"Yeah, me too. The ship won't be able to leave until the weather improves.","vi":"Ừ, tôi cũng vậy. Con tàu sẽ không thể rời cảng cho đến khi thời tiết khá hơn.","units":[{"en":"Yeah, me too.","vi":"Ừ, tôi cũng vậy."},{"en":"The ship won't be able to leave until the weather improves.","vi":"Con tàu sẽ không thể rời cảng cho đến khi thời tiết khá hơn."}]},{"speaker":"M-Au","en":"I hope we won't get too far behind schedule. I'll be sure to call the port authority soon for an update on when we'll be cleared to leave.","vi":"Tôi hy vọng chúng ta sẽ không bị trễ lịch trình quá nhiều. Tôi chắc chắn sẽ sớm gọi cho ban quản lý cảng để cập nhật thời điểm chúng ta được cấp phép rời bến.","units":[{"en":"I hope we won't get too far behind schedule.","vi":"Tôi hy vọng chúng ta sẽ không bị trễ lịch trình quá nhiều."},{"en":"I'll be sure to call the port authority soon for an update on when we'll be cleared to leave.","vi":"Tôi chắc chắn sẽ sớm gọi cho ban quản lý cảng để cập nhật thời điểm chúng ta được cấp phép rời bến."}]},{"speaker":"W-Br","en":"Sounds good.","vi":"Nghe hợp lý đấy.","units":[{"en":"Sounds good.","vi":"Nghe hợp lý đấy."}]}],"vocab":[{"word":"port authority","pos":"n","ipa":"/pɔːrt əˈθɔːrəti/","meaning":"ban quản lý cảng"},{"word":"behind schedule","pos":"phr","ipa":"/bɪˈhaɪnd ˈskedʒuːl/","meaning":"trễ lịch trình"},{"word":"cleared","pos":"adj","ipa":"/klɪrd/","meaning":"được cấp phép (rời bến, cất cánh)"},{"word":"place a call","pos":"phr","ipa":"/pleɪs ə kɔːl/","meaning":"gọi một cuộc điện thoại"}],"isScanBacked":false,"grammarType":"Part 3 — Hành động tiếp theo & Đề xuất (Next Step & Offer/Request)","formula":"CÔNG THỨC PART 3 (Hành động tương lai với \"I'll be sure to\"): Nghe cụm \"I'll be sure to call the port authority\" và nhận diện paraphrase kinh điển \"call [someone]\" → \"Place a call\".","optionAnalysis":{"A":"Bẫy ghép từ khóa: Bài nghe có \"behind schedule\" và \"for an update\", nhưng là xin cập nhật giờ xuất bến chứ không phải sửa lịch phân ca.","B":"Bẫy từ đa nghĩa \"clear\": Cụm \"cleared to leave\" nghĩa là được cảng vụ cấp phép khởi hành, không phải dọn dẹp khu vực làm việc.","C":"Không có trong bài: Người đàn ông không đề cập đến bảng kiểm tra an toàn hay danh sách công việc nào.","D":"Chính xác: Cụm \"I'll be sure to call the port authority\" được paraphrase trực tiếp thành \"Place a call\"."},"evDocIdx":0,"evTargets":[{"badge":"Câu 40 · Đáp án D","opt":"D","isCorrect":true,"quote":"I'll be sure to call the port authority soon for an update on when we'll be cleared to leave.","viQuote":"Tôi chắc chắn sẽ sớm gọi cho ban quản lý cảng để cập nhật thời điểm chúng ta được cấp phép rời bến."}],"evQuotes":["I'll be sure to call the port authority soon for an update on when we'll be cleared to leave."]},{"q":41,"part":3,"group_id":"E25_T01_G41_43","audio":"web_assets/ets2025/audio/E25_T01/track_35.mp3","graphicImg":null,"transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_09.webp","web_assets/ets2025/tr/E25_T01_tr_10.webp"],"stem_en":"Why is the woman at the restaurant?","stem_vi":"Tại sao người phụ nữ lại có mặt tại nhà hàng?","options":{"A":{"en":"To celebrate a retirement","vi":"Để tổ chức tiệc nghỉ hưu"},"B":{"en":"To perform an inspection","vi":"Để tiến hành kiểm tra"},"C":{"en":"To meet with some clients","vi":"Để gặp gỡ một vài khách hàng"},"D":{"en":"To write an article","vi":"Để viết một bài báo"}},"ans":"C","explanation":"Đáp án đúng: (C) Để gặp gỡ một vài khách hàng — Người phụ nữ nói rõ ngay khi vào nhà hàng rằng cô đã đặt bàn để ăn trưa gặp gỡ một số khách hàng.\nDẫn chứng: \"Hi. I've made a reservation to meet with some clients for lunch today.\" (Xin chào. Tôi có đặt bàn trước để gặp gỡ một vài khách hàng ăn trưa hôm nay — khớp nguyên văn với \"To meet with some clients\").\nPhân tích bẫy:\n- (A) \"To celebrate a retirement\" (tiệc nghỉ hưu) sai mục đích bữa ăn; đây là cuộc gặp công việc với khách hàng (\"clients\").\n- (B) \"To perform an inspection\" (tiến hành kiểm tra) không liên quan vì cô là thực khách đã đặt bàn trước, không phải thanh tra.\n- (D) \"To write an article\" (viết bài báo) suy diễn sai vai trò thành nhà báo/phê bình ẩm thực; cô đến ăn trưa tiếp khách.","lines":[{"speaker":"W-Br","en":"Hi. I've made a reservation to meet with some clients for lunch today. It's under Cohen.","vi":"Xin chào. Tôi có đặt bàn trước để gặp gỡ một vài khách hàng ăn trưa hôm nay. Bàn được đặt dưới tên Cohen.","units":[{"en":"Hi.","vi":"Xin chào."},{"en":"I've made a reservation to meet with some clients for lunch today.","vi":"Tôi có đặt bàn trước để gặp gỡ một vài khách hàng ăn trưa hôm nay."},{"en":"It's under Cohen.","vi":"Bàn được đặt dưới tên Cohen."}]},{"speaker":"M-Au","en":"Oh, yes. I see your reservation. Welcome, Ms. Cohen.","vi":"Ồ, vâng. Tôi thấy thông tin đặt bàn của bà rồi ạ. Chào mừng bà Cohen ạ.","units":[{"en":"Oh, yes.","vi":"Ồ, vâng."},{"en":"I see your reservation.","vi":"Tôi thấy thông tin đặt bàn của bà rồi ạ."},{"en":"Welcome, Ms. Cohen.","vi":"Chào mừng bà Cohen ạ."}]},{"speaker":"W-Br","en":"I know I asked to be seated on your beautiful terrace, but it's very hot today.","vi":"Tôi biết trước đó mình đã yêu cầu ngồi ngoài sân hiên xinh đẹp của nhà hàng, nhưng hôm nay trời nóng quá.","units":[{"en":"I know I asked to be seated on your beautiful terrace, but it's very hot today.","vi":"Tôi biết trước đó mình đã yêu cầu ngồi ngoài sân hiên xinh đẹp của nhà hàng, nhưng hôm nay trời nóng quá."}]},{"speaker":"M-Au","en":"Hmm. I can seat you at table four inside. Do you mind waiting a few minutes?","vi":"Ừm. Tôi có thể sắp xếp cho bà ngồi ở bàn số bốn bên trong nhà. Bà có phiền chờ vài phút không ạ?","units":[{"en":"Hmm.","vi":"Ừm."},{"en":"I can seat you at table four inside.","vi":"Tôi có thể sắp xếp cho bà ngồi ở bàn số bốn bên trong nhà."},{"en":"Do you mind waiting a few minutes?","vi":"Bà có phiền chờ vài phút không ạ?"}]},{"speaker":"W-Br","en":"Not at all. By the way, your parking area's nearly full. Where can I tell my clients to park?","vi":"Không hề gì. Nhân tiện thì bãi đỗ xe của nhà hàng gần kín chỗ rồi. Tôi nên bảo khách hàng của mình đỗ xe ở đâu đây?","units":[{"en":"Not at all.","vi":"Không hề gì."},{"en":"By the way, your parking area's nearly full.","vi":"Nhân tiện thì bãi đỗ xe của nhà hàng gần kín chỗ rồi."},{"en":"Where can I tell my clients to park?","vi":"Tôi nên bảo khách hàng của mình đỗ xe ở đâu đây?"}]},{"speaker":"M-Au","en":"Our customers can park for free in the garage across the street. Our cashier will stamp their parking tickets.","vi":"Khách hàng của chúng tôi có thể đỗ xe miễn phí tại nhà đỗ xe bên kia đường. Nhân viên thu ngân của chúng tôi sẽ đóng dấu xác nhận lên vé gửi xe của họ.","units":[{"en":"Our customers can park for free in the garage across the street.","vi":"Khách hàng của chúng tôi có thể đỗ xe miễn phí tại nhà đỗ xe bên kia đường."},{"en":"Our cashier will stamp their parking tickets.","vi":"Nhân viên thu ngân của chúng tôi sẽ đóng dấu xác nhận lên vé gửi xe của họ."}]},{"speaker":"W-Br","en":"Oh, great. Thanks. I'll call them and let them know.","vi":"Ồ, tuyệt quá. Cảm ơn anh. Tôi sẽ gọi điện báo cho họ biết.","units":[{"en":"Oh, great.","vi":"Ồ, tuyệt quá."},{"en":"Thanks.","vi":"Cảm ơn anh."},{"en":"I'll call them and let them know.","vi":"Tôi sẽ gọi điện báo cho họ biết."}]}],"vocab":[{"word":"reservation","pos":"n","ipa":"/ˌrezərˈveɪʃən/","meaning":"sự đặt chỗ trước, đặt bàn"},{"word":"client","pos":"n","ipa":"/ˈklaɪənt/","meaning":"khách hàng"},{"word":"inspection","pos":"n","ipa":"/ɪnˈspekʃən/","meaning":"cuộc kiểm tra, thanh tra"}],"isScanBacked":false,"grammarType":"Part 3 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 3 (Mục đích ngay câu mở đầu \"I've made a reservation to\"): Chú ý động từ chỉ mục đích sau \"to\" ngay lượt nói đầu tiên của khách hàng (\"to meet with some clients for lunch today\").","optionAnalysis":{"A":"Sai lý do đặt bàn: Bữa trưa này dùng để gặp khách hàng làm việc, không có thông tin nào về tiệc nghỉ hưu.","B":"Sai vai trò nhân vật: Cô Cohen là khách hàng đặt bàn (\"made a reservation\"), không phải nhân viên đi kiểm tra nhà hàng.","C":"Chính xác: Người phụ nữ nói rõ ngay câu đầu \"I've made a reservation to meet with some clients for lunch today\".","D":"Không có dữ kiện: Cô khen sân hiên đẹp nhưng không hề là phóng viên đến viết bài đánh giá."},"evDocIdx":0,"evTargets":[{"badge":"Câu 41 · Đáp án C","opt":"C","isCorrect":true,"quote":"I've made a reservation to meet with some clients for lunch today.","viQuote":"Tôi có đặt bàn trước để gặp gỡ một vài khách hàng ăn trưa hôm nay."}],"evQuotes":["I've made a reservation to meet with some clients for lunch today."]},{"q":42,"part":3,"group_id":"E25_T01_G41_43","audio":"web_assets/ets2025/audio/E25_T01/track_35.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the woman mean when she says, \"it's very hot today\"?","stem_vi":"Người phụ nữ có ý gì khi nói \"it's very hot today\"?","options":{"A":{"en":"She is unable to accept an invitation.","vi":"Cô ấy không thể nhận lời mời."},"B":{"en":"A cooling system is not working.","vi":"Hệ thống làm mát không hoạt động."},"C":{"en":"A meeting will end soon.","vi":"Một cuộc họp sẽ sớm kết thúc."},"D":{"en":"She wants to change a seating request.","vi":"Cô ấy muốn thay đổi yêu cầu về chỗ ngồi."}},"ans":"D","explanation":"Đáp án đúng: (D) Cô ấy muốn thay đổi yêu cầu về chỗ ngồi — Dù trước đó đã đặt bàn ngoài sân hiên (terrace), nhưng vì trời nóng nên cô muốn đổi sang ngồi bên trong nhà hàng.\nDẫn chứng: \"I know I asked to be seated on your beautiful terrace, but it's very hot today.\" → Nhân viên đáp ngay: \"I can seat you at table four inside.\" (Tôi biết mình đã xin ngồi ngoài sân hiên, nhưng hôm nay nóng quá → Tôi có thể xếp bà ngồi bàn số 4 bên trong — chứng tỏ hàm ý đổi chỗ ngồi).\nPhân tích bẫy:\n- (A) \"She is unable to accept an invitation\" (không thể nhận lời mời) sai vì chính cô là người chủ động đặt bàn tiếp khách và sẵn sàng đợi vài phút (\"Not at all\").\n- (B) \"A cooling system is not working\" (hệ thống làm mát hỏng) là bẫy diễn giải theo nghĩa đen từ chữ \"very hot\"; thực chất cô nói về thời tiết ngoài sân hiên, còn bên trong nhà hàng vẫn mát nên mới xin đổi vào trong.\n- (C) \"A meeting will end soon\" (cuộc họp sắp kết thúc) sai trình tự thời gian vì bữa trưa gặp khách hàng thậm chí còn chưa bắt đầu.","lines":[{"speaker":"W-Br","en":"Hi. I've made a reservation to meet with some clients for lunch today. It's under Cohen.","vi":"Xin chào. Tôi có đặt bàn trước để gặp gỡ một vài khách hàng ăn trưa hôm nay. Bàn được đặt dưới tên Cohen.","units":[{"en":"Hi.","vi":"Xin chào."},{"en":"I've made a reservation to meet with some clients for lunch today.","vi":"Tôi có đặt bàn trước để gặp gỡ một vài khách hàng ăn trưa hôm nay."},{"en":"It's under Cohen.","vi":"Bàn được đặt dưới tên Cohen."}]},{"speaker":"M-Au","en":"Oh, yes. I see your reservation. Welcome, Ms. Cohen.","vi":"Ồ, vâng. Tôi thấy thông tin đặt bàn của bà rồi ạ. Chào mừng bà Cohen ạ.","units":[{"en":"Oh, yes.","vi":"Ồ, vâng."},{"en":"I see your reservation.","vi":"Tôi thấy thông tin đặt bàn của bà rồi ạ."},{"en":"Welcome, Ms. Cohen.","vi":"Chào mừng bà Cohen ạ."}]},{"speaker":"W-Br","en":"I know I asked to be seated on your beautiful terrace, but it's very hot today.","vi":"Tôi biết trước đó mình đã yêu cầu ngồi ngoài sân hiên xinh đẹp của nhà hàng, nhưng hôm nay trời nóng quá.","units":[{"en":"I know I asked to be seated on your beautiful terrace, but it's very hot today.","vi":"Tôi biết trước đó mình đã yêu cầu ngồi ngoài sân hiên xinh đẹp của nhà hàng, nhưng hôm nay trời nóng quá."}]},{"speaker":"M-Au","en":"Hmm. I can seat you at table four inside. Do you mind waiting a few minutes?","vi":"Ừm. Tôi có thể sắp xếp cho bà ngồi ở bàn số bốn bên trong nhà. Bà có phiền chờ vài phút không ạ?","units":[{"en":"Hmm.","vi":"Ừm."},{"en":"I can seat you at table four inside.","vi":"Tôi có thể sắp xếp cho bà ngồi ở bàn số bốn bên trong nhà."},{"en":"Do you mind waiting a few minutes?","vi":"Bà có phiền chờ vài phút không ạ?"}]},{"speaker":"W-Br","en":"Not at all. By the way, your parking area's nearly full. Where can I tell my clients to park?","vi":"Không hề gì. Nhân tiện thì bãi đỗ xe của nhà hàng gần kín chỗ rồi. Tôi nên bảo khách hàng của mình đỗ xe ở đâu đây?","units":[{"en":"Not at all.","vi":"Không hề gì."},{"en":"By the way, your parking area's nearly full.","vi":"Nhân tiện thì bãi đỗ xe của nhà hàng gần kín chỗ rồi."},{"en":"Where can I tell my clients to park?","vi":"Tôi nên bảo khách hàng của mình đỗ xe ở đâu đây?"}]},{"speaker":"M-Au","en":"Our customers can park for free in the garage across the street. Our cashier will stamp their parking tickets.","vi":"Khách hàng của chúng tôi có thể đỗ xe miễn phí tại nhà đỗ xe bên kia đường. Nhân viên thu ngân của chúng tôi sẽ đóng dấu xác nhận lên vé gửi xe của họ.","units":[{"en":"Our customers can park for free in the garage across the street.","vi":"Khách hàng của chúng tôi có thể đỗ xe miễn phí tại nhà đỗ xe bên kia đường."},{"en":"Our cashier will stamp their parking tickets.","vi":"Nhân viên thu ngân của chúng tôi sẽ đóng dấu xác nhận lên vé gửi xe của họ."}]},{"speaker":"W-Br","en":"Oh, great. Thanks. I'll call them and let them know.","vi":"Ồ, tuyệt quá. Cảm ơn anh. Tôi sẽ gọi điện báo cho họ biết.","units":[{"en":"Oh, great.","vi":"Ồ, tuyệt quá."},{"en":"Thanks.","vi":"Cảm ơn anh."},{"en":"I'll call them and let them know.","vi":"Tôi sẽ gọi điện báo cho họ biết."}]}],"vocab":[{"word":"terrace","pos":"n","ipa":"/ˈterəs/","meaning":"sân hiên ngoài trời"},{"word":"seat","pos":"v","ipa":"/siːt/","meaning":"sắp xếp chỗ ngồi cho"},{"word":"seating request","pos":"n","ipa":"/ˈsiːtɪŋ rɪˈkwest/","meaning":"yêu cầu về chỗ ngồi"}],"isScanBacked":false,"grammarType":"Part 3 — Câu hỏi hàm ý (Speaker Intent / Implied Meaning)","formula":"CÔNG THỨC PART 3 (Câu hỏi hàm ý — Cấu trúc nhượng bộ \"I know I asked, but\"): Khi người nói dùng \"I know [yêu cầu cũ], but [lý do thực tế]\", hàm ý là muốn điều chỉnh/thay đổi yêu cầu trước đó → Kiểm tra câu phản hồi ngay sau của đối phương (\"I can seat you at table four inside\").","optionAnalysis":{"A":"Ngược ngữ cảnh: Cô ấy đã có mặt tại nhà hàng để đón khách và đồng ý chờ xếp bàn bên trong, không từ chối lời mời nào.","B":"Bẫy suy diễn sai vị trí nóng: Cô ấy phàn nàn trời nóng ở khu vực sân hiên ngoài trời (\"terrace\"), không phải điều hòa trong nhà bị hỏng.","C":"Sai thời điểm sự kiện: Khách hàng của cô còn đang trên đường tới tìm chỗ đỗ xe, cuộc gặp chưa hề diễn ra.","D":"Chính xác: Cấu trúc \"I know I asked to be seated on your terrace, but it's very hot\" ngụ ý muốn đổi sang bàn trong nhà (\"table four inside\")."},"evDocIdx":0,"evTargets":[{"badge":"Câu 42 · Đáp án D","opt":"D","isCorrect":true,"quote":"I know I asked to be seated on your beautiful terrace, but it's very hot today.","viQuote":"Tôi biết trước đó mình đã yêu cầu ngồi ngoài sân hiên xinh đẹp của nhà hàng, nhưng hôm nay trời nóng quá."},{"badge":"Câu 42 · Đáp án D","opt":"D","isCorrect":true,"quote":"I can seat you at table four inside.","viQuote":"Tôi có thể sắp xếp cho bà ngồi ở bàn số bốn bên trong nhà."}],"evQuotes":["I know I asked to be seated on your beautiful terrace, but it's very hot today.","I can seat you at table four inside."]},{"q":43,"part":3,"group_id":"E25_T01_G41_43","audio":"web_assets/ets2025/audio/E25_T01/track_35.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the man say about a parking garage?","stem_vi":"Người đàn ông nói gì về nhà đỗ xe?","options":{"A":{"en":"It is free for customers.","vi":"Nơi đó miễn phí cho khách hàng."},"B":{"en":"It is under construction.","vi":"Nơi đó đang được thi công."},"C":{"en":"It closes soon.","vi":"Nơi đó sắp đóng cửa."},"D":{"en":"It offers monthly contracts.","vi":"Nơi đó cung cấp hợp đồng theo tháng."}},"ans":"A","explanation":"Đáp án đúng: (A) Nơi đó miễn phí cho khách hàng — Nhân viên nhà hàng cho biết khách của họ có thể đỗ xe miễn phí tại nhà đỗ xe bên kia đường và thu ngân sẽ đóng dấu vé.\nDẫn chứng: \"Our customers can park for free in the garage across the street. Our cashier will stamp their parking tickets.\" (Khách hàng của chúng tôi có thể đỗ xe miễn phí tại nhà đỗ xe bên kia đường — khớp trực tiếp với \"It is free for customers\").\nPhân tích bẫy:\n- (B) \"It is under construction\" (đang thi công) không được nhắc đến; lý do không đỗ ở bãi của nhà hàng là vì \"parking area's nearly full\" (gần kín chỗ), không phải do sửa chữa.\n- (C) \"It closes soon\" (sắp đóng cửa) sai hoàn toàn vì anh ấy vẫn giới thiệu cho khách hàng sang đó gửi xe ăn trưa.\n- (D) \"It offers monthly contracts\" (cung cấp hợp đồng tháng) là thông tin tự suy diễn, không phù hợp với khách ăn trưa vãng lai chỉ cần đóng dấu vé (\"stamp their parking tickets\").","lines":[{"speaker":"W-Br","en":"Hi. I've made a reservation to meet with some clients for lunch today. It's under Cohen.","vi":"Xin chào. Tôi có đặt bàn trước để gặp gỡ một vài khách hàng ăn trưa hôm nay. Bàn được đặt dưới tên Cohen.","units":[{"en":"Hi.","vi":"Xin chào."},{"en":"I've made a reservation to meet with some clients for lunch today.","vi":"Tôi có đặt bàn trước để gặp gỡ một vài khách hàng ăn trưa hôm nay."},{"en":"It's under Cohen.","vi":"Bàn được đặt dưới tên Cohen."}]},{"speaker":"M-Au","en":"Oh, yes. I see your reservation. Welcome, Ms. Cohen.","vi":"Ồ, vâng. Tôi thấy thông tin đặt bàn của bà rồi ạ. Chào mừng bà Cohen ạ.","units":[{"en":"Oh, yes.","vi":"Ồ, vâng."},{"en":"I see your reservation.","vi":"Tôi thấy thông tin đặt bàn của bà rồi ạ."},{"en":"Welcome, Ms. Cohen.","vi":"Chào mừng bà Cohen ạ."}]},{"speaker":"W-Br","en":"I know I asked to be seated on your beautiful terrace, but it's very hot today.","vi":"Tôi biết trước đó mình đã yêu cầu ngồi ngoài sân hiên xinh đẹp của nhà hàng, nhưng hôm nay trời nóng quá.","units":[{"en":"I know I asked to be seated on your beautiful terrace, but it's very hot today.","vi":"Tôi biết trước đó mình đã yêu cầu ngồi ngoài sân hiên xinh đẹp của nhà hàng, nhưng hôm nay trời nóng quá."}]},{"speaker":"M-Au","en":"Hmm. I can seat you at table four inside. Do you mind waiting a few minutes?","vi":"Ừm. Tôi có thể sắp xếp cho bà ngồi ở bàn số bốn bên trong nhà. Bà có phiền chờ vài phút không ạ?","units":[{"en":"Hmm.","vi":"Ừm."},{"en":"I can seat you at table four inside.","vi":"Tôi có thể sắp xếp cho bà ngồi ở bàn số bốn bên trong nhà."},{"en":"Do you mind waiting a few minutes?","vi":"Bà có phiền chờ vài phút không ạ?"}]},{"speaker":"W-Br","en":"Not at all. By the way, your parking area's nearly full. Where can I tell my clients to park?","vi":"Không hề gì. Nhân tiện thì bãi đỗ xe của nhà hàng gần kín chỗ rồi. Tôi nên bảo khách hàng của mình đỗ xe ở đâu đây?","units":[{"en":"Not at all.","vi":"Không hề gì."},{"en":"By the way, your parking area's nearly full.","vi":"Nhân tiện thì bãi đỗ xe của nhà hàng gần kín chỗ rồi."},{"en":"Where can I tell my clients to park?","vi":"Tôi nên bảo khách hàng của mình đỗ xe ở đâu đây?"}]},{"speaker":"M-Au","en":"Our customers can park for free in the garage across the street. Our cashier will stamp their parking tickets.","vi":"Khách hàng của chúng tôi có thể đỗ xe miễn phí tại nhà đỗ xe bên kia đường. Nhân viên thu ngân của chúng tôi sẽ đóng dấu xác nhận lên vé gửi xe của họ.","units":[{"en":"Our customers can park for free in the garage across the street.","vi":"Khách hàng của chúng tôi có thể đỗ xe miễn phí tại nhà đỗ xe bên kia đường."},{"en":"Our cashier will stamp their parking tickets.","vi":"Nhân viên thu ngân của chúng tôi sẽ đóng dấu xác nhận lên vé gửi xe của họ."}]},{"speaker":"W-Br","en":"Oh, great. Thanks. I'll call them and let them know.","vi":"Ồ, tuyệt quá. Cảm ơn anh. Tôi sẽ gọi điện báo cho họ biết.","units":[{"en":"Oh, great.","vi":"Ồ, tuyệt quá."},{"en":"Thanks.","vi":"Cảm ơn anh."},{"en":"I'll call them and let them know.","vi":"Tôi sẽ gọi điện báo cho họ biết."}]}],"vocab":[{"word":"parking garage","pos":"n","ipa":"/ˈpɑːrkɪŋ ɡəˈrɑːʒ/","meaning":"nhà đỗ xe"},{"word":"cashier","pos":"n","ipa":"/kæˈʃɪr/","meaning":"nhân viên thu ngân"},{"word":"stamp","pos":"v","ipa":"/stæmp/","meaning":"đóng dấu"},{"word":"across the street","pos":"phr","ipa":"/əˈkrɔːs ðə striːt/","meaning":"ở bên kia đường"}],"isScanBacked":false,"grammarType":"Part 3 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 3 (Hỏi-Đáp chi tiết địa điểm phụ trợ): Khi một người hỏi \"Where can I tell my clients to park?\", câu trả lời ngay sau nêu vị trí và điều kiện sử dụng (\"park for free in the garage across the street\" → \"It is free for customers\").","optionAnalysis":{"A":"Chính xác: Người đàn ông nói rõ \"Our customers can park for free in the garage across the street\", khớp hoàn toàn với \"It is free for customers\".","B":"Bẫy nhầm lý do: Bãi xe của nhà hàng gần kín chỗ (\"nearly full\"), chứ không phải nhà đỗ xe bên kia đường đang thi công.","C":"Ngược thông tin bài nghe: Nhà đỗ xe vẫn đang mở phục vụ khách hàng của nhà hàng, không hề nhắc giờ đóng cửa.","D":"Thông tin không có trong bài: Nhân viên thu ngân chỉ đóng dấu xác nhận từng vé gửi xe (\"stamp their parking tickets\"), không đề cập hợp đồng tháng."},"evDocIdx":0,"evTargets":[{"badge":"Câu 43 · Đáp án A","opt":"A","isCorrect":true,"quote":"Our customers can park for free in the garage across the street.","viQuote":"Khách hàng của chúng tôi có thể đỗ xe miễn phí tại nhà đỗ xe bên kia đường."},{"badge":"Câu 43 · Đáp án A","opt":"A","isCorrect":true,"quote":"Our cashier will stamp their parking tickets.","viQuote":"Nhân viên thu ngân của chúng tôi sẽ đóng dấu xác nhận lên vé gửi xe của họ."}],"evQuotes":["Our customers can park for free in the garage across the street.","Our cashier will stamp their parking tickets."]},{"q":44,"part":3,"group_id":"E25_T01_G44_46","audio":"web_assets/ets2025/audio/E25_T01/track_36.mp3","graphicImg":null,"transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_10.webp","web_assets/ets2025/tr/E25_T01_tr_11.webp"],"stem_en":"Where does the woman most likely work?","stem_vi":"Người phụ nữ có khả năng làm việc ở đâu nhất?","options":{"A":{"en":"At a university","vi":"Tại một trường đại học"},"B":{"en":"At a publishing company","vi":"Tại một công ty xuất bản"},"C":{"en":"At an electronics store","vi":"Tại một cửa hàng điện tử"},"D":{"en":"At a grocery store","vi":"Tại một cửa hàng tạp hóa"}},"ans":"C","explanation":"Đáp án đúng: (C) Tại một cửa hàng điện tử — Người phụ nữ chào đón hai đối tác đến giới thiệu máy in mới tại cửa hàng nơi đang giảm giá lớn máy tính xách tay và máy tính bảng.\nDẫn chứng: \"Thank you both for coming here today to demonstrate your company's new compact printer. I know the store will be busy because we're having a big sale on laptop computers and tablets.\" (Cảm ơn hai anh đến trình diễn máy in nhỏ gọn mới. Tôi biết cửa hàng sẽ đông vì đang giảm giá lớn laptop và máy tính bảng → \"electronics store\").\nPhân tích bẫy:\n- (A) \"At a university\" (tại trường đại học) là bẫy từ khóa \"students\" do người đàn ông M1 nhắc tới khi nói đối tượng khách hàng mục tiêu của máy in (\"perfect for students\").\n- (B) \"At a publishing company\" (công ty xuất bản) bẫy liên tưởng với từ \"printer\" (máy in) và \"brochures\" (tờ rơi), nhưng đây là nơi bán lẻ thiết bị điện tử tiêu dùng.\n- (D) \"At a grocery store\" (cửa hàng tạp hóa) bẫy nửa từ khóa \"store\" nhưng sai hẳn mặt hàng kinh doanh (\"laptop computers and tablets\").","lines":[{"speaker":"W-Am","en":"Thank you both for coming here today to demonstrate your company's new compact printer. I know the store will be busy because we're having a big sale on laptop computers and tablets.","vi":"Cảm ơn cả hai anh đã đến đây hôm nay để trình diễn mẫu máy in nhỏ gọn mới của công ty các anh. Tôi biết hôm nay cửa hàng sẽ rất đông khách vì chúng tôi đang có đợt giảm giá lớn cho máy tính xách tay và máy tính bảng.","units":[{"en":"Thank you both for coming here today to demonstrate your company's new compact printer.","vi":"Cảm ơn cả hai anh đã đến đây hôm nay để trình diễn mẫu máy in nhỏ gọn mới của công ty các anh."},{"en":"I know the store will be busy because we're having a big sale on laptop computers and tablets.","vi":"Tôi biết hôm nay cửa hàng sẽ rất đông khách vì chúng tôi đang có đợt giảm giá lớn cho máy tính xách tay và máy tính bảng."}]},{"speaker":"M1 (M-Cn)","en":"We're happy to be here. Our printers are perfect for students or people with home offices who may have limited space. My partner, Murat, will be setting up the printer station.","vi":"Chúng tôi rất vui khi được có mặt tại đây. Máy in của chúng tôi rất lý tưởng cho sinh viên hoặc những người làm việc tại nhà có không gian hạn chế. Cộng sự của tôi, anh Murat, sẽ phụ trách lắp đặt quầy trưng bày máy in.","units":[{"en":"We're happy to be here.","vi":"Chúng tôi rất vui khi được có mặt tại đây."},{"en":"Our printers are perfect for students or people with home offices who may have limited space.","vi":"Máy in của chúng tôi rất lý tưởng cho sinh viên hoặc những người làm việc tại nhà có không gian hạn chế."},{"en":"My partner, Murat, will be setting up the printer station.","vi":"Cộng sự của tôi, anh Murat, sẽ phụ trách lắp đặt quầy trưng bày máy in."}]},{"speaker":"M2 (M-Au)","en":"Yes—where can I put our demonstration table?","vi":"Vâng — tôi có thể đặt bàn trình diễn sản phẩm của chúng tôi ở đâu ạ?","units":[{"en":"Yes—where can I put our demonstration table?","vi":"Vâng — tôi có thể đặt bàn trình diễn sản phẩm của chúng tôi ở đâu ạ?"}]},{"speaker":"W-Am","en":"I'll show you the area. Also, if you brought any brochures with you, it'll be helpful to put those out for people to take.","vi":"Tôi sẽ chỉ cho các anh khu vực đó. Ngoài ra, nếu các anh có mang theo tờ rơi giới thiệu, sẽ rất hữu ích nếu bày chúng ra để khách hàng có thể lấy xem.","units":[{"en":"I'll show you the area.","vi":"Tôi sẽ chỉ cho các anh khu vực đó."},{"en":"Also, if you brought any brochures with you, it'll be helpful to put those out for people to take.","vi":"Ngoài ra, nếu các anh có mang theo tờ rơi giới thiệu, sẽ rất hữu ích nếu bày chúng ra để khách hàng có thể lấy xem."}]}],"vocab":[{"word":"demonstrate","pos":"v","ipa":"/ˈdemənstreɪt/","meaning":"trình diễn, giới thiệu sản phẩm"},{"word":"compact","pos":"adj","ipa":"/kəmˈpækt/","meaning":"nhỏ gọn"},{"word":"electronics","pos":"n","ipa":"/ɪˌlekˈtrɑːnɪks/","meaning":"đồ điện tử"},{"word":"tablet","pos":"n","ipa":"/ˈtæblət/","meaning":"máy tính bảng"}],"isScanBacked":false,"grammarType":"Part 3 — Ngữ cảnh, Địa điểm & Danh tính người nói (Setting & Role)","formula":"CÔNG THỨC PART 3 (Xác định nơi làm việc qua mặt hàng đang bán): Kết hợp danh từ \"the store\" với các sản phẩm \"compact printer\", \"laptop computers\", \"tablets\" → Chốt ngay Cửa hàng điện tử (\"At an electronics store\").","optionAnalysis":{"A":"Bẫy bắt từ khóa \"students\": M1 nhắc máy in hợp với sinh viên, nhưng địa điểm diễn ra buổi giới thiệu là \"the store\" đang bán laptop và tablet.","B":"Bẫy liên tưởng \"printer / brochures\": Đây là cửa hàng bán lẻ thiết bị công nghệ cho người dùng cá nhân, không phải nhà xuất bản.","C":"Chính xác: Người phụ nữ nói \"the store\" đang giảm giá lớn \"laptop computers and tablets\" và mời trưng bày \"compact printer\", khớp cửa hàng điện tử.","D":"Bẫy khớp một nửa từ \"store\": Dù đúng là cửa hàng, mặt hàng được nhắc là máy tính bảng và máy tính xách tay chứ không phải thực phẩm tạp hóa."},"evDocIdx":0,"evTargets":[{"badge":"Câu 44 · Đáp án C","opt":"C","isCorrect":true,"quote":"Thank you both for coming here today to demonstrate your company's new compact printer.","viQuote":"Cảm ơn cả hai anh đã đến đây hôm nay để trình diễn mẫu máy in nhỏ gọn mới của công ty các anh."},{"badge":"Câu 44 · Đáp án C","opt":"C","isCorrect":true,"quote":"I know the store will be busy because we're having a big sale on laptop computers and tablets.","viQuote":"Tôi biết hôm nay cửa hàng sẽ rất đông khách vì chúng tôi đang có đợt giảm giá lớn cho máy tính xách tay và máy tính bảng."}],"evQuotes":["Thank you both for coming here today to demonstrate your company's new compact printer.","I know the store will be busy because we're having a big sale on laptop computers and tablets."]},{"q":45,"part":3,"group_id":"E25_T01_G44_46","audio":"web_assets/ets2025/audio/E25_T01/track_36.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does Murat ask about?","stem_vi":"Murat hỏi về điều gì?","options":{"A":{"en":"How much an item costs","vi":"Giá của một mặt hàng là bao nhiêu"},"B":{"en":"When an event will begin","vi":"Khi nào một sự kiện sẽ bắt đầu"},"C":{"en":"How many people will participate","vi":"Sẽ có bao nhiêu người tham gia"},"D":{"en":"Where to set up some equipment","vi":"Lắp đặt một số thiết bị ở đâu"}},"ans":"D","explanation":"Đáp án đúng: (D) Lắp đặt một số thiết bị ở đâu — Ngay sau khi được giới thiệu là người phụ trách quầy máy in, Murat hỏi vị trí đặt bàn trình diễn sản phẩm.\nDẫn chứng: \"My partner, Murat, will be setting up the printer station.\" → M2 (Murat): \"Yes—where can I put our demonstration table?\" (Cộng sự Murat của tôi sẽ lắp đặt quầy máy in. → Vâng, tôi có thể đặt bàn trình diễn ở đâu ạ? — khớp với \"Where to set up some equipment\").\nPhân tích bẫy:\n- (A) \"How much an item costs\" (giá mặt hàng bao nhiêu) sai vì không ai nhắc đến giá bán máy in, laptop hay máy tính bảng trong bài.\n- (B) \"When an event will begin\" (khi nào sự kiện bắt đầu) sai trọng tâm câu hỏi; Murat dùng từ để hỏi \"where\" (ở đâu), không phải \"when\".\n- (C) \"How many people will participate\" (có bao nhiêu người tham gia) có thể gây nhiễu với chi tiết \"the store will be busy\", nhưng Murat không hỏi số lượng khách.","lines":[{"speaker":"W-Am","en":"Thank you both for coming here today to demonstrate your company's new compact printer. I know the store will be busy because we're having a big sale on laptop computers and tablets.","vi":"Cảm ơn cả hai anh đã đến đây hôm nay để trình diễn mẫu máy in nhỏ gọn mới của công ty các anh. Tôi biết hôm nay cửa hàng sẽ rất đông khách vì chúng tôi đang có đợt giảm giá lớn cho máy tính xách tay và máy tính bảng.","units":[{"en":"Thank you both for coming here today to demonstrate your company's new compact printer.","vi":"Cảm ơn cả hai anh đã đến đây hôm nay để trình diễn mẫu máy in nhỏ gọn mới của công ty các anh."},{"en":"I know the store will be busy because we're having a big sale on laptop computers and tablets.","vi":"Tôi biết hôm nay cửa hàng sẽ rất đông khách vì chúng tôi đang có đợt giảm giá lớn cho máy tính xách tay và máy tính bảng."}]},{"speaker":"M1 (M-Cn)","en":"We're happy to be here. Our printers are perfect for students or people with home offices who may have limited space. My partner, Murat, will be setting up the printer station.","vi":"Chúng tôi rất vui khi được có mặt tại đây. Máy in của chúng tôi rất lý tưởng cho sinh viên hoặc những người làm việc tại nhà có không gian hạn chế. Cộng sự của tôi, anh Murat, sẽ phụ trách lắp đặt quầy trưng bày máy in.","units":[{"en":"We're happy to be here.","vi":"Chúng tôi rất vui khi được có mặt tại đây."},{"en":"Our printers are perfect for students or people with home offices who may have limited space.","vi":"Máy in của chúng tôi rất lý tưởng cho sinh viên hoặc những người làm việc tại nhà có không gian hạn chế."},{"en":"My partner, Murat, will be setting up the printer station.","vi":"Cộng sự của tôi, anh Murat, sẽ phụ trách lắp đặt quầy trưng bày máy in."}]},{"speaker":"M2 (M-Au)","en":"Yes—where can I put our demonstration table?","vi":"Vâng — tôi có thể đặt bàn trình diễn sản phẩm của chúng tôi ở đâu ạ?","units":[{"en":"Yes—where can I put our demonstration table?","vi":"Vâng — tôi có thể đặt bàn trình diễn sản phẩm của chúng tôi ở đâu ạ?"}]},{"speaker":"W-Am","en":"I'll show you the area. Also, if you brought any brochures with you, it'll be helpful to put those out for people to take.","vi":"Tôi sẽ chỉ cho các anh khu vực đó. Ngoài ra, nếu các anh có mang theo tờ rơi giới thiệu, sẽ rất hữu ích nếu bày chúng ra để khách hàng có thể lấy xem.","units":[{"en":"I'll show you the area.","vi":"Tôi sẽ chỉ cho các anh khu vực đó."},{"en":"Also, if you brought any brochures with you, it'll be helpful to put those out for people to take.","vi":"Ngoài ra, nếu các anh có mang theo tờ rơi giới thiệu, sẽ rất hữu ích nếu bày chúng ra để khách hàng có thể lấy xem."}]}],"vocab":[{"word":"set up","pos":"phr. v","ipa":"/set ˈʌp/","meaning":"lắp đặt, bố trí"},{"word":"equipment","pos":"n","ipa":"/ɪˈkwɪpmənt/","meaning":"thiết bị"},{"word":"partner","pos":"n","ipa":"/ˈpɑːrtnər/","meaning":"cộng sự, đối tác"},{"word":"limited space","pos":"phr","ipa":"/ˈlɪmɪtɪd speɪs/","meaning":"không gian hạn chế"}],"isScanBacked":false,"grammarType":"Part 3 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 3 (Hội thoại 3 người — Theo dõi tên riêng để bắt đúng người nói): Khi M1 giới thiệu \"My partner, Murat, will be setting up the printer station\", câu hỏi ngay sau của M2 chính là lời của Murat (\"where can I put our demonstration table?\" → \"Where to set up some equipment\").","optionAnalysis":{"A":"Không có trong hội thoại: Mặc dù có nhắc đến đợt giảm giá (\"a big sale\"), Murat không hề hỏi về giá tiền của máy in hay laptop.","B":"Bẫy nhầm từ để hỏi (When vs Where): Murat đặt câu hỏi \"where can I put our demonstration table?\" (ở đâu), không hỏi thời gian bắt đầu.","C":"Bẫy suy diễn từ \"store will be busy\": Cửa hàng dự kiến sẽ đông khách, nhưng Murat không hỏi con số người tham gia.","D":"Chính xác: M1 giới thiệu Murat phụ trách \"setting up the printer station\" và Murat hỏi ngay \"where can I put our demonstration table?\"."},"evDocIdx":0,"evTargets":[{"badge":"Câu 45 · Đáp án D","opt":"D","isCorrect":true,"quote":"My partner, Murat, will be setting up the printer station.","viQuote":"Cộng sự của tôi, anh Murat, sẽ phụ trách lắp đặt quầy trưng bày máy in."},{"badge":"Câu 45 · Đáp án D","opt":"D","isCorrect":true,"quote":"Yes—where can I put our demonstration table?","viQuote":"Vâng — tôi có thể đặt bàn trình diễn sản phẩm của chúng tôi ở đâu ạ?"}],"evQuotes":["My partner, Murat, will be setting up the printer station.","Yes—where can I put our demonstration table?"]},{"q":46,"part":3,"group_id":"E25_T01_G44_46","audio":"web_assets/ets2025/audio/E25_T01/track_36.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the woman suggest doing?","stem_vi":"Người phụ nữ đề xuất làm gì?","options":{"A":{"en":"Offering a discount","vi":"Đưa ra chương trình giảm giá"},"B":{"en":"Displaying informational materials","vi":"Trưng bày tài liệu thông tin"},"C":{"en":"Holding a contest","vi":"Tổ chức một cuộc thi"},"D":{"en":"Visiting a registration table","vi":"Ghé qua bàn đăng ký"}},"ans":"B","explanation":"Đáp án đúng: (B) Trưng bày tài liệu thông tin — Người phụ nữ gợi ý nếu hai anh có mang theo tờ rơi (brochures) thì nên bày ra để khách hàng lấy xem.\nDẫn chứng: \"Also, if you brought any brochures with you, it'll be helpful to put those out for people to take.\" (Ngoài ra, nếu các anh mang theo tờ rơi, sẽ rất hữu ích nếu bày chúng ra cho mọi người lấy — \"put those [brochures] out\" = \"Displaying informational materials\").\nPhân tích bẫy:\n- (A) \"Offering a discount\" (đưa ra giảm giá) là bẫy từ chi tiết cửa hàng đang \"having a big sale on laptop computers and tablets\", không phải lời đề xuất dành cho hai người bán máy in.\n- (C) \"Holding a contest\" (tổ chức cuộc thi) không hề xuất hiện trong nội dung hội thoại.\n- (D) \"Visiting a registration table\" (ghé bàn đăng ký) bẫy từ khóa \"table\" trong \"demonstration table\" của lượt thoại trước, nhưng là bàn trình diễn sản phẩm chứ không phải bàn đăng ký.","lines":[{"speaker":"W-Am","en":"Thank you both for coming here today to demonstrate your company's new compact printer. I know the store will be busy because we're having a big sale on laptop computers and tablets.","vi":"Cảm ơn cả hai anh đã đến đây hôm nay để trình diễn mẫu máy in nhỏ gọn mới của công ty các anh. Tôi biết hôm nay cửa hàng sẽ rất đông khách vì chúng tôi đang có đợt giảm giá lớn cho máy tính xách tay và máy tính bảng.","units":[{"en":"Thank you both for coming here today to demonstrate your company's new compact printer.","vi":"Cảm ơn cả hai anh đã đến đây hôm nay để trình diễn mẫu máy in nhỏ gọn mới của công ty các anh."},{"en":"I know the store will be busy because we're having a big sale on laptop computers and tablets.","vi":"Tôi biết hôm nay cửa hàng sẽ rất đông khách vì chúng tôi đang có đợt giảm giá lớn cho máy tính xách tay và máy tính bảng."}]},{"speaker":"M1 (M-Cn)","en":"We're happy to be here. Our printers are perfect for students or people with home offices who may have limited space. My partner, Murat, will be setting up the printer station.","vi":"Chúng tôi rất vui khi được có mặt tại đây. Máy in của chúng tôi rất lý tưởng cho sinh viên hoặc những người làm việc tại nhà có không gian hạn chế. Cộng sự của tôi, anh Murat, sẽ phụ trách lắp đặt quầy trưng bày máy in.","units":[{"en":"We're happy to be here.","vi":"Chúng tôi rất vui khi được có mặt tại đây."},{"en":"Our printers are perfect for students or people with home offices who may have limited space.","vi":"Máy in của chúng tôi rất lý tưởng cho sinh viên hoặc những người làm việc tại nhà có không gian hạn chế."},{"en":"My partner, Murat, will be setting up the printer station.","vi":"Cộng sự của tôi, anh Murat, sẽ phụ trách lắp đặt quầy trưng bày máy in."}]},{"speaker":"M2 (M-Au)","en":"Yes—where can I put our demonstration table?","vi":"Vâng — tôi có thể đặt bàn trình diễn sản phẩm của chúng tôi ở đâu ạ?","units":[{"en":"Yes—where can I put our demonstration table?","vi":"Vâng — tôi có thể đặt bàn trình diễn sản phẩm của chúng tôi ở đâu ạ?"}]},{"speaker":"W-Am","en":"I'll show you the area. Also, if you brought any brochures with you, it'll be helpful to put those out for people to take.","vi":"Tôi sẽ chỉ cho các anh khu vực đó. Ngoài ra, nếu các anh có mang theo tờ rơi giới thiệu, sẽ rất hữu ích nếu bày chúng ra để khách hàng có thể lấy xem.","units":[{"en":"I'll show you the area.","vi":"Tôi sẽ chỉ cho các anh khu vực đó."},{"en":"Also, if you brought any brochures with you, it'll be helpful to put those out for people to take.","vi":"Ngoài ra, nếu các anh có mang theo tờ rơi giới thiệu, sẽ rất hữu ích nếu bày chúng ra để khách hàng có thể lấy xem."}]}],"vocab":[{"word":"brochure","pos":"n","ipa":"/broʊˈʃʊr/","meaning":"tờ rơi, tập sách nhỏ giới thiệu"},{"word":"put out","pos":"phr. v","ipa":"/pʊt ˈaʊt/","meaning":"bày ra, đặt ra ngoài"},{"word":"informational","pos":"adj","ipa":"/ˌɪnfərˈmeɪʃənəl/","meaning":"cung cấp thông tin"}],"isScanBacked":false,"grammarType":"Part 3 — Hành động tiếp theo & Đề xuất (Next Step & Offer/Request)","formula":"CÔNG THỨC PART 3 (Gợi ý cuối bài với \"it'll be helpful to\"): Cấu trúc \"it'll be helpful to put [brochures] out for people to take\" mang chức năng đề xuất và được paraphrase thành \"Displaying informational materials\" (put out = display; brochures = informational materials).","optionAnalysis":{"A":"Bẫy thông tin nền: Cửa hàng đang giảm giá laptop và tablet (\"having a big sale\"), nhưng người phụ nữ không đề xuất hai anh giảm giá máy in.","B":"Chính xác: \"put those [brochures] out for people to take\" được paraphrase chuẩn xác thành \"Displaying informational materials\".","C":"Thông tin không có trong bài: Không có cuộc thi hay chương trình bốc thăm trúng thưởng nào được đề xuất.","D":"Bẫy lặp từ \"table\": Hội thoại chỉ có \"demonstration table\" (bàn trình diễn máy in), không có bàn đăng ký sự kiện nào."},"evDocIdx":0,"evTargets":[{"badge":"Câu 46 · Đáp án B","opt":"B","isCorrect":true,"quote":"Also, if you brought any brochures with you, it'll be helpful to put those out for people to take.","viQuote":"Ngoài ra, nếu các anh có mang theo tờ rơi giới thiệu, sẽ rất hữu ích nếu bày chúng ra để khách hàng có thể lấy xem."}],"evQuotes":["Also, if you brought any brochures with you, it'll be helpful to put those out for people to take."]},{"q":47,"part":3,"group_id":"E25_T01_G47_49","audio":"web_assets/ets2025/audio/E25_T01/track_37.mp3","graphicImg":null,"transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_11.webp","web_assets/ets2025/tr/E25_T01_tr_12.webp"],"stem_en":"What type of industry do the speakers most likely work in?","stem_vi":"Những người nói có khả năng làm việc trong lĩnh vực nào nhất?","options":{"A":{"en":"Textile manufacturing","vi":"Sản xuất dệt may"},"B":{"en":"Food production","vi":"Sản xuất thực phẩm"},"C":{"en":"Health care","vi":"Chăm sóc sức khỏe"},"D":{"en":"Hospitality","vi":"Dịch vụ nhà hàng - khách sạn"}},"ans":"B","explanation":"Đáp án đúng: (B) Sản xuất thực phẩm — Họ bàn về doanh số các nhãn hiệu bánh ngọt, bánh nướng, bánh quy và làm việc với nhà cung cấp nguyên liệu chất tạo ngọt.\nDẫn chứng: \"I'm very pleased with the sales of our brands of cakes, pies, and cookies this past holiday season.\" / \"One of our ingredient suppliers recently started offering a sweetener made entirely from natural ingredients.\" (Doanh số các dòng bánh ngọt, bánh nướng, bánh quy thuộc thương hiệu của chúng ta / Nhà cung cấp nguyên liệu vừa giới thiệu chất tạo ngọt tự nhiên → Ngành sản xuất thực phẩm \"Food production\").\nPhân tích bẫy:\n- (A) \"Textile manufacturing\" (sản xuất dệt may) sai loại hàng hóa vì họ làm bánh và xử lý nguyên liệu đường/chất tạo ngọt, không phải vải vóc.\n- (C) \"Health care\" (chăm sóc sức khỏe) là bẫy liên tưởng từ cụm \"reduction of sugar\" và \"healthier products\", nhưng đó chỉ là xu hướng sản phẩm bánh kẹo ít đường.\n- (D) \"Hospitality\" (nhà hàng - khách sạn) là bẫy gần nghĩa khi nhắc đến đồ ăn, nhưng cụm \"our brands of cakes\" và \"ingredient suppliers\" cho thấy đây là doanh nghiệp sản xuất thực phẩm đóng gói/thương hiệu.","lines":[{"speaker":"W1 (W-Am)","en":"Gizem and Hector, I'm very pleased with the sales of our brands of cakes, pies, and cookies this past holiday season. Any thoughts on what we should be concentrating on going forward?","vi":"Gizem và Hector à, tôi rất hài lòng với doanh số bán hàng của các dòng bánh ngọt, bánh nướng và bánh quy thuộc thương hiệu của chúng ta trong mùa lễ vừa qua. Hai bạn có ý kiến gì về việc chúng ta nên tập trung vào điều gì trong thời gian tới không?","units":[{"en":"Gizem and Hector, I'm very pleased with the sales of our brands of cakes, pies, and cookies this past holiday season.","vi":"Gizem và Hector à, tôi rất hài lòng với doanh số bán hàng của các dòng bánh ngọt, bánh nướng và bánh quy thuộc thương hiệu của chúng ta trong mùa lễ vừa qua."},{"en":"Any thoughts on what we should be concentrating on going forward?","vi":"Hai bạn có ý kiến gì về việc chúng ta nên tập trung vào điều gì trong thời gian tới không?"}]},{"speaker":"W2 (W-Br)","en":"The biggest trend right now is the reduction of sugar. The public wants healthier products, but the same great taste. That'll be our biggest challenge.","vi":"Xu hướng lớn nhất hiện nay là cắt giảm lượng đường. Người tiêu dùng mong muốn các sản phẩm tốt cho sức khỏe hơn nhưng vẫn giữ nguyên hương vị thơm ngon như cũ. Đó sẽ là thách thức lớn nhất của chúng ta.","units":[{"en":"The biggest trend right now is the reduction of sugar.","vi":"Xu hướng lớn nhất hiện nay là cắt giảm lượng đường."},{"en":"The public wants healthier products, but the same great taste.","vi":"Người tiêu dùng mong muốn các sản phẩm tốt cho sức khỏe hơn nhưng vẫn giữ nguyên hương vị thơm ngon như cũ."},{"en":"That'll be our biggest challenge.","vi":"Đó sẽ là thách thức lớn nhất của chúng ta."}]},{"speaker":"M-Cn","en":"One of our ingredient suppliers recently started offering a sweetener made entirely from natural ingredients.","vi":"Một trong những nhà cung cấp nguyên liệu của chúng ta gần đây đã bắt đầu cung cấp một loại chất tạo ngọt được làm hoàn toàn từ nguyên liệu tự nhiên.","units":[{"en":"One of our ingredient suppliers recently started offering a sweetener made entirely from natural ingredients.","vi":"Một trong những nhà cung cấp nguyên liệu của chúng ta gần đây đã bắt đầu cung cấp một loại chất tạo ngọt được làm hoàn toàn từ nguyên liệu tự nhiên."}]},{"speaker":"W1 (W-Am)","en":"Are there similar ones on the market? And how do they compare?","vi":"Trên thị trường có những sản phẩm tương tự không? Và khi so sánh thì chúng như thế nào?","units":[{"en":"Are there similar ones on the market?","vi":"Trên thị trường có những sản phẩm tương tự không?"},{"en":"And how do they compare?","vi":"Và khi so sánh thì chúng như thế nào?"}]},{"speaker":"M-Cn","en":"I'd have to do some investigation to find out more about that. I have some time available tomorrow afternoon.","vi":"Tôi sẽ phải tìm hiểu kỹ thêm để nắm rõ hơn về điều đó. Chiều mai tôi có chút thời gian rảnh.","units":[{"en":"I'd have to do some investigation to find out more about that.","vi":"Tôi sẽ phải tìm hiểu kỹ thêm để nắm rõ hơn về điều đó."},{"en":"I have some time available tomorrow afternoon.","vi":"Chiều mai tôi có chút thời gian rảnh."}]}],"vocab":[{"word":"brand","pos":"n","ipa":"/brænd/","meaning":"thương hiệu, nhãn hiệu"},{"word":"ingredient","pos":"n","ipa":"/ɪnˈɡriːdiənt/","meaning":"nguyên liệu, thành phần"},{"word":"sweetener","pos":"n","ipa":"/ˈswiːtnər/","meaning":"chất tạo ngọt"},{"word":"going forward","pos":"phr","ipa":"/ˈɡoʊɪŋ ˈfɔːrwərd/","meaning":"trong thời gian tới"}],"isScanBacked":false,"grammarType":"Part 3 — Ngữ cảnh, Địa điểm & Danh tính người nói (Setting & Role)","formula":"CÔNG THỨC PART 3 (Phân biệt Sản xuất Thực phẩm vs Dịch vụ Khách sạn): Khi có các danh từ \"our brands of cakes, pies, and cookies\" cùng \"ingredient suppliers\" (nhà cung cấp nguyên liệu), bối cảnh là công ty sản xuất thực phẩm (\"Food production\"), không phải nhà hàng.","optionAnalysis":{"A":"Sai sản phẩm: Cuộc họp bàn về bánh ngọt, bánh quy và chất tạo ngọt tự nhiên, hoàn toàn không liên quan đến ngành dệt may.","B":"Chính xác: Các từ khóa \"our brands of cakes, pies, and cookies\" và \"ingredient suppliers\" xác định rõ ngành sản xuất thực phẩm.","C":"Bẫy liên tưởng \"healthier products\": Dù nhắc việc giảm đường để sản phẩm lành mạnh hơn, họ vẫn là công ty sản xuất bánh kẹo chứ không thuộc ngành y tế.","D":"Bẫy nhầm mô hình F&B: Họ phát triển thương hiệu sản phẩm (\"our brands\") và làm việc với nhà cung cấp nguyên liệu chứ không vận hành khách sạn hay nhà hàng."},"evDocIdx":0,"evTargets":[{"badge":"Câu 47 · Đáp án B","opt":"B","isCorrect":true,"quote":"Gizem and Hector, I'm very pleased with the sales of our brands of cakes, pies, and cookies this past holiday season.","viQuote":"Gizem và Hector à, tôi rất hài lòng với doanh số bán hàng của các dòng bánh ngọt, bánh nướng và bánh quy thuộc thương hiệu của chúng ta trong mùa lễ vừa qua."},{"badge":"Câu 47 · Đáp án B","opt":"B","isCorrect":true,"quote":"One of our ingredient suppliers recently started offering a sweetener made entirely from natural ingredients.","viQuote":"Một trong những nhà cung cấp nguyên liệu của chúng ta gần đây đã bắt đầu cung cấp một loại chất tạo ngọt được làm hoàn toàn từ nguyên liệu tự nhiên."}],"evQuotes":["Gizem and Hector, I'm very pleased with the sales of our brands of cakes, pies, and cookies this past holiday season.","One of our ingredient suppliers recently started offering a sweetener made entirely from natural ingredients."]},{"q":48,"part":3,"group_id":"E25_T01_G47_49","audio":"web_assets/ets2025/audio/E25_T01/track_37.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What business challenge are the speakers discussing?","stem_vi":"Những người nói đang thảo luận về thách thức kinh doanh nào?","options":{"A":{"en":"Lack of qualified personnel","vi":"Thiếu hụt nhân sự đủ trình độ"},"B":{"en":"Rising production costs","vi":"Chi phí sản xuất tăng cao"},"C":{"en":"Changes in consumer preferences","vi":"Sự thay đổi trong thị hiếu người tiêu dùng"},"D":{"en":"Increased competition","vi":"Sự cạnh tranh gia tăng"}},"ans":"C","explanation":"Đáp án đúng: (C) Sự thay đổi trong thị hiếu người tiêu dùng — Xu hướng hiện nay là cắt giảm đường vì công chúng muốn sản phẩm tốt cho sức khỏe hơn mà vẫn giữ nguyên vị ngon.\nDẫn chứng: \"The biggest trend right now is the reduction of sugar. The public wants healthier products, but the same great taste. That'll be our biggest challenge.\" (Xu hướng lớn nhất hiện nay là giảm đường. Công chúng muốn sản phẩm lành mạnh hơn nhưng vị vẫn ngon. Đó sẽ là thách thức lớn nhất — \"trend / the public wants\" = \"Changes in consumer preferences\").\nPhân tích bẫy:\n- (A) \"Lack of qualified personnel\" (thiếu nhân sự đủ trình độ) không được nhắc đến; nhóm đang họp rất đầy đủ và chủ động phân công tìm hiểu nguyên liệu.\n- (B) \"Rising production costs\" (chi phí sản xuất tăng cao) là bẫy suy diễn thường gặp khi nhắc tới nguyên liệu tự nhiên mới, nhưng bài nghe không hề nói tới giá thành hay chi phí.\n- (D) \"Increased competition\" (sự cạnh tranh gia tăng) bẫy từ câu hỏi \"Are there similar ones on the market?\" của W1, nhưng câu đó hỏi về các loại chất tạo ngọt cùng loại từ nhà cung cấp chứ không nói doanh số bánh bị đối thủ cạnh tranh đe dọa.","lines":[{"speaker":"W1 (W-Am)","en":"Gizem and Hector, I'm very pleased with the sales of our brands of cakes, pies, and cookies this past holiday season. Any thoughts on what we should be concentrating on going forward?","vi":"Gizem và Hector à, tôi rất hài lòng với doanh số bán hàng của các dòng bánh ngọt, bánh nướng và bánh quy thuộc thương hiệu của chúng ta trong mùa lễ vừa qua. Hai bạn có ý kiến gì về việc chúng ta nên tập trung vào điều gì trong thời gian tới không?","units":[{"en":"Gizem and Hector, I'm very pleased with the sales of our brands of cakes, pies, and cookies this past holiday season.","vi":"Gizem và Hector à, tôi rất hài lòng với doanh số bán hàng của các dòng bánh ngọt, bánh nướng và bánh quy thuộc thương hiệu của chúng ta trong mùa lễ vừa qua."},{"en":"Any thoughts on what we should be concentrating on going forward?","vi":"Hai bạn có ý kiến gì về việc chúng ta nên tập trung vào điều gì trong thời gian tới không?"}]},{"speaker":"W2 (W-Br)","en":"The biggest trend right now is the reduction of sugar. The public wants healthier products, but the same great taste. That'll be our biggest challenge.","vi":"Xu hướng lớn nhất hiện nay là cắt giảm lượng đường. Người tiêu dùng mong muốn các sản phẩm tốt cho sức khỏe hơn nhưng vẫn giữ nguyên hương vị thơm ngon như cũ. Đó sẽ là thách thức lớn nhất của chúng ta.","units":[{"en":"The biggest trend right now is the reduction of sugar.","vi":"Xu hướng lớn nhất hiện nay là cắt giảm lượng đường."},{"en":"The public wants healthier products, but the same great taste.","vi":"Người tiêu dùng mong muốn các sản phẩm tốt cho sức khỏe hơn nhưng vẫn giữ nguyên hương vị thơm ngon như cũ."},{"en":"That'll be our biggest challenge.","vi":"Đó sẽ là thách thức lớn nhất của chúng ta."}]},{"speaker":"M-Cn","en":"One of our ingredient suppliers recently started offering a sweetener made entirely from natural ingredients.","vi":"Một trong những nhà cung cấp nguyên liệu của chúng ta gần đây đã bắt đầu cung cấp một loại chất tạo ngọt được làm hoàn toàn từ nguyên liệu tự nhiên.","units":[{"en":"One of our ingredient suppliers recently started offering a sweetener made entirely from natural ingredients.","vi":"Một trong những nhà cung cấp nguyên liệu của chúng ta gần đây đã bắt đầu cung cấp một loại chất tạo ngọt được làm hoàn toàn từ nguyên liệu tự nhiên."}]},{"speaker":"W1 (W-Am)","en":"Are there similar ones on the market? And how do they compare?","vi":"Trên thị trường có những sản phẩm tương tự không? Và khi so sánh thì chúng như thế nào?","units":[{"en":"Are there similar ones on the market?","vi":"Trên thị trường có những sản phẩm tương tự không?"},{"en":"And how do they compare?","vi":"Và khi so sánh thì chúng như thế nào?"}]},{"speaker":"M-Cn","en":"I'd have to do some investigation to find out more about that. I have some time available tomorrow afternoon.","vi":"Tôi sẽ phải tìm hiểu kỹ thêm để nắm rõ hơn về điều đó. Chiều mai tôi có chút thời gian rảnh.","units":[{"en":"I'd have to do some investigation to find out more about that.","vi":"Tôi sẽ phải tìm hiểu kỹ thêm để nắm rõ hơn về điều đó."},{"en":"I have some time available tomorrow afternoon.","vi":"Chiều mai tôi có chút thời gian rảnh."}]}],"vocab":[{"word":"public","pos":"n","ipa":"/ˈpʌblɪk/","meaning":"công chúng, người tiêu dùng"},{"word":"reduction","pos":"n","ipa":"/rɪˈdʌkʃən/","meaning":"sự cắt giảm"},{"word":"consumer preference","pos":"n","ipa":"/kənˈsuːmər ˈprefərəns/","meaning":"thị hiếu người tiêu dùng"},{"word":"challenge","pos":"n","ipa":"/ˈtʃælɪndʒ/","meaning":"thách thức"}],"isScanBacked":false,"grammarType":"Part 3 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 3 (Paraphrase xu hướng thị trường): Các cụm \"The biggest trend right now\", \"The public wants healthier products\" liên kết trực tiếp với câu kết \"That'll be our biggest challenge\" → Paraphrase \"the public wants\" thành \"consumer preferences\".","optionAnalysis":{"A":"Không có dữ kiện: Hội thoại không nhắc đến việc tuyển dụng hay thiếu hụt nhân sự có chuyên môn.","B":"Bẫy suy diễn chi phí: Bài nghe đề cập đến chất tạo ngọt tự nhiên mới nhưng không hề nói nguyên liệu đó đắt hơn hay làm tăng chi phí sản xuất.","C":"Chính xác: \"The biggest trend right now is the reduction of sugar. The public wants healthier products\" được diễn đạt lại thành \"Changes in consumer preferences\".","D":"Bẫy hiểu nhầm câu hỏi về thị trường: W1 hỏi \"Are there similar ones on the market?\" để so sánh các chất tạo ngọt tự nhiên, không nói về áp lực cạnh tranh đối thủ."},"evDocIdx":0,"evTargets":[{"badge":"Câu 48 · Đáp án C","opt":"C","isCorrect":true,"quote":"The biggest trend right now is the reduction of sugar.","viQuote":"Xu hướng lớn nhất hiện nay là cắt giảm lượng đường."},{"badge":"Câu 48 · Đáp án C","opt":"C","isCorrect":true,"quote":"The public wants healthier products, but the same great taste.","viQuote":"Người tiêu dùng mong muốn các sản phẩm tốt cho sức khỏe hơn nhưng vẫn giữ nguyên hương vị thơm ngon như cũ."}],"evQuotes":["The biggest trend right now is the reduction of sugar.","The public wants healthier products, but the same great taste."]},{"q":49,"part":3,"group_id":"E25_T01_G47_49","audio":"web_assets/ets2025/audio/E25_T01/track_37.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the man say he will do?","stem_vi":"Người đàn ông nói anh ấy sẽ làm gì?","options":{"A":{"en":"Research more information","vi":"Nghiên cứu thêm thông tin"},"B":{"en":"Negotiate a discount","vi":"Thương lượng mức giảm giá"},"C":{"en":"Upgrade some machinery","vi":"Nâng cấp một số máy móc"},"D":{"en":"Train a new employee","vi":"Đào tạo một nhân viên mới"}},"ans":"A","explanation":"Đáp án đúng: (A) Nghiên cứu thêm thông tin — Người đàn ông (Hector) cho biết anh sẽ dành thời gian vào chiều mai để tìm hiểu thêm về các chất tạo ngọt cùng loại trên thị trường.\nDẫn chứng: \"I'd have to do some investigation to find out more about that. I have some time available tomorrow afternoon.\" (Tôi sẽ phải tìm hiểu thêm để biết rõ hơn về điều đó. Chiều mai tôi có thời gian rảnh — \"do some investigation / find out more\" = \"Research more information\").\nPhân tích bẫy:\n- (B) \"Negotiate a discount\" (thương lượng giảm giá) sai vì ở bước này họ mới tìm hiểu tính năng và so sánh chất tạo ngọt trên thị trường, chưa bàn đến giá cả hay đặt mua.\n- (C) \"Upgrade some machinery\" (nâng cấp máy móc) không xuất hiện; thảo luận chỉ xoay quanh công thức và nguyên liệu chất tạo ngọt.\n- (D) \"Train a new employee\" (đào tạo nhân viên mới) hoàn toàn không có trong ngữ cảnh cuộc họp chiến lược sản phẩm.","lines":[{"speaker":"W1 (W-Am)","en":"Gizem and Hector, I'm very pleased with the sales of our brands of cakes, pies, and cookies this past holiday season. Any thoughts on what we should be concentrating on going forward?","vi":"Gizem và Hector à, tôi rất hài lòng với doanh số bán hàng của các dòng bánh ngọt, bánh nướng và bánh quy thuộc thương hiệu của chúng ta trong mùa lễ vừa qua. Hai bạn có ý kiến gì về việc chúng ta nên tập trung vào điều gì trong thời gian tới không?","units":[{"en":"Gizem and Hector, I'm very pleased with the sales of our brands of cakes, pies, and cookies this past holiday season.","vi":"Gizem và Hector à, tôi rất hài lòng với doanh số bán hàng của các dòng bánh ngọt, bánh nướng và bánh quy thuộc thương hiệu của chúng ta trong mùa lễ vừa qua."},{"en":"Any thoughts on what we should be concentrating on going forward?","vi":"Hai bạn có ý kiến gì về việc chúng ta nên tập trung vào điều gì trong thời gian tới không?"}]},{"speaker":"W2 (W-Br)","en":"The biggest trend right now is the reduction of sugar. The public wants healthier products, but the same great taste. That'll be our biggest challenge.","vi":"Xu hướng lớn nhất hiện nay là cắt giảm lượng đường. Người tiêu dùng mong muốn các sản phẩm tốt cho sức khỏe hơn nhưng vẫn giữ nguyên hương vị thơm ngon như cũ. Đó sẽ là thách thức lớn nhất của chúng ta.","units":[{"en":"The biggest trend right now is the reduction of sugar.","vi":"Xu hướng lớn nhất hiện nay là cắt giảm lượng đường."},{"en":"The public wants healthier products, but the same great taste.","vi":"Người tiêu dùng mong muốn các sản phẩm tốt cho sức khỏe hơn nhưng vẫn giữ nguyên hương vị thơm ngon như cũ."},{"en":"That'll be our biggest challenge.","vi":"Đó sẽ là thách thức lớn nhất của chúng ta."}]},{"speaker":"M-Cn","en":"One of our ingredient suppliers recently started offering a sweetener made entirely from natural ingredients.","vi":"Một trong những nhà cung cấp nguyên liệu của chúng ta gần đây đã bắt đầu cung cấp một loại chất tạo ngọt được làm hoàn toàn từ nguyên liệu tự nhiên.","units":[{"en":"One of our ingredient suppliers recently started offering a sweetener made entirely from natural ingredients.","vi":"Một trong những nhà cung cấp nguyên liệu của chúng ta gần đây đã bắt đầu cung cấp một loại chất tạo ngọt được làm hoàn toàn từ nguyên liệu tự nhiên."}]},{"speaker":"W1 (W-Am)","en":"Are there similar ones on the market? And how do they compare?","vi":"Trên thị trường có những sản phẩm tương tự không? Và khi so sánh thì chúng như thế nào?","units":[{"en":"Are there similar ones on the market?","vi":"Trên thị trường có những sản phẩm tương tự không?"},{"en":"And how do they compare?","vi":"Và khi so sánh thì chúng như thế nào?"}]},{"speaker":"M-Cn","en":"I'd have to do some investigation to find out more about that. I have some time available tomorrow afternoon.","vi":"Tôi sẽ phải tìm hiểu kỹ thêm để nắm rõ hơn về điều đó. Chiều mai tôi có chút thời gian rảnh.","units":[{"en":"I'd have to do some investigation to find out more about that.","vi":"Tôi sẽ phải tìm hiểu kỹ thêm để nắm rõ hơn về điều đó."},{"en":"I have some time available tomorrow afternoon.","vi":"Chiều mai tôi có chút thời gian rảnh."}]}],"vocab":[{"word":"investigation","pos":"n","ipa":"/ɪnˌvestɪˈɡeɪʃən/","meaning":"việc tìm hiểu, nghiên cứu"},{"word":"compare","pos":"v","ipa":"/kəmˈper/","meaning":"so sánh"},{"word":"negotiate","pos":"v","ipa":"/nɪˈɡoʊʃieɪt/","meaning":"đàm phán, thương lượng"}],"isScanBacked":false,"grammarType":"Part 3 — Hành động tiếp theo & Đề xuất (Next Step & Offer/Request)","formula":"CÔNG THỨC PART 3 (Bắt tín hiệu hành động ở câu cuối): Khi người nói đáp lại câu hỏi bằng \"I'd have to do some investigation to find out more about that\", cụm \"do some investigation / find out more\" tương ứng với \"Research more information\".","optionAnalysis":{"A":"Chính xác: Cụm \"do some investigation to find out more about that\" được paraphrase trực tiếp thành \"Research more information\".","B":"Bẫy suy diễn bước mua hàng: Nhóm mới dừng ở bước tìm hiểu so sánh chất tạo ngọt, chưa hề nhắc đến đàm phán giá hay giảm giá với nhà cung cấp.","C":"Sai phạm vi giải pháp: Thách thức giảm đường được giải quyết bằng cách đổi nguyên liệu tạo ngọt, không phải nâng cấp thiết bị máy móc.","D":"Thông tin bịa đặt: Cuộc họp có sẵn các thành viên phụ trách (Gizem và Hector) và không hề nhắc đến nhân viên mới cần đào tạo."},"evDocIdx":0,"evTargets":[{"badge":"Câu 49 · Đáp án A","opt":"A","isCorrect":true,"quote":"I'd have to do some investigation to find out more about that.","viQuote":"Tôi sẽ phải tìm hiểu kỹ thêm để nắm rõ hơn về điều đó."}],"evQuotes":["I'd have to do some investigation to find out more about that."]},{"q":50,"part":3,"group_id":"E25_T01_G50_52","audio":"web_assets/ets2025/audio/E25_T01/track_38.mp3","graphicImg":null,"transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_12.webp","web_assets/ets2025/tr/E25_T01_tr_13.webp"],"stem_en":"Why is the man calling?","stem_vi":"Tại sao người đàn ông lại gọi điện?","options":{"A":{"en":"To explain a business merger","vi":"Để giải thích về một thương vụ sáp nhập doanh nghiệp"},"B":{"en":"To describe a new company policy","vi":"Để trình bày về một chính sách mới của công ty"},"C":{"en":"To offer the woman a work assignment","vi":"Để đề nghị giao một dự án công việc cho người phụ nữ"},"D":{"en":"To invite the woman to speak at a conference","vi":"Để mời người phụ nữ phát biểu tại một hội nghị"}},"ans":"C","explanation":"Đáp án đúng: (C) Để đề nghị giao một dự án công việc cho người phụ nữ — ngay đầu cuộc gọi, người đàn ông hỏi xem Bianca có thời gian tham gia một dự án cho công ty tiếp thị của anh không và giải thích cô sẽ giám sát chiến dịch.\nDẫn chứng: \"I'm calling to see if you'd have time to work on a project for my marketing firm.\" và \"You'd be overseeing the campaign.\" (work on a project / overseeing the campaign → offer a work assignment).\nPhân tích bẫy:\n- (A) Bẫy suy diễn sai từ chi tiết công ty mở rộng quy mô (\"expanded a lot in the past year\"); bài nghe không hề nhắc đến sáp nhập doanh nghiệp.\n- (B) Không có nội dung nào đề cập đến chính sách nội bộ mới của công ty; cuộc gọi hoàn toàn xoay quanh dự án cho khách hàng mới.\n- (D) Sai hoàn toàn bản chất lời mời; người đàn ông muốn mời cô phụ trách dự án chiến dịch tiếp thị chứ không mời phát biểu tại hội nghị.","lines":[{"speaker":"M-Au","en":"Hi, Bianca. I'm calling to see if you'd have time to work on a project for my marketing firm. We've expanded a lot in the past year, and we need some help.","vi":"Chào Bianca. Tôi gọi để hỏi xem bạn có thời gian tham gia một dự án cho công ty tiếp thị của tôi không. Trong năm qua chúng tôi đã mở rộng quy mô rất nhiều và đang cần thêm người hỗ trợ.","units":[{"en":"Hi, Bianca.","vi":"Chào Bianca."},{"en":"I'm calling to see if you'd have time to work on a project for my marketing firm.","vi":"Tôi gọi để hỏi xem bạn có thời gian tham gia một dự án cho công ty tiếp thị của tôi không."},{"en":"We've expanded a lot in the past year, and we need some help.","vi":"Trong năm qua chúng tôi đã mở rộng quy mô rất nhiều và đang cần thêm người hỗ trợ."}]},{"speaker":"W-Am","en":"Thanks for thinking of me. What type of work would I be doing?","vi":"Cảm ơn bạn đã nghĩ đến tôi. Cụ thể thì tôi sẽ đảm nhận công việc gì?","units":[{"en":"Thanks for thinking of me.","vi":"Cảm ơn bạn đã nghĩ đến tôi."},{"en":"What type of work would I be doing?","vi":"Cụ thể thì tôi sẽ đảm nhận công việc gì?"}]},{"speaker":"M-Au","en":"Well, we have a new client in Brazil who's interested in creating a marketing campaign for social media sites. You'd be overseeing the campaign.","vi":"À, chúng tôi có một khách hàng mới ở Brazil đang muốn xây dựng một chiến dịch tiếp thị cho các trang mạng xã hội. Bạn sẽ phụ trách giám sát chiến dịch đó.","units":[{"en":"Well, we have a new client in Brazil who's interested in creating a marketing campaign for social media sites.","vi":"À, chúng tôi có một khách hàng mới ở Brazil đang muốn xây dựng một chiến dịch tiếp thị cho các trang mạng xã hội."},{"en":"You'd be overseeing the campaign.","vi":"Bạn sẽ phụ trách giám sát chiến dịch đó."}]},{"speaker":"W-Am","en":"Oh, I have experience with that. Why don't you send me a detailed description of the work? That'll give me an idea of how much time this project will take.","vi":"Ồ, tôi có kinh nghiệm trong mảng này đấy. Hay là bạn gửi cho tôi bản mô tả chi tiết công việc đi? Nhờ đó tôi sẽ ước lượng được dự án này cần bao nhiêu thời gian.","units":[{"en":"Oh, I have experience with that.","vi":"Ồ, tôi có kinh nghiệm trong mảng này đấy."},{"en":"Why don't you send me a detailed description of the work?","vi":"Hay là bạn gửi cho tôi bản mô tả chi tiết công việc đi?"},{"en":"That'll give me an idea of how much time this project will take.","vi":"Nhờ đó tôi sẽ ước lượng được dự án này cần bao nhiêu thời gian."}]}],"vocab":[{"word":"marketing firm","pos":"n","ipa":"/ˈmɑːrkɪtɪŋ fɜːrm/","meaning":"công ty tiếp thị"},{"word":"expand","pos":"v","ipa":"/ɪkˈspænd/","meaning":"mở rộng quy mô"},{"word":"oversee","pos":"v","ipa":"/ˌoʊvərˈsiː/","meaning":"giám sát, phụ trách"},{"word":"assignment","pos":"n","ipa":"/əˈsaɪnmənt/","meaning":"nhiệm vụ, dự án được giao"}],"isScanBacked":false,"grammarType":"Part 3 — Ý chính & Mục đích (Gist & Purpose)","formula":"CÔNG THỨC PART 3 (Ý chính & Mục đích cuộc gọi): Nghe câu mở đầu sau lời chào (\"I'm calling to see if you'd have time\") kết hợp phần mô tả vai trò người nghe (\"overseeing the campaign\") -> Paraphrase thành mục đích giao dự án công việc (offer a work assignment).","optionAnalysis":{"A":"Bẫy suy diễn sai từ chi tiết \"expanded a lot in the past year\"; bài nghe không đề cập đến thương vụ sáp nhập doanh nghiệp nào.","B":"Không có thông tin về chính sách mới của công ty; mục đích cuộc gọi là tìm người giám sát dự án tiếp thị.","C":"Khớp trực tiếp lời thoại mở đầu: \"I'm calling to see if you'd have time to work on a project for my marketing firm\" và \"You'd be overseeing the campaign\".","D":"Sai nội dung lời mời; anh ấy mời Bianca giám sát chiến dịch mạng xã hội chứ không mời diễn thuyết tại hội nghị."},"evDocIdx":0,"evTargets":[{"badge":"Câu 50 · Đáp án C","opt":"C","isCorrect":true,"quote":"I'm calling to see if you'd have time to work on a project for my marketing firm.","viQuote":"Tôi gọi để hỏi xem bạn có thời gian tham gia một dự án cho công ty tiếp thị của tôi không."},{"badge":"Câu 50 · Đáp án C","opt":"C","isCorrect":true,"quote":"You'd be overseeing the campaign.","viQuote":"Bạn sẽ phụ trách giám sát chiến dịch đó."}],"evQuotes":["I'm calling to see if you'd have time to work on a project for my marketing firm.","You'd be overseeing the campaign."]},{"q":51,"part":3,"group_id":"E25_T01_G50_52","audio":"web_assets/ets2025/audio/E25_T01/track_38.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the man say a client is interested in doing?","stem_vi":"Người đàn ông nói một khách hàng đang quan tâm đến việc gì?","options":{"A":{"en":"Purchasing another business","vi":"Mua lại một doanh nghiệp khác"},"B":{"en":"Finding a new office space","vi":"Tìm một không gian văn phòng mới"},"C":{"en":"Revising a budget proposal","vi":"Chỉnh sửa một đề xuất ngân sách"},"D":{"en":"Creating a marketing campaign","vi":"Xây dựng một chiến dịch tiếp thị"}},"ans":"D","explanation":"Đáp án đúng: (D) Xây dựng một chiến dịch tiếp thị — khi người phụ nữ hỏi cụ thể sẽ làm gì, người đàn ông nêu rõ công ty có khách hàng mới ở Brazil muốn lập một chiến dịch tiếp thị trên mạng xã hội.\nDẫn chứng: \"Well, we have a new client in Brazil who's interested in creating a marketing campaign for social media sites.\" (khớp nguyên cụm từ khóa \"creating a marketing campaign\").\nPhân tích bẫy:\n- (A) Bẫy đánh lạc hướng dựa vào chi tiết mở rộng quy mô công ty ở lượt đầu; khách hàng ở Brazil không có ý định mua lại doanh nghiệp khác.\n- (B) Tự suy đoán không có căn cứ từ việc công ty phát triển; hội thoại không nhắc đến việc khách hàng tìm thuê không gian văn phòng mới.\n- (C) Chi tiết chỉnh sửa đề xuất ngân sách không xuất hiện trong lời thoại; nhu cầu của khách hàng là tạo chiến dịch quảng bá trực tuyến.","lines":[{"speaker":"M-Au","en":"Hi, Bianca. I'm calling to see if you'd have time to work on a project for my marketing firm. We've expanded a lot in the past year, and we need some help.","vi":"Chào Bianca. Tôi gọi để hỏi xem bạn có thời gian tham gia một dự án cho công ty tiếp thị của tôi không. Trong năm qua chúng tôi đã mở rộng quy mô rất nhiều và đang cần thêm người hỗ trợ.","units":[{"en":"Hi, Bianca.","vi":"Chào Bianca."},{"en":"I'm calling to see if you'd have time to work on a project for my marketing firm.","vi":"Tôi gọi để hỏi xem bạn có thời gian tham gia một dự án cho công ty tiếp thị của tôi không."},{"en":"We've expanded a lot in the past year, and we need some help.","vi":"Trong năm qua chúng tôi đã mở rộng quy mô rất nhiều và đang cần thêm người hỗ trợ."}]},{"speaker":"W-Am","en":"Thanks for thinking of me. What type of work would I be doing?","vi":"Cảm ơn bạn đã nghĩ đến tôi. Cụ thể thì tôi sẽ đảm nhận công việc gì?","units":[{"en":"Thanks for thinking of me.","vi":"Cảm ơn bạn đã nghĩ đến tôi."},{"en":"What type of work would I be doing?","vi":"Cụ thể thì tôi sẽ đảm nhận công việc gì?"}]},{"speaker":"M-Au","en":"Well, we have a new client in Brazil who's interested in creating a marketing campaign for social media sites. You'd be overseeing the campaign.","vi":"À, chúng tôi có một khách hàng mới ở Brazil đang muốn xây dựng một chiến dịch tiếp thị cho các trang mạng xã hội. Bạn sẽ phụ trách giám sát chiến dịch đó.","units":[{"en":"Well, we have a new client in Brazil who's interested in creating a marketing campaign for social media sites.","vi":"À, chúng tôi có một khách hàng mới ở Brazil đang muốn xây dựng một chiến dịch tiếp thị cho các trang mạng xã hội."},{"en":"You'd be overseeing the campaign.","vi":"Bạn sẽ phụ trách giám sát chiến dịch đó."}]},{"speaker":"W-Am","en":"Oh, I have experience with that. Why don't you send me a detailed description of the work? That'll give me an idea of how much time this project will take.","vi":"Ồ, tôi có kinh nghiệm trong mảng này đấy. Hay là bạn gửi cho tôi bản mô tả chi tiết công việc đi? Nhờ đó tôi sẽ ước lượng được dự án này cần bao nhiêu thời gian.","units":[{"en":"Oh, I have experience with that.","vi":"Ồ, tôi có kinh nghiệm trong mảng này đấy."},{"en":"Why don't you send me a detailed description of the work?","vi":"Hay là bạn gửi cho tôi bản mô tả chi tiết công việc đi?"},{"en":"That'll give me an idea of how much time this project will take.","vi":"Nhờ đó tôi sẽ ước lượng được dự án này cần bao nhiêu thời gian."}]}],"vocab":[{"word":"campaign","pos":"n","ipa":"/kæmˈpeɪn/","meaning":"chiến dịch"},{"word":"social media","pos":"n","ipa":"/ˈsoʊʃəl ˈmiːdiə/","meaning":"mạng xã hội"},{"word":"proposal","pos":"n","ipa":"/prəˈpoʊzəl/","meaning":"bản đề xuất"}],"isScanBacked":false,"grammarType":"Part 3 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 3 (Chi tiết cụ thể theo câu hỏi What): Bám sát từ khóa \"a client is interested in\" khi người đàn ông trả lời câu hỏi loại hình công việc -> Chốt cụm động từ ngay sau \"who's interested in\".","optionAnalysis":{"A":"Bẫy suy đoán từ việc công ty tiếp thị mở rộng quy mô; khách hàng mới ở Brazil không hề muốn mua lại doanh nghiệp khác.","B":"Thông tin tìm văn phòng mới không có trong bài; công ty chỉ đang tìm nhân sự phụ trách chiến dịch cho khách hàng.","C":"Không nhắc đến đề xuất ngân sách hay việc chỉnh sửa tài chính nào trong suốt cuộc trò chuyện.","D":"Trùng khớp trực tiếp với lời người đàn ông: \"a new client in Brazil who's interested in creating a marketing campaign for social media sites\"."},"evDocIdx":0,"evTargets":[{"badge":"Câu 51 · Đáp án D","opt":"D","isCorrect":true,"quote":"Well, we have a new client in Brazil who's interested in creating a marketing campaign for social media sites.","viQuote":"À, chúng tôi có một khách hàng mới ở Brazil đang muốn xây dựng một chiến dịch tiếp thị cho các trang mạng xã hội."}],"evQuotes":["Well, we have a new client in Brazil who's interested in creating a marketing campaign for social media sites."]},{"q":52,"part":3,"group_id":"E25_T01_G50_52","audio":"web_assets/ets2025/audio/E25_T01/track_38.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the woman ask the man to send?","stem_vi":"Người phụ nữ yêu cầu người đàn ông gửi thứ gì?","options":{"A":{"en":"A project description","vi":"Bản mô tả dự án"},"B":{"en":"An event invitation","vi":"Thư mời tham dự sự kiện"},"C":{"en":"Some social media links","vi":"Một số đường dẫn mạng xã hội"},"D":{"en":"Some contact information","vi":"Một số thông tin liên hệ"}},"ans":"A","explanation":"Đáp án đúng: (A) Bản mô tả dự án — ở lượt lời cuối cùng, Bianca đề nghị người đàn ông gửi cho cô bản mô tả chi tiết công việc để ước lượng thời gian thực hiện dự án.\nDẫn chứng: \"Why don't you send me a detailed description of the work? That'll give me an idea of how much time this project will take.\" (detailed description of the work → project description).\nPhân tích bẫy:\n- (B) Không có sự kiện nào được tổ chức hay nhắc tới trong hội thoại nên không có thư mời tham dự sự kiện.\n- (C) Bẫy lặp từ \"social media sites\" xuất hiện ở lượt nói trước đó của người đàn ông; Bianca không xin đường dẫn mạng xã hội.\n- (D) Hai người đã trao đổi qua điện thoại và biết nhau từ trước nên Bianca không yêu cầu gửi thông tin liên hệ.","lines":[{"speaker":"M-Au","en":"Hi, Bianca. I'm calling to see if you'd have time to work on a project for my marketing firm. We've expanded a lot in the past year, and we need some help.","vi":"Chào Bianca. Tôi gọi để hỏi xem bạn có thời gian tham gia một dự án cho công ty tiếp thị của tôi không. Trong năm qua chúng tôi đã mở rộng quy mô rất nhiều và đang cần thêm người hỗ trợ.","units":[{"en":"Hi, Bianca.","vi":"Chào Bianca."},{"en":"I'm calling to see if you'd have time to work on a project for my marketing firm.","vi":"Tôi gọi để hỏi xem bạn có thời gian tham gia một dự án cho công ty tiếp thị của tôi không."},{"en":"We've expanded a lot in the past year, and we need some help.","vi":"Trong năm qua chúng tôi đã mở rộng quy mô rất nhiều và đang cần thêm người hỗ trợ."}]},{"speaker":"W-Am","en":"Thanks for thinking of me. What type of work would I be doing?","vi":"Cảm ơn bạn đã nghĩ đến tôi. Cụ thể thì tôi sẽ đảm nhận công việc gì?","units":[{"en":"Thanks for thinking of me.","vi":"Cảm ơn bạn đã nghĩ đến tôi."},{"en":"What type of work would I be doing?","vi":"Cụ thể thì tôi sẽ đảm nhận công việc gì?"}]},{"speaker":"M-Au","en":"Well, we have a new client in Brazil who's interested in creating a marketing campaign for social media sites. You'd be overseeing the campaign.","vi":"À, chúng tôi có một khách hàng mới ở Brazil đang muốn xây dựng một chiến dịch tiếp thị cho các trang mạng xã hội. Bạn sẽ phụ trách giám sát chiến dịch đó.","units":[{"en":"Well, we have a new client in Brazil who's interested in creating a marketing campaign for social media sites.","vi":"À, chúng tôi có một khách hàng mới ở Brazil đang muốn xây dựng một chiến dịch tiếp thị cho các trang mạng xã hội."},{"en":"You'd be overseeing the campaign.","vi":"Bạn sẽ phụ trách giám sát chiến dịch đó."}]},{"speaker":"W-Am","en":"Oh, I have experience with that. Why don't you send me a detailed description of the work? That'll give me an idea of how much time this project will take.","vi":"Ồ, tôi có kinh nghiệm trong mảng này đấy. Hay là bạn gửi cho tôi bản mô tả chi tiết công việc đi? Nhờ đó tôi sẽ ước lượng được dự án này cần bao nhiêu thời gian.","units":[{"en":"Oh, I have experience with that.","vi":"Ồ, tôi có kinh nghiệm trong mảng này đấy."},{"en":"Why don't you send me a detailed description of the work?","vi":"Hay là bạn gửi cho tôi bản mô tả chi tiết công việc đi?"},{"en":"That'll give me an idea of how much time this project will take.","vi":"Nhờ đó tôi sẽ ước lượng được dự án này cần bao nhiêu thời gian."}]}],"vocab":[{"word":"detailed","pos":"adj","ipa":"/ˈdiːteɪld/","meaning":"chi tiết, cặn kẽ"},{"word":"description","pos":"n","ipa":"/dɪˈskrɪpʃən/","meaning":"bản mô tả"},{"word":"experience","pos":"n","ipa":"/ɪkˈspɪriəns/","meaning":"kinh nghiệm"}],"isScanBacked":false,"grammarType":"Part 3 — Hành động tiếp theo & Đề xuất (Next Step & Offer/Request)","formula":"CÔNG THỨC PART 3 (Câu hỏi yêu cầu/hành động cuối hội thoại): Lắng nghe mẫu câu đề nghị lịch sự \"Why don't you send me + [N]?\" ở lượt cuối của người phụ nữ -> Quy đổi danh từ cốt lõi (description of the work -> project description).","optionAnalysis":{"A":"Khớp chính xác cấu trúc đề nghị ở cuối bài: \"Why don't you send me a detailed description of the work?\" (paraphrase thành \"A project description\").","B":"Hội thoại nói về dự án tiếp thị mạng xã hội, hoàn toàn không nhắc đến sự kiện hay thư mời nào.","C":"Bẫy lặp từ \"social media\" ở lượt nói trước của người đàn ông; người phụ nữ cần bản mô tả công việc để ước lượng thời gian, không phải link mạng xã hội.","D":"Hai nhân vật đã gọi điện trao đổi trực tiếp với nhau nên người phụ nữ không hỏi xin thêm thông tin liên hệ."},"evDocIdx":0,"evTargets":[{"badge":"Câu 52 · Đáp án A","opt":"A","isCorrect":true,"quote":"Why don't you send me a detailed description of the work?","viQuote":"Hay là bạn gửi cho tôi bản mô tả chi tiết công việc đi?"}],"evQuotes":["Why don't you send me a detailed description of the work?"]},{"q":53,"part":3,"group_id":"E25_T01_G53_55","audio":"web_assets/ets2025/audio/E25_T01/track_39.mp3","graphicImg":null,"transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_13.webp","web_assets/ets2025/tr/E25_T01_tr_14.webp"],"stem_en":"What problem does the woman mention?","stem_vi":"Người phụ nữ đề cập đến vấn đề gì?","options":{"A":{"en":"A vehicle is out of service.","vi":"Một chiếc xe đang không thể sử dụng được."},"B":{"en":"An employee is late.","vi":"Một nhân viên đi làm muộn."},"C":{"en":"A shipment was damaged.","vi":"Một lô hàng đã bị hư hại."},"D":{"en":"Traffic is heavy.","vi":"Giao thông đang tắc nghẽn."}},"ans":"A","explanation":"Đáp án đúng: (A) Một chiếc xe đang không thể sử dụng được — người phụ nữ báo cho Koji biết chiếc xe tải số 5 vừa chuẩn bị chất đồ thì phát hiện bị xẹp lốp nên phải xin xe khác thay thế.\nDẫn chứng: \"We were about to pack van number five for the music festival when we noticed it's got a flat tire.\" và \"Is there another van we can take?\" (van got a flat tire → vehicle is out of service).\nPhân tích bẫy:\n- (B) Bẫy mốc thời gian \"get there by eleven\"; cô ấy nêu hạn chót phải tới lễ hội trước 11 giờ chứ không phàn nàn nhân viên đi trễ.\n- (C) Bẫy ngữ cảnh vận chuyển đồ ăn (\"food's already in coolers\"); đồ ăn vẫn ổn, thứ gặp trục trặc là lốp của xe tải số 5.\n- (D) Cả nhóm mới chuẩn bị chất đồ tại bếp và bãi đỗ xe của công ty chứ chưa di chuyển ra đường nên chưa gặp tắc đường.","lines":[{"speaker":"W-Br","en":"Hey, Koji? We were about to pack van number five for the music festival when we noticed it's got a flat tire.","vi":"Này, Koji ơi? Chúng tôi vừa định chất đồ lên xe tải số 5 để đi phục vụ lễ hội âm nhạc thì phát hiện xe bị xẹp lốp.","units":[{"en":"Hey, Koji?","vi":"Này, Koji ơi?"},{"en":"We were about to pack van number five for the music festival when we noticed it's got a flat tire.","vi":"Chúng tôi vừa định chất đồ lên xe tải số 5 để đi phục vụ lễ hội âm nhạc thì phát hiện xe bị xẹp lốp."}]},{"speaker":"M-Au","en":"Oh. That's not good.","vi":"Ôi. Vậy thì không ổn rồi.","units":[{"en":"Oh.","vi":"Ôi."},{"en":"That's not good.","vi":"Vậy thì không ổn rồi."}]},{"speaker":"W-Br","en":"We're supposed to get there by eleven to set up lunch for the performers. Is there another van we can take?","vi":"Chúng tôi phải có mặt ở đó trước 11 giờ để chuẩn bị bữa trưa cho các nghệ sĩ biểu diễn. Còn chiếc xe tải nào khác chúng tôi có thể dùng không?","units":[{"en":"We're supposed to get there by eleven to set up lunch for the performers.","vi":"Chúng tôi phải có mặt ở đó trước 11 giờ để chuẩn bị bữa trưa cho các nghệ sĩ biểu diễn."},{"en":"Is there another van we can take?","vi":"Còn chiếc xe tải nào khác chúng tôi có thể dùng không?"}]},{"speaker":"M-Au","en":"Let me see what's available. We've got a lot of catering jobs today. Ah, yes—we can use van number three. Do you need help loading?","vi":"Để tôi kiểm tra xem còn xe nào trống không. Hôm nay bên mình có rất nhiều đơn đặt tiệc. À, có đây rồi—chúng ta có thể dùng xe tải số 3. Bạn có cần giúp bốc xếp đồ lên xe không?","units":[{"en":"Let me see what's available.","vi":"Để tôi kiểm tra xem còn xe nào trống không."},{"en":"We've got a lot of catering jobs today.","vi":"Hôm nay bên mình có rất nhiều đơn đặt tiệc."},{"en":"Ah, yes—we can use van number three.","vi":"À, có đây rồi—chúng ta có thể dùng xe tải số 3."},{"en":"Do you need help loading?","vi":"Bạn có cần giúp bốc xếp đồ lên xe không?"}]},{"speaker":"W-Br","en":"Yes, thanks. The food's already in coolers, but everything's in the kitchen with the serving utensils and napkins. It all needs to be brought to the parking area.","vi":"Có chứ, cảm ơn bạn. Đồ ăn đã được cho vào thùng giữ lạnh rồi, nhưng tất cả vẫn đang để trong bếp cùng với dụng cụ phục vụ và khăn ăn. Cần mang toàn bộ số đó ra khu vực bãi đỗ xe.","units":[{"en":"Yes, thanks.","vi":"Có chứ, cảm ơn bạn."},{"en":"The food's already in coolers, but everything's in the kitchen with the serving utensils and napkins.","vi":"Đồ ăn đã được cho vào thùng giữ lạnh rồi, nhưng tất cả vẫn đang để trong bếp cùng với dụng cụ phục vụ và khăn ăn."},{"en":"It all needs to be brought to the parking area.","vi":"Cần mang toàn bộ số đó ra khu vực bãi đỗ xe."}]},{"speaker":"M-Au","en":"All right; I can help with that.","vi":"Được thôi; tôi có thể giúp một tay.","units":[{"en":"All right; I can help with that.","vi":"Được thôi; tôi có thể giúp một tay."}]}],"vocab":[{"word":"flat tire","pos":"n","ipa":"/flæt ˈtaɪər/","meaning":"lốp xe bị xẹp"},{"word":"out of service","pos":"phr","ipa":"/aʊt ʌv ˈsɜːrvɪs/","meaning":"ngừng hoạt động, không thể sử dụng"},{"word":"pack","pos":"v","ipa":"/pæk/","meaning":"đóng gói, chất đồ lên xe"},{"word":"vehicle","pos":"n","ipa":"/ˈviːɪkəl/","meaning":"xe cộ, phương tiện"}],"isScanBacked":false,"grammarType":"Part 3 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 3 (Nhận diện vấn đề mở bài): Bám sát câu mở đầu của người nói đầu tiên sau khi gọi tên đồng nghiệp (\"We were about to pack\" và \"when we noticed\") -> Paraphrase sự cố kỹ thuật cụ thể (flat tire -> vehicle out of service).","optionAnalysis":{"A":"Khớp trực tiếp sự cố ở câu mở đầu: \"van number five\" bị \"got a flat tire\", khiến họ phải xin đổi sang xe khác (\"out of service\").","B":"Bẫy liên tưởng từ mốc 11 giờ (\"get there by eleven\"); đây là giờ phải có mặt để bày tiệc trưa, không có nhân viên nào bị báo đi muộn.","C":"Đồ ăn đã được đóng gói an toàn trong thùng giữ lạnh (\"food's already in coolers\"), không hề bị hư hại như phương án nêu.","D":"Họ vẫn đang ở công ty chuẩn bị xếp đồ lên xe tại bãi đỗ (\"brought to the parking area\"), chưa xuất phát nên không nhắc đến kẹt xe."},"evDocIdx":0,"evTargets":[{"badge":"Câu 53 · Đáp án A","opt":"A","isCorrect":true,"quote":"We were about to pack van number five for the music festival when we noticed it's got a flat tire.","viQuote":"Chúng tôi vừa định chất đồ lên xe tải số 5 để đi phục vụ lễ hội âm nhạc thì phát hiện xe bị xẹp lốp."}],"evQuotes":["We were about to pack van number five for the music festival when we noticed it's got a flat tire."]},{"q":54,"part":3,"group_id":"E25_T01_G53_55","audio":"web_assets/ets2025/audio/E25_T01/track_39.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"Where do the speakers most likely work?","stem_vi":"Những người nói có khả năng làm việc ở đâu nhất?","options":{"A":{"en":"At a recording studio","vi":"Tại một phòng thu âm"},"B":{"en":"At a catering company","vi":"Tại một công ty dịch vụ tiệc lưu động"},"C":{"en":"At a radio station","vi":"Tại một đài phát thanh"},"D":{"en":"At a car dealership","vi":"Tại một đại lý ô tô"}},"ans":"B","explanation":"Đáp án đúng: (B) Tại một công ty dịch vụ tiệc lưu động — cả hai đều nói về việc chuẩn bị bữa trưa cho nghệ sĩ tại lễ hội âm nhạc, số lượng đơn đặt tiệc trong ngày và mang đồ từ bếp ra xe tải.\nDẫn chứng: \"We've got a lot of catering jobs today.\" cùng các chi tiết \"set up lunch for the performers\" và \"everything's in the kitchen with the serving utensils and napkins\" (catering jobs → catering company).\nPhân tích bẫy:\n- (A) Bẫy liên tưởng từ \"music festival\" và \"performers\"; họ chỉ là đơn vị mang bữa trưa đến phục vụ các nghệ sĩ chứ không làm ở phòng thu âm.\n- (C) Bẫy chủ đề âm nhạc từ lễ hội ngoài trời; không có thiết bị hay hoạt động phát thanh nào được đề cập.\n- (D) Bẫy lặp từ xoay quanh đội xe tải (\"van number five\", \"van number three\", \"flat tire\"); họ dùng xe tải nội bộ để chở đồ tiệc chứ không bán ô tô.","lines":[{"speaker":"W-Br","en":"Hey, Koji? We were about to pack van number five for the music festival when we noticed it's got a flat tire.","vi":"Này, Koji ơi? Chúng tôi vừa định chất đồ lên xe tải số 5 để đi phục vụ lễ hội âm nhạc thì phát hiện xe bị xẹp lốp.","units":[{"en":"Hey, Koji?","vi":"Này, Koji ơi?"},{"en":"We were about to pack van number five for the music festival when we noticed it's got a flat tire.","vi":"Chúng tôi vừa định chất đồ lên xe tải số 5 để đi phục vụ lễ hội âm nhạc thì phát hiện xe bị xẹp lốp."}]},{"speaker":"M-Au","en":"Oh. That's not good.","vi":"Ôi. Vậy thì không ổn rồi.","units":[{"en":"Oh.","vi":"Ôi."},{"en":"That's not good.","vi":"Vậy thì không ổn rồi."}]},{"speaker":"W-Br","en":"We're supposed to get there by eleven to set up lunch for the performers. Is there another van we can take?","vi":"Chúng tôi phải có mặt ở đó trước 11 giờ để chuẩn bị bữa trưa cho các nghệ sĩ biểu diễn. Còn chiếc xe tải nào khác chúng tôi có thể dùng không?","units":[{"en":"We're supposed to get there by eleven to set up lunch for the performers.","vi":"Chúng tôi phải có mặt ở đó trước 11 giờ để chuẩn bị bữa trưa cho các nghệ sĩ biểu diễn."},{"en":"Is there another van we can take?","vi":"Còn chiếc xe tải nào khác chúng tôi có thể dùng không?"}]},{"speaker":"M-Au","en":"Let me see what's available. We've got a lot of catering jobs today. Ah, yes—we can use van number three. Do you need help loading?","vi":"Để tôi kiểm tra xem còn xe nào trống không. Hôm nay bên mình có rất nhiều đơn đặt tiệc. À, có đây rồi—chúng ta có thể dùng xe tải số 3. Bạn có cần giúp bốc xếp đồ lên xe không?","units":[{"en":"Let me see what's available.","vi":"Để tôi kiểm tra xem còn xe nào trống không."},{"en":"We've got a lot of catering jobs today.","vi":"Hôm nay bên mình có rất nhiều đơn đặt tiệc."},{"en":"Ah, yes—we can use van number three.","vi":"À, có đây rồi—chúng ta có thể dùng xe tải số 3."},{"en":"Do you need help loading?","vi":"Bạn có cần giúp bốc xếp đồ lên xe không?"}]},{"speaker":"W-Br","en":"Yes, thanks. The food's already in coolers, but everything's in the kitchen with the serving utensils and napkins. It all needs to be brought to the parking area.","vi":"Có chứ, cảm ơn bạn. Đồ ăn đã được cho vào thùng giữ lạnh rồi, nhưng tất cả vẫn đang để trong bếp cùng với dụng cụ phục vụ và khăn ăn. Cần mang toàn bộ số đó ra khu vực bãi đỗ xe.","units":[{"en":"Yes, thanks.","vi":"Có chứ, cảm ơn bạn."},{"en":"The food's already in coolers, but everything's in the kitchen with the serving utensils and napkins.","vi":"Đồ ăn đã được cho vào thùng giữ lạnh rồi, nhưng tất cả vẫn đang để trong bếp cùng với dụng cụ phục vụ và khăn ăn."},{"en":"It all needs to be brought to the parking area.","vi":"Cần mang toàn bộ số đó ra khu vực bãi đỗ xe."}]},{"speaker":"M-Au","en":"All right; I can help with that.","vi":"Được thôi; tôi có thể giúp một tay.","units":[{"en":"All right; I can help with that.","vi":"Được thôi; tôi có thể giúp một tay."}]}],"vocab":[{"word":"catering","pos":"n","ipa":"/ˈkeɪtərɪŋ/","meaning":"dịch vụ cung cấp tiệc"},{"word":"performer","pos":"n","ipa":"/pərˈfɔːrmər/","meaning":"nghệ sĩ biểu diễn"},{"word":"utensil","pos":"n","ipa":"/juːˈtensəl/","meaning":"dụng cụ ăn uống, làm bếp"},{"word":"napkin","pos":"n","ipa":"/ˈnæpkɪn/","meaning":"khăn ăn"}],"isScanBacked":false,"grammarType":"Part 3 — Ngữ cảnh, Địa điểm & Danh tính người nói (Setting & Role)","formula":"CÔNG THỨC PART 3 (Suy luận nơi làm việc): Tổng hợp các từ khóa nghề nghiệp rải đều trong thoại (\"set up lunch\", \"catering jobs\", \"kitchen\", \"serving utensils\") -> Xác định ngay loại hình doanh nghiệp.","optionAnalysis":{"A":"Bẫy ngữ cảnh từ cụm \"music festival\" và \"performers\"; hai người chuẩn bị bữa trưa phục vụ nghệ sĩ chứ không làm việc ở phòng thu âm.","B":"Được khẳng định trực tiếp qua cụm \"a lot of catering jobs today\", \"set up lunch\", \"coolers\", \"kitchen\" và \"serving utensils\".","C":"Không có chi tiết nào liên quan đến phát sóng hay đài phát thanh; sự kiện lễ hội âm nhạc chỉ là địa điểm giao tiệc.","D":"Bẫy lặp từ về xe tải (\"van number five\", \"van number three\", \"flat tire\"); xe tải được dùng để chở đồ ăn chứ không phải để kinh doanh ô tô."},"evDocIdx":0,"evTargets":[{"badge":"Câu 54 · Đáp án B","opt":"B","isCorrect":true,"quote":"We're supposed to get there by eleven to set up lunch for the performers.","viQuote":"Chúng tôi phải có mặt ở đó trước 11 giờ để chuẩn bị bữa trưa cho các nghệ sĩ biểu diễn."},{"badge":"Câu 54 · Đáp án B","opt":"B","isCorrect":true,"quote":"We've got a lot of catering jobs today.","viQuote":"Hôm nay bên mình có rất nhiều đơn đặt tiệc."}],"evQuotes":["We're supposed to get there by eleven to set up lunch for the performers.","We've got a lot of catering jobs today."]},{"q":55,"part":3,"group_id":"E25_T01_G53_55","audio":"web_assets/ets2025/audio/E25_T01/track_39.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the man say he will do next?","stem_vi":"Người đàn ông nói anh ấy sẽ làm gì tiếp theo?","options":{"A":{"en":"Arrange for a car repair","vi":"Sắp xếp việc sửa xe"},"B":{"en":"Order some kitchen supplies","vi":"Đặt mua một số đồ dùng nhà bếp"},"C":{"en":"Carry some items","vi":"Mang vác một số đồ đạc"},"D":{"en":"Offer a refund","vi":"Đề nghị hoàn tiền"}},"ans":"C","explanation":"Đáp án đúng: (C) Mang vác một số đồ đạc — người đàn ông hỏi cô có cần giúp chất đồ lên xe không; khi biết thùng giữ lạnh, dụng cụ phục vụ và khăn ăn đang ở trong bếp cần đưa ra bãi đỗ xe, anh đồng ý hỗ trợ ngay.\nDẫn chứng: \"Do you need help loading?\" → \"It all needs to be brought to the parking area.\" → \"All right; I can help with that.\" (help loading / bring items to parking area → carry some items).\nPhân tích bẫy:\n- (A) Bẫy bám chi tiết xe tải số 5 bị xẹp lốp ở đầu bài; thay vì đi gọi sửa xe, Koji chuyển sang điều xe số 3 và ra giúp khuân đồ.\n- (B) Bẫy lặp từ \"kitchen\" và \"serving utensils and napkins\"; các vật dụng này đã có sẵn trong bếp chỉ chờ mang ra xe, không phải đặt mua thêm.\n- (D) Không có khách hàng nào phàn nàn hay hủy đơn đặt tiệc để phải đề nghị hoàn tiền.","lines":[{"speaker":"W-Br","en":"Hey, Koji? We were about to pack van number five for the music festival when we noticed it's got a flat tire.","vi":"Này, Koji ơi? Chúng tôi vừa định chất đồ lên xe tải số 5 để đi phục vụ lễ hội âm nhạc thì phát hiện xe bị xẹp lốp.","units":[{"en":"Hey, Koji?","vi":"Này, Koji ơi?"},{"en":"We were about to pack van number five for the music festival when we noticed it's got a flat tire.","vi":"Chúng tôi vừa định chất đồ lên xe tải số 5 để đi phục vụ lễ hội âm nhạc thì phát hiện xe bị xẹp lốp."}]},{"speaker":"M-Au","en":"Oh. That's not good.","vi":"Ôi. Vậy thì không ổn rồi.","units":[{"en":"Oh.","vi":"Ôi."},{"en":"That's not good.","vi":"Vậy thì không ổn rồi."}]},{"speaker":"W-Br","en":"We're supposed to get there by eleven to set up lunch for the performers. Is there another van we can take?","vi":"Chúng tôi phải có mặt ở đó trước 11 giờ để chuẩn bị bữa trưa cho các nghệ sĩ biểu diễn. Còn chiếc xe tải nào khác chúng tôi có thể dùng không?","units":[{"en":"We're supposed to get there by eleven to set up lunch for the performers.","vi":"Chúng tôi phải có mặt ở đó trước 11 giờ để chuẩn bị bữa trưa cho các nghệ sĩ biểu diễn."},{"en":"Is there another van we can take?","vi":"Còn chiếc xe tải nào khác chúng tôi có thể dùng không?"}]},{"speaker":"M-Au","en":"Let me see what's available. We've got a lot of catering jobs today. Ah, yes—we can use van number three. Do you need help loading?","vi":"Để tôi kiểm tra xem còn xe nào trống không. Hôm nay bên mình có rất nhiều đơn đặt tiệc. À, có đây rồi—chúng ta có thể dùng xe tải số 3. Bạn có cần giúp bốc xếp đồ lên xe không?","units":[{"en":"Let me see what's available.","vi":"Để tôi kiểm tra xem còn xe nào trống không."},{"en":"We've got a lot of catering jobs today.","vi":"Hôm nay bên mình có rất nhiều đơn đặt tiệc."},{"en":"Ah, yes—we can use van number three.","vi":"À, có đây rồi—chúng ta có thể dùng xe tải số 3."},{"en":"Do you need help loading?","vi":"Bạn có cần giúp bốc xếp đồ lên xe không?"}]},{"speaker":"W-Br","en":"Yes, thanks. The food's already in coolers, but everything's in the kitchen with the serving utensils and napkins. It all needs to be brought to the parking area.","vi":"Có chứ, cảm ơn bạn. Đồ ăn đã được cho vào thùng giữ lạnh rồi, nhưng tất cả vẫn đang để trong bếp cùng với dụng cụ phục vụ và khăn ăn. Cần mang toàn bộ số đó ra khu vực bãi đỗ xe.","units":[{"en":"Yes, thanks.","vi":"Có chứ, cảm ơn bạn."},{"en":"The food's already in coolers, but everything's in the kitchen with the serving utensils and napkins.","vi":"Đồ ăn đã được cho vào thùng giữ lạnh rồi, nhưng tất cả vẫn đang để trong bếp cùng với dụng cụ phục vụ và khăn ăn."},{"en":"It all needs to be brought to the parking area.","vi":"Cần mang toàn bộ số đó ra khu vực bãi đỗ xe."}]},{"speaker":"M-Au","en":"All right; I can help with that.","vi":"Được thôi; tôi có thể giúp một tay.","units":[{"en":"All right; I can help with that.","vi":"Được thôi; tôi có thể giúp một tay."}]}],"vocab":[{"word":"load","pos":"v","ipa":"/loʊd/","meaning":"bốc xếp hàng hóa lên xe"},{"word":"cooler","pos":"n","ipa":"/ˈkuːlər/","meaning":"thùng giữ lạnh"},{"word":"parking area","pos":"n","ipa":"/ˈpɑːrkɪŋ ˈeriə/","meaning":"khu vực bãi đỗ xe"}],"isScanBacked":false,"grammarType":"Part 3 — Hành động tiếp theo & Đề xuất (Next Step & Offer/Request)","formula":"CÔNG THỨC PART 3 (Hành động tiếp theo): Đối chiếu lời đề nghị \"Do you need help loading?\" với yêu cầu mang đồ từ bếp ra bãi xe và câu chốt \"All right; I can help with that.\" -> Paraphrase động từ hành động (load / bring to parking area -> carry some items).","optionAnalysis":{"A":"Bẫy chi tiết xẹp lốp ở đầu hội thoại; Koji xử lý bằng cách cho dùng xe tải số 3 và đi giúp chất đồ, không nói sẽ đi sắp xếp sửa xe.","B":"Bẫy lặp từ \"kitchen\" và \"serving utensils and napkins\"; các đồ dùng này đã sẵn sàng trong bếp để mang ra xe chứ không cần đặt mua.","C":"Khớp mạch hội thoại cuối bài: Koji hỏi \"Do you need help loading?\" rồi đồng ý phụ mang thùng đồ ăn, dụng cụ và khăn ăn từ bếp ra bãi xe.","D":"Hội thoại giữa hai đồng nghiệp về việc điều phối xe giao tiệc đúng giờ, không có tình huống hoàn tiền cho khách hàng."},"evDocIdx":0,"evTargets":[{"badge":"Câu 55 · Đáp án C","opt":"C","isCorrect":true,"quote":"It all needs to be brought to the parking area.","viQuote":"Cần mang toàn bộ số đó ra khu vực bãi đỗ xe."},{"badge":"Câu 55 · Đáp án C","opt":"C","isCorrect":true,"quote":"All right; I can help with that.","viQuote":"Được thôi; tôi có thể giúp một tay."}],"evQuotes":["It all needs to be brought to the parking area.","All right; I can help with that."]},{"q":56,"part":3,"group_id":"E25_T01_G56_58","audio":"web_assets/ets2025/audio/E25_T01/track_40.mp3","graphicImg":null,"transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_14.webp","web_assets/ets2025/tr/E25_T01_tr_15.webp"],"stem_en":"Why is the man calling the woman?","stem_vi":"Tại sao người đàn ông lại gọi điện cho người phụ nữ?","options":{"A":{"en":"To plan a company event","vi":"Để lên kế hoạch cho một sự kiện của công ty"},"B":{"en":"To confirm a work deadline","vi":"Để xác nhận một thời hạn công việc"},"C":{"en":"To discuss a career path","vi":"Để trao đổi về một định hướng nghề nghiệp"},"D":{"en":"To accept a job offer","vi":"Để nhận một lời mời làm việc"}},"ans":"C","explanation":"Đáp án đúng: (C) Để trao đổi về một định hướng nghề nghiệp — người đàn ông cảm ơn người phụ nữ đã nghe máy và giải thích anh đang muốn tìm hiểu về ngành của chị từ các người làm nghề trước khi bước vào lĩnh vực này.\nDẫn chứng: \"I'm interested in working in your field. But I'm talking to some professionals first so I can find out more about it.\" (interested in working in your field + hỏi kinh nghiệm vào nghề → discuss a career path).\nPhân tích bẫy:\n- (A) Không có bất kỳ kế hoạch tổ chức sự kiện công ty nào được đề cập; cuộc gọi chỉ là buổi trò chuyện tham khảo nghề nghiệp.\n- (B) Hai người chưa làm cùng cơ quan nên không có thời hạn công việc cần xác nhận; cuối bài anh ấy chỉ hỏi lịch làm việc chung trong ngành báo.\n- (D) Bẫy suy diễn quá đà từ cụm \"working in your field\"; anh mới ở bước tìm hiểu ngành báo chí chứ chưa nhận lời mời làm việc nào.","lines":[{"speaker":"M-Cn","en":"Thanks for taking my call. As I mentioned in my e-mail, I'm interested in working in your field. But I'm talking to some professionals first so I can find out more about it.","vi":"Cảm ơn chị đã nhận cuộc gọi của tôi. Như tôi đã đề cập trong e-mail, tôi rất muốn làm việc trong lĩnh vực của chị. Nhưng trước tiên tôi muốn trao đổi với một số chuyên gia trong ngành để tìm hiểu rõ hơn.","units":[{"en":"Thanks for taking my call.","vi":"Cảm ơn chị đã nhận cuộc gọi của tôi."},{"en":"As I mentioned in my e-mail, I'm interested in working in your field.","vi":"Như tôi đã đề cập trong e-mail, tôi rất muốn làm việc trong lĩnh vực của chị."},{"en":"But I'm talking to some professionals first so I can find out more about it.","vi":"Nhưng trước tiên tôi muốn trao đổi với một số chuyên gia trong ngành để tìm hiểu rõ hơn."}]},{"speaker":"W-Am","en":"Happy to help.","vi":"Rất sẵn lòng giúp đỡ.","units":[{"en":"Happy to help.","vi":"Rất sẵn lòng giúp đỡ."}]},{"speaker":"M-Cn","en":"So how did you get your start?","vi":"Vậy chị đã bắt đầu bước vào nghề như thế nào?","units":[{"en":"So how did you get your start?","vi":"Vậy chị đã bắt đầu bước vào nghề như thế nào?"}]},{"speaker":"W-Am","en":"Oh, my family always subscribed to three newspapers. So I always thought the news was important. At my university, I joined the newspaper and eventually worked my way up to being an editor.","vi":"Ồ, trước đây gia đình tôi lúc nào cũng đặt mua dài hạn ba tờ báo. Vì vậy tôi luôn cho rằng tin tức rất quan trọng. Khi học đại học, tôi tham gia tờ báo của trường và dần dần phấn đấu lên vị trí biên tập viên.","units":[{"en":"Oh, my family always subscribed to three newspapers.","vi":"Ồ, trước đây gia đình tôi lúc nào cũng đặt mua dài hạn ba tờ báo."},{"en":"So I always thought the news was important.","vi":"Vì vậy tôi luôn cho rằng tin tức rất quan trọng."},{"en":"At my university, I joined the newspaper and eventually worked my way up to being an editor.","vi":"Khi học đại học, tôi tham gia tờ báo của trường và dần dần phấn đấu lên vị trí biên tập viên."}]},{"speaker":"M-Cn","en":"Wow. Is it true that people in the news business work very long hours? So what's your schedule like?","vi":"Chà. Có đúng là những người làm trong ngành báo chí phải làm việc rất nhiều giờ mỗi ngày không? Lịch làm việc của chị thường như thế nào?","units":[{"en":"Wow.","vi":"Chà."},{"en":"Is it true that people in the news business work very long hours?","vi":"Có đúng là những người làm trong ngành báo chí phải làm việc rất nhiều giờ mỗi ngày không?"},{"en":"So what's your schedule like?","vi":"Lịch làm việc của chị thường như thế nào?"}]}],"vocab":[{"word":"field","pos":"n","ipa":"/fiːld/","meaning":"lĩnh vực, ngành nghề"},{"word":"professional","pos":"n","ipa":"/prəˈfeʃənəl/","meaning":"chuyên gia, người làm nghề chuyên nghiệp"},{"word":"career path","pos":"n","ipa":"/kəˈrɪr pæθ/","meaning":"con đường sự nghiệp, định hướng nghề nghiệp"}],"isScanBacked":false,"grammarType":"Part 3 — Ý chính & Mục đích (Gist & Purpose)","formula":"CÔNG THỨC PART 3 (Mục đích cuộc gọi tìm hiểu thông tin): Chú ý động cơ giải thích ngay đầu thoại (\"interested in working in your field\" và \"find out more about it\") -> Quy đổi thành trao đổi định hướng nghề nghiệp (discuss a career path).","optionAnalysis":{"A":"Cuộc gọi nhằm phỏng vấn tìm hiểu kinh nghiệm nghề nghiệp cá nhân, hoàn toàn không liên quan đến tổ chức sự kiện công ty.","B":"Không có hạn chót dự án hay thời hạn công việc nào cần xác nhận giữa hai người trong cuộc gọi này.","C":"Khớp trực tiếp phần mở đầu: người đàn ông bày tỏ muốn làm trong ngành của chị nên gọi hỏi các chuyên gia để tìm hiểu con đường vào nghề.","D":"Bẫy suy diễn sai từ cụm \"interested in working in your field\"; anh mới đang tìm hiểu thông tin ngành nghề chứ chưa được mời làm việc."},"evDocIdx":0,"evTargets":[{"badge":"Câu 56 · Đáp án C","opt":"C","isCorrect":true,"quote":"As I mentioned in my e-mail, I'm interested in working in your field.","viQuote":"Như tôi đã đề cập trong e-mail, tôi rất muốn làm việc trong lĩnh vực của chị."},{"badge":"Câu 56 · Đáp án C","opt":"C","isCorrect":true,"quote":"But I'm talking to some professionals first so I can find out more about it.","viQuote":"Nhưng trước tiên tôi muốn trao đổi với một số chuyên gia trong ngành để tìm hiểu rõ hơn."}],"evQuotes":["As I mentioned in my e-mail, I'm interested in working in your field.","But I'm talking to some professionals first so I can find out more about it."]},{"q":57,"part":3,"group_id":"E25_T01_G56_58","audio":"web_assets/ets2025/audio/E25_T01/track_40.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"Who most likely is the woman?","stem_vi":"Người phụ nữ có khả năng là ai nhất?","options":{"A":{"en":"A newspaper editor","vi":"Một biên tập viên báo chí"},"B":{"en":"A university professor","vi":"Một giáo sư đại học"},"C":{"en":"A delivery person","vi":"Một nhân viên giao hàng"},"D":{"en":"A professional actor","vi":"Một diễn viên chuyên nghiệp"}},"ans":"A","explanation":"Đáp án đúng: (A) Một biên tập viên báo chí — khi kể cách mình bước vào nghề, người phụ nữ cho biết cô tham gia tờ báo ở trường đại học và dần phấn đấu lên vị trí biên tập viên.\nDẫn chứng: \"At my university, I joined the newspaper and eventually worked my way up to being an editor.\" cùng nhận xét sau đó của người đàn ông về \"people in the news business\".\nPhân tích bẫy:\n- (B) Bẫy lặp từ \"university\"; đây là nơi cô từng theo học và làm báo sinh viên, không phải nơi cô đang giảng dạy với tư cách giáo sư.\n- (C) Bẫy liên tưởng sai từ chi tiết gia đình cô từng đặt mua ba tờ báo dài hạn (\"subscribed to three newspapers\"), không phải cô làm nghề giao báo.\n- (D) Không có thông tin nào về diễn xuất hay điện ảnh; toàn bộ ngữ cảnh xoay quanh ngành tin tức và báo chí.","lines":[{"speaker":"M-Cn","en":"Thanks for taking my call. As I mentioned in my e-mail, I'm interested in working in your field. But I'm talking to some professionals first so I can find out more about it.","vi":"Cảm ơn chị đã nhận cuộc gọi của tôi. Như tôi đã đề cập trong e-mail, tôi rất muốn làm việc trong lĩnh vực của chị. Nhưng trước tiên tôi muốn trao đổi với một số chuyên gia trong ngành để tìm hiểu rõ hơn.","units":[{"en":"Thanks for taking my call.","vi":"Cảm ơn chị đã nhận cuộc gọi của tôi."},{"en":"As I mentioned in my e-mail, I'm interested in working in your field.","vi":"Như tôi đã đề cập trong e-mail, tôi rất muốn làm việc trong lĩnh vực của chị."},{"en":"But I'm talking to some professionals first so I can find out more about it.","vi":"Nhưng trước tiên tôi muốn trao đổi với một số chuyên gia trong ngành để tìm hiểu rõ hơn."}]},{"speaker":"W-Am","en":"Happy to help.","vi":"Rất sẵn lòng giúp đỡ.","units":[{"en":"Happy to help.","vi":"Rất sẵn lòng giúp đỡ."}]},{"speaker":"M-Cn","en":"So how did you get your start?","vi":"Vậy chị đã bắt đầu bước vào nghề như thế nào?","units":[{"en":"So how did you get your start?","vi":"Vậy chị đã bắt đầu bước vào nghề như thế nào?"}]},{"speaker":"W-Am","en":"Oh, my family always subscribed to three newspapers. So I always thought the news was important. At my university, I joined the newspaper and eventually worked my way up to being an editor.","vi":"Ồ, trước đây gia đình tôi lúc nào cũng đặt mua dài hạn ba tờ báo. Vì vậy tôi luôn cho rằng tin tức rất quan trọng. Khi học đại học, tôi tham gia tờ báo của trường và dần dần phấn đấu lên vị trí biên tập viên.","units":[{"en":"Oh, my family always subscribed to three newspapers.","vi":"Ồ, trước đây gia đình tôi lúc nào cũng đặt mua dài hạn ba tờ báo."},{"en":"So I always thought the news was important.","vi":"Vì vậy tôi luôn cho rằng tin tức rất quan trọng."},{"en":"At my university, I joined the newspaper and eventually worked my way up to being an editor.","vi":"Khi học đại học, tôi tham gia tờ báo của trường và dần dần phấn đấu lên vị trí biên tập viên."}]},{"speaker":"M-Cn","en":"Wow. Is it true that people in the news business work very long hours? So what's your schedule like?","vi":"Chà. Có đúng là những người làm trong ngành báo chí phải làm việc rất nhiều giờ mỗi ngày không? Lịch làm việc của chị thường như thế nào?","units":[{"en":"Wow.","vi":"Chà."},{"en":"Is it true that people in the news business work very long hours?","vi":"Có đúng là những người làm trong ngành báo chí phải làm việc rất nhiều giờ mỗi ngày không?"},{"en":"So what's your schedule like?","vi":"Lịch làm việc của chị thường như thế nào?"}]}],"vocab":[{"word":"subscribe","pos":"v","ipa":"/səbˈskraɪb/","meaning":"đặt mua dài hạn (báo, tạp chí)"},{"word":"eventually","pos":"adv","ipa":"/ɪˈventʃuəli/","meaning":"cuối cùng, dần dần"},{"word":"editor","pos":"n","ipa":"/ˈedɪtər/","meaning":"biên tập viên"},{"word":"work one's way up","pos":"phr","ipa":"/wɜːrk wʌnz weɪ ʌp/","meaning":"phấn đấu thăng tiến dần lên"}],"isScanBacked":false,"grammarType":"Part 3 — Ngữ cảnh, Địa điểm & Danh tính người nói (Setting & Role)","formula":"CÔNG THỨC PART 3 (Xác định nghề nghiệp người nói): Theo dõi câu trả lời về lộ trình vào nghề (\"joined the newspaper and eventually worked my way up to being an editor\") -> Chọn đúng chức danh hiện tại.","optionAnalysis":{"A":"Khớp trực tiếp câu trả lời của người phụ nữ: \"I joined the newspaper and eventually worked my way up to being an editor\".","B":"Bẫy lặp từ \"university\"; cô nhắc tới thời sinh viên đại học khi mới tham gia làm báo trường chứ không phải giảng viên đại học.","C":"Bẫy suy diễn sai từ việc gia đình cô đặt mua dài hạn ba tờ báo (\"subscribed to three newspapers\"), không liên quan đến nghề giao hàng.","D":"Không có bất kỳ chi tiết nào về nghệ thuật biểu diễn hay diễn viên trong cuộc trò chuyện về ngành tin tức báo chí này."},"evDocIdx":0,"evTargets":[{"badge":"Câu 57 · Đáp án A","opt":"A","isCorrect":true,"quote":"At my university, I joined the newspaper and eventually worked my way up to being an editor.","viQuote":"Khi học đại học, tôi tham gia tờ báo của trường và dần dần phấn đấu lên vị trí biên tập viên."}],"evQuotes":["At my university, I joined the newspaper and eventually worked my way up to being an editor."]},{"q":58,"part":3,"group_id":"E25_T01_G56_58","audio":"web_assets/ets2025/audio/E25_T01/track_40.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What will the woman most likely do next?","stem_vi":"Người phụ nữ có khả năng sẽ làm gì tiếp theo?","options":{"A":{"en":"Negotiate a contract","vi":"Đàm phán một bản hợp đồng"},"B":{"en":"Explain an office policy","vi":"Giải thích một chính sách văn phòng"},"C":{"en":"Review a résumé","vi":"Xem xét một bản sơ yếu lý lịch"},"D":{"en":"Describe a work schedule","vi":"Mô tả lịch trình làm việc"}},"ans":"D","explanation":"Đáp án đúng: (D) Mô tả lịch trình làm việc — ngay câu cuối cùng của đoạn hội thoại, người đàn ông hỏi về việc người làm báo có phải làm nhiều giờ không và lịch làm việc của cô như thế nào, nên cô sẽ trả lời nội dung này tiếp theo.\nDẫn chứng: \"Is it true that people in the news business work very long hours? So what's your schedule like?\" (câu hỏi trực tiếp dẫn tới hành động kế tiếp là \"Describe a work schedule\").\nPhân tích bẫy:\n- (A) Cuộc gọi chỉ mang tính chất trao đổi thông tin hướng nghiệp, không phải đàm phán hợp đồng lao động.\n- (B) Câu hỏi cuối cùng hỏi riêng về lịch trình làm việc của người phụ nữ (\"your schedule\"), không hỏi về chính sách nội bộ của văn phòng.\n- (C) Người đàn ông không hề nhắc đến việc gửi hồ sơ hay nhờ biên tập viên xem xét sơ yếu lý lịch của anh.","lines":[{"speaker":"M-Cn","en":"Thanks for taking my call. As I mentioned in my e-mail, I'm interested in working in your field. But I'm talking to some professionals first so I can find out more about it.","vi":"Cảm ơn chị đã nhận cuộc gọi của tôi. Như tôi đã đề cập trong e-mail, tôi rất muốn làm việc trong lĩnh vực của chị. Nhưng trước tiên tôi muốn trao đổi với một số chuyên gia trong ngành để tìm hiểu rõ hơn.","units":[{"en":"Thanks for taking my call.","vi":"Cảm ơn chị đã nhận cuộc gọi của tôi."},{"en":"As I mentioned in my e-mail, I'm interested in working in your field.","vi":"Như tôi đã đề cập trong e-mail, tôi rất muốn làm việc trong lĩnh vực của chị."},{"en":"But I'm talking to some professionals first so I can find out more about it.","vi":"Nhưng trước tiên tôi muốn trao đổi với một số chuyên gia trong ngành để tìm hiểu rõ hơn."}]},{"speaker":"W-Am","en":"Happy to help.","vi":"Rất sẵn lòng giúp đỡ.","units":[{"en":"Happy to help.","vi":"Rất sẵn lòng giúp đỡ."}]},{"speaker":"M-Cn","en":"So how did you get your start?","vi":"Vậy chị đã bắt đầu bước vào nghề như thế nào?","units":[{"en":"So how did you get your start?","vi":"Vậy chị đã bắt đầu bước vào nghề như thế nào?"}]},{"speaker":"W-Am","en":"Oh, my family always subscribed to three newspapers. So I always thought the news was important. At my university, I joined the newspaper and eventually worked my way up to being an editor.","vi":"Ồ, trước đây gia đình tôi lúc nào cũng đặt mua dài hạn ba tờ báo. Vì vậy tôi luôn cho rằng tin tức rất quan trọng. Khi học đại học, tôi tham gia tờ báo của trường và dần dần phấn đấu lên vị trí biên tập viên.","units":[{"en":"Oh, my family always subscribed to three newspapers.","vi":"Ồ, trước đây gia đình tôi lúc nào cũng đặt mua dài hạn ba tờ báo."},{"en":"So I always thought the news was important.","vi":"Vì vậy tôi luôn cho rằng tin tức rất quan trọng."},{"en":"At my university, I joined the newspaper and eventually worked my way up to being an editor.","vi":"Khi học đại học, tôi tham gia tờ báo của trường và dần dần phấn đấu lên vị trí biên tập viên."}]},{"speaker":"M-Cn","en":"Wow. Is it true that people in the news business work very long hours? So what's your schedule like?","vi":"Chà. Có đúng là những người làm trong ngành báo chí phải làm việc rất nhiều giờ mỗi ngày không? Lịch làm việc của chị thường như thế nào?","units":[{"en":"Wow.","vi":"Chà."},{"en":"Is it true that people in the news business work very long hours?","vi":"Có đúng là những người làm trong ngành báo chí phải làm việc rất nhiều giờ mỗi ngày không?"},{"en":"So what's your schedule like?","vi":"Lịch làm việc của chị thường như thế nào?"}]}],"vocab":[{"word":"news business","pos":"n","ipa":"/nuːz ˈbɪznəs/","meaning":"ngành báo chí, truyền thông tin tức"},{"word":"schedule","pos":"n","ipa":"/ˈskedʒuːl/","meaning":"lịch trình làm việc"},{"word":"negotiate","pos":"v","ipa":"/nɪˈɡoʊʃieɪt/","meaning":"đàm phán"}],"isScanBacked":false,"grammarType":"Part 3 — Hành động tiếp theo & Đề xuất (Next Step & Offer/Request)","formula":"CÔNG THỨC PART 3 (Dự đoán phản hồi lượt kế tiếp): Bám sát câu hỏi trực tiếp đặt ở cuối cùng của người đối thoại (\"So what's your schedule like?\") -> Người được hỏi chắc chắn sẽ mô tả lịch trình làm việc của mình.","optionAnalysis":{"A":"Đây là cuộc gọi tìm hiểu nghề nghiệp, không có nội dung tuyển dụng hay thương lượng hợp đồng giữa hai người.","B":"Câu hỏi cuối bài hỏi cụ thể về giờ giấc cá nhân của cô (\"what's your schedule like?\") chứ không phải chính sách văn phòng.","C":"Không có chi tiết nào đề cập đến sơ yếu lý lịch; trước đó anh chỉ gửi một e-mail xin hẹn trò chuyện tìm hiểu ngành.","D":"Bắt buộc nối tiếp câu hỏi trực tiếp ở cuối lời thoại của người đàn ông: \"So what's your schedule like?\""},"evDocIdx":0,"evTargets":[{"badge":"Câu 58 · Đáp án D","opt":"D","isCorrect":true,"quote":"Is it true that people in the news business work very long hours?","viQuote":"Có đúng là những người làm trong ngành báo chí phải làm việc rất nhiều giờ mỗi ngày không?"},{"badge":"Câu 58 · Đáp án D","opt":"D","isCorrect":true,"quote":"So what's your schedule like?","viQuote":"Lịch làm việc của chị thường như thế nào?"}],"evQuotes":["Is it true that people in the news business work very long hours?","So what's your schedule like?"]},{"q":59,"part":3,"group_id":"E25_T01_G59_61","audio":"web_assets/ets2025/audio/E25_T01/track_41.mp3","graphicImg":null,"transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_15.webp","web_assets/ets2025/tr/E25_T01_tr_16.webp"],"stem_en":"What are the speakers mainly discussing?","stem_vi":"Những người nói chủ yếu đang thảo luận về điều gì?","options":{"A":{"en":"A new transportation route","vi":"Một tuyến giao thông mới"},"B":{"en":"A company merger","vi":"Một vụ sáp nhập công ty"},"C":{"en":"A public relations initiative","vi":"Một sáng kiến quan hệ công chúng"},"D":{"en":"A medical facility design","vi":"Thiết kế của một cơ sở y tế"}},"ans":"B","explanation":"Đáp án đúng: (B) Một vụ sáp nhập công ty — người đàn ông mở đầu bằng thông tin trên website công ty về đề xuất sáp nhập với Tập đoàn QZ và sau đó hai người bàn về lợi ích cũng như khả năng chuyển trụ sở từ vụ sáp nhập này.\nDẫn chứng: \"I just read the article on the company Web site about the proposed merger with QZ Corporation.\" và \"There would be a lot of advantages to merging operations\" (proposed merger / merging operations → company merger).\nPhân tích bẫy:\n- (A) Bẫy liên tưởng từ việc chuyển địa điểm văn phòng (\"relocating\", \"move\"); họ chỉ bàn về trụ sở ở Chicago chứ không nói đến tuyến đường giao thông.\n- (C) Bài viết được đọc trên website công ty nói về thương vụ sáp nhập doanh nghiệp, không phải sáng kiến quan hệ công chúng.\n- (D) Không có chi tiết nào về cơ sở y tế hay bản vẽ thiết kế được nhắc tới trong đoạn hội thoại.","lines":[{"speaker":"M-Au","en":"Hi, Karen! I just read the article on the company Web site about the proposed merger with QZ Corporation. It looks like we're going ahead with it.","vi":"Chào Karen! Tôi vừa đọc bài viết trên trang web công ty về đề xuất sáp nhập với Tập đoàn QZ. Có vẻ như công ty sẽ tiến hành thương vụ này rồi.","units":[{"en":"Hi, Karen!","vi":"Chào Karen!"},{"en":"I just read the article on the company Web site about the proposed merger with QZ Corporation.","vi":"Tôi vừa đọc bài viết trên trang web công ty về đề xuất sáp nhập với Tập đoàn QZ."},{"en":"It looks like we're going ahead with it.","vi":"Có vẻ như công ty sẽ tiến hành thương vụ này rồi."}]},{"speaker":"W-Br","en":"There would be a lot of advantages to merging operations, although they also talked about it last year.","vi":"Việc hợp nhất hoạt động kinh doanh sẽ mang lại nhiều lợi ích, mặc dù năm ngoái họ cũng từng bàn về chuyện này rồi.","units":[{"en":"There would be a lot of advantages to merging operations, although they also talked about it last year.","vi":"Việc hợp nhất hoạt động kinh doanh sẽ mang lại nhiều lợi ích, mặc dù năm ngoái họ cũng từng bàn về chuyện này rồi."}]},{"speaker":"M-Au","en":"I remember that. But there were a lot of details to work out—like whether our offices would stay in Chicago. Now it looks like we won't be relocating.","vi":"Tôi nhớ chuyện đó mà. Nhưng lúc đó còn rất nhiều chi tiết cần giải quyết—chẳng hạn như liệu văn phòng của chúng ta có giữ nguyên ở Chicago hay không. Giờ thì có vẻ như chúng ta sẽ không phải chuyển địa điểm đâu.","units":[{"en":"I remember that.","vi":"Tôi nhớ chuyện đó mà."},{"en":"But there were a lot of details to work out—like whether our offices would stay in Chicago.","vi":"Nhưng lúc đó còn rất nhiều chi tiết cần giải quyết—chẳng hạn như liệu văn phòng của chúng ta có giữ nguyên ở Chicago hay không."},{"en":"Now it looks like we won't be relocating.","vi":"Giờ thì có vẻ như chúng ta sẽ không phải chuyển địa điểm đâu."}]},{"speaker":"W-Br","en":"Well, I really don't want to move, so that's a relief.","vi":"Ừ, tôi thực sự không muốn chuyển đi chút nào, nên nghe vậy cũng nhẹ cả người.","units":[{"en":"Well, I really don't want to move, so that's a relief.","vi":"Ừ, tôi thực sự không muốn chuyển đi chút nào, nên nghe vậy cũng nhẹ cả người."}]}],"vocab":[{"word":"proposed","pos":"adj","ipa":"/prəˈpoʊzd/","meaning":"được đề xuất"},{"word":"merger","pos":"n","ipa":"/ˈmɜːrdʒər/","meaning":"vụ sáp nhập (doanh nghiệp)"},{"word":"corporation","pos":"n","ipa":"/ˌkɔːrpəˈreɪʃən/","meaning":"tập đoàn"},{"word":"go ahead with","pos":"phr. v","ipa":"/ɡoʊ əˈhed wɪð/","meaning":"tiến hành, xúc tiến"}],"isScanBacked":false,"grammarType":"Part 3 — Ý chính & Mục đích (Gist & Purpose)","formula":"CÔNG THỨC PART 3 (Chủ đề chính của hội thoại): Xác định danh từ trung tâm được nhắc ở lượt mở đầu (\"proposed merger with QZ Corporation\") và lặp lại ở lượt phản hồi (\"merging operations\") -> Chốt chủ đề chung.","optionAnalysis":{"A":"Dù có nhắc tới việc chuyển địa điểm văn phòng (\"relocating\"), hai người không hề bàn về tuyến đường giao thông nào.","B":"Chủ đề xuyên suốt từ câu mở đầu đến cuối bài là đề xuất sáp nhập với Tập đoàn QZ (\"proposed merger\", \"merging operations\").","C":"Không đề cập đến hoạt động truyền thông hay quan hệ công chúng; bài viết trên web là thông báo nội bộ về sáp nhập.","D":"Thông tin thiết kế cơ sở y tế hoàn toàn không xuất hiện trong cuộc trò chuyện giữa hai nhân viên này."},"evDocIdx":0,"evTargets":[{"badge":"Câu 59 · Đáp án B","opt":"B","isCorrect":true,"quote":"I just read the article on the company Web site about the proposed merger with QZ Corporation.","viQuote":"Tôi vừa đọc bài viết trên trang web công ty về đề xuất sáp nhập với Tập đoàn QZ."}],"evQuotes":["I just read the article on the company Web site about the proposed merger with QZ Corporation."]},{"q":60,"part":3,"group_id":"E25_T01_G59_61","audio":"web_assets/ets2025/audio/E25_T01/track_41.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"Why does the woman say, \"they also talked about it last year\"?","stem_vi":"Tại sao người phụ nữ lại nói \"they also talked about it last year\"?","options":{"A":{"en":"To express doubt","vi":"Để bày tỏ sự nghi ngờ"},"B":{"en":"To explain a process","vi":"Để giải thích một quy trình"},"C":{"en":"To make a recommendation","vi":"Để đưa ra một đề xuất"},"D":{"en":"To update some information","vi":"Để cập nhật một số thông tin"}},"ans":"A","explanation":"Đáp án đúng: (A) Để bày tỏ sự nghi ngờ — sau khi thừa nhận việc hợp nhất có nhiều lợi thế, người phụ nữ dùng từ \"although\" để nhắc lại chuyện năm ngoái họ cũng đã bàn rồi nhưng chưa chốt, qua đó ngụ ý hoài nghi lần này có thực sự diễn ra.\nDẫn chứng: \"There would be a lot of advantages to merging operations, although they also talked about it last year.\" (liên từ đối lập \"although\" + tiền lệ bàn suông năm ngoái → express doubt).\nPhân tích bẫy:\n- (B) Câu nói chỉ nhắc lại một sự kiện cũ bằng thái độ dè dặt chứ không hề trình bày các bước trong quy trình sáp nhập.\n- (C) Cô ấy đang nêu lý do khiến mình chưa hoàn toàn tin tưởng vào tin sáp nhập, không đưa ra đề xuất hay lời khuyên nào.\n- (D) Người đàn ông mới là người mang thông tin cập nhật từ bài viết mới và xác nhận không chuyển văn phòng; câu của cô không mang tính cập nhật thông tin.","lines":[{"speaker":"M-Au","en":"Hi, Karen! I just read the article on the company Web site about the proposed merger with QZ Corporation. It looks like we're going ahead with it.","vi":"Chào Karen! Tôi vừa đọc bài viết trên trang web công ty về đề xuất sáp nhập với Tập đoàn QZ. Có vẻ như công ty sẽ tiến hành thương vụ này rồi.","units":[{"en":"Hi, Karen!","vi":"Chào Karen!"},{"en":"I just read the article on the company Web site about the proposed merger with QZ Corporation.","vi":"Tôi vừa đọc bài viết trên trang web công ty về đề xuất sáp nhập với Tập đoàn QZ."},{"en":"It looks like we're going ahead with it.","vi":"Có vẻ như công ty sẽ tiến hành thương vụ này rồi."}]},{"speaker":"W-Br","en":"There would be a lot of advantages to merging operations, although they also talked about it last year.","vi":"Việc hợp nhất hoạt động kinh doanh sẽ mang lại nhiều lợi ích, mặc dù năm ngoái họ cũng từng bàn về chuyện này rồi.","units":[{"en":"There would be a lot of advantages to merging operations, although they also talked about it last year.","vi":"Việc hợp nhất hoạt động kinh doanh sẽ mang lại nhiều lợi ích, mặc dù năm ngoái họ cũng từng bàn về chuyện này rồi."}]},{"speaker":"M-Au","en":"I remember that. But there were a lot of details to work out—like whether our offices would stay in Chicago. Now it looks like we won't be relocating.","vi":"Tôi nhớ chuyện đó mà. Nhưng lúc đó còn rất nhiều chi tiết cần giải quyết—chẳng hạn như liệu văn phòng của chúng ta có giữ nguyên ở Chicago hay không. Giờ thì có vẻ như chúng ta sẽ không phải chuyển địa điểm đâu.","units":[{"en":"I remember that.","vi":"Tôi nhớ chuyện đó mà."},{"en":"But there were a lot of details to work out—like whether our offices would stay in Chicago.","vi":"Nhưng lúc đó còn rất nhiều chi tiết cần giải quyết—chẳng hạn như liệu văn phòng của chúng ta có giữ nguyên ở Chicago hay không."},{"en":"Now it looks like we won't be relocating.","vi":"Giờ thì có vẻ như chúng ta sẽ không phải chuyển địa điểm đâu."}]},{"speaker":"W-Br","en":"Well, I really don't want to move, so that's a relief.","vi":"Ừ, tôi thực sự không muốn chuyển đi chút nào, nên nghe vậy cũng nhẹ cả người.","units":[{"en":"Well, I really don't want to move, so that's a relief.","vi":"Ừ, tôi thực sự không muốn chuyển đi chút nào, nên nghe vậy cũng nhẹ cả người."}]}],"vocab":[{"word":"advantage","pos":"n","ipa":"/ədˈvæntɪdʒ/","meaning":"lợi thế, ưu điểm"},{"word":"merge","pos":"v","ipa":"/mɜːrdʒ/","meaning":"sáp nhập, hợp nhất"},{"word":"operations","pos":"n","ipa":"/ˌɑːpəˈreɪʃənz/","meaning":"hoạt động vận hành, kinh doanh"},{"word":"doubt","pos":"n","ipa":"/daʊt/","meaning":"sự nghi ngờ, hoài nghi"}],"isScanBacked":false,"grammarType":"Part 3 — Câu hỏi hàm ý (Speaker Intent / Implied Meaning)","formula":"CÔNG THỨC PART 3 (Hàm ý câu trích dẫn): Kiểm tra liên từ tương phản đứng ngay trước câu trích dẫn (\"although they also talked about it last year\") -> Diễn tả sự dè dặt, hoài nghi rằng kế hoạch lần này chưa chắc thành hiện thực.","optionAnalysis":{"A":"Liên từ \"although\" kết hợp việc năm ngoái từng bàn nhưng bất thành cho thấy Karen hoài nghi liệu thương vụ sáp nhập có thực sự tiến hành lần này không.","B":"Cô chỉ nhắc lại tiền lệ năm ngoái chứ không mô tả quy trình hay trình tự thực hiện một vụ sáp nhập.","C":"Phát biểu này thể hiện sự dè dặt dựa trên kinh nghiệm cũ, không chứa lời khuyên hay đề xuất hành động nào.","D":"Người đàn ông mới là người cập nhật tin tức mới từ website; người phụ nữ chỉ gợi lại chuyện năm ngoái để bày tỏ sự băn khoăn."},"evDocIdx":0,"evTargets":[{"badge":"Câu 60 · Đáp án A","opt":"A","isCorrect":true,"quote":"There would be a lot of advantages to merging operations, although they also talked about it last year.","viQuote":"Việc hợp nhất hoạt động kinh doanh sẽ mang lại nhiều lợi ích, mặc dù năm ngoái họ cũng từng bàn về chuyện này rồi."}],"evQuotes":["There would be a lot of advantages to merging operations, although they also talked about it last year."]},{"q":61,"part":3,"group_id":"E25_T01_G59_61","audio":"web_assets/ets2025/audio/E25_T01/track_41.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the woman want to avoid?","stem_vi":"Người phụ nữ muốn tránh điều gì?","options":{"A":{"en":"Paying a certification fee","vi":"Trả phí cấp chứng chỉ"},"B":{"en":"Training additional staff","vi":"Đào tạo thêm nhân sự"},"C":{"en":"Upgrading some technology","vi":"Nâng cấp một số công nghệ"},"D":{"en":"Relocating to another city","vi":"Chuyển đến một thành phố khác"}},"ans":"D","explanation":"Đáp án đúng: (D) Chuyển đến một thành phố khác — khi người đàn ông cho biết các văn phòng nhiều khả năng sẽ giữ nguyên ở Chicago và không phải chuyển đi, Karen thở phào nhẹ nhõm vì cô thực sự không muốn chuyển chỗ.\nDẫn chứng: \"whether our offices would stay in Chicago. Now it looks like we won't be relocating.\" → \"Well, I really don't want to move, so that's a relief.\" (don't want to move + stay in Chicago → avoid relocating to another city).\nPhân tích bẫy:\n- (A) Không có chi tiết nào về chứng chỉ hay lệ phí cấp chứng chỉ trong cuộc hội thoại về sáp nhập công ty.\n- (B) Dù nói về hợp nhất hoạt động kinh doanh, hai người không đề cập đến việc phải đào tạo thêm nhân viên.\n- (C) Hội thoại chỉ xoay quanh địa điểm văn phòng tại Chicago, không nhắc đến việc nâng cấp hệ thống công nghệ.","lines":[{"speaker":"M-Au","en":"Hi, Karen! I just read the article on the company Web site about the proposed merger with QZ Corporation. It looks like we're going ahead with it.","vi":"Chào Karen! Tôi vừa đọc bài viết trên trang web công ty về đề xuất sáp nhập với Tập đoàn QZ. Có vẻ như công ty sẽ tiến hành thương vụ này rồi.","units":[{"en":"Hi, Karen!","vi":"Chào Karen!"},{"en":"I just read the article on the company Web site about the proposed merger with QZ Corporation.","vi":"Tôi vừa đọc bài viết trên trang web công ty về đề xuất sáp nhập với Tập đoàn QZ."},{"en":"It looks like we're going ahead with it.","vi":"Có vẻ như công ty sẽ tiến hành thương vụ này rồi."}]},{"speaker":"W-Br","en":"There would be a lot of advantages to merging operations, although they also talked about it last year.","vi":"Việc hợp nhất hoạt động kinh doanh sẽ mang lại nhiều lợi ích, mặc dù năm ngoái họ cũng từng bàn về chuyện này rồi.","units":[{"en":"There would be a lot of advantages to merging operations, although they also talked about it last year.","vi":"Việc hợp nhất hoạt động kinh doanh sẽ mang lại nhiều lợi ích, mặc dù năm ngoái họ cũng từng bàn về chuyện này rồi."}]},{"speaker":"M-Au","en":"I remember that. But there were a lot of details to work out—like whether our offices would stay in Chicago. Now it looks like we won't be relocating.","vi":"Tôi nhớ chuyện đó mà. Nhưng lúc đó còn rất nhiều chi tiết cần giải quyết—chẳng hạn như liệu văn phòng của chúng ta có giữ nguyên ở Chicago hay không. Giờ thì có vẻ như chúng ta sẽ không phải chuyển địa điểm đâu.","units":[{"en":"I remember that.","vi":"Tôi nhớ chuyện đó mà."},{"en":"But there were a lot of details to work out—like whether our offices would stay in Chicago.","vi":"Nhưng lúc đó còn rất nhiều chi tiết cần giải quyết—chẳng hạn như liệu văn phòng của chúng ta có giữ nguyên ở Chicago hay không."},{"en":"Now it looks like we won't be relocating.","vi":"Giờ thì có vẻ như chúng ta sẽ không phải chuyển địa điểm đâu."}]},{"speaker":"W-Br","en":"Well, I really don't want to move, so that's a relief.","vi":"Ừ, tôi thực sự không muốn chuyển đi chút nào, nên nghe vậy cũng nhẹ cả người.","units":[{"en":"Well, I really don't want to move, so that's a relief.","vi":"Ừ, tôi thực sự không muốn chuyển đi chút nào, nên nghe vậy cũng nhẹ cả người."}]}],"vocab":[{"word":"relocate","pos":"v","ipa":"/ˌriːˈloʊkeɪt/","meaning":"di dời, chuyển địa điểm"},{"word":"work out","pos":"phr. v","ipa":"/wɜːrk ˈaʊt/","meaning":"giải quyết, thu xếp ổn thỏa"},{"word":"relief","pos":"n","ipa":"/rɪˈliːf/","meaning":"cảm giác nhẹ nhõm"}],"isScanBacked":false,"grammarType":"Part 3 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 3 (Thông tin phủ định / Mong muốn tránh): Kết hợp câu nói \"we won't be relocating\" (trước đó nhắc giữ văn phòng ở Chicago) với phản ứng \"I really don't want to move\" -> Paraphrase \"move\" thành \"Relocating to another city\".","optionAnalysis":{"A":"Không có thông tin về chứng chỉ hay khoản phí nào trong suốt cuộc trò chuyện về thương vụ sáp nhập.","B":"Hai nhân vật không hề bày tỏ lo ngại về việc tuyển dụng hay đào tạo thêm nhân sự khi sáp nhập.","C":"Không có chi tiết nào liên quan đến công nghệ hay việc nâng cấp trang thiết bị làm việc.","D":"Khớp trực tiếp mạch thoại cuối: nghe tin \"offices would stay in Chicago\" và \"won't be relocating\", Karen đáp \"I really don't want to move, so that's a relief\"."},"evDocIdx":0,"evTargets":[{"badge":"Câu 61 · Đáp án D","opt":"D","isCorrect":true,"quote":"Now it looks like we won't be relocating.","viQuote":"Giờ thì có vẻ như chúng ta sẽ không phải chuyển địa điểm đâu."},{"badge":"Câu 61 · Đáp án D","opt":"D","isCorrect":true,"quote":"Well, I really don't want to move, so that's a relief.","viQuote":"Ừ, tôi thực sự không muốn chuyển đi chút nào, nên nghe vậy cũng nhẹ cả người."}],"evQuotes":["Now it looks like we won't be relocating.","Well, I really don't want to move, so that's a relief."]},{"q":62,"part":3,"group_id":"E25_T01_G62_64","audio":"web_assets/ets2025/audio/E25_T01/track_42.mp3","graphicImg":"web_assets/ets2025/gfx/E25_T01_Q62.webp","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_17.webp"],"stem_en":"Who is a gift for?","stem_vi":"Món quà dành cho ai?","options":{"A":{"en":"Donors","vi":"Các nhà tài trợ"},"B":{"en":"Volunteers","vi":"Các tình nguyện viên"},"C":{"en":"Employees","vi":"Các nhân viên"},"D":{"en":"Clients","vi":"Các khách hàng"}},"ans":"C","explanation":"Đáp án đúng: (C) Các nhân viên — ngay khi nhân viên bán hàng hỏi cần hỗ trợ gì, người phụ nữ nêu rõ công ty cô muốn tặng mỗi nhân viên một món quà nhân dịp giải bóng rổ nội bộ thường niên.\nDẫn chứng: \"My company wants to give every employee a gift, something useful but not too big. Since we're about to host our annual staff basketball tournament, I thought a water bottle might be good.\" (every employee / staff → Employees).\nPhân tích bẫy:\n- (A) Công ty tổ chức giải bóng rổ cho nhân viên nội bộ chứ không tặng quà tri ân nhà tài trợ.\n- (B) Không có hoạt động thiện nguyện hay tình nguyện viên nào được nhắc tới trong đoạn thoại.\n- (D) Bẫy thói quen suy luận khi thấy từ \"company logo\" ở cuối bài; quà in logo lần này tặng nội bộ nhân viên, không phải tặng khách hàng.","lines":[{"speaker":"M-Au","en":"Thanks for calling Customized Concepts. How can I help you?","vi":"Cảm ơn quý khách đã gọi đến Customized Concepts. Tôi có thể hỗ trợ gì cho chị ạ?","units":[{"en":"Thanks for calling Customized Concepts.","vi":"Cảm ơn quý khách đã gọi đến Customized Concepts."},{"en":"How can I help you?","vi":"Tôi có thể hỗ trợ gì cho chị ạ?"}]},{"speaker":"W-Am","en":"My company wants to give every employee a gift, something useful but not too big. Since we're about to host our annual staff basketball tournament, I thought a water bottle might be good.","vi":"Công ty tôi muốn tặng mỗi nhân viên một món quà, thứ gì đó thiết thực nhưng không quá lớn. Vì chúng tôi sắp tổ chức giải bóng rổ nhân viên thường niên nên tôi nghĩ bình đựng nước sẽ rất phù hợp.","units":[{"en":"My company wants to give every employee a gift, something useful but not too big.","vi":"Công ty tôi muốn tặng mỗi nhân viên một món quà, thứ gì đó thiết thực nhưng không quá lớn."},{"en":"Since we're about to host our annual staff basketball tournament, I thought a water bottle might be good.","vi":"Vì chúng tôi sắp tổ chức giải bóng rổ nhân viên thường niên nên tôi nghĩ bình đựng nước sẽ rất phù hợp."}]},{"speaker":"M-Au","en":"We carry a few drink containers. If you're at our Web site, you'll see them under the Lifestyle tab.","vi":"Bên tôi có bán một vài mẫu bình đựng đồ uống. Nếu chị đang mở trang web của chúng tôi, chị sẽ thấy chúng nằm trong mục Lifestyle.","units":[{"en":"We carry a few drink containers.","vi":"Bên tôi có bán một vài mẫu bình đựng đồ uống."},{"en":"If you're at our Web site, you'll see them under the Lifestyle tab.","vi":"Nếu chị đang mở trang web của chúng tôi, chị sẽ thấy chúng nằm trong mục Lifestyle."}]},{"speaker":"W-Am","en":"Let me pull it up now... All right.","vi":"Để tôi mở trang đó lên ngay bây giờ… Được rồi.","units":[{"en":"Let me pull it up now...","vi":"Để tôi mở trang đó lên ngay bây giờ…"},{"en":"All right.","vi":"Được rồi."}]},{"speaker":"M-Au","en":"I recommend the metal bottle with the wide-mouthed lid. It's easier to clean than the one with the straw.","vi":"Tôi khuyên chị nên chọn mẫu bình kim loại có nắp miệng rộng. Loại này dễ vệ sinh hơn mẫu có ống hút.","units":[{"en":"I recommend the metal bottle with the wide-mouthed lid.","vi":"Tôi khuyên chị nên chọn mẫu bình kim loại có nắp miệng rộng."},{"en":"It's easier to clean than the one with the straw.","vi":"Loại này dễ vệ sinh hơn mẫu có ống hút."}]},{"speaker":"W-Am","en":"OK, thanks. And you could put our company logo on it, right?","vi":"Vâng, cảm ơn anh. Và bên anh có thể in logo công ty tôi lên bình được chứ?","units":[{"en":"OK, thanks.","vi":"Vâng, cảm ơn anh."},{"en":"And you could put our company logo on it, right?","vi":"Và bên anh có thể in logo công ty tôi lên bình được chứ?"}]},{"speaker":"M-Au","en":"Yes. You'll just need to send me the graphic file.","vi":"Được chứ ạ. Chị chỉ cần gửi cho tôi tệp đồ họa là được.","units":[{"en":"Yes.","vi":"Được chứ ạ."},{"en":"You'll just need to send me the graphic file.","vi":"Chị chỉ cần gửi cho tôi tệp đồ họa là được."}]},{"speaker":"W-Am","en":"I can do that.","vi":"Tôi có thể gửi được.","units":[{"en":"I can do that.","vi":"Tôi có thể gửi được."}]}],"vocab":[{"word":"employee","pos":"n","ipa":"/ɪmˈplɔɪiː/","meaning":"nhân viên"},{"word":"useful","pos":"adj","ipa":"/ˈjuːsfəl/","meaning":"hữu ích, thiết thực"},{"word":"donor","pos":"n","ipa":"/ˈdoʊnər/","meaning":"nhà tài trợ, người quyên góp"},{"word":"tournament","pos":"n","ipa":"/ˈtʊrnəmənt/","meaning":"giải đấu"}],"isScanBacked":false,"grammarType":"Part 3 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 3 (Chi tiết đối tượng nhận): Chú ý câu giới thiệu mục đích mua hàng ngay khi khách hàng mở lời (\"My company wants to give every employee a gift\") -> Chọn đúng danh từ chỉ người nhận.","optionAnalysis":{"A":"Quà được đặt cho sự kiện nội bộ của công ty (\"annual staff basketball tournament\"), không dành cho các nhà tài trợ.","B":"Hội thoại không nhắc đến tình nguyện viên; đối tượng nhận quà được nêu đích danh ở lượt đầu của khách hàng.","C":"Khớp nguyên văn lời người phụ nữ: \"My company wants to give every employee a gift\" nhân dịp giải đấu của nhân viên (\"staff basketball tournament\").","D":"Bẫy suy diễn quen thuộc từ chi tiết in logo công ty (\"company logo\"); thực tế đây là quà cho nhân viên chứ không phải khách hàng."},"evDocIdx":0,"evTargets":[{"badge":"Câu 62 · Đáp án C","opt":"C","isCorrect":true,"quote":"My company wants to give every employee a gift, something useful but not too big.","viQuote":"Công ty tôi muốn tặng mỗi nhân viên một món quà, thứ gì đó thiết thực nhưng không quá lớn."}],"evQuotes":["My company wants to give every employee a gift, something useful but not too big."]},{"q":63,"part":3,"group_id":"E25_T01_G62_64","audio":"web_assets/ets2025/audio/E25_T01/track_42.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"Look at the graphic. What is the price of the item the man recommends?","stem_vi":"Hãy nhìn vào hình ảnh. Giá của món đồ mà người đàn ông đề xuất là bao nhiêu?","options":{"A":{"en":"$21","vi":"$21"},"B":{"en":"$18","vi":"$18"},"C":{"en":"$24","vi":"$24"},"D":{"en":"$15","vi":"$15"}},"ans":"C","explanation":"Đáp án đúng: (C) $24 — trong lời thoại, người đàn ông khuyên chọn mẫu bình kim loại có nắp miệng rộng (dễ vệ sinh hơn mẫu có ống hút); tra ô góc dưới bên trái trên trang web sản phẩm \"Wide-Mouthed Steel Water Bottle\" có giá $24.\nDẫn chứng: \"I recommend the metal bottle with the wide-mouthed lid. It's easier to clean than the one with the straw.\" → Đối chiếu bảng 2x2 ở ảnh trang web: ô dưới bên trái ghi \"Wide-Mouthed Steel Water Bottle\" = \"$24\".\nPhân tích bẫy:\n- (A) $21 là giá của ô trên bên trái \"Plastic Water Bottle with Straw Lid\" (bình nhựa có nắp ống hút) — loại mà người đàn ông nhận xét là khó rửa hơn.\n- (B) $18 là giá của ô trên bên phải \"Ceramic Travel Mug\" (cốc du lịch bằng sứ), không phải bình nước kim loại được đề xuất.\n- (D) $15 là giá của ô dưới bên phải \"Mug with Handle\" (cốc có tay cầm), không khớp với bình thép miệng rộng.","lines":[{"speaker":"M-Au","en":"Thanks for calling Customized Concepts. How can I help you?","vi":"Cảm ơn quý khách đã gọi đến Customized Concepts. Tôi có thể hỗ trợ gì cho chị ạ?","units":[{"en":"Thanks for calling Customized Concepts.","vi":"Cảm ơn quý khách đã gọi đến Customized Concepts."},{"en":"How can I help you?","vi":"Tôi có thể hỗ trợ gì cho chị ạ?"}]},{"speaker":"W-Am","en":"My company wants to give every employee a gift, something useful but not too big. Since we're about to host our annual staff basketball tournament, I thought a water bottle might be good.","vi":"Công ty tôi muốn tặng mỗi nhân viên một món quà, thứ gì đó thiết thực nhưng không quá lớn. Vì chúng tôi sắp tổ chức giải bóng rổ nhân viên thường niên nên tôi nghĩ bình đựng nước sẽ rất phù hợp.","units":[{"en":"My company wants to give every employee a gift, something useful but not too big.","vi":"Công ty tôi muốn tặng mỗi nhân viên một món quà, thứ gì đó thiết thực nhưng không quá lớn."},{"en":"Since we're about to host our annual staff basketball tournament, I thought a water bottle might be good.","vi":"Vì chúng tôi sắp tổ chức giải bóng rổ nhân viên thường niên nên tôi nghĩ bình đựng nước sẽ rất phù hợp."}]},{"speaker":"M-Au","en":"We carry a few drink containers. If you're at our Web site, you'll see them under the Lifestyle tab.","vi":"Bên tôi có bán một vài mẫu bình đựng đồ uống. Nếu chị đang mở trang web của chúng tôi, chị sẽ thấy chúng nằm trong mục Lifestyle.","units":[{"en":"We carry a few drink containers.","vi":"Bên tôi có bán một vài mẫu bình đựng đồ uống."},{"en":"If you're at our Web site, you'll see them under the Lifestyle tab.","vi":"Nếu chị đang mở trang web của chúng tôi, chị sẽ thấy chúng nằm trong mục Lifestyle."}]},{"speaker":"W-Am","en":"Let me pull it up now... All right.","vi":"Để tôi mở trang đó lên ngay bây giờ… Được rồi.","units":[{"en":"Let me pull it up now...","vi":"Để tôi mở trang đó lên ngay bây giờ…"},{"en":"All right.","vi":"Được rồi."}]},{"speaker":"M-Au","en":"I recommend the metal bottle with the wide-mouthed lid. It's easier to clean than the one with the straw.","vi":"Tôi khuyên chị nên chọn mẫu bình kim loại có nắp miệng rộng. Loại này dễ vệ sinh hơn mẫu có ống hút.","units":[{"en":"I recommend the metal bottle with the wide-mouthed lid.","vi":"Tôi khuyên chị nên chọn mẫu bình kim loại có nắp miệng rộng."},{"en":"It's easier to clean than the one with the straw.","vi":"Loại này dễ vệ sinh hơn mẫu có ống hút."}]},{"speaker":"W-Am","en":"OK, thanks. And you could put our company logo on it, right?","vi":"Vâng, cảm ơn anh. Và bên anh có thể in logo công ty tôi lên bình được chứ?","units":[{"en":"OK, thanks.","vi":"Vâng, cảm ơn anh."},{"en":"And you could put our company logo on it, right?","vi":"Và bên anh có thể in logo công ty tôi lên bình được chứ?"}]},{"speaker":"M-Au","en":"Yes. You'll just need to send me the graphic file.","vi":"Được chứ ạ. Chị chỉ cần gửi cho tôi tệp đồ họa là được.","units":[{"en":"Yes.","vi":"Được chứ ạ."},{"en":"You'll just need to send me the graphic file.","vi":"Chị chỉ cần gửi cho tôi tệp đồ họa là được."}]},{"speaker":"W-Am","en":"I can do that.","vi":"Tôi có thể gửi được.","units":[{"en":"I can do that.","vi":"Tôi có thể gửi được."}]}],"vocab":[{"word":"wide-mouthed","pos":"adj","ipa":"/waɪd maʊθd/","meaning":"có miệng rộng"},{"word":"lid","pos":"n","ipa":"/lɪd/","meaning":"nắp đậy"},{"word":"straw","pos":"n","ipa":"/strɔː/","meaning":"ống hút"},{"word":"container","pos":"n","ipa":"/kənˈteɪnər/","meaning":"đồ đựng, bình chứa"}],"isScanBacked":false,"grammarType":"Part 3 — Kết hợp Hình ảnh & Bảng biểu (Graphic Question)","formula":"CÔNG THỨC PART 3 (Bảng biểu 2x2 — Đối chiếu 2 bước): Nghe mô tả sản phẩm được người bán khuyên chọn (\"metal bottle with the wide-mouthed lid\") -> Tra trên lưới 4 sản phẩm trong ảnh để đọc đúng mức giá tương ứng.","optionAnalysis":{"A":"Mức giá $21 thuộc về ô trên bên trái \"Plastic Water Bottle with Straw Lid\", mẫu bị người đàn ông chê là khó vệ sinh hơn.","B":"Mức giá $18 thuộc về ô trên bên phải \"Ceramic Travel Mug\" (cốc sứ), không phải bình kim loại miệng rộng.","C":"Đối chiếu 2 bước: nghe gợi ý \"metal bottle with the wide-mouthed lid\" → tra ô dưới bên trái trong lưới 2x2 là \"Wide-Mouthed Steel Water Bottle\" có giá $24.","D":"Mức giá $15 thuộc về ô dưới bên phải \"Mug with Handle\" (cốc có tay cầm), không phải sản phẩm được khuyên chọn."},"evDocIdx":0,"evTargets":[{"badge":"Câu 63 · Đáp án C","opt":"C","isCorrect":true,"quote":"I recommend the metal bottle with the wide-mouthed lid.","viQuote":"Tôi khuyên chị nên chọn mẫu bình kim loại có nắp miệng rộng."}],"evQuotes":["I recommend the metal bottle with the wide-mouthed lid."]},{"q":64,"part":3,"group_id":"E25_T01_G62_64","audio":"web_assets/ets2025/audio/E25_T01/track_42.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What is the woman going to send to the man?","stem_vi":"Người phụ nữ sẽ gửi gì cho người đàn ông?","options":{"A":{"en":"A graphic file","vi":"Một tệp đồ họa"},"B":{"en":"A list of names","vi":"Một danh sách tên"},"C":{"en":"A delivery address","vi":"Một địa chỉ giao hàng"},"D":{"en":"An account number","vi":"Một số tài khoản"}},"ans":"A","explanation":"Đáp án đúng: (A) Một tệp đồ họa — khi người phụ nữ hỏi bên bán có in được logo công ty lên bình nước không, người đàn ông đồng ý và dặn chị chỉ cần gửi cho anh tệp đồ họa, chị liền xác nhận sẽ gửi.\nDẫn chứng: \"Yes. You'll just need to send me the graphic file.\" → \"I can do that.\" (khớp nguyên cụm \"graphic file\").\nPhân tích bẫy:\n- (B) Đơn hàng chỉ in logo công ty lên từng bình chứ không đề cập việc khắc tên riêng hay gửi danh sách tên nhân viên.\n- (C) Cuộc gọi chưa chuyển sang bước chốt hóa đơn hay xác nhận địa chỉ giao hàng.\n- (D) Không có thông tin nào về số tài khoản công ty hay thanh toán được yêu cầu trong đoạn kết hội thoại.","lines":[{"speaker":"M-Au","en":"Thanks for calling Customized Concepts. How can I help you?","vi":"Cảm ơn quý khách đã gọi đến Customized Concepts. Tôi có thể hỗ trợ gì cho chị ạ?","units":[{"en":"Thanks for calling Customized Concepts.","vi":"Cảm ơn quý khách đã gọi đến Customized Concepts."},{"en":"How can I help you?","vi":"Tôi có thể hỗ trợ gì cho chị ạ?"}]},{"speaker":"W-Am","en":"My company wants to give every employee a gift, something useful but not too big. Since we're about to host our annual staff basketball tournament, I thought a water bottle might be good.","vi":"Công ty tôi muốn tặng mỗi nhân viên một món quà, thứ gì đó thiết thực nhưng không quá lớn. Vì chúng tôi sắp tổ chức giải bóng rổ nhân viên thường niên nên tôi nghĩ bình đựng nước sẽ rất phù hợp.","units":[{"en":"My company wants to give every employee a gift, something useful but not too big.","vi":"Công ty tôi muốn tặng mỗi nhân viên một món quà, thứ gì đó thiết thực nhưng không quá lớn."},{"en":"Since we're about to host our annual staff basketball tournament, I thought a water bottle might be good.","vi":"Vì chúng tôi sắp tổ chức giải bóng rổ nhân viên thường niên nên tôi nghĩ bình đựng nước sẽ rất phù hợp."}]},{"speaker":"M-Au","en":"We carry a few drink containers. If you're at our Web site, you'll see them under the Lifestyle tab.","vi":"Bên tôi có bán một vài mẫu bình đựng đồ uống. Nếu chị đang mở trang web của chúng tôi, chị sẽ thấy chúng nằm trong mục Lifestyle.","units":[{"en":"We carry a few drink containers.","vi":"Bên tôi có bán một vài mẫu bình đựng đồ uống."},{"en":"If you're at our Web site, you'll see them under the Lifestyle tab.","vi":"Nếu chị đang mở trang web của chúng tôi, chị sẽ thấy chúng nằm trong mục Lifestyle."}]},{"speaker":"W-Am","en":"Let me pull it up now... All right.","vi":"Để tôi mở trang đó lên ngay bây giờ… Được rồi.","units":[{"en":"Let me pull it up now...","vi":"Để tôi mở trang đó lên ngay bây giờ…"},{"en":"All right.","vi":"Được rồi."}]},{"speaker":"M-Au","en":"I recommend the metal bottle with the wide-mouthed lid. It's easier to clean than the one with the straw.","vi":"Tôi khuyên chị nên chọn mẫu bình kim loại có nắp miệng rộng. Loại này dễ vệ sinh hơn mẫu có ống hút.","units":[{"en":"I recommend the metal bottle with the wide-mouthed lid.","vi":"Tôi khuyên chị nên chọn mẫu bình kim loại có nắp miệng rộng."},{"en":"It's easier to clean than the one with the straw.","vi":"Loại này dễ vệ sinh hơn mẫu có ống hút."}]},{"speaker":"W-Am","en":"OK, thanks. And you could put our company logo on it, right?","vi":"Vâng, cảm ơn anh. Và bên anh có thể in logo công ty tôi lên bình được chứ?","units":[{"en":"OK, thanks.","vi":"Vâng, cảm ơn anh."},{"en":"And you could put our company logo on it, right?","vi":"Và bên anh có thể in logo công ty tôi lên bình được chứ?"}]},{"speaker":"M-Au","en":"Yes. You'll just need to send me the graphic file.","vi":"Được chứ ạ. Chị chỉ cần gửi cho tôi tệp đồ họa là được.","units":[{"en":"Yes.","vi":"Được chứ ạ."},{"en":"You'll just need to send me the graphic file.","vi":"Chị chỉ cần gửi cho tôi tệp đồ họa là được."}]},{"speaker":"W-Am","en":"I can do that.","vi":"Tôi có thể gửi được.","units":[{"en":"I can do that.","vi":"Tôi có thể gửi được."}]}],"vocab":[{"word":"graphic file","pos":"n","ipa":"/ˈɡræfɪk faɪl/","meaning":"tệp đồ họa"},{"word":"logo","pos":"n","ipa":"/ˈloʊɡoʊ/","meaning":"biểu trưng, logo"},{"word":"delivery address","pos":"n","ipa":"/dɪˈlɪvəri əˈdres/","meaning":"địa chỉ giao hàng"}],"isScanBacked":false,"grammarType":"Part 3 — Hành động tiếp theo & Đề xuất (Next Step & Offer/Request)","formula":"CÔNG THỨC PART 3 (Hành động gửi tệp ở cuối thoại): Bám sát điều kiện người bán yêu cầu để in logo (\"You'll just need to send me the graphic file.\") và lời xác nhận \"I can do that.\" -> Chọn đúng vật phẩm được gửi.","optionAnalysis":{"A":"Khớp nguyên văn yêu cầu của người bán ở cuối thoại: \"You'll just need to send me the graphic file.\" và câu chốt \"I can do that.\"","B":"Hai người chỉ bàn việc in logo chung của công ty lên bình nước, không hề yêu cầu danh sách tên nhân viên.","C":"Chưa có trao đổi về địa chỉ giao nhận hàng; yêu cầu cụ thể duy nhất là gửi tệp thiết kế đồ họa logo.","D":"Không nhắc đến số tài khoản ngân hàng hay mã tài khoản khách hàng trong suốt cuộc gọi đặt hàng."},"evDocIdx":0,"evTargets":[{"badge":"Câu 64 · Đáp án A","opt":"A","isCorrect":true,"quote":"You'll just need to send me the graphic file.","viQuote":"Chị chỉ cần gửi cho tôi tệp đồ họa là được."}],"evQuotes":["You'll just need to send me the graphic file."]},{"q":65,"part":3,"group_id":"E25_T01_G65_67","audio":"web_assets/ets2025/audio/E25_T01/track_43.mp3","graphicImg":"web_assets/ets2025/gfx/E25_T01_Q65.webp","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_17.webp","web_assets/ets2025/tr/E25_T01_tr_18.webp"],"stem_en":"What type of art will be displayed in an exhibit?","stem_vi":"Loại hình nghệ thuật nào sẽ được trưng bày trong triển lãm?","options":{"A":{"en":"Clay sculptures","vi":"Tác phẩm điêu khắc đất sét"},"B":{"en":"Oil paintings","vi":"Tranh sơn dầu"},"C":{"en":"Black-and-white photographs","vi":"Ảnh đen trắng"},"D":{"en":"Pencil drawings","vi":"Tranh vẽ bút chì"}},"ans":"D","explanation":"Đáp án đúng: (D) Tranh vẽ bút chì — ngay câu đầu tiên, người phụ nữ thông báo cô vừa thu âm xong phần thuyết minh cho các bức vẽ bút chì sẽ góp mặt trong triển lãm nghệ thuật hiện đại tuần tới.\nDẫn chứng: \"I just finished recording the audio guide for the pencil drawings that'll be included in our modern art exhibit next week.\" (khớp trực tiếp cụm \"pencil drawings\").\nPhân tích bẫy:\n- (A) Tác phẩm điêu khắc đất sét không được nhắc tới; cả hai người đều nói về \"pencil drawings\" và \"drawing by Claudia Hoffman\".\n- (B) Bẫy liên tưởng quen thuộc khi nghe cụm \"modern art exhibit\" (triển lãm nghệ thuật hiện đại), nhưng chất liệu thực tế là tranh vẽ chì chứ không phải sơn dầu.\n- (C) Không có ảnh chụp hay nhiếp ảnh đen trắng nào được đề cập trong đoạn hội thoại.","lines":[{"speaker":"W-Br","en":"Yun, I just finished recording the audio guide for the pencil drawings that'll be included in our modern art exhibit next week. The files'll be loaded onto the audio devices tomorrow.","vi":"Yun à, tôi vừa thu âm xong phần thuyết minh tự động cho các bức vẽ bút chì sẽ được trưng bày trong triển lãm nghệ thuật hiện đại tuần tới của chúng ta. Các tệp âm thanh sẽ được nạp vào thiết bị nghe thuyết minh vào ngày mai.","units":[{"en":"Yun, I just finished recording the audio guide for the pencil drawings that'll be included in our modern art exhibit next week.","vi":"Yun à, tôi vừa thu âm xong phần thuyết minh tự động cho các bức vẽ bút chì sẽ được trưng bày trong triển lãm nghệ thuật hiện đại tuần tới của chúng ta."},{"en":"The files'll be loaded onto the audio devices tomorrow.","vi":"Các tệp âm thanh sẽ được nạp vào thiết bị nghe thuyết minh vào ngày mai."}]},{"speaker":"M-Cn","en":"That's great. But, unfortunately, we have to make one change. The drawing by Claudia Hoffman will no longer be in the exhibit. There was a scheduling mix-up, and it was promised to another museum starting next week.","vi":"Tuyệt quá. Nhưng rất tiếc là chúng ta phải thay đổi một chút. Bức vẽ của Claudia Hoffman sẽ không còn xuất hiện trong triển lãm nữa. Đã xảy ra sự nhầm lẫn về lịch trình, và tác phẩm đó đã được hẹn cho một bảo tàng khác mượn từ tuần tới.","units":[{"en":"That's great.","vi":"Tuyệt quá."},{"en":"But, unfortunately, we have to make one change.","vi":"Nhưng rất tiếc là chúng ta phải thay đổi một chút."},{"en":"The drawing by Claudia Hoffman will no longer be in the exhibit.","vi":"Bức vẽ của Claudia Hoffman sẽ không còn xuất hiện trong triển lãm nữa."},{"en":"There was a scheduling mix-up, and it was promised to another museum starting next week.","vi":"Đã xảy ra sự nhầm lẫn về lịch trình, và tác phẩm đó đã được hẹn cho một bảo tàng khác mượn từ tuần tới."}]},{"speaker":"W-Br","en":"Oh, that's too bad. That was one of my favorite pieces. Will you put anything in its place?","vi":"Ôi, tiếc quá. Đó là một trong những tác phẩm tôi thích nhất. Bạn có định trưng bày tác phẩm nào khác thay vào vị trí đó không?","units":[{"en":"Oh, that's too bad.","vi":"Ôi, tiếc quá."},{"en":"That was one of my favorite pieces.","vi":"Đó là một trong những tác phẩm tôi thích nhất."},{"en":"Will you put anything in its place?","vi":"Bạn có định trưng bày tác phẩm nào khác thay vào vị trí đó không?"}]},{"speaker":"M-Cn","en":"No. We'll just remove it.","vi":"Không. Chúng ta sẽ chỉ gỡ bỏ nó thôi.","units":[{"en":"No.","vi":"Không."},{"en":"We'll just remove it.","vi":"Chúng ta sẽ chỉ gỡ bỏ nó thôi."}]},{"speaker":"W-Br","en":"OK, then I'll make that change to the audio-guide recording. I'll do that right away.","vi":"Được rồi, vậy tôi sẽ chỉnh sửa lại bản thu âm hướng dẫn thuyết minh. Tôi sẽ làm ngay bây giờ.","units":[{"en":"OK, then I'll make that change to the audio-guide recording.","vi":"Được rồi, vậy tôi sẽ chỉnh sửa lại bản thu âm hướng dẫn thuyết minh."},{"en":"I'll do that right away.","vi":"Tôi sẽ làm ngay bây giờ."}]}],"vocab":[{"word":"audio guide","pos":"n","ipa":"/ˈɔːdioʊ ɡaɪd/","meaning":"thiết bị hoặc bản thu thuyết minh tự động"},{"word":"exhibit","pos":"n","ipa":"/ɪɡˈzɪbɪt/","meaning":"cuộc triển lãm"},{"word":"sculpture","pos":"n","ipa":"/ˈskʌlptʃər/","meaning":"tác phẩm điêu khắc"},{"word":"drawing","pos":"n","ipa":"/ˈdrɔːɪŋ/","meaning":"bức tranh vẽ"}],"isScanBacked":false,"grammarType":"Part 3 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 3 (Chi tiết loại hình sự kiện/trưng bày): Lắng nghe cụm danh từ xác định ngay câu mở đầu (\"recording the audio guide for the pencil drawings that'll be included in our modern art exhibit\") -> Chọn đúng chất liệu tác phẩm.","optionAnalysis":{"A":"Hội thoại không đề cập đến điêu khắc hay chất liệu đất sét; triển lãm trưng bày các bức vẽ.","B":"Bẫy suy đoán từ cụm \"modern art exhibit\"; bài nghe nêu đích danh là \"pencil drawings\" chứ không phải tranh sơn dầu.","C":"Không có chi tiết nào về ảnh chụp đen trắng; phần thuyết minh được thu cho các tác phẩm vẽ bút chì.","D":"Khớp chính xác cụm danh từ ở lượt nói đầu tiên: \"for the pencil drawings that'll be included in our modern art exhibit\"."},"evDocIdx":0,"evTargets":[{"badge":"Câu 65 · Đáp án D","opt":"D","isCorrect":true,"quote":"Yun, I just finished recording the audio guide for the pencil drawings that'll be included in our modern art exhibit next week.","viQuote":"Yun à, tôi vừa thu âm xong phần thuyết minh tự động cho các bức vẽ bút chì sẽ được trưng bày trong triển lãm nghệ thuật hiện đại tuần tới của chúng ta."}],"evQuotes":["Yun, I just finished recording the audio guide for the pencil drawings that'll be included in our modern art exhibit next week."]},{"q":66,"part":3,"group_id":"E25_T01_G65_67","audio":"web_assets/ets2025/audio/E25_T01/track_43.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"Look at the graphic. Which piece of artwork will no longer be included?","stem_vi":"Hãy nhìn vào hình ảnh. Tác phẩm nghệ thuật nào sẽ không còn được trưng bày nữa?","options":{"A":{"en":"A Careful Glance","vi":"Tác phẩm \"A Careful Glance\""},"B":{"en":"Promises","vi":"Tác phẩm \"Promises\""},"C":{"en":"Stormy Sea","vi":"Tác phẩm \"Stormy Sea\""},"D":{"en":"The Moment","vi":"Tác phẩm \"The Moment\""}},"ans":"C","explanation":"Đáp án đúng: (C) Tác phẩm \"Stormy Sea\" — người đàn ông thông báo bức vẽ của Claudia Hoffman sẽ không còn nằm trong triển lãm vì bị trùng lịch hẹn cho bảo tàng khác mượn; đối chiếu dòng 3 trong bảng Title | Artist, nghệ sĩ Claudia Hoffman ứng với tác phẩm \"Stormy Sea\".\nDẫn chứng: \"The drawing by Claudia Hoffman will no longer be in the exhibit.\" → Tra bảng 2 cột trong hình: dòng 3 cột Artist ghi \"Claudia Hoffman\" tương ứng cột Title là \"Stormy Sea\".\nPhân tích bẫy:\n- (A) Dòng 1 của bảng ghi \"A Careful Glance\" là tác phẩm của So-Jin Park, vẫn giữ nguyên trong triển lãm.\n- (B) Dòng 2 của bảng ghi \"Promises\" là tác phẩm của Vivek Madan, không bị nhầm lẫn lịch trình.\n- (D) Dòng 4 của bảng ghi \"The Moment\" là tác phẩm của Adisa Rotimi, không phải bức vẽ của Claudia Hoffman.","lines":[{"speaker":"W-Br","en":"Yun, I just finished recording the audio guide for the pencil drawings that'll be included in our modern art exhibit next week. The files'll be loaded onto the audio devices tomorrow.","vi":"Yun à, tôi vừa thu âm xong phần thuyết minh tự động cho các bức vẽ bút chì sẽ được trưng bày trong triển lãm nghệ thuật hiện đại tuần tới của chúng ta. Các tệp âm thanh sẽ được nạp vào thiết bị nghe thuyết minh vào ngày mai.","units":[{"en":"Yun, I just finished recording the audio guide for the pencil drawings that'll be included in our modern art exhibit next week.","vi":"Yun à, tôi vừa thu âm xong phần thuyết minh tự động cho các bức vẽ bút chì sẽ được trưng bày trong triển lãm nghệ thuật hiện đại tuần tới của chúng ta."},{"en":"The files'll be loaded onto the audio devices tomorrow.","vi":"Các tệp âm thanh sẽ được nạp vào thiết bị nghe thuyết minh vào ngày mai."}]},{"speaker":"M-Cn","en":"That's great. But, unfortunately, we have to make one change. The drawing by Claudia Hoffman will no longer be in the exhibit. There was a scheduling mix-up, and it was promised to another museum starting next week.","vi":"Tuyệt quá. Nhưng rất tiếc là chúng ta phải thay đổi một chút. Bức vẽ của Claudia Hoffman sẽ không còn xuất hiện trong triển lãm nữa. Đã xảy ra sự nhầm lẫn về lịch trình, và tác phẩm đó đã được hẹn cho một bảo tàng khác mượn từ tuần tới.","units":[{"en":"That's great.","vi":"Tuyệt quá."},{"en":"But, unfortunately, we have to make one change.","vi":"Nhưng rất tiếc là chúng ta phải thay đổi một chút."},{"en":"The drawing by Claudia Hoffman will no longer be in the exhibit.","vi":"Bức vẽ của Claudia Hoffman sẽ không còn xuất hiện trong triển lãm nữa."},{"en":"There was a scheduling mix-up, and it was promised to another museum starting next week.","vi":"Đã xảy ra sự nhầm lẫn về lịch trình, và tác phẩm đó đã được hẹn cho một bảo tàng khác mượn từ tuần tới."}]},{"speaker":"W-Br","en":"Oh, that's too bad. That was one of my favorite pieces. Will you put anything in its place?","vi":"Ôi, tiếc quá. Đó là một trong những tác phẩm tôi thích nhất. Bạn có định trưng bày tác phẩm nào khác thay vào vị trí đó không?","units":[{"en":"Oh, that's too bad.","vi":"Ôi, tiếc quá."},{"en":"That was one of my favorite pieces.","vi":"Đó là một trong những tác phẩm tôi thích nhất."},{"en":"Will you put anything in its place?","vi":"Bạn có định trưng bày tác phẩm nào khác thay vào vị trí đó không?"}]},{"speaker":"M-Cn","en":"No. We'll just remove it.","vi":"Không. Chúng ta sẽ chỉ gỡ bỏ nó thôi.","units":[{"en":"No.","vi":"Không."},{"en":"We'll just remove it.","vi":"Chúng ta sẽ chỉ gỡ bỏ nó thôi."}]},{"speaker":"W-Br","en":"OK, then I'll make that change to the audio-guide recording. I'll do that right away.","vi":"Được rồi, vậy tôi sẽ chỉnh sửa lại bản thu âm hướng dẫn thuyết minh. Tôi sẽ làm ngay bây giờ.","units":[{"en":"OK, then I'll make that change to the audio-guide recording.","vi":"Được rồi, vậy tôi sẽ chỉnh sửa lại bản thu âm hướng dẫn thuyết minh."},{"en":"I'll do that right away.","vi":"Tôi sẽ làm ngay bây giờ."}]}],"vocab":[{"word":"mix-up","pos":"n","ipa":"/ˈmɪksʌp/","meaning":"sự nhầm lẫn, trục trặc"},{"word":"no longer","pos":"adv","ipa":"/noʊ ˈlɔːŋɡər/","meaning":"không còn nữa"},{"word":"artwork","pos":"n","ipa":"/ˈɑːrtwɜːrk/","meaning":"tác phẩm nghệ thuật"}],"isScanBacked":false,"grammarType":"Part 3 — Kết hợp Hình ảnh & Bảng biểu (Graphic Question)","formula":"CÔNG THỨC PART 3 (Bảng 2 cột Title–Artist — Đối chiếu 2 bước): Nghe tên họa sĩ có tác phẩm bị rút khỏi triển lãm (\"The drawing by Claudia Hoffman will no longer be in the exhibit\") -> Dò cột Artist trong bảng để lấy tên tác phẩm ở cột Title.","optionAnalysis":{"A":"Theo dòng 1 của bảng, tác phẩm \"A Careful Glance\" thuộc về nghệ sĩ So-Jin Park, không bị rút khỏi triển lãm.","B":"Theo dòng 2 của bảng, tác phẩm \"Promises\" thuộc về nghệ sĩ Vivek Madan, không liên quan đến sự cố trùng lịch.","C":"Đối chiếu 2 bước: nghe tên nghệ sĩ \"Claudia Hoffman\" ở lời thoại → tra cột Artist dòng 3 trên bảng tương ứng cột Title là \"Stormy Sea\".","D":"Theo dòng 4 của bảng, tác phẩm \"The Moment\" thuộc về nghệ sĩ Adisa Rotimi, vẫn được trưng bày bình thường."},"evDocIdx":0,"evTargets":[{"badge":"Câu 66 · Đáp án C","opt":"C","isCorrect":true,"quote":"The drawing by Claudia Hoffman will no longer be in the exhibit.","viQuote":"Bức vẽ của Claudia Hoffman sẽ không còn xuất hiện trong triển lãm nữa."},{"badge":"Câu 66 · Đáp án C","opt":"C","isCorrect":true,"quote":"There was a scheduling mix-up, and it was promised to another museum starting next week.","viQuote":"Đã xảy ra sự nhầm lẫn về lịch trình, và tác phẩm đó đã được hẹn cho một bảo tàng khác mượn từ tuần tới."}],"evQuotes":["The drawing by Claudia Hoffman will no longer be in the exhibit.","There was a scheduling mix-up, and it was promised to another museum starting next week."]},{"q":67,"part":3,"group_id":"E25_T01_G65_67","audio":"web_assets/ets2025/audio/E25_T01/track_43.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the woman say she will do right away?","stem_vi":"Người phụ nữ nói cô ấy sẽ làm gì ngay lập tức?","options":{"A":{"en":"Speak with an artist","vi":"Trao đổi với một nghệ sĩ"},"B":{"en":"Edit a recording","vi":"Chỉnh sửa một bản thu âm"},"C":{"en":"Clean a gallery space","vi":"Dọn dẹp một không gian trưng bày"},"D":{"en":"Greet some visitors","vi":"Đón tiếp một số khách tham quan"}},"ans":"B","explanation":"Đáp án đúng: (B) Chỉnh sửa một bản thu âm — vì tác phẩm \"Stormy Sea\" bị gỡ bỏ mà không có tác phẩm thay thế, người phụ nữ quyết định sẽ chỉnh sửa lại ngay bản thu âm hướng dẫn thuyết minh trước khi nạp vào thiết bị ngày mai.\nDẫn chứng: \"OK, then I'll make that change to the audio-guide recording. I'll do that right away.\" (make that change to the audio-guide recording → Edit a recording).\nPhân tích bẫy:\n- (A) Người đàn ông đã trả lời rõ \"No. We'll just remove it.\" nên không cần liên hệ nghệ sĩ nào để mượn tác phẩm bù vào.\n- (C) Không có thông tin nào về việc dọn dẹp hay lau chùi phòng trưng bày; việc cô làm ngay là sửa file thu âm.\n- (D) Triển lãm tuần tới mới mở cửa (\"next week\") và các tệp âm thanh ngày mai mới chép vào thiết bị nên chưa có khách tham quan để đón tiếp.","lines":[{"speaker":"W-Br","en":"Yun, I just finished recording the audio guide for the pencil drawings that'll be included in our modern art exhibit next week. The files'll be loaded onto the audio devices tomorrow.","vi":"Yun à, tôi vừa thu âm xong phần thuyết minh tự động cho các bức vẽ bút chì sẽ được trưng bày trong triển lãm nghệ thuật hiện đại tuần tới của chúng ta. Các tệp âm thanh sẽ được nạp vào thiết bị nghe thuyết minh vào ngày mai.","units":[{"en":"Yun, I just finished recording the audio guide for the pencil drawings that'll be included in our modern art exhibit next week.","vi":"Yun à, tôi vừa thu âm xong phần thuyết minh tự động cho các bức vẽ bút chì sẽ được trưng bày trong triển lãm nghệ thuật hiện đại tuần tới của chúng ta."},{"en":"The files'll be loaded onto the audio devices tomorrow.","vi":"Các tệp âm thanh sẽ được nạp vào thiết bị nghe thuyết minh vào ngày mai."}]},{"speaker":"M-Cn","en":"That's great. But, unfortunately, we have to make one change. The drawing by Claudia Hoffman will no longer be in the exhibit. There was a scheduling mix-up, and it was promised to another museum starting next week.","vi":"Tuyệt quá. Nhưng rất tiếc là chúng ta phải thay đổi một chút. Bức vẽ của Claudia Hoffman sẽ không còn xuất hiện trong triển lãm nữa. Đã xảy ra sự nhầm lẫn về lịch trình, và tác phẩm đó đã được hẹn cho một bảo tàng khác mượn từ tuần tới.","units":[{"en":"That's great.","vi":"Tuyệt quá."},{"en":"But, unfortunately, we have to make one change.","vi":"Nhưng rất tiếc là chúng ta phải thay đổi một chút."},{"en":"The drawing by Claudia Hoffman will no longer be in the exhibit.","vi":"Bức vẽ của Claudia Hoffman sẽ không còn xuất hiện trong triển lãm nữa."},{"en":"There was a scheduling mix-up, and it was promised to another museum starting next week.","vi":"Đã xảy ra sự nhầm lẫn về lịch trình, và tác phẩm đó đã được hẹn cho một bảo tàng khác mượn từ tuần tới."}]},{"speaker":"W-Br","en":"Oh, that's too bad. That was one of my favorite pieces. Will you put anything in its place?","vi":"Ôi, tiếc quá. Đó là một trong những tác phẩm tôi thích nhất. Bạn có định trưng bày tác phẩm nào khác thay vào vị trí đó không?","units":[{"en":"Oh, that's too bad.","vi":"Ôi, tiếc quá."},{"en":"That was one of my favorite pieces.","vi":"Đó là một trong những tác phẩm tôi thích nhất."},{"en":"Will you put anything in its place?","vi":"Bạn có định trưng bày tác phẩm nào khác thay vào vị trí đó không?"}]},{"speaker":"M-Cn","en":"No. We'll just remove it.","vi":"Không. Chúng ta sẽ chỉ gỡ bỏ nó thôi.","units":[{"en":"No.","vi":"Không."},{"en":"We'll just remove it.","vi":"Chúng ta sẽ chỉ gỡ bỏ nó thôi."}]},{"speaker":"W-Br","en":"OK, then I'll make that change to the audio-guide recording. I'll do that right away.","vi":"Được rồi, vậy tôi sẽ chỉnh sửa lại bản thu âm hướng dẫn thuyết minh. Tôi sẽ làm ngay bây giờ.","units":[{"en":"OK, then I'll make that change to the audio-guide recording.","vi":"Được rồi, vậy tôi sẽ chỉnh sửa lại bản thu âm hướng dẫn thuyết minh."},{"en":"I'll do that right away.","vi":"Tôi sẽ làm ngay bây giờ."}]}],"vocab":[{"word":"recording","pos":"n","ipa":"/rɪˈkɔːrdɪŋ/","meaning":"bản thu âm"},{"word":"right away","pos":"adv","ipa":"/raɪt əˈweɪ/","meaning":"ngay lập tức"},{"word":"remove","pos":"v","ipa":"/rɪˈmuːv/","meaning":"gỡ bỏ, loại bỏ"}],"isScanBacked":false,"grammarType":"Part 3 — Hành động tiếp theo & Đề xuất (Next Step & Offer/Request)","formula":"CÔNG THỨC PART 3 (Hành động làm ngay lập tức): Bắt cụm trạng từ \"right away\" ở lượt thoại cuối cùng (\"make that change to the audio-guide recording. I'll do that right away.\") -> Paraphrase động từ (make that change to recording -> edit a recording).","optionAnalysis":{"A":"Người đàn ông khẳng định chỉ gỡ tác phẩm chứ không thay thế (\"No. We'll just remove it.\") nên cô không cần trao đổi với nghệ sĩ.","B":"Khớp trực tiếp lượt thoại cuối: \"I'll make that change to the audio-guide recording. I'll do that right away.\"","C":"Hội thoại không hề nhắc đến công việc dọn dẹp không gian trưng bày; nhiệm vụ của cô là phần thu âm thuyết minh.","D":"Triển lãm tuần sau mới diễn ra (\"next week\"), lúc này chưa có khách tham quan nào để đón tiếp."},"evDocIdx":0,"evTargets":[{"badge":"Câu 67 · Đáp án B","opt":"B","isCorrect":true,"quote":"OK, then I'll make that change to the audio-guide recording.","viQuote":"Được rồi, vậy tôi sẽ chỉnh sửa lại bản thu âm hướng dẫn thuyết minh."},{"badge":"Câu 67 · Đáp án B","opt":"B","isCorrect":true,"quote":"I'll do that right away.","viQuote":"Tôi sẽ làm ngay bây giờ."}],"evQuotes":["OK, then I'll make that change to the audio-guide recording.","I'll do that right away."]},{"q":68,"part":3,"group_id":"E25_T01_G68_70","audio":"web_assets/ets2025/audio/E25_T01/track_44.mp3","graphicImg":"web_assets/ets2025/gfx/E25_T01_Q68.webp","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_18.webp","web_assets/ets2025/tr/E25_T01_tr_19.webp"],"stem_en":"Who most likely are the speakers?","stem_vi":"Những người nói có khả năng là ai nhất?","options":{"A":{"en":"Urban planners","vi":"Các nhà quy hoạch đô thị"},"B":{"en":"Journalists","vi":"Các nhà báo"},"C":{"en":"Engineers","vi":"Các kỹ sư"},"D":{"en":"Environmental scientists","vi":"Các nhà khoa học môi trường"}},"ans":"B","explanation":"Đáp án đúng: (B) Các nhà báo — người đàn ông nhắc đến việc được phân công đưa tin về buổi họp báo cùng bảy hãng truyền thông lớn khác và rủ đồng nghiệp đối chiếu số liệu trước khi bắt đầu viết bài.\nDẫn chứng: \"I'm glad we were assigned to cover the press conference earlier today. I counted seven other major media networks there, in addition to ours.\" và \"Let's compare our facts before we start writing.\" (cover press conference + media networks + writing → Journalists).\nPhân tích bẫy:\n- (A) Bẫy liên tưởng từ việc thảo luận các địa điểm ven biển và tác động việc làm khu vực; hai người chỉ đi họp báo viết tin chứ không làm quy hoạch đô thị.\n- (C) Bẫy ngữ cảnh điện gió (\"assembling and maintaining the turbines\"); họ đưa tin về cơ hội việc làm kỹ thuật chứ không phải kỹ sư trực tiếp thi công.\n- (D) Dù nói về năng lượng tái tạo (\"offshore wind industry\"), vai trò thực sự của họ được lộ rõ qua cụm \"media networks\" và \"start writing\".","lines":[{"speaker":"M-Cn","en":"I'm glad we were assigned to cover the press conference earlier today. I counted seven other major media networks there, in addition to ours.","vi":"Tôi rất vui vì chúng ta được phân công đưa tin về buổi họp báo trước đó trong ngày. Ngoài đơn vị của chúng ta ra, tôi đếm được có bảy hãng truyền thông lớn khác cũng có mặt ở đó.","units":[{"en":"I'm glad we were assigned to cover the press conference earlier today.","vi":"Tôi rất vui vì chúng ta được phân công đưa tin về buổi họp báo trước đó trong ngày."},{"en":"I counted seven other major media networks there, in addition to ours.","vi":"Ngoài đơn vị của chúng ta ra, tôi đếm được có bảy hãng truyền thông lớn khác cũng có mặt ở đó."}]},{"speaker":"W-Am","en":"Well, the offshore wind industry is going to transform the way this region gets its power.","vi":"Ừ, ngành điện gió ngoài khơi sẽ làm thay đổi hoàn toàn cách khu vực này được cung cấp điện.","units":[{"en":"Well, the offshore wind industry is going to transform the way this region gets its power.","vi":"Ừ, ngành điện gió ngoài khơi sẽ làm thay đổi hoàn toàn cách khu vực này được cung cấp điện."}]},{"speaker":"M-Cn","en":"Agreed. Let's compare our facts before we start writing.","vi":"Đồng ý. Chúng ta hãy đối chiếu lại các thông tin thu thập được trước khi bắt đầu viết bài nhé.","units":[{"en":"Agreed.","vi":"Đồng ý."},{"en":"Let's compare our facts before we start writing.","vi":"Chúng ta hãy đối chiếu lại các thông tin thu thập được trước khi bắt đầu viết bài nhé."}]},{"speaker":"W-Am","en":"So the largest cluster of wind turbines—off the coast of Winston—is already built. The other sites are at different stages of construction, though Lanchester is also close to being done.","vi":"Vậy cụm tua-bin gió lớn nhất—nằm ngoài khơi Winston—đã được xây dựng xong. Các địa điểm khác đang ở những giai đoạn thi công khác nhau, mặc dù khu vực Lanchester cũng sắp hoàn thành rồi.","units":[{"en":"So the largest cluster of wind turbines—off the coast of Winston—is already built.","vi":"Vậy cụm tua-bin gió lớn nhất—nằm ngoài khơi Winston—đã được xây dựng xong."},{"en":"The other sites are at different stages of construction, though Lanchester is also close to being done.","vi":"Các địa điểm khác đang ở những giai đoạn thi công khác nhau, mặc dù khu vực Lanchester cũng sắp hoàn thành rồi."}]},{"speaker":"M-Cn","en":"Right. And I think it's crucial for us to focus on how many new jobs related to assembling and maintaining the turbines are opening up in the area as a result of this.","vi":"Đúng rồi. Và tôi nghĩ điều cốt yếu là chúng ta cần tập trung làm rõ xem nhờ đó có bao nhiêu việc làm mới liên quan đến lắp ráp và bảo trì tua-bin đang mở ra trong khu vực.","units":[{"en":"Right.","vi":"Đúng rồi."},{"en":"And I think it's crucial for us to focus on how many new jobs related to assembling and maintaining the turbines are opening up in the area as a result of this.","vi":"Và tôi nghĩ điều cốt yếu là chúng ta cần tập trung làm rõ xem nhờ đó có bao nhiêu việc làm mới liên quan đến lắp ráp và bảo trì tua-bin đang mở ra trong khu vực."}]}],"vocab":[{"word":"assign","pos":"v","ipa":"/əˈsaɪn/","meaning":"phân công"},{"word":"cover","pos":"v","ipa":"/ˈkʌvər/","meaning":"đưa tin (báo chí)"},{"word":"press conference","pos":"n","ipa":"/pres ˈkɑːnfərəns/","meaning":"buổi họp báo"},{"word":"journalist","pos":"n","ipa":"/ˈdʒɜːrnəlɪst/","meaning":"nhà báo"}],"isScanBacked":false,"grammarType":"Part 3 — Ngữ cảnh, Địa điểm & Danh tính người nói (Setting & Role)","formula":"CÔNG THỨC PART 3 (Suy luận nghề nghiệp từ cụm từ khóa truyền thông): Nối các dấu hiệu \"cover the press conference\", \"major media networks\" và \"compare our facts before we start writing\" -> Suy ra nghề nghiệp nhà báo / phóng viên.","optionAnalysis":{"A":"Dù bàn về các thị trấn ven biển và việc làm địa phương, hai người đi dự họp báo viết tin chứ không phải nhà quy hoạch đô thị.","B":"Được chứng minh qua chuỗi từ khóa báo chí: \"cover the press conference\", \"other major media networks\" và \"compare our facts before we start writing\".","C":"Bẫy liên tưởng từ \"assembling and maintaining the turbines\"; họ là phóng viên đưa tin về tác động việc làm chứ không phải kỹ sư lắp đặt.","D":"Bẫy chủ đề năng lượng gió; danh tính thực tế thuộc về đơn vị truyền thông (\"media networks\") chuẩn bị viết bài sau họp báo."},"evDocIdx":0,"evTargets":[{"badge":"Câu 68 · Đáp án B","opt":"B","isCorrect":true,"quote":"I'm glad we were assigned to cover the press conference earlier today.","viQuote":"Tôi rất vui vì chúng ta được phân công đưa tin về buổi họp báo trước đó trong ngày."},{"badge":"Câu 68 · Đáp án B","opt":"B","isCorrect":true,"quote":"I counted seven other major media networks there, in addition to ours.","viQuote":"Ngoài đơn vị của chúng ta ra, tôi đếm được có bảy hãng truyền thông lớn khác cũng có mặt ở đó."}],"evQuotes":["I'm glad we were assigned to cover the press conference earlier today.","I counted seven other major media networks there, in addition to ours."]},{"q":69,"part":3,"group_id":"E25_T01_G68_70","audio":"web_assets/ets2025/audio/E25_T01/track_44.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"Look at the graphic. Which site has already been completed?","stem_vi":"Hãy nhìn vào hình ảnh. Địa điểm nào đã được hoàn thành?","options":{"A":{"en":"Site A","vi":"Địa điểm A"},"B":{"en":"Site B","vi":"Địa điểm B"},"C":{"en":"Site C","vi":"Địa điểm C"},"D":{"en":"Site D","vi":"Địa điểm D"}},"ans":"D","explanation":"Đáp án đúng: (D) Địa điểm D — người phụ nữ cho biết cụm tua-bin gió lớn nhất nằm ngoài khơi bờ biển Winston đã được xây dựng xong; trên bản đồ ven biển, thị trấn Winston ở phía nam cùng có mũi tên nối với \"Site D (70 Wind Turbines)\" — cũng là cụm có số tua-bin lớn nhất.\nDẫn chứng: \"So the largest cluster of wind turbines—off the coast of Winston—is already built.\" → Tra bản đồ: tên địa danh \"Winston\" ở góc dưới bên trái có mũi tên trỏ sang vòng tròn \"Site D — 70 Wind Turbines\" (already built → completed).\nPhân tích bẫy:\n- (A) Trên bản đồ, Site A (55 Wind Turbines) nằm ngoài khơi Bayport; theo bài nghe các địa điểm khác ngoài Winston vẫn đang trong các giai đoạn thi công.\n- (B) Trên bản đồ, Site B (60 Wind Turbines) nằm ngoài khơi Clarksville, không phải cụm lớn nhất và chưa xây xong.\n- (C) Bẫy thông tin gần đúng: trên bản đồ Site C (35 Wind Turbines) nằm ngoài khơi Lanchester, mà trong bài người phụ nữ chỉ nói Lanchester sắp xong (\"close to being done\"), chưa hoàn thành.","lines":[{"speaker":"M-Cn","en":"I'm glad we were assigned to cover the press conference earlier today. I counted seven other major media networks there, in addition to ours.","vi":"Tôi rất vui vì chúng ta được phân công đưa tin về buổi họp báo trước đó trong ngày. Ngoài đơn vị của chúng ta ra, tôi đếm được có bảy hãng truyền thông lớn khác cũng có mặt ở đó.","units":[{"en":"I'm glad we were assigned to cover the press conference earlier today.","vi":"Tôi rất vui vì chúng ta được phân công đưa tin về buổi họp báo trước đó trong ngày."},{"en":"I counted seven other major media networks there, in addition to ours.","vi":"Ngoài đơn vị của chúng ta ra, tôi đếm được có bảy hãng truyền thông lớn khác cũng có mặt ở đó."}]},{"speaker":"W-Am","en":"Well, the offshore wind industry is going to transform the way this region gets its power.","vi":"Ừ, ngành điện gió ngoài khơi sẽ làm thay đổi hoàn toàn cách khu vực này được cung cấp điện.","units":[{"en":"Well, the offshore wind industry is going to transform the way this region gets its power.","vi":"Ừ, ngành điện gió ngoài khơi sẽ làm thay đổi hoàn toàn cách khu vực này được cung cấp điện."}]},{"speaker":"M-Cn","en":"Agreed. Let's compare our facts before we start writing.","vi":"Đồng ý. Chúng ta hãy đối chiếu lại các thông tin thu thập được trước khi bắt đầu viết bài nhé.","units":[{"en":"Agreed.","vi":"Đồng ý."},{"en":"Let's compare our facts before we start writing.","vi":"Chúng ta hãy đối chiếu lại các thông tin thu thập được trước khi bắt đầu viết bài nhé."}]},{"speaker":"W-Am","en":"So the largest cluster of wind turbines—off the coast of Winston—is already built. The other sites are at different stages of construction, though Lanchester is also close to being done.","vi":"Vậy cụm tua-bin gió lớn nhất—nằm ngoài khơi Winston—đã được xây dựng xong. Các địa điểm khác đang ở những giai đoạn thi công khác nhau, mặc dù khu vực Lanchester cũng sắp hoàn thành rồi.","units":[{"en":"So the largest cluster of wind turbines—off the coast of Winston—is already built.","vi":"Vậy cụm tua-bin gió lớn nhất—nằm ngoài khơi Winston—đã được xây dựng xong."},{"en":"The other sites are at different stages of construction, though Lanchester is also close to being done.","vi":"Các địa điểm khác đang ở những giai đoạn thi công khác nhau, mặc dù khu vực Lanchester cũng sắp hoàn thành rồi."}]},{"speaker":"M-Cn","en":"Right. And I think it's crucial for us to focus on how many new jobs related to assembling and maintaining the turbines are opening up in the area as a result of this.","vi":"Đúng rồi. Và tôi nghĩ điều cốt yếu là chúng ta cần tập trung làm rõ xem nhờ đó có bao nhiêu việc làm mới liên quan đến lắp ráp và bảo trì tua-bin đang mở ra trong khu vực.","units":[{"en":"Right.","vi":"Đúng rồi."},{"en":"And I think it's crucial for us to focus on how many new jobs related to assembling and maintaining the turbines are opening up in the area as a result of this.","vi":"Và tôi nghĩ điều cốt yếu là chúng ta cần tập trung làm rõ xem nhờ đó có bao nhiêu việc làm mới liên quan đến lắp ráp và bảo trì tua-bin đang mở ra trong khu vực."}]}],"vocab":[{"word":"cluster","pos":"n","ipa":"/ˈklʌstər/","meaning":"cụm, nhóm"},{"word":"wind turbine","pos":"n","ipa":"/wɪnd ˈtɜːrbaɪn/","meaning":"tua-bin gió"},{"word":"off the coast","pos":"phr","ipa":"/ɔːf ðə koʊst/","meaning":"ngoài khơi bờ biển"},{"word":"construction","pos":"n","ipa":"/kənˈstrʌkʃən/","meaning":"việc xây dựng, thi công"}],"isScanBacked":false,"grammarType":"Part 3 — Kết hợp Hình ảnh & Bảng biểu (Graphic Question)","formula":"CÔNG THỨC PART 3 (Bản đồ khu vực — Đối chiếu 2 bước): Nghe dấu hiệu vị trí hoàn thành trên lời thoại (\"the largest cluster of wind turbines—off the coast of Winston—is already built\") -> Dò tên thị trấn Winston trên bản đồ theo mũi tên để chọn đúng mã Site.","optionAnalysis":{"A":"Trên bản đồ, Site A (55 tua-bin) ứng với thị trấn Bayport ở cực bắc, chưa hoàn thành và không khớp vị trí ngoài khơi Winston.","B":"Trên bản đồ, Site B (60 tua-bin) ứng với Clarksville; bài nghe nói các điểm khác ngoài Winston vẫn đang ở các giai đoạn thi công.","C":"Bẫy câu nói kế tiếp: Site C (35 tua-bin) ứng với Lanchester nhưng chỉ mới \"close to being done\" (sắp xong), chưa xây xong hẳn.","D":"Đối chiếu 2 bước: nghe \"the largest cluster of wind turbines—off the coast of Winston—is already built\" → tra bản đồ thấy Winston nối mũi tên với Site D (70 Wind Turbines)."},"evDocIdx":0,"evTargets":[{"badge":"Câu 69 · Đáp án D","opt":"D","isCorrect":true,"quote":"So the largest cluster of wind turbines—off the coast of Winston—is already built.","viQuote":"Vậy cụm tua-bin gió lớn nhất—nằm ngoài khơi Winston—đã được xây dựng xong."}],"evQuotes":["So the largest cluster of wind turbines—off the coast of Winston—is already built."]},{"q":70,"part":3,"group_id":"E25_T01_G68_70","audio":"web_assets/ets2025/audio/E25_T01/track_44.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the man suggest focusing on?","stem_vi":"Người đàn ông đề xuất nên tập trung vào điều gì?","options":{"A":{"en":"Work opportunities","vi":"Các cơ hội việc làm"},"B":{"en":"Wind turbine costs","vi":"Chi phí tua-bin gió"},"C":{"en":"Supply chain issues","vi":"Các vấn đề về chuỗi cung ứng"},"D":{"en":"Power capacity","vi":"Công suất phát điện"}},"ans":"A","explanation":"Đáp án đúng: (A) Các cơ hội việc làm — ở lượt cuối cùng, người đàn ông nhấn mạnh điều cốt yếu là bài viết cần tập trung vào việc có bao nhiêu việc làm mới liên quan đến lắp ráp và bảo trì tua-bin đang mở ra trong khu vực.\nDẫn chứng: \"And I think it's crucial for us to focus on how many new jobs related to assembling and maintaining the turbines are opening up in the area as a result of this.\" (new jobs opening up → Work opportunities).\nPhân tích bẫy:\n- (B) Hội thoại không nhắc đến giá tiền hay chi phí đầu tư sản xuất tua-bin gió.\n- (C) Không có vấn đề nào về chuỗi cung ứng hay thiếu hụt linh kiện được nêu ra trong buổi họp báo.\n- (D) Bẫy liên tưởng từ câu nhận xét trước của người phụ nữ (\"transform the way this region gets its power\") và số lượng tua-bin trên bản đồ, nhưng góc độ người đàn ông đề xuất tập trung lại là cơ hội việc làm.","lines":[{"speaker":"M-Cn","en":"I'm glad we were assigned to cover the press conference earlier today. I counted seven other major media networks there, in addition to ours.","vi":"Tôi rất vui vì chúng ta được phân công đưa tin về buổi họp báo trước đó trong ngày. Ngoài đơn vị của chúng ta ra, tôi đếm được có bảy hãng truyền thông lớn khác cũng có mặt ở đó.","units":[{"en":"I'm glad we were assigned to cover the press conference earlier today.","vi":"Tôi rất vui vì chúng ta được phân công đưa tin về buổi họp báo trước đó trong ngày."},{"en":"I counted seven other major media networks there, in addition to ours.","vi":"Ngoài đơn vị của chúng ta ra, tôi đếm được có bảy hãng truyền thông lớn khác cũng có mặt ở đó."}]},{"speaker":"W-Am","en":"Well, the offshore wind industry is going to transform the way this region gets its power.","vi":"Ừ, ngành điện gió ngoài khơi sẽ làm thay đổi hoàn toàn cách khu vực này được cung cấp điện.","units":[{"en":"Well, the offshore wind industry is going to transform the way this region gets its power.","vi":"Ừ, ngành điện gió ngoài khơi sẽ làm thay đổi hoàn toàn cách khu vực này được cung cấp điện."}]},{"speaker":"M-Cn","en":"Agreed. Let's compare our facts before we start writing.","vi":"Đồng ý. Chúng ta hãy đối chiếu lại các thông tin thu thập được trước khi bắt đầu viết bài nhé.","units":[{"en":"Agreed.","vi":"Đồng ý."},{"en":"Let's compare our facts before we start writing.","vi":"Chúng ta hãy đối chiếu lại các thông tin thu thập được trước khi bắt đầu viết bài nhé."}]},{"speaker":"W-Am","en":"So the largest cluster of wind turbines—off the coast of Winston—is already built. The other sites are at different stages of construction, though Lanchester is also close to being done.","vi":"Vậy cụm tua-bin gió lớn nhất—nằm ngoài khơi Winston—đã được xây dựng xong. Các địa điểm khác đang ở những giai đoạn thi công khác nhau, mặc dù khu vực Lanchester cũng sắp hoàn thành rồi.","units":[{"en":"So the largest cluster of wind turbines—off the coast of Winston—is already built.","vi":"Vậy cụm tua-bin gió lớn nhất—nằm ngoài khơi Winston—đã được xây dựng xong."},{"en":"The other sites are at different stages of construction, though Lanchester is also close to being done.","vi":"Các địa điểm khác đang ở những giai đoạn thi công khác nhau, mặc dù khu vực Lanchester cũng sắp hoàn thành rồi."}]},{"speaker":"M-Cn","en":"Right. And I think it's crucial for us to focus on how many new jobs related to assembling and maintaining the turbines are opening up in the area as a result of this.","vi":"Đúng rồi. Và tôi nghĩ điều cốt yếu là chúng ta cần tập trung làm rõ xem nhờ đó có bao nhiêu việc làm mới liên quan đến lắp ráp và bảo trì tua-bin đang mở ra trong khu vực.","units":[{"en":"Right.","vi":"Đúng rồi."},{"en":"And I think it's crucial for us to focus on how many new jobs related to assembling and maintaining the turbines are opening up in the area as a result of this.","vi":"Và tôi nghĩ điều cốt yếu là chúng ta cần tập trung làm rõ xem nhờ đó có bao nhiêu việc làm mới liên quan đến lắp ráp và bảo trì tua-bin đang mở ra trong khu vực."}]}],"vocab":[{"word":"crucial","pos":"adj","ipa":"/ˈkruːʃəl/","meaning":"cốt yếu, tối quan trọng"},{"word":"assemble","pos":"v","ipa":"/əˈsembəl/","meaning":"lắp ráp"},{"word":"maintain","pos":"v","ipa":"/meɪnˈteɪn/","meaning":"bảo trì, duy trì"},{"word":"open up","pos":"phr. v","ipa":"/ˈoʊpən ʌp/","meaning":"mở ra (cơ hội, việc làm)"}],"isScanBacked":false,"grammarType":"Part 3 — Hành động tiếp theo & Đề xuất (Next Step & Offer/Request)","formula":"CÔNG THỨC PART 3 (Đề xuất trọng tâm bài viết): Nghe cấu trúc nhấn mạnh ở lượt cuối (\"I think it's crucial for us to focus on how many new jobs\") -> Paraphrase \"new jobs opening up\" thành \"Work opportunities\".","optionAnalysis":{"A":"Paraphrase trực tiếp từ lượt cuối của người đàn ông: \"focus on how many new jobs related to assembling and maintaining the turbines are opening up in the area\" (cơ hội việc làm mới).","B":"Hội thoại hoàn toàn không đề cập đến chi phí chế tạo hay ngân sách đầu tư cho tua-bin gió.","C":"Không có thông tin nào về chuỗi cung ứng hay khâu vận chuyển thiết bị trong bài nghe.","D":"Bẫy ngữ cảnh từ câu trước của người phụ nữ về nguồn điện khu vực và các con số tua-bin trên bản đồ, không phải trọng tâm người đàn ông gợi ý."},"evDocIdx":0,"evTargets":[{"badge":"Câu 70 · Đáp án A","opt":"A","isCorrect":true,"quote":"And I think it's crucial for us to focus on how many new jobs related to assembling and maintaining the turbines are opening up in the area as a result of this.","viQuote":"Và tôi nghĩ điều cốt yếu là chúng ta cần tập trung làm rõ xem nhờ đó có bao nhiêu việc làm mới liên quan đến lắp ráp và bảo trì tua-bin đang mở ra trong khu vực."}],"evQuotes":["And I think it's crucial for us to focus on how many new jobs related to assembling and maintaining the turbines are opening up in the area as a result of this."]},{"q":71,"part":4,"group_id":"E25_T01_G71_73","audio":"web_assets/ets2025/audio/E25_T01/track_45.mp3","graphicImg":null,"transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_20.webp","web_assets/ets2025/tr/E25_T01_tr_24.webp"],"stem_en":"Who has recorded the message?","stem_vi":"Ai đã ghi âm tin nhắn này?","options":{"A":{"en":"A city mayor's office","vi":"Văn phòng thị trưởng thành phố"},"B":{"en":"A maintenance department","vi":"Bộ phận bảo trì"},"C":{"en":"An automobile dealership","vi":"Đại lý ô tô"},"D":{"en":"A building management office","vi":"Văn phòng quản lý tòa nhà"}},"ans":"D","explanation":"Đáp án đúng: (D) Văn phòng quản lý tòa nhà — Câu chào mở đầu xác nhận đường dây thông tin này thuộc về văn phòng quản lý khu căn hộ Cranbury Apartments (\"management office\" → \"A building management office\").\nDẫn chứng: \"You have reached the information line for the Cranbury Apartments management office.\" (Quý vị đã gọi đến đường dây thông tin của văn phòng quản lý khu căn hộ Cranbury Apartments.)\nPhân tích bẫy:\n- (A) Văn phòng thị trưởng thành phố không được nhắc tới; tin nhắn chỉ phục vụ cư dân một khu căn hộ.\n- (B) Bẫy lặp từ \"maintenance\": bài nói nhắc đến \"maintenance work\" (công tác bảo trì trải nhựa), nhưng đây là công việc sắp triển khai chứ không phải đơn vị ghi âm tin nhắn.\n- (C) Bẫy liên tưởng từ \"vehicles\" (phương tiện): xe cộ được nhắc đến liên quan đến việc di chuyển khỏi bãi đỗ xe, không liên quan đến đại lý bán ô tô.","lines":[{"speaker":"M-Au (Tin nhắn ghi âm)","en":"You have reached the information line for the Cranbury Apartments management office. On Monday, April twelfth, maintenance work will begin to repave the entire parking area adjacent to our building's main entrance.","vi":"Quý vị đã gọi đến đường dây thông tin của văn phòng quản lý khu căn hộ Cranbury Apartments. Vào thứ Hai, ngày 12 tháng 4, công tác bảo trì sẽ bắt đầu nhằm trải nhựa lại toàn bộ khu vực bãi đỗ xe nằm liền kề lối vào chính của tòa nhà.","units":[{"en":"You have reached the information line for the Cranbury Apartments management office.","vi":"Quý vị đã gọi đến đường dây thông tin của văn phòng quản lý khu căn hộ Cranbury Apartments."},{"en":"On Monday, April twelfth, maintenance work will begin to repave the entire parking area adjacent to our building's main entrance.","vi":"Vào thứ Hai, ngày 12 tháng 4, công tác bảo trì sẽ bắt đầu nhằm trải nhựa lại toàn bộ khu vực bãi đỗ xe nằm liền kề lối vào chính của tòa nhà."}]},{"speaker":"M-Au","en":"All Cranbury residents should move their vehicles from their designated parking spots before eight A.M. on Monday. Any vehicle still in its spot after eight A.M. will be towed at the owner's expense.","vi":"Tất cả cư dân Cranbury cần di chuyển phương tiện ra khỏi vị trí đỗ xe được chỉ định trước 8 giờ sáng thứ Hai. Bất kỳ phương tiện nào vẫn còn đỗ tại chỗ sau 8 giờ sáng sẽ bị kéo đi với chi phí do chủ xe chi trả.","units":[{"en":"All Cranbury residents should move their vehicles from their designated parking spots before eight A.M. on Monday.","vi":"Tất cả cư dân Cranbury cần di chuyển phương tiện ra khỏi vị trí đỗ xe được chỉ định trước 8 giờ sáng thứ Hai."},{"en":"Any vehicle still in its spot after eight A.M. will be towed at the owner's expense.","vi":"Bất kỳ phương tiện nào vẫn còn đỗ tại chỗ sau 8 giờ sáng sẽ bị kéo đi với chi phí do chủ xe chi trả."}]},{"speaker":"M-Au","en":"A map of alternate parking sites was mailed to residents last week and is also posted in the building lobby.","vi":"Bản đồ các điểm đỗ xe thay thế đã được gửi qua đường bưu điện đến cư dân vào tuần trước và cũng được niêm yết tại sảnh tòa nhà.","units":[{"en":"A map of alternate parking sites was mailed to residents last week and is also posted in the building lobby.","vi":"Bản đồ các điểm đỗ xe thay thế đã được gửi qua đường bưu điện đến cư dân vào tuần trước và cũng được niêm yết tại sảnh tòa nhà."}]}],"vocab":[{"word":"management","pos":"n","ipa":"/ˈmænɪdʒmənt/","meaning":"ban quản lý, sự quản lý"},{"word":"repave","pos":"v","ipa":"/ˌriːˈpeɪv/","meaning":"trải nhựa lại, lát lại mặt đường"},{"word":"adjacent","pos":"adj","ipa":"/əˈdʒeɪsənt/","meaning":"nằm liền kề, kế bên"},{"word":"maintenance","pos":"n","ipa":"/ˈmeɪntənəns/","meaning":"công tác bảo trì, bảo dưỡng"}],"isScanBacked":false,"grammarType":"Part 4 — Ngữ cảnh, Địa điểm & Danh tính người nói (Setting & Role)","formula":"CÔNG THỨC PART 4 (PART 4 THUỘC LÒNG — Ngữ cảnh & Danh tính người nói): Nghe câu chào mở đầu tin nhắn ghi âm (\"You have reached...\") để xác định ngay tổ chức phát ngôn, tránh bẫy lặp từ \"maintenance\" hay \"vehicles\" ở các câu sau.","optionAnalysis":{"A":"Sai ngữ cảnh hành chính: Tin nhắn dành riêng cho cư dân khu căn hộ Cranbury Apartments, không có chi tiết nào về văn phòng thị trưởng.","B":"Bẫy lặp từ \"maintenance\": Bài nói nhắc tới \"maintenance work\" (công tác bảo trì bãi đỗ xe), không phải bộ phận bảo trì là đơn vị ghi âm tin nhắn.","C":"Bẫy suy diễn theo từ \"vehicles\": Xe cộ được đề cập để yêu cầu cư dân di chuyển khỏi bãi đỗ, hoàn toàn không liên quan đến đại lý ô tô.","D":"Chính xác: Câu mở đầu \"You have reached the information line for the Cranbury Apartments management office\" khẳng định đây là văn phòng quản lý tòa nhà."},"evDocIdx":0,"evTargets":[{"badge":"Câu 71 · Đáp án D","opt":"D","isCorrect":true,"quote":"You have reached the information line for the Cranbury Apartments management office.","viQuote":"Quý vị đã gọi đến đường dây thông tin của văn phòng quản lý khu căn hộ Cranbury Apartments."}],"evQuotes":["You have reached the information line for the Cranbury Apartments management office."]},{"q":72,"part":4,"group_id":"E25_T01_G71_73","audio":"web_assets/ets2025/audio/E25_T01/track_45.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What are the listeners asked to do?","stem_vi":"Người nghe được yêu cầu làm gì?","options":{"A":{"en":"Move their vehicles","vi":"Di chuyển phương tiện của họ"},"B":{"en":"Pay their parking fines","vi":"Đóng tiền phạt đỗ xe"},"C":{"en":"Use an alternate entrance","vi":"Sử dụng một lối vào thay thế"},"D":{"en":"Participate in a meeting","vi":"Tham gia một cuộc họp"}},"ans":"A","explanation":"Đáp án đúng: (A) Di chuyển phương tiện của họ — Người nói yêu cầu toàn bộ cư dân dời xe khỏi vị trí đỗ trước 8 giờ sáng thứ Hai để phục vụ việc trải nhựa bãi đỗ xe.\nDẫn chứng: \"All Cranbury residents should move their vehicles from their designated parking spots before eight A.M. on Monday.\" (Tất cả cư dân Cranbury cần di chuyển phương tiện ra khỏi vị trí đỗ được chỉ định trước 8 giờ sáng thứ Hai.)\nPhân tích bẫy:\n- (B) Bẫy liên tưởng tiền phạt: bài nói cảnh báo xe còn đỗ sau 8 giờ sáng sẽ bị kéo đi và chủ xe chịu chi phí (\"towed at the owner's expense\"), không yêu cầu đóng tiền phạt đỗ xe ngay.\n- (C) Bẫy ghép từ \"alternate\" + \"entrance\": bài nói nhắc đến \"alternate parking sites\" (điểm đỗ xe thay thế) và \"main entrance\" (lối vào chính), không yêu cầu dùng lối vào thay thế.\n- (D) Không có thông tin nào trong tin nhắn kêu gọi cư dân tham dự cuộc họp.","lines":[{"speaker":"M-Au (Tin nhắn ghi âm)","en":"You have reached the information line for the Cranbury Apartments management office. On Monday, April twelfth, maintenance work will begin to repave the entire parking area adjacent to our building's main entrance.","vi":"Quý vị đã gọi đến đường dây thông tin của văn phòng quản lý khu căn hộ Cranbury Apartments. Vào thứ Hai, ngày 12 tháng 4, công tác bảo trì sẽ bắt đầu nhằm trải nhựa lại toàn bộ khu vực bãi đỗ xe nằm liền kề lối vào chính của tòa nhà.","units":[{"en":"You have reached the information line for the Cranbury Apartments management office.","vi":"Quý vị đã gọi đến đường dây thông tin của văn phòng quản lý khu căn hộ Cranbury Apartments."},{"en":"On Monday, April twelfth, maintenance work will begin to repave the entire parking area adjacent to our building's main entrance.","vi":"Vào thứ Hai, ngày 12 tháng 4, công tác bảo trì sẽ bắt đầu nhằm trải nhựa lại toàn bộ khu vực bãi đỗ xe nằm liền kề lối vào chính của tòa nhà."}]},{"speaker":"M-Au","en":"All Cranbury residents should move their vehicles from their designated parking spots before eight A.M. on Monday. Any vehicle still in its spot after eight A.M. will be towed at the owner's expense.","vi":"Tất cả cư dân Cranbury cần di chuyển phương tiện ra khỏi vị trí đỗ xe được chỉ định trước 8 giờ sáng thứ Hai. Bất kỳ phương tiện nào vẫn còn đỗ tại chỗ sau 8 giờ sáng sẽ bị kéo đi với chi phí do chủ xe chi trả.","units":[{"en":"All Cranbury residents should move their vehicles from their designated parking spots before eight A.M. on Monday.","vi":"Tất cả cư dân Cranbury cần di chuyển phương tiện ra khỏi vị trí đỗ xe được chỉ định trước 8 giờ sáng thứ Hai."},{"en":"Any vehicle still in its spot after eight A.M. will be towed at the owner's expense.","vi":"Bất kỳ phương tiện nào vẫn còn đỗ tại chỗ sau 8 giờ sáng sẽ bị kéo đi với chi phí do chủ xe chi trả."}]},{"speaker":"M-Au","en":"A map of alternate parking sites was mailed to residents last week and is also posted in the building lobby.","vi":"Bản đồ các điểm đỗ xe thay thế đã được gửi qua đường bưu điện đến cư dân vào tuần trước và cũng được niêm yết tại sảnh tòa nhà.","units":[{"en":"A map of alternate parking sites was mailed to residents last week and is also posted in the building lobby.","vi":"Bản đồ các điểm đỗ xe thay thế đã được gửi qua đường bưu điện đến cư dân vào tuần trước và cũng được niêm yết tại sảnh tòa nhà."}]}],"vocab":[{"word":"resident","pos":"n","ipa":"/ˈrezɪdənt/","meaning":"cư dân"},{"word":"designated","pos":"adj","ipa":"/ˈdezɪɡneɪtɪd/","meaning":"được chỉ định, quy định"},{"word":"tow","pos":"v","ipa":"/toʊ/","meaning":"kéo xe (vi phạm)"},{"word":"at the owner's expense","pos":"phr","ipa":"/æt ði ˈoʊnərz ɪkˈspens/","meaning":"chi phí do chủ xe tự chi trả"}],"isScanBacked":false,"grammarType":"Part 4 — Hành động tiếp theo & Đề xuất (Next Step & Offer/Request)","formula":"CÔNG THỨC PART 4 (PART 4 THUỘC LÒNG — Yêu cầu người nghe): Bắt các động từ khuyết thiếu chỉ yêu cầu như \"should / need to / must\" ở thân bài (\"All Cranbury residents should move...\") và loại bẫy ghép từ trái ngữ cảnh.","optionAnalysis":{"A":"Chính xác: Khớp trực tiếp yêu cầu \"All Cranbury residents should move their vehicles from their designated parking spots before eight A.M. on Monday.\"","B":"Bẫy suy diễn chi phí kéo xe: Bài nói cảnh báo xe đỗ quá giờ sẽ bị kéo đi do chủ xe chịu phí, không phải yêu cầu nộp phạt đỗ xe.","C":"Bẫy ghép từ (\"alternate\" + \"entrance\"): \"alternate\" đi với \"parking sites\" (bãi đỗ thay thế), còn \"main entrance\" chỉ mốc vị trí bãi đỗ chứ không yêu cầu đổi lối vào.","D":"Thông tin bịa đặt: Tin nhắn thông báo bảo trì bãi đỗ xe không hề đề cập đến việc tổ chức hay tham gia cuộc họp nào."},"evDocIdx":0,"evTargets":[{"badge":"Câu 72 · Đáp án A","opt":"A","isCorrect":true,"quote":"All Cranbury residents should move their vehicles from their designated parking spots before eight A.M. on Monday.","viQuote":"Tất cả cư dân Cranbury cần di chuyển phương tiện ra khỏi vị trí đỗ xe được chỉ định trước 8 giờ sáng thứ Hai."}],"evQuotes":["All Cranbury residents should move their vehicles from their designated parking spots before eight A.M. on Monday."]},{"q":73,"part":4,"group_id":"E25_T01_G71_73","audio":"web_assets/ets2025/audio/E25_T01/track_45.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the speaker say was mailed last week?","stem_vi":"Người nói cho biết thứ gì đã được gửi qua đường bưu điện vào tuần trước?","options":{"A":{"en":"An election ballot","vi":"Một lá phiếu bầu cử"},"B":{"en":"A maintenance plan","vi":"Một kế hoạch bảo trì"},"C":{"en":"A map","vi":"Một tấm bản đồ"},"D":{"en":"A coupon","vi":"Một phiếu giảm giá"}},"ans":"C","explanation":"Đáp án đúng: (C) Một tấm bản đồ — Câu cuối của tin nhắn nêu rõ bản đồ các điểm đỗ xe thay thế đã được gửi qua đường bưu điện cho cư dân vào tuần trước.\nDẫn chứng: \"A map of alternate parking sites was mailed to residents last week and is also posted in the building lobby.\" (Bản đồ các điểm đỗ xe thay thế đã được gửi qua đường bưu điện đến cư dân vào tuần trước và cũng được niêm yết tại sảnh tòa nhà.)\nPhân tích bẫy:\n- (A) Phiếu bầu cử hoàn toàn không xuất hiện trong bối cảnh thông báo bảo trì bãi đỗ xe này.\n- (B) Bẫy lặp từ \"maintenance\": công tác bảo trì được nhắc ở đầu bài, nhưng thứ được gửi qua bưu điện tuần trước là bản đồ bãi đỗ xe, không phải kế hoạch bảo trì.\n- (D) Phiếu giảm giá không được đề cập; cư dân không nhận được ưu đãi mua sắm nào trong tin nhắn này.","lines":[{"speaker":"M-Au (Tin nhắn ghi âm)","en":"You have reached the information line for the Cranbury Apartments management office. On Monday, April twelfth, maintenance work will begin to repave the entire parking area adjacent to our building's main entrance.","vi":"Quý vị đã gọi đến đường dây thông tin của văn phòng quản lý khu căn hộ Cranbury Apartments. Vào thứ Hai, ngày 12 tháng 4, công tác bảo trì sẽ bắt đầu nhằm trải nhựa lại toàn bộ khu vực bãi đỗ xe nằm liền kề lối vào chính của tòa nhà.","units":[{"en":"You have reached the information line for the Cranbury Apartments management office.","vi":"Quý vị đã gọi đến đường dây thông tin của văn phòng quản lý khu căn hộ Cranbury Apartments."},{"en":"On Monday, April twelfth, maintenance work will begin to repave the entire parking area adjacent to our building's main entrance.","vi":"Vào thứ Hai, ngày 12 tháng 4, công tác bảo trì sẽ bắt đầu nhằm trải nhựa lại toàn bộ khu vực bãi đỗ xe nằm liền kề lối vào chính của tòa nhà."}]},{"speaker":"M-Au","en":"All Cranbury residents should move their vehicles from their designated parking spots before eight A.M. on Monday. Any vehicle still in its spot after eight A.M. will be towed at the owner's expense.","vi":"Tất cả cư dân Cranbury cần di chuyển phương tiện ra khỏi vị trí đỗ xe được chỉ định trước 8 giờ sáng thứ Hai. Bất kỳ phương tiện nào vẫn còn đỗ tại chỗ sau 8 giờ sáng sẽ bị kéo đi với chi phí do chủ xe chi trả.","units":[{"en":"All Cranbury residents should move their vehicles from their designated parking spots before eight A.M. on Monday.","vi":"Tất cả cư dân Cranbury cần di chuyển phương tiện ra khỏi vị trí đỗ xe được chỉ định trước 8 giờ sáng thứ Hai."},{"en":"Any vehicle still in its spot after eight A.M. will be towed at the owner's expense.","vi":"Bất kỳ phương tiện nào vẫn còn đỗ tại chỗ sau 8 giờ sáng sẽ bị kéo đi với chi phí do chủ xe chi trả."}]},{"speaker":"M-Au","en":"A map of alternate parking sites was mailed to residents last week and is also posted in the building lobby.","vi":"Bản đồ các điểm đỗ xe thay thế đã được gửi qua đường bưu điện đến cư dân vào tuần trước và cũng được niêm yết tại sảnh tòa nhà.","units":[{"en":"A map of alternate parking sites was mailed to residents last week and is also posted in the building lobby.","vi":"Bản đồ các điểm đỗ xe thay thế đã được gửi qua đường bưu điện đến cư dân vào tuần trước và cũng được niêm yết tại sảnh tòa nhà."}]}],"vocab":[{"word":"alternate","pos":"adj","ipa":"/ˈɔːltərnət/","meaning":"thay thế, luân phiên"},{"word":"post","pos":"v","ipa":"/poʊst/","meaning":"niêm yết, dán thông báo"},{"word":"lobby","pos":"n","ipa":"/ˈlɑːbi/","meaning":"sảnh chờ (tòa nhà)"},{"word":"vehicle","pos":"n","ipa":"/ˈviːəkəl/","meaning":"phương tiện giao thông"}],"isScanBacked":false,"grammarType":"Part 4 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 4 (PART 4 THUỘC LÒNG — Chi tiết & Mốc thời gian): Nghe đúng cụm mốc thời gian \"last week\" và động từ bị động \"was mailed\" để bắt chủ ngữ \"A map of alternate parking sites\".","optionAnalysis":{"A":"Thông tin không có trong bài: Không có nội dung nào liên quan đến bầu cử hay phiếu bầu trong thông báo của khu căn hộ.","B":"Bẫy lặp từ \"maintenance\": Bài nói đề cập \"maintenance work\" bắt đầu vào ngày 12/4, nhưng tài liệu gửi bưu điện tuần trước là bản đồ chứ không phải kế hoạch bảo trì.","C":"Chính xác: Câu cuối nêu rõ \"A map of alternate parking sites was mailed to residents last week\".","D":"Sai chủ đề hoàn toàn: Tin nhắn của ban quản lý tòa nhà không hề nhắc đến phiếu giảm giá hay khuyến mãi nào."},"evDocIdx":0,"evTargets":[{"badge":"Câu 73 · Đáp án C","opt":"C","isCorrect":true,"quote":"A map of alternate parking sites was mailed to residents last week and is also posted in the building lobby.","viQuote":"Bản đồ các điểm đỗ xe thay thế đã được gửi qua đường bưu điện đến cư dân vào tuần trước và cũng được niêm yết tại sảnh tòa nhà."}],"evQuotes":["A map of alternate parking sites was mailed to residents last week and is also posted in the building lobby."]},{"q":74,"part":4,"group_id":"E25_T01_G74_76","audio":"web_assets/ets2025/audio/E25_T01/track_46.mp3","graphicImg":null,"transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_21.webp"],"stem_en":"What is the topic of the episode?","stem_vi":"Chủ đề của tập phát sóng này là gì?","options":{"A":{"en":"Garden landscaping","vi":"Thiết kế cảnh quan sân vườn"},"B":{"en":"Window installation","vi":"Lắp đặt cửa sổ"},"C":{"en":"Roof maintenance","vi":"Bảo trì mái nhà"},"D":{"en":"Kitchen renovations","vi":"Cải tạo nhà bếp"}},"ans":"C","explanation":"Đáp án đúng: (C) Bảo trì mái nhà — Ngay ở câu giới thiệu tập phát sóng, người dẫn nêu rõ nội dung là cách bảo dưỡng và sửa chữa nhỏ mái nhà (\"maintain and make minor repairs to the roof\" → \"Roof maintenance\").\nDẫn chứng: \"On today's episode, we'll go over how you can maintain and make minor repairs to the roof of your home.\" (Trong tập phát sóng hôm nay, chúng tôi sẽ hướng dẫn cách bảo dưỡng và thực hiện các sửa chữa nhỏ cho mái nhà của bạn.)\nPhân tích bẫy:\n- (A) Bẫy cùng nhóm chủ đề nhà cửa: thiết kế sân vườn không được nhắc đến trong tập phát sóng này.\n- (B) Bẫy cùng nhóm hạng mục sửa nhà: người nói hướng dẫn xử lý vết nứt và tấm lợp mái, không phải lắp đặt cửa sổ.\n- (D) Bẫy liên tưởng từ tên chương trình \"Your House Works\": cải tạo nhà bếp không phải nội dung của tập hôm nay.","lines":[{"speaker":"W-Am (Phát sóng)","en":"Welcome to Your House Works. On today's episode, we'll go over how you can maintain and make minor repairs to the roof of your home.","vi":"Chào mừng quý vị đến với chương trình Your House Works. Trong tập phát sóng hôm nay, chúng tôi sẽ hướng dẫn cách bảo dưỡng và thực hiện các sửa chữa nhỏ cho mái nhà của bạn.","units":[{"en":"Welcome to Your House Works.","vi":"Chào mừng quý vị đến với chương trình Your House Works."},{"en":"On today's episode, we'll go over how you can maintain and make minor repairs to the roof of your home.","vi":"Trong tập phát sóng hôm nay, chúng tôi sẽ hướng dẫn cách bảo dưỡng và thực hiện các sửa chữa nhỏ cho mái nhà của bạn."}]},{"speaker":"W-Am","en":"The first thing to do is to invest in a few special tools, like a trowel and crowbar. It's important to choose some that are high quality because you'll use them for many years.","vi":"Điều đầu tiên cần làm là đầu tư một vài dụng cụ chuyên dụng, chẳng hạn như bay trát và xà beng. Điều quan trọng là phải chọn loại có chất lượng cao vì bạn sẽ sử dụng chúng trong nhiều năm.","units":[{"en":"The first thing to do is to invest in a few special tools, like a trowel and crowbar.","vi":"Điều đầu tiên cần làm là đầu tư một vài dụng cụ chuyên dụng, chẳng hạn như bay trát và xà beng."},{"en":"It's important to choose some that are high quality because you'll use them for many years.","vi":"Điều quan trọng là phải chọn loại có chất lượng cao vì bạn sẽ sử dụng chúng trong nhiều năm."}]},{"speaker":"W-Am","en":"With your trowel and some roof cement, you can seal any cracks or chips. The crowbar will help you remove loose shingles that you can then replace.","vi":"Với chiếc bay và một ít xi măng trét mái, bạn có thể bịt kín mọi vết nứt hoặc sứt mẻ. Chiếc xà beng sẽ giúp bạn tháo bỏ những tấm lợp mái bị lỏng để sau đó thay mới.","units":[{"en":"With your trowel and some roof cement, you can seal any cracks or chips.","vi":"Với chiếc bay và một ít xi măng trét mái, bạn có thể bịt kín mọi vết nứt hoặc sứt mẻ."},{"en":"The crowbar will help you remove loose shingles that you can then replace.","vi":"Chiếc xà beng sẽ giúp bạn tháo bỏ những tấm lợp mái bị lỏng để sau đó thay mới."}]},{"speaker":"W-Am","en":"Now, I highly recommend you take photos of your roof every year so that you can track its overall condition.","vi":"Ngoài ra, tôi đặc biệt khuyên bạn nên chụp ảnh mái nhà hằng năm để có thể theo dõi tình trạng tổng thể của mái.","units":[{"en":"Now, I highly recommend you take photos of your roof every year so that you can track its overall condition.","vi":"Ngoài ra, tôi đặc biệt khuyên bạn nên chụp ảnh mái nhà hằng năm để có thể theo dõi tình trạng tổng thể của mái."}]}],"vocab":[{"word":"episode","pos":"n","ipa":"/ˈepɪsoʊd/","meaning":"tập phát sóng"},{"word":"go over","pos":"phr. v","ipa":"/ɡoʊ ˈoʊvər/","meaning":"xem xét, hướng dẫn qua"},{"word":"minor repair","pos":"phr","ipa":"/ˈmaɪnər rɪˈper/","meaning":"sửa chữa nhỏ"},{"word":"renovation","pos":"n","ipa":"/ˌrenəˈveɪʃən/","meaning":"việc cải tạo, nâng cấp"}],"isScanBacked":false,"grammarType":"Part 4 — Ý chính & Mục đích (Gist & Purpose)","formula":"CÔNG THỨC PART 4 (PART 4 THUỘC LÒNG — Chủ đề bài phát sóng): Tập trung nghe câu giới thiệu ngay sau lời chào (\"On today's episode, we'll go over...\") để bắt paraphrase \"maintain ... the roof\" → \"Roof maintenance\".","optionAnalysis":{"A":"Sai hạng mục nhà ở: Tập phát sóng hướng dẫn sửa chữa mái nhà, không nhắc đến thiết kế cảnh quan sân vườn.","B":"Sai hạng mục công việc: Người nói hướng dẫn trét vết nứt mái và thay tấm lợp, không hề đề cập đến việc lắp đặt cửa sổ.","C":"Chính xác: Cụm \"how you can maintain and make minor repairs to the roof\" được paraphrase trực tiếp thành \"Roof maintenance\".","D":"Bẫy suy diễn theo chủ đề sửa nhà: Chương trình nói về nhà ở nói chung nhưng tập hôm nay chỉ tập trung vào mái nhà, không phải cải tạo bếp."},"evDocIdx":0,"evTargets":[{"badge":"Câu 74 · Đáp án C","opt":"C","isCorrect":true,"quote":"On today's episode, we'll go over how you can maintain and make minor repairs to the roof of your home.","viQuote":"Trong tập phát sóng hôm nay, chúng tôi sẽ hướng dẫn cách bảo dưỡng và thực hiện các sửa chữa nhỏ cho mái nhà của bạn."}],"evQuotes":["On today's episode, we'll go over how you can maintain and make minor repairs to the roof of your home."]},{"q":75,"part":4,"group_id":"E25_T01_G74_76","audio":"web_assets/ets2025/audio/E25_T01/track_46.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the speaker emphasize about some tools?","stem_vi":"Người nói nhấn mạnh điều gì về một số dụng cụ?","options":{"A":{"en":"They should be cleaned regularly.","vi":"Chúng nên được vệ sinh thường xuyên."},"B":{"en":"They should be of high quality.","vi":"Chúng nên có chất lượng cao."},"C":{"en":"They were recently invented.","vi":"Chúng mới được phát minh gần đây."},"D":{"en":"They can be easily stored.","vi":"Chúng có thể được cất giữ dễ dàng."}},"ans":"B","explanation":"Đáp án đúng: (B) Chúng nên có chất lượng cao — Người nói nhấn mạnh điều quan trọng là chọn mua những dụng cụ chuyên dụng có chất lượng cao vì người nghe sẽ dùng chúng trong nhiều năm.\nDẫn chứng: \"It's important to choose some that are high quality because you'll use them for many years.\" (Điều quan trọng là phải chọn loại có chất lượng cao vì bạn sẽ sử dụng chúng trong nhiều năm.)\nPhân tích bẫy:\n- (A) Việc vệ sinh dụng cụ thường xuyên không được đề cập; người nói chỉ hướng dẫn dùng bay và xà beng để trét xi măng và cạy tấm lợp.\n- (C) Không có chi tiết nào nói bay trát (trowel) hay xà beng (crowbar) là dụng cụ mới được phát minh gần đây.\n- (D) Khả năng cất giữ dễ dàng không được nhắc tới; lý do chọn loại tốt là để sử dụng bền lâu nhiều năm (\"for many years\").","lines":[{"speaker":"W-Am (Phát sóng)","en":"Welcome to Your House Works. On today's episode, we'll go over how you can maintain and make minor repairs to the roof of your home.","vi":"Chào mừng quý vị đến với chương trình Your House Works. Trong tập phát sóng hôm nay, chúng tôi sẽ hướng dẫn cách bảo dưỡng và thực hiện các sửa chữa nhỏ cho mái nhà của bạn.","units":[{"en":"Welcome to Your House Works.","vi":"Chào mừng quý vị đến với chương trình Your House Works."},{"en":"On today's episode, we'll go over how you can maintain and make minor repairs to the roof of your home.","vi":"Trong tập phát sóng hôm nay, chúng tôi sẽ hướng dẫn cách bảo dưỡng và thực hiện các sửa chữa nhỏ cho mái nhà của bạn."}]},{"speaker":"W-Am","en":"The first thing to do is to invest in a few special tools, like a trowel and crowbar. It's important to choose some that are high quality because you'll use them for many years.","vi":"Điều đầu tiên cần làm là đầu tư một vài dụng cụ chuyên dụng, chẳng hạn như bay trát và xà beng. Điều quan trọng là phải chọn loại có chất lượng cao vì bạn sẽ sử dụng chúng trong nhiều năm.","units":[{"en":"The first thing to do is to invest in a few special tools, like a trowel and crowbar.","vi":"Điều đầu tiên cần làm là đầu tư một vài dụng cụ chuyên dụng, chẳng hạn như bay trát và xà beng."},{"en":"It's important to choose some that are high quality because you'll use them for many years.","vi":"Điều quan trọng là phải chọn loại có chất lượng cao vì bạn sẽ sử dụng chúng trong nhiều năm."}]},{"speaker":"W-Am","en":"With your trowel and some roof cement, you can seal any cracks or chips. The crowbar will help you remove loose shingles that you can then replace.","vi":"Với chiếc bay và một ít xi măng trét mái, bạn có thể bịt kín mọi vết nứt hoặc sứt mẻ. Chiếc xà beng sẽ giúp bạn tháo bỏ những tấm lợp mái bị lỏng để sau đó thay mới.","units":[{"en":"With your trowel and some roof cement, you can seal any cracks or chips.","vi":"Với chiếc bay và một ít xi măng trét mái, bạn có thể bịt kín mọi vết nứt hoặc sứt mẻ."},{"en":"The crowbar will help you remove loose shingles that you can then replace.","vi":"Chiếc xà beng sẽ giúp bạn tháo bỏ những tấm lợp mái bị lỏng để sau đó thay mới."}]},{"speaker":"W-Am","en":"Now, I highly recommend you take photos of your roof every year so that you can track its overall condition.","vi":"Ngoài ra, tôi đặc biệt khuyên bạn nên chụp ảnh mái nhà hằng năm để có thể theo dõi tình trạng tổng thể của mái.","units":[{"en":"Now, I highly recommend you take photos of your roof every year so that you can track its overall condition.","vi":"Ngoài ra, tôi đặc biệt khuyên bạn nên chụp ảnh mái nhà hằng năm để có thể theo dõi tình trạng tổng thể của mái."}]}],"vocab":[{"word":"invest in","pos":"phr. v","ipa":"/ɪnˈvest ɪn/","meaning":"đầu tư vào"},{"word":"high quality","pos":"adj","ipa":"/haɪ ˈkwɑːləti/","meaning":"chất lượng cao"},{"word":"seal","pos":"v","ipa":"/siːl/","meaning":"bịt kín, trám kín"},{"word":"loose","pos":"adj","ipa":"/luːs/","meaning":"bị lỏng, lung lay"}],"isScanBacked":false,"grammarType":"Part 4 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 4 (PART 4 THUỘC LÒNG — Chi tiết nhấn mạnh): Bắt tín hiệu nhấn mạnh \"It's important to...\" kết hợp với lý do \"because...\" để chọn đúng đặc điểm \"high quality\" của dụng cụ.","optionAnalysis":{"A":"Chi tiết không có trong bài: Người nói không dặn dò cách vệ sinh hay bảo quản định kỳ các dụng cụ sau khi sửa mái.","B":"Chính xác: Khớp nguyên văn cụm \"choose some that are high quality\" ngay sau tín hiệu nhấn mạnh \"It's important to\".","C":"Thông tin sai lệch: Bay trát và xà beng được gọi là \"special tools\" (dụng cụ chuyên dụng), không phải mới phát minh gần đây.","D":"Suy diễn ngoài bài: Tiêu chí được nhấn mạnh là độ bền để dùng nhiều năm (\"use them for many years\"), không phải dễ cất giữ."},"evDocIdx":0,"evTargets":[{"badge":"Câu 75 · Đáp án B","opt":"B","isCorrect":true,"quote":"It's important to choose some that are high quality because you'll use them for many years.","viQuote":"Điều quan trọng là phải chọn loại có chất lượng cao vì bạn sẽ sử dụng chúng trong nhiều năm."}],"evQuotes":["It's important to choose some that are high quality because you'll use them for many years."]},{"q":76,"part":4,"group_id":"E25_T01_G74_76","audio":"web_assets/ets2025/audio/E25_T01/track_46.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the speaker recommend doing every year?","stem_vi":"Người nói khuyên nên làm gì mỗi năm?","options":{"A":{"en":"Treating some wood","vi":"Xử lý bảo quản gỗ"},"B":{"en":"Consulting an electrician","vi":"Tham khảo ý kiến thợ điện"},"C":{"en":"Taking some photos","vi":"Chụp một số bức ảnh"},"D":{"en":"Draining some water","vi":"Xả bớt nước"}},"ans":"C","explanation":"Đáp án đúng: (C) Chụp một số bức ảnh — Ở cuối chương trình, người nói khuyên nên chụp ảnh mái nhà hằng năm để theo dõi tình trạng tổng thể của mái (\"take photos ... every year\" → \"Taking some photos\").\nDẫn chứng: \"Now, I highly recommend you take photos of your roof every year so that you can track its overall condition.\" (Ngoài ra, tôi đặc biệt khuyên bạn nên chụp ảnh mái nhà hằng năm để có thể theo dõi tình trạng tổng thể của mái.)\nPhân tích bẫy:\n- (A) Không có hướng dẫn nào về việc xử lý bảo quản gỗ trong bài nói về bảo trì mái nhà này.\n- (B) Thợ điện không được nhắc tới; toàn bộ hướng dẫn đều xoay quanh tự sửa vết nứt và thay tấm lợp mái.\n- (D) Việc xả bớt nước không được đề cập; bài nói chỉ hướng dẫn bịt kín vết nứt bằng xi măng trét mái.","lines":[{"speaker":"W-Am (Phát sóng)","en":"Welcome to Your House Works. On today's episode, we'll go over how you can maintain and make minor repairs to the roof of your home.","vi":"Chào mừng quý vị đến với chương trình Your House Works. Trong tập phát sóng hôm nay, chúng tôi sẽ hướng dẫn cách bảo dưỡng và thực hiện các sửa chữa nhỏ cho mái nhà của bạn.","units":[{"en":"Welcome to Your House Works.","vi":"Chào mừng quý vị đến với chương trình Your House Works."},{"en":"On today's episode, we'll go over how you can maintain and make minor repairs to the roof of your home.","vi":"Trong tập phát sóng hôm nay, chúng tôi sẽ hướng dẫn cách bảo dưỡng và thực hiện các sửa chữa nhỏ cho mái nhà của bạn."}]},{"speaker":"W-Am","en":"The first thing to do is to invest in a few special tools, like a trowel and crowbar. It's important to choose some that are high quality because you'll use them for many years.","vi":"Điều đầu tiên cần làm là đầu tư một vài dụng cụ chuyên dụng, chẳng hạn như bay trát và xà beng. Điều quan trọng là phải chọn loại có chất lượng cao vì bạn sẽ sử dụng chúng trong nhiều năm.","units":[{"en":"The first thing to do is to invest in a few special tools, like a trowel and crowbar.","vi":"Điều đầu tiên cần làm là đầu tư một vài dụng cụ chuyên dụng, chẳng hạn như bay trát và xà beng."},{"en":"It's important to choose some that are high quality because you'll use them for many years.","vi":"Điều quan trọng là phải chọn loại có chất lượng cao vì bạn sẽ sử dụng chúng trong nhiều năm."}]},{"speaker":"W-Am","en":"With your trowel and some roof cement, you can seal any cracks or chips. The crowbar will help you remove loose shingles that you can then replace.","vi":"Với chiếc bay và một ít xi măng trét mái, bạn có thể bịt kín mọi vết nứt hoặc sứt mẻ. Chiếc xà beng sẽ giúp bạn tháo bỏ những tấm lợp mái bị lỏng để sau đó thay mới.","units":[{"en":"With your trowel and some roof cement, you can seal any cracks or chips.","vi":"Với chiếc bay và một ít xi măng trét mái, bạn có thể bịt kín mọi vết nứt hoặc sứt mẻ."},{"en":"The crowbar will help you remove loose shingles that you can then replace.","vi":"Chiếc xà beng sẽ giúp bạn tháo bỏ những tấm lợp mái bị lỏng để sau đó thay mới."}]},{"speaker":"W-Am","en":"Now, I highly recommend you take photos of your roof every year so that you can track its overall condition.","vi":"Ngoài ra, tôi đặc biệt khuyên bạn nên chụp ảnh mái nhà hằng năm để có thể theo dõi tình trạng tổng thể của mái.","units":[{"en":"Now, I highly recommend you take photos of your roof every year so that you can track its overall condition.","vi":"Ngoài ra, tôi đặc biệt khuyên bạn nên chụp ảnh mái nhà hằng năm để có thể theo dõi tình trạng tổng thể của mái."}]}],"vocab":[{"word":"recommend","pos":"v","ipa":"/ˌrekəˈmend/","meaning":"khuyên, khuyến nghị"},{"word":"track","pos":"v","ipa":"/træk/","meaning":"theo dõi, giám sát"},{"word":"overall condition","pos":"phr","ipa":"/ˌoʊvərˈɔːl kənˈdɪʃən/","meaning":"tình trạng tổng thể"},{"word":"shingle","pos":"n","ipa":"/ˈʃɪŋɡəl/","meaning":"tấm lợp mái"}],"isScanBacked":false,"grammarType":"Part 4 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 4 (PART 4 THUỘC LÒNG — Lời khuyên & Tần suất): Nghe động từ gợi ý \"recommend\" và cụm tần suất \"every year\" ở cuối bài nói để xác định chính xác hành động \"take photos\".","optionAnalysis":{"A":"Không được nhắc đến: Bài phát sóng tập trung vào xi măng trét mái và tấm lợp (\"shingles\"), không đề cập đến xử lý gỗ.","B":"Sai đối tượng/công việc: Nội dung không liên quan đến hệ thống điện hay việc hỏi ý kiến thợ điện.","C":"Chính xác: Khớp trực tiếp cụm \"highly recommend you take photos of your roof every year\" ở câu cuối.","D":"Suy diễn ngoài ngữ cảnh: Dù mái nhà liên quan đến thời tiết, người nói không hề khuyên xả nước hằng năm."},"evDocIdx":0,"evTargets":[{"badge":"Câu 76 · Đáp án C","opt":"C","isCorrect":true,"quote":"Now, I highly recommend you take photos of your roof every year so that you can track its overall condition.","viQuote":"Ngoài ra, tôi đặc biệt khuyên bạn nên chụp ảnh mái nhà hằng năm để có thể theo dõi tình trạng tổng thể của mái."}],"evQuotes":["Now, I highly recommend you take photos of your roof every year so that you can track its overall condition."]},{"q":77,"part":4,"group_id":"E25_T01_G77_79","audio":"web_assets/ets2025/audio/E25_T01/track_47.mp3","graphicImg":null,"transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_22.webp"],"stem_en":"Who most likely is the speaker?","stem_vi":"Người nói có khả năng là ai nhất?","options":{"A":{"en":"A radio show host","vi":"Người dẫn chương trình phát thanh"},"B":{"en":"A tour guide","vi":"Hướng dẫn viên du lịch"},"C":{"en":"A sales associate","vi":"Nhân viên bán hàng"},"D":{"en":"A professor","vi":"Giáo sư"}},"ans":"B","explanation":"Đáp án đúng: (B) Hướng dẫn viên du lịch — Người nói cảm ơn khách đã đồng hành cùng mình trong chuyến tham quan nhà kính thực vật Wallingford Conservatory (\"joining me on today's tour\" → \"A tour guide\").\nDẫn chứng: \"Thanks again for joining me on today's tour of the beautiful Wallingford Conservatory.\" (Một lần nữa xin cảm ơn quý vị đã đồng hành cùng tôi trong chuyến tham quan nhà kính thực vật Wallingford Conservatory xinh đẹp hôm nay.)\nPhân tích bẫy:\n- (A) Đây là lời nói trực tiếp kết thúc chuyến tham quan tại nhà kính, không phải chương trình phát thanh trên đài.\n- (C) Bẫy liên tưởng \"online gift shop\": người nói chỉ giới thiệu khách có thể tự mua phim tài liệu qua cửa hàng trực tuyến, không phải nhân viên bán hàng đứng quầy.\n- (D) Bẫy liên tưởng từ \"botanist\" và \"lecture\": người có buổi thuyết trình là nhà thực vật học Samantha Hughes, không phải người dẫn tour đang nói.","lines":[{"speaker":"W-Br (Bài nói)","en":"Thanks again for joining me on today's tour of the beautiful Wallingford Conservatory. I hope you enjoyed seeing and learning about the many species of plants and flowers we care for here.","vi":"Một lần nữa xin cảm ơn quý vị đã đồng hành cùng tôi trong chuyến tham quan nhà kính thực vật Wallingford Conservatory xinh đẹp hôm nay. Tôi hy vọng quý vị đã có khoảng thời gian thú vị khi chiêm ngưỡng và tìm hiểu về rất nhiều loài cây và hoa mà chúng tôi chăm sóc tại đây.","units":[{"en":"Thanks again for joining me on today's tour of the beautiful Wallingford Conservatory.","vi":"Một lần nữa xin cảm ơn quý vị đã đồng hành cùng tôi trong chuyến tham quan nhà kính thực vật Wallingford Conservatory xinh đẹp hôm nay."},{"en":"I hope you enjoyed seeing and learning about the many species of plants and flowers we care for here.","vi":"Tôi hy vọng quý vị đã có khoảng thời gian thú vị khi chiêm ngưỡng và tìm hiểu về rất nhiều loài cây và hoa mà chúng tôi chăm sóc tại đây."}]},{"speaker":"W-Br","en":"As I mentioned at the beginning of the tour, world-renowned botanist Samantha Hughes will be giving a lecture on the care of flowering orchid plants at two o'clock in the community room. I recommend attending.","vi":"Như tôi đã đề cập ở đầu chuyến tham quan, nhà thực vật học nổi tiếng thế giới Samantha Hughes sẽ có buổi thuyết trình về cách chăm sóc cây lan ra hoa vào lúc 2 giờ tại phòng sinh hoạt cộng đồng. Tôi rất khuyến khích quý vị tham dự.","units":[{"en":"As I mentioned at the beginning of the tour, world-renowned botanist Samantha Hughes will be giving a lecture on the care of flowering orchid plants at two o'clock in the community room.","vi":"Như tôi đã đề cập ở đầu chuyến tham quan, nhà thực vật học nổi tiếng thế giới Samantha Hughes sẽ có buổi thuyết trình về cách chăm sóc cây lan ra hoa vào lúc 2 giờ tại phòng sinh hoạt cộng đồng."},{"en":"I recommend attending.","vi":"Tôi rất khuyến khích quý vị tham dự."}]},{"speaker":"W-Br","en":"Samantha's work has also been featured in a documentary film called Orchid Caretakers, which you can purchase through the conservatory's online gift shop. I watched it recently and learned many new things about the orchid species we have right here at the conservatory.","vi":"Công trình của Samantha cũng đã được giới thiệu trong bộ phim tài liệu mang tên Orchid Caretakers, và quý vị có thể đặt mua bộ phim này qua cửa hàng quà tặng trực tuyến của nhà kính. Gần đây tôi đã xem bộ phim này và học thêm được rất nhiều điều mới mẻ về các loài lan hiện có ngay tại nhà kính của chúng tôi.","units":[{"en":"Samantha's work has also been featured in a documentary film called Orchid Caretakers, which you can purchase through the conservatory's online gift shop.","vi":"Công trình của Samantha cũng đã được giới thiệu trong bộ phim tài liệu mang tên Orchid Caretakers, và quý vị có thể đặt mua bộ phim này qua cửa hàng quà tặng trực tuyến của nhà kính."},{"en":"I watched it recently and learned many new things about the orchid species we have right here at the conservatory.","vi":"Gần đây tôi đã xem bộ phim này và học thêm được rất nhiều điều mới mẻ về các loài lan hiện có ngay tại nhà kính của chúng tôi."}]}],"vocab":[{"word":"conservatory","pos":"n","ipa":"/kənˈsɜːrvətɔːri/","meaning":"nhà kính thực vật"},{"word":"species","pos":"n","ipa":"/ˈspiːʃiːz/","meaning":"loài (thực vật, động vật)"},{"word":"tour guide","pos":"n","ipa":"/tʊr ɡaɪd/","meaning":"hướng dẫn viên du lịch"},{"word":"care for","pos":"phr. v","ipa":"/ker fɔːr/","meaning":"chăm sóc"}],"isScanBacked":false,"grammarType":"Part 4 — Ngữ cảnh, Địa điểm & Danh tính người nói (Setting & Role)","formula":"CÔNG THỨC PART 4 (PART 4 THUỘC LÒNG — Danh tính người nói): Bắt cụm cảm ơn ở đầu bài (\"Thanks again for joining me on today's tour...\") để nhận diện vai trò người dẫn đoàn tham quan (\"A tour guide\").","optionAnalysis":{"A":"Sai bối cảnh: Người nói đang dẫn khách tham quan trực tiếp tại nhà kính thực vật, không phải đang dẫn chương trình phát thanh.","B":"Chính xác: Cụm \"joining me on today's tour\" và \"at the beginning of the tour\" xác nhận vai trò hướng dẫn viên.","C":"Bẫy chi tiết \"gift shop\": Người nói chỉ gợi ý du khách mua phim trên cửa hàng trực tuyến chứ không làm công việc bán hàng.","D":"Bẫy nhầm vai (Samantha Hughes): Người giảng bài (\"giving a lecture\") là nhà thực vật học Samantha Hughes, không phải người nói."},"evDocIdx":0,"evTargets":[{"badge":"Câu 77 · Đáp án B","opt":"B","isCorrect":true,"quote":"Thanks again for joining me on today's tour of the beautiful Wallingford Conservatory.","viQuote":"Một lần nữa xin cảm ơn quý vị đã đồng hành cùng tôi trong chuyến tham quan nhà kính thực vật Wallingford Conservatory xinh đẹp hôm nay."}],"evQuotes":["Thanks again for joining me on today's tour of the beautiful Wallingford Conservatory."]},{"q":78,"part":4,"group_id":"E25_T01_G77_79","audio":"web_assets/ets2025/audio/E25_T01/track_47.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What will happen at two o'clock?","stem_vi":"Điều gì sẽ diễn ra vào lúc 2 giờ?","options":{"A":{"en":"A lecture will begin.","vi":"Một buổi thuyết trình sẽ bắt đầu."},"B":{"en":"A demonstration will be given.","vi":"Một buổi trình diễn minh họa sẽ được tổ chức."},"C":{"en":"An interview will be conducted.","vi":"Một cuộc phỏng vấn sẽ được tiến hành."},"D":{"en":"A park will close.","vi":"Một công viên sẽ đóng cửa."}},"ans":"A","explanation":"Đáp án đúng: (A) Một buổi thuyết trình sẽ bắt đầu — Người nói nhắc lại lịch trình vào lúc 2 giờ tại phòng sinh hoạt cộng đồng, nhà thực vật học Samantha Hughes sẽ có một buổi thuyết trình về cách chăm sóc hoa lan.\nDẫn chứng: \"...world-renowned botanist Samantha Hughes will be giving a lecture on the care of flowering orchid plants at two o'clock in the community room.\" (...nhà thực vật học nổi tiếng thế giới Samantha Hughes sẽ có buổi thuyết trình về cách chăm sóc cây lan ra hoa vào lúc 2 giờ tại phòng sinh hoạt cộng đồng.)\nPhân tích bẫy:\n- (B) Bẫy ngữ nghĩa gần: bài nói dùng chính xác từ \"giving a lecture\" (buổi thuyết trình/bài giảng), không nói có buổi trình diễn thao tác (\"demonstration\").\n- (C) Không có cuộc phỏng vấn nào được lên lịch lúc 2 giờ; sự kiện là bài thuyết trình của một chuyên gia.\n- (D) Giờ đóng cửa của nhà kính hoặc công viên hoàn toàn không được đề cập trong bài nói.","lines":[{"speaker":"W-Br (Bài nói)","en":"Thanks again for joining me on today's tour of the beautiful Wallingford Conservatory. I hope you enjoyed seeing and learning about the many species of plants and flowers we care for here.","vi":"Một lần nữa xin cảm ơn quý vị đã đồng hành cùng tôi trong chuyến tham quan nhà kính thực vật Wallingford Conservatory xinh đẹp hôm nay. Tôi hy vọng quý vị đã có khoảng thời gian thú vị khi chiêm ngưỡng và tìm hiểu về rất nhiều loài cây và hoa mà chúng tôi chăm sóc tại đây.","units":[{"en":"Thanks again for joining me on today's tour of the beautiful Wallingford Conservatory.","vi":"Một lần nữa xin cảm ơn quý vị đã đồng hành cùng tôi trong chuyến tham quan nhà kính thực vật Wallingford Conservatory xinh đẹp hôm nay."},{"en":"I hope you enjoyed seeing and learning about the many species of plants and flowers we care for here.","vi":"Tôi hy vọng quý vị đã có khoảng thời gian thú vị khi chiêm ngưỡng và tìm hiểu về rất nhiều loài cây và hoa mà chúng tôi chăm sóc tại đây."}]},{"speaker":"W-Br","en":"As I mentioned at the beginning of the tour, world-renowned botanist Samantha Hughes will be giving a lecture on the care of flowering orchid plants at two o'clock in the community room. I recommend attending.","vi":"Như tôi đã đề cập ở đầu chuyến tham quan, nhà thực vật học nổi tiếng thế giới Samantha Hughes sẽ có buổi thuyết trình về cách chăm sóc cây lan ra hoa vào lúc 2 giờ tại phòng sinh hoạt cộng đồng. Tôi rất khuyến khích quý vị tham dự.","units":[{"en":"As I mentioned at the beginning of the tour, world-renowned botanist Samantha Hughes will be giving a lecture on the care of flowering orchid plants at two o'clock in the community room.","vi":"Như tôi đã đề cập ở đầu chuyến tham quan, nhà thực vật học nổi tiếng thế giới Samantha Hughes sẽ có buổi thuyết trình về cách chăm sóc cây lan ra hoa vào lúc 2 giờ tại phòng sinh hoạt cộng đồng."},{"en":"I recommend attending.","vi":"Tôi rất khuyến khích quý vị tham dự."}]},{"speaker":"W-Br","en":"Samantha's work has also been featured in a documentary film called Orchid Caretakers, which you can purchase through the conservatory's online gift shop. I watched it recently and learned many new things about the orchid species we have right here at the conservatory.","vi":"Công trình của Samantha cũng đã được giới thiệu trong bộ phim tài liệu mang tên Orchid Caretakers, và quý vị có thể đặt mua bộ phim này qua cửa hàng quà tặng trực tuyến của nhà kính. Gần đây tôi đã xem bộ phim này và học thêm được rất nhiều điều mới mẻ về các loài lan hiện có ngay tại nhà kính của chúng tôi.","units":[{"en":"Samantha's work has also been featured in a documentary film called Orchid Caretakers, which you can purchase through the conservatory's online gift shop.","vi":"Công trình của Samantha cũng đã được giới thiệu trong bộ phim tài liệu mang tên Orchid Caretakers, và quý vị có thể đặt mua bộ phim này qua cửa hàng quà tặng trực tuyến của nhà kính."},{"en":"I watched it recently and learned many new things about the orchid species we have right here at the conservatory.","vi":"Gần đây tôi đã xem bộ phim này và học thêm được rất nhiều điều mới mẻ về các loài lan hiện có ngay tại nhà kính của chúng tôi."}]}],"vocab":[{"word":"world-renowned","pos":"adj","ipa":"/ˌwɜːrld rɪˈnaʊnd/","meaning":"nổi tiếng thế giới"},{"word":"botanist","pos":"n","ipa":"/ˈbɑːtənɪst/","meaning":"nhà thực vật học"},{"word":"give a lecture","pos":"phr","ipa":"/ɡɪv ə ˈlektʃər/","meaning":"thuyết trình, giảng bài"},{"word":"community room","pos":"n","ipa":"/kəˈmjuːnəti ruːm/","meaning":"phòng sinh hoạt cộng đồng"}],"isScanBacked":false,"grammarType":"Part 4 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 4 (PART 4 THUỘC LÒNG — Chi tiết mốc giờ): Định vị chính xác mốc giờ \"at two o'clock\" trong bài nói để bắt sự kiện đi kèm \"giving a lecture\" → \"A lecture will begin\".","optionAnalysis":{"A":"Chính xác: Khớp trực tiếp cụm \"will be giving a lecture ... at two o'clock in the community room\".","B":"Bẫy thay từ gần nghĩa: Bài nói dùng rõ cụm \"giving a lecture\" (thuyết trình), không đề cập buổi trình diễn thực hành (\"demonstration\").","C":"Thông tin sai sự kiện: Không có cuộc phỏng vấn nào diễn ra với Samantha Hughes vào lúc 2 giờ.","D":"Chi tiết không xuất hiện: Bài nói không hề nhắc đến giờ đóng cửa của công viên hay nhà kính."},"evDocIdx":0,"evTargets":[{"badge":"Câu 78 · Đáp án A","opt":"A","isCorrect":true,"quote":"As I mentioned at the beginning of the tour, world-renowned botanist Samantha Hughes will be giving a lecture on the care of flowering orchid plants at two o'clock in the community room.","viQuote":"Như tôi đã đề cập ở đầu chuyến tham quan, nhà thực vật học nổi tiếng thế giới Samantha Hughes sẽ có buổi thuyết trình về cách chăm sóc cây lan ra hoa vào lúc 2 giờ tại phòng sinh hoạt cộng đồng."}],"evQuotes":["As I mentioned at the beginning of the tour, world-renowned botanist Samantha Hughes will be giving a lecture on the care of flowering orchid plants at two o'clock in the community room."]},{"q":79,"part":4,"group_id":"E25_T01_G77_79","audio":"web_assets/ets2025/audio/E25_T01/track_47.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What is Orchid Caretakers?","stem_vi":"Orchid Caretakers là gì?","options":{"A":{"en":"A book","vi":"Một cuốn sách"},"B":{"en":"An album","vi":"Một album"},"C":{"en":"A film","vi":"Một bộ phim"},"D":{"en":"A magazine","vi":"Một cuốn tạp chí"}},"ans":"C","explanation":"Đáp án đúng: (C) Một bộ phim — Người nói giới thiệu trực tiếp Orchid Caretakers là tên một bộ phim tài liệu có sự góp mặt công trình của Samantha (\"a documentary film called Orchid Caretakers\" → \"A film\").\nDẫn chứng: \"Samantha's work has also been featured in a documentary film called Orchid Caretakers, which you can purchase through the conservatory's online gift shop.\" (Công trình của Samantha cũng đã được giới thiệu trong bộ phim tài liệu mang tên Orchid Caretakers, và quý vị có thể đặt mua qua cửa hàng quà tặng trực tuyến của nhà kính.)\nPhân tích bẫy:\n- (A) Bẫy liên tưởng \"gift shop\" và \"purchase\": dù cửa hàng quà tặng thường bán sách, ở đây sản phẩm mang tên Orchid Caretakers là phim tài liệu (\"documentary film\").\n- (B) Không phải album ảnh hay âm nhạc; người nói xác nhận mình đã xem (\"I watched it recently\").\n- (D) Không phải tạp chí in ấn; định dạng được nêu rõ là \"documentary film\".","lines":[{"speaker":"W-Br (Bài nói)","en":"Thanks again for joining me on today's tour of the beautiful Wallingford Conservatory. I hope you enjoyed seeing and learning about the many species of plants and flowers we care for here.","vi":"Một lần nữa xin cảm ơn quý vị đã đồng hành cùng tôi trong chuyến tham quan nhà kính thực vật Wallingford Conservatory xinh đẹp hôm nay. Tôi hy vọng quý vị đã có khoảng thời gian thú vị khi chiêm ngưỡng và tìm hiểu về rất nhiều loài cây và hoa mà chúng tôi chăm sóc tại đây.","units":[{"en":"Thanks again for joining me on today's tour of the beautiful Wallingford Conservatory.","vi":"Một lần nữa xin cảm ơn quý vị đã đồng hành cùng tôi trong chuyến tham quan nhà kính thực vật Wallingford Conservatory xinh đẹp hôm nay."},{"en":"I hope you enjoyed seeing and learning about the many species of plants and flowers we care for here.","vi":"Tôi hy vọng quý vị đã có khoảng thời gian thú vị khi chiêm ngưỡng và tìm hiểu về rất nhiều loài cây và hoa mà chúng tôi chăm sóc tại đây."}]},{"speaker":"W-Br","en":"As I mentioned at the beginning of the tour, world-renowned botanist Samantha Hughes will be giving a lecture on the care of flowering orchid plants at two o'clock in the community room. I recommend attending.","vi":"Như tôi đã đề cập ở đầu chuyến tham quan, nhà thực vật học nổi tiếng thế giới Samantha Hughes sẽ có buổi thuyết trình về cách chăm sóc cây lan ra hoa vào lúc 2 giờ tại phòng sinh hoạt cộng đồng. Tôi rất khuyến khích quý vị tham dự.","units":[{"en":"As I mentioned at the beginning of the tour, world-renowned botanist Samantha Hughes will be giving a lecture on the care of flowering orchid plants at two o'clock in the community room.","vi":"Như tôi đã đề cập ở đầu chuyến tham quan, nhà thực vật học nổi tiếng thế giới Samantha Hughes sẽ có buổi thuyết trình về cách chăm sóc cây lan ra hoa vào lúc 2 giờ tại phòng sinh hoạt cộng đồng."},{"en":"I recommend attending.","vi":"Tôi rất khuyến khích quý vị tham dự."}]},{"speaker":"W-Br","en":"Samantha's work has also been featured in a documentary film called Orchid Caretakers, which you can purchase through the conservatory's online gift shop. I watched it recently and learned many new things about the orchid species we have right here at the conservatory.","vi":"Công trình của Samantha cũng đã được giới thiệu trong bộ phim tài liệu mang tên Orchid Caretakers, và quý vị có thể đặt mua bộ phim này qua cửa hàng quà tặng trực tuyến của nhà kính. Gần đây tôi đã xem bộ phim này và học thêm được rất nhiều điều mới mẻ về các loài lan hiện có ngay tại nhà kính của chúng tôi.","units":[{"en":"Samantha's work has also been featured in a documentary film called Orchid Caretakers, which you can purchase through the conservatory's online gift shop.","vi":"Công trình của Samantha cũng đã được giới thiệu trong bộ phim tài liệu mang tên Orchid Caretakers, và quý vị có thể đặt mua bộ phim này qua cửa hàng quà tặng trực tuyến của nhà kính."},{"en":"I watched it recently and learned many new things about the orchid species we have right here at the conservatory.","vi":"Gần đây tôi đã xem bộ phim này và học thêm được rất nhiều điều mới mẻ về các loài lan hiện có ngay tại nhà kính của chúng tôi."}]}],"vocab":[{"word":"feature","pos":"v","ipa":"/ˈfiːtʃər/","meaning":"giới thiệu nổi bật, đưa vào"},{"word":"documentary","pos":"n","ipa":"/ˌdɑːkjəˈmentəri/","meaning":"phim tài liệu"},{"word":"purchase","pos":"v","ipa":"/ˈpɜːrtʃəs/","meaning":"đặt mua, mua sắm"},{"word":"gift shop","pos":"n","ipa":"/ɡɪft ʃɑːp/","meaning":"cửa hàng quà tặng"}],"isScanBacked":false,"grammarType":"Part 4 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 4 (PART 4 THUỘC LÒNG — Định danh tên riêng): Nghe danh từ đứng ngay trước cụm \"called + <Tên riêng>\" (\"a documentary film called Orchid Caretakers\") để chọn đúng loại hình.","optionAnalysis":{"A":"Bẫy liên tưởng cửa hàng quà tặng: Du khách được giới thiệu mua sản phẩm này ở \"online gift shop\", nhưng bản chất nó là phim chứ không phải sách.","B":"Sai loại hình: Cụm \"a documentary film called Orchid Caretakers\" và động từ \"watched it\" loại trừ phương án album.","C":"Chính xác: Khớp trực tiếp cụm định danh \"a documentary film called Orchid Caretakers\".","D":"Thông tin sai loại hình: Bài nói không hề nhắc đến ấn phẩm tạp chí nào về hoa lan."},"evDocIdx":0,"evTargets":[{"badge":"Câu 79 · Đáp án C","opt":"C","isCorrect":true,"quote":"Samantha's work has also been featured in a documentary film called Orchid Caretakers, which you can purchase through the conservatory's online gift shop.","viQuote":"Công trình của Samantha cũng đã được giới thiệu trong bộ phim tài liệu mang tên Orchid Caretakers, và quý vị có thể đặt mua bộ phim này qua cửa hàng quà tặng trực tuyến của nhà kính."}],"evQuotes":["Samantha's work has also been featured in a documentary film called Orchid Caretakers, which you can purchase through the conservatory's online gift shop."]},{"q":80,"part":4,"group_id":"E25_T01_G80_82","audio":"web_assets/ets2025/audio/E25_T01/track_48.mp3","graphicImg":null,"transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_22.webp","web_assets/ets2025/tr/E25_T01_tr_23.webp"],"stem_en":"What event is taking place?","stem_vi":"Sự kiện nào đang diễn ra?","options":{"A":{"en":"A fund-raising concert","vi":"Một buổi hòa nhạc gây quỹ"},"B":{"en":"A sports competition","vi":"Một giải đấu thể thao"},"C":{"en":"A play rehearsal","vi":"Một buổi diễn tập kịch"},"D":{"en":"An awards ceremony","vi":"Một lễ trao giải"}},"ans":"A","explanation":"Đáp án đúng: (A) Một buổi hòa nhạc gây quỹ — Người nói mở đầu ngay trước khi \"benefit concert\" bắt đầu và nhắc đến số tiền bán vé đã gây quỹ được 5.000 đô la (\"benefit concert\" → \"fund-raising concert\").\nDẫn chứng: \"Before the benefit concert begins, I want to thank all of you for supporting the Hillcaster Community Center.\" (Trước khi buổi hòa nhạc gây quỹ bắt đầu, tôi muốn cảm ơn tất cả quý vị đã ủng hộ trung tâm Hillcaster Community Center.)\nPhân tích bẫy:\n- (B) Giải đấu thể thao không liên quan; cuối bài người nói còn chúc khán giả thưởng thức âm nhạc (\"Enjoy the music!\").\n- (C) Bẫy cùng bối cảnh sân khấu: đây là buổi biểu diễn hòa nhạc chính thức đã bán vé, không phải buổi tập duyệt kịch.\n- (D) Không có chi tiết trao giải thưởng hay vinh danh nào được nhắc đến trong bài phát biểu.","lines":[{"speaker":"M-Au (Bài phát biểu)","en":"Before the benefit concert begins, I want to thank all of you for supporting the Hillcaster Community Center. As you know, our facilities have been in need of some repairs for quite a while.","vi":"Trước khi buổi hòa nhạc gây quỹ bắt đầu, tôi muốn cảm ơn tất cả quý vị đã ủng hộ trung tâm Hillcaster Community Center. Như quý vị đã biết, cơ sở vật chất của chúng tôi đã cần được sửa chữa từ khá lâu rồi.","units":[{"en":"Before the benefit concert begins, I want to thank all of you for supporting the Hillcaster Community Center.","vi":"Trước khi buổi hòa nhạc gây quỹ bắt đầu, tôi muốn cảm ơn tất cả quý vị đã ủng hộ trung tâm Hillcaster Community Center."},{"en":"As you know, our facilities have been in need of some repairs for quite a while.","vi":"Như quý vị đã biết, cơ sở vật chất của chúng tôi đã cần được sửa chữa từ khá lâu rồi."}]},{"speaker":"M-Au","en":"So far, we've raised 5,000 dollars in ticket sales, but we haven't quite reached our goal yet.","vi":"Tính đến nay, chúng tôi đã gây quỹ được 5.000 đô la từ tiền bán vé, nhưng vẫn chưa hoàn toàn đạt được mục tiêu đề ra.","units":[{"en":"So far, we've raised 5,000 dollars in ticket sales, but we haven't quite reached our goal yet.","vi":"Tính đến nay, chúng tôi đã gây quỹ được 5.000 đô la từ tiền bán vé, nhưng vẫn chưa hoàn toàn đạt được mục tiêu đề ra."}]},{"speaker":"M-Au","en":"So during the concert, I want to encourage you to buy food and drinks from the concession stand. Eighty percent of the proceeds will go to construction at the Hillcaster Community Center. Enjoy the music!","vi":"Vì vậy, trong suốt buổi hòa nhạc, tôi muốn khuyến khích quý vị mua đồ ăn và thức uống tại quầy giải khát. 80% số tiền thu được sẽ được dành cho công tác xây dựng tại Hillcaster Community Center. Chúc quý vị thưởng thức âm nhạc vui vẻ!","units":[{"en":"So during the concert, I want to encourage you to buy food and drinks from the concession stand.","vi":"Vì vậy, trong suốt buổi hòa nhạc, tôi muốn khuyến khích quý vị mua đồ ăn và thức uống tại quầy giải khát."},{"en":"Eighty percent of the proceeds will go to construction at the Hillcaster Community Center.","vi":"80% số tiền thu được sẽ được dành cho công tác xây dựng tại Hillcaster Community Center."},{"en":"Enjoy the music!","vi":"Chúc quý vị thưởng thức âm nhạc vui vẻ!"}]}],"vocab":[{"word":"benefit concert","pos":"n","ipa":"/ˈbenɪfɪt ˈkɑːnsərt/","meaning":"buổi hòa nhạc từ thiện gây quỹ"},{"word":"fund-raising","pos":"adj","ipa":"/ˈfʌnd reɪzɪŋ/","meaning":"gây quỹ"},{"word":"raise","pos":"v","ipa":"/reɪz/","meaning":"quyên góp, gây quỹ"},{"word":"ticket sales","pos":"n","ipa":"/ˈtɪkɪt seɪlz/","meaning":"doanh thu bán vé"}],"isScanBacked":false,"grammarType":"Part 4 — Ý chính & Mục đích (Gist & Purpose)","formula":"CÔNG THỨC PART 4 (PART 4 THUỘC LÒNG — Nhận diện sự kiện): Bắt cụm từ khóa ở mệnh đề đầu (\"Before the benefit concert begins...\") và quy đổi paraphrase \"benefit concert\" = \"fund-raising concert\".","optionAnalysis":{"A":"Chính xác: Paraphrase chuẩn TOEIC từ \"benefit concert\" (kết hợp chi tiết \"raised 5,000 dollars\") thành \"fund-raising concert\".","B":"Sai loại hình sự kiện: Khán giả đến nghe nhạc (\"Enjoy the music!\"), không phải xem thi đấu thể thao.","C":"Bẫy bối cảnh biểu diễn: Sự kiện có bán vé gây quỹ (\"ticket sales\") và chuẩn bị diễn ra chính thức, không phải buổi tập kịch.","D":"Thông tin không có trong bài: Bài phát biểu cảm ơn đóng góp xây dựng trung tâm cộng đồng, không nhắc đến lễ trao giải."},"evDocIdx":0,"evTargets":[{"badge":"Câu 80 · Đáp án A","opt":"A","isCorrect":true,"quote":"Before the benefit concert begins, I want to thank all of you for supporting the Hillcaster Community Center.","viQuote":"Trước khi buổi hòa nhạc gây quỹ bắt đầu, tôi muốn cảm ơn tất cả quý vị đã ủng hộ trung tâm Hillcaster Community Center."},{"badge":"Câu 80 · Đáp án A","opt":"A","isCorrect":true,"quote":"So far, we've raised 5,000 dollars in ticket sales, but we haven't quite reached our goal yet.","viQuote":"Tính đến nay, chúng tôi đã gây quỹ được 5.000 đô la từ tiền bán vé, nhưng vẫn chưa hoàn toàn đạt được mục tiêu đề ra."}],"evQuotes":["Before the benefit concert begins, I want to thank all of you for supporting the Hillcaster Community Center.","So far, we've raised 5,000 dollars in ticket sales, but we haven't quite reached our goal yet."]},{"q":81,"part":4,"group_id":"E25_T01_G80_82","audio":"web_assets/ets2025/audio/E25_T01/track_48.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the organization plan to do?","stem_vi":"Tổ chức này dự định làm gì?","options":{"A":{"en":"Change a policy","vi":"Thay đổi một chính sách"},"B":{"en":"Repair a building","vi":"Sửa chữa một tòa nhà"},"C":{"en":"Select a winner","vi":"Chọn ra người chiến thắng"},"D":{"en":"Sponsor a team","vi":"Tài trợ cho một đội"}},"ans":"B","explanation":"Đáp án đúng: (B) Sửa chữa một tòa nhà — Người nói cho biết cơ sở vật chất của trung tâm cộng đồng cần sửa chữa từ lâu và 80% doanh thu quầy đồ ăn sẽ dùng cho công tác xây dựng tại trung tâm (\"facilities have been in need of some repairs\" → \"Repair a building\").\nDẫn chứng: \"As you know, our facilities have been in need of some repairs for quite a while... Eighty percent of the proceeds will go to construction at the Hillcaster Community Center.\" (Như quý vị đã biết, cơ sở vật chất của chúng tôi đã cần được sửa chữa từ khá lâu rồi... 80% số tiền thu được sẽ được dành cho công tác xây dựng tại Hillcaster Community Center.)\nPhân tích bẫy:\n- (A) Không có nội dung nào về việc thay đổi quy định hay chính sách của trung tâm cộng đồng.\n- (C) Không có cuộc thi hay việc chọn ra người chiến thắng nào trong chương trình gây quỹ này.\n- (D) Tiền gây quỹ được dùng cho xây dựng và sửa chữa cơ sở vật chất, không phải để tài trợ cho một đội nhóm nào.","lines":[{"speaker":"M-Au (Bài phát biểu)","en":"Before the benefit concert begins, I want to thank all of you for supporting the Hillcaster Community Center. As you know, our facilities have been in need of some repairs for quite a while.","vi":"Trước khi buổi hòa nhạc gây quỹ bắt đầu, tôi muốn cảm ơn tất cả quý vị đã ủng hộ trung tâm Hillcaster Community Center. Như quý vị đã biết, cơ sở vật chất của chúng tôi đã cần được sửa chữa từ khá lâu rồi.","units":[{"en":"Before the benefit concert begins, I want to thank all of you for supporting the Hillcaster Community Center.","vi":"Trước khi buổi hòa nhạc gây quỹ bắt đầu, tôi muốn cảm ơn tất cả quý vị đã ủng hộ trung tâm Hillcaster Community Center."},{"en":"As you know, our facilities have been in need of some repairs for quite a while.","vi":"Như quý vị đã biết, cơ sở vật chất của chúng tôi đã cần được sửa chữa từ khá lâu rồi."}]},{"speaker":"M-Au","en":"So far, we've raised 5,000 dollars in ticket sales, but we haven't quite reached our goal yet.","vi":"Tính đến nay, chúng tôi đã gây quỹ được 5.000 đô la từ tiền bán vé, nhưng vẫn chưa hoàn toàn đạt được mục tiêu đề ra.","units":[{"en":"So far, we've raised 5,000 dollars in ticket sales, but we haven't quite reached our goal yet.","vi":"Tính đến nay, chúng tôi đã gây quỹ được 5.000 đô la từ tiền bán vé, nhưng vẫn chưa hoàn toàn đạt được mục tiêu đề ra."}]},{"speaker":"M-Au","en":"So during the concert, I want to encourage you to buy food and drinks from the concession stand. Eighty percent of the proceeds will go to construction at the Hillcaster Community Center. Enjoy the music!","vi":"Vì vậy, trong suốt buổi hòa nhạc, tôi muốn khuyến khích quý vị mua đồ ăn và thức uống tại quầy giải khát. 80% số tiền thu được sẽ được dành cho công tác xây dựng tại Hillcaster Community Center. Chúc quý vị thưởng thức âm nhạc vui vẻ!","units":[{"en":"So during the concert, I want to encourage you to buy food and drinks from the concession stand.","vi":"Vì vậy, trong suốt buổi hòa nhạc, tôi muốn khuyến khích quý vị mua đồ ăn và thức uống tại quầy giải khát."},{"en":"Eighty percent of the proceeds will go to construction at the Hillcaster Community Center.","vi":"80% số tiền thu được sẽ được dành cho công tác xây dựng tại Hillcaster Community Center."},{"en":"Enjoy the music!","vi":"Chúc quý vị thưởng thức âm nhạc vui vẻ!"}]}],"vocab":[{"word":"facility","pos":"n","ipa":"/fəˈsɪləti/","meaning":"cơ sở vật chất"},{"word":"in need of","pos":"phr","ipa":"/ɪn niːd ʌv/","meaning":"đang cần được"},{"word":"proceeds","pos":"n","ipa":"/ˈproʊsiːdz/","meaning":"số tiền thu được, doanh thu"},{"word":"construction","pos":"n","ipa":"/kənˈstrʌkʃən/","meaning":"công tác xây dựng, tu sửa"}],"isScanBacked":false,"grammarType":"Part 4 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 4 (PART 4 THUỘC LÒNG — Mục đích tổ chức): Nghe nguyên nhân gây quỹ (\"facilities have been in need of some repairs\" + \"go to construction\") để nối sang paraphrase \"Repair a building\".","optionAnalysis":{"A":"Không xuất hiện trong bài: Trung tâm chỉ kêu gọi kinh phí sửa chữa cơ sở vật chất, không bàn về thay đổi chính sách.","B":"Chính xác: Paraphrase trực tiếp từ \"our facilities have been in need of some repairs\" và \"go to construction\".","C":"Bẫy suy diễn sự kiện: Đây là buổi hòa nhạc gây quỹ chứ không phải cuộc thi có người thắng cuộc.","D":"Sai mục đích sử dụng quỹ: Nguồn tiền thu được dành để sửa chữa tòa nhà trung tâm, không phải tài trợ cho đội nào."},"evDocIdx":0,"evTargets":[{"badge":"Câu 81 · Đáp án B","opt":"B","isCorrect":true,"quote":"As you know, our facilities have been in need of some repairs for quite a while.","viQuote":"Như quý vị đã biết, cơ sở vật chất của chúng tôi đã cần được sửa chữa từ khá lâu rồi."},{"badge":"Câu 81 · Đáp án B","opt":"B","isCorrect":true,"quote":"Eighty percent of the proceeds will go to construction at the Hillcaster Community Center.","viQuote":"80% số tiền thu được sẽ được dành cho công tác xây dựng tại Hillcaster Community Center."}],"evQuotes":["As you know, our facilities have been in need of some repairs for quite a while.","Eighty percent of the proceeds will go to construction at the Hillcaster Community Center."]},{"q":82,"part":4,"group_id":"E25_T01_G80_82","audio":"web_assets/ets2025/audio/E25_T01/track_48.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the speaker encourage the listeners to do?","stem_vi":"Người nói khuyến khích người nghe làm gì?","options":{"A":{"en":"Order tickets early","vi":"Đặt vé sớm"},"B":{"en":"Visit a community center","vi":"Đến thăm một trung tâm cộng đồng"},"C":{"en":"Purchase refreshments","vi":"Mua đồ ăn nhẹ và thức uống"},"D":{"en":"Donate clothing","vi":"Quyên góp quần áo"}},"ans":"C","explanation":"Đáp án đúng: (C) Mua đồ ăn nhẹ và thức uống — Người nói khuyến khích khán giả mua đồ ăn và thức uống tại quầy giải khát trong suốt buổi hòa nhạc để đóng góp 80% doanh thu cho quỹ (\"buy food and drinks\" → \"Purchase refreshments\").\nDẫn chứng: \"So during the concert, I want to encourage you to buy food and drinks from the concession stand.\" (Vì vậy, trong suốt buổi hòa nhạc, tôi muốn khuyến khích quý vị mua đồ ăn và thức uống tại quầy giải khát.)\nPhân tích bẫy:\n- (A) Bẫy lặp từ \"ticket\": vé đã được bán trước đó (\"raised 5,000 dollars in ticket sales\"), người nói không kêu gọi đặt vé sớm.\n- (B) Bẫy lặp từ \"community center\": trung tâm cộng đồng là nơi nhận tiền sửa chữa, không phải lời kêu gọi đến tham quan trung tâm.\n- (D) Bẫy suy diễn hoạt động từ thiện: chương trình gây quỹ bằng tiền bán vé và quầy đồ ăn, không kêu gọi quyên góp quần áo.","lines":[{"speaker":"M-Au (Bài phát biểu)","en":"Before the benefit concert begins, I want to thank all of you for supporting the Hillcaster Community Center. As you know, our facilities have been in need of some repairs for quite a while.","vi":"Trước khi buổi hòa nhạc gây quỹ bắt đầu, tôi muốn cảm ơn tất cả quý vị đã ủng hộ trung tâm Hillcaster Community Center. Như quý vị đã biết, cơ sở vật chất của chúng tôi đã cần được sửa chữa từ khá lâu rồi.","units":[{"en":"Before the benefit concert begins, I want to thank all of you for supporting the Hillcaster Community Center.","vi":"Trước khi buổi hòa nhạc gây quỹ bắt đầu, tôi muốn cảm ơn tất cả quý vị đã ủng hộ trung tâm Hillcaster Community Center."},{"en":"As you know, our facilities have been in need of some repairs for quite a while.","vi":"Như quý vị đã biết, cơ sở vật chất của chúng tôi đã cần được sửa chữa từ khá lâu rồi."}]},{"speaker":"M-Au","en":"So far, we've raised 5,000 dollars in ticket sales, but we haven't quite reached our goal yet.","vi":"Tính đến nay, chúng tôi đã gây quỹ được 5.000 đô la từ tiền bán vé, nhưng vẫn chưa hoàn toàn đạt được mục tiêu đề ra.","units":[{"en":"So far, we've raised 5,000 dollars in ticket sales, but we haven't quite reached our goal yet.","vi":"Tính đến nay, chúng tôi đã gây quỹ được 5.000 đô la từ tiền bán vé, nhưng vẫn chưa hoàn toàn đạt được mục tiêu đề ra."}]},{"speaker":"M-Au","en":"So during the concert, I want to encourage you to buy food and drinks from the concession stand. Eighty percent of the proceeds will go to construction at the Hillcaster Community Center. Enjoy the music!","vi":"Vì vậy, trong suốt buổi hòa nhạc, tôi muốn khuyến khích quý vị mua đồ ăn và thức uống tại quầy giải khát. 80% số tiền thu được sẽ được dành cho công tác xây dựng tại Hillcaster Community Center. Chúc quý vị thưởng thức âm nhạc vui vẻ!","units":[{"en":"So during the concert, I want to encourage you to buy food and drinks from the concession stand.","vi":"Vì vậy, trong suốt buổi hòa nhạc, tôi muốn khuyến khích quý vị mua đồ ăn và thức uống tại quầy giải khát."},{"en":"Eighty percent of the proceeds will go to construction at the Hillcaster Community Center.","vi":"80% số tiền thu được sẽ được dành cho công tác xây dựng tại Hillcaster Community Center."},{"en":"Enjoy the music!","vi":"Chúc quý vị thưởng thức âm nhạc vui vẻ!"}]}],"vocab":[{"word":"encourage","pos":"v","ipa":"/ɪnˈkɜːrɪdʒ/","meaning":"khuyến khích, động viên"},{"word":"concession stand","pos":"n","ipa":"/kənˈseʃən stænd/","meaning":"quầy bán đồ ăn nhẹ và nước giải khát"},{"word":"refreshments","pos":"n","ipa":"/rɪˈfreʃmənts/","meaning":"đồ ăn nhẹ và thức uống"},{"word":"reach a goal","pos":"phr","ipa":"/riːtʃ ə ɡoʊl/","meaning":"đạt được mục tiêu"}],"isScanBacked":false,"grammarType":"Part 4 — Hành động tiếp theo & Đề xuất (Next Step & Offer/Request)","formula":"CÔNG THỨC PART 4 (PART 4 THUỘC LÒNG — Khuyến khích & Paraphrase): Bắt động từ trong câu hỏi \"encourage ... to do\" → \"buy food and drinks\" được paraphrase thành \"Purchase refreshments\".","optionAnalysis":{"A":"Bẫy lặp từ \"ticket\": Tiền bán vé đã thu được 5.000 đô la tính đến hiện tại, không phải lời khuyên đặt vé sớm.","B":"Bẫy lặp từ \"community center\": Hillcaster Community Center là đơn vị thụ hưởng quỹ sửa chữa, không phải địa điểm được mời tới tham quan.","C":"Chính xác: \"buy food and drinks from the concession stand\" khớp chuẩn paraphrase thành \"Purchase refreshments\".","D":"Bẫy liên tưởng từ thiện: Dù là sự kiện gây quỹ (\"benefit concert\"), bài nói chỉ kêu gọi mua đồ ăn thức uống chứ không quyên góp quần áo."},"evDocIdx":0,"evTargets":[{"badge":"Câu 82 · Đáp án C","opt":"C","isCorrect":true,"quote":"So during the concert, I want to encourage you to buy food and drinks from the concession stand.","viQuote":"Vì vậy, trong suốt buổi hòa nhạc, tôi muốn khuyến khích quý vị mua đồ ăn và thức uống tại quầy giải khát."}],"evQuotes":["So during the concert, I want to encourage you to buy food and drinks from the concession stand."]},{"q":83,"part":4,"group_id":"E25_T01_G83_85","audio":"web_assets/ets2025/audio/E25_T01/track_49.mp3","graphicImg":null,"transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_23.webp","web_assets/ets2025/tr/E25_T01_tr_24.webp"],"stem_en":"What is the topic of the workshop?","stem_vi":"Chủ đề của buổi hội thảo là gì?","options":{"A":{"en":"Time management","vi":"Quản lý thời gian"},"B":{"en":"Public speaking","vi":"Thuyết trình trước công chúng"},"C":{"en":"Leadership skills","vi":"Kỹ năng lãnh đạo"},"D":{"en":"Professional networking","vi":"Xây dựng mạng lưới quan hệ nghề nghiệp"}},"ans":"A","explanation":"Đáp án đúng: (A) Quản lý thời gian — Diễn giả nêu rõ buổi hội thảo tập trung vào việc sử dụng thời gian hiệu quả và lên kế hoạch sử dụng thời gian hợp lý cho chủ doanh nghiệp (\"using time efficiently\" → \"Time management\").\nDẫn chứng: \"...we'll be focusing on using time efficiently as a business owner. Planning and spending your time wisely is a key factor to business success.\" (...chúng tôi sẽ tập trung vào cách sử dụng thời gian hiệu quả trên cương vị chủ doanh nghiệp. Việc lập kế hoạch và sử dụng thời gian một cách hợp lý là yếu tố then chốt dẫn đến thành công trong kinh doanh.)\nPhân tích bẫy:\n- (B) Kỹ năng thuyết trình trước công chúng không được nhắc đến; diễn giả chỉ dùng từ \"presentation\" để chỉ bài trình bày của chính mình.\n- (C) Bẫy liên tưởng từ \"business owner\": đối tượng tham dự là chủ doanh nghiệp, nhưng chủ đề cụ thể là quản lý thời gian chứ không phải kỹ năng lãnh đạo chung.\n- (D) Bẫy suy diễn từ hoạt động làm quen ở cuối bài (\"get to know one another better\"): làm quen chỉ là bài tập khởi động, không phải chủ đề chính của hội thảo.","lines":[{"speaker":"M-Cn (Bài phát biểu)","en":"Thank you all for attending today's workshop. Erina Kimura and I will be conducting the session, and we'll be focusing on using time efficiently as a business owner. Planning and spending your time wisely is a key factor to business success.","vi":"Cảm ơn tất cả quý vị đã tham dự buổi hội thảo hôm nay. Erina Kimura và tôi sẽ cùng điều phối buổi hội thảo này, và chúng tôi sẽ tập trung vào cách sử dụng thời gian hiệu quả trên cương vị chủ doanh nghiệp. Việc lập kế hoạch và sử dụng thời gian một cách hợp lý là yếu tố then chốt dẫn đến thành công trong kinh doanh.","units":[{"en":"Thank you all for attending today's workshop.","vi":"Cảm ơn tất cả quý vị đã tham dự buổi hội thảo hôm nay."},{"en":"Erina Kimura and I will be conducting the session, and we'll be focusing on using time efficiently as a business owner.","vi":"Erina Kimura và tôi sẽ cùng điều phối buổi hội thảo này, và chúng tôi sẽ tập trung vào cách sử dụng thời gian hiệu quả trên cương vị chủ doanh nghiệp."},{"en":"Planning and spending your time wisely is a key factor to business success.","vi":"Việc lập kế hoạch và sử dụng thời gian một cách hợp lý là yếu tố then chốt dẫn đến thành công trong kinh doanh."}]},{"speaker":"M-Cn","en":"During the presentation, I'll be referring to documents from the packet you were handed as you arrived. If you don't have one yet, Erina's at the back of the room.","vi":"Trong bài thuyết trình, tôi sẽ dẫn chiếu các tài liệu trong tập hồ sơ mà quý vị đã được phát khi mới đến. Nếu quý vị nào chưa có, Erina đang ở phía cuối phòng.","units":[{"en":"During the presentation, I'll be referring to documents from the packet you were handed as you arrived.","vi":"Trong bài thuyết trình, tôi sẽ dẫn chiếu các tài liệu trong tập hồ sơ mà quý vị đã được phát khi mới đến."},{"en":"If you don't have one yet, Erina's at the back of the room.","vi":"Nếu quý vị nào chưa có, Erina đang ở phía cuối phòng."}]},{"speaker":"M-Cn","en":"OK then, to start off, we'll do an exercise to get to know one another better.","vi":"Được rồi, để mở đầu, chúng ta sẽ cùng làm một bài tập giúp mọi người làm quen với nhau hơn.","units":[{"en":"OK then, to start off, we'll do an exercise to get to know one another better.","vi":"Được rồi, để mở đầu, chúng ta sẽ cùng làm một bài tập giúp mọi người làm quen với nhau hơn."}]}],"vocab":[{"word":"conduct","pos":"v","ipa":"/kənˈdʌkt/","meaning":"điều phối, tiến hành"},{"word":"efficiently","pos":"adv","ipa":"/ɪˈfɪʃəntli/","meaning":"một cách hiệu quả"},{"word":"wisely","pos":"adv","ipa":"/ˈwaɪzli/","meaning":"một cách khôn ngoan, hợp lý"},{"word":"key factor","pos":"n","ipa":"/kiː ˈfæktər/","meaning":"yếu tố then chốt"}],"isScanBacked":false,"grammarType":"Part 4 — Ý chính & Mục đích (Gist & Purpose)","formula":"CÔNG THỨC PART 4 (PART 4 THUỘC LÒNG — Chủ đề hội thảo): Nghe cụm chỉ trọng tâm ngay sau lời chào (\"we'll be focusing on...\") và quy đổi \"using time efficiently / spending your time wisely\" → \"Time management\".","optionAnalysis":{"A":"Chính xác: Paraphrase trực tiếp từ \"using time efficiently\" và \"Planning and spending your time wisely\".","B":"Bẫy đồng dạng từ \"presentation\": Người nói nhắc \"During the presentation\" (trong phần trình bày của tôi), không dạy kỹ năng thuyết trình.","C":"Bẫy suy diễn theo \"business owner\": Hội thảo dành cho chủ doanh nghiệp nhưng nội dung trọng tâm là quản lý thời gian, không phải kỹ năng lãnh đạo.","D":"Bẫy chi tiết hoạt động mở đầu: Bài tập cuối đoạn giúp mọi người làm quen nhau, không phải chủ đề \"networking\" của cả buổi hội thảo."},"evDocIdx":0,"evTargets":[{"badge":"Câu 83 · Đáp án A","opt":"A","isCorrect":true,"quote":"Erina Kimura and I will be conducting the session, and we'll be focusing on using time efficiently as a business owner.","viQuote":"Erina Kimura và tôi sẽ cùng điều phối buổi hội thảo này, và chúng tôi sẽ tập trung vào cách sử dụng thời gian hiệu quả trên cương vị chủ doanh nghiệp."},{"badge":"Câu 83 · Đáp án A","opt":"A","isCorrect":true,"quote":"Planning and spending your time wisely is a key factor to business success.","viQuote":"Việc lập kế hoạch và sử dụng thời gian một cách hợp lý là yếu tố then chốt dẫn đến thành công trong kinh doanh."}],"evQuotes":["Erina Kimura and I will be conducting the session, and we'll be focusing on using time efficiently as a business owner.","Planning and spending your time wisely is a key factor to business success."]},{"q":84,"part":4,"group_id":"E25_T01_G83_85","audio":"web_assets/ets2025/audio/E25_T01/track_49.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the speaker imply when he says, \"Erina's at the back of the room\"?","stem_vi":"Người nói ngụ ý gì khi nói \"Erina's at the back of the room\"?","options":{"A":{"en":"A guest speaker has just arrived.","vi":"Một diễn giả khách mời vừa mới đến."},"B":{"en":"Assistance is available.","vi":"Có người sẵn sàng hỗ trợ."},"C":{"en":"Attendees should speak clearly and loudly.","vi":"Người tham dự nên nói to và rõ ràng."},"D":{"en":"An extra chair should be provided.","vi":"Cần bố trí thêm một chiếc ghế."}},"ans":"B","explanation":"Đáp án đúng: (B) Có người sẵn sàng hỗ trợ — Ngay trước câu trích dẫn, diễn giả đặt điều kiện nếu ai chưa nhận được tập tài liệu phát khi đến cửa thì Erina (người đồng điều phối) đang đứng ở cuối phòng để hỗ trợ phát bổ sung.\nDẫn chứng: \"During the presentation, I'll be referring to documents from the packet you were handed as you arrived. If you don't have one yet, Erina's at the back of the room.\" (Trong bài thuyết trình, tôi sẽ dẫn chiếu các tài liệu trong tập hồ sơ mà quý vị đã được phát khi mới đến. Nếu quý vị nào chưa có, Erina đang ở phía cuối phòng.)\nPhân tích bẫy:\n- (A) Sai vai trò và hành động: Erina Kimura là người cùng điều phối buổi hội thảo (\"Erina Kimura and I will be conducting the session\"), không phải khách mời vừa mới tới.\n- (C) Bẫy diễn giải theo nghĩa đen cụm \"at the back of the room\": nhắc vị trí cuối phòng không nhằm yêu cầu khán giả nói to hơn để phía sau nghe thấy.\n- (D) Không có ngữ cảnh thiếu chỗ ngồi; Erina đứng ở cuối phòng để phát tập tài liệu (\"packet\") cho người chưa có.","lines":[{"speaker":"M-Cn (Bài phát biểu)","en":"Thank you all for attending today's workshop. Erina Kimura and I will be conducting the session, and we'll be focusing on using time efficiently as a business owner. Planning and spending your time wisely is a key factor to business success.","vi":"Cảm ơn tất cả quý vị đã tham dự buổi hội thảo hôm nay. Erina Kimura và tôi sẽ cùng điều phối buổi hội thảo này, và chúng tôi sẽ tập trung vào cách sử dụng thời gian hiệu quả trên cương vị chủ doanh nghiệp. Việc lập kế hoạch và sử dụng thời gian một cách hợp lý là yếu tố then chốt dẫn đến thành công trong kinh doanh.","units":[{"en":"Thank you all for attending today's workshop.","vi":"Cảm ơn tất cả quý vị đã tham dự buổi hội thảo hôm nay."},{"en":"Erina Kimura and I will be conducting the session, and we'll be focusing on using time efficiently as a business owner.","vi":"Erina Kimura và tôi sẽ cùng điều phối buổi hội thảo này, và chúng tôi sẽ tập trung vào cách sử dụng thời gian hiệu quả trên cương vị chủ doanh nghiệp."},{"en":"Planning and spending your time wisely is a key factor to business success.","vi":"Việc lập kế hoạch và sử dụng thời gian một cách hợp lý là yếu tố then chốt dẫn đến thành công trong kinh doanh."}]},{"speaker":"M-Cn","en":"During the presentation, I'll be referring to documents from the packet you were handed as you arrived. If you don't have one yet, Erina's at the back of the room.","vi":"Trong bài thuyết trình, tôi sẽ dẫn chiếu các tài liệu trong tập hồ sơ mà quý vị đã được phát khi mới đến. Nếu quý vị nào chưa có, Erina đang ở phía cuối phòng.","units":[{"en":"During the presentation, I'll be referring to documents from the packet you were handed as you arrived.","vi":"Trong bài thuyết trình, tôi sẽ dẫn chiếu các tài liệu trong tập hồ sơ mà quý vị đã được phát khi mới đến."},{"en":"If you don't have one yet, Erina's at the back of the room.","vi":"Nếu quý vị nào chưa có, Erina đang ở phía cuối phòng."}]},{"speaker":"M-Cn","en":"OK then, to start off, we'll do an exercise to get to know one another better.","vi":"Được rồi, để mở đầu, chúng ta sẽ cùng làm một bài tập giúp mọi người làm quen với nhau hơn.","units":[{"en":"OK then, to start off, we'll do an exercise to get to know one another better.","vi":"Được rồi, để mở đầu, chúng ta sẽ cùng làm một bài tập giúp mọi người làm quen với nhau hơn."}]}],"vocab":[{"word":"refer to","pos":"phr. v","ipa":"/rɪˈfɜːr tuː/","meaning":"đề cập đến, dẫn chiếu tới"},{"word":"packet","pos":"n","ipa":"/ˈpækɪt/","meaning":"tập tài liệu, bộ hồ sơ"},{"word":"hand","pos":"v","ipa":"/hænd/","meaning":"trao tận tay, phát cho"},{"word":"assistance","pos":"n","ipa":"/əˈsɪstəns/","meaning":"sự hỗ trợ"}],"isScanBacked":false,"grammarType":"Part 4 — Câu hỏi hàm ý (Speaker Intent / Implied Meaning)","formula":"CÔNG THỨC PART 4 (PART 4 THUỘC LÒNG — Câu hỏi hàm ý): Luôn đọc câu đứng ngay trước câu trích dẫn (\"If you don't have one yet...\") để hiểu mục đích chỉ chỗ đồng điều phối Erina giúp phát tài liệu còn thiếu.","optionAnalysis":{"A":"Sai thông tin đầu bài: Erina là người đồng tổ chức buổi hội thảo từ đầu, không phải diễn giả khách mời vừa mới bước vào.","B":"Chính xác: Câu điều kiện ngay trước (\"If you don't have one yet\") cho thấy Erina ở cuối phòng sẵn sàng hỗ trợ phát tập tài liệu.","C":"Bẫy hiểu sai vị trí: Việc nêu Erina ở cuối phòng là để người thiếu tài liệu quay lại nhận, không phải nhắc mọi người nói lớn tiếng.","D":"Suy diễn ngoài ngữ cảnh: Vấn đề đang được giải quyết là thiếu tập tài liệu (\"packet\"), hoàn toàn không nhắc đến việc thiếu ghế ngồi."},"evDocIdx":0,"evTargets":[{"badge":"Câu 84 · Đáp án B","opt":"B","isCorrect":true,"quote":"During the presentation, I'll be referring to documents from the packet you were handed as you arrived.","viQuote":"Trong bài thuyết trình, tôi sẽ dẫn chiếu các tài liệu trong tập hồ sơ mà quý vị đã được phát khi mới đến."},{"badge":"Câu 84 · Đáp án B","opt":"B","isCorrect":true,"quote":"If you don't have one yet, Erina's at the back of the room.","viQuote":"Nếu quý vị nào chưa có, Erina đang ở phía cuối phòng."}],"evQuotes":["During the presentation, I'll be referring to documents from the packet you were handed as you arrived.","If you don't have one yet, Erina's at the back of the room."]},{"q":85,"part":4,"group_id":"E25_T01_G83_85","audio":"web_assets/ets2025/audio/E25_T01/track_49.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What will the listeners do next?","stem_vi":"Người nghe sẽ làm gì tiếp theo?","options":{"A":{"en":"Sign their names on a list","vi":"Ký tên vào một danh sách"},"B":{"en":"Take a break","vi":"Nghỉ giải lao"},"C":{"en":"Participate in an introductory activity","vi":"Tham gia một hoạt động làm quen"},"D":{"en":"Fill out a questionnaire","vi":"Điền vào bảng câu hỏi khảo sát"}},"ans":"C","explanation":"Đáp án đúng: (C) Tham gia một hoạt động làm quen — Ở câu cuối, diễn giả nói để mở đầu buổi hội thảo, cả nhóm sẽ làm một bài tập giúp mọi người làm quen với nhau hơn (\"an exercise to get to know one another better\" → \"an introductory activity\").\nDẫn chứng: \"OK then, to start off, we'll do an exercise to get to know one another better.\" (Được rồi, để mở đầu, chúng ta sẽ cùng làm một bài tập giúp mọi người làm quen với nhau hơn.)\nPhân tích bẫy:\n- (A) Không có yêu cầu ký tên vào danh sách điểm danh nào ở phần mở đầu hội thảo.\n- (B) Hội thảo mới bắt đầu (\"to start off\"), không thể nghỉ giải lao ngay lúc này.\n- (D) Bẫy liên tưởng từ \"documents from the packet\" và \"exercise\": tập hồ sơ là tài liệu phục vụ bài thuyết trình, không phải bảng câu hỏi khảo sát cần điền ngay.","lines":[{"speaker":"M-Cn (Bài phát biểu)","en":"Thank you all for attending today's workshop. Erina Kimura and I will be conducting the session, and we'll be focusing on using time efficiently as a business owner. Planning and spending your time wisely is a key factor to business success.","vi":"Cảm ơn tất cả quý vị đã tham dự buổi hội thảo hôm nay. Erina Kimura và tôi sẽ cùng điều phối buổi hội thảo này, và chúng tôi sẽ tập trung vào cách sử dụng thời gian hiệu quả trên cương vị chủ doanh nghiệp. Việc lập kế hoạch và sử dụng thời gian một cách hợp lý là yếu tố then chốt dẫn đến thành công trong kinh doanh.","units":[{"en":"Thank you all for attending today's workshop.","vi":"Cảm ơn tất cả quý vị đã tham dự buổi hội thảo hôm nay."},{"en":"Erina Kimura and I will be conducting the session, and we'll be focusing on using time efficiently as a business owner.","vi":"Erina Kimura và tôi sẽ cùng điều phối buổi hội thảo này, và chúng tôi sẽ tập trung vào cách sử dụng thời gian hiệu quả trên cương vị chủ doanh nghiệp."},{"en":"Planning and spending your time wisely is a key factor to business success.","vi":"Việc lập kế hoạch và sử dụng thời gian một cách hợp lý là yếu tố then chốt dẫn đến thành công trong kinh doanh."}]},{"speaker":"M-Cn","en":"During the presentation, I'll be referring to documents from the packet you were handed as you arrived. If you don't have one yet, Erina's at the back of the room.","vi":"Trong bài thuyết trình, tôi sẽ dẫn chiếu các tài liệu trong tập hồ sơ mà quý vị đã được phát khi mới đến. Nếu quý vị nào chưa có, Erina đang ở phía cuối phòng.","units":[{"en":"During the presentation, I'll be referring to documents from the packet you were handed as you arrived.","vi":"Trong bài thuyết trình, tôi sẽ dẫn chiếu các tài liệu trong tập hồ sơ mà quý vị đã được phát khi mới đến."},{"en":"If you don't have one yet, Erina's at the back of the room.","vi":"Nếu quý vị nào chưa có, Erina đang ở phía cuối phòng."}]},{"speaker":"M-Cn","en":"OK then, to start off, we'll do an exercise to get to know one another better.","vi":"Được rồi, để mở đầu, chúng ta sẽ cùng làm một bài tập giúp mọi người làm quen với nhau hơn.","units":[{"en":"OK then, to start off, we'll do an exercise to get to know one another better.","vi":"Được rồi, để mở đầu, chúng ta sẽ cùng làm một bài tập giúp mọi người làm quen với nhau hơn."}]}],"vocab":[{"word":"to start off","pos":"phr","ipa":"/tuː stɑːrt ɔːf/","meaning":"để mở đầu, trước hết"},{"word":"exercise","pos":"n","ipa":"/ˈeksərsaɪz/","meaning":"bài tập, hoạt động thực hành"},{"word":"get to know","pos":"phr","ipa":"/ɡet tuː noʊ/","meaning":"làm quen, tìm hiểu về"},{"word":"introductory","pos":"adj","ipa":"/ˌɪntrəˈdʌktəri/","meaning":"mang tính mở đầu, giới thiệu"}],"isScanBacked":false,"grammarType":"Part 4 — Hành động tiếp theo & Đề xuất (Next Step & Offer/Request)","formula":"CÔNG THỨC PART 4 (PART 4 THUỘC LÒNG — Hành động tiếp theo): Nghe cụm chuyển tiếp ở câu kết bài (\"OK then, to start off, we'll do...\") để xác định hoạt động đầu tiên sắp diễn ra.","optionAnalysis":{"A":"Chi tiết bịa đặt: Bài nói không nhắc tới danh sách ký tên hay thủ tục điểm danh người tham dự.","B":"Sai thời điểm: Cụm \"to start off\" báo hiệu buổi hội thảo mới bắt đầu, chưa đến giờ nghỉ giải lao.","C":"Chính xác: \"do an exercise to get to know one another better\" được paraphrase chuẩn xác thành \"Participate in an introductory activity\".","D":"Bẫy liên tưởng tài liệu: Tập tài liệu (\"packet\") dùng để đối chiếu trong bài giảng, không phải phiếu khảo sát cần điền ngay."},"evDocIdx":0,"evTargets":[{"badge":"Câu 85 · Đáp án C","opt":"C","isCorrect":true,"quote":"OK then, to start off, we'll do an exercise to get to know one another better.","viQuote":"Được rồi, để mở đầu, chúng ta sẽ cùng làm một bài tập giúp mọi người làm quen với nhau hơn."}],"evQuotes":["OK then, to start off, we'll do an exercise to get to know one another better."]},{"q":86,"part":4,"group_id":"E25_T01_G86_88","audio":"web_assets/ets2025/audio/E25_T01/track_50.mp3","graphicImg":null,"transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_24.webp","web_assets/ets2025/tr/E25_T01_tr_25.webp"],"stem_en":"What is a historical site famous for?","stem_vi":"Di tích lịch sử nổi tiếng vì điều gì?","options":{"A":{"en":"Its defensive walls","vi":"Những bức tường thành phòng thủ"},"B":{"en":"Its royal inhabitants","vi":"Những cư dân hoàng gia từng sinh sống"},"C":{"en":"An event that happened there","vi":"Một sự kiện từng diễn ra tại đó"},"D":{"en":"Some artwork","vi":"Một số tác phẩm nghệ thuật"}},"ans":"D","explanation":"Đáp án đúng: (D) Một số tác phẩm nghệ thuật — Bài giới thiệu khẳng định điều làm khu phế tích nổi tiếng nhất là những viên gạch khảm nhiều màu sắc và các bức tranh khắc họa đời sống thường ngày của nghệ nhân.\nDẫn chứng: \"...colorful mosaic tiles on the walls. You'll notice how vibrant the colors are... This is what the ruins are most famous for. You can still see intricate details in the artists' pictures of scenes from daily life.\" (Paraphrase: colorful mosaic tiles & artists' pictures -> Some artwork).\nPhân tích bẫy:\n- (A) Bẫy nhắc từ 'walls': bài nói nhắc 'mosaic tiles on the walls' (tranh khảm trên tường khu chợ), không phải tường thành phòng thủ (defensive walls).\n- (B) Sai bối cảnh di tích: địa điểm khai quật là tàn tích một khu chợ thế kỷ thứ 5 (fifth-century marketplace) với tranh sinh hoạt đời thường, không đề cập cư dân hoàng gia.\n- (C) Suy diễn sai trọng tâm: bài nói nhấn mạnh nét nghệ thuật rực rỡ qua nhiều thế kỷ, không nhắc đến một sự kiện lịch sử cụ thể nào từng xảy ra tại đây.","lines":[{"speaker":"W-Br (Thông tin du lịch)","en":"At this site, archaeologists have uncovered the remains of a fifth-century marketplace with colorful mosaic tiles on the walls. You'll notice how vibrant the colors are, even after all these centuries. This is what the ruins are most famous for. You can still see intricate details in the artists' pictures of scenes from daily life.","vi":"Tại khu di tích này, các nhà khảo cổ đã khai quật được tàn tích của một khu chợ thế kỷ thứ năm với những viên gạch khảm đầy màu sắc trên tường. Quý vị sẽ thấy màu sắc vẫn rực rỡ đến nhường nào, ngay cả sau biết bao thế kỷ trôi qua. Đây chính là điểm nổi tiếng nhất của khu phế tích này. Quý vị vẫn có thể thấy rõ những chi tiết tinh xảo trong các bức tranh của nghệ nhân khắc họa cảnh sinh hoạt đời thường.","units":[{"en":"At this site, archaeologists have uncovered the remains of a fifth-century marketplace with colorful mosaic tiles on the walls.","vi":"Tại khu di tích này, các nhà khảo cổ đã khai quật được tàn tích của một khu chợ thế kỷ thứ năm với những viên gạch khảm đầy màu sắc trên tường."},{"en":"You'll notice how vibrant the colors are, even after all these centuries.","vi":"Quý vị sẽ thấy màu sắc vẫn rực rỡ đến nhường nào, ngay cả sau biết bao thế kỷ trôi qua."},{"en":"This is what the ruins are most famous for.","vi":"Đây chính là điểm nổi tiếng nhất của khu phế tích này."},{"en":"You can still see intricate details in the artists' pictures of scenes from daily life.","vi":"Quý vị vẫn có thể thấy rõ những chi tiết tinh xảo trong các bức tranh của nghệ nhân khắc họa cảnh sinh hoạt đời thường."}]},{"speaker":"W-Br","en":"Now, to protect the mosaics, a roof has been constructed over the area, and the lights are dim. And I'm sorry, but taking photos is not allowed, as the flash would damage the tiles.","vi":"Hiện tại, để bảo vệ các bức tranh khảm, một mái che đã được dựng lên phía trên khu vực này và ánh đèn cũng được giữ ở mức dịu nhẹ. Và tôi rất tiếc, nhưng quý vị không được phép chụp ảnh vì ánh đèn flash sẽ làm hư hại các viên gạch khảm.","units":[{"en":"Now, to protect the mosaics, a roof has been constructed over the area, and the lights are dim.","vi":"Hiện tại, để bảo vệ các bức tranh khảm, một mái che đã được dựng lên phía trên khu vực này và ánh đèn cũng được giữ ở mức dịu nhẹ."},{"en":"And I'm sorry, but taking photos is not allowed, as the flash would damage the tiles.","vi":"Và tôi rất tiếc, nhưng quý vị không được phép chụp ảnh vì ánh đèn flash sẽ làm hư hại các viên gạch khảm."}]},{"speaker":"W-Br","en":"As we proceed, please hold on to the handrails on either side. They'll help you stay on the path and protect the ruins around us.","vi":"Khi chúng ta tiếp tục di chuyển, xin quý vị vui lòng vịn vào tay vịn ở hai bên. Chúng sẽ giúp quý vị đi đúng lối đi và bảo vệ khu tàn tích xung quanh chúng ta.","units":[{"en":"As we proceed, please hold on to the handrails on either side.","vi":"Khi chúng ta tiếp tục di chuyển, xin quý vị vui lòng vịn vào tay vịn ở hai bên."},{"en":"They'll help you stay on the path and protect the ruins around us.","vi":"Chúng sẽ giúp quý vị đi đúng lối đi và bảo vệ khu tàn tích xung quanh chúng ta."}]}],"vocab":[{"word":"archaeologist","pos":"n","ipa":"/ˌɑːrkiˈɑːlədʒɪst/","meaning":"nhà khảo cổ học"},{"word":"uncover","pos":"v","ipa":"/ʌnˈkʌvər/","meaning":"khai quật, phát hiện ra"},{"word":"remains","pos":"n","ipa":"/rɪˈmeɪnz/","meaning":"di tích, tàn tích"},{"word":"intricate","pos":"adj","ipa":"/ˈɪntrɪkət/","meaning":"tinh xảo, phức tạp"}],"isScanBacked":false,"grammarType":"Part 4 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 4 (Chi tiết & Paraphrase): Nghe câu chốt đặc trưng ('This is what the ruins are most famous for') -> Ánh xạ mô tả 'colorful mosaic tiles / artists' pictures' thành danh từ khái quát 'Some artwork'.","optionAnalysis":{"A":"Bẫy từ khóa 'walls': người nói nhắc đến những viên gạch khảm gắn trên tường khu chợ cổ, không phải tường thành phòng thủ.","B":"Sai đối tượng lịch sử: khu di tích là tàn tích một khu chợ thế kỷ thứ 5 và tranh cảnh đời thường, không nhắc tới hoàng gia.","C":"Không có cơ sở trong bài: hướng dẫn viên không đề cập sự kiện lịch sử nào diễn ra tại địa điểm này mà chỉ nói về tranh khảm.","D":"Đáp án đúng: 'Some artwork' khái quát chính xác cho cụm 'colorful mosaic tiles' và 'artists' pictures' — điểm nổi tiếng nhất của di tích."},"evDocIdx":0,"evTargets":[{"badge":"Câu 86 · Đáp án D","opt":"D","isCorrect":true,"quote":"At this site, archaeologists have uncovered the remains of a fifth-century marketplace with colorful mosaic tiles on the walls.","viQuote":"Tại khu di tích này, các nhà khảo cổ đã khai quật được tàn tích của một khu chợ thế kỷ thứ năm với những viên gạch khảm đầy màu sắc trên tường."},{"badge":"Câu 86 · Đáp án D","opt":"D","isCorrect":true,"quote":"This is what the ruins are most famous for.","viQuote":"Đây chính là điểm nổi tiếng nhất của khu phế tích này."},{"badge":"Câu 86 · Đáp án D","opt":"D","isCorrect":true,"quote":"You can still see intricate details in the artists' pictures of scenes from daily life.","viQuote":"Quý vị vẫn có thể thấy rõ những chi tiết tinh xảo trong các bức tranh của nghệ nhân khắc họa cảnh sinh hoạt đời thường."}],"evQuotes":["At this site, archaeologists have uncovered the remains of a fifth-century marketplace with colorful mosaic tiles on the walls.","This is what the ruins are most famous for.","You can still see intricate details in the artists' pictures of scenes from daily life."]},{"q":87,"part":4,"group_id":"E25_T01_G86_88","audio":"web_assets/ets2025/audio/E25_T01/track_50.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"Why does the speaker apologize?","stem_vi":"Tại sao người nói lại xin lỗi?","options":{"A":{"en":"The listeners cannot take pictures.","vi":"Người nghe không được phép chụp ảnh."},"B":{"en":"An area is closed to the listeners.","vi":"Một khu vực đang đóng cửa đối với người nghe."},"C":{"en":"There is no gift shop.","vi":"Không có cửa hàng quà lưu niệm."},"D":{"en":"A tour started late.","vi":"Chuyến tham quan bắt đầu muộn."}},"ans":"A","explanation":"Đáp án đúng: (A) Người nghe không được phép chụp ảnh — Người nói xin lỗi du khách vì quy định không cho phép chụp ảnh nhằm tránh ánh đèn flash làm hư hại các viên gạch khảm cổ.\nDẫn chứng: \"And I'm sorry, but taking photos is not allowed, as the flash would damage the tiles.\" (Paraphrase: taking photos is not allowed -> cannot take pictures).\nPhân tích bẫy:\n- (B) Suy diễn sai từ chi tiết bảo tồn: mái che được dựng và đèn được giảm độ sáng (lights are dim) để bảo vệ tranh khảm, nhưng khu vực vẫn mở cửa cho đoàn tham quan.\n- (C) Thông tin không có trong bài: hướng dẫn viên không hề nhắc đến cửa hàng quà lưu niệm (gift shop) trong toàn bộ lượt lời.\n- (D) Sai nguyên nhân xin lỗi: lời xin lỗi gắn trực tiếp với lệnh cấm chụp ảnh, hoàn toàn không liên quan đến giờ khởi hành của chuyến tham quan.","lines":[{"speaker":"W-Br (Thông tin du lịch)","en":"At this site, archaeologists have uncovered the remains of a fifth-century marketplace with colorful mosaic tiles on the walls. You'll notice how vibrant the colors are, even after all these centuries. This is what the ruins are most famous for. You can still see intricate details in the artists' pictures of scenes from daily life.","vi":"Tại khu di tích này, các nhà khảo cổ đã khai quật được tàn tích của một khu chợ thế kỷ thứ năm với những viên gạch khảm đầy màu sắc trên tường. Quý vị sẽ thấy màu sắc vẫn rực rỡ đến nhường nào, ngay cả sau biết bao thế kỷ trôi qua. Đây chính là điểm nổi tiếng nhất của khu phế tích này. Quý vị vẫn có thể thấy rõ những chi tiết tinh xảo trong các bức tranh của nghệ nhân khắc họa cảnh sinh hoạt đời thường.","units":[{"en":"At this site, archaeologists have uncovered the remains of a fifth-century marketplace with colorful mosaic tiles on the walls.","vi":"Tại khu di tích này, các nhà khảo cổ đã khai quật được tàn tích của một khu chợ thế kỷ thứ năm với những viên gạch khảm đầy màu sắc trên tường."},{"en":"You'll notice how vibrant the colors are, even after all these centuries.","vi":"Quý vị sẽ thấy màu sắc vẫn rực rỡ đến nhường nào, ngay cả sau biết bao thế kỷ trôi qua."},{"en":"This is what the ruins are most famous for.","vi":"Đây chính là điểm nổi tiếng nhất của khu phế tích này."},{"en":"You can still see intricate details in the artists' pictures of scenes from daily life.","vi":"Quý vị vẫn có thể thấy rõ những chi tiết tinh xảo trong các bức tranh của nghệ nhân khắc họa cảnh sinh hoạt đời thường."}]},{"speaker":"W-Br","en":"Now, to protect the mosaics, a roof has been constructed over the area, and the lights are dim. And I'm sorry, but taking photos is not allowed, as the flash would damage the tiles.","vi":"Hiện tại, để bảo vệ các bức tranh khảm, một mái che đã được dựng lên phía trên khu vực này và ánh đèn cũng được giữ ở mức dịu nhẹ. Và tôi rất tiếc, nhưng quý vị không được phép chụp ảnh vì ánh đèn flash sẽ làm hư hại các viên gạch khảm.","units":[{"en":"Now, to protect the mosaics, a roof has been constructed over the area, and the lights are dim.","vi":"Hiện tại, để bảo vệ các bức tranh khảm, một mái che đã được dựng lên phía trên khu vực này và ánh đèn cũng được giữ ở mức dịu nhẹ."},{"en":"And I'm sorry, but taking photos is not allowed, as the flash would damage the tiles.","vi":"Và tôi rất tiếc, nhưng quý vị không được phép chụp ảnh vì ánh đèn flash sẽ làm hư hại các viên gạch khảm."}]},{"speaker":"W-Br","en":"As we proceed, please hold on to the handrails on either side. They'll help you stay on the path and protect the ruins around us.","vi":"Khi chúng ta tiếp tục di chuyển, xin quý vị vui lòng vịn vào tay vịn ở hai bên. Chúng sẽ giúp quý vị đi đúng lối đi và bảo vệ khu tàn tích xung quanh chúng ta.","units":[{"en":"As we proceed, please hold on to the handrails on either side.","vi":"Khi chúng ta tiếp tục di chuyển, xin quý vị vui lòng vịn vào tay vịn ở hai bên."},{"en":"They'll help you stay on the path and protect the ruins around us.","vi":"Chúng sẽ giúp quý vị đi đúng lối đi và bảo vệ khu tàn tích xung quanh chúng ta."}]}],"vocab":[{"word":"mosaic","pos":"n","ipa":"/moʊˈzeɪɪk/","meaning":"tranh khảm, gạch khảm"},{"word":"dim","pos":"adj","ipa":"/dɪm/","meaning":"mờ, dịu nhẹ (ánh sáng)"},{"word":"allow","pos":"v","ipa":"/əˈlaʊ/","meaning":"cho phép"},{"word":"damage","pos":"v","ipa":"/ˈdæmɪdʒ/","meaning":"làm hư hại, gây tổn hại"}],"isScanBacked":false,"grammarType":"Part 4 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 4 (Lý do & Cảm xúc người nói): Bắt tín hiệu xin lỗi ('I'm sorry, but...') -> Chốt ngay quy định cấm đi kèm ('taking photos is not allowed') để tránh bẫy suy đoán.","optionAnalysis":{"A":"Đáp án đúng: câu 'I'm sorry, but taking photos is not allowed' khớp trực tiếp với 'The listeners cannot take pictures.'","B":"Suy diễn sai từ chi tiết mái che và ánh đèn dịu: không gian di tích vẫn đón khách đi dọc lối tham quan chứ không bị đóng cửa.","C":"Ngoài nội dung bài nói: không có câu nào đề cập đến cửa hàng quà lưu niệm hay lý do xin lỗi liên quan đến mua sắm.","D":"Sai lý do xin lỗi: người nói xin lỗi vì không được dùng máy ảnh do sợ hỏng gạch khảm, không nói chuyến tham quan bắt đầu trễ."},"evDocIdx":0,"evTargets":[{"badge":"Câu 87 · Đáp án A","opt":"A","isCorrect":true,"quote":"And I'm sorry, but taking photos is not allowed, as the flash would damage the tiles.","viQuote":"Và tôi rất tiếc, nhưng quý vị không được phép chụp ảnh vì ánh đèn flash sẽ làm hư hại các viên gạch khảm."}],"evQuotes":["And I'm sorry, but taking photos is not allowed, as the flash would damage the tiles."]},{"q":88,"part":4,"group_id":"E25_T01_G86_88","audio":"web_assets/ets2025/audio/E25_T01/track_50.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the speaker ask the listeners to do?","stem_vi":"Người nói yêu cầu người nghe làm gì?","options":{"A":{"en":"Show their tickets","vi":"Xuất trình vé"},"B":{"en":"Put on protective clothing","vi":"Mặc đồ bảo hộ"},"C":{"en":"Use some handrails","vi":"Sử dụng tay vịn"},"D":{"en":"Speak quietly","vi":"Nói chuyện nhỏ nhẹ"}},"ans":"C","explanation":"Đáp án đúng: (C) Sử dụng tay vịn — Khi đoàn tiếp tục di chuyển, hướng dẫn viên đề nghị mọi người nắm vào tay vịn ở hai bên để đi đúng lối đi và bảo vệ khu tàn tích.\nDẫn chứng: \"As we proceed, please hold on to the handrails on either side. They'll help you stay on the path and protect the ruins around us.\" (Paraphrase: hold on to the handrails -> Use some handrails).\nPhân tích bẫy:\n- (A) Bẫy bối cảnh tham quan: khách tham quan thường phải xuất trình vé ở cửa vào, nhưng tại đây người nói không hề yêu cầu kiểm tra vé.\n- (B) Bẫy lặp từ 'protect': động từ 'protect' dùng cho việc bảo vệ tranh khảm và khu phế tích (protect the ruins), không phải yêu cầu khách mặc đồ bảo hộ.\n- (D) Suy diễn sai từ không gian ánh sáng dịu: dù đèn trong khu mái che hơi tối (lights are dim), người nói không đưa ra yêu cầu giữ trật tự hay nói nhỏ.","lines":[{"speaker":"W-Br (Thông tin du lịch)","en":"At this site, archaeologists have uncovered the remains of a fifth-century marketplace with colorful mosaic tiles on the walls. You'll notice how vibrant the colors are, even after all these centuries. This is what the ruins are most famous for. You can still see intricate details in the artists' pictures of scenes from daily life.","vi":"Tại khu di tích này, các nhà khảo cổ đã khai quật được tàn tích của một khu chợ thế kỷ thứ năm với những viên gạch khảm đầy màu sắc trên tường. Quý vị sẽ thấy màu sắc vẫn rực rỡ đến nhường nào, ngay cả sau biết bao thế kỷ trôi qua. Đây chính là điểm nổi tiếng nhất của khu phế tích này. Quý vị vẫn có thể thấy rõ những chi tiết tinh xảo trong các bức tranh của nghệ nhân khắc họa cảnh sinh hoạt đời thường.","units":[{"en":"At this site, archaeologists have uncovered the remains of a fifth-century marketplace with colorful mosaic tiles on the walls.","vi":"Tại khu di tích này, các nhà khảo cổ đã khai quật được tàn tích của một khu chợ thế kỷ thứ năm với những viên gạch khảm đầy màu sắc trên tường."},{"en":"You'll notice how vibrant the colors are, even after all these centuries.","vi":"Quý vị sẽ thấy màu sắc vẫn rực rỡ đến nhường nào, ngay cả sau biết bao thế kỷ trôi qua."},{"en":"This is what the ruins are most famous for.","vi":"Đây chính là điểm nổi tiếng nhất của khu phế tích này."},{"en":"You can still see intricate details in the artists' pictures of scenes from daily life.","vi":"Quý vị vẫn có thể thấy rõ những chi tiết tinh xảo trong các bức tranh của nghệ nhân khắc họa cảnh sinh hoạt đời thường."}]},{"speaker":"W-Br","en":"Now, to protect the mosaics, a roof has been constructed over the area, and the lights are dim. And I'm sorry, but taking photos is not allowed, as the flash would damage the tiles.","vi":"Hiện tại, để bảo vệ các bức tranh khảm, một mái che đã được dựng lên phía trên khu vực này và ánh đèn cũng được giữ ở mức dịu nhẹ. Và tôi rất tiếc, nhưng quý vị không được phép chụp ảnh vì ánh đèn flash sẽ làm hư hại các viên gạch khảm.","units":[{"en":"Now, to protect the mosaics, a roof has been constructed over the area, and the lights are dim.","vi":"Hiện tại, để bảo vệ các bức tranh khảm, một mái che đã được dựng lên phía trên khu vực này và ánh đèn cũng được giữ ở mức dịu nhẹ."},{"en":"And I'm sorry, but taking photos is not allowed, as the flash would damage the tiles.","vi":"Và tôi rất tiếc, nhưng quý vị không được phép chụp ảnh vì ánh đèn flash sẽ làm hư hại các viên gạch khảm."}]},{"speaker":"W-Br","en":"As we proceed, please hold on to the handrails on either side. They'll help you stay on the path and protect the ruins around us.","vi":"Khi chúng ta tiếp tục di chuyển, xin quý vị vui lòng vịn vào tay vịn ở hai bên. Chúng sẽ giúp quý vị đi đúng lối đi và bảo vệ khu tàn tích xung quanh chúng ta.","units":[{"en":"As we proceed, please hold on to the handrails on either side.","vi":"Khi chúng ta tiếp tục di chuyển, xin quý vị vui lòng vịn vào tay vịn ở hai bên."},{"en":"They'll help you stay on the path and protect the ruins around us.","vi":"Chúng sẽ giúp quý vị đi đúng lối đi và bảo vệ khu tàn tích xung quanh chúng ta."}]}],"vocab":[{"word":"proceed","pos":"v","ipa":"/prəˈsiːd/","meaning":"tiếp tục di chuyển, tiến hành"},{"word":"hold on to","pos":"phr. v","ipa":"/hoʊld ɑːn tuː/","meaning":"vịn vào, nắm chặt"},{"word":"handrail","pos":"n","ipa":"/ˈhændreɪl/","meaning":"tay vịn, lan can"},{"word":"ruins","pos":"n","ipa":"/ˈruːɪnz/","meaning":"khu phế tích, tàn tích"}],"isScanBacked":false,"grammarType":"Part 4 — Hành động tiếp theo & Đề xuất (Next Step & Offer/Request)","formula":"CÔNG THỨC PART 4 (Yêu cầu & Mệnh lệnh lịch sự): Nghe cụm cầu khiến cuối bài nói ('As we proceed, please + V...') -> Paraphrase động từ 'hold on to the handrails' thành 'Use some handrails'.","optionAnalysis":{"A":"Sai yêu cầu: bài nói chỉ hướng dẫn cách di chuyển an toàn trên lối đi, không nhắc khách xuất trình vé tham quan.","B":"Bẫy từ khóa 'protect': bài nói nhắc việc bảo vệ gạch khảm và tàn tích xung quanh, không yêu cầu người nghe mặc trang phục bảo hộ.","C":"Đáp án đúng: lời đề nghị 'please hold on to the handrails on either side' được diễn đạt lại thành 'Use some handrails'.","D":"Suy diễn vô căn cứ: không có lời nhắc nào về việc giữ im lặng hay nói nhỏ nhẹ khi tham quan khu di tích."},"evDocIdx":0,"evTargets":[{"badge":"Câu 88 · Đáp án C","opt":"C","isCorrect":true,"quote":"As we proceed, please hold on to the handrails on either side.","viQuote":"Khi chúng ta tiếp tục di chuyển, xin quý vị vui lòng vịn vào tay vịn ở hai bên."}],"evQuotes":["As we proceed, please hold on to the handrails on either side."]},{"q":89,"part":4,"group_id":"E25_T01_G89_91","audio":"web_assets/ets2025/audio/E25_T01/track_51.mp3","graphicImg":null,"transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_25.webp","web_assets/ets2025/tr/E25_T01_tr_26.webp"],"stem_en":"What is the speaker mainly discussing?","stem_vi":"Người nói chủ yếu đang thảo luận về vấn đề gì?","options":{"A":{"en":"An advertising campaign","vi":"Một chiến dịch quảng cáo"},"B":{"en":"A market expansion","vi":"Việc mở rộng thị trường"},"C":{"en":"Some contract negotiations","vi":"Một số cuộc đàm phán hợp đồng"},"D":{"en":"Some audit procedures","vi":"Một số quy trình kiểm toán"}},"ans":"A","explanation":"Đáp án đúng: (A) Một chiến dịch quảng cáo — Người nói chủ trì cuộc họp triển khai kế hoạch sản xuất chuỗi các đoạn quảng cáo phát thanh (hai đoạn 30 giây tháng tới và hai đoạn 20 giây tháng kế tiếp) cho hãng Parker Auto Parts.\nDẫn chứng: \"We'll be developing two 30-second ads for local radio stations to be released next month and two additional 20-second ads for the following month.\" (Chuỗi các mẫu quảng cáo phát thanh -> An advertising campaign).\nPhân tích bẫy:\n- (B) Sai chủ đề cuộc họp: bài nói bàn về lịch phát hành các mẫu quảng cáo cho một khách hàng cụ thể, không nhắc đến kế hoạch mở rộng thị trường.\n- (C) Bẫy từ khóa 'contract': công ty đã giành được hợp đồng rồi ('just won an important contract'), không phải đang thảo luận về các cuộc đàm phán hợp đồng.\n- (D) Sai lĩnh vực chuyên môn: đây là cuộc họp của công ty quảng cáo (agency) chỉnh sửa bản nháp quảng cáo, không liên quan đến quy trình kiểm toán (audit).","lines":[{"speaker":"M-Cn (Trích đoạn cuộc họp)","en":"As you all know, our agency's just won an important contract with Parker Auto Parts Company. We'll be developing two 30-second ads for local radio stations to be released next month and two additional 20-second ads for the following month.","vi":"Như mọi người đều biết, công ty quảng cáo của chúng ta vừa giành được một hợp đồng quan trọng với Công ty Parker Auto Parts. Chúng ta sẽ xây dựng hai đoạn quảng cáo dài 30 giây cho các đài phát thanh địa phương để phát sóng vào tháng tới và thêm hai đoạn quảng cáo dài 20 giây cho tháng kế tiếp.","units":[{"en":"As you all know, our agency's just won an important contract with Parker Auto Parts Company.","vi":"Như mọi người đều biết, công ty quảng cáo của chúng ta vừa giành được một hợp đồng quan trọng với Công ty Parker Auto Parts."},{"en":"We'll be developing two 30-second ads for local radio stations to be released next month and two additional 20-second ads for the following month.","vi":"Chúng ta sẽ xây dựng hai đoạn quảng cáo dài 30 giây cho các đài phát thanh địa phương để phát sóng vào tháng tới và thêm hai đoạn quảng cáo dài 20 giây cho tháng kế tiếp."}]},{"speaker":"M-Cn","en":"Now, I know it's a tight schedule, but this is a priority.","vi":"Tôi biết lịch trình khá gấp gáp, nhưng đây là nhiệm vụ ưu tiên hàng đầu.","units":[{"en":"Now, I know it's a tight schedule, but this is a priority.","vi":"Tôi biết lịch trình khá gấp gáp, nhưng đây là nhiệm vụ ưu tiên hàng đầu."}]},{"speaker":"M-Cn","en":"The client has actually started trying to work on this internally, so there's a rough ad we can start editing. Let's work on that now.","vi":"Thực ra khách hàng đã bắt đầu thử tự triển khai nội bộ, nên hiện có sẵn một bản quảng cáo nháp để chúng ta bắt tay vào biên tập. Hãy cùng bắt tay vào xử lý bản nháp đó ngay bây giờ nhé.","units":[{"en":"The client has actually started trying to work on this internally, so there's a rough ad we can start editing.","vi":"Thực ra khách hàng đã bắt đầu thử tự triển khai nội bộ, nên hiện có sẵn một bản quảng cáo nháp để chúng ta bắt tay vào biên tập."},{"en":"Let's work on that now.","vi":"Hãy cùng bắt tay vào xử lý bản nháp đó ngay bây giờ nhé."}]}],"vocab":[{"word":"agency","pos":"n","ipa":"/ˈeɪdʒənsi/","meaning":"công ty dịch vụ, công ty quảng cáo"},{"word":"contract","pos":"n","ipa":"/ˈkɑːntrækt/","meaning":"hợp đồng"},{"word":"release","pos":"v","ipa":"/rɪˈliːs/","meaning":"phát hành, phát sóng"},{"word":"campaign","pos":"n","ipa":"/kæmˈpeɪn/","meaning":"chiến dịch (quảng cáo)"}],"isScanBacked":false,"grammarType":"Part 4 — Ý chính & Mục đích (Gist & Purpose)","formula":"CÔNG THỨC PART 4 (Chủ đề chính bài nói): Nắm câu mở đầu giới thiệu bối cảnh ('our agency's just won a contract... developing ads') -> Tổng hợp nội dung xuyên suốt để chọn 'An advertising campaign'.","optionAnalysis":{"A":"Đáp án đúng: toàn bộ cuộc họp xoay quanh kế hoạch sản xuất và biên tập chuỗi quảng cáo phát thanh cho Parker Auto Parts.","B":"Không khớp nội dung: không có thông tin nào bàn về mở rộng thị trường mới hay kế hoạch phát triển kinh doanh của công ty.","C":"Bẫy từ 'contract': hợp đồng đã được ký thành công ('just won an important contract'), hiện tại nhóm bắt tay làm sản phẩm chứ không đàm phán.","D":"Sai ngữ cảnh chuyên môn (bẫy gần âm auto/ads với audit): công ty quảng cáo đang xử lý mẫu phát thanh, không thực hiện kiểm toán."},"evDocIdx":0,"evTargets":[{"badge":"Câu 89 · Đáp án A","opt":"A","isCorrect":true,"quote":"We'll be developing two 30-second ads for local radio stations to be released next month and two additional 20-second ads for the following month.","viQuote":"Chúng ta sẽ xây dựng hai đoạn quảng cáo dài 30 giây cho các đài phát thanh địa phương để phát sóng vào tháng tới và thêm hai đoạn quảng cáo dài 20 giây cho tháng kế tiếp."}],"evQuotes":["We'll be developing two 30-second ads for local radio stations to be released next month and two additional 20-second ads for the following month."]},{"q":90,"part":4,"group_id":"E25_T01_G89_91","audio":"web_assets/ets2025/audio/E25_T01/track_51.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the speaker imply when he says, \"this is a priority\"?","stem_vi":"Người nói ngụ ý gì khi nói \"this is a priority\"?","options":{"A":{"en":"Overtime pay has been approved.","vi":"Tiền làm thêm giờ đã được phê duyệt."},"B":{"en":"A deadline must be met.","vi":"Phải hoàn thành đúng thời hạn."},"C":{"en":"A client expressed concern.","vi":"Một khách hàng đã bày tỏ sự lo ngại."},"D":{"en":"A supervisor will be observing closely.","vi":"Người giám sát sẽ theo dõi sát sao."}},"ans":"B","explanation":"Đáp án đúng: (B) Phải hoàn thành đúng thời hạn — Khi thừa nhận lịch trình rất gấp nhưng nhấn mạnh đây là nhiệm vụ ưu tiên, người nói ngụ ý cả nhóm bắt buộc phải hoàn thành kịp mốc phát sóng tháng tới.\nDẫn chứng: \"...to be released next month... Now, I know it's a tight schedule, but this is a priority.\" (Lịch trình gấp + ưu tiên hàng đầu -> không thể trễ hạn / A deadline must be met).\nPhân tích bẫy:\n- (A) Suy diễn quá mức từ 'tight schedule': người nói không hề đề cập đến vấn đề lương thưởng hay việc phê duyệt làm thêm giờ.\n- (C) Bóp méo chi tiết về khách hàng: khách hàng đã chủ động thử tự làm một bản nháp nội bộ (started trying to work on this internally), không phải bày tỏ sự lo ngại.\n- (D) Suy diễn ngoài ngữ cảnh: cuộc họp không nhắc tới việc có giám sát viên đứng quan sát hay kiểm tra sát sao tiến độ.","lines":[{"speaker":"M-Cn (Trích đoạn cuộc họp)","en":"As you all know, our agency's just won an important contract with Parker Auto Parts Company. We'll be developing two 30-second ads for local radio stations to be released next month and two additional 20-second ads for the following month.","vi":"Như mọi người đều biết, công ty quảng cáo của chúng ta vừa giành được một hợp đồng quan trọng với Công ty Parker Auto Parts. Chúng ta sẽ xây dựng hai đoạn quảng cáo dài 30 giây cho các đài phát thanh địa phương để phát sóng vào tháng tới và thêm hai đoạn quảng cáo dài 20 giây cho tháng kế tiếp.","units":[{"en":"As you all know, our agency's just won an important contract with Parker Auto Parts Company.","vi":"Như mọi người đều biết, công ty quảng cáo của chúng ta vừa giành được một hợp đồng quan trọng với Công ty Parker Auto Parts."},{"en":"We'll be developing two 30-second ads for local radio stations to be released next month and two additional 20-second ads for the following month.","vi":"Chúng ta sẽ xây dựng hai đoạn quảng cáo dài 30 giây cho các đài phát thanh địa phương để phát sóng vào tháng tới và thêm hai đoạn quảng cáo dài 20 giây cho tháng kế tiếp."}]},{"speaker":"M-Cn","en":"Now, I know it's a tight schedule, but this is a priority.","vi":"Tôi biết lịch trình khá gấp gáp, nhưng đây là nhiệm vụ ưu tiên hàng đầu.","units":[{"en":"Now, I know it's a tight schedule, but this is a priority.","vi":"Tôi biết lịch trình khá gấp gáp, nhưng đây là nhiệm vụ ưu tiên hàng đầu."}]},{"speaker":"M-Cn","en":"The client has actually started trying to work on this internally, so there's a rough ad we can start editing. Let's work on that now.","vi":"Thực ra khách hàng đã bắt đầu thử tự triển khai nội bộ, nên hiện có sẵn một bản quảng cáo nháp để chúng ta bắt tay vào biên tập. Hãy cùng bắt tay vào xử lý bản nháp đó ngay bây giờ nhé.","units":[{"en":"The client has actually started trying to work on this internally, so there's a rough ad we can start editing.","vi":"Thực ra khách hàng đã bắt đầu thử tự triển khai nội bộ, nên hiện có sẵn một bản quảng cáo nháp để chúng ta bắt tay vào biên tập."},{"en":"Let's work on that now.","vi":"Hãy cùng bắt tay vào xử lý bản nháp đó ngay bây giờ nhé."}]}],"vocab":[{"word":"tight schedule","pos":"phr","ipa":"/taɪt ˈskedʒuːl/","meaning":"lịch trình gấp gáp, eo hẹp"},{"word":"priority","pos":"n","ipa":"/praɪˈɔːrəti/","meaning":"việc ưu tiên hàng đầu"},{"word":"deadline","pos":"n","ipa":"/ˈdedlaɪn/","meaning":"hạn chót"},{"word":"additional","pos":"adj","ipa":"/əˈdɪʃənəl/","meaning":"bổ sung, thêm vào"}],"isScanBacked":false,"grammarType":"Part 4 — Câu hỏi hàm ý (Speaker Intent / Implied Meaning)","formula":"CÔNG THỨC PART 4 (Câu hỏi hàm ý — Trích dẫn): Đọc câu ngay trước câu trích dẫn ('I know it's a tight schedule, but...') + mốc thời gian 'next month' -> Suy ra hàm ý phải chạy kịp tiến độ ('A deadline must be met').","optionAnalysis":{"A":"Suy diễn không có cơ sở: người nói nhắc lịch trình gấp nhưng hoàn toàn không đề cập đến tiền làm thêm giờ hay chính sách nhân sự.","B":"Đáp án đúng: đặt câu 'this is a priority' ngay sau 'it's a tight schedule' và mốc phát hành tháng tới ngụ ý phải đảm bảo đúng hạn chót.","C":"Hiểu sai chi tiết khách hàng: khách hàng chỉ tự dựng sẵn một bản quảng cáo nháp chứ không hề phàn nàn hay bày tỏ lo lắng.","D":"Thông tin bịa thêm: không có chi tiết nào về người giám sát theo dõi sát sao quá trình chỉnh sửa bản quảng cáo."},"evDocIdx":0,"evTargets":[{"badge":"Câu 90 · Đáp án B","opt":"B","isCorrect":true,"quote":"We'll be developing two 30-second ads for local radio stations to be released next month and two additional 20-second ads for the following month.","viQuote":"Chúng ta sẽ xây dựng hai đoạn quảng cáo dài 30 giây cho các đài phát thanh địa phương để phát sóng vào tháng tới và thêm hai đoạn quảng cáo dài 20 giây cho tháng kế tiếp."},{"badge":"Câu 90 · Đáp án B","opt":"B","isCorrect":true,"quote":"Now, I know it's a tight schedule, but this is a priority.","viQuote":"Tôi biết lịch trình khá gấp gáp, nhưng đây là nhiệm vụ ưu tiên hàng đầu."}],"evQuotes":["We'll be developing two 30-second ads for local radio stations to be released next month and two additional 20-second ads for the following month.","Now, I know it's a tight schedule, but this is a priority."]},{"q":91,"part":4,"group_id":"E25_T01_G89_91","audio":"web_assets/ets2025/audio/E25_T01/track_51.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What will the listeners do next?","stem_vi":"Người nghe sẽ làm gì tiếp theo?","options":{"A":{"en":"View a presentation","vi":"Xem một bài thuyết trình"},"B":{"en":"Review a budget","vi":"Xem xét ngân sách"},"C":{"en":"Revise some work","vi":"Chỉnh sửa một số nội dung công việc"},"D":{"en":"Do some research","vi":"Thực hiện một số nghiên cứu"}},"ans":"C","explanation":"Đáp án đúng: (C) Chỉnh sửa một số nội dung công việc — Ngay cuối lượt lời, người nói cho biết khách hàng đã có sẵn một bản quảng cáo nháp để biên tập và kêu gọi cả nhóm bắt tay xử lý bản đó ngay.\nDẫn chứng: \"The client has actually started trying to work on this internally, so there's a rough ad we can start editing. Let's work on that now.\" (Paraphrase: start editing a rough ad -> Revise some work).\nPhân tích bẫy:\n- (A) Sai hành động tiếp theo: cả nhóm sẽ trực tiếp chỉnh sửa bản nháp quảng cáo chứ không ngồi xem một bài thuyết trình.\n- (B) Thông tin vắng mặt trong bài: người nói chỉ bàn về thời lượng đoạn quảng cáo và lịch trình, không nhắc đến ngân sách.\n- (D) Sai trình tự công việc: nhóm không cần làm nghiên cứu thị trường từ đầu vì đã có sẵn bản nháp nội bộ của khách hàng để biên tập.","lines":[{"speaker":"M-Cn (Trích đoạn cuộc họp)","en":"As you all know, our agency's just won an important contract with Parker Auto Parts Company. We'll be developing two 30-second ads for local radio stations to be released next month and two additional 20-second ads for the following month.","vi":"Như mọi người đều biết, công ty quảng cáo của chúng ta vừa giành được một hợp đồng quan trọng với Công ty Parker Auto Parts. Chúng ta sẽ xây dựng hai đoạn quảng cáo dài 30 giây cho các đài phát thanh địa phương để phát sóng vào tháng tới và thêm hai đoạn quảng cáo dài 20 giây cho tháng kế tiếp.","units":[{"en":"As you all know, our agency's just won an important contract with Parker Auto Parts Company.","vi":"Như mọi người đều biết, công ty quảng cáo của chúng ta vừa giành được một hợp đồng quan trọng với Công ty Parker Auto Parts."},{"en":"We'll be developing two 30-second ads for local radio stations to be released next month and two additional 20-second ads for the following month.","vi":"Chúng ta sẽ xây dựng hai đoạn quảng cáo dài 30 giây cho các đài phát thanh địa phương để phát sóng vào tháng tới và thêm hai đoạn quảng cáo dài 20 giây cho tháng kế tiếp."}]},{"speaker":"M-Cn","en":"Now, I know it's a tight schedule, but this is a priority.","vi":"Tôi biết lịch trình khá gấp gáp, nhưng đây là nhiệm vụ ưu tiên hàng đầu.","units":[{"en":"Now, I know it's a tight schedule, but this is a priority.","vi":"Tôi biết lịch trình khá gấp gáp, nhưng đây là nhiệm vụ ưu tiên hàng đầu."}]},{"speaker":"M-Cn","en":"The client has actually started trying to work on this internally, so there's a rough ad we can start editing. Let's work on that now.","vi":"Thực ra khách hàng đã bắt đầu thử tự triển khai nội bộ, nên hiện có sẵn một bản quảng cáo nháp để chúng ta bắt tay vào biên tập. Hãy cùng bắt tay vào xử lý bản nháp đó ngay bây giờ nhé.","units":[{"en":"The client has actually started trying to work on this internally, so there's a rough ad we can start editing.","vi":"Thực ra khách hàng đã bắt đầu thử tự triển khai nội bộ, nên hiện có sẵn một bản quảng cáo nháp để chúng ta bắt tay vào biên tập."},{"en":"Let's work on that now.","vi":"Hãy cùng bắt tay vào xử lý bản nháp đó ngay bây giờ nhé."}]}],"vocab":[{"word":"internally","pos":"adv","ipa":"/ɪnˈtɜːrnəli/","meaning":"trong nội bộ"},{"word":"rough","pos":"adj","ipa":"/rʌf/","meaning":"sơ bộ, bản nháp"},{"word":"edit","pos":"v","ipa":"/ˈedɪt/","meaning":"biên tập, chỉnh sửa"},{"word":"revise","pos":"v","ipa":"/rɪˈvaɪz/","meaning":"chỉnh sửa, rà soát lại"}],"isScanBacked":false,"grammarType":"Part 4 — Hành động tiếp theo & Đề xuất (Next Step & Offer/Request)","formula":"CÔNG THỨC PART 4 (Hành động tiếp theo): Bắt tín hiệu kết bài ('Let's work on that now') và tìm tiền ngữ của 'that' ở câu ngay trước ('a rough ad we can start editing') -> Chọn 'Revise some work'.","optionAnalysis":{"A":"Sai hoạt động tiếp theo: người nói mời cả nhóm biên tập ngay bản nháp, không phải xem bài thuyết trình.","B":"Không được đề cập: nội dung cuộc họp chỉ tập trung vào sản xuất các đoạn radio 20-30 giây, không đề cập đến ngân sách.","C":"Đáp án đúng: 'start editing [a rough ad]' kết hợp với 'Let's work on that now' đồng nghĩa trực tiếp với 'Revise some work'.","D":"Không đúng với chỉ dẫn cuối bài: không có yêu cầu tiến hành nghiên cứu vì bản nháp quảng cáo đã có sẵn để chỉnh sửa."},"evDocIdx":0,"evTargets":[{"badge":"Câu 91 · Đáp án C","opt":"C","isCorrect":true,"quote":"The client has actually started trying to work on this internally, so there's a rough ad we can start editing.","viQuote":"Thực ra khách hàng đã bắt đầu thử tự triển khai nội bộ, nên hiện có sẵn một bản quảng cáo nháp để chúng ta bắt tay vào biên tập."},{"badge":"Câu 91 · Đáp án C","opt":"C","isCorrect":true,"quote":"Let's work on that now.","viQuote":"Hãy cùng bắt tay vào xử lý bản nháp đó ngay bây giờ nhé."}],"evQuotes":["The client has actually started trying to work on this internally, so there's a rough ad we can start editing.","Let's work on that now."]},{"q":92,"part":4,"group_id":"E25_T01_G92_94","audio":"web_assets/ets2025/audio/E25_T01/track_52.mp3","graphicImg":null,"transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_26.webp","web_assets/ets2025/tr/E25_T01_tr_27.webp"],"stem_en":"Where do the listeners most likely work?","stem_vi":"Người nghe có khả năng làm việc ở đâu nhất?","options":{"A":{"en":"At a hospital","vi":"Tại một bệnh viện"},"B":{"en":"At a restaurant","vi":"Tại một nhà hàng"},"C":{"en":"At a grocery store","vi":"Tại một cửa hàng tạp hóa"},"D":{"en":"At an electronics store","vi":"Tại một cửa hàng điện tử"}},"ans":"A","explanation":"Đáp án đúng: (A) Tại một bệnh viện — Người nói gọi thẳng đối tượng nghe là các điều dưỡng ('nurses') và nhắc trực tiếp tới phòng nghỉ cũng như căng tin của bệnh viện.\nDẫn chứng: \"Excuse me, nurses. Your attention please. I've been receiving complaints about the free snacks in the hospital break rooms.\" (Từ khóa trực tiếp: nurses, hospital break rooms, hospital cafeteria -> At a hospital).\nPhân tích bẫy:\n- (B) Bẫy liên tưởng từ 'snacks' và 'cafeteria': đồ ăn nhẹ và căng tin là khu vực phục vụ nhân viên bên trong bệnh viện, không phải nơi làm việc là nhà hàng.\n- (C) Bẫy liên tưởng từ 'buy the snacks you want': nhân viên tự mua đồ ăn vặt tại căng tin bệnh viện bằng tài khoản chi tiêu, không làm việc ở cửa hàng tạp hóa.\n- (D) Sai hoàn toàn ngành nghề: danh xưng 'nurses' (điều dưỡng) và bối cảnh chia ca tại bệnh viện không liên quan đến cửa hàng điện tử.","lines":[{"speaker":"W-Am (Trích đoạn cuộc họp)","en":"Excuse me, nurses. Your attention please. I've been receiving complaints about the free snacks in the hospital break rooms.","vi":"Xin phép các anh chị điều dưỡng. Xin mọi người vui lòng chú ý. Thời gian gần đây tôi đã nhận được nhiều phản ánh về đồ ăn nhẹ miễn phí trong các phòng nghỉ của bệnh viện.","units":[{"en":"Excuse me, nurses.","vi":"Xin phép các anh chị điều dưỡng."},{"en":"Your attention please.","vi":"Xin mọi người vui lòng chú ý."},{"en":"I've been receiving complaints about the free snacks in the hospital break rooms.","vi":"Thời gian gần đây tôi đã nhận được nhiều phản ánh về đồ ăn nhẹ miễn phí trong các phòng nghỉ của bệnh viện."}]},{"speaker":"W-Am","en":"Some people have mentioned that they don't like the selection of snacks, and some have said that they don't get to eat them at all because they're gone by the time the evening shift starts.","vi":"Một số người cho biết họ không thích các lựa chọn đồ ăn nhẹ hiện có, và một số khác nói rằng họ chẳng kịp ăn chút nào vì đồ ăn đã hết sạch trước khi ca tối bắt đầu.","units":[{"en":"Some people have mentioned that they don't like the selection of snacks, and some have said that they don't get to eat them at all because they're gone by the time the evening shift starts.","vi":"Một số người cho biết họ không thích các lựa chọn đồ ăn nhẹ hiện có, và một số khác nói rằng họ chẳng kịp ăn chút nào vì đồ ăn đã hết sạch trước khi ca tối bắt đầu."}]},{"speaker":"W-Am","en":"So I was thinking about putting some money into each of your staff spending accounts every month so that you can buy the snacks you want at the hospital cafeteria. That will require management approval, but I'll keep you posted.","vi":"Vì vậy, tôi đang cân nhắc nạp một khoản tiền vào tài khoản chi tiêu nhân viên của mỗi người hằng tháng để mọi người có thể tự mua đồ ăn nhẹ mình thích tại căng tin bệnh viện. Phương án đó sẽ cần sự phê duyệt của ban lãnh đạo, nhưng tôi sẽ cập nhật thông tin cho mọi người.","units":[{"en":"So I was thinking about putting some money into each of your staff spending accounts every month so that you can buy the snacks you want at the hospital cafeteria.","vi":"Vì vậy, tôi đang cân nhắc nạp một khoản tiền vào tài khoản chi tiêu nhân viên của mỗi người hằng tháng để mọi người có thể tự mua đồ ăn nhẹ mình thích tại căng tin bệnh viện."},{"en":"That will require management approval, but I'll keep you posted.","vi":"Phương án đó sẽ cần sự phê duyệt của ban lãnh đạo, nhưng tôi sẽ cập nhật thông tin cho mọi người."}]}],"vocab":[{"word":"complaint","pos":"n","ipa":"/kəmˈpleɪnt/","meaning":"lời phàn nàn, phản ánh"},{"word":"break room","pos":"n","ipa":"/breɪk ruːm/","meaning":"phòng nghỉ nhân viên"},{"word":"shift","pos":"n","ipa":"/ʃɪft/","meaning":"ca làm việc"},{"word":"cafeteria","pos":"n","ipa":"/ˌkæfəˈtɪriə/","meaning":"căng tin, nhà ăn tự phục vụ"}],"isScanBacked":false,"grammarType":"Part 4 — Ngữ cảnh, Địa điểm & Danh tính người nói (Setting & Role)","formula":"CÔNG THỨC PART 4 (Địa điểm & Đối tượng nghe): Xác định danh xưng mở đầu ('Excuse me, nurses') + từ khóa lặp lại về cơ sở vật chất ('hospital break rooms', 'hospital cafeteria') -> Chốt ngay 'At a hospital'.","optionAnalysis":{"A":"Đáp án đúng: bài nói gọi trực tiếp 'nurses' và nhắc hai lần địa điểm 'hospital break rooms' và 'hospital cafeteria'.","B":"Bẫy liên tưởng ngữ cảnh: dù nhắc đến đồ ăn nhẹ và căng tin, đây chỉ là tiện ích cho nhân viên bệnh viện chứ họ không làm việc ở nhà hàng.","C":"Bẫy cụm từ 'buy the snacks': việc nhân viên dùng tiền trợ cấp mua đồ ăn tại căng tin không đồng nghĩa họ làm việc ở tiệm tạp hóa.","D":"Sai hoàn toàn bối cảnh y tế: đối tượng nghe là các điều dưỡng tại bệnh viện, không có bất kỳ liên hệ nào với cửa hàng điện tử."},"evDocIdx":0,"evTargets":[{"badge":"Câu 92 · Đáp án A","opt":"A","isCorrect":true,"quote":"Excuse me, nurses.","viQuote":"Xin phép các anh chị điều dưỡng."},{"badge":"Câu 92 · Đáp án A","opt":"A","isCorrect":true,"quote":"I've been receiving complaints about the free snacks in the hospital break rooms.","viQuote":"Thời gian gần đây tôi đã nhận được nhiều phản ánh về đồ ăn nhẹ miễn phí trong các phòng nghỉ của bệnh viện."}],"evQuotes":["Excuse me, nurses.","I've been receiving complaints about the free snacks in the hospital break rooms."]},{"q":93,"part":4,"group_id":"E25_T01_G92_94","audio":"web_assets/ets2025/audio/E25_T01/track_52.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What is the main purpose of the talk?","stem_vi":"Mục đích chính của bài nói là gì?","options":{"A":{"en":"To make a request","vi":"Để đưa ra một yêu cầu"},"B":{"en":"To address staff complaints","vi":"Để giải quyết những phản ánh của nhân viên"},"C":{"en":"To present a new schedule","vi":"Để trình bày một lịch trình mới"},"D":{"en":"To explain a technical process","vi":"Để giải thích một quy trình kỹ thuật"}},"ans":"B","explanation":"Đáp án đúng: (B) Để giải quyết những phản ánh của nhân viên — Người nói mở đầu bằng việc ghi nhận nhiều lời phàn nàn về đồ ăn nhẹ ở phòng nghỉ rồi nêu phương án nạp tiền hằng tháng vào tài khoản chi tiêu để khắc phục.\nDẫn chứng: \"I've been receiving complaints about the free snacks... So I was thinking about putting some money into each of your staff spending accounts...\" (Tiếp nhận phàn nàn và đưa giải pháp -> To address staff complaints).\nPhân tích bẫy:\n- (A) Sai mục đích chính: người nói thông báo giải pháp phúc lợi chứ không đưa ra yêu cầu công việc nào bắt buộc các điều dưỡng thực hiện.\n- (C) Bẫy nhắc từ 'evening shift': cụm 'by the time the evening shift starts' chỉ dùng để giải thích đồ ăn thường hết trước ca tối, không phải công bố lịch làm việc mới.\n- (D) Sai nội dung chuyên môn: chủ đề buổi nói ngắn là chính sách đồ ăn nhẹ ở phòng nghỉ, hoàn toàn không giải thích quy trình kỹ thuật nào.","lines":[{"speaker":"W-Am (Trích đoạn cuộc họp)","en":"Excuse me, nurses. Your attention please. I've been receiving complaints about the free snacks in the hospital break rooms.","vi":"Xin phép các anh chị điều dưỡng. Xin mọi người vui lòng chú ý. Thời gian gần đây tôi đã nhận được nhiều phản ánh về đồ ăn nhẹ miễn phí trong các phòng nghỉ của bệnh viện.","units":[{"en":"Excuse me, nurses.","vi":"Xin phép các anh chị điều dưỡng."},{"en":"Your attention please.","vi":"Xin mọi người vui lòng chú ý."},{"en":"I've been receiving complaints about the free snacks in the hospital break rooms.","vi":"Thời gian gần đây tôi đã nhận được nhiều phản ánh về đồ ăn nhẹ miễn phí trong các phòng nghỉ của bệnh viện."}]},{"speaker":"W-Am","en":"Some people have mentioned that they don't like the selection of snacks, and some have said that they don't get to eat them at all because they're gone by the time the evening shift starts.","vi":"Một số người cho biết họ không thích các lựa chọn đồ ăn nhẹ hiện có, và một số khác nói rằng họ chẳng kịp ăn chút nào vì đồ ăn đã hết sạch trước khi ca tối bắt đầu.","units":[{"en":"Some people have mentioned that they don't like the selection of snacks, and some have said that they don't get to eat them at all because they're gone by the time the evening shift starts.","vi":"Một số người cho biết họ không thích các lựa chọn đồ ăn nhẹ hiện có, và một số khác nói rằng họ chẳng kịp ăn chút nào vì đồ ăn đã hết sạch trước khi ca tối bắt đầu."}]},{"speaker":"W-Am","en":"So I was thinking about putting some money into each of your staff spending accounts every month so that you can buy the snacks you want at the hospital cafeteria. That will require management approval, but I'll keep you posted.","vi":"Vì vậy, tôi đang cân nhắc nạp một khoản tiền vào tài khoản chi tiêu nhân viên của mỗi người hằng tháng để mọi người có thể tự mua đồ ăn nhẹ mình thích tại căng tin bệnh viện. Phương án đó sẽ cần sự phê duyệt của ban lãnh đạo, nhưng tôi sẽ cập nhật thông tin cho mọi người.","units":[{"en":"So I was thinking about putting some money into each of your staff spending accounts every month so that you can buy the snacks you want at the hospital cafeteria.","vi":"Vì vậy, tôi đang cân nhắc nạp một khoản tiền vào tài khoản chi tiêu nhân viên của mỗi người hằng tháng để mọi người có thể tự mua đồ ăn nhẹ mình thích tại căng tin bệnh viện."},{"en":"That will require management approval, but I'll keep you posted.","vi":"Phương án đó sẽ cần sự phê duyệt của ban lãnh đạo, nhưng tôi sẽ cập nhật thông tin cho mọi người."}]}],"vocab":[{"word":"selection","pos":"n","ipa":"/səˈlekʃən/","meaning":"danh mục lựa chọn, các món có sẵn"},{"word":"spending account","pos":"n","ipa":"/ˈspendɪŋ əˈkaʊnt/","meaning":"tài khoản chi tiêu"},{"word":"address","pos":"v","ipa":"/əˈdres/","meaning":"giải quyết, xử lý (vấn đề)"},{"word":"mention","pos":"v","ipa":"/ˈmenʃən/","meaning":"đề cập, nhắc tới"}],"isScanBacked":false,"grammarType":"Part 4 — Ý chính & Mục đích (Gist & Purpose)","formula":"CÔNG THỨC PART 4 (Mục đích bài nói): Xác định cặp Vấn đề - Giải pháp ('I've been receiving complaints...' + 'So I was thinking about...') -> Quy đổi về mục đích 'To address staff complaints'.","optionAnalysis":{"A":"Sai mục đích: người nói chủ yếu phản hồi ý kiến bức xúc của nhân viên và đề xuất giải pháp mới, không giao nhiệm vụ hay yêu cầu nào.","B":"Đáp án đúng: cấu trúc 'receiving complaints... So I was thinking about...' thể hiện rõ mục đích giải quyết phản ánh của đội ngũ điều dưỡng.","C":"Bẫy từ khóa 'shift': bài nói nhắc 'evening shift' để làm rõ thực trạng hết đồ ăn vào ca tối, không hề trình bày lịch trực mới.","D":"Không khớp chủ đề: bài nói bàn về chế độ đồ ăn nhẹ và tài khoản chi tiêu nhân viên, không phải hướng dẫn quy trình kỹ thuật."},"evDocIdx":0,"evTargets":[{"badge":"Câu 93 · Đáp án B","opt":"B","isCorrect":true,"quote":"I've been receiving complaints about the free snacks in the hospital break rooms.","viQuote":"Thời gian gần đây tôi đã nhận được nhiều phản ánh về đồ ăn nhẹ miễn phí trong các phòng nghỉ của bệnh viện."},{"badge":"Câu 93 · Đáp án B","opt":"B","isCorrect":true,"quote":"So I was thinking about putting some money into each of your staff spending accounts every month so that you can buy the snacks you want at the hospital cafeteria.","viQuote":"Vì vậy, tôi đang cân nhắc nạp một khoản tiền vào tài khoản chi tiêu nhân viên của mỗi người hằng tháng để mọi người có thể tự mua đồ ăn nhẹ mình thích tại căng tin bệnh viện."}],"evQuotes":["I've been receiving complaints about the free snacks in the hospital break rooms.","So I was thinking about putting some money into each of your staff spending accounts every month so that you can buy the snacks you want at the hospital cafeteria."]},{"q":94,"part":4,"group_id":"E25_T01_G92_94","audio":"web_assets/ets2025/audio/E25_T01/track_52.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the speaker imply when she says, \"That will require management approval\"?","stem_vi":"Người nói ngụ ý gì khi nói \"That will require management approval\"?","options":{"A":{"en":"A process has not been followed.","vi":"Một quy trình đã không được tuân thủ."},"B":{"en":"The listeners may be asked to work extra shifts.","vi":"Người nghe có thể sẽ được yêu cầu làm thêm ca."},"C":{"en":"The listeners should contact a manager.","vi":"Người nghe nên liên hệ với người quản lý."},"D":{"en":"A change will not be immediate.","vi":"Sự thay đổi sẽ không diễn ra ngay lập tức."}},"ans":"D","explanation":"Đáp án đúng: (D) Sự thay đổi sẽ không diễn ra ngay lập tức — Vì phương án nạp tiền vào tài khoản chi tiêu mới chỉ là ý tưởng và còn phải chờ ban lãnh đạo phê duyệt rồi mới thông báo lại, nên chưa thể áp dụng ngay.\nDẫn chứng: \"So I was thinking about putting some money into each of your staff spending accounts... That will require management approval, but I'll keep you posted.\" (Còn phải chờ cấp trên duyệt -> thay đổi chưa thể có ngay).\nPhân tích bẫy:\n- (A) Hiểu sai nghĩa 'require approval': việc cần ban lãnh đạo thông qua là bước xét duyệt bình thường cho đề xuất ngân sách mới, không ám chỉ có sai phạm quy trình.\n- (B) Bẫy lặp từ 'shift': từ 'evening shift' xuất hiện ở đoạn phàn nàn thiếu đồ ăn trước đó, không có hàm ý bắt nhân viên làm thêm ca.\n- (C) Bẫy chuyển nhầm người thực hiện: chính người nói cam kết sẽ cập nhật kết quả sau ('I'll keep you posted'), không bảo các điều dưỡng tự liên hệ quản lý.","lines":[{"speaker":"W-Am (Trích đoạn cuộc họp)","en":"Excuse me, nurses. Your attention please. I've been receiving complaints about the free snacks in the hospital break rooms.","vi":"Xin phép các anh chị điều dưỡng. Xin mọi người vui lòng chú ý. Thời gian gần đây tôi đã nhận được nhiều phản ánh về đồ ăn nhẹ miễn phí trong các phòng nghỉ của bệnh viện.","units":[{"en":"Excuse me, nurses.","vi":"Xin phép các anh chị điều dưỡng."},{"en":"Your attention please.","vi":"Xin mọi người vui lòng chú ý."},{"en":"I've been receiving complaints about the free snacks in the hospital break rooms.","vi":"Thời gian gần đây tôi đã nhận được nhiều phản ánh về đồ ăn nhẹ miễn phí trong các phòng nghỉ của bệnh viện."}]},{"speaker":"W-Am","en":"Some people have mentioned that they don't like the selection of snacks, and some have said that they don't get to eat them at all because they're gone by the time the evening shift starts.","vi":"Một số người cho biết họ không thích các lựa chọn đồ ăn nhẹ hiện có, và một số khác nói rằng họ chẳng kịp ăn chút nào vì đồ ăn đã hết sạch trước khi ca tối bắt đầu.","units":[{"en":"Some people have mentioned that they don't like the selection of snacks, and some have said that they don't get to eat them at all because they're gone by the time the evening shift starts.","vi":"Một số người cho biết họ không thích các lựa chọn đồ ăn nhẹ hiện có, và một số khác nói rằng họ chẳng kịp ăn chút nào vì đồ ăn đã hết sạch trước khi ca tối bắt đầu."}]},{"speaker":"W-Am","en":"So I was thinking about putting some money into each of your staff spending accounts every month so that you can buy the snacks you want at the hospital cafeteria. That will require management approval, but I'll keep you posted.","vi":"Vì vậy, tôi đang cân nhắc nạp một khoản tiền vào tài khoản chi tiêu nhân viên của mỗi người hằng tháng để mọi người có thể tự mua đồ ăn nhẹ mình thích tại căng tin bệnh viện. Phương án đó sẽ cần sự phê duyệt của ban lãnh đạo, nhưng tôi sẽ cập nhật thông tin cho mọi người.","units":[{"en":"So I was thinking about putting some money into each of your staff spending accounts every month so that you can buy the snacks you want at the hospital cafeteria.","vi":"Vì vậy, tôi đang cân nhắc nạp một khoản tiền vào tài khoản chi tiêu nhân viên của mỗi người hằng tháng để mọi người có thể tự mua đồ ăn nhẹ mình thích tại căng tin bệnh viện."},{"en":"That will require management approval, but I'll keep you posted.","vi":"Phương án đó sẽ cần sự phê duyệt của ban lãnh đạo, nhưng tôi sẽ cập nhật thông tin cho mọi người."}]}],"vocab":[{"word":"require","pos":"v","ipa":"/rɪˈkwaɪər/","meaning":"đòi hỏi, yêu cầu"},{"word":"approval","pos":"n","ipa":"/əˈpruːvəl/","meaning":"sự phê duyệt, chấp thuận"},{"word":"keep someone posted","pos":"phr","ipa":"/kiːp ˈsʌmwʌn ˈpoʊstɪd/","meaning":"cập nhật thông tin thường xuyên cho ai"},{"word":"immediate","pos":"adj","ipa":"/ɪˈmiːdiət/","meaning":"ngay lập tức"}],"isScanBacked":false,"grammarType":"Part 4 — Câu hỏi hàm ý (Speaker Intent / Implied Meaning)","formula":"CÔNG THỨC PART 4 (Câu hỏi hàm ý — Trích dẫn): Xâu chuỗi cụm phỏng đoán ('I was thinking about') + điều kiện phê duyệt ('require management approval') + lời hẹn ('keep you posted') -> Chưa thể áp dụng ngay ('A change will not be immediate').","optionAnalysis":{"A":"Diễn giải sai ý câu: cần phê duyệt của ban lãnh đạo cho chính sách phúc lợi mới không có nghĩa là quy trình trước đó bị làm sai.","B":"Bẫy từ khóa 'shift' từ đoạn trước: câu nói về quyền phê duyệt tiền ăn nhẹ hoàn toàn không ngụ ý nhân viên phải tăng ca.","C":"Đảo ngược người hành động: người nói hẹn 'I'll keep you posted' (tự báo lại kết quả), không yêu cầu người nghe tự đi gặp quản lý.","D":"Đáp án đúng: cụm 'require management approval' kết hợp 'keep you posted' ngụ ý kế hoạch chưa thể thực hiện ngay lập tức."},"evDocIdx":0,"evTargets":[{"badge":"Câu 94 · Đáp án D","opt":"D","isCorrect":true,"quote":"That will require management approval, but I'll keep you posted.","viQuote":"Phương án đó sẽ cần sự phê duyệt của ban lãnh đạo, nhưng tôi sẽ cập nhật thông tin cho mọi người."}],"evQuotes":["That will require management approval, but I'll keep you posted."]},{"q":95,"part":4,"group_id":"E25_T01_G95_97","audio":"web_assets/ets2025/audio/E25_T01/track_53.mp3","graphicImg":"web_assets/ets2025/gfx/E25_T01_Q95.webp","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_27.webp","web_assets/ets2025/tr/E25_T01_tr_28.webp"],"stem_en":"According to the speaker, what was recently completed?","stem_vi":"Theo lời người nói, điều gì vừa được hoàn thành gần đây?","options":{"A":{"en":"A company reorganization","vi":"Một đợt tái cơ cấu công ty"},"B":{"en":"A park renovation","vi":"Việc cải tạo một công viên"},"C":{"en":"A volunteer training","vi":"Một khóa đào tạo tình nguyện viên"},"D":{"en":"A conservation project","vi":"Một dự án bảo tồn"}},"ans":"B","explanation":"Đáp án đúng: (B) Việc cải tạo một công viên — Thị trưởng Lakeville chào mừng người dân đến dự lễ kỷ niệm công trình Công viên Lakeville vừa mới được cải tạo xong.\nDẫn chứng: \"As mayor of Lakeville, I'm pleased to welcome you to the celebration for our town's newly renovated Lakeville Park.\" (Paraphrase: newly renovated Lakeville Park -> A park renovation).\nPhân tích bẫy:\n- (A) Sai bối cảnh diễn giả: người phát biểu là thị trưởng thị trấn tại lễ mừng công viên địa phương, không liên quan đến tái cơ cấu doanh nghiệp.\n- (C) Thông tin không xuất hiện: bài phát biểu không đề cập đến tình nguyện viên hay bất kỳ khóa tập huấn nào.\n- (D) Bẫy suy diễn từ không gian ngoài trời: bài nói chỉ nhấn mạnh việc cải tạo công viên và lối đi bộ ('newly renovated... / renovated walking trail'), không phải dự án bảo tồn thiên nhiên.","lines":[{"speaker":"M-Cn (Bài phát biểu)","en":"As mayor of Lakeville, I'm pleased to welcome you to the celebration for our town's newly renovated Lakeville Park. There are a lot of new areas to explore, so we've planned a short hike.","vi":"Với tư cách là thị trưởng Lakeville, tôi rất vui mừng chào đón quý vị đến với buổi lễ mừng Công viên Lakeville vừa được cải tạo mới của thị trấn chúng ta. Có rất nhiều khu vực mới để khám phá, vì vậy chúng tôi đã lên kế hoạch cho một chuyến đi bộ đường ngắn.","units":[{"en":"As mayor of Lakeville, I'm pleased to welcome you to the celebration for our town's newly renovated Lakeville Park.","vi":"Với tư cách là thị trưởng Lakeville, tôi rất vui mừng chào đón quý vị đến với buổi lễ mừng Công viên Lakeville vừa được cải tạo mới của thị trấn chúng ta."},{"en":"There are a lot of new areas to explore, so we've planned a short hike.","vi":"Có rất nhiều khu vực mới để khám phá, vì vậy chúng tôi đã lên kế hoạch cho một chuyến đi bộ đường ngắn."}]},{"speaker":"M-Cn","en":"We'll be walking around the pond and along the renovated walking trail. We'll end our walk on the hill on the north side of the park. There we'll be having some free snacks and ice cream.","vi":"Chúng ta sẽ đi bộ quanh ao và dọc theo lối đi bộ vừa được cải tạo. Chúng ta sẽ kết thúc chặng đi bộ trên ngọn đồi ở phía bắc công viên. Tại đó, chúng ta sẽ cùng thưởng thức đồ ăn nhẹ và kem miễn phí.","units":[{"en":"We'll be walking around the pond and along the renovated walking trail.","vi":"Chúng ta sẽ đi bộ quanh ao và dọc theo lối đi bộ vừa được cải tạo."},{"en":"We'll end our walk on the hill on the north side of the park.","vi":"Chúng ta sẽ kết thúc chặng đi bộ trên ngọn đồi ở phía bắc công viên."},{"en":"There we'll be having some free snacks and ice cream.","vi":"Tại đó, chúng ta sẽ cùng thưởng thức đồ ăn nhẹ và kem miễn phí."}]},{"speaker":"M-Cn","en":"For those of you taking photos, don't forget to post them on the city's Web site. We'd like to commemorate this special day.","vi":"Với những quý vị có chụp ảnh, đừng quên đăng tải lên trang web của thành phố nhé. Chúng tôi muốn lưu giữ kỷ niệm về ngày đặc biệt này.","units":[{"en":"For those of you taking photos, don't forget to post them on the city's Web site.","vi":"Với những quý vị có chụp ảnh, đừng quên đăng tải lên trang web của thành phố nhé."},{"en":"We'd like to commemorate this special day.","vi":"Chúng tôi muốn lưu giữ kỷ niệm về ngày đặc biệt này."}]}],"vocab":[{"word":"mayor","pos":"n","ipa":"/ˈmeɪər/","meaning":"thị trưởng"},{"word":"newly renovated","pos":"phr","ipa":"/ˈnuːli ˈrenəveɪtɪd/","meaning":"mới được cải tạo"},{"word":"celebration","pos":"n","ipa":"/ˌselɪˈbreɪʃən/","meaning":"buổi lễ kỷ niệm, lễ ăn mừng"},{"word":"explore","pos":"v","ipa":"/ɪkˈsplɔːr/","meaning":"khám phá"}],"isScanBacked":false,"grammarType":"Part 4 — Chi tiết cụ thể & Paraphrase (Specific Detail)","formula":"CÔNG THỨC PART 4 (Chi tiết mở bài): Bắt cụm tính từ + danh từ ở câu chào mừng ('newly renovated Lakeville Park') -> Đổi sang cụm danh từ tương đương ('A park renovation').","optionAnalysis":{"A":"Sai hoàn toàn bối cảnh: đây là sự kiện cộng đồng do thị trưởng chủ trì tại công viên thị trấn, không phải tái cơ cấu công ty.","B":"Đáp án đúng: cụm 'our town's newly renovated Lakeville Park' tương ứng trực tiếp với 'A park renovation'.","C":"Không được đề cập trong bài: không có chi tiết nào về công tác tình nguyện hay chương trình đào tạo vừa hoàn tất.","D":"Suy diễn lệch từ khóa: công viên được tu sửa lại lối đi bộ và nhiều khu vực mới ('renovated'), không phải một dự án bảo tồn sinh thái."},"evDocIdx":0,"evTargets":[{"badge":"Câu 95 · Đáp án B","opt":"B","isCorrect":true,"quote":"As mayor of Lakeville, I'm pleased to welcome you to the celebration for our town's newly renovated Lakeville Park.","viQuote":"Với tư cách là thị trưởng Lakeville, tôi rất vui mừng chào đón quý vị đến với buổi lễ mừng Công viên Lakeville vừa được cải tạo mới của thị trấn chúng ta."}],"evQuotes":["As mayor of Lakeville, I'm pleased to welcome you to the celebration for our town's newly renovated Lakeville Park."]},{"q":96,"part":4,"group_id":"E25_T01_G95_97","audio":"web_assets/ets2025/audio/E25_T01/track_53.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"Look at the graphic. Where does the speaker say refreshments will be served?","stem_vi":"Hãy nhìn vào hình minh họa. Người nói cho biết đồ ăn thức uống nhẹ sẽ được phục vụ ở đâu?","options":{"A":{"en":"Location 1","vi":"Vị trí 1"},"B":{"en":"Location 2","vi":"Vị trí 2"},"C":{"en":"Location 3","vi":"Vị trí 3"},"D":{"en":"Location 4","vi":"Vị trí 4"}},"ans":"A","explanation":"Đáp án đúng: (A) Vị trí 1 — Thị trưởng cho biết đoàn sẽ kết thúc chặng đi bộ trên ngọn đồi ở phía bắc công viên để thưởng thức đồ ăn nhẹ và kem miễn phí; đối chiếu bản đồ công viên (`E25_T01_Q95.webp`), ký hiệu ở góc trên (phía bắc) có hình ngọn đồi ghi nhãn '1. Hill'.\nDẫn chứng: \"We'll end our walk on the hill on the north side of the park. There we'll be having some free snacks and ice cream.\" -> Tra bản đồ lối đi bộ nét đứt: mục '1. Hill' nằm ở góc trên bên trái (Paraphrase: free snacks and ice cream -> refreshments; the hill -> Location 1).\nPhân tích bẫy:\n- (B) Sai điểm trên bản đồ: '2. Walking Trail Entrance' (góc trên bên phải) là điểm xuất phát vào đường đi bộ, không phải điểm kết thúc có đồ ăn nhẹ.\n- (C) Bẫy suy đoán theo hình minh họa: '3. Picnic Tables' (góc dưới bên phải) vẽ các bàn dã ngoại dễ khiến người thi tưởng là nơi ăn uống, nhưng bài nghe chốt địa điểm ăn kem và snack là trên đồi ('on the hill').\n- (D) Bẫy nhắc địa danh trong bài: '4. Pond' (góc dưới bên trái) được nhắc ở câu 'walking around the pond' (chỉ đi bộ ngang qua ao), không phải nơi phục vụ đồ ăn.","lines":[{"speaker":"M-Cn (Bài phát biểu)","en":"As mayor of Lakeville, I'm pleased to welcome you to the celebration for our town's newly renovated Lakeville Park. There are a lot of new areas to explore, so we've planned a short hike.","vi":"Với tư cách là thị trưởng Lakeville, tôi rất vui mừng chào đón quý vị đến với buổi lễ mừng Công viên Lakeville vừa được cải tạo mới của thị trấn chúng ta. Có rất nhiều khu vực mới để khám phá, vì vậy chúng tôi đã lên kế hoạch cho một chuyến đi bộ đường ngắn.","units":[{"en":"As mayor of Lakeville, I'm pleased to welcome you to the celebration for our town's newly renovated Lakeville Park.","vi":"Với tư cách là thị trưởng Lakeville, tôi rất vui mừng chào đón quý vị đến với buổi lễ mừng Công viên Lakeville vừa được cải tạo mới của thị trấn chúng ta."},{"en":"There are a lot of new areas to explore, so we've planned a short hike.","vi":"Có rất nhiều khu vực mới để khám phá, vì vậy chúng tôi đã lên kế hoạch cho một chuyến đi bộ đường ngắn."}]},{"speaker":"M-Cn","en":"We'll be walking around the pond and along the renovated walking trail. We'll end our walk on the hill on the north side of the park. There we'll be having some free snacks and ice cream.","vi":"Chúng ta sẽ đi bộ quanh ao và dọc theo lối đi bộ vừa được cải tạo. Chúng ta sẽ kết thúc chặng đi bộ trên ngọn đồi ở phía bắc công viên. Tại đó, chúng ta sẽ cùng thưởng thức đồ ăn nhẹ và kem miễn phí.","units":[{"en":"We'll be walking around the pond and along the renovated walking trail.","vi":"Chúng ta sẽ đi bộ quanh ao và dọc theo lối đi bộ vừa được cải tạo."},{"en":"We'll end our walk on the hill on the north side of the park.","vi":"Chúng ta sẽ kết thúc chặng đi bộ trên ngọn đồi ở phía bắc công viên."},{"en":"There we'll be having some free snacks and ice cream.","vi":"Tại đó, chúng ta sẽ cùng thưởng thức đồ ăn nhẹ và kem miễn phí."}]},{"speaker":"M-Cn","en":"For those of you taking photos, don't forget to post them on the city's Web site. We'd like to commemorate this special day.","vi":"Với những quý vị có chụp ảnh, đừng quên đăng tải lên trang web của thành phố nhé. Chúng tôi muốn lưu giữ kỷ niệm về ngày đặc biệt này.","units":[{"en":"For those of you taking photos, don't forget to post them on the city's Web site.","vi":"Với những quý vị có chụp ảnh, đừng quên đăng tải lên trang web của thành phố nhé."},{"en":"We'd like to commemorate this special day.","vi":"Chúng tôi muốn lưu giữ kỷ niệm về ngày đặc biệt này."}]}],"vocab":[{"word":"trail","pos":"n","ipa":"/treɪl/","meaning":"đường mòn, lối đi bộ"},{"word":"pond","pos":"n","ipa":"/pɑːnd/","meaning":"cái ao, hồ nhỏ"},{"word":"hike","pos":"n","ipa":"/haɪk/","meaning":"chuyến đi bộ đường dài"},{"word":"serve","pos":"v","ipa":"/sɜːrv/","meaning":"phục vụ (đồ ăn, thức uống)"}],"isScanBacked":false,"grammarType":"Part 4 — Kết hợp Hình ảnh & Bảng biểu (Graphic Question)","formula":"CÔNG THỨC PART 4 (Bản đồ — Đối chiếu 2 bước): Bước 1 nghe nơi phục vụ đồ ăn ('end our walk on the hill on the north side... free snacks and ice cream') -> Bước 2 dò bản đồ thấy '1. Hill' ở phía bắc -> Chọn 'Location 1'.","optionAnalysis":{"A":"Đáp án đúng: bài nghe chốt ăn snack và kem miễn phí ở 'the hill on the north side', khớp nhãn '1. Hill' ở góc trên trái bản đồ.","B":"Sai vị trí bản đồ: Location 2 là '2. Walking Trail Entrance' (cổng vào đường đi bộ ở góc trên phải), không phải điểm cuối chặng đi.","C":"Bẫy thị giác từ hình bàn dã ngoại: Location 3 là '3. Picnic Tables', nhưng người nói nêu rõ đồ ăn nhẹ được phục vụ trên đồi chứ không ở khu bàn này.","D":"Bẫy nhắc địa danh: Location 4 là '4. Pond' được nhắc đến như điểm đi bộ vòng qua ('walking around the pond'), không phải điểm dừng ăn uống."},"evDocIdx":0,"evTargets":[{"badge":"Câu 96 · Đáp án A","opt":"A","isCorrect":true,"quote":"We'll end our walk on the hill on the north side of the park.","viQuote":"Chúng ta sẽ kết thúc chặng đi bộ trên ngọn đồi ở phía bắc công viên."},{"badge":"Câu 96 · Đáp án A","opt":"A","isCorrect":true,"quote":"There we'll be having some free snacks and ice cream.","viQuote":"Tại đó, chúng ta sẽ cùng thưởng thức đồ ăn nhẹ và kem miễn phí."}],"evQuotes":["We'll end our walk on the hill on the north side of the park.","There we'll be having some free snacks and ice cream."]},{"q":97,"part":4,"group_id":"E25_T01_G95_97","audio":"web_assets/ets2025/audio/E25_T01/track_53.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What are the listeners reminded to do?","stem_vi":"Người nghe được nhắc nhở làm gì?","options":{"A":{"en":"Complete a survey","vi":"Hoàn thành một bản khảo sát"},"B":{"en":"Donate some money","vi":"Quyên góp một khoản tiền"},"C":{"en":"Join an organization","vi":"Tham gia một tổ chức"},"D":{"en":"Post some photographs","vi":"Đăng tải một số bức ảnh"}},"ans":"D","explanation":"Đáp án đúng: (D) Đăng tải một số bức ảnh — Ở phần kết, thị trưởng nhắc những ai chụp ảnh trong buổi lễ đừng quên đăng ảnh lên trang web của thành phố để lưu giữ kỷ niệm.\nDẫn chứng: \"For those of you taking photos, don't forget to post them on the city's Web site. We'd like to commemorate this special day.\" (Paraphrase: taking photos... post them -> Post some photographs).\nPhân tích bẫy:\n- (A) Không có trong bài nói: thị trưởng không yêu cầu người dân điền phiếu khảo sát đánh giá công viên.\n- (B) Bẫy ngữ cảnh sự kiện công cộng: trái với việc quyên góp tiền, thành phố còn cung cấp đồ ăn nhẹ và kem miễn phí cho người tham dự.\n- (C) Suy diễn ngoài nội dung: bài phát biểu chỉ mời chụp ảnh kỷ niệm, không kêu gọi gia nhập tổ chức hay hội nhóm nào.","lines":[{"speaker":"M-Cn (Bài phát biểu)","en":"As mayor of Lakeville, I'm pleased to welcome you to the celebration for our town's newly renovated Lakeville Park. There are a lot of new areas to explore, so we've planned a short hike.","vi":"Với tư cách là thị trưởng Lakeville, tôi rất vui mừng chào đón quý vị đến với buổi lễ mừng Công viên Lakeville vừa được cải tạo mới của thị trấn chúng ta. Có rất nhiều khu vực mới để khám phá, vì vậy chúng tôi đã lên kế hoạch cho một chuyến đi bộ đường ngắn.","units":[{"en":"As mayor of Lakeville, I'm pleased to welcome you to the celebration for our town's newly renovated Lakeville Park.","vi":"Với tư cách là thị trưởng Lakeville, tôi rất vui mừng chào đón quý vị đến với buổi lễ mừng Công viên Lakeville vừa được cải tạo mới của thị trấn chúng ta."},{"en":"There are a lot of new areas to explore, so we've planned a short hike.","vi":"Có rất nhiều khu vực mới để khám phá, vì vậy chúng tôi đã lên kế hoạch cho một chuyến đi bộ đường ngắn."}]},{"speaker":"M-Cn","en":"We'll be walking around the pond and along the renovated walking trail. We'll end our walk on the hill on the north side of the park. There we'll be having some free snacks and ice cream.","vi":"Chúng ta sẽ đi bộ quanh ao và dọc theo lối đi bộ vừa được cải tạo. Chúng ta sẽ kết thúc chặng đi bộ trên ngọn đồi ở phía bắc công viên. Tại đó, chúng ta sẽ cùng thưởng thức đồ ăn nhẹ và kem miễn phí.","units":[{"en":"We'll be walking around the pond and along the renovated walking trail.","vi":"Chúng ta sẽ đi bộ quanh ao và dọc theo lối đi bộ vừa được cải tạo."},{"en":"We'll end our walk on the hill on the north side of the park.","vi":"Chúng ta sẽ kết thúc chặng đi bộ trên ngọn đồi ở phía bắc công viên."},{"en":"There we'll be having some free snacks and ice cream.","vi":"Tại đó, chúng ta sẽ cùng thưởng thức đồ ăn nhẹ và kem miễn phí."}]},{"speaker":"M-Cn","en":"For those of you taking photos, don't forget to post them on the city's Web site. We'd like to commemorate this special day.","vi":"Với những quý vị có chụp ảnh, đừng quên đăng tải lên trang web của thành phố nhé. Chúng tôi muốn lưu giữ kỷ niệm về ngày đặc biệt này.","units":[{"en":"For those of you taking photos, don't forget to post them on the city's Web site.","vi":"Với những quý vị có chụp ảnh, đừng quên đăng tải lên trang web của thành phố nhé."},{"en":"We'd like to commemorate this special day.","vi":"Chúng tôi muốn lưu giữ kỷ niệm về ngày đặc biệt này."}]}],"vocab":[{"word":"post","pos":"v","ipa":"/poʊst/","meaning":"đăng tải (lên mạng)"},{"word":"commemorate","pos":"v","ipa":"/kəˈmeməreɪt/","meaning":"kỷ niệm, ghi dấu"},{"word":"remind","pos":"v","ipa":"/rɪˈmaɪnd/","meaning":"nhắc nhở"},{"word":"photograph","pos":"n","ipa":"/ˈfoʊtəɡræf/","meaning":"bức ảnh"}],"isScanBacked":false,"grammarType":"Part 4 — Hành động tiếp theo & Đề xuất (Next Step & Offer/Request)","formula":"CÔNG THỨC PART 4 (Lời nhắc cuối bài): Bắt từ khóa nhắc nhở ('don't forget to + V...') -> Paraphrase 'post them [photos] on the city's Web site' thành 'Post some photographs'.","optionAnalysis":{"A":"Không được đề cập: bài phát biểu không nhắc đến việc lấy ý kiến hay hoàn thành bản khảo sát nào.","B":"Sai ngữ cảnh sự kiện: thành phố tổ chức lễ khánh thành kèm kem và đồ ăn nhẹ miễn phí, không hề kêu gọi quyên góp tiền.","C":"Thông tin không có trong bài: thị trưởng không đề cập hay mời người nghe đăng ký tham gia bất kỳ tổ chức nào.","D":"Đáp án đúng: lời dặn 'don't forget to post them [photos] on the city's Web site' khớp sát với 'Post some photographs'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 97 · Đáp án D","opt":"D","isCorrect":true,"quote":"For those of you taking photos, don't forget to post them on the city's Web site.","viQuote":"Với những quý vị có chụp ảnh, đừng quên đăng tải lên trang web của thành phố nhé."}],"evQuotes":["For those of you taking photos, don't forget to post them on the city's Web site."]},{"q":98,"part":4,"group_id":"E25_T01_G98_100","audio":"web_assets/ets2025/audio/E25_T01/track_54.mp3","graphicImg":"web_assets/ets2025/gfx/E25_T01_Q98.webp","transcriptImgs":["web_assets/ets2025/tr/E25_T01_tr_28.webp","web_assets/ets2025/tr/E25_T01_tr_29.webp"],"stem_en":"What is the topic of today's lecture?","stem_vi":"Chủ đề của bài giảng hôm nay là gì?","options":{"A":{"en":"When to harvest crops","vi":"Khi nào nên thu hoạch cây trồng"},"B":{"en":"Where to plant trees","vi":"Nên trồng cây ở đâu"},"C":{"en":"How to grow vegetables","vi":"Cách trồng rau"},"D":{"en":"Which flowers need more sun","vi":"Loại hoa nào cần nhiều ánh nắng hơn"}},"ans":"C","explanation":"Đáp án đúng: (C) Cách trồng rau — Diễn giả mở đầu bài giảng bằng cách nêu rõ lý do tổ chức là đáp ứng nhiều yêu cầu tìm hiểu về cách trồng và chăm sóc một vườn rau khỏe mạnh.\nDẫn chứng: \"So, we've received lots of requests for information on growing a vegetable garden. People want to know how to keep their garden healthy and get the vegetables they want.\" (Paraphrase: growing a vegetable garden -> How to grow vegetables).\nPhân tích bẫy:\n- (A) Bẫy từ khóa bảng biểu: cột 'Time of Year' và 'Type of Crop' trên bảng nói về lịch lấy mẫu đất ('Soil Sampling Timeline'), không phải thời điểm thu hoạch mùa màng.\n- (B) Bẫy từ dòng cuối bảng biểu: bảng có mục 'Trees and shrubs' cho độ sâu lấy mẫu đất tháng 11–8, nhưng bài giảng không bàn về vị trí trồng cây.\n- (D) Bẫy từ dòng thứ hai bảng biểu: mục 'Flowers' chỉ xuất hiện trong bảng độ sâu lấy mẫu đất, bài nói không nhắc đến ánh nắng cho hoa.","lines":[{"speaker":"W-Br (Bài giảng)","en":"Thanks, everyone, for attending today's free public lecture, sponsored by the Springfield Farmers' Association. So, we've received lots of requests for information on growing a vegetable garden. People want to know how to keep their garden healthy and get the vegetables they want.","vi":"Cảm ơn mọi người đã tham dự buổi giảng cộng đồng miễn phí hôm nay do Hiệp hội Nông dân Springfield tài trợ. Chúng tôi đã nhận được rất nhiều yêu cầu cung cấp thông tin về cách trồng một vườn rau. Mọi người muốn biết cách chăm sóc để khu vườn phát triển khỏe mạnh và thu hoạch được những loại rau mình mong muốn.","units":[{"en":"Thanks, everyone, for attending today's free public lecture, sponsored by the Springfield Farmers' Association.","vi":"Cảm ơn mọi người đã tham dự buổi giảng cộng đồng miễn phí hôm nay do Hiệp hội Nông dân Springfield tài trợ."},{"en":"So, we've received lots of requests for information on growing a vegetable garden.","vi":"Chúng tôi đã nhận được rất nhiều yêu cầu cung cấp thông tin về cách trồng một vườn rau."},{"en":"People want to know how to keep their garden healthy and get the vegetables they want.","vi":"Mọi người muốn biết cách chăm sóc để khu vườn phát triển khỏe mạnh và thu hoạch được những loại rau mình mong muốn."}]},{"speaker":"W-Br","en":"The first thing we recommend is regular soil testing. Since this is September, all soil samples in the next six weeks should be taken from the same depth, as seen on this chart.","vi":"Điều đầu tiên chúng tôi khuyến nghị là kiểm tra đất định kỳ. Vì hiện tại đang là tháng Chín, tất cả các mẫu đất trong sáu tuần tới đều nên được lấy ở cùng một độ sâu, như thể hiện trên biểu đồ này.","units":[{"en":"The first thing we recommend is regular soil testing.","vi":"Điều đầu tiên chúng tôi khuyến nghị là kiểm tra đất định kỳ."},{"en":"Since this is September, all soil samples in the next six weeks should be taken from the same depth, as seen on this chart.","vi":"Vì hiện tại đang là tháng Chín, tất cả các mẫu đất trong sáu tuần tới đều nên được lấy ở cùng một độ sâu, như thể hiện trên biểu đồ này."}]},{"speaker":"W-Br","en":"Oh, and before you leave today, please sign up for our mailing list to stay informed of future lectures.","vi":"À, và trước khi ra về hôm nay, xin mọi người hãy đăng ký vào danh sách nhận thư của chúng tôi để cập nhật thông tin về các buổi giảng sắp tới.","units":[{"en":"Oh, and before you leave today, please sign up for our mailing list to stay informed of future lectures.","vi":"À, và trước khi ra về hôm nay, xin mọi người hãy đăng ký vào danh sách nhận thư của chúng tôi để cập nhật thông tin về các buổi giảng sắp tới."}]}],"vocab":[{"word":"public lecture","pos":"n","ipa":"/ˈpʌblɪk ˈlektʃər/","meaning":"buổi thuyết trình cộng đồng"},{"word":"sponsor","pos":"v","ipa":"/ˈspɑːnsər/","meaning":"tài trợ"},{"word":"association","pos":"n","ipa":"/əˌsoʊsiˈeɪʃən/","meaning":"hiệp hội"},{"word":"healthy","pos":"adj","ipa":"/ˈhelθi/","meaning":"khỏe mạnh, phát triển tốt"}],"isScanBacked":false,"grammarType":"Part 4 — Ý chính & Mục đích (Gist & Purpose)","formula":"CÔNG THỨC PART 4 (Chủ đề bài giảng): Nghe câu giới thiệu trọng tâm ngay sau lời cảm ơn ('requests for information on growing a vegetable garden') -> Tránh bị bẫy bởi các dòng phụ trên bảng biểu.","optionAnalysis":{"A":"Bẫy tiêu đề cột bảng biểu: bảng 'Soil Sampling Timeline' hướng dẫn lịch lấy mẫu đất theo mùa chứ bài giảng không bàn về thời điểm thu hoạch.","B":"Bẫy từ bảng biểu: dòng cuối bảng nhắc 'Trees and shrubs' (lấy mẫu đất sâu 8 inch), nhưng bài giảng không bàn nơi trồng cây.","C":"Đáp án đúng: cụm 'information on growing a vegetable garden' ở phần mở đầu khớp trực tiếp với 'How to grow vegetables'.","D":"Bẫy từ dòng 'Flowers' trên bảng: diễn giả không hề thảo luận về loại hoa nào cần nhiều ánh nắng hơn."},"evDocIdx":0,"evTargets":[{"badge":"Câu 98 · Đáp án C","opt":"C","isCorrect":true,"quote":"So, we've received lots of requests for information on growing a vegetable garden.","viQuote":"Chúng tôi đã nhận được rất nhiều yêu cầu cung cấp thông tin về cách trồng một vườn rau."},{"badge":"Câu 98 · Đáp án C","opt":"C","isCorrect":true,"quote":"People want to know how to keep their garden healthy and get the vegetables they want.","viQuote":"Mọi người muốn biết cách chăm sóc để khu vườn phát triển khỏe mạnh và thu hoạch được những loại rau mình mong muốn."}],"evQuotes":["So, we've received lots of requests for information on growing a vegetable garden.","People want to know how to keep their garden healthy and get the vegetables they want."]},{"q":99,"part":4,"group_id":"E25_T01_G98_100","audio":"web_assets/ets2025/audio/E25_T01/track_54.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"Look at the graphic. At what depth should samples be collected this month?","stem_vi":"Hãy nhìn vào hình minh họa. Các mẫu nên được lấy ở độ sâu nào trong tháng này?","options":{"A":{"en":"12 inches","vi":"12 inch"},"B":{"en":"4 inches","vi":"4 inch"},"C":{"en":"6 inches","vi":"6 inch"},"D":{"en":"8 inches","vi":"8 inch"}},"ans":"A","explanation":"Đáp án đúng: (A) 12 inch — Diễn giả nêu rõ hiện tại đang là tháng Chín nên mọi mẫu đất trong sáu tuần tới phải lấy ở cùng một độ sâu; tra bảng `Soil Sampling Timeline` (`E25_T01_Q98.webp`) gồm 3 cột (Time of Year | Type of Crop | Depth), dòng 1 ghi 'September–October' áp dụng cho 'All plants' ở độ sâu '12 inches'.\nDẫn chứng: \"Since this is September, all soil samples in the next six weeks should be taken from the same depth, as seen on this chart.\" -> Dòng 1 bảng biểu: Time of Year = 'September–October' -> Type of Crop = 'All plants' -> Depth = '12 inches' -> Chọn (A).\nPhân tích bẫy:\n- (B) Bẫy tra nhầm khoảng thời gian: '4 inches' là độ sâu cho 'Flowers' nhưng thuộc giai đoạn 'November–August', không phải tháng 9.\n- (C) Bẫy giao thoa chủ đề Q98: '6 inches' là độ sâu của 'Vegetables' nhưng chỉ áp dụng cho 'November–August'; riêng tháng 9–10 thì tất cả cây trồng ('All plants') đều lấy ở mức 12 inch.\n- (D) Bẫy tra nhầm dòng cuối bảng: '8 inches' áp dụng cho 'Trees and shrubs' trong giai đoạn 'November–August', sai cả thời gian lẫn loại cây trọng tâm.","lines":[{"speaker":"W-Br (Bài giảng)","en":"Thanks, everyone, for attending today's free public lecture, sponsored by the Springfield Farmers' Association. So, we've received lots of requests for information on growing a vegetable garden. People want to know how to keep their garden healthy and get the vegetables they want.","vi":"Cảm ơn mọi người đã tham dự buổi giảng cộng đồng miễn phí hôm nay do Hiệp hội Nông dân Springfield tài trợ. Chúng tôi đã nhận được rất nhiều yêu cầu cung cấp thông tin về cách trồng một vườn rau. Mọi người muốn biết cách chăm sóc để khu vườn phát triển khỏe mạnh và thu hoạch được những loại rau mình mong muốn.","units":[{"en":"Thanks, everyone, for attending today's free public lecture, sponsored by the Springfield Farmers' Association.","vi":"Cảm ơn mọi người đã tham dự buổi giảng cộng đồng miễn phí hôm nay do Hiệp hội Nông dân Springfield tài trợ."},{"en":"So, we've received lots of requests for information on growing a vegetable garden.","vi":"Chúng tôi đã nhận được rất nhiều yêu cầu cung cấp thông tin về cách trồng một vườn rau."},{"en":"People want to know how to keep their garden healthy and get the vegetables they want.","vi":"Mọi người muốn biết cách chăm sóc để khu vườn phát triển khỏe mạnh và thu hoạch được những loại rau mình mong muốn."}]},{"speaker":"W-Br","en":"The first thing we recommend is regular soil testing. Since this is September, all soil samples in the next six weeks should be taken from the same depth, as seen on this chart.","vi":"Điều đầu tiên chúng tôi khuyến nghị là kiểm tra đất định kỳ. Vì hiện tại đang là tháng Chín, tất cả các mẫu đất trong sáu tuần tới đều nên được lấy ở cùng một độ sâu, như thể hiện trên biểu đồ này.","units":[{"en":"The first thing we recommend is regular soil testing.","vi":"Điều đầu tiên chúng tôi khuyến nghị là kiểm tra đất định kỳ."},{"en":"Since this is September, all soil samples in the next six weeks should be taken from the same depth, as seen on this chart.","vi":"Vì hiện tại đang là tháng Chín, tất cả các mẫu đất trong sáu tuần tới đều nên được lấy ở cùng một độ sâu, như thể hiện trên biểu đồ này."}]},{"speaker":"W-Br","en":"Oh, and before you leave today, please sign up for our mailing list to stay informed of future lectures.","vi":"À, và trước khi ra về hôm nay, xin mọi người hãy đăng ký vào danh sách nhận thư của chúng tôi để cập nhật thông tin về các buổi giảng sắp tới.","units":[{"en":"Oh, and before you leave today, please sign up for our mailing list to stay informed of future lectures.","vi":"À, và trước khi ra về hôm nay, xin mọi người hãy đăng ký vào danh sách nhận thư của chúng tôi để cập nhật thông tin về các buổi giảng sắp tới."}]}],"vocab":[{"word":"regular","pos":"adj","ipa":"/ˈreɡjələr/","meaning":"định kỳ, thường xuyên"},{"word":"soil sample","pos":"n","ipa":"/sɔɪl ˈsæmpəl/","meaning":"mẫu đất"},{"word":"depth","pos":"n","ipa":"/depθ/","meaning":"độ sâu"},{"word":"collect","pos":"v","ipa":"/kəˈlekt/","meaning":"thu thập, lấy mẫu"}],"isScanBacked":false,"grammarType":"Part 4 — Kết hợp Hình ảnh & Bảng biểu (Graphic Question)","formula":"CÔNG THỨC PART 4 (Bảng 3 cột — Đối chiếu 2 bước): Bước 1 nghe mốc thời gian hiện tại ('Since this is September') -> Bước 2 tra dòng 'September–October | All plants' trên bảng 'Soil Sampling Timeline' -> Chốt cột Depth '12 inches'.","optionAnalysis":{"A":"Đáp án đúng: mốc 'September' ở lời thoại tra sang dòng 1 cột Time of Year ('September–October | All plants') cho ra Depth = '12 inches'.","B":"Bẫy tra sai dòng thời gian: '4 inches' nằm ở dòng 'Flowers' của giai đoạn 'November–August', không áp dụng cho tháng Chín.","C":"Bẫy rất tinh vi theo chủ đề rau: '6 inches' đúng với dòng 'Vegetables', nhưng thuộc giai đoạn 'November–August' chứ không phải tháng Chín ('September–October').","D":"Bẫy tra nhầm dòng cuối bảng: '8 inches' chỉ dùng cho 'Trees and shrubs' vào giai đoạn 'November–August', không khớp mốc hiện tại."},"evDocIdx":0,"evTargets":[{"badge":"Câu 99 · Đáp án A","opt":"A","isCorrect":true,"quote":"Since this is September, all soil samples in the next six weeks should be taken from the same depth, as seen on this chart.","viQuote":"Vì hiện tại đang là tháng Chín, tất cả các mẫu đất trong sáu tuần tới đều nên được lấy ở cùng một độ sâu, như thể hiện trên biểu đồ này."}],"evQuotes":["Since this is September, all soil samples in the next six weeks should be taken from the same depth, as seen on this chart."]},{"q":100,"part":4,"group_id":"E25_T01_G98_100","audio":"web_assets/ets2025/audio/E25_T01/track_54.mp3","graphicImg":null,"transcriptImgs":[],"stem_en":"What does the speaker encourage the listeners to do?","stem_vi":"Người nói khuyến khích người nghe làm gì?","options":{"A":{"en":"Turn off mobile phones","vi":"Tắt điện thoại di động"},"B":{"en":"Have some refreshments","vi":"Dùng đồ ăn thức uống nhẹ"},"C":{"en":"Purchase some seeds","vi":"Mua một ít hạt giống"},"D":{"en":"Sign up for a mailing list","vi":"Đăng ký vào danh sách nhận thư"}},"ans":"D","explanation":"Đáp án đúng: (D) Đăng ký vào danh sách nhận thư — Trước khi kết thúc buổi giảng, diễn giả khuyến khích người nghe đăng ký vào danh sách nhận thư của hiệp hội để nhận thông báo về các buổi giảng tiếp theo.\nDẫn chứng: \"Oh, and before you leave today, please sign up for our mailing list to stay informed of future lectures.\" (Khớp nguyên văn: sign up for our mailing list -> Sign up for a mailing list).\nPhân tích bẫy:\n- (A) Bẫy thói quen trước giờ giảng: câu cuối dặn trước khi ra về ('before you leave today'), không phải nhắc tắt điện thoại khi bắt đầu buổi nói chuyện.\n- (B) Sai ngữ cảnh sự kiện: diễn giả không hề mời người tham dự dùng đồ ăn nhẹ hay nước uống sau buổi giảng.\n- (C) Suy diễn lệch từ chủ đề làm vườn: dù nói về trồng vườn rau, hiệp hội chỉ tổ chức giảng miễn phí và mời nhận tin chứ không bán hạt giống.","lines":[{"speaker":"W-Br (Bài giảng)","en":"Thanks, everyone, for attending today's free public lecture, sponsored by the Springfield Farmers' Association. So, we've received lots of requests for information on growing a vegetable garden. People want to know how to keep their garden healthy and get the vegetables they want.","vi":"Cảm ơn mọi người đã tham dự buổi giảng cộng đồng miễn phí hôm nay do Hiệp hội Nông dân Springfield tài trợ. Chúng tôi đã nhận được rất nhiều yêu cầu cung cấp thông tin về cách trồng một vườn rau. Mọi người muốn biết cách chăm sóc để khu vườn phát triển khỏe mạnh và thu hoạch được những loại rau mình mong muốn.","units":[{"en":"Thanks, everyone, for attending today's free public lecture, sponsored by the Springfield Farmers' Association.","vi":"Cảm ơn mọi người đã tham dự buổi giảng cộng đồng miễn phí hôm nay do Hiệp hội Nông dân Springfield tài trợ."},{"en":"So, we've received lots of requests for information on growing a vegetable garden.","vi":"Chúng tôi đã nhận được rất nhiều yêu cầu cung cấp thông tin về cách trồng một vườn rau."},{"en":"People want to know how to keep their garden healthy and get the vegetables they want.","vi":"Mọi người muốn biết cách chăm sóc để khu vườn phát triển khỏe mạnh và thu hoạch được những loại rau mình mong muốn."}]},{"speaker":"W-Br","en":"The first thing we recommend is regular soil testing. Since this is September, all soil samples in the next six weeks should be taken from the same depth, as seen on this chart.","vi":"Điều đầu tiên chúng tôi khuyến nghị là kiểm tra đất định kỳ. Vì hiện tại đang là tháng Chín, tất cả các mẫu đất trong sáu tuần tới đều nên được lấy ở cùng một độ sâu, như thể hiện trên biểu đồ này.","units":[{"en":"The first thing we recommend is regular soil testing.","vi":"Điều đầu tiên chúng tôi khuyến nghị là kiểm tra đất định kỳ."},{"en":"Since this is September, all soil samples in the next six weeks should be taken from the same depth, as seen on this chart.","vi":"Vì hiện tại đang là tháng Chín, tất cả các mẫu đất trong sáu tuần tới đều nên được lấy ở cùng một độ sâu, như thể hiện trên biểu đồ này."}]},{"speaker":"W-Br","en":"Oh, and before you leave today, please sign up for our mailing list to stay informed of future lectures.","vi":"À, và trước khi ra về hôm nay, xin mọi người hãy đăng ký vào danh sách nhận thư của chúng tôi để cập nhật thông tin về các buổi giảng sắp tới.","units":[{"en":"Oh, and before you leave today, please sign up for our mailing list to stay informed of future lectures.","vi":"À, và trước khi ra về hôm nay, xin mọi người hãy đăng ký vào danh sách nhận thư của chúng tôi để cập nhật thông tin về các buổi giảng sắp tới."}]}],"vocab":[{"word":"sign up","pos":"phr. v","ipa":"/saɪn ʌp/","meaning":"đăng ký"},{"word":"mailing list","pos":"n","ipa":"/ˈmeɪlɪŋ lɪst/","meaning":"danh sách nhận thư, bản tin"},{"word":"stay informed","pos":"phr","ipa":"/steɪ ɪnˈfɔːrmd/","meaning":"cập nhật thông tin"},{"word":"encourage","pos":"v","ipa":"/ɪnˈkɜːrɪdʒ/","meaning":"khuyến khích"}],"isScanBacked":false,"grammarType":"Part 4 — Hành động tiếp theo & Đề xuất (Next Step & Offer/Request)","formula":"CÔNG THỨC PART 4 (Lời kêu gọi kết bài): Bắt tín hiệu chuyển ý cuối bài ('Oh, and before you leave today, please...') -> Khớp cụm động từ 'sign up for our mailing list'.","optionAnalysis":{"A":"Sai bối cảnh và thời điểm: lời nhắc đưa ra lúc sắp ra về ('before you leave'), không có yêu cầu nào liên quan đến điện thoại di động.","B":"Không được đề cập trong bài giảng: không có lời mời dùng trà bánh hay đồ ăn nhẹ nào dành cho người tham dự.","C":"Suy diễn ngoài bài nói: bài giảng cung cấp kiến thức miễn phí, không quảng bá hay khuyến khích người nghe mua hạt giống.","D":"Đáp án đúng: cụm 'please sign up for our mailing list' ở câu cuối khớp trực tiếp với phương án (D)."},"evDocIdx":0,"evTargets":[{"badge":"Câu 100 · Đáp án D","opt":"D","isCorrect":true,"quote":"Oh, and before you leave today, please sign up for our mailing list to stay informed of future lectures.","viQuote":"À, và trước khi ra về hôm nay, xin mọi người hãy đăng ký vào danh sách nhận thư của chúng tôi để cập nhật thông tin về các buổi giảng sắp tới."}],"evQuotes":["Oh, and before you leave today, please sign up for our mailing list to stay informed of future lectures."]},{"q":101,"part":5,"group_id":null,"audio":null,"stem_en":"Former Sendai Company CEO Ken Nakata spoke about ------- career experiences.","stem_vi":"Cựu CEO của Công ty Sendai, ông Ken Nakata, đã chia sẻ về những kinh nghiệm sự nghiệp -------.","options":{"A":{"en":"he","vi":"ông ấy, anh ấy (đại từ chủ ngữ)"},"B":{"en":"his","vi":"của ông ấy, của anh ấy (tính từ sở hữu)"},"C":{"en":"him","vi":"ông ấy, anh ấy (đại từ tân ngữ)"},"D":{"en":"himself","vi":"chính ông ấy, tự bản thân (đại từ phản thân)"}},"ans":"B","explanation":"Đáp án đúng: (B) his — tính từ sở hữu bổ nghĩa cho cụm danh từ 'career experiences', quy chiếu về chủ ngữ số ít chỉ nam 'Ken Nakata'.\nDẫn chứng: \"Former Sendai Company CEO Ken Nakata spoke about ------- career experiences.\" (Cụm danh từ 'career experiences' đứng ngay sau chỗ trống cần từ hạn định sở hữu).\nPhân tích bẫy:\n- (A) 'he' là đại từ nhân xưng chủ ngữ, chỉ đứng làm chủ ngữ trước động từ chia thì chứ không đứng trước danh từ để bổ nghĩa.\n- (C) 'him' là đại từ tân ngữ, chỉ đứng sau động từ hoặc giới từ một mình chứ không kết hợp trực tiếp với cụm danh từ 'career experiences'.\n- (D) 'himself' là đại từ phản thân dùng để nhấn mạnh hoặc làm tân ngữ trùng chủ ngữ, không có chức năng sở hữu trước danh từ.","lines":[],"vocab":[{"word":"former","pos":"adj","ipa":"/ˈfɔːrmər/","meaning":"cựu, trước đây"},{"word":"career","pos":"n","ipa":"/kəˈrɪr/","meaning":"sự nghiệp"},{"word":"experience","pos":"n","ipa":"/ɪkˈspɪriəns/","meaning":"kinh nghiệm"},{"word":"his","pos":"det","ipa":"/hɪz/","meaning":"của ông ấy (tính từ sở hữu)"}],"isScanBacked":false,"grammarType":"Đại từ / Từ hạn định (Pronoun & Determiner)","formula":"CÔNG THỨC PART 5 (Tờ A3 Màu — Tính từ sở hữu + Cụm danh từ): Trước cụm danh từ 'career experiences' cần Tính từ sở hữu để chỉ quyền sở hữu của chủ ngữ nam giới 'Ken Nakata' -> Chọn 'his' (loại đại từ chủ ngữ/tân ngữ/phản thân).","optionAnalysis":{"A":"Sai loại từ: 'he' là đại từ chủ ngữ, không thể đứng trước cụm danh từ 'career experiences' làm từ sở hữu.","B":"Chính xác: 'his' là tính từ sở hữu khớp với danh từ 'Ken Nakata' và đứng đúng vị trí trước cụm danh từ 'career experiences'.","C":"Sai chức năng ngữ pháp: 'him' là đại từ tân ngữ, đứng độc lập sau giới từ 'about' được nhưng không thể bổ nghĩa cho 'career experiences'.","D":"Sai chức năng sở hữu: 'himself' là đại từ phản thân, không dùng thay cho tính từ sở hữu trước danh từ."},"evDocIdx":0,"evTargets":[{"badge":"Câu 101 · Đáp án B","opt":"B","isCorrect":true,"quote":"Former Sendai Company CEO Ken Nakata spoke about ------- career experiences.","viQuote":"Cựu CEO của Công ty Sendai, ông Ken Nakata, đã chia sẻ về những kinh nghiệm sự nghiệp -------."},{"badge":"Câu 101 · Từ khóa B","opt":"B","isCorrect":true,"quote":"his","viQuote":"của ông ấy, của anh ấy (tính từ sở hữu)"}],"evQuotes":["Former Sendai Company CEO Ken Nakata spoke about ------- career experiences.","his"]},{"q":102,"part":5,"group_id":null,"audio":null,"stem_en":"Passengers who will be taking a ------- domestic flight should go to Terminal A.","stem_vi":"Hành khách sẽ đi chuyến bay nội địa ------- nên di chuyển đến Nhà ga A.","options":{"A":{"en":"connectivity","vi":"khả năng kết nối (n)"},"B":{"en":"connects","vi":"kết nối (v - chia ngôi 3 số ít)"},"C":{"en":"connect","vi":"kết nối (v - nguyên thể)"},"D":{"en":"connecting","vi":"nối chuyến, kết nối (adj/V-ing)"}},"ans":"D","explanation":"Đáp án đúng: (D) connecting — tính từ dạng phân từ hiện tại mang nghĩa 'nối chuyến', kết hợp tự nhiên thành cụm 'a connecting domestic flight'.\nDẫn chứng: \"Passengers who will be taking a ------- domestic flight should go to Terminal A.\" (Cần tính từ bổ nghĩa cho 'domestic flight' sau mạo từ 'a').\nPhân tích bẫy:\n- (A) 'connectivity' là danh từ trừu tượng ('khả năng kết nối'), ghép vào tạo thành chuỗi danh từ sai nghĩa và sai cấu trúc bổ nghĩa.\n- (B) 'connects' là động từ chia ngôi thứ ba số ít, mệnh đề quan hệ đã có cụm động từ chính 'will be taking' nên thừa động từ chia thì.\n- (C) 'connect' là động từ nguyên thể, không thể đứng sau mạo từ 'a' để bổ nghĩa cho cụm danh từ 'domestic flight'.","lines":[],"vocab":[{"word":"connecting","pos":"adj","ipa":"/kəˈnektɪŋ/","meaning":"nối chuyến, kết nối"},{"word":"domestic","pos":"adj","ipa":"/dəˈmestɪk/","meaning":"nội địa, trong nước"},{"word":"passenger","pos":"n","ipa":"/ˈpæsɪndʒər/","meaning":"hành khách"},{"word":"terminal","pos":"n","ipa":"/ˈtɜːrmɪnəl/","meaning":"nhà ga sân bay"}],"isScanBacked":false,"grammarType":"Từ loại (Word Form: Danh từ / Động từ / Tính từ / Trạng từ)","formula":"CÔNG THỨC PART 5 (Tờ A3 Màu — Mạo từ + Tính từ + Danh từ): Trong cụm danh từ 'a ___ domestic flight', vị trí giữa mạo từ 'a' và tính từ/danh từ ghép 'domestic flight' cần tính từ 'connecting' (chuyến bay nối chuyến).","optionAnalysis":{"A":"Sai từ loại: 'connectivity' là danh từ chỉ tính kết nối, không dùng để bổ nghĩa trực tiếp cho 'domestic flight' sau mạo từ 'a'.","B":"Sai cấu trúc động từ: 'connects' là động từ chia thì, không thể đứng trong cụm danh từ sau mạo từ 'a' khi đã có 'will be taking'.","C":"Sai từ loại: 'connect' là động từ nguyên thể, không có chức năng làm tính từ đứng trước 'domestic flight'.","D":"Chính xác: 'connecting' đóng vai trò tính từ trong cụm thuật ngữ hàng không 'connecting domestic flight' (chuyến bay nội địa nối chuyến)."},"evDocIdx":0,"evTargets":[{"badge":"Câu 102 · Đáp án D","opt":"D","isCorrect":true,"quote":"Passengers who will be taking a ------- domestic flight should go to Terminal A.","viQuote":"Hành khách sẽ đi chuyến bay nội địa ------- nên di chuyển đến Nhà ga A."},{"badge":"Câu 102 · Từ khóa D","opt":"D","isCorrect":true,"quote":"connecting","viQuote":"nối chuyến, kết nối (adj/V-ing)"}],"evQuotes":["Passengers who will be taking a ------- domestic flight should go to Terminal A.","connecting"]},{"q":103,"part":5,"group_id":null,"audio":null,"stem_en":"Fresh and ------- apple-cider donuts are available at Oakcrest Orchard's retail shop for £6 per dozen.","stem_vi":"Bánh donut nước táo ép tươi mới và ------- hiện được bày bán tại cửa hàng bán lẻ của Oakcrest Orchard với giá £6 mỗi tá.","options":{"A":{"en":"eaten","vi":"đã bị ăn (V-pp)"},"B":{"en":"open","vi":"mở, thoáng mở (adj)"},"C":{"en":"tasty","vi":"thơm ngon (adj)"},"D":{"en":"free","vi":"miễn phí, tự do (adj)"}},"ans":"C","explanation":"Đáp án đúng: (C) tasty — tính từ mang nghĩa 'thơm ngon', song song với 'Fresh' (tươi mới) để miêu tả bánh donut táo đang bày bán.\nDẫn chứng: \"Fresh and ------- apple-cider donuts are available at Oakcrest Orchard's retail shop for £6 per dozen.\" (Sản phẩm ăn uống được bán theo tá với giá £6).\nPhân tích bẫy:\n- (A) 'eaten' là quá khứ phân từ mang nghĩa bị động 'đã bị ăn hết', phi lý khi ghép với mặt hàng đang 'available' (có sẵn để bán).\n- (B) 'open' nghĩa là 'mở cửa/thoáng', thường đi với cửa hàng hoặc không gian chứ không kết hợp tự nhiên để tả chất lượng bánh donut.\n- (D) 'free' nghĩa là 'miễn phí', mâu thuẫn trực tiếp với thông tin giá bán 'for £6 per dozen' ngay phía sau câu.","lines":[],"vocab":[{"word":"tasty","pos":"adj","ipa":"/ˈteɪsti/","meaning":"thơm ngon"},{"word":"available","pos":"adj","ipa":"/əˈveɪləbəl/","meaning":"có sẵn, được bày bán"},{"word":"retail shop","pos":"n","ipa":"/ˈriːteɪl ʃɑːp/","meaning":"cửa hàng bán lẻ"},{"word":"per dozen","pos":"phr","ipa":"/pər ˈdʌzən/","meaning":"mỗi tá (12 cái)"}],"isScanBacked":false,"grammarType":"Từ vựng — Tính từ (Adjective)","formula":"CÔNG THỨC PART 5 (Từ vựng Ngữ cảnh — Cấu trúc song song 'Fresh and ___'): Liên từ 'and' nối hai tính từ cùng trường nghĩa tích cực miêu tả món bánh 'apple-cider donuts' đang bán với giá £6/tá -> Chọn 'tasty' (thơm ngon).","optionAnalysis":{"A":"Sai ngữ nghĩa: 'eaten' mang nghĩa 'đã bị ăn', hoàn toàn trái ngược với trạng thái hàng hóa còn sẵn để bán ('available').","B":"Sai kết hợp từ: 'open' mang nghĩa 'mở' không phù hợp để miêu tả hương vị hay chất lượng của bánh 'apple-cider donuts'.","C":"Chính xác: 'tasty' (thơm ngon) song hành hợp lý với 'Fresh' (tươi mới) để quảng bá món bánh đang bán tại cửa hàng.","D":"Mâu thuẫn dữ kiện câu: 'free' (miễn phí) trái ngược hoàn toàn với mức giá 'for £6 per dozen' được nêu ở cuối câu."},"evDocIdx":0,"evTargets":[{"badge":"Câu 103 · Đáp án C","opt":"C","isCorrect":true,"quote":"Fresh and ------- apple-cider donuts are available at Oakcrest Orchard's retail shop for £6 per dozen.","viQuote":"Bánh donut nước táo ép tươi mới và ------- hiện được bày bán tại cửa hàng bán lẻ của Oakcrest Orchard với giá £6 mỗi tá."},{"badge":"Câu 103 · Từ khóa C","opt":"C","isCorrect":true,"quote":"tasty","viQuote":"thơm ngon (adj)"}],"evQuotes":["Fresh and ------- apple-cider donuts are available at Oakcrest Orchard's retail shop for £6 per dozen.","tasty"]},{"q":104,"part":5,"group_id":null,"audio":null,"stem_en":"Zahn Flooring has the widest selection of ------- in the United Kingdom.","stem_vi":"Zahn Flooring sở hữu danh mục ------- đa dạng nhất tại Vương quốc Anh.","options":{"A":{"en":"paints","vi":"các loại sơn (n)"},"B":{"en":"tiles","vi":"gạch lát, gạch ốp lát (n)"},"C":{"en":"furniture","vi":"đồ nội thất (n)"},"D":{"en":"curtains","vi":"rèm cửa (n)"}},"ans":"B","explanation":"Đáp án đúng: (B) tiles — danh từ số nhiều nghĩa là 'gạch lát', phù hợp trực tiếp với lĩnh vực kinh doanh sàn nhà của 'Zahn Flooring'.\nDẫn chứng: \"Zahn Flooring has the widest selection of ------- in the United Kingdom.\" (Từ khóa 'Flooring' chỉ mảng sàn nhà là manh mối chốt nghĩa).\nPhân tích bẫy:\n- (A) 'paints' là các loại sơn tường, lệch sang mảng sơn phủ bề mặt chứ không phải sản phẩm đặc trưng của công ty 'Flooring'.\n- (C) 'furniture' là đồ nội thất như bàn ghế, tủ kệ, không phải vật liệu làm sàn nhà như tên doanh nghiệp gợi ý.\n- (D) 'curtains' là rèm cửa sổ, thuộc mảng trang trí cửa và không liên quan đến chuyên ngành 'Flooring'.","lines":[],"vocab":[{"word":"tile","pos":"n","ipa":"/taɪl/","meaning":"gạch lát, gạch ốp lát"},{"word":"selection","pos":"n","ipa":"/səˈlekʃən/","meaning":"danh mục lựa chọn, bộ sưu tập"},{"word":"flooring","pos":"n","ipa":"/ˈflɔːrɪŋ/","meaning":"vật liệu lát sàn"},{"word":"furniture","pos":"n","ipa":"/ˈfɜːrnɪtʃər/","meaning":"đồ nội thất"}],"isScanBacked":false,"grammarType":"Từ vựng — Danh từ (Noun)","formula":"CÔNG THỨC PART 5 (Từ vựng theo Chủ thể — Gắn tên doanh nghiệp): Chủ ngữ 'Zahn Flooring' cho biết công ty chuyên về vật liệu lót sàn, đứng sau 'widest selection of' cần danh từ vật liệu sàn -> Chọn 'tiles' (gạch lát).","optionAnalysis":{"A":"Lệch lĩnh vực: 'paints' (sơn) dùng để sơn tường hoặc bề mặt, không khớp với manh mối tên công ty 'Zahn Flooring' (chuyên sàn nhà).","B":"Chính xác: 'tiles' (gạch lát) khớp hoàn toàn với tên công ty 'Zahn Flooring' và cụm 'widest selection of'.","C":"Sai ngữ cảnh ngành hàng: 'furniture' (đồ nội thất) là vật dụng đặt trong phòng chứ không phải vật liệu lót sàn.","D":"Sai ngữ cảnh ngành hàng: 'curtains' (rèm cửa) không thuộc dòng sản phẩm cốt lõi của một đơn vị kinh doanh 'Flooring'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 104 · Đáp án B","opt":"B","isCorrect":true,"quote":"Zahn Flooring has the widest selection of ------- in the United Kingdom.","viQuote":"Zahn Flooring sở hữu danh mục ------- đa dạng nhất tại Vương quốc Anh."},{"badge":"Câu 104 · Từ khóa B","opt":"B","isCorrect":true,"quote":"tiles","viQuote":"gạch lát, gạch ốp lát (n)"}],"evQuotes":["Zahn Flooring has the widest selection of ------- in the United Kingdom.","tiles"]},{"q":105,"part":5,"group_id":null,"audio":null,"stem_en":"One responsibility of the IT department is to ensure that the company is using ------- software.","stem_vi":"Một trong những trách nhiệm của bộ phận CNTT là đảm bảo công ty đang sử dụng phần mềm -------.","options":{"A":{"en":"update","vi":"cập nhật (v/n)"},"B":{"en":"updating","vi":"đang cập nhật, việc cập nhật (V-ing)"},"C":{"en":"updates","vi":"các bản cập nhật / cập nhật (n số nhiều / v-s)"},"D":{"en":"updated","vi":"đã được cập nhật, phiên bản mới (adj/V-ed)"}},"ans":"D","explanation":"Đáp án đúng: (D) updated — tính từ dạng quá khứ phân từ mang nghĩa 'đã được cập nhật', bổ nghĩa cho danh từ không đếm được 'software'.\nDẫn chứng: \"One responsibility of the IT department is to ensure that the company is using ------- software.\" (Chỗ trống đứng trước danh từ 'software' sau động từ 'is using').\nPhân tích bẫy:\n- (A) 'update' là động từ nguyên thể hoặc danh từ số ít ('bản cập nhật'), không dùng làm tính từ bổ nghĩa cho danh từ 'software'.\n- (B) 'updating' là V-ing mang nghĩa chủ động 'đang cập nhật', không hợp lý vì phần mềm là vật được người/hệ thống cập nhật.\n- (C) 'updates' là động từ chia ngôi số ít hoặc danh từ số nhiều, ghép vào trước 'software' tạo cấu trúc sai ngữ pháp.","lines":[],"vocab":[{"word":"updated","pos":"adj","ipa":"/ʌpˈdeɪtɪd/","meaning":"đã được cập nhật, phiên bản mới"},{"word":"responsibility","pos":"n","ipa":"/rɪˌspɑːnsəˈbɪləti/","meaning":"trách nhiệm, bổn phận"},{"word":"ensure","pos":"v","ipa":"/ɪnˈʃʊr/","meaning":"đảm bảo"},{"word":"software","pos":"n","ipa":"/ˈsɔːftwer/","meaning":"phần mềm"}],"isScanBacked":false,"grammarType":"Từ loại (Word Form: Danh từ / Động từ / Tính từ / Trạng từ)","formula":"CÔNG THỨC PART 5 (Phân từ làm Tính từ — 'V-ing' vs 'V-ed' trước Danh từ): Trước danh từ không đếm được 'software', phần mềm là đối tượng chịu tác động cập nhật -> Chọn phân từ bị động 'updated' (đã cập nhật / phiên bản mới).","optionAnalysis":{"A":"Sai từ loại: 'update' là động từ hoặc danh từ số ít, không đóng vai trò tính từ bổ nghĩa cho 'software'.","B":"Sai nghĩa chủ động: 'updating' mang sắc thái đang tự thực hiện hành động, trong khi 'software' cần mang nghĩa đã được cập nhật.","C":"Sai ngữ pháp: 'updates' là động từ chia số ít hoặc danh từ số nhiều, không thể đứng bổ nghĩa trước danh từ không đếm được 'software'.","D":"Chính xác: 'updated' là quá khứ phân từ dùng như tính từ chỉ trạng thái phần mềm đã được cập nhật phiên bản mới."},"evDocIdx":0,"evTargets":[{"badge":"Câu 105 · Đáp án D","opt":"D","isCorrect":true,"quote":"One responsibility of the IT department is to ensure that the company is using ------- software.","viQuote":"Một trong những trách nhiệm của bộ phận CNTT là đảm bảo công ty đang sử dụng phần mềm -------."},{"badge":"Câu 105 · Từ khóa D","opt":"D","isCorrect":true,"quote":"updated","viQuote":"đã được cập nhật, phiên bản mới (adj/V-ed)"}],"evQuotes":["One responsibility of the IT department is to ensure that the company is using ------- software.","updated"]},{"q":106,"part":5,"group_id":null,"audio":null,"stem_en":"It is wise to check a company's dress code ------- visiting its head office.","stem_vi":"Việc kiểm tra quy định trang phục của một công ty ------- đến thăm trụ sở chính của công ty đó là điều rất khôn ngoan.","options":{"A":{"en":"so","vi":"vì vậy, do đó (conj/adv)"},"B":{"en":"how","vi":"như thế nào, cách thức (adv/conj)"},"C":{"en":"like","vi":"như, giống như (prep)"},"D":{"en":"before","vi":"trước khi (prep/conj)"}},"ans":"D","explanation":"Đáp án đúng: (D) before — giới từ/liên từ đứng trước V-ing 'visiting', mang nghĩa 'trước khi đến thăm trụ sở chính'.\nDẫn chứng: \"It is wise to check a company's dress code ------- visiting its head office.\" (Kiểm tra quy định trang phục phải diễn ra trước chuyến thăm).\nPhân tích bẫy:\n- (A) 'so' là liên từ chỉ kết quả đi với mệnh đề S+V, không đứng trực tiếp trước danh động từ 'visiting' và làm sai quan hệ nhân quả.\n- (B) 'how' là trạng từ nghi vấn chỉ cách thức ('như thế nào'), không nối được tân ngữ 'dress code' với cụm 'visiting its head office'.\n- (C) 'like' là giới từ mang nghĩa 'giống như', ghép vào câu thành so sánh vô nghĩa giữa kiểm tra trang phục và việc đến thăm.","lines":[],"vocab":[{"word":"dress code","pos":"n","ipa":"/dres koʊd/","meaning":"quy định trang phục"},{"word":"wise","pos":"adj","ipa":"/waɪz/","meaning":"khôn ngoan, sáng suốt"},{"word":"head office","pos":"n","ipa":"/hed ˈɔːfɪs/","meaning":"trụ sở chính"},{"word":"before","pos":"prep","ipa":"/bɪˈfɔːr/","meaning":"trước khi"}],"isScanBacked":false,"grammarType":"Phân biệt Giới từ (cụm N/V-ing) vs Liên từ (mệnh đề S+V)","formula":"CÔNG THỨC PART 5 (Tờ A3 Màu — Giới từ thời gian + V-ing): Phía sau chỗ trống là cụm danh động từ 'visiting its head office', cần giới từ chỉ trình tự thời gian hợp lý -> Chọn 'before' (trước khi đến thăm).","optionAnalysis":{"A":"Sai cấu trúc và nghĩa: 'so' là liên từ đẳng lập đòi hỏi mệnh đề S+V, không đi thẳng với V-ing 'visiting'.","B":"Sai ngữ pháp: 'how' không thể đóng vai trò giới từ nối giữa mệnh đề trước với cụm V-ing 'visiting its head office'.","C":"Sai ngữ nghĩa: 'like' (giống như) tạo phép so sánh vô lý với hành động 'check a company's dress code'.","D":"Chính xác: 'before' kết hợp chuẩn xác với V-ing 'visiting', diễn đạt trình tự hợp lý là kiểm tra trang phục trước khi đến thăm."},"evDocIdx":0,"evTargets":[{"badge":"Câu 106 · Đáp án D","opt":"D","isCorrect":true,"quote":"It is wise to check a company's dress code ------- visiting its head office.","viQuote":"Việc kiểm tra quy định trang phục của một công ty ------- đến thăm trụ sở chính của công ty đó là điều rất khôn ngoan."},{"badge":"Câu 106 · Từ khóa D","opt":"D","isCorrect":true,"quote":"before","viQuote":"trước khi (prep/conj)"}],"evQuotes":["It is wise to check a company's dress code ------- visiting its head office.","before"]},{"q":107,"part":5,"group_id":null,"audio":null,"stem_en":"Wexler Store's management team expects that employees will ------- support any new hires.","stem_vi":"Đội ngũ quản lý của Wexler Store kỳ vọng các nhân viên sẽ ------- hỗ trợ bất kỳ nhân sự mới tuyển nào.","options":{"A":{"en":"enthusiastically","vi":"một cách nhiệt tình, hào hứng (adv)"},"B":{"en":"enthusiasm","vi":"sự nhiệt tình, lòng hăng hái (n)"},"C":{"en":"enthusiastic","vi":"nhiệt tình, hăng hái (adj)"},"D":{"en":"enthused","vi":"hào hứng, phấn khởi (adj/V-ed)"}},"ans":"A","explanation":"Đáp án đúng: (A) enthusiastically — trạng từ bổ nghĩa cho động từ thường 'support' đứng ngay phía sau trợ động từ 'will'.\nDẫn chứng: \"Wexler Store's management team expects that employees will ------- support any new hires.\" (Cấu trúc Modal Verb 'will' + Adv + V-bare 'support').\nPhân tích bẫy:\n- (B) 'enthusiasm' là danh từ ('sự nhiệt tình'), không thể chèn vào giữa trợ động từ 'will' và động từ chính 'support'.\n- (C) 'enthusiastic' là tính từ ('nhiệt tình'), chỉ bổ nghĩa cho danh từ chứ không dùng để bổ nghĩa cho động từ 'support'.\n- (D) 'enthused' là tính từ/quá khứ phân từ chỉ cảm xúc ('hào hứng'), không có chức năng trạng từ bổ nghĩa cho hành động 'support'.","lines":[],"vocab":[{"word":"enthusiastically","pos":"adv","ipa":"/ɪnˌθuːziˈæstɪkli/","meaning":"một cách nhiệt tình, hào hứng"},{"word":"management team","pos":"n","ipa":"/ˈmænɪdʒmənt tiːm/","meaning":"đội ngũ quản lý"},{"word":"new hire","pos":"n","ipa":"/nuː ˈhaɪər/","meaning":"nhân sự mới tuyển"},{"word":"expect","pos":"v","ipa":"/ɪkˈspekt/","meaning":"kỳ vọng, mong đợi"}],"isScanBacked":false,"grammarType":"Từ loại (Word Form: Danh từ / Động từ / Tính từ / Trạng từ)","formula":"CÔNG THỨC PART 5 (Tờ A3 Màu — Trợ động từ + Trạng từ + Động từ nguyên mẫu): Giữa 'will' và động từ thường 'support', cần Trạng từ bổ nghĩa cho cách thức hỗ trợ -> Chọn 'enthusiastically' (một cách nhiệt tình).","optionAnalysis":{"A":"Chính xác: 'enthusiastically' là trạng từ đứng giữa 'will' và 'support' để bổ nghĩa trực tiếp cho động từ 'support'.","B":"Sai từ loại: 'enthusiasm' là danh từ, sai vị trí ngữ pháp khi xen vào giữa trợ động từ 'will' và động từ 'support'.","C":"Sai từ loại: 'enthusiastic' là tính từ, không thể dùng để bổ nghĩa cho động từ hành động 'support'.","D":"Sai từ loại: 'enthused' là tính từ chỉ trạng thái cảm xúc, không bổ nghĩa được cho động từ 'support'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 107 · Đáp án A","opt":"A","isCorrect":true,"quote":"Wexler Store's management team expects that employees will ------- support any new hires.","viQuote":"Đội ngũ quản lý của Wexler Store kỳ vọng các nhân viên sẽ ------- hỗ trợ bất kỳ nhân sự mới tuyển nào."},{"badge":"Câu 107 · Từ khóa A","opt":"A","isCorrect":true,"quote":"enthusiastically","viQuote":"một cách nhiệt tình, hào hứng (adv)"}],"evQuotes":["Wexler Store's management team expects that employees will ------- support any new hires.","enthusiastically"]},{"q":108,"part":5,"group_id":null,"audio":null,"stem_en":"Wheel alignments and brake system ------- are part of our vehicle service plan.","stem_vi":"Việc cân chỉnh bánh xe và ------- hệ thống phanh là một phần trong gói dịch vụ bảo dưỡng xe của chúng tôi.","options":{"A":{"en":"inspects","vi":"kiểm tra, thanh tra (v - ngôi 3 số ít)"},"B":{"en":"inspector","vi":"thanh tra viên, người kiểm tra (n)"},"C":{"en":"inspected","vi":"đã kiểm tra (V-ed)"},"D":{"en":"inspections","vi":"các đợt kiểm tra, việc kiểm định (n số nhiều)"}},"ans":"D","explanation":"Đáp án đúng: (D) inspections — danh từ số nhiều chỉ hoạt động ('các đợt kiểm tra'), song song về nghĩa và số nhiều với 'Wheel alignments' trước động từ 'are'.\nDẫn chứng: \"Wheel alignments and brake system ------- are part of our vehicle service plan.\" (Chủ ngữ ghép trước 'are' đòi hỏi danh từ chỉ hạng mục bảo dưỡng).\nPhân tích bẫy:\n- (A) 'inspects' là động từ chia ngôi thứ ba số ít, không thể đóng vai trò danh từ làm chủ ngữ đứng trước động từ chính 'are'.\n- (B) 'inspector' là danh từ số ít chỉ người ('thanh tra viên'), vừa sai nghĩa hạng mục dịch vụ vừa lệch dạng số nhiều của 'Wheel alignments'.\n- (C) 'inspected' là động từ quá khứ hoặc tính từ phân từ, khiến cụm 'brake system inspected' thiếu danh từ trung tâm làm chủ ngữ.","lines":[],"vocab":[{"word":"inspection","pos":"n","ipa":"/ɪnˈspekʃən/","meaning":"đợt kiểm tra, việc kiểm định"},{"word":"alignment","pos":"n","ipa":"/əˈlaɪnmənt/","meaning":"sự cân chỉnh (bánh xe)"},{"word":"brake system","pos":"n","ipa":"/breɪk ˈsɪstəm/","meaning":"hệ thống phanh"},{"word":"service plan","pos":"n","ipa":"/ˈsɜːrvɪs plæn/","meaning":"gói dịch vụ bảo dưỡng"}],"isScanBacked":false,"grammarType":"Từ loại (Word Form: Danh từ / Động từ / Tính từ / Trạng từ)","formula":"CÔNG THỨC PART 5 (Cấu trúc song song với 'and' + Hòa hợp chủ-vị): Cụm chủ ngữ 'Wheel alignments and brake system ___' nối với động từ số nhiều 'are' cần danh từ chỉ sự việc số nhiều -> Chọn 'inspections' (các đợt kiểm tra).","optionAnalysis":{"A":"Sai từ loại: 'inspects' là động từ chia thì, không thể làm danh từ chính cho cụm chủ ngữ đứng trước 'are'.","B":"Sai ngữ nghĩa và số: 'inspector' chỉ con người (thanh tra viên) ở số ít, không khớp hạng mục dịch vụ song song với 'Wheel alignments'.","C":"Sai từ loại: 'inspected' là động từ quá khứ/tính từ, làm cụm danh từ 'brake system ___' bị khuyết danh từ chính.","D":"Chính xác: 'inspections' là danh từ số nhiều chỉ hạng mục kiểm định, song hành chuẩn với 'Wheel alignments' trong gói dịch vụ."},"evDocIdx":0,"evTargets":[{"badge":"Câu 108 · Đáp án D","opt":"D","isCorrect":true,"quote":"Wheel alignments and brake system ------- are part of our vehicle service plan.","viQuote":"Việc cân chỉnh bánh xe và ------- hệ thống phanh là một phần trong gói dịch vụ bảo dưỡng xe của chúng tôi."},{"badge":"Câu 108 · Từ khóa D","opt":"D","isCorrect":true,"quote":"inspections","viQuote":"các đợt kiểm tra, việc kiểm định (n số nhiều)"}],"evQuotes":["Wheel alignments and brake system ------- are part of our vehicle service plan.","inspections"]},{"q":109,"part":5,"group_id":null,"audio":null,"stem_en":"Registration for the Marketing Coalition Conference is now open ------- September 30.","stem_vi":"Cổng đăng ký tham dự Hội nghị Marketing Coalition hiện đã mở ------- ngày 30 tháng 9.","options":{"A":{"en":"until","vi":"cho đến, tới tận (prep/conj)"},"B":{"en":"into","vi":"vào trong (prep)"},"C":{"en":"yet","vi":"chưa, tuy nhiên (adv/conj)"},"D":{"en":"while","vi":"trong khi, trong lúc (conj)"}},"ans":"A","explanation":"Đáp án đúng: (A) until — giới từ chỉ thời gian mang nghĩa 'cho đến tận', diễn đạt cổng đăng ký mở kéo dài tới hết ngày 30 tháng 9.\nDẫn chứng: \"Registration for the Marketing Coalition Conference is now open ------- September 30.\" (Cụm danh từ chỉ ngày 'September 30' cần một giới từ thời gian đứng trước).\nPhân tích bẫy:\n- (B) 'into' là giới từ chỉ hướng chuyển động vào bên trong không gian hoặc sự chuyển hóa, không dùng trước ngày tháng.\n- (C) 'yet' là trạng từ ('chưa') hoặc liên từ ('nhưng'), không có chức năng giới từ đứng trước cụm ngày 'September 30'.\n- (D) 'while' là liên từ phụ thuộc bắt buộc phải đi với một mệnh đề S+V đầy đủ, không thể đứng trước một mốc ngày đơn lẻ.","lines":[],"vocab":[{"word":"registration","pos":"n","ipa":"/ˌredʒɪˈstreɪʃən/","meaning":"việc đăng ký"},{"word":"coalition","pos":"n","ipa":"/ˌkoʊəˈlɪʃən/","meaning":"liên minh, hiệp hội"},{"word":"conference","pos":"n","ipa":"/ˈkɑːnfərəns/","meaning":"hội nghị"},{"word":"until","pos":"prep","ipa":"/ənˈtɪl/","meaning":"cho đến, tới tận"}],"isScanBacked":false,"grammarType":"Giới từ (Preposition)","formula":"CÔNG THỨC PART 5 (Tách Cụm Giới Từ & Mốc Thời Gian): Trước mốc thời gian kết thúc 'September 30' đi cùng trạng thái 'is now open' cần giới từ chỉ hạn chót -> Chọn 'until' (cho đến tận).","optionAnalysis":{"A":"Chính xác: 'until' là giới từ thời gian khớp với 'is now open', chỉ thời hạn kéo dài đến ngày 30 tháng 9.","B":"Sai nghĩa giới từ: 'into' diễn tả hướng đi vào trong, không dùng để nối với mốc thời gian kết thúc 'September 30'.","C":"Sai từ loại: 'yet' là trạng từ hoặc liên từ đẳng lập, không thể làm giới từ đứng trước danh từ chỉ ngày.","D":"Sai cấu trúc giới từ vs liên từ: 'while' là liên từ cần theo sau bởi mệnh đề S+V, không đi với cụm ngày 'September 30'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 109 · Đáp án A","opt":"A","isCorrect":true,"quote":"Registration for the Marketing Coalition Conference is now open ------- September 30.","viQuote":"Cổng đăng ký tham dự Hội nghị Marketing Coalition hiện đã mở ------- ngày 30 tháng 9."},{"badge":"Câu 109 · Từ khóa A","opt":"A","isCorrect":true,"quote":"until","viQuote":"cho đến, tới tận (prep/conj)"}],"evQuotes":["Registration for the Marketing Coalition Conference is now open ------- September 30.","until"]},{"q":110,"part":5,"group_id":null,"audio":null,"stem_en":"Growth in the home entertainment industry has been ------- this quarter.","stem_vi":"Sự tăng trưởng trong ngành giải trí tại gia đã ------- trong quý này.","options":{"A":{"en":"separate","vi":"riêng biệt, tách rời (adj)"},"B":{"en":"limited","vi":"hạn chế, bị hạn chế (adj)"},"C":{"en":"willing","vi":"sẵn lòng, tự nguyện (adj)"},"D":{"en":"assorted","vi":"đa dạng, đủ loại (adj)"}},"ans":"B","explanation":"Đáp án đúng: (B) limited — tính từ mang nghĩa 'bị hạn chế, ít ỏi', kết hợp tự nhiên với danh từ 'Growth' (sự tăng trưởng) trong báo cáo quý.\nDẫn chứng: \"Growth in the home entertainment industry has been ------- this quarter.\" (Chủ ngữ trừu tượng 'Growth' cần tính từ chỉ mức độ).\nPhân tích bẫy:\n- (A) 'separate' nghĩa là 'tách rời, riêng biệt', không dùng để đánh giá tốc độ hay quy mô tăng trưởng của một ngành.\n- (C) 'willing' nghĩa là 'sẵn lòng, tự nguyện', chỉ đi với chủ ngữ chỉ người hoặc tổ chức kèm 'to V', không dùng cho 'Growth'.\n- (D) 'assorted' nghĩa là 'đủ loại, hỗn hợp', dùng cho sản phẩm vật chất như bánh kẹo hoặc hàng hóa chứ không dùng cho 'Growth'.","lines":[],"vocab":[{"word":"limited","pos":"adj","ipa":"/ˈlɪmɪtɪd/","meaning":"hạn chế, có giới hạn"},{"word":"growth","pos":"n","ipa":"/ɡroʊθ/","meaning":"sự tăng trưởng"},{"word":"quarter","pos":"n","ipa":"/ˈkwɔːrtər/","meaning":"quý (3 tháng)"},{"word":"assorted","pos":"adj","ipa":"/əˈsɔːrtɪd/","meaning":"đa dạng, đủ loại"}],"isScanBacked":false,"grammarType":"Từ vựng — Tính từ (Adjective)","formula":"CÔNG THỨC PART 5 (Từ vựng Ngữ cảnh Kinh doanh — Chủ ngữ 'Growth'): Sau động từ nối 'has been', tính từ miêu tả mức độ tăng trưởng kinh tế 'Growth' trong quý -> Chọn 'limited' (hạn chế, khiêm tốn).","optionAnalysis":{"A":"Sai kết hợp nghĩa: 'separate' (tách biệt) không dùng để miêu tả mức độ tăng trưởng kinh tế trong quý.","B":"Chính xác: 'limited' (hạn chế) mô tả đúng tình trạng tăng trưởng chậm của ngành giải trí tại gia trong quý này.","C":"Sai đối tượng chủ ngữ: 'willing' (sẵn lòng) chỉ dùng cho con người hoặc chủ thể có ý chí, không đi với danh từ 'Growth'.","D":"Sai ngữ cảnh từ vựng: 'assorted' (đa dạng chủng loại) chỉ mô tả tập hợp đồ vật, không miêu tả mức độ tăng trưởng."},"evDocIdx":0,"evTargets":[{"badge":"Câu 110 · Đáp án B","opt":"B","isCorrect":true,"quote":"Growth in the home entertainment industry has been ------- this quarter.","viQuote":"Sự tăng trưởng trong ngành giải trí tại gia đã ------- trong quý này."},{"badge":"Câu 110 · Từ khóa B","opt":"B","isCorrect":true,"quote":"limited","viQuote":"hạn chế, bị hạn chế (adj)"}],"evQuotes":["Growth in the home entertainment industry has been ------- this quarter.","limited"]},{"q":111,"part":5,"group_id":null,"audio":null,"stem_en":"Hawson Furniture will be making ------- on the east side of town on Thursday.","stem_vi":"Hawson Furniture sẽ thực hiện ------- tại khu vực phía đông thị trấn vào thứ Năm.","options":{"A":{"en":"deliveries","vi":"các chuyến giao hàng, việc giao hàng (n số nhiều)"},"B":{"en":"delivered","vi":"đã giao hàng (V-ed)"},"C":{"en":"deliver","vi":"giao hàng (v - nguyên thể)"},"D":{"en":"deliverable","vi":"có thể giao được / sản phẩm bàn giao (adj/n)"}},"ans":"A","explanation":"Đáp án đúng: (A) deliveries — danh từ số nhiều làm tân ngữ trực tiếp cho động từ 'making' trong cụm cố định 'make deliveries' (thực hiện giao hàng).\nDẫn chứng: \"Hawson Furniture will be making ------- on the east side of town on Thursday.\" (Sau 'will be making' chưa có tân ngữ và không có mạo từ 'a').\nPhân tích bẫy:\n- (B) 'delivered' là động từ quá khứ hoặc quá khứ phân từ, không thể đứng làm tân ngữ trực tiếp ngay sau 'will be making'.\n- (C) 'deliver' là động từ nguyên thể, không dùng nối tiếp sau dạng tiếp diễn 'will be making' để làm tân ngữ.\n- (D) 'deliverable' là tính từ ('có thể giao') hoặc danh từ đếm được số ít ('sản phẩm bàn giao'), thiếu mạo từ 'a' và sai cụm từ.","lines":[],"vocab":[{"word":"delivery","pos":"n","ipa":"/dɪˈlɪvəri/","meaning":"chuyến giao hàng, việc giao hàng"},{"word":"furniture","pos":"n","ipa":"/ˈfɜːrnɪtʃər/","meaning":"đồ nội thất"},{"word":"deliverable","pos":"adj","ipa":"/dɪˈlɪvərəbəl/","meaning":"có thể giao được; sản phẩm bàn giao"},{"word":"make deliveries","pos":"phr","ipa":"/meɪk dɪˈlɪvəriz/","meaning":"thực hiện các chuyến giao hàng"}],"isScanBacked":false,"grammarType":"Từ loại (Word Form: Danh từ / Động từ / Tính từ / Trạng từ)","formula":"CÔNG THỨC PART 5 (Phân tích Cấu trúc S-V-O & Collocation): Sau ngoại động từ 'will be making' đang thiếu tân ngữ, kết hợp cụm cố định 'make deliveries' (giao hàng) -> Chọn danh từ số nhiều 'deliveries'.","optionAnalysis":{"A":"Chính xác: 'deliveries' là danh từ số nhiều hoàn chỉnh cụm 'make deliveries' làm tân ngữ cho 'will be making'.","B":"Sai từ loại: 'delivered' là động từ quá khứ/phân từ, không thể đóng vai trò tân ngữ sau ngoại động từ 'making'.","C":"Sai từ loại: 'deliver' là động từ nguyên mẫu, không thể làm tân ngữ trực tiếp cho cụm động từ 'will be making'.","D":"Sai số và ngữ pháp: 'deliverable' là tính từ hoặc danh từ đếm được số ít thiếu mạo từ, không khớp cụm 'make deliveries'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 111 · Đáp án A","opt":"A","isCorrect":true,"quote":"Hawson Furniture will be making ------- on the east side of town on Thursday.","viQuote":"Hawson Furniture sẽ thực hiện ------- tại khu vực phía đông thị trấn vào thứ Năm."},{"badge":"Câu 111 · Từ khóa A","opt":"A","isCorrect":true,"quote":"deliveries","viQuote":"các chuyến giao hàng, việc giao hàng (n số nhiều)"}],"evQuotes":["Hawson Furniture will be making ------- on the east side of town on Thursday.","deliveries"]},{"q":112,"part":5,"group_id":null,"audio":null,"stem_en":"The Marlton City Council does not have the authority to ------- parking on city streets.","stem_vi":"Hội đồng Thành phố Marlton không có thẩm quyền ------- việc đỗ xe trên các tuyến phố của thành phố.","options":{"A":{"en":"drive","vi":"lái xe (v)"},"B":{"en":"prohibit","vi":"cấm, nghiêm cấm (v)"},"C":{"en":"bother","vi":"làm phiền (v)"},"D":{"en":"travel","vi":"di chuyển, đi lại (v)"}},"ans":"B","explanation":"Đáp án đúng: (B) prohibit — ngoại động từ mang nghĩa 'cấm, nghiêm cấm', đi đúng nghĩa với chủ thể 'City Council' (Hội đồng Thành phố) và tân ngữ 'parking'.\nDẫn chứng: \"The Marlton City Council does not have the authority to ------- parking on city streets.\" (Cụm 'authority to ___ parking' nói về quyền cấm đỗ xe).\nPhân tích bẫy:\n- (A) 'drive' nghĩa là 'lái xe', không kết hợp thành cụm 'drive parking' và hội đồng thành phố không trực tiếp lái việc đỗ xe.\n- (C) 'bother' nghĩa là 'làm phiền', không mang sắc thái pháp lý phù hợp với thẩm quyền ('authority') của hội đồng thành phố.\n- (D) 'travel' là nội động từ nghĩa là 'di chuyển, đi lại', không nhận trực tiếp danh động từ 'parking' làm tân ngữ.","lines":[],"vocab":[{"word":"prohibit","pos":"v","ipa":"/prəˈhɪbɪt/","meaning":"cấm, nghiêm cấm"},{"word":"authority","pos":"n","ipa":"/əˈθɔːrəti/","meaning":"thẩm quyền, quyền hạn"},{"word":"city council","pos":"n","ipa":"/ˈsɪti ˈkaʊnsəl/","meaning":"hội đồng thành phố"},{"word":"bother","pos":"v","ipa":"/ˈbɑːðər/","meaning":"làm phiền"}],"isScanBacked":false,"grammarType":"Động từ (Verb & Collocation)","formula":"CÔNG THỨC PART 5 (Collocation Thực Chiến — Thẩm quyền + Tân ngữ 'parking'): Trong cấu trúc 'have the authority to + V + parking', động từ chỉ quyền lực quản lý đô thị phù hợp -> Chọn 'prohibit' (cấm).","optionAnalysis":{"A":"Sai kết hợp từ: 'drive' (lái xe) không tạo thành cụm có nghĩa với tân ngữ 'parking' trong ngữ cảnh thẩm quyền pháp lý.","B":"Chính xác: 'prohibit' (nghiêm cấm) khớp cả về ngữ pháp ngoại động từ lẫn thẩm quyền của Hội đồng Thành phố với việc đỗ xe.","C":"Sai văn phong và nghĩa: 'bother' (làm phiền) không phù hợp với chủ ngữ cơ quan công quyền 'City Council' và tân ngữ 'parking'.","D":"Sai ngữ pháp và nghĩa: 'travel' (đi lại) là nội động từ, không nhận trực tiếp 'parking' làm tân ngữ."},"evDocIdx":0,"evTargets":[{"badge":"Câu 112 · Đáp án B","opt":"B","isCorrect":true,"quote":"The Marlton City Council does not have the authority to ------- parking on city streets.","viQuote":"Hội đồng Thành phố Marlton không có thẩm quyền ------- việc đỗ xe trên các tuyến phố của thành phố."},{"badge":"Câu 112 · Từ khóa B","opt":"B","isCorrect":true,"quote":"prohibit","viQuote":"cấm, nghiêm cấm (v)"}],"evQuotes":["The Marlton City Council does not have the authority to ------- parking on city streets.","prohibit"]},{"q":113,"part":5,"group_id":null,"audio":null,"stem_en":"Project Earth Group is ------- for ways to reduce transport-related greenhouse gas emissions.","stem_vi":"Tổ chức Project Earth Group đang ------- các giải pháp nhằm cắt giảm lượng khí thải nhà kính liên quan đến giao thông vận tải.","options":{"A":{"en":"looking","vi":"tìm kiếm (look for) / nhìn (V-ing)"},"B":{"en":"seeing","vi":"nhìn thấy, xem xét (V-ing)"},"C":{"en":"driving","vi":"lái xe, thúc đẩy (V-ing)"},"D":{"en":"leaning","vi":"nghiêng, tựa vào (V-ing)"}},"ans":"A","explanation":"Đáp án đúng: (A) looking — kết hợp với giới từ 'for' ngay phía sau tạo cụm động từ 'is looking for' (đang tìm kiếm các giải pháp).\nDẫn chứng: \"Project Earth Group is ------- for ways to reduce transport-related greenhouse gas emissions.\" (Giới từ 'for' là dấu hiệu chốt cụm 'look for ways').\nPhân tích bẫy:\n- (B) 'seeing' nghĩa là 'nhìn thấy', là ngoại động từ đi thẳng với tân ngữ chứ không đi với 'for' theo nghĩa tìm kiếm giải pháp.\n- (C) 'driving' nghĩa là 'lái xe, thúc đẩy', không kết hợp với giới từ 'for' để diễn đạt ý tìm kiếm phương án.\n- (D) 'leaning' nghĩa là 'nghiêng, tựa vào', thường đi với giới từ 'on/against/toward' chứ không đi với 'for ways'.","lines":[],"vocab":[{"word":"look for","pos":"phr. v","ipa":"/lʊk fɔːr/","meaning":"tìm kiếm"},{"word":"reduce","pos":"v","ipa":"/rɪˈduːs/","meaning":"cắt giảm, làm giảm"},{"word":"emission","pos":"n","ipa":"/ɪˈmɪʃən/","meaning":"lượng khí thải"},{"word":"greenhouse gas","pos":"n","ipa":"/ˈɡriːnhaʊs ɡæs/","meaning":"khí nhà kính"}],"isScanBacked":false,"grammarType":"Động từ (Verb & Collocation)","formula":"CÔNG THỨC PART 5 (Collocation Động từ + Giới từ 'for'): Trước giới từ 'for' và tân ngữ 'ways to reduce…' cần động từ tạo thành cụm 'look for' (tìm kiếm) -> Chọn 'looking'.","optionAnalysis":{"A":"Chính xác: 'looking' ghép với giới từ 'for' tạo thành cụm cố định 'look for ways' (tìm kiếm cách thức).","B":"Sai giới từ đi kèm: 'seeing' là ngoại động từ nhận tân ngữ trực tiếp, không dùng 'see for' để diễn đạt nghĩa tìm kiếm.","C":"Sai ngữ nghĩa và cụm từ: 'driving' (lái, thúc đẩy) không kết hợp với giới từ 'for' trước cụm 'ways to reduce'.","D":"Sai giới từ và nghĩa: 'leaning' (tựa vào, nghiêng về) đi với 'on/against/toward', vô nghĩa khi ghép cùng 'for ways'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 113 · Đáp án A","opt":"A","isCorrect":true,"quote":"Project Earth Group is ------- for ways to reduce transport-related greenhouse gas emissions.","viQuote":"Tổ chức Project Earth Group đang ------- các giải pháp nhằm cắt giảm lượng khí thải nhà kính liên quan đến giao thông vận tải."},{"badge":"Câu 113 · Từ khóa A","opt":"A","isCorrect":true,"quote":"looking","viQuote":"tìm kiếm (look for) / nhìn (V-ing)"}],"evQuotes":["Project Earth Group is ------- for ways to reduce transport-related greenhouse gas emissions.","looking"]},{"q":114,"part":5,"group_id":null,"audio":null,"stem_en":"Our skilled tailors are happy to design a custom-made suit that fits your style and budget -------.","stem_vi":"Đội ngũ thợ may lành nghề của chúng tôi rất hân hạnh thiết kế một bộ vest may đo phù hợp với phong cách và ngân sách của bạn -------.","options":{"A":{"en":"perfect","vi":"hoàn hảo (adj) / hoàn thiện (v)"},"B":{"en":"perfects","vi":"hoàn thiện (v - ngôi 3 số ít)"},"C":{"en":"perfectly","vi":"một cách hoàn hảo (adv)"},"D":{"en":"perfection","vi":"sự hoàn hảo (n)"}},"ans":"C","explanation":"Đáp án đúng: (C) perfectly — trạng từ đứng cuối mệnh đề để bổ nghĩa cho động từ 'fits' ('vừa vặn một cách hoàn hảo').\nDẫn chứng: \"Our skilled tailors are happy to design a custom-made suit that fits your style and budget -------.\" (Đã đủ động từ 'fits' + tân ngữ 'your style and budget').\nPhân tích bẫy:\n- (A) 'perfect' là tính từ hoặc động từ nguyên thể, không thể đứng sau cụm tân ngữ để bổ nghĩa cho động từ thường 'fits'.\n- (B) 'perfects' là động từ chia ngôi thứ ba số ít, thừa động từ chia thì khi mệnh đề quan hệ đã có động từ 'fits'.\n- (D) 'perfection' là danh từ ('sự hoàn hảo'), đứng trơ trọi cuối câu sau cụm tân ngữ mà không có giới từ là sai ngữ pháp.","lines":[],"vocab":[{"word":"perfectly","pos":"adv","ipa":"/ˈpɜːrfɪktli/","meaning":"một cách hoàn hảo, vừa vặn"},{"word":"skilled","pos":"adj","ipa":"/skɪld/","meaning":"lành nghề, có tay nghề cao"},{"word":"tailor","pos":"n","ipa":"/ˈteɪlər/","meaning":"thợ may"},{"word":"custom-made","pos":"adj","ipa":"/ˌkʌstəm ˈmeɪd/","meaning":"được may đo riêng, đặt làm riêng"}],"isScanBacked":false,"grammarType":"Từ loại (Word Form: Danh từ / Động từ / Tính từ / Trạng từ)","formula":"CÔNG THỨC PART 5 (Cấu trúc S-V-O + Trạng từ cuối câu): Mệnh đề quan hệ 'that fits your style and budget ___' đã đủ S-V-O, vị trí cuối câu cần Trạng từ bổ nghĩa cho động từ 'fits' -> Chọn 'perfectly'.","optionAnalysis":{"A":"Sai từ loại: 'perfect' là tính từ hoặc động từ, không thể bổ nghĩa cho động từ 'fits' ở vị trí cuối mệnh đề.","B":"Sai cấu trúc câu: 'perfects' là động từ chia thì, gây lỗi hai động từ chính trong cùng mệnh đề sau 'fits'.","C":"Chính xác: 'perfectly' là trạng từ bổ nghĩa chuẩn xác cho cách thức của động từ 'fits' ở cuối câu.","D":"Sai từ loại: 'perfection' là danh từ, không thể đứng sau cụm tân ngữ 'your style and budget' làm bổ ngữ cho 'fits'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 114 · Đáp án C","opt":"C","isCorrect":true,"quote":"Our skilled tailors are happy to design a custom-made suit that fits your style and budget -------.","viQuote":"Đội ngũ thợ may lành nghề của chúng tôi rất hân hạnh thiết kế một bộ vest may đo phù hợp với phong cách và ngân sách của bạn -------."},{"badge":"Câu 114 · Từ khóa C","opt":"C","isCorrect":true,"quote":"perfectly","viQuote":"một cách hoàn hảo (adv)"}],"evQuotes":["Our skilled tailors are happy to design a custom-made suit that fits your style and budget -------.","perfectly"]},{"q":115,"part":5,"group_id":null,"audio":null,"stem_en":"Project manager Hannah Chung has proved to be very ------- with completing company projects.","stem_vi":"Quản lý dự án Hannah Chung đã chứng tỏ mình rất ------- trong việc hoàn thành các dự án của công ty.","options":{"A":{"en":"helpfulness","vi":"sự hữu ích, tính hay giúp đỡ (n)"},"B":{"en":"help","vi":"giúp đỡ (v) / sự giúp đỡ (n)"},"C":{"en":"helpfully","vi":"một cách hữu ích, tận tình (adv)"},"D":{"en":"helpful","vi":"hữu ích, có ích (adj)"}},"ans":"D","explanation":"Đáp án đúng: (D) helpful — tính từ đứng sau động từ nối 'be' và trạng từ chỉ mức độ 'very', hợp cụm 'helpful with + V-ing'.\nDẫn chứng: \"Project manager Hannah Chung has proved to be very ------- with completing company projects.\" (Cấu trúc 'to be + very + Adj').\nPhân tích bẫy:\n- (A) 'helpfulness' là danh từ ('sự hữu ích'), không thể đứng trực tiếp sau trạng từ bổ nghĩa 'very'.\n- (B) 'help' là động từ hoặc danh từ, hoàn toàn sai ngữ pháp khi đứng sau trạng từ chỉ mức độ 'very' và sau 'to be'.\n- (C) 'helpfully' là trạng từ, không dùng làm bổ ngữ miêu tả chủ ngữ 'Hannah Chung' sau động từ nối 'to be'.","lines":[],"vocab":[{"word":"helpful","pos":"adj","ipa":"/ˈhelpfəl/","meaning":"hữu ích, có ích"},{"word":"prove","pos":"v","ipa":"/pruːv/","meaning":"chứng tỏ, chứng minh"},{"word":"complete","pos":"v","ipa":"/kəmˈpliːt/","meaning":"hoàn thành"},{"word":"project manager","pos":"n","ipa":"/ˈprɑːdʒekt ˈmænɪdʒər/","meaning":"quản lý dự án"}],"isScanBacked":false,"grammarType":"Từ loại (Word Form: Danh từ / Động từ / Tính từ / Trạng từ)","formula":"CÔNG THỨC PART 5 (Tờ A3 Màu — Động từ nối 'be' + Trạng từ mức độ 'very' + Tính từ): Sau 'to be very' miêu tả phẩm chất của chủ ngữ 'Hannah Chung' bắt buộc là Tính từ -> Chọn 'helpful' (hữu ích, tận tình).","optionAnalysis":{"A":"Sai từ loại: 'helpfulness' là danh từ, không thể được bổ nghĩa trực tiếp bởi trạng từ chỉ mức độ 'very'.","B":"Sai từ loại: 'help' là động từ hoặc danh từ, không phù hợp cấu trúc 'to be + very + Adj'.","C":"Sai từ loại: 'helpfully' là trạng từ, không làm bổ ngữ tính chất cho chủ ngữ người sau động từ nối 'be'.","D":"Chính xác: 'helpful' là tính từ đứng sau 'to be very' và kết hợp tự nhiên với 'with completing company projects'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 115 · Đáp án D","opt":"D","isCorrect":true,"quote":"Project manager Hannah Chung has proved to be very ------- with completing company projects.","viQuote":"Quản lý dự án Hannah Chung đã chứng tỏ mình rất ------- trong việc hoàn thành các dự án của công ty."},{"badge":"Câu 115 · Từ khóa D","opt":"D","isCorrect":true,"quote":"helpful","viQuote":"hữu ích, có ích (adj)"}],"evQuotes":["Project manager Hannah Chung has proved to be very ------- with completing company projects.","helpful"]},{"q":116,"part":5,"group_id":null,"audio":null,"stem_en":"Lehua Vacation Club members will receive double points ------- the month of August at participating hotels.","stem_vi":"Hội viên của Lehua Vacation Club sẽ nhận được gấp đôi điểm thưởng ------- tháng 8 tại các khách sạn tham gia chương trình.","options":{"A":{"en":"onto","vi":"lên trên, sang (prep)"},"B":{"en":"above","vi":"ở phía trên, vượt mức (prep)"},"C":{"en":"during","vi":"trong suốt, trong khoảng thời gian (prep)"},"D":{"en":"between","vi":"ở giữa (prep)"}},"ans":"C","explanation":"Đáp án đúng: (C) during — giới từ chỉ thời gian mang nghĩa 'trong suốt, trong khoảng', dùng chuẩn trước cụm 'the month of August'.\nDẫn chứng: \"Lehua Vacation Club members will receive double points ------- the month of August at participating hotels.\" (Cụm 'the month of August' chỉ một khoảng thời gian cụ thể).\nPhân tích bẫy:\n- (A) 'onto' là giới từ không gian chỉ hướng chuyển động lên trên một bề mặt, không dùng cho thời gian.\n- (B) 'above' là giới từ chỉ vị trí cao hơn hoặc mức độ vượt quá, không kết hợp với danh từ chỉ tháng 'the month of August'.\n- (D) 'between' đòi hỏi hai mốc giới hạn nối bằng 'and' hoặc danh từ số nhiều, không đi với cụm số ít 'the month of August'.","lines":[],"vocab":[{"word":"during","pos":"prep","ipa":"/ˈdʊrɪŋ/","meaning":"trong suốt (khoảng thời gian)"},{"word":"double","pos":"adj","ipa":"/ˈdʌbəl/","meaning":"gấp đôi"},{"word":"participating","pos":"adj","ipa":"/pɑːrˈtɪsɪpeɪtɪŋ/","meaning":"có tham gia chương trình"},{"word":"member","pos":"n","ipa":"/ˈmembər/","meaning":"hội viên, thành viên"}],"isScanBacked":false,"grammarType":"Giới từ (Preposition)","formula":"CÔNG THỨC PART 5 (Tách Cụm Giới Từ Thời Gian): Trước danh từ chỉ khoảng thời gian xác định 'the month of August', dùng giới từ chỉ suốt khoảng thời gian -> Chọn 'during' (trong suốt).","optionAnalysis":{"A":"Sai loại giới từ: 'onto' diễn tả chuyển động lên bề mặt không gian, không dùng trước khoảng thời gian 'the month of August'.","B":"Sai loại giới từ: 'above' chỉ vị trí bên trên hoặc con số vượt ngưỡng, không kết hợp với tên tháng.","C":"Chính xác: 'during' là giới từ thời gian đứng trước 'the month of August' để chỉ toàn bộ tháng 8 diễn ra ưu đãi.","D":"Sai cấu trúc giới từ: 'between' cần hai mốc nối bằng 'and' hoặc danh từ số nhiều, không đi với 'the month of August'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 116 · Đáp án C","opt":"C","isCorrect":true,"quote":"Lehua Vacation Club members will receive double points ------- the month of August at participating hotels.","viQuote":"Hội viên của Lehua Vacation Club sẽ nhận được gấp đôi điểm thưởng ------- tháng 8 tại các khách sạn tham gia chương trình."},{"badge":"Câu 116 · Từ khóa C","opt":"C","isCorrect":true,"quote":"during","viQuote":"trong suốt, trong khoảng thời gian (prep)"}],"evQuotes":["Lehua Vacation Club members will receive double points ------- the month of August at participating hotels.","during"]},{"q":117,"part":5,"group_id":null,"audio":null,"stem_en":"The costumes were not received ------- enough to be used in the first dress rehearsal.","stem_vi":"Trang phục biểu diễn đã không được nhận đủ ------- để sử dụng trong buổi tổng duyệt đầu tiên.","options":{"A":{"en":"far","vi":"xa, nhiều (adv/adj)"},"B":{"en":"very","vi":"rất (adv)"},"C":{"en":"almost","vi":"gần như, hầu như (adv)"},"D":{"en":"soon","vi":"sớm (adv)"}},"ans":"D","explanation":"Đáp án đúng: (D) soon — trạng từ chỉ thời gian, tạo cấu trúc 'soon enough to be used' (đủ sớm để kịp sử dụng cho buổi tổng duyệt đầu tiên).\nDẫn chứng: \"The costumes were not received ------- enough to be used in the first dress rehearsal.\" (Trang phục đến trễ nên không kịp dùng cho buổi tổng duyệt).\nPhân tích bẫy:\n- (A) 'far' là trạng từ chỉ khoảng cách địa lý hoặc mức độ ('xa/nhiều'), không phù hợp ngữ cảnh nhận hàng kịp tiến độ.\n- (B) 'very' là phó từ nhấn mạnh, không thể đứng ngay trước 'enough' theo cấu trúc 'very enough to V'.\n- (C) 'almost' nghĩa là 'gần như, suýt chút nữa', không kết hợp được trong cấu trúc '___ enough to be used'.","lines":[],"vocab":[{"word":"soon","pos":"adv","ipa":"/suːn/","meaning":"sớm"},{"word":"costume","pos":"n","ipa":"/ˈkɑːstuːm/","meaning":"trang phục biểu diễn"},{"word":"dress rehearsal","pos":"n","ipa":"/dres rɪˈhɜːrsəl/","meaning":"buổi tổng duyệt"},{"word":"receive","pos":"v","ipa":"/rɪˈsiːv/","meaning":"nhận được"}],"isScanBacked":false,"grammarType":"Từ vựng — Trạng từ (Adverb)","formula":"CÔNG THỨC PART 5 (Từ vựng Trạng từ + 'enough to V'): Trước 'enough to be used in the first dress rehearsal', cần trạng từ chỉ thời điểm kịp lúc -> Chọn 'soon' (đủ sớm để).","optionAnalysis":{"A":"Sai ngữ nghĩa: 'far' chỉ khoảng cách hoặc mức độ, không diễn đạt được ý nhận trang phục kịp thời gian tổng duyệt.","B":"Sai cấu trúc ngữ pháp: phó từ 'very' không đứng trước 'enough' để tạo thành 'very enough to V'.","C":"Sai kết hợp từ: 'almost' (hầu như) không đi trước 'enough to' để bổ nghĩa cho động từ 'received'.","D":"Chính xác: 'soon' tạo cụm 'not received soon enough to be used' (không nhận được đủ sớm để kịp sử dụng)."},"evDocIdx":0,"evTargets":[{"badge":"Câu 117 · Đáp án D","opt":"D","isCorrect":true,"quote":"The costumes were not received ------- enough to be used in the first dress rehearsal.","viQuote":"Trang phục biểu diễn đã không được nhận đủ ------- để sử dụng trong buổi tổng duyệt đầu tiên."},{"badge":"Câu 117 · Từ khóa D","opt":"D","isCorrect":true,"quote":"soon","viQuote":"sớm (adv)"}],"evQuotes":["The costumes were not received ------- enough to be used in the first dress rehearsal.","soon"]},{"q":118,"part":5,"group_id":null,"audio":null,"stem_en":"As a former publicist for several renowned orchestras, Mr. Wu would excel in the role of event -------.","stem_vi":"Từng là chuyên viên truyền thông cho nhiều dàn nhạc danh tiếng, ông Wu sẽ hoàn thành xuất sắc vai trò ------- sự kiện.","options":{"A":{"en":"organized","vi":"có tổ chức, đã được tổ chức (adj/V-ed)"},"B":{"en":"organizer","vi":"nhà tổ chức, người tổ chức (n)"},"C":{"en":"organizes","vi":"tổ chức (v - ngôi 3 số ít)"},"D":{"en":"organizational","vi":"thuộc về tổ chức (adj)"}},"ans":"B","explanation":"Đáp án đúng: (B) organizer — danh từ chỉ người ('nhà tổ chức'), tạo thành chức danh 'event organizer' (người tổ chức sự kiện) cho ông Wu.\nDẫn chứng: \"As a former publicist for several renowned orchestras, Mr. Wu would excel in the role of event -------.\" (Cần danh từ làm thành phần chính cho cụm 'the role of event ___').\nPhân tích bẫy:\n- (A) 'organized' là tính từ hoặc phân từ ('ngăn nắp, được tổ chức'), khiến cụm sau giới từ 'of' bị thiếu danh từ chính.\n- (C) 'organizes' là động từ chia ngôi thứ ba số ít, hoàn toàn không thể đứng sau danh từ 'event' trong cụm giới từ 'of'.\n- (D) 'organizational' là tính từ ('thuộc về tổ chức'), không phải danh từ chỉ vai trò công việc như ngữ cảnh yêu cầu.","lines":[],"vocab":[{"word":"organizer","pos":"n","ipa":"/ˈɔːrɡənaɪzər/","meaning":"nhà tổ chức, người tổ chức"},{"word":"publicist","pos":"n","ipa":"/ˈpʌblɪsɪst/","meaning":"chuyên viên truyền thông, quan hệ công chúng"},{"word":"renowned","pos":"adj","ipa":"/rɪˈnaʊnd/","meaning":"danh tiếng, lừng danh"},{"word":"excel in","pos":"phr. v","ipa":"/ɪkˈsel ɪn/","meaning":"làm xuất sắc, vượt trội ở"}],"isScanBacked":false,"grammarType":"Từ loại (Word Form: Danh từ / Động từ / Tính từ / Trạng từ)","formula":"CÔNG THỨC PART 5 (Tờ A3 Màu — Danh từ ghép chỉ nghề nghiệp 'event + N người'): Sau 'the role of event ___' chỉ vai trò đảm nhiệm của 'Mr. Wu', cần danh từ chỉ người -> Chọn 'organizer' (nhà tổ chức).","optionAnalysis":{"A":"Sai từ loại: 'organized' là tính từ/phân từ, làm cụm 'the role of event ___' bị thiếu danh từ chính chỉ vai trò.","B":"Chính xác: 'organizer' là danh từ chỉ người, kết hợp với 'event' thành cụm danh từ chỉ chức danh 'event organizer'.","C":"Sai từ loại: 'organizes' là động từ chia thì, không thể đứng ở vị trí tân ngữ của giới từ 'of'.","D":"Sai từ loại: 'organizational' là tính từ, không thể đóng vai trò danh từ trung tâm sau 'event'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 118 · Đáp án B","opt":"B","isCorrect":true,"quote":"As a former publicist for several renowned orchestras, Mr. Wu would excel in the role of event -------.","viQuote":"Từng là chuyên viên truyền thông cho nhiều dàn nhạc danh tiếng, ông Wu sẽ hoàn thành xuất sắc vai trò ------- sự kiện."},{"badge":"Câu 118 · Từ khóa B","opt":"B","isCorrect":true,"quote":"organizer","viQuote":"nhà tổ chức, người tổ chức (n)"}],"evQuotes":["As a former publicist for several renowned orchestras, Mr. Wu would excel in the role of event -------.","organizer"]},{"q":119,"part":5,"group_id":null,"audio":null,"stem_en":"The northbound lane on Davis Street will be ------- closed because of the city's bridge reinforcement project.","stem_vi":"Làn đường hướng bắc trên phố Davis sẽ ------- bị đóng do dự án gia cố cầu của thành phố.","options":{"A":{"en":"temporarily","vi":"tạm thời (adv)"},"B":{"en":"competitively","vi":"một cách cạnh tranh (adv)"},"C":{"en":"recently","vi":"gần đây (adv)"},"D":{"en":"collectively","vi":"cùng nhau, mang tính tập thể (adv)"}},"ans":"A","explanation":"Đáp án đúng: (A) temporarily — trạng từ nghĩa là 'tạm thời', khớp hoàn toàn với tình huống đóng làn đường phục vụ dự án gia cố cầu.\nDẫn chứng: \"The northbound lane on Davis Street will be ------- closed because of the city's bridge reinforcement project.\" (Dự án sửa chữa cầu chỉ khiến đường đóng tạm thời).\nPhân tích bẫy:\n- (B) 'competitively' nghĩa là 'một cách cạnh tranh', thường dùng cho giá cả hoặc thị trường, vô nghĩa khi ghép với 'closed'.\n- (C) 'recently' nghĩa là 'gần đây', chỉ thời gian trong quá khứ gần nên mâu thuẫn với thì tương lai 'will be closed'.\n- (D) 'collectively' nghĩa là 'tập thể, cùng nhau', không hợp lý khi nói về một làn đường duy nhất ('The northbound lane').","lines":[],"vocab":[{"word":"temporarily","pos":"adv","ipa":"/ˌtempəˈrerəli/","meaning":"tạm thời"},{"word":"lane","pos":"n","ipa":"/leɪn/","meaning":"làn đường"},{"word":"reinforcement","pos":"n","ipa":"/ˌriːɪnˈfɔːrsmənt/","meaning":"việc gia cố, tăng cường"},{"word":"collectively","pos":"adv","ipa":"/kəˈlektɪvli/","meaning":"cùng nhau, mang tính tập thể"}],"isScanBacked":false,"grammarType":"Từ vựng — Trạng từ (Adverb)","formula":"CÔNG THỨC PART 5 (Từ vựng Ngữ cảnh — Động từ bị động 'will be ___ closed'): Việc đóng làn đường vì dự án gia cố cầu diễn ra trong một khoảng thời gian dự án -> Chọn 'temporarily' (tạm thời).","optionAnalysis":{"A":"Chính xác: 'temporarily' (tạm thời) hợp nghĩa với trạng thái đóng làn đường trong thời gian thi công gia cố cầu.","B":"Sai ngữ nghĩa: 'competitively' (cạnh tranh) không thể bổ nghĩa cho động từ 'closed' trong thông báo giao thông.","C":"Mâu thuẫn thì: 'recently' (gần đây) dùng cho mốc quá khứ/hiện tại hoàn thành, xung đột với thì tương lai 'will be closed'.","D":"Sai ngữ nghĩa: 'collectively' (mang tính tập thể) không phù hợp để mô tả việc đóng một làn đường hướng bắc."},"evDocIdx":0,"evTargets":[{"badge":"Câu 119 · Đáp án A","opt":"A","isCorrect":true,"quote":"The northbound lane on Davis Street will be ------- closed because of the city's bridge reinforcement project.","viQuote":"Làn đường hướng bắc trên phố Davis sẽ ------- bị đóng do dự án gia cố cầu của thành phố."},{"badge":"Câu 119 · Từ khóa A","opt":"A","isCorrect":true,"quote":"temporarily","viQuote":"tạm thời (adv)"}],"evQuotes":["The northbound lane on Davis Street will be ------- closed because of the city's bridge reinforcement project.","temporarily"]},{"q":120,"part":5,"group_id":null,"audio":null,"stem_en":"Airline representatives must handle a wide range of passenger issues, ------- missed connections to lost luggage.","stem_vi":"Nhân viên đại diện hãng hàng không phải xử lý rất nhiều vấn đề của hành khách, ------- việc lỡ chuyến nối đến thất lạc hành lý.","options":{"A":{"en":"from","vi":"từ (prep)"},"B":{"en":"under","vi":"dưới, theo (prep)"},"C":{"en":"on","vi":"trên, vào (prep)"},"D":{"en":"against","vi":"chống lại, đối chiếu với (prep)"}},"ans":"A","explanation":"Đáp án đúng: (A) from — kết hợp với giới từ 'to' phía sau tạo thành cặp cấu trúc 'from A to B' (từ việc lỡ chuyến nối đến thất lạc hành lý).\nDẫn chứng: \"Airline representatives must handle a wide range of passenger issues, ------- missed connections to lost luggage.\" (Cụm 'a wide range of… from… to…').\nPhân tích bẫy:\n- (B) 'under' nghĩa là 'ở dưới, theo quy định của', không tạo được cặp đối xứng với 'to' để liệt kê phạm vi vấn đề.\n- (C) 'on' nghĩa là 'trên, về chủ đề', không đi kèm với 'to' trong cấu trúc liệt kê từ trường hợp này sang trường hợp khác.\n- (D) 'against' nghĩa là 'chống lại', sai hoàn toàn về nghĩa lẫn cấu trúc song hành với 'to' phía sau.","lines":[],"vocab":[{"word":"representative","pos":"n","ipa":"/ˌreprɪˈzentətɪv/","meaning":"nhân viên đại diện"},{"word":"a wide range of","pos":"phr","ipa":"/ə waɪd reɪndʒ ʌv/","meaning":"rất nhiều, đa dạng"},{"word":"missed connection","pos":"n","ipa":"/mɪst kəˈnekʃən/","meaning":"chuyến nối bị lỡ"},{"word":"luggage","pos":"n","ipa":"/ˈlʌɡɪdʒ/","meaning":"hành lý"}],"isScanBacked":false,"grammarType":"Giới từ (Preposition)","formula":"CÔNG THỨC PART 5 (Cặp Giới từ Cố định 'from A to B'): Phía sau có giới từ 'to' nối hai ví dụ liệt kê phạm vi ('missed connections to lost luggage') -> Chọn 'from' để hoàn chỉnh cặp 'from A to B'.","optionAnalysis":{"A":"Chính xác: 'from' phối hợp với 'to' tạo thành cấu trúc chuẩn 'from missed connections to lost luggage' minh họa cho 'a wide range of'.","B":"Sai cấu trúc cặp giới từ: 'under' không ghép cặp với 'to' để diễn đạt phạm vi liệt kê các vấn đề.","C":"Sai cấu trúc cặp giới từ: 'on' không hình thành cụm chỉ dải phạm vi '___ A to B'.","D":"Sai nghĩa và cấu trúc: 'against' (chống lại) không phù hợp ngữ cảnh xử lý sự cố và không đi cặp với 'to'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 120 · Đáp án A","opt":"A","isCorrect":true,"quote":"Airline representatives must handle a wide range of passenger issues, ------- missed connections to lost luggage.","viQuote":"Nhân viên đại diện hãng hàng không phải xử lý rất nhiều vấn đề của hành khách, ------- việc lỡ chuyến nối đến thất lạc hành lý."},{"badge":"Câu 120 · Từ khóa A","opt":"A","isCorrect":true,"quote":"from","viQuote":"từ (prep)"}],"evQuotes":["Airline representatives must handle a wide range of passenger issues, ------- missed connections to lost luggage.","from"]},{"q":121,"part":5,"group_id":null,"audio":null,"stem_en":"The meeting notes were ------- deleted, but Mr. Hahm was able to recreate them from memory.","stem_vi":"Biên bản ghi chú cuộc họp đã ------- bị xóa, nhưng ông Hahm đã có thể khôi phục lại chúng từ trí nhớ.","options":{"A":{"en":"accident","vi":"tai nạn, sự cố (n - số ít)"},"B":{"en":"accidental","vi":"tình cờ, vô ý (adj)"},"C":{"en":"accidents","vi":"các tai nạn, sự cố (n - số nhiều)"},"D":{"en":"accidentally","vi":"vô tình, tình cờ (adv)"}},"ans":"D","explanation":"Đáp án đúng: (D) accidentally — trạng từ nghĩa là 'vô tình', đứng giữa 'were' và phân từ 'deleted' để bổ nghĩa cho động từ bị xóa.\nDẫn chứng: \"The meeting notes were ------- deleted, but Mr. Hahm was able to recreate them from memory.\" (Ông Hahm phải khôi phục lại chứng tỏ việc xóa là vô tình).\nPhân tích bẫy:\n- (A) 'accident' là danh từ số ít ('tai nạn'), không thể chen giữa động từ 'were' và quá khứ phân từ 'deleted'.\n- (B) 'accidental' là tính từ ('tình cờ'), chỉ bổ nghĩa cho danh từ chứ không bổ nghĩa cho động từ bị động 'were deleted'.\n- (C) 'accidents' là danh từ số nhiều, sai hoàn toàn về chức năng từ loại tại vị trí bổ nghĩa cho động từ 'deleted'.","lines":[],"vocab":[{"word":"accidentally","pos":"adv","ipa":"/ˌæksɪˈdentəli/","meaning":"vô tình, tình cờ"},{"word":"delete","pos":"v","ipa":"/dɪˈliːt/","meaning":"xóa bỏ"},{"word":"recreate","pos":"v","ipa":"/ˌriːkriˈeɪt/","meaning":"khôi phục lại, tái tạo lại"},{"word":"from memory","pos":"phr","ipa":"/frʌm ˈmeməri/","meaning":"từ trí nhớ"}],"isScanBacked":false,"grammarType":"Từ loại (Word Form: Danh từ / Động từ / Tính từ / Trạng từ)","formula":"CÔNG THỨC PART 5 (Tờ A3 Màu — 'be + Adv + V3/ed'): Giữa trợ động từ 'were' và quá khứ phân từ 'deleted' cần Trạng từ bổ nghĩa cho cách thức hành động -> Chọn 'accidentally' (vô tình, ngoài ý muốn).","optionAnalysis":{"A":"Sai từ loại: 'accident' là danh từ số ít, không thể đứng giữa 'were' và phân từ 'deleted' để bổ nghĩa cho động từ.","B":"Sai từ loại: 'accidental' là tính từ, không dùng để bổ nghĩa cho động từ ở thể bị động 'were deleted'.","C":"Sai từ loại: 'accidents' là danh từ số nhiều, sai vị trí ngữ pháp giữa 'were' và 'deleted'.","D":"Chính xác: 'accidentally' là trạng từ đứng đúng vị trí giữa 'were' và 'deleted', khớp nghĩa phải khôi phục lại ghi chú."},"evDocIdx":0,"evTargets":[{"badge":"Câu 121 · Đáp án D","opt":"D","isCorrect":true,"quote":"The meeting notes were ------- deleted, but Mr. Hahm was able to recreate them from memory.","viQuote":"Biên bản ghi chú cuộc họp đã ------- bị xóa, nhưng ông Hahm đã có thể khôi phục lại chúng từ trí nhớ."},{"badge":"Câu 121 · Từ khóa D","opt":"D","isCorrect":true,"quote":"accidentally","viQuote":"vô tình, tình cờ (adv)"}],"evQuotes":["The meeting notes were ------- deleted, but Mr. Hahm was able to recreate them from memory.","accidentally"]},{"q":122,"part":5,"group_id":null,"audio":null,"stem_en":"The current issue of Farming Scene magazine predicts that the price of corn will rise 5 percent over the ------- year.","stem_vi":"Số phát hành hiện tại của tạp chí Farming Scene dự báo giá ngô sẽ tăng 5% trong năm -------.","options":{"A":{"en":"next","vi":"tới, tiếp theo (adj/det)"},"B":{"en":"with","vi":"với, cùng với (prep)"},"C":{"en":"which","vi":"mà, cái nào (pron/det)"},"D":{"en":"now","vi":"bây giờ, hiện nay (adv)"}},"ans":"A","explanation":"Đáp án đúng: (A) next — tính từ đứng giữa mạo từ 'the' và danh từ 'year', tạo cụm 'over the next year' (trong vòng năm tới) khớp với thì tương lai 'will rise'.\nDẫn chứng: \"The current issue of Farming Scene magazine predicts that the price of corn will rise 5 percent over the ------- year.\" (Động từ 'will rise' chỉ dự báo tương lai).\nPhân tích bẫy:\n- (B) 'with' là giới từ, hoàn toàn không thể đứng lọt vào giữa mạo từ 'the' và danh từ 'year'.\n- (C) 'which' là đại từ hoặc từ hạn định nghi vấn/quan hệ, không đứng sau mạo từ 'the' để tạo cụm 'the which year'.\n- (D) 'now' là trạng từ chỉ thời điểm hiện tại, không dùng làm tính từ đứng giữa 'the' và 'year'.","lines":[],"vocab":[{"word":"current issue","pos":"n","ipa":"/ˈkɜːrənt ˈɪʃuː/","meaning":"số phát hành hiện tại (tạp chí)"},{"word":"predict","pos":"v","ipa":"/prɪˈdɪkt/","meaning":"dự báo, dự đoán"},{"word":"rise","pos":"v","ipa":"/raɪz/","meaning":"tăng lên"},{"word":"next","pos":"adj","ipa":"/nekst/","meaning":"tới, tiếp theo"}],"isScanBacked":false,"grammarType":"Từ vựng & Ngữ cảnh TOEIC (Vocabulary in Context)","formula":"CÔNG THỨC PART 5 (Mốc Thời Gian Tương Lai — 'over the ___ year'): Mệnh đề dự báo thì tương lai 'will rise 5 percent' yêu cầu tính từ chỉ năm sắp tới nằm giữa 'the' và 'year' -> Chọn 'next' (năm tới).","optionAnalysis":{"A":"Chính xác: 'next' đứng đúng vị trí giữa 'the' và 'year' ('the next year'), phù hợp với dự báo tương lai 'will rise'.","B":"Sai từ loại: 'with' là giới từ, không thể đứng sau mạo từ 'the' để bổ nghĩa cho danh từ 'year'.","C":"Sai ngữ pháp: 'which' không thể kết hợp sau mạo từ xác định 'the' trong cụm danh từ 'the ___ year'.","D":"Sai từ loại và thì: 'now' là trạng từ thời gian hiện tại, không làm tính từ kẹp giữa 'the' và 'year'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 122 · Đáp án A","opt":"A","isCorrect":true,"quote":"The current issue of Farming Scene magazine predicts that the price of corn will rise 5 percent over the ------- year.","viQuote":"Số phát hành hiện tại của tạp chí Farming Scene dự báo giá ngô sẽ tăng 5% trong năm -------."},{"badge":"Câu 122 · Từ khóa A","opt":"A","isCorrect":true,"quote":"next","viQuote":"tới, tiếp theo (adj/det)"}],"evQuotes":["The current issue of Farming Scene magazine predicts that the price of corn will rise 5 percent over the ------- year.","next"]},{"q":123,"part":5,"group_id":null,"audio":null,"stem_en":"Anyone who still ------- to take the fire safety training should do so before the end of the month.","stem_vi":"Bất kỳ ai vẫn ------- tham gia khóa tập huấn an toàn phòng cháy chữa cháy nên hoàn thành trước cuối tháng.","options":{"A":{"en":"needing","vi":"đang cần (V-ing)"},"B":{"en":"needs","vi":"cần (v - hiện tại đơn, số ít)"},"C":{"en":"has needed","vi":"đã cần (v - hiện tại hoàn thành)"},"D":{"en":"were needing","vi":"đã đang cần (v - quá khứ tiếp diễn, số nhiều)"}},"ans":"B","explanation":"Đáp án đúng: (B) needs — động từ chia thì hiện tại đơn ở ngôi số ít, hòa hợp với chủ ngữ đại từ bất định 'Anyone' và trạng từ 'still'.\nDẫn chứng: \"Anyone who still ------- to take the fire safety training should do so before the end of the month.\" (Mệnh đề quan hệ 'who still ___' cần động từ chia thì ngôi số ít).\nPhân tích bẫy:\n- (A) 'needing' là phân từ V-ing đứng một mình, không có trợ động từ 'is' nên không tạo được động từ chia thì hoàn chỉnh cho mệnh đề 'who'.\n- (C) 'has needed' là thì hiện tại hoàn thành, nhấn mạnh việc cần kéo dài từ quá khứ hơn là tình trạng hiện tại đi với 'still' và lời khuyên 'should do so'.\n- (D) 'were needing' vừa sai thì quá khứ tiếp diễn (động từ trạng thái 'need' không chia tiếp diễn), vừa sai số nhiều so với 'Anyone'.","lines":[],"vocab":[{"word":"need","pos":"v","ipa":"/niːd/","meaning":"cần"},{"word":"fire safety","pos":"n","ipa":"/ˈfaɪər ˈseɪfti/","meaning":"an toàn phòng cháy chữa cháy"},{"word":"training","pos":"n","ipa":"/ˈtreɪnɪŋ/","meaning":"khóa tập huấn, đào tạo"},{"word":"before the end of","pos":"phr","ipa":"/bɪˈfɔːr ði end ʌv/","meaning":"trước khi kết thúc"}],"isScanBacked":false,"grammarType":"Chia động từ — Thì / Thể (Bị động - Chủ động) / Dạng V-ing · to V","formula":"CÔNG THỨC PART 5 (Hòa hợp Chủ-Vị với Đại từ bất định 'Anyone'): Đại từ bất định 'Anyone' luôn chia động từ số ít; trạng từ 'still' cùng lời khuyên 'should do so' chốt thì Hiện tại đơn -> Chọn 'needs'.","optionAnalysis":{"A":"Thiếu động từ chia thì: 'needing' là dạng V-ing không thể tự làm động từ chính cho mệnh đề quan hệ 'who still ___'.","B":"Chính xác: 'needs' chia thì hiện tại đơn số ít đúng với chủ ngữ 'Anyone' và ngữ cảnh nhắc nhở hiện tại.","C":"Sai sắc thái thì: 'has needed' diễn đạt quá trình đã cần từ trước, không tự nhiên bằng hiện tại đơn cùng 'still' và 'should do so'.","D":"Sai cả thì và số: 'were needing' chia quá khứ tiếp diễn số nhiều, sai với chủ ngữ số ít 'Anyone' và động từ trạng thái 'need'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 123 · Đáp án B","opt":"B","isCorrect":true,"quote":"Anyone who still ------- to take the fire safety training should do so before the end of the month.","viQuote":"Bất kỳ ai vẫn ------- tham gia khóa tập huấn an toàn phòng cháy chữa cháy nên hoàn thành trước cuối tháng."},{"badge":"Câu 123 · Từ khóa B","opt":"B","isCorrect":true,"quote":"needs","viQuote":"cần (v - hiện tại đơn, số ít)"}],"evQuotes":["Anyone who still ------- to take the fire safety training should do so before the end of the month.","needs"]},{"q":124,"part":5,"group_id":null,"audio":null,"stem_en":"Emerging technologies have ------- begun to transform the shipping industry in ways that were once unimaginable.","stem_vi":"Các công nghệ mới nổi đã ------- bắt đầu chuyển đổi ngành vận tải biển theo những cách từng không thể tưởng tượng nổi.","options":{"A":{"en":"already","vi":"đã sớm, đã rồi (adv)"},"B":{"en":"exactly","vi":"chính xác (adv)"},"C":{"en":"hardly","vi":"hầu như không (adv)"},"D":{"en":"closely","vi":"chặt chẽ, sát sao (adv)"}},"ans":"A","explanation":"Đáp án đúng: (A) already — trạng từ đứng giữa trợ động từ 'have' và phân từ 'begun', nhấn mạnh sự chuyển đổi 'đã bắt đầu diễn ra rồi'.\nDẫn chứng: \"Emerging technologies have ------- begun to transform the shipping industry in ways that were once unimaginable.\" (Thì hiện tại hoàn thành 'have… begun' kết hợp đặc trưng với 'already').\nPhân tích bẫy:\n- (B) 'exactly' nghĩa là 'chính xác', thường đi với số liệu, thời điểm hay vị trí cụ thể chứ không ghép vào 'have ___ begun'.\n- (C) 'hardly' mang nghĩa phủ định 'hầu như không', làm đảo ngược ý khẳng định công nghệ đang biến đổi ngành vận tải.\n- (D) 'closely' nghĩa là 'chặt chẽ, sát sao', thường đi với động từ như 'monitor, follow, work' chứ không đi với 'begun'.","lines":[],"vocab":[{"word":"already","pos":"adv","ipa":"/ɔːlˈredi/","meaning":"đã sớm, đã rồi"},{"word":"emerging","pos":"adj","ipa":"/ɪˈmɜːrdʒɪŋ/","meaning":"mới nổi, đang phát triển"},{"word":"transform","pos":"v","ipa":"/trænsˈfɔːrm/","meaning":"chuyển đổi, biến đổi"},{"word":"unimaginable","pos":"adj","ipa":"/ˌʌnɪˈmædʒɪnəbəl/","meaning":"không thể tưởng tượng nổi"}],"isScanBacked":false,"grammarType":"Từ vựng — Trạng từ (Adverb)","formula":"CÔNG THỨC PART 5 (Trạng từ đi với Hiện tại hoàn thành 'have ___ begun'): Nhấn mạnh công nghệ mới đã bắt đầu làm biến đổi ngành vận tải từ trước đến nay -> Chọn 'already' (đã rồi, đã sớm).","optionAnalysis":{"A":"Chính xác: 'already' đi chuẩn với thì hiện tại hoàn thành 'have… begun' để nhấn mạnh xu hướng chuyển đổi đã bắt đầu.","B":"Sai kết hợp từ: 'exactly' (một cách chính xác) không dùng để bổ nghĩa cho động từ khởi phát 'begun'.","C":"Ngược nghĩa ngữ cảnh: 'hardly' (hầu như không) phủ nhận tác động biến đổi mà câu văn đang nhấn mạnh.","D":"Sai kết hợp từ: 'closely' (sát sao, chặt chẽ) không collocate với động từ 'begun to transform'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 124 · Đáp án A","opt":"A","isCorrect":true,"quote":"Emerging technologies have ------- begun to transform the shipping industry in ways that were once unimaginable.","viQuote":"Các công nghệ mới nổi đã ------- bắt đầu chuyển đổi ngành vận tải biển theo những cách từng không thể tưởng tượng nổi."},{"badge":"Câu 124 · Từ khóa A","opt":"A","isCorrect":true,"quote":"already","viQuote":"đã sớm, đã rồi (adv)"}],"evQuotes":["Emerging technologies have ------- begun to transform the shipping industry in ways that were once unimaginable.","already"]},{"q":125,"part":5,"group_id":null,"audio":null,"stem_en":"The company handbook outlines the high ------- that employees are expected to meet every day.","stem_vi":"Sổ tay nhân viên của công ty nêu rõ những ------- cao mà nhân viên được kỳ vọng phải đáp ứng mỗi ngày.","options":{"A":{"en":"experts","vi":"các chuyên gia (n)"},"B":{"en":"accounts","vi":"các tài khoản, khách hàng (n)"},"C":{"en":"recommendations","vi":"các khuyến nghị, đề xuất (n)"},"D":{"en":"standards","vi":"các tiêu chuẩn (n)"}},"ans":"D","explanation":"Đáp án đúng: (D) standards — danh từ số nhiều tạo thành cụm collocation chuẩn 'meet high standards' (đáp ứng những tiêu chuẩn cao).\nDẫn chứng: \"The company handbook outlines the high ------- that employees are expected to meet every day.\" (Cụm động từ 'meet' kết hợp cố định với 'standards').\nPhân tích bẫy:\n- (A) 'experts' nghĩa là 'các chuyên gia', là danh từ chỉ người nên không thể ghép thành 'high experts' hay làm tân ngữ cho 'meet' theo nghĩa quy chuẩn.\n- (B) 'accounts' nghĩa là 'tài khoản, khách hàng', không đi sau tính từ 'high' trong ngữ cảnh quy định sổ tay nhân viên.\n- (C) 'recommendations' nghĩa là 'các khuyến nghị, gợi ý', mang tính tham khảo nên không khớp với tính từ 'high' và nghĩa bắt buộc đáp ứng mỗi ngày.","lines":[],"vocab":[{"word":"standard","pos":"n","ipa":"/ˈstændərd/","meaning":"tiêu chuẩn, chuẩn mực"},{"word":"handbook","pos":"n","ipa":"/ˈhændbʊk/","meaning":"sổ tay (nhân viên)"},{"word":"outline","pos":"v","ipa":"/ˈaʊtlaɪn/","meaning":"nêu rõ, phác thảo"},{"word":"recommendation","pos":"n","ipa":"/ˌrekəmenˈdeɪʃən/","meaning":"khuyến nghị, đề xuất"}],"isScanBacked":false,"grammarType":"Từ vựng — Danh từ (Noun)","formula":"CÔNG THỨC PART 5 (Collocation Thực Chiến — 'meet high ___'): Sau tính từ 'high' và trước mệnh đề quan hệ 'that employees are expected to meet' cần danh từ chỉ chuẩn mực -> Chọn 'standards' (tiêu chuẩn).","optionAnalysis":{"A":"Sai đối tượng danh từ: 'experts' (chuyên gia) là người, không phải quy chuẩn được nêu trong sổ tay để nhân viên 'meet'.","B":"Sai ngữ cảnh từ vựng: 'accounts' (tài khoản) không kết hợp với 'high' và 'meet' trong quy định nội bộ công ty.","C":"Sai sắc thái nghĩa: 'recommendations' (đề xuất, khuyến nghị) không đi với cụm 'high ___' và mức kỳ vọng bắt buộc mỗi ngày.","D":"Chính xác: 'standards' tạo collocation kinh điển 'meet high standards' (đáp ứng các tiêu chuẩn cao)."},"evDocIdx":0,"evTargets":[{"badge":"Câu 125 · Đáp án D","opt":"D","isCorrect":true,"quote":"The company handbook outlines the high ------- that employees are expected to meet every day.","viQuote":"Sổ tay nhân viên của công ty nêu rõ những ------- cao mà nhân viên được kỳ vọng phải đáp ứng mỗi ngày."},{"badge":"Câu 125 · Từ khóa D","opt":"D","isCorrect":true,"quote":"standards","viQuote":"các tiêu chuẩn (n)"}],"evQuotes":["The company handbook outlines the high ------- that employees are expected to meet every day.","standards"]},{"q":126,"part":5,"group_id":null,"audio":null,"stem_en":"Because ------- of the board members have scheduling conflicts, the board meeting will be moved to a date when all can attend.","stem_vi":"Vì ------- thành viên hội đồng quản trị bị trùng lịch, cuộc họp hội đồng quản trị sẽ được dời sang một ngày mà tất cả mọi người đều có thể tham dự.","options":{"A":{"en":"any","vi":"bất kỳ (det/pron)"},"B":{"en":"everybody","vi":"mọi người (pron)"},"C":{"en":"those","vi":"những người đó, những cái đó (pron/det)"},"D":{"en":"some","vi":"một số, một vài (det/pron)"}},"ans":"D","explanation":"Đáp án đúng: (D) some — đại từ bất định chỉ lượng ('một số, một vài'), dùng chuẩn trong câu khẳng định với cấu trúc 'some of the board members' và động từ số nhiều 'have'.\nDẫn chứng: \"Because ------- of the board members have scheduling conflicts, the board meeting will be moved to a date when all can attend.\" (Mệnh đề khẳng định cần lượng từ chỉ một bộ phận thành viên, đối lập với 'all' ở vế sau).\nPhân tích bẫy:\n- (A) 'any' thường dùng trong câu phủ định, nghi vấn hoặc mệnh đề điều kiện; câu trần thuật khẳng định bắt đầu bằng 'Because' không dùng 'any of'.\n- (B) 'everybody' là đại từ bất định chỉ toàn bộ mọi người, chia động từ số ít và không bao giờ đi theo cấu trúc 'everybody of the…'.\n- (C) 'those' dùng với 'of' ('those of…') để thay thế cho một danh từ đã nhắc trước đó trong phép so sánh, không dùng để chỉ 'những thành viên trong số các thành viên'.","lines":[],"vocab":[{"word":"board member","pos":"n","ipa":"/bɔːrd ˈmembər/","meaning":"thành viên hội đồng quản trị"},{"word":"scheduling conflict","pos":"n","ipa":"/ˈskedʒuːlɪŋ ˈkɑːnflɪkt/","meaning":"sự trùng lịch, xung đột lịch trình"},{"word":"move to","pos":"phr. v","ipa":"/muːv tuː/","meaning":"dời sang (một ngày, giờ khác)"},{"word":"attend","pos":"v","ipa":"/əˈtend/","meaning":"tham dự"}],"isScanBacked":false,"grammarType":"Đại từ / Từ hạn định (Pronoun & Determiner)","formula":"CÔNG THỨC PART 5 (Lượng từ + 'of the + N số nhiều' trong câu khẳng định): Trong mệnh đề nguyên nhân khẳng định 'Because ___ of the board members have…', loại 'any' (dùng cho phủ định/nghi vấn) -> Chọn 'some' (một vài).","optionAnalysis":{"A":"Sai ngữ cảnh khẳng định: 'any' dùng trong câu phủ định, nghi vấn hoặc điều kiện, không dùng ở mệnh đề khẳng định 'Because ___ of'.","B":"Sai cấu trúc ngữ pháp: 'everybody' không kết hợp với giới từ 'of' ('everybody of the…') và đòi hỏi động từ số ít thay vì 'have'.","C":"Sai cách dùng đại từ: 'those of' dùng để thay thế danh từ đã nêu ở trước khi so sánh, không có nghĩa 'một số trong các thành viên'.","D":"Chính xác: 'some' tạo cụm 'some of the board members' chia động từ số nhiều 'have', tương phản hợp lý với 'all can attend'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 126 · Đáp án D","opt":"D","isCorrect":true,"quote":"Because ------- of the board members have scheduling conflicts, the board meeting will be moved to a date when all can attend.","viQuote":"Vì ------- thành viên hội đồng quản trị bị trùng lịch, cuộc họp hội đồng quản trị sẽ được dời sang một ngày mà tất cả mọi người đều có thể tham dự."},{"badge":"Câu 126 · Từ khóa D","opt":"D","isCorrect":true,"quote":"some","viQuote":"một số, một vài (det/pron)"}],"evQuotes":["Because ------- of the board members have scheduling conflicts, the board meeting will be moved to a date when all can attend.","some"]},{"q":127,"part":5,"group_id":null,"audio":null,"stem_en":"The project ------- the collaboration of several teams across the company.","stem_vi":"Dự án này ------- sự phối hợp của nhiều nhóm làm việc trong toàn công ty.","options":{"A":{"en":"passed","vi":"vượt qua, thông qua (v - quá khứ)"},"B":{"en":"decided","vi":"quyết định (v - quá khứ)"},"C":{"en":"required","vi":"đòi hỏi, yêu cầu (v - quá khứ)"},"D":{"en":"performed","vi":"thực hiện, biểu diễn (v - quá khứ)"}},"ans":"C","explanation":"Đáp án đúng: (C) required — ngoại động từ quá khứ nghĩa là 'đòi hỏi, yêu cầu', khớp hoàn toàn giữa chủ ngữ 'The project' và tân ngữ 'the collaboration'.\nDẫn chứng: \"The project ------- the collaboration of several teams across the company.\" (Dự án đòi hỏi sự hợp tác giữa nhiều phòng ban).\nPhân tích bẫy:\n- (A) 'passed' nghĩa là 'thông qua, vượt qua', không kết hợp tự nhiên với tân ngữ 'the collaboration' của chủ ngữ 'The project'.\n- (B) 'decided' nghĩa là 'quyết định', đòi hỏi chủ thể có tư duy như con người hoặc hội đồng, 'The project' không thể tự quyết định.\n- (D) 'performed' nghĩa là 'thực hiện, biểu diễn', thường đi với nhiệm vụ hoặc bài kiểm tra ('task/test') chứ không đi với 'collaboration'.","lines":[],"vocab":[{"word":"require","pos":"v","ipa":"/rɪˈkwaɪər/","meaning":"đòi hỏi, yêu cầu"},{"word":"collaboration","pos":"n","ipa":"/kəˌlæbəˈreɪʃən/","meaning":"sự phối hợp, hợp tác"},{"word":"several","pos":"det","ipa":"/ˈsevrəl/","meaning":"nhiều, một vài"},{"word":"across the company","pos":"phr","ipa":"/əˈkrɔːs ðə ˈkʌmpəni/","meaning":"trên toàn công ty"}],"isScanBacked":false,"grammarType":"Động từ (Verb & Collocation)","formula":"CÔNG THỨC PART 5 (Phân tích Cấu trúc S-V-O — 'The project ___ the collaboration'): Chủ ngữ vật 'The project' không tự quyết định hay thực hiện mà cần đến sự phối hợp -> Chọn ngoại động từ 'required' (đòi hỏi).","optionAnalysis":{"A":"Sai kết hợp từ: 'passed' (vượt qua, thông qua) không đi với tân ngữ 'the collaboration' của một dự án.","B":"Sai chủ thể hành động: 'decided' (quyết định) cần chủ ngữ là người hoặc tổ chức, dự án ('The project') không tự quyết định.","C":"Chính xác: 'required' (đòi hỏi) diễn đạt đúng mối quan hệ giữa dự án và sự phối hợp của nhiều nhóm.","D":"Sai kết hợp từ: 'performed' (thực hiện) đi với hành động/nhiệm vụ cụ thể, không kết hợp với danh từ 'collaboration'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 127 · Đáp án C","opt":"C","isCorrect":true,"quote":"The project ------- the collaboration of several teams across the company.","viQuote":"Dự án này ------- sự phối hợp của nhiều nhóm làm việc trong toàn công ty."},{"badge":"Câu 127 · Từ khóa C","opt":"C","isCorrect":true,"quote":"required","viQuote":"đòi hỏi, yêu cầu (v - quá khứ)"}],"evQuotes":["The project ------- the collaboration of several teams across the company.","required"]},{"q":128,"part":5,"group_id":null,"audio":null,"stem_en":"We cannot send the store's coupon booklet to the printers until it ------- by Ms. Jeon.","stem_vi":"Chúng tôi không thể gửi tập phiếu giảm giá của cửa hàng đến nhà in cho đến khi nó ------- bởi bà Jeon.","options":{"A":{"en":"is approving","vi":"đang phê duyệt (chủ động - hiện tại tiếp diễn)"},"B":{"en":"approves","vi":"phê duyệt (chủ động - hiện tại đơn)"},"C":{"en":"has been approved","vi":"đã được phê duyệt (bị động - hiện tại hoàn thành)"},"D":{"en":"will be approved","vi":"sẽ được phê duyệt (bị động - tương lai đơn)"}},"ans":"C","explanation":"Đáp án đúng: (C) has been approved — thì hiện tại hoàn thành ở thể bị động, vừa phù hợp chủ ngữ vật 'it' có tác nhân 'by Ms. Jeon', vừa đúng quy tắc không dùng 'will' sau 'until'.\nDẫn chứng: \"We cannot send the store's coupon booklet to the printers until it ------- by Ms. Jeon.\" (Đại từ 'it' quy chiếu về 'coupon booklet', có cụm 'by Ms. Jeon' chốt bị động).\nPhân tích bẫy:\n- (A) 'is approving' là thể chủ động thì hiện tại tiếp diễn, vô lý vì tập phiếu giảm giá ('it') không thể tự phê duyệt.\n- (B) 'approves' là thể chủ động thì hiện tại đơn, sai hoàn toàn vì phía sau có cụm tác nhân bị động 'by Ms. Jeon'.\n- (D) 'will be approved' dù đúng thể bị động nhưng vi phạm quy tắc ngữ pháp tiếng Anh: không chia thì tương lai 'will' trong mệnh đề thời gian sau 'until'.","lines":[],"vocab":[{"word":"approve","pos":"v","ipa":"/əˈpruːv/","meaning":"phê duyệt, chấp thuận"},{"word":"coupon booklet","pos":"n","ipa":"/ˈkuːpɑːn ˈbʊklət/","meaning":"tập phiếu giảm giá"},{"word":"printer","pos":"n","ipa":"/ˈprɪntər/","meaning":"nhà in, xưởng in"},{"word":"until","pos":"conj","ipa":"/ənˈtɪl/","meaning":"cho đến khi"}],"isScanBacked":false,"grammarType":"Chia động từ — Thì / Thể (Bị động - Chủ động) / Dạng V-ing · to V","formula":"CÔNG THỨC PART 5 (Mệnh đề Thời gian 'until' + Thể Bị động): Trong mệnh đề trạng ngữ chỉ thời gian bắt đầu bằng 'until', KHÔNG dùng 'will'; chủ ngữ vật 'it' (= coupon booklet) đi với 'by Ms. Jeon' -> Chọn bị động Hiện tại hoàn thành 'has been approved'.","optionAnalysis":{"A":"Sai thể chủ động/bị động: 'is approving' là chủ động, vật 'it' (cuốn phiếu giảm giá) không thể tự thực hiện hành động phê duyệt.","B":"Sai thể chủ động/bị động: 'approves' chia chủ động, mâu thuẫn với chủ ngữ vật 'it' và tác nhân 'by Ms. Jeon'.","C":"Chính xác: 'has been approved' đúng thể bị động cho 'it… by Ms. Jeon' và tuân thủ quy tắc thay 'will' sau liên từ thời gian 'until'.","D":"Bẫy thì sau liên từ thời gian: 'will be approved' sai ngữ pháp vì mệnh đề bắt đầu bằng 'until' không được dùng 'will'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 128 · Đáp án C","opt":"C","isCorrect":true,"quote":"We cannot send the store's coupon booklet to the printers until it ------- by Ms. Jeon.","viQuote":"Chúng tôi không thể gửi tập phiếu giảm giá của cửa hàng đến nhà in cho đến khi nó ------- bởi bà Jeon."},{"badge":"Câu 128 · Từ khóa C","opt":"C","isCorrect":true,"quote":"has been approved","viQuote":"đã được phê duyệt (bị động - hiện tại hoàn thành)"}],"evQuotes":["We cannot send the store's coupon booklet to the printers until it ------- by Ms. Jeon.","has been approved"]},{"q":129,"part":5,"group_id":null,"audio":null,"stem_en":"------- the closure of Verdigold Transport Services, we are looking for a new shipping company.","stem_vi":"------- việc Verdigold Transport Services đóng cửa, chúng tôi đang tìm kiếm một đơn vị vận chuyển mới.","options":{"A":{"en":"In spite of","vi":"mặc dù, bất chấp (cụm giới từ)"},"B":{"en":"Just as","vi":"ngay khi, cũng giống như (liên từ)"},"C":{"en":"In light of","vi":"xét đến, trước tình hình, bởi vì (cụm giới từ)"},"D":{"en":"According to","vi":"theo như (cụm giới từ)"}},"ans":"C","explanation":"Đáp án đúng: (C) In light of — cụm giới từ mang nghĩa 'xét đến, bởi vì', nối hợp lý cụm danh từ 'the closure…' với hệ quả phải tìm công ty vận chuyển mới.\nDẫn chứng: \"------- the closure of Verdigold Transport Services, we are looking for a new shipping company.\" (Chỗ trống đứng trước cụm danh từ 'the closure…' và mang quan hệ nguyên nhân - kết quả).\nPhân tích bẫy:\n- (A) 'In spite of' là cụm giới từ chỉ sự nhượng bộ ('mặc dù'), sai quan hệ logic vì đơn vị cũ đóng cửa chính là lý do khiến họ tìm đơn vị mới.\n- (B) 'Just as' là liên từ bắt buộc theo sau là một mệnh đề S+V, không thể đứng trước một cụm danh từ đơn thuần 'the closure of…'.\n- (D) 'According to' nghĩa là 'theo như (một nguồn tin/báo cáo)', không dùng để diễn đạt nguyên nhân từ một sự kiện đóng cửa.","lines":[],"vocab":[{"word":"in light of","pos":"prep","ipa":"/ɪn laɪt ʌv/","meaning":"xét đến, trước tình hình"},{"word":"closure","pos":"n","ipa":"/ˈkloʊʒər/","meaning":"việc đóng cửa, ngừng hoạt động"},{"word":"shipping company","pos":"n","ipa":"/ˈʃɪpɪŋ ˈkʌmpəni/","meaning":"công ty vận chuyển"},{"word":"in spite of","pos":"prep","ipa":"/ɪn spaɪt ʌv/","meaning":"mặc dù, bất chấp"}],"isScanBacked":false,"grammarType":"Phân biệt Giới từ (cụm N/V-ing) vs Liên từ (mệnh đề S+V)","formula":"CÔNG THỨC PART 5 (Tờ A3 Màu — Cụm Giới từ chỉ Nguyên nhân + Cụm Danh từ): Phía sau là cụm danh từ 'the closure of Verdigold Transport Services' cần cụm giới từ mang nghĩa nguyên nhân -> Chọn 'In light of' (xét thấy, bởi vì).","optionAnalysis":{"A":"Ngược logic câu: 'In spite of' (mặc dù) chỉ tương phản, sai với quan hệ nguyên nhân đóng cửa dẫn đến tìm đối tác mới.","B":"Sai cấu trúc giới từ vs liên từ: 'Just as' là liên từ cần mệnh đề S+V, không đi trước cụm danh từ 'the closure of…'.","C":"Chính xác: 'In light of' là cụm giới từ chỉ nguyên nhân (xét đến, trước tình hình), khớp chuẩn cả ngữ pháp lẫn logic câu.","D":"Sai ngữ nghĩa giới từ: 'According to' (theo như lời/tài liệu) không dùng để nêu nguyên nhân sự việc 'the closure'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 129 · Đáp án C","opt":"C","isCorrect":true,"quote":"------- the closure of Verdigold Transport Services, we are looking for a new shipping company.","viQuote":"------- việc Verdigold Transport Services đóng cửa, chúng tôi đang tìm kiếm một đơn vị vận chuyển mới."},{"badge":"Câu 129 · Từ khóa C","opt":"C","isCorrect":true,"quote":"In light of","viQuote":"xét đến, trước tình hình, bởi vì (cụm giới từ)"}],"evQuotes":["------- the closure of Verdigold Transport Services, we are looking for a new shipping company.","In light of"]},{"q":130,"part":5,"group_id":null,"audio":null,"stem_en":"The ------- information provided by Uniss Bank's brochure helps applicants understand the terms of their loans.","stem_vi":"Thông tin ------- được cung cấp trong tập tài liệu giới thiệu của Uniss Bank giúp người đăng ký vay hiểu rõ các điều khoản trong khoản vay của họ.","options":{"A":{"en":"arbitrary","vi":"tùy tiện, độc đoán (adj)"},"B":{"en":"supplemental","vi":"bổ sung, phụ thêm (adj)"},"C":{"en":"superfluous","vi":"dư thừa, không cần thiết (adj)"},"D":{"en":"potential","vi":"tiềm năng, tiềm ẩn (adj)"}},"ans":"B","explanation":"Đáp án đúng: (B) supplemental — tính từ nghĩa là 'bổ sung, phụ thêm', mô tả thông tin hữu ích trong tài liệu giới thiệu giúp người vay hiểu rõ điều khoản.\nDẫn chứng: \"The ------- information provided by Uniss Bank's brochure helps applicants understand the terms of their loans.\" (Thông tin có ích cho người đăng ký vay).\nPhân tích bẫy:\n- (A) 'arbitrary' nghĩa là 'tùy tiện, độc đoán', mang nghĩa tiêu cực hoàn toàn trái ngược với tác dụng 'helps applicants understand'.\n- (C) 'superfluous' nghĩa là 'dư thừa, không cần thiết', mâu thuẫn với việc thông tin này giúp khách hàng hiểu điều khoản vay.\n- (D) 'potential' nghĩa là 'tiềm năng, có khả năng xảy ra', không kết hợp tự nhiên với thông tin đã được in sẵn trong brochure.","lines":[],"vocab":[{"word":"supplemental","pos":"adj","ipa":"/ˌsʌpləˈmentəl/","meaning":"bổ sung, phụ thêm"},{"word":"brochure","pos":"n","ipa":"/broʊˈʃʊr/","meaning":"tập tài liệu giới thiệu"},{"word":"applicant","pos":"n","ipa":"/ˈæplɪkənt/","meaning":"người nộp đơn, người đăng ký"},{"word":"loan terms","pos":"n","ipa":"/loʊn tɜːrmz/","meaning":"các điều khoản khoản vay"}],"isScanBacked":false,"grammarType":"Từ vựng — Tính từ (Adjective)","formula":"CÔNG THỨC PART 5 (Từ vựng Ngữ cảnh Ngân hàng — 'The ___ information… helps applicants'): Tính từ đứng trước 'information' phải mang sắc thái tích cực, hỗ trợ người vay hiểu điều khoản -> Chọn 'supplemental' (bổ sung).","optionAnalysis":{"A":"Sai sắc thái nghĩa: 'arbitrary' (tùy tiện, võ đoán) mang nghĩa tiêu cực, không phù hợp mô tả tài liệu ngân hàng hỗ trợ khách hàng.","B":"Chính xác: 'supplemental' (bổ sung) khớp ngữ cảnh tập tài liệu cung cấp thêm thông tin giúp người vay hiểu điều khoản.","C":"Mâu thuẫn ngữ cảnh: 'superfluous' (dư thừa, thừa thãi) trái ngược với vai trò 'helps applicants understand' của thông tin.","D":"Sai kết hợp từ: 'potential' (tiềm năng) không dùng để miêu tả thông tin đã có sẵn trong brochure ('provided by… brochure')."},"evDocIdx":0,"evTargets":[{"badge":"Câu 130 · Đáp án B","opt":"B","isCorrect":true,"quote":"The ------- information provided by Uniss Bank's brochure helps applicants understand the terms of their loans.","viQuote":"Thông tin ------- được cung cấp trong tập tài liệu giới thiệu của Uniss Bank giúp người đăng ký vay hiểu rõ các điều khoản trong khoản vay của họ."},{"badge":"Câu 130 · Từ khóa B","opt":"B","isCorrect":true,"quote":"supplemental","viQuote":"bổ sung, phụ thêm (adj)"}],"evQuotes":["The ------- information provided by Uniss Bank's brochure helps applicants understand the terms of their loans.","supplemental"]},{"q":131,"part":6,"group_id":"E25_T01_G131_134","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc04.webp"],"stem_en":"Select the best answer for blank (131) in the passage.","stem_vi":"131. Chọn câu phù hợp nhất điền vào chỗ trống [131].","options":{"A":{"en":"Children of all ages will enjoy the new exhibits.","vi":"Trẻ em ở mọi lứa tuổi sẽ thích thú với các khu trưng bày mới."},"B":{"en":"Learn about rainfall patterns across the region.","vi":"Tìm hiểu về quy luật lượng mưa trên toàn khu vực."},"C":{"en":"Build a set of simple patio furniture with easy-to-acquire materials.","vi":"Tự đóng một bộ bàn ghế sân hiên đơn giản bằng những vật liệu dễ tìm."},"D":{"en":"Next Saturday at 4 P.M., we are hosting a free workshop for the public.","vi":"Vào lúc 4 giờ chiều thứ Bảy tới, chúng tôi sẽ tổ chức một buổi hội thảo miễn phí cho công chúng."}},"ans":"D","explanation":"Đáp án đúng: (D) Vào lúc 4 giờ chiều thứ Bảy tới, chúng tôi sẽ tổ chức một buổi hội thảo miễn phí cho công chúng — mở đầu trực tiếp cho hoạt động giảng dạy của \"we\" ở câu kế tiếp và khớp với lời kêu gọi đăng ký cuối thông báo.\nDẫn chứng: \"Come to the Maxley Heights Center for Horticulture and learn how to create a beautiful, eco-friendly garden for your home or business. [131] -------. We will teach you how to plant a rain garden\" (Liên kết lùi với lời mời đến học làm vườn, liên kết tiến với chủ ngữ \"We will teach you\" và câu cuối \"To register, visit www.maxley-horticulture.org.\").\nPhân tích bẫy:\n- (A) Lạc chủ đề: thông báo mời công chúng đến học thiết kế vườn cho nhà ở hoặc doanh nghiệp và đăng ký tham gia, không nói về khu trưng bày mới dành cho trẻ em (\"new exhibits\").\n- (B) Sai mạch ý: câu liền sau nêu rõ nội dung giảng dạy là cách trồng vườn mưa (\"how to plant a rain garden\"), không phải tìm hiểu quy luật lượng mưa toàn khu vực (\"rainfall patterns\").\n- (C) Sai nội dung chuyên môn: trung tâm làm vườn hướng dẫn làm vườn mưa sinh thái, không hướng dẫn đóng bàn ghế sân hiên (\"patio furniture\").","lines":[{"speaker":"","en":"Come to the Maxley Heights Center for Horticulture and learn how to create a beautiful, eco-friendly garden for your home or business. [131] -------. We will teach you how to plant a rain garden, which is simply a shallow sunken garden [132] ------- a special soil mix to filter pollutants from rainwater flowing from nearby roads and rooftops. These gardens can be landscaped with native plants and flowers. [133] -------, rain gardens are always beneficial to the local environment. Among other things, [134] ------- improve drainage and protect rivers and streams.","vi":"Hãy đến với Maxley Heights Center for Horticulture để học cách tạo nên một khu vườn xinh đẹp, thân thiện với môi trường cho ngôi nhà hoặc doanh nghiệp của bạn. [131]. Chúng tôi sẽ hướng dẫn bạn cách trồng một khu vườn mưa — đơn giản là một khu vườn trũng nông [132] hỗn hợp đất đặc biệt để lọc các chất ô nhiễm trong nước mưa chảy từ các tuyến đường và mái nhà lân cận. Những khu vườn này có thể được thiết kế cảnh quan bằng các loài cây và hoa bản địa. [133], vườn mưa luôn mang lại lợi ích cho môi trường địa phương. Bên cạnh những tác dụng khác, [134] giúp cải thiện khả năng thoát nước và bảo vệ sông suối.","units":[{"en":"Come to the Maxley Heights Center for Horticulture and learn how to create a beautiful, eco-friendly garden for your home or business. [131] -------.","vi":"Hãy đến với Maxley Heights Center for Horticulture để học cách tạo nên một khu vườn xinh đẹp, thân thiện với môi trường cho ngôi nhà hoặc doanh nghiệp của bạn. [131]."},{"en":"We will teach you how to plant a rain garden, which is simply a shallow sunken garden [132] ------- a special soil mix to filter pollutants from rainwater flowing from nearby roads and rooftops.","vi":"Chúng tôi sẽ hướng dẫn bạn cách trồng một khu vườn mưa — đơn giản là một khu vườn trũng nông [132] hỗn hợp đất đặc biệt để lọc các chất ô nhiễm trong nước mưa chảy từ các tuyến đường và mái nhà lân cận."},{"en":"These gardens can be landscaped with native plants and flowers.","vi":"Những khu vườn này có thể được thiết kế cảnh quan bằng các loài cây và hoa bản địa."},{"en":"[133] -------, rain gardens are always beneficial to the local environment.","vi":"[133], vườn mưa luôn mang lại lợi ích cho môi trường địa phương."},{"en":"Among other things, [134] ------- improve drainage and protect rivers and streams.","vi":"Bên cạnh những tác dụng khác, [134] giúp cải thiện khả năng thoát nước và bảo vệ sông suối."}]},{"speaker":"","en":"To register, visit www.maxley-horticulture.org.","vi":"Để đăng ký, vui lòng truy cập www.maxley-horticulture.org.","units":[{"en":"To register, visit www.maxley-horticulture.org.","vi":"Để đăng ký, vui lòng truy cập www.maxley-horticulture.org."}]}],"vocab":[{"word":"horticulture","pos":"n","ipa":"/ˈhɔːrtɪkʌltʃər/","meaning":"nghề làm vườn, ngành trồng trọt cảnh quan"},{"word":"eco-friendly","pos":"adj","ipa":"/ˌiːkoʊˈfrendli/","meaning":"thân thiện với môi trường"},{"word":"host","pos":"v","ipa":"/hoʊst/","meaning":"đăng cai, tổ chức (hội thảo, sự kiện)"},{"word":"register","pos":"v","ipa":"/ˈredʒɪstər/","meaning":"đăng ký tham gia"}],"isScanBacked":false,"docTypeLabel":"notice","context":"Notice from Maxley Heights Center for Horticulture announcing a free rain-garden workshop","grammarType":"Điền câu hoàn chỉnh vào mạch đoạn văn (Sentence Insertion)","formula":"CÔNG THỨC PART 6 (6. PART 6 THUỘC LÒNG — Điền câu vào mạch đoạn văn): Đọc câu trước [131] (lời mời đến trung tâm học làm vườn) và câu sau [131] (\"We will teach you how to plant a rain garden\") -> Cần câu giới thiệu buổi hội thảo hướng dẫn của \"we\" để bắc cầu mạch ý.","optionAnalysis":{"A":"Lạc chủ đề của thông báo: đoạn văn mời người đọc học cách tạo khu vườn thân thiện với môi trường và đăng ký tham gia, không đề cập đến khu trưng bày mới cho trẻ em (\"new exhibits\").","B":"Đứt mạch với câu liền sau: câu sau [131] giới thiệu sẽ dạy cách trồng vườn mưa (\"how to plant a rain garden\"), chứ không dạy về quy luật lượng mưa khu vực (\"rainfall patterns\").","C":"Sai nội dung trọng tâm: bài viết của Maxley Heights Center for Horticulture bàn về làm vườn sinh thái và vườn mưa, không phải hướng dẫn đóng bàn ghế sân hiên (\"patio furniture\").","D":"Đáp án chính xác: nêu rõ thời gian và buổi hội thảo miễn phí do \"we\" tổ chức, nối liền mạch từ lời mời ở câu đầu sang \"We will teach you\" ở câu sau và lời kêu gọi đăng ký ở cuối bài."},"evDocIdx":0,"evTargets":[{"badge":"Câu 131 · Đáp án D","opt":"D","isCorrect":true,"quote":"Come to the Maxley Heights Center for Horticulture and learn how to create a beautiful, eco-friendly garden for your home or business.","viQuote":"Hãy đến với Maxley Heights Center for Horticulture để học cách tạo nên một khu vườn xinh đẹp, thân thiện với môi trường cho ngôi nhà hoặc doanh nghiệp của bạn."},{"badge":"Câu 131 · Đáp án D","opt":"D","isCorrect":true,"quote":"We will teach you how to plant a rain garden,","viQuote":"Chúng tôi sẽ hướng dẫn bạn cách trồng một khu vườn mưa"}],"evQuotes":["Come to the Maxley Heights Center for Horticulture and learn how to create a beautiful, eco-friendly garden for your home or business.","We will teach you how to plant a rain garden,"]},{"q":132,"part":6,"group_id":"E25_T01_G131_134","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc04.webp"],"stem_en":"Select the best answer for blank (132) in the passage.","stem_vi":"Chọn đáp án phù hợp nhất để điền vào chỗ trống (132) trong đoạn văn.","options":{"A":{"en":"to use","vi":"để sử dụng (động từ nguyên mẫu có to)"},"B":{"en":"used to","vi":"đã từng / được dùng để (quá khứ phân từ / cụm động từ)"},"C":{"en":"by using","vi":"bằng cách sử dụng (giới từ + V-ing)"},"D":{"en":"that uses","vi":"mà sử dụng (mệnh đề quan hệ)"}},"ans":"D","explanation":"Đáp án đúng: (D) that uses (mà sử dụng) — dùng đại từ quan hệ \"that\" thay cho danh từ số ít \"a shallow sunken garden\" và chia động từ hiện tại đơn số ít \"uses\" ở thể chủ động.\nDẫn chứng: \"which is simply a shallow sunken garden [132] ------- a special soil mix to filter pollutants from rainwater\" (Một khu vườn trũng nông sử dụng hỗn hợp đất đặc biệt để lọc các chất ô nhiễm từ nước mưa).\nPhân tích bẫy:\n- (A) Sai cấu trúc và nghĩa: \"to use\" mang nghĩa chỉ mục đích (\"để sử dụng\"), nhưng phía sau đã có cụm \"to filter pollutants\" làm mục đích chính, khiến câu tối nghĩa nếu viết vườn trũng \"để sử dụng hỗn hợp đất\".\n- (B) Sai nghĩa và ngữ pháp: \"used to\" diễn tả thói quen quá khứ (\"đã từng\") hoặc dạng bị động rút gọn thiếu giới từ (nếu bị động phải đi kèm \"with\", không đứng trực tiếp trước danh từ \"a special soil mix\").\n- (C) Sai cấu trúc bổ ngữ: \"by using\" (bằng cách sử dụng) chỉ phương thức cho một hành động, không đóng vai trò định nghĩa trực tiếp cho danh từ \"a shallow sunken garden\".","lines":[{"speaker":"","en":"Come to the Maxley Heights Center for Horticulture and learn how to create a beautiful, eco-friendly garden for your home or business. [131] -------. We will teach you how to plant a rain garden, which is simply a shallow sunken garden [132] ------- a special soil mix to filter pollutants from rainwater flowing from nearby roads and rooftops. These gardens can be landscaped with native plants and flowers. [133] -------, rain gardens are always beneficial to the local environment. Among other things, [134] ------- improve drainage and protect rivers and streams.","vi":"Hãy đến với Maxley Heights Center for Horticulture để học cách tạo nên một khu vườn xinh đẹp, thân thiện với môi trường cho ngôi nhà hoặc doanh nghiệp của bạn. [131]. Chúng tôi sẽ hướng dẫn bạn cách trồng một khu vườn mưa — đơn giản là một khu vườn trũng nông [132] hỗn hợp đất đặc biệt để lọc các chất ô nhiễm trong nước mưa chảy từ các tuyến đường và mái nhà lân cận. Những khu vườn này có thể được thiết kế cảnh quan bằng các loài cây và hoa bản địa. [133], vườn mưa luôn mang lại lợi ích cho môi trường địa phương. Bên cạnh những tác dụng khác, [134] giúp cải thiện khả năng thoát nước và bảo vệ sông suối.","units":[{"en":"Come to the Maxley Heights Center for Horticulture and learn how to create a beautiful, eco-friendly garden for your home or business. [131] -------.","vi":"Hãy đến với Maxley Heights Center for Horticulture để học cách tạo nên một khu vườn xinh đẹp, thân thiện với môi trường cho ngôi nhà hoặc doanh nghiệp của bạn. [131]."},{"en":"We will teach you how to plant a rain garden, which is simply a shallow sunken garden [132] ------- a special soil mix to filter pollutants from rainwater flowing from nearby roads and rooftops.","vi":"Chúng tôi sẽ hướng dẫn bạn cách trồng một khu vườn mưa — đơn giản là một khu vườn trũng nông [132] hỗn hợp đất đặc biệt để lọc các chất ô nhiễm trong nước mưa chảy từ các tuyến đường và mái nhà lân cận."},{"en":"These gardens can be landscaped with native plants and flowers.","vi":"Những khu vườn này có thể được thiết kế cảnh quan bằng các loài cây và hoa bản địa."},{"en":"[133] -------, rain gardens are always beneficial to the local environment.","vi":"[133], vườn mưa luôn mang lại lợi ích cho môi trường địa phương."},{"en":"Among other things, [134] ------- improve drainage and protect rivers and streams.","vi":"Bên cạnh những tác dụng khác, [134] giúp cải thiện khả năng thoát nước và bảo vệ sông suối."}]},{"speaker":"","en":"To register, visit www.maxley-horticulture.org.","vi":"Để đăng ký, vui lòng truy cập www.maxley-horticulture.org.","units":[{"en":"To register, visit www.maxley-horticulture.org.","vi":"Để đăng ký, vui lòng truy cập www.maxley-horticulture.org."}]}],"vocab":[{"word":"shallow","pos":"adj","ipa":"/ˈʃæloʊ/","meaning":"nông, cạn"},{"word":"sunken","pos":"adj","ipa":"/ˈsʌŋkən/","meaning":"trũng xuống, nằm thấp hơn mặt bằng"},{"word":"filter","pos":"v","ipa":"/ˈfɪltər/","meaning":"lọc, thanh lọc"},{"word":"pollutant","pos":"n","ipa":"/pəˈluːtənt/","meaning":"chất gây ô nhiễm"}],"isScanBacked":false,"docTypeLabel":"notice","context":"Notice from Maxley Heights Center for Horticulture announcing a free rain-garden workshop","grammarType":"Chia động từ — Thì / Thể (Bị động - Chủ động) / Dạng V-ing · to V","formula":"CÔNG THỨC PART 6 (Phân tích S-V-O & Mệnh đề quan hệ): Sau danh từ chỉ vật số ít \"a shallow sunken garden\" cần mệnh đề quan hệ đầy đủ hoặc cụm bổ ngữ chủ động để kết nối với tân ngữ \"a special soil mix\" -> Chọn \"that uses\" (mà sử dụng).","optionAnalysis":{"A":"Sai chức năng ngữ pháp: động từ nguyên mẫu \"to use\" diễn tả mục đích (\"để sử dụng\"), không phù hợp làm định ngữ định nghĩa cho danh từ \"a shallow sunken garden\" trước tân ngữ \"a special soil mix\".","B":"Sai cấu trúc và nghĩa: \"used to\" nghĩa là \"đã từng\" (không hợp nghĩa định nghĩa), hoặc nếu hiểu theo phân từ bị động rút gọn \"được dùng\" thì thiếu giới từ nối trước cụm danh từ \"a special soil mix\".","C":"Sai liên kết ngữ pháp: cụm giới từ \"by using\" (bằng cách sử dụng) chỉ cách thức cho động từ hành động, không thể nối trực tiếp sau danh từ \"a shallow sunken garden\" để giải thích cấu tạo của khu vườn.","D":"Đáp án chính xác: mệnh đề quan hệ \"that uses\" bổ nghĩa trực tiếp cho danh từ số ít \"a shallow sunken garden\", chia động từ \"uses\" hòa hợp số ít ở thì hiện tại đơn mô tả đặc điểm cố định."},"evDocIdx":0,"evTargets":[{"badge":"Câu 132 · Đáp án D","opt":"D","isCorrect":true,"quote":"which is simply a shallow sunken garden","viQuote":"đơn giản là một khu vườn trũng nông"},{"badge":"Câu 132 · Đáp án D","opt":"D","isCorrect":true,"quote":"a special soil mix to filter pollutants from rainwater flowing from nearby roads and rooftops.","viQuote":"hỗn hợp đất đặc biệt để lọc các chất ô nhiễm trong nước mưa chảy từ các tuyến đường và mái nhà lân cận."}],"evQuotes":["which is simply a shallow sunken garden","a special soil mix to filter pollutants from rainwater flowing from nearby roads and rooftops."]},{"q":133,"part":6,"group_id":"E25_T01_G131_134","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc04.webp"],"stem_en":"Select the best answer for blank (133) in the passage.","stem_vi":"Chọn đáp án phù hợp nhất để điền vào chỗ trống (133) trong đoạn văn.","options":{"A":{"en":"Best of all","vi":"Tuyệt vời nhất là"},"B":{"en":"For example","vi":"Ví dụ như"},"C":{"en":"In any event","vi":"Dù trong trường hợp nào đi nữa"},"D":{"en":"As a matter of fact","vi":"Thực tế là"}},"ans":"A","explanation":"Đáp án đúng: (A) Best of all (Tuyệt vời nhất là) — nhấn mạnh điểm ưu việt nổi bật nhất tiếp nối phần mô tả lợi ích thẩm mỹ ở câu trước.\nDẫn chứng: \"These gardens can be landscaped with native plants and flowers. [133] -------, rain gardens are always beneficial to the local environment.\" (Những khu vườn này có thể được thiết kế cảnh quan bằng cây hoa bản địa. Tuyệt vời nhất là vườn mưa luôn mang lại lợi ích cho môi trường địa phương).\nPhân tích bẫy:\n- (B) Sai quan hệ logic: \"For example\" (ví dụ như) dùng để đưa ví dụ cụ thể minh họa cho câu trước, nhưng \"luôn có lợi cho môi trường địa phương\" là nhận định khái quát chứ không phải ví dụ cho việc trồng cây hoa bản địa.\n- (C) Sai sắc thái ngữ cảnh: \"In any event\" (dù trong trường hợp nào) thường dùng để khép lại một tình huống băn khoăn hoặc sự cố, không khớp mạch quảng bá ưu điểm tích cực.\n- (D) Sai chức năng liên kết: \"As a matter of fact\" (thực tế là) thường dùng để đính chính hoặc nêu sự thật bất ngờ đối chiếu với nhận định trước, không tự nhiên khi nâng cấp ưu điểm như \"Best of all\".","lines":[{"speaker":"","en":"Come to the Maxley Heights Center for Horticulture and learn how to create a beautiful, eco-friendly garden for your home or business. [131] -------. We will teach you how to plant a rain garden, which is simply a shallow sunken garden [132] ------- a special soil mix to filter pollutants from rainwater flowing from nearby roads and rooftops. These gardens can be landscaped with native plants and flowers. [133] -------, rain gardens are always beneficial to the local environment. Among other things, [134] ------- improve drainage and protect rivers and streams.","vi":"Hãy đến với Maxley Heights Center for Horticulture để học cách tạo nên một khu vườn xinh đẹp, thân thiện với môi trường cho ngôi nhà hoặc doanh nghiệp của bạn. [131]. Chúng tôi sẽ hướng dẫn bạn cách trồng một khu vườn mưa — đơn giản là một khu vườn trũng nông [132] hỗn hợp đất đặc biệt để lọc các chất ô nhiễm trong nước mưa chảy từ các tuyến đường và mái nhà lân cận. Những khu vườn này có thể được thiết kế cảnh quan bằng các loài cây và hoa bản địa. [133], vườn mưa luôn mang lại lợi ích cho môi trường địa phương. Bên cạnh những tác dụng khác, [134] giúp cải thiện khả năng thoát nước và bảo vệ sông suối.","units":[{"en":"Come to the Maxley Heights Center for Horticulture and learn how to create a beautiful, eco-friendly garden for your home or business. [131] -------.","vi":"Hãy đến với Maxley Heights Center for Horticulture để học cách tạo nên một khu vườn xinh đẹp, thân thiện với môi trường cho ngôi nhà hoặc doanh nghiệp của bạn. [131]."},{"en":"We will teach you how to plant a rain garden, which is simply a shallow sunken garden [132] ------- a special soil mix to filter pollutants from rainwater flowing from nearby roads and rooftops.","vi":"Chúng tôi sẽ hướng dẫn bạn cách trồng một khu vườn mưa — đơn giản là một khu vườn trũng nông [132] hỗn hợp đất đặc biệt để lọc các chất ô nhiễm trong nước mưa chảy từ các tuyến đường và mái nhà lân cận."},{"en":"These gardens can be landscaped with native plants and flowers.","vi":"Những khu vườn này có thể được thiết kế cảnh quan bằng các loài cây và hoa bản địa."},{"en":"[133] -------, rain gardens are always beneficial to the local environment.","vi":"[133], vườn mưa luôn mang lại lợi ích cho môi trường địa phương."},{"en":"Among other things, [134] ------- improve drainage and protect rivers and streams.","vi":"Bên cạnh những tác dụng khác, [134] giúp cải thiện khả năng thoát nước và bảo vệ sông suối."}]},{"speaker":"","en":"To register, visit www.maxley-horticulture.org.","vi":"Để đăng ký, vui lòng truy cập www.maxley-horticulture.org.","units":[{"en":"To register, visit www.maxley-horticulture.org.","vi":"Để đăng ký, vui lòng truy cập www.maxley-horticulture.org."}]}],"vocab":[{"word":"landscape","pos":"v","ipa":"/ˈlændskeɪp/","meaning":"thiết kế cảnh quan, tạo cảnh sân vườn"},{"word":"native","pos":"adj","ipa":"/ˈneɪtɪv/","meaning":"bản địa, có nguồn gốc địa phương"},{"word":"beneficial","pos":"adj","ipa":"/ˌbenɪˈfɪʃəl/","meaning":"có lợi, mang lại lợi ích"}],"isScanBacked":false,"docTypeLabel":"notice","context":"Notice from Maxley Heights Center for Horticulture announcing a free rain-garden workshop","grammarType":"Liên từ / Trạng từ liên kết (Conjunction / Conjunctive Adverb)","formula":"CÔNG THỨC PART 6 (6. PART 6 THUỘC LÒNG — Trạng từ liên kết tăng tiến): Câu trước nêu ưu điểm thẩm mỹ (trồng cây hoa bản địa); câu sau nêu lợi ích lớn nhất và luôn đúng (luôn có lợi cho môi trường địa phương) -> Chọn trạng từ nhấn mạnh mức độ cao nhất \"Best of all\".","optionAnalysis":{"A":"Đáp án chính xác: \"Best of all\" (tuyệt vời nhất là) giúp nâng tầm mạch ý từ lợi ích cảnh quan bằng cây hoa bản địa ở câu trước sang lợi ích cốt lõi luôn có lợi cho môi trường địa phương.","B":"Sai logic minh họa: câu sau [133] khẳng định khái quát vườn mưa luôn có lợi cho môi trường, không phải ví dụ cụ thể cho việc thiết kế cảnh quan bằng \"native plants and flowers\".","C":"Sai sắc thái văn phong: \"In any event\" (dù thế nào đi nữa) thường xuất hiện khi chuyển ý bất chấp trở ngại đã nêu, không phù hợp với hai câu liệt kê ưu điểm liên tiếp.","D":"Sai quan hệ ý nghĩa: \"As a matter of fact\" (thực tế là) dùng để làm rõ hoặc phản hồi một giả định trước đó, không tạo sắc thái nhấn mạnh điểm cộng lớn nhất bằng \"Best of all\"."},"evDocIdx":0,"evTargets":[{"badge":"Câu 133 · Đáp án A","opt":"A","isCorrect":true,"quote":"These gardens can be landscaped with native plants and flowers.","viQuote":"Những khu vườn này có thể được thiết kế cảnh quan bằng các loài cây và hoa bản địa."},{"badge":"Câu 133 · Đáp án A","opt":"A","isCorrect":true,"quote":"rain gardens are always beneficial to the local environment.","viQuote":"vườn mưa luôn mang lại lợi ích cho môi trường địa phương."}],"evQuotes":["These gardens can be landscaped with native plants and flowers.","rain gardens are always beneficial to the local environment."]},{"q":134,"part":6,"group_id":"E25_T01_G131_134","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc04.webp"],"stem_en":"Select the best answer for blank (134) in the passage.","stem_vi":"Chọn đáp án phù hợp nhất để điền vào chỗ trống (134) trong đoạn văn.","options":{"A":{"en":"we","vi":"chúng tôi"},"B":{"en":"they","vi":"chúng (các khu vườn mưa)"},"C":{"en":"both","vi":"cả hai"},"D":{"en":"yours","vi":"của bạn"}},"ans":"B","explanation":"Đáp án đúng: (B) they (chúng) — đại từ nhân xưng chủ ngữ số nhiều thay thế trực tiếp cho cụm danh từ \"rain gardens\" ở câu trước, hòa hợp với động từ \"improve\" và \"protect\".\nDẫn chứng: \"[133] -------, rain gardens are always beneficial to the local environment. Among other things, [134] ------- improve drainage and protect rivers and streams.\" (Vườn mưa luôn có lợi cho môi trường địa phương. Bên cạnh những tác dụng khác, chúng giúp cải thiện khả năng thoát nước và bảo vệ sông suối).\nPhân tích bẫy:\n- (A) Sai đối tượng quy chiếu: \"we\" chỉ trung tâm làm vườn (ban tổ chức), không thể đóng vai trò chủ thể tự nhiên trực tiếp cải thiện thoát nước như \"rain gardens\".\n- (C) Sai ngữ cảnh số lượng: \"both\" (cả hai) chỉ dùng khi câu trước nhắc đến đúng hai đối tượng cụ thể, trong khi câu trước chỉ nêu chung \"rain gardens\" (số nhiều không giới hạn 2).\n- (D) Sai nghĩa và hòa hợp: \"yours\" (cái của bạn) chỉ khu vườn riêng của một người đọc (số ít trong câu đầu \"your home\"), không thay thế được cho khái niệm chung \"rain gardens\" số nhiều.","lines":[{"speaker":"","en":"Come to the Maxley Heights Center for Horticulture and learn how to create a beautiful, eco-friendly garden for your home or business. [131] -------. We will teach you how to plant a rain garden, which is simply a shallow sunken garden [132] ------- a special soil mix to filter pollutants from rainwater flowing from nearby roads and rooftops. These gardens can be landscaped with native plants and flowers. [133] -------, rain gardens are always beneficial to the local environment. Among other things, [134] ------- improve drainage and protect rivers and streams.","vi":"Hãy đến với Maxley Heights Center for Horticulture để học cách tạo nên một khu vườn xinh đẹp, thân thiện với môi trường cho ngôi nhà hoặc doanh nghiệp của bạn. [131]. Chúng tôi sẽ hướng dẫn bạn cách trồng một khu vườn mưa — đơn giản là một khu vườn trũng nông [132] hỗn hợp đất đặc biệt để lọc các chất ô nhiễm trong nước mưa chảy từ các tuyến đường và mái nhà lân cận. Những khu vườn này có thể được thiết kế cảnh quan bằng các loài cây và hoa bản địa. [133], vườn mưa luôn mang lại lợi ích cho môi trường địa phương. Bên cạnh những tác dụng khác, [134] giúp cải thiện khả năng thoát nước và bảo vệ sông suối.","units":[{"en":"Come to the Maxley Heights Center for Horticulture and learn how to create a beautiful, eco-friendly garden for your home or business. [131] -------.","vi":"Hãy đến với Maxley Heights Center for Horticulture để học cách tạo nên một khu vườn xinh đẹp, thân thiện với môi trường cho ngôi nhà hoặc doanh nghiệp của bạn. [131]."},{"en":"We will teach you how to plant a rain garden, which is simply a shallow sunken garden [132] ------- a special soil mix to filter pollutants from rainwater flowing from nearby roads and rooftops.","vi":"Chúng tôi sẽ hướng dẫn bạn cách trồng một khu vườn mưa — đơn giản là một khu vườn trũng nông [132] hỗn hợp đất đặc biệt để lọc các chất ô nhiễm trong nước mưa chảy từ các tuyến đường và mái nhà lân cận."},{"en":"These gardens can be landscaped with native plants and flowers.","vi":"Những khu vườn này có thể được thiết kế cảnh quan bằng các loài cây và hoa bản địa."},{"en":"[133] -------, rain gardens are always beneficial to the local environment.","vi":"[133], vườn mưa luôn mang lại lợi ích cho môi trường địa phương."},{"en":"Among other things, [134] ------- improve drainage and protect rivers and streams.","vi":"Bên cạnh những tác dụng khác, [134] giúp cải thiện khả năng thoát nước và bảo vệ sông suối."}]},{"speaker":"","en":"To register, visit www.maxley-horticulture.org.","vi":"Để đăng ký, vui lòng truy cập www.maxley-horticulture.org.","units":[{"en":"To register, visit www.maxley-horticulture.org.","vi":"Để đăng ký, vui lòng truy cập www.maxley-horticulture.org."}]}],"vocab":[{"word":"among other things","pos":"phr","ipa":"/əˈmʌŋ ˈʌðər θɪŋz/","meaning":"bên cạnh những điều/tác dụng khác"},{"word":"drainage","pos":"n","ipa":"/ˈdreɪnɪdʒ/","meaning":"hệ thống hoặc khả năng thoát nước"},{"word":"stream","pos":"n","ipa":"/striːm/","meaning":"dòng suối, khe nước"}],"isScanBacked":false,"docTypeLabel":"notice","context":"Notice from Maxley Heights Center for Horticulture announcing a free rain-garden workshop","grammarType":"Đại từ / Từ hạn định (Pronoun & Determiner)","formula":"CÔNG THỨC PART 6 (Tờ A3 Màu — Đại từ nhân xưng chủ ngữ): Trước động từ chính chia số nhiều \"improve\" và \"protect\" cần đại từ chủ ngữ số nhiều quy chiếu về danh từ số nhiều \"rain gardens\" ở câu liền trước -> Chọn \"they\".","optionAnalysis":{"A":"Sai đối tượng quy chiếu: \"we\" chỉ đội ngũ của Maxley Heights Center for Horticulture, không phải chủ thể cải thiện thoát nước và bảo vệ sông suối được giải thích ngay sau câu nói về \"rain gardens\".","B":"Đáp án chính xác: \"they\" là đại từ chủ ngữ ngôi thứ ba số nhiều thay thế cho \"rain gardens\" ở câu trước và chia đúng dạng nguyên mẫu với cặp động từ \"improve\" và \"protect\".","C":"Sai điều kiện sử dụng: đại từ \"both\" đòi hỏi phải có đúng hai danh từ/đối tượng đã xác định trước đó, trong khi câu liền trước chỉ nhắc đến đối tượng số nhiều chung là \"rain gardens\".","D":"Sai quy chiếu sở hữu: \"yours\" (của bạn) không thay thế cho danh từ chung \"rain gardens\", và ở câu đầu văn bản chỉ nhắc đến một khu vườn số ít cho nhà hoặc doanh nghiệp của bạn."},"evDocIdx":0,"evTargets":[{"badge":"Câu 134 · Đáp án B","opt":"B","isCorrect":true,"quote":"rain gardens are always beneficial to the local environment.","viQuote":"vườn mưa luôn mang lại lợi ích cho môi trường địa phương."},{"badge":"Câu 134 · Đáp án B","opt":"B","isCorrect":true,"quote":"improve drainage and protect rivers and streams.","viQuote":"giúp cải thiện khả năng thoát nước và bảo vệ sông suối."}],"evQuotes":["rain gardens are always beneficial to the local environment.","improve drainage and protect rivers and streams."]},{"q":135,"part":6,"group_id":"E25_T01_G135_138","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc05.webp"],"stem_en":"Select the best answer for blank (135) in the passage.","stem_vi":"Chọn đáp án phù hợp nhất để điền vào chỗ trống (135) trong đoạn văn.","options":{"A":{"en":"amazed","vi":"ngạc nhiên, kinh ngạc (adj - chỉ cảm xúc)"},"B":{"en":"amazement","vi":"sự kinh ngạc (n)"},"C":{"en":"amazing","vi":"tuyệt vời, đáng kinh ngạc (adj - chỉ tính chất)"},"D":{"en":"amazingly","vi":"một cách đáng kinh ngạc (adv)"}},"ans":"C","explanation":"Đáp án đúng: (C) amazing (tuyệt vời, đáng kinh ngạc) — tính từ đuôi \"-ing\" bổ nghĩa cho tính chất của danh từ chỉ sự việc \"support\" sau tính từ sở hữu \"your\".\nDẫn chứng: \"Thank you for your [135] ------- support in helping me to plan the opening gala for Tokyo's fashion week.\" (Cảm ơn sự hỗ trợ tuyệt vời của ông trong việc giúp tôi lên kế hoạch cho dạ tiệc khai mạc tuần lễ thời trang Tokyo).\nPhân tích bẫy:\n- (A) Sai phân loại tính từ: \"amazed\" (-ed) chỉ cảm xúc của con người (\"cảm thấy kinh ngạc\"), không dùng để mô tả tính chất của danh từ \"support\".\n- (B) Sai từ loại: \"amazement\" là danh từ (\"sự kinh ngạc\"), đứng trước danh từ \"support\" không tạo thành cụm danh từ có nghĩa hợp lý.\n- (D) Sai từ loại: \"amazingly\" là trạng từ, không thể đứng giữa tính từ sở hữu \"your\" và danh từ \"support\" để bổ nghĩa trực tiếp cho danh từ.","lines":[{"speaker":"","en":"31 July","vi":"Ngày 31 tháng 7","units":[{"en":"31 July","vi":"Ngày 31 tháng 7"}]},{"speaker":"","en":"Akwasi Dombo, Fourth Avenue, GA 105, Accra, Ghana","vi":"Người nhận: Akwasi Dombo, Fourth Avenue, GA 105, Accra, Ghana","units":[{"en":"Akwasi Dombo, Fourth Avenue, GA 105, Accra, Ghana","vi":"Người nhận: Akwasi Dombo, Fourth Avenue, GA 105, Accra, Ghana"}]},{"speaker":"","en":"Dear Mr. Dombo,","vi":"Kính gửi ông Dombo,","units":[{"en":"Dear Mr. Dombo,","vi":"Kính gửi ông Dombo,"}]},{"speaker":"","en":"Thank you for your [135] ------- support in helping me to plan the opening gala for Tokyo's fashion week. The event was a huge success, and I was honored to work with you. I know that our attendees follow your work closely, and they loved the designs you contributed for this event. Your designs received a lot of [136] ------- on social media. Shows like this will keep Tokyo on the map as a premier fashion centre. [137] -------. I realize that the multiple delays made the planning no easy task. The auction [138] ------- our Young Designers Award program is coming up soon and I look forward to working with you on that as well.","vi":"Cảm ơn sự hỗ trợ [135] của ông trong việc giúp tôi lên kế hoạch cho dạ tiệc khai mạc tuần lễ thời trang Tokyo. Sự kiện đã thành công rực rỡ, và tôi rất vinh dự được làm việc cùng ông. Tôi biết khách tham dự của chúng tôi luôn theo dõi sát sao các tác phẩm của ông, và họ rất yêu thích những thiết kế mà ông đóng góp cho sự kiện lần này. Các thiết kế của ông đã nhận được rất nhiều [136] trên mạng xã hội. Những buổi trình diễn như thế này sẽ giúp Tokyo tiếp tục giữ vững vị thế là một trung tâm thời trang hàng đầu. [137]. Tôi hiểu rằng nhiều lần trì hoãn đã khiến công tác lên kế hoạch không hề dễ dàng. Buổi đấu giá [138] chương trình Young Designers Award của chúng tôi sắp diễn ra và tôi cũng rất mong được hợp tác với ông trong sự kiện đó.","units":[{"en":"Thank you for your [135] ------- support in helping me to plan the opening gala for Tokyo's fashion week.","vi":"Cảm ơn sự hỗ trợ [135] của ông trong việc giúp tôi lên kế hoạch cho dạ tiệc khai mạc tuần lễ thời trang Tokyo."},{"en":"The event was a huge success, and I was honored to work with you.","vi":"Sự kiện đã thành công rực rỡ, và tôi rất vinh dự được làm việc cùng ông."},{"en":"I know that our attendees follow your work closely, and they loved the designs you contributed for this event.","vi":"Tôi biết khách tham dự của chúng tôi luôn theo dõi sát sao các tác phẩm của ông, và họ rất yêu thích những thiết kế mà ông đóng góp cho sự kiện lần này."},{"en":"Your designs received a lot of [136] ------- on social media.","vi":"Các thiết kế của ông đã nhận được rất nhiều [136] trên mạng xã hội."},{"en":"Shows like this will keep Tokyo on the map as a premier fashion centre. [137] -------.","vi":"Những buổi trình diễn như thế này sẽ giúp Tokyo tiếp tục giữ vững vị thế là một trung tâm thời trang hàng đầu. [137]."},{"en":"I realize that the multiple delays made the planning no easy task.","vi":"Tôi hiểu rằng nhiều lần trì hoãn đã khiến công tác lên kế hoạch không hề dễ dàng."},{"en":"The auction [138] ------- our Young Designers Award program is coming up soon and I look forward to working with you on that as well.","vi":"Buổi đấu giá [138] chương trình Young Designers Award của chúng tôi sắp diễn ra và tôi cũng rất mong được hợp tác với ông trong sự kiện đó."}]},{"speaker":"","en":"Sincerely,","vi":"Trân trọng,","units":[{"en":"Sincerely,","vi":"Trân trọng,"}]},{"speaker":"","en":"Asahi Ishioka","vi":"Asahi Ishioka","units":[{"en":"Asahi Ishioka","vi":"Asahi Ishioka"}]},{"speaker":"","en":"Director, Japanese Guild of Fashion Designers","vi":"Giám đốc, Japanese Guild of Fashion Designers","units":[{"en":"Director, Japanese Guild of Fashion Designers","vi":"Giám đốc, Japanese Guild of Fashion Designers"}]}],"vocab":[{"word":"gala","pos":"n","ipa":"/ˈɡeɪlə/","meaning":"dạ tiệc, buổi lễ kỷ niệm trang trọng"},{"word":"honored","pos":"adj","ipa":"/ˈɑːnərd/","meaning":"vinh dự, hân hạnh"},{"word":"attendee","pos":"n","ipa":"/əˌtenˈdiː/","meaning":"người tham dự, khách tham dự"}],"isScanBacked":false,"docTypeLabel":"letter","context":"Thank-you letter from Asahi Ishioka of the Japanese Guild of Fashion Designers to Akwasi Dombo","grammarType":"Từ loại (Word Form: Danh từ / Động từ / Tính từ / Trạng từ)","formula":"CÔNG THỨC PART 6 (Tờ A3 Màu — Tính từ đuôi -ing vs -ed): Giữa tính từ sở hữu \"your\" và danh từ chỉ sự việc \"support\" cần Tính từ miêu tả tính chất -> Chọn tính từ chủ động đuôi \"-ing\" (amazing) thay vì đuôi \"-ed\" chỉ cảm xúc (amazed).","optionAnalysis":{"A":"Sai loại tính từ: \"amazed\" mang nghĩa bị tác động cảm xúc (\"cảm thấy ngạc nhiên\"), chỉ dùng cho người hoặc sinh vật, không dùng để miêu tả tính chất của danh từ \"support\".","B":"Sai từ loại: \"amazement\" là danh từ (\"sự ngạc nhiên\"), không thể dùng làm định ngữ miêu tả mức độ đáng khen cho danh từ \"support\" sau \"your\".","C":"Đáp án chính xác: \"amazing\" là tính từ đuôi -ing miêu tả bản chất xuất sắc của danh từ \"support\" trong cụm \"your amazing support\".","D":"Sai từ loại: \"amazingly\" là trạng từ (\"một cách đáng kinh ngạc\"), chỉ bổ nghĩa cho động từ, tính từ hoặc cả câu chứ không bổ nghĩa trực tiếp cho danh từ \"support\"."},"evDocIdx":0,"evTargets":[{"badge":"Câu 135 · Đáp án C","opt":"C","isCorrect":true,"quote":"Thank you for your","viQuote":"Cảm ơn sự hỗ trợ"},{"badge":"Câu 135 · Đáp án C","opt":"C","isCorrect":true,"quote":"support in helping me to plan the opening gala for Tokyo's fashion week.","viQuote":"của ông trong việc giúp tôi lên kế hoạch cho dạ tiệc khai mạc tuần lễ thời trang Tokyo."}],"evQuotes":["Thank you for your","support in helping me to plan the opening gala for Tokyo's fashion week."]},{"q":136,"part":6,"group_id":"E25_T01_G135_138","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc05.webp"],"stem_en":"Select the best answer for blank (136) in the passage.","stem_vi":"Chọn đáp án phù hợp nhất để điền vào chỗ trống (136) trong đoạn văn.","options":{"A":{"en":"attention","vi":"sự chú ý, quan tâm"},"B":{"en":"proposals","vi":"các đề xuất"},"C":{"en":"innovation","vi":"sự đổi mới, sáng tạo"},"D":{"en":"criticism","vi":"sự chỉ trích, phê bình"}},"ans":"A","explanation":"Đáp án đúng: (A) attention (sự chú ý) — kết hợp chuẩn tự nhiên trong cụm \"receive a lot of attention on social media\", phù hợp với ngữ cảnh các mẫu thiết kế được yêu thích.\nDẫn chứng: \"I know that our attendees follow your work closely, and they loved the designs you contributed for this event. Your designs received a lot of [136] ------- on social media.\" (Khách tham dự rất yêu thích các thiết kế của ông. Các thiết kế của ông đã nhận được rất nhiều sự chú ý trên mạng xã hội).\nPhân tích bẫy:\n- (B) Sai nghĩa ngữ cảnh: \"proposals\" (các đề xuất, bản kiến nghị) không hợp với việc các thiết kế thời trang thu hút phản hồi trên mạng xã hội.\n- (C) Sai kết hợp từ: \"innovation\" (sự đổi mới) là phẩm chất sáng tạo của thiết kế, không dùng cấu trúc thiết kế \"nhận được nhiều sự đổi mới trên mạng xã hội\".\n- (D) Sai sắc thái nghĩa: \"criticism\" (sự chỉ trích, phê bình tiêu cực) trái ngược hoàn toàn với lời khen sự kiện thành công rực rỡ và khách rất yêu thích ở các câu trước.","lines":[{"speaker":"","en":"31 July","vi":"Ngày 31 tháng 7","units":[{"en":"31 July","vi":"Ngày 31 tháng 7"}]},{"speaker":"","en":"Akwasi Dombo, Fourth Avenue, GA 105, Accra, Ghana","vi":"Người nhận: Akwasi Dombo, Fourth Avenue, GA 105, Accra, Ghana","units":[{"en":"Akwasi Dombo, Fourth Avenue, GA 105, Accra, Ghana","vi":"Người nhận: Akwasi Dombo, Fourth Avenue, GA 105, Accra, Ghana"}]},{"speaker":"","en":"Dear Mr. Dombo,","vi":"Kính gửi ông Dombo,","units":[{"en":"Dear Mr. Dombo,","vi":"Kính gửi ông Dombo,"}]},{"speaker":"","en":"Thank you for your [135] ------- support in helping me to plan the opening gala for Tokyo's fashion week. The event was a huge success, and I was honored to work with you. I know that our attendees follow your work closely, and they loved the designs you contributed for this event. Your designs received a lot of [136] ------- on social media. Shows like this will keep Tokyo on the map as a premier fashion centre. [137] -------. I realize that the multiple delays made the planning no easy task. The auction [138] ------- our Young Designers Award program is coming up soon and I look forward to working with you on that as well.","vi":"Cảm ơn sự hỗ trợ [135] của ông trong việc giúp tôi lên kế hoạch cho dạ tiệc khai mạc tuần lễ thời trang Tokyo. Sự kiện đã thành công rực rỡ, và tôi rất vinh dự được làm việc cùng ông. Tôi biết khách tham dự của chúng tôi luôn theo dõi sát sao các tác phẩm của ông, và họ rất yêu thích những thiết kế mà ông đóng góp cho sự kiện lần này. Các thiết kế của ông đã nhận được rất nhiều [136] trên mạng xã hội. Những buổi trình diễn như thế này sẽ giúp Tokyo tiếp tục giữ vững vị thế là một trung tâm thời trang hàng đầu. [137]. Tôi hiểu rằng nhiều lần trì hoãn đã khiến công tác lên kế hoạch không hề dễ dàng. Buổi đấu giá [138] chương trình Young Designers Award của chúng tôi sắp diễn ra và tôi cũng rất mong được hợp tác với ông trong sự kiện đó.","units":[{"en":"Thank you for your [135] ------- support in helping me to plan the opening gala for Tokyo's fashion week.","vi":"Cảm ơn sự hỗ trợ [135] của ông trong việc giúp tôi lên kế hoạch cho dạ tiệc khai mạc tuần lễ thời trang Tokyo."},{"en":"The event was a huge success, and I was honored to work with you.","vi":"Sự kiện đã thành công rực rỡ, và tôi rất vinh dự được làm việc cùng ông."},{"en":"I know that our attendees follow your work closely, and they loved the designs you contributed for this event.","vi":"Tôi biết khách tham dự của chúng tôi luôn theo dõi sát sao các tác phẩm của ông, và họ rất yêu thích những thiết kế mà ông đóng góp cho sự kiện lần này."},{"en":"Your designs received a lot of [136] ------- on social media.","vi":"Các thiết kế của ông đã nhận được rất nhiều [136] trên mạng xã hội."},{"en":"Shows like this will keep Tokyo on the map as a premier fashion centre. [137] -------.","vi":"Những buổi trình diễn như thế này sẽ giúp Tokyo tiếp tục giữ vững vị thế là một trung tâm thời trang hàng đầu. [137]."},{"en":"I realize that the multiple delays made the planning no easy task.","vi":"Tôi hiểu rằng nhiều lần trì hoãn đã khiến công tác lên kế hoạch không hề dễ dàng."},{"en":"The auction [138] ------- our Young Designers Award program is coming up soon and I look forward to working with you on that as well.","vi":"Buổi đấu giá [138] chương trình Young Designers Award của chúng tôi sắp diễn ra và tôi cũng rất mong được hợp tác với ông trong sự kiện đó."}]},{"speaker":"","en":"Sincerely,","vi":"Trân trọng,","units":[{"en":"Sincerely,","vi":"Trân trọng,"}]},{"speaker":"","en":"Asahi Ishioka","vi":"Asahi Ishioka","units":[{"en":"Asahi Ishioka","vi":"Asahi Ishioka"}]},{"speaker":"","en":"Director, Japanese Guild of Fashion Designers","vi":"Giám đốc, Japanese Guild of Fashion Designers","units":[{"en":"Director, Japanese Guild of Fashion Designers","vi":"Giám đốc, Japanese Guild of Fashion Designers"}]}],"vocab":[{"word":"contribute","pos":"v","ipa":"/kənˈtrɪbjuːt/","meaning":"đóng góp, góp phần"},{"word":"attention","pos":"n","ipa":"/əˈtenʃən/","meaning":"sự chú ý, sự quan tâm"},{"word":"proposal","pos":"n","ipa":"/prəˈpoʊzəl/","meaning":"bản đề xuất, lời đề nghị"},{"word":"criticism","pos":"n","ipa":"/ˈkrɪtɪsɪzəm/","meaning":"sự chỉ trích, lời phê bình"}],"isScanBacked":false,"docTypeLabel":"letter","context":"Thank-you letter from Asahi Ishioka of the Japanese Guild of Fashion Designers to Akwasi Dombo","grammarType":"Từ vựng — Danh từ (Noun)","formula":"CÔNG THỨC PART 6 (COLLOCATION THUỘC LÒNG — Cụm danh từ theo ngữ cảnh): Động từ \"received a lot of + [Danh từ] + on social media\" kết hợp với ngữ cảnh tích cực (khách yêu thích các mẫu thiết kế) -> Chọn \"attention\" (nhận được nhiều sự chú ý).","optionAnalysis":{"A":"Đáp án chính xác: tạo cụm tự nhiên \"received a lot of attention on social media\" (nhận được nhiều sự chú ý trên mạng xã hội), khớp mạch khen ngợi tác phẩm của ông Dombo.","B":"Sai nghĩa ngữ cảnh: \"proposals\" nghĩa là \"các bản đề xuất/đề nghị\", không phù hợp với phản ứng của công chúng trên mạng xã hội dành cho các mẫu thiết kế thời trang.","C":"Sai kết hợp nghĩa: \"innovation\" là \"sự đổi mới\", không phù hợp với động từ \"received a lot of [136] on social media\" vì mạng xã hội không trao sự đổi mới cho các mẫu thiết kế.","D":"Sai sắc thái câu văn: \"criticism\" mang nghĩa tiêu cực (\"sự chỉ trích\"), mâu thuẫn trực tiếp với câu liền trước khẳng định sự kiện \"a huge success\" và người xem \"loved the designs\"."},"evDocIdx":0,"evTargets":[{"badge":"Câu 136 · Đáp án A","opt":"A","isCorrect":true,"quote":"they loved the designs you contributed for this event.","viQuote":"họ rất yêu thích những thiết kế mà ông đóng góp cho sự kiện lần này."},{"badge":"Câu 136 · Đáp án A","opt":"A","isCorrect":true,"quote":"Your designs received a lot of","viQuote":"Các thiết kế của ông đã nhận được rất nhiều"}],"evQuotes":["they loved the designs you contributed for this event.","Your designs received a lot of"]},{"q":137,"part":6,"group_id":"E25_T01_G135_138","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc05.webp"],"stem_en":"Select the best answer for blank (137) in the passage.","stem_vi":"137. Chọn câu phù hợp nhất điền vào chỗ trống [137].","options":{"A":{"en":"Several other events have gone surprisingly well.","vi":"Một số sự kiện khác cũng đã diễn ra suôn sẻ đến bất ngờ."},"B":{"en":"Thank you also for your flexibility in planning the event.","vi":"Tôi cũng xin cảm ơn sự linh hoạt của ông trong quá trình lên kế hoạch cho sự kiện."},"C":{"en":"Please stop by our office the next time you are in the city.","vi":"Xin mời ông ghé thăm văn phòng của chúng tôi vào lần tới khi ông có dịp đến thành phố."},"D":{"en":"Tokyo is a top tourism destination for many reasons.","vi":"Tokyo là một điểm đến du lịch hàng đầu vì nhiều lý do."}},"ans":"B","explanation":"Đáp án đúng: (B) Tôi cũng xin cảm ơn sự linh hoạt của ông trong quá trình lên kế hoạch cho sự kiện — mở ra chủ đề \"planning the event\" để câu tiếp theo giải thích hợp lý về việc nhiều lần trì hoãn đã gây khó khăn cho khâu lên kế hoạch.\nDẫn chứng: \"Shows like this will keep Tokyo on the map as a premier fashion centre. [137] -------. I realize that the multiple delays made the planning no easy task.\" (Khớp cặp từ khóa liên kết tiến: \"flexibility in planning the event\" nối trực tiếp sang \"the multiple delays made the planning no easy task\").\nPhân tích bẫy:\n- (A) Lạc mạch liên kết: nhắc chung chung đến \"nhiều sự kiện khác\" diễn ra suôn sẻ, không tạo cầu nối với câu tiếp theo nói về việc trì hoãn khi lên kế hoạch sự kiện hiện tại.\n- (C) Sai vị trí logic: lời mời ghé thăm văn phòng khi đến thành phố ngắt quãng mạch cảm ơn trước câu nhắc đến những lần trì hoãn trong khâu lập kế hoạch.\n- (D) Lạc trọng tâm: mở rộng sang chủ đề du lịch Tokyo nói chung (\"top tourism destination\"), đứt mạch hoàn toàn với nội dung tri ân quá trình tổ chức tuần lễ thời trang.","lines":[{"speaker":"","en":"31 July","vi":"Ngày 31 tháng 7","units":[{"en":"31 July","vi":"Ngày 31 tháng 7"}]},{"speaker":"","en":"Akwasi Dombo, Fourth Avenue, GA 105, Accra, Ghana","vi":"Người nhận: Akwasi Dombo, Fourth Avenue, GA 105, Accra, Ghana","units":[{"en":"Akwasi Dombo, Fourth Avenue, GA 105, Accra, Ghana","vi":"Người nhận: Akwasi Dombo, Fourth Avenue, GA 105, Accra, Ghana"}]},{"speaker":"","en":"Dear Mr. Dombo,","vi":"Kính gửi ông Dombo,","units":[{"en":"Dear Mr. Dombo,","vi":"Kính gửi ông Dombo,"}]},{"speaker":"","en":"Thank you for your [135] ------- support in helping me to plan the opening gala for Tokyo's fashion week. The event was a huge success, and I was honored to work with you. I know that our attendees follow your work closely, and they loved the designs you contributed for this event. Your designs received a lot of [136] ------- on social media. Shows like this will keep Tokyo on the map as a premier fashion centre. [137] -------. I realize that the multiple delays made the planning no easy task. The auction [138] ------- our Young Designers Award program is coming up soon and I look forward to working with you on that as well.","vi":"Cảm ơn sự hỗ trợ [135] của ông trong việc giúp tôi lên kế hoạch cho dạ tiệc khai mạc tuần lễ thời trang Tokyo. Sự kiện đã thành công rực rỡ, và tôi rất vinh dự được làm việc cùng ông. Tôi biết khách tham dự của chúng tôi luôn theo dõi sát sao các tác phẩm của ông, và họ rất yêu thích những thiết kế mà ông đóng góp cho sự kiện lần này. Các thiết kế của ông đã nhận được rất nhiều [136] trên mạng xã hội. Những buổi trình diễn như thế này sẽ giúp Tokyo tiếp tục giữ vững vị thế là một trung tâm thời trang hàng đầu. [137]. Tôi hiểu rằng nhiều lần trì hoãn đã khiến công tác lên kế hoạch không hề dễ dàng. Buổi đấu giá [138] chương trình Young Designers Award của chúng tôi sắp diễn ra và tôi cũng rất mong được hợp tác với ông trong sự kiện đó.","units":[{"en":"Thank you for your [135] ------- support in helping me to plan the opening gala for Tokyo's fashion week.","vi":"Cảm ơn sự hỗ trợ [135] của ông trong việc giúp tôi lên kế hoạch cho dạ tiệc khai mạc tuần lễ thời trang Tokyo."},{"en":"The event was a huge success, and I was honored to work with you.","vi":"Sự kiện đã thành công rực rỡ, và tôi rất vinh dự được làm việc cùng ông."},{"en":"I know that our attendees follow your work closely, and they loved the designs you contributed for this event.","vi":"Tôi biết khách tham dự của chúng tôi luôn theo dõi sát sao các tác phẩm của ông, và họ rất yêu thích những thiết kế mà ông đóng góp cho sự kiện lần này."},{"en":"Your designs received a lot of [136] ------- on social media.","vi":"Các thiết kế của ông đã nhận được rất nhiều [136] trên mạng xã hội."},{"en":"Shows like this will keep Tokyo on the map as a premier fashion centre. [137] -------.","vi":"Những buổi trình diễn như thế này sẽ giúp Tokyo tiếp tục giữ vững vị thế là một trung tâm thời trang hàng đầu. [137]."},{"en":"I realize that the multiple delays made the planning no easy task.","vi":"Tôi hiểu rằng nhiều lần trì hoãn đã khiến công tác lên kế hoạch không hề dễ dàng."},{"en":"The auction [138] ------- our Young Designers Award program is coming up soon and I look forward to working with you on that as well.","vi":"Buổi đấu giá [138] chương trình Young Designers Award của chúng tôi sắp diễn ra và tôi cũng rất mong được hợp tác với ông trong sự kiện đó."}]},{"speaker":"","en":"Sincerely,","vi":"Trân trọng,","units":[{"en":"Sincerely,","vi":"Trân trọng,"}]},{"speaker":"","en":"Asahi Ishioka","vi":"Asahi Ishioka","units":[{"en":"Asahi Ishioka","vi":"Asahi Ishioka"}]},{"speaker":"","en":"Director, Japanese Guild of Fashion Designers","vi":"Giám đốc, Japanese Guild of Fashion Designers","units":[{"en":"Director, Japanese Guild of Fashion Designers","vi":"Giám đốc, Japanese Guild of Fashion Designers"}]}],"vocab":[{"word":"premier","pos":"adj","ipa":"/prɪˈmɪr/","meaning":"hàng đầu, đứng đầu"},{"word":"flexibility","pos":"n","ipa":"/ˌfleksəˈbɪləti/","meaning":"sự linh hoạt, tính mềm dẻo"},{"word":"delay","pos":"n","ipa":"/dɪˈleɪ/","meaning":"sự trì hoãn, sự chậm trễ"},{"word":"keep on the map","pos":"phr","ipa":"/kiːp ɑːn ðə mæp/","meaning":"giữ vững vị thế nổi bật, được biết đến"}],"isScanBacked":false,"docTypeLabel":"letter","context":"Thank-you letter from Asahi Ishioka of the Japanese Guild of Fashion Designers to Akwasi Dombo","grammarType":"Điền câu hoàn chỉnh vào mạch đoạn văn (Sentence Insertion)","formula":"CÔNG THỨC PART 6 (6. PART 6 THUỘC LÒNG — Điền câu vào mạch đoạn văn): Đọc câu liền sau [137] (\"I realize that the multiple delays made the planning no easy task.\") -> Câu cần điền phải đề cập đến quá trình lên kế hoạch sự kiện (\"planning the event\") để giải thích cho khó khăn trì hoãn ở câu sau.","optionAnalysis":{"A":"Đứt mạch câu sau: nói về \"các sự kiện khác\" diễn ra suôn sẻ khiến câu kế tiếp nhắc đến \"multiple delays made the planning no easy task\" bị hụt chủ ngữ quy chiếu.","B":"Đáp án chính xác: cảm ơn sự linh hoạt của người nhận trong việc \"planning the event\", làm tiền đề trực tiếp cho câu ngay sau nhắc tới những lần trì hoãn gây khó cho việc lên kế hoạch.","C":"Sai vị trí trong đoạn văn: câu mời ghé thăm văn phòng làm đứt mạch chuyển ý sang câu tiếp theo nói về sự trì hoãn trong công tác lập kế hoạch sự kiện vừa qua.","D":"Lạc đề khỏi nội dung thư: bàn sang việc Tokyo là điểm đến du lịch hàng đầu vì nhiều lý do, không liên quan đến việc cảm ơn đóng góp hay sự linh hoạt tổ chức sự kiện."},"evDocIdx":0,"evTargets":[{"badge":"Câu 137 · Đáp án B","opt":"B","isCorrect":true,"quote":"Shows like this will keep Tokyo on the map as a premier fashion centre.","viQuote":"Những buổi trình diễn như thế này sẽ giúp Tokyo tiếp tục giữ vững vị thế là một trung tâm thời trang hàng đầu."},{"badge":"Câu 137 · Đáp án B","opt":"B","isCorrect":true,"quote":"I realize that the multiple delays made the planning no easy task.","viQuote":"Tôi hiểu rằng nhiều lần trì hoãn đã khiến công tác lên kế hoạch không hề dễ dàng."}],"evQuotes":["Shows like this will keep Tokyo on the map as a premier fashion centre.","I realize that the multiple delays made the planning no easy task."]},{"q":138,"part":6,"group_id":"E25_T01_G135_138","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc05.webp"],"stem_en":"Select the best answer for blank (138) in the passage.","stem_vi":"Chọn đáp án phù hợp nhất để điền vào chỗ trống (138) trong đoạn văn.","options":{"A":{"en":"will benefit","vi":"sẽ mang lại lợi ích cho (tương lai đơn)"},"B":{"en":"to benefit","vi":"nhằm gây quỹ hỗ trợ / mang lại lợi ích cho (động từ nguyên mẫu chỉ mục đích)"},"C":{"en":"has benefited","vi":"đã mang lại lợi ích cho (hiện tại hoàn thành)"},"D":{"en":"benefits","vi":"mang lại lợi ích cho (hiện tại đơn)"}},"ans":"B","explanation":"Đáp án đúng: (B) to benefit (nhằm mang lại lợi ích / gây quỹ hỗ trợ) — động từ nguyên mẫu có \"to\" diễn tả mục đích của danh từ \"The auction\", giữ \"is coming up\" làm động từ chính duy nhất.\nDẫn chứng: \"The auction [138] ------- our Young Designers Award program is coming up soon and I look forward to working with you on that as well.\" (Buổi đấu giá nhằm gây quỹ hỗ trợ chương trình Young Designers Award của chúng tôi sắp diễn ra).\nPhân tích bẫy:\n- (A) Sai cấu trúc câu: \"will benefit\" là động từ chia thì tương lai đơn; dùng ở đây khiến mệnh đề có hai động từ chính (\"will benefit\" và \"is coming up\") mà không có đại từ quan hệ.\n- (C) Sai cấu trúc và thì: \"has benefited\" là động từ chia thì hiện tại hoàn thành, vừa thừa động từ chính vừa sai thời gian vì buổi đấu giá sắp diễn ra (\"coming up soon\").\n- (D) Sai cấu trúc câu: \"benefits\" là động từ chia thì hiện tại đơn, tạo lỗi xung đột hai động từ chính không có từ nối trong cùng một mệnh đề.","lines":[{"speaker":"","en":"31 July","vi":"Ngày 31 tháng 7","units":[{"en":"31 July","vi":"Ngày 31 tháng 7"}]},{"speaker":"","en":"Akwasi Dombo, Fourth Avenue, GA 105, Accra, Ghana","vi":"Người nhận: Akwasi Dombo, Fourth Avenue, GA 105, Accra, Ghana","units":[{"en":"Akwasi Dombo, Fourth Avenue, GA 105, Accra, Ghana","vi":"Người nhận: Akwasi Dombo, Fourth Avenue, GA 105, Accra, Ghana"}]},{"speaker":"","en":"Dear Mr. Dombo,","vi":"Kính gửi ông Dombo,","units":[{"en":"Dear Mr. Dombo,","vi":"Kính gửi ông Dombo,"}]},{"speaker":"","en":"Thank you for your [135] ------- support in helping me to plan the opening gala for Tokyo's fashion week. The event was a huge success, and I was honored to work with you. I know that our attendees follow your work closely, and they loved the designs you contributed for this event. Your designs received a lot of [136] ------- on social media. Shows like this will keep Tokyo on the map as a premier fashion centre. [137] -------. I realize that the multiple delays made the planning no easy task. The auction [138] ------- our Young Designers Award program is coming up soon and I look forward to working with you on that as well.","vi":"Cảm ơn sự hỗ trợ [135] của ông trong việc giúp tôi lên kế hoạch cho dạ tiệc khai mạc tuần lễ thời trang Tokyo. Sự kiện đã thành công rực rỡ, và tôi rất vinh dự được làm việc cùng ông. Tôi biết khách tham dự của chúng tôi luôn theo dõi sát sao các tác phẩm của ông, và họ rất yêu thích những thiết kế mà ông đóng góp cho sự kiện lần này. Các thiết kế của ông đã nhận được rất nhiều [136] trên mạng xã hội. Những buổi trình diễn như thế này sẽ giúp Tokyo tiếp tục giữ vững vị thế là một trung tâm thời trang hàng đầu. [137]. Tôi hiểu rằng nhiều lần trì hoãn đã khiến công tác lên kế hoạch không hề dễ dàng. Buổi đấu giá [138] chương trình Young Designers Award của chúng tôi sắp diễn ra và tôi cũng rất mong được hợp tác với ông trong sự kiện đó.","units":[{"en":"Thank you for your [135] ------- support in helping me to plan the opening gala for Tokyo's fashion week.","vi":"Cảm ơn sự hỗ trợ [135] của ông trong việc giúp tôi lên kế hoạch cho dạ tiệc khai mạc tuần lễ thời trang Tokyo."},{"en":"The event was a huge success, and I was honored to work with you.","vi":"Sự kiện đã thành công rực rỡ, và tôi rất vinh dự được làm việc cùng ông."},{"en":"I know that our attendees follow your work closely, and they loved the designs you contributed for this event.","vi":"Tôi biết khách tham dự của chúng tôi luôn theo dõi sát sao các tác phẩm của ông, và họ rất yêu thích những thiết kế mà ông đóng góp cho sự kiện lần này."},{"en":"Your designs received a lot of [136] ------- on social media.","vi":"Các thiết kế của ông đã nhận được rất nhiều [136] trên mạng xã hội."},{"en":"Shows like this will keep Tokyo on the map as a premier fashion centre. [137] -------.","vi":"Những buổi trình diễn như thế này sẽ giúp Tokyo tiếp tục giữ vững vị thế là một trung tâm thời trang hàng đầu. [137]."},{"en":"I realize that the multiple delays made the planning no easy task.","vi":"Tôi hiểu rằng nhiều lần trì hoãn đã khiến công tác lên kế hoạch không hề dễ dàng."},{"en":"The auction [138] ------- our Young Designers Award program is coming up soon and I look forward to working with you on that as well.","vi":"Buổi đấu giá [138] chương trình Young Designers Award của chúng tôi sắp diễn ra và tôi cũng rất mong được hợp tác với ông trong sự kiện đó."}]},{"speaker":"","en":"Sincerely,","vi":"Trân trọng,","units":[{"en":"Sincerely,","vi":"Trân trọng,"}]},{"speaker":"","en":"Asahi Ishioka","vi":"Asahi Ishioka","units":[{"en":"Asahi Ishioka","vi":"Asahi Ishioka"}]},{"speaker":"","en":"Director, Japanese Guild of Fashion Designers","vi":"Giám đốc, Japanese Guild of Fashion Designers","units":[{"en":"Director, Japanese Guild of Fashion Designers","vi":"Giám đốc, Japanese Guild of Fashion Designers"}]}],"vocab":[{"word":"auction","pos":"n","ipa":"/ˈɔːkʃən/","meaning":"buổi đấu giá"},{"word":"benefit","pos":"v","ipa":"/ˈbenɪfɪt/","meaning":"mang lại lợi ích cho, gây quỹ hỗ trợ"},{"word":"guild","pos":"n","ipa":"/ɡɪld/","meaning":"hiệp hội nghề nghiệp, hội đồng ngành"}],"isScanBacked":false,"docTypeLabel":"letter","context":"Thank-you letter from Asahi Ishioka of the Japanese Guild of Fashion Designers to Akwasi Dombo","grammarType":"Chia động từ — Thì / Thể (Bị động - Chủ động) / Dạng V-ing · to V","formula":"CÔNG THỨC PART 6 (Phân tích Cấu trúc S-V-O & Động từ nguyên mẫu chỉ mục đích): Câu đã có động từ chia thì chính là \"is coming up\" cho chủ ngữ \"The auction\" -> Chỗ trống không thể điền động từ chia thì thứ hai mà phải dùng \"to V\" chỉ mục đích (\"to benefit\").","optionAnalysis":{"A":"Sai ngữ pháp câu đơn: \"will benefit\" là động từ chia thì, nếu điền vào sẽ tạo hai động từ chính (\"will benefit\" và \"is coming up\") cho cùng chủ ngữ \"The auction\" mà thiếu đại từ quan hệ.","B":"Đáp án chính xác: dùng dạng nguyên mẫu \"to benefit\" để bổ nghĩa chỉ mục đích cho danh từ \"The auction\" (buổi đấu giá nhằm hỗ trợ chương trình), bảo toàn động từ chính \"is coming up\".","C":"Sai cả cấu trúc và thì: \"has benefited\" là động từ chia thì hiện tại hoàn thành gây dư động từ chính, đồng thời mâu thuẫn với trạng thái sự kiện sắp tới (\"is coming up soon\").","D":"Sai cấu trúc mệnh đề: \"benefits\" là động từ chia thì hiện tại đơn, không thể đứng nối giữa chủ ngữ \"The auction\" và động từ chính \"is coming up\" khi không có đại từ quan hệ."},"evDocIdx":0,"evTargets":[{"badge":"Câu 138 · Đáp án B","opt":"B","isCorrect":true,"quote":"our Young Designers Award program is coming up soon and I look forward to working with you on that as well.","viQuote":"chương trình Young Designers Award của chúng tôi sắp diễn ra và tôi cũng rất mong được hợp tác với ông trong sự kiện đó."}],"evQuotes":["our Young Designers Award program is coming up soon and I look forward to working with you on that as well."]},{"q":139,"part":6,"group_id":"E25_T01_G139_142","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc06.webp"],"stem_en":"Select the best answer for blank (139) in the passage.","stem_vi":"Chọn đáp án phù hợp nhất để điền vào chỗ trống (139) trong đoạn văn.","options":{"A":{"en":"It","vi":"Nó / Thẻ này (đại từ ngôi thứ ba số ít)"},"B":{"en":"You","vi":"Ông / Bạn (đại từ ngôi thứ hai)"},"C":{"en":"Our","vi":"Của chúng tôi (tính từ sở hữu)"},"D":{"en":"Each","vi":"Mỗi (từ hạn định / đại từ)"}},"ans":"A","explanation":"Đáp án đúng: (A) It (Nó / Thẻ này) — đại từ nhân xưng ngôi thứ ba số ít thay thế cho cụm danh từ \"your Mena Chin Library card\" ở câu trước.\nDẫn chứng: \"Please be advised that your Mena Chin Library card will expire one month from today. [139] ------- must be renewed if you intend to keep your membership for the coming year.\" (Thẻ thư viện của ông sẽ hết hạn sau một tháng kể từ hôm nay. Thẻ này phải được gia hạn nếu ông muốn duy trì tư cách thành viên).\nPhân tích bẫy:\n- (B) Sai nghĩa bị động: \"You\" là người đọc (ông Hughes), không thể kết hợp với \"must be renewed\" (\"phải được gia hạn\") như tấm thẻ thư viện.\n- (C) Sai từ loại: \"Our\" là tính từ sở hữu, không thể đứng độc lập làm chủ ngữ mà bắt buộc phải có danh từ đi kèm phía sau.\n- (D) Sai quy chiếu số lượng: \"Each\" (mỗi cái) chỉ dùng khi đề cập từ hai thẻ trở lên, không phù hợp khi câu trước chỉ nói tới một thẻ số ít (\"card\").","lines":[{"speaker":"","en":"From: Patron Services <patronservices@menachinlibrary.org>","vi":"Từ: Bộ phận Dịch vụ Bạn đọc <patronservices@menachinlibrary.org>","units":[{"en":"From: Patron Services <patronservices@menachinlibrary.org>","vi":"Từ: Bộ phận Dịch vụ Bạn đọc <patronservices@menachinlibrary.org>"}]},{"speaker":"","en":"To: Edgar Hughes <hughese98@villachesta.com>","vi":"Đến: Edgar Hughes <hughese98@villachesta.com>","units":[{"en":"To: Edgar Hughes <hughese98@villachesta.com>","vi":"Đến: Edgar Hughes <hughese98@villachesta.com>"}]},{"speaker":"","en":"Subject: Card expiration date approaching","vi":"Chủ đề: Ngày hết hạn thẻ đang đến gần","units":[{"en":"Subject: Card expiration date approaching","vi":"Chủ đề: Ngày hết hạn thẻ đang đến gần"}]},{"speaker":"","en":"Date: December 3","vi":"Ngày: 3 tháng 12","units":[{"en":"Date: December 3","vi":"Ngày: 3 tháng 12"}]},{"speaker":"","en":"Dear Mr. Hughes,","vi":"Kính gửi ông Hughes,","units":[{"en":"Dear Mr. Hughes,","vi":"Kính gửi ông Hughes,"}]},{"speaker":"","en":"Please be advised that your Mena Chin Library card will expire one month from today. [139] ------- must be renewed if you intend to keep your membership for the coming year. [140] -------. This can be done at the information desk at any branch location.","vi":"Xin thông báo rằng thẻ thư viện Mena Chin Library của ông sẽ hết hạn sau một tháng kể từ hôm nay. [139] phải được gia hạn nếu ông dự định duy trì tư cách thành viên cho năm tới. [140]. Việc này có thể được thực hiện tại quầy thông tin ở bất kỳ chi nhánh nào.","units":[{"en":"Please be advised that your Mena Chin Library card will expire one month from today.","vi":"Xin thông báo rằng thẻ thư viện Mena Chin Library của ông sẽ hết hạn sau một tháng kể từ hôm nay."},{"en":"[139] ------- must be renewed if you intend to keep your membership for the coming year. [140] -------.","vi":"[139] phải được gia hạn nếu ông dự định duy trì tư cách thành viên cho năm tới. [140]."},{"en":"This can be done at the information desk at any branch location.","vi":"Việc này có thể được thực hiện tại quầy thông tin ở bất kỳ chi nhánh nào."}]},{"speaker":"","en":"[141] ------- you decide to close your account, no action is necessary. Failure to complete your renewal by the [142] ------- date will result in the expiration of your library privileges.","vi":"[141] ông quyết định đóng tài khoản của mình, không cần thực hiện bất kỳ thao tác nào. Việc không hoàn tất gia hạn trước ngày [142] sẽ khiến các quyền lợi thư viện của ông hết hiệu lực.","units":[{"en":"[141] ------- you decide to close your account, no action is necessary.","vi":"[141] ông quyết định đóng tài khoản của mình, không cần thực hiện bất kỳ thao tác nào."},{"en":"Failure to complete your renewal by the [142] ------- date will result in the expiration of your library privileges.","vi":"Việc không hoàn tất gia hạn trước ngày [142] sẽ khiến các quyền lợi thư viện của ông hết hiệu lực."}]},{"speaker":"","en":"If you have any questions about this notice, or about general library services, you may reply directly to this e-mail.","vi":"Nếu ông có bất kỳ thắc mắc nào về thông báo này hoặc về các dịch vụ chung của thư viện, ông có thể trả lời trực tiếp vào email này.","units":[{"en":"If you have any questions about this notice, or about general library services, you may reply directly to this e-mail.","vi":"Nếu ông có bất kỳ thắc mắc nào về thông báo này hoặc về các dịch vụ chung của thư viện, ông có thể trả lời trực tiếp vào email này."}]},{"speaker":"","en":"Sincerely, Patron Services","vi":"Trân trọng, Bộ phận Dịch vụ Bạn đọc","units":[{"en":"Sincerely, Patron Services","vi":"Trân trọng, Bộ phận Dịch vụ Bạn đọc"}]}],"vocab":[{"word":"expire","pos":"v","ipa":"/ɪkˈspaɪər/","meaning":"hết hạn, hết hiệu lực"},{"word":"renew","pos":"v","ipa":"/rɪˈnuː/","meaning":"gia hạn"},{"word":"membership","pos":"n","ipa":"/ˈmembərʃɪp/","meaning":"tư cách thành viên, thẻ hội viên"},{"word":"patron","pos":"n","ipa":"/ˈpeɪtrən/","meaning":"bạn đọc, khách hàng quen"}],"isScanBacked":false,"docTypeLabel":"e-mail","context":"E-mail from Mena Chin Library Patron Services to Edgar Hughes regarding library card expiration","grammarType":"Đại từ / Từ hạn định (Pronoun & Determiner)","formula":"CÔNG THỨC PART 6 (Tờ A3 Màu — Đại từ quy chiếu câu trước): Câu trước nhắc đến danh từ số ít chỉ vật \"your Mena Chin Library card\" + chỗ trống làm chủ ngữ của động từ bị động \"must be renewed\" -> Chọn đại từ số ít \"It\".","optionAnalysis":{"A":"Đáp án chính xác: đại từ số ít \"It\" quy chiếu chính xác về \"your Mena Chin Library card\" ở câu liền trước và phù hợp về nghĩa với vị ngữ bị động \"must be renewed\".","B":"Sai đối tượng của hành động: \"You\" chỉ người nhận email (ông Hughes), không phải đối tượng bị động chịu tác động \"must be renewed\" (phải được gia hạn) như thẻ thư viện.","C":"Sai cấu trúc từ loại: \"Our\" là tính từ sở hữu, thiếu danh từ theo sau nên không thể làm chủ ngữ đứng ngay trước trợ động từ khuyết thiếu \"must be renewed\".","D":"Sai ngữ cảnh số lượng: \"Each\" (mỗi chiếc) ám chỉ nhiều thẻ khác nhau, không khớp với danh từ đếm được số ít \"your Mena Chin Library card\" ở câu trước."},"evDocIdx":0,"evTargets":[{"badge":"Câu 139 · Đáp án A","opt":"A","isCorrect":true,"quote":"Please be advised that your Mena Chin Library card will expire one month from today.","viQuote":"Xin thông báo rằng thẻ thư viện Mena Chin Library của ông sẽ hết hạn sau một tháng kể từ hôm nay."},{"badge":"Câu 139 · Đáp án A","opt":"A","isCorrect":true,"quote":"must be renewed if you intend to keep your membership for the coming year.","viQuote":"phải được gia hạn nếu ông dự định duy trì tư cách thành viên cho năm tới."}],"evQuotes":["Please be advised that your Mena Chin Library card will expire one month from today.","must be renewed if you intend to keep your membership for the coming year."]},{"q":140,"part":6,"group_id":"E25_T01_G139_142","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc06.webp"],"stem_en":"Select the best answer for blank (140) in the passage.","stem_vi":"140. Chọn câu phù hợp nhất điền vào chỗ trống [140].","options":{"A":{"en":"To sign up for a card, visit your local library branch.","vi":"Để đăng ký làm thẻ, hãy đến chi nhánh thư viện địa phương của ông."},"B":{"en":"For questions about library membership, please visit our Web site.","vi":"Nếu có thắc mắc về tư cách thành viên thư viện, vui lòng truy cập trang web của chúng tôi."},"C":{"en":"Renewal must be completed at least one week before your card expires.","vi":"Việc gia hạn phải được hoàn tất ít nhất một tuần trước khi thẻ của ông hết hạn."},"D":{"en":"You may opt out of this program at any time.","vi":"Ông có thể rút khỏi chương trình này bất cứ lúc nào."}},"ans":"C","explanation":"Đáp án đúng: (C) Việc gia hạn phải được hoàn tất ít nhất một tuần trước khi thẻ của ông hết hạn — nối tiếp yêu cầu gia hạn ở câu 139, làm tiền đề cho đại từ \"This\" ở câu sau (chỉ việc hoàn tất gia hạn tại quầy thông tin) và khớp với mốc \"specified date\" ở câu 142.\nDẫn chứng: \"[139] ------- must be renewed if you intend to keep your membership for the coming year. [140] -------. This can be done at the information desk at any branch location.\" (Đại từ \"This\" ở câu sau quy chiếu trực tiếp về hành động hoàn tất gia hạn trong \"Renewal must be completed\", đồng thời giải thích cho \"the specified date\" ở đoạn 2).\nPhân tích bẫy:\n- (A) Sai bối cảnh người nhận: ông Hughes đã có thẻ sắp hết hạn (\"will expire\"), email yêu cầu gia hạn thẻ chứ không hướng dẫn đăng ký làm thẻ mới (\"sign up for a card\").\n- (B) Sai mạch quy chiếu \"This\": nếu đặt câu hướng dẫn truy cập trang web nếu có thắc mắc vào [140], đại từ \"This\" ở câu sau (\"tại quầy thông tin\") không còn ăn khớp với việc gia hạn thẻ.\n- (D) Sai ngữ cảnh thuật ngữ: không khớp với nội dung thư nói về gia hạn tư cách thành viên (\"membership\") và thẻ thư viện, đồng thời làm câu sau \"This can be done at the information desk\" mất logic.","lines":[{"speaker":"","en":"From: Patron Services <patronservices@menachinlibrary.org>","vi":"Từ: Bộ phận Dịch vụ Bạn đọc <patronservices@menachinlibrary.org>","units":[{"en":"From: Patron Services <patronservices@menachinlibrary.org>","vi":"Từ: Bộ phận Dịch vụ Bạn đọc <patronservices@menachinlibrary.org>"}]},{"speaker":"","en":"To: Edgar Hughes <hughese98@villachesta.com>","vi":"Đến: Edgar Hughes <hughese98@villachesta.com>","units":[{"en":"To: Edgar Hughes <hughese98@villachesta.com>","vi":"Đến: Edgar Hughes <hughese98@villachesta.com>"}]},{"speaker":"","en":"Subject: Card expiration date approaching","vi":"Chủ đề: Ngày hết hạn thẻ đang đến gần","units":[{"en":"Subject: Card expiration date approaching","vi":"Chủ đề: Ngày hết hạn thẻ đang đến gần"}]},{"speaker":"","en":"Date: December 3","vi":"Ngày: 3 tháng 12","units":[{"en":"Date: December 3","vi":"Ngày: 3 tháng 12"}]},{"speaker":"","en":"Dear Mr. Hughes,","vi":"Kính gửi ông Hughes,","units":[{"en":"Dear Mr. Hughes,","vi":"Kính gửi ông Hughes,"}]},{"speaker":"","en":"Please be advised that your Mena Chin Library card will expire one month from today. [139] ------- must be renewed if you intend to keep your membership for the coming year. [140] -------. This can be done at the information desk at any branch location.","vi":"Xin thông báo rằng thẻ thư viện Mena Chin Library của ông sẽ hết hạn sau một tháng kể từ hôm nay. [139] phải được gia hạn nếu ông dự định duy trì tư cách thành viên cho năm tới. [140]. Việc này có thể được thực hiện tại quầy thông tin ở bất kỳ chi nhánh nào.","units":[{"en":"Please be advised that your Mena Chin Library card will expire one month from today.","vi":"Xin thông báo rằng thẻ thư viện Mena Chin Library của ông sẽ hết hạn sau một tháng kể từ hôm nay."},{"en":"[139] ------- must be renewed if you intend to keep your membership for the coming year. [140] -------.","vi":"[139] phải được gia hạn nếu ông dự định duy trì tư cách thành viên cho năm tới. [140]."},{"en":"This can be done at the information desk at any branch location.","vi":"Việc này có thể được thực hiện tại quầy thông tin ở bất kỳ chi nhánh nào."}]},{"speaker":"","en":"[141] ------- you decide to close your account, no action is necessary. Failure to complete your renewal by the [142] ------- date will result in the expiration of your library privileges.","vi":"[141] ông quyết định đóng tài khoản của mình, không cần thực hiện bất kỳ thao tác nào. Việc không hoàn tất gia hạn trước ngày [142] sẽ khiến các quyền lợi thư viện của ông hết hiệu lực.","units":[{"en":"[141] ------- you decide to close your account, no action is necessary.","vi":"[141] ông quyết định đóng tài khoản của mình, không cần thực hiện bất kỳ thao tác nào."},{"en":"Failure to complete your renewal by the [142] ------- date will result in the expiration of your library privileges.","vi":"Việc không hoàn tất gia hạn trước ngày [142] sẽ khiến các quyền lợi thư viện của ông hết hiệu lực."}]},{"speaker":"","en":"If you have any questions about this notice, or about general library services, you may reply directly to this e-mail.","vi":"Nếu ông có bất kỳ thắc mắc nào về thông báo này hoặc về các dịch vụ chung của thư viện, ông có thể trả lời trực tiếp vào email này.","units":[{"en":"If you have any questions about this notice, or about general library services, you may reply directly to this e-mail.","vi":"Nếu ông có bất kỳ thắc mắc nào về thông báo này hoặc về các dịch vụ chung của thư viện, ông có thể trả lời trực tiếp vào email này."}]},{"speaker":"","en":"Sincerely, Patron Services","vi":"Trân trọng, Bộ phận Dịch vụ Bạn đọc","units":[{"en":"Sincerely, Patron Services","vi":"Trân trọng, Bộ phận Dịch vụ Bạn đọc"}]}],"vocab":[{"word":"renewal","pos":"n","ipa":"/rɪˈnuːəl/","meaning":"việc gia hạn"},{"word":"branch","pos":"n","ipa":"/bræntʃ/","meaning":"chi nhánh"},{"word":"opt out","pos":"phr. v","ipa":"/ɑːpt aʊt/","meaning":"rút khỏi, từ chối tham gia"}],"isScanBacked":false,"docTypeLabel":"e-mail","context":"E-mail from Mena Chin Library Patron Services to Edgar Hughes regarding library card expiration","grammarType":"Điền câu hoàn chỉnh vào mạch đoạn văn (Sentence Insertion)","formula":"CÔNG THỨC PART 6 (6. PART 6 THUỘC LÒNG — Neo đại từ 'This' ở câu sau): Câu trước yêu cầu thẻ phải được gia hạn; câu sau dùng \"This can be done at the information desk at any branch location\" -> Chỗ trống phải là câu quy định thời hạn thực hiện \"Renewal\" để \"This\" thay thế trực tiếp.","optionAnalysis":{"A":"Mâu thuẫn bối cảnh email: ông Hughes đã là chủ thẻ sắp hết hạn cần gia hạn, không phải người mới đi đăng ký làm thẻ (\"sign up for a card\").","B":"Phá vỡ liên kết tiến: câu sau nói \"This can be done at the information desk\" nhằm hướng dẫn nơi làm thủ tục gia hạn, không phải nơi giải đáp thắc mắc trên trang web (mà việc hỏi đáp đã được nêu ở đoạn cuối qua email).","C":"Đáp án chính xác: bổ sung mốc thời hạn gia hạn (\"ít nhất một tuần trước khi thẻ hết hạn\"), nối mượt với \"This can be done\" ở câu sau và cụm \"by the specified date\" ở câu 142.","D":"Lạc mạch hành động: nói về việc rút khỏi một chương trình bất cứ lúc nào (\"opt out of this program\") khiến đại từ \"This\" ở câu tiếp theo tại quầy thông tin trở nên rời rạc và lệch chủ đề gia hạn thẻ."},"evDocIdx":0,"evTargets":[{"badge":"Câu 140 · Đáp án C","opt":"C","isCorrect":true,"quote":"must be renewed if you intend to keep your membership for the coming year.","viQuote":"phải được gia hạn nếu ông dự định duy trì tư cách thành viên cho năm tới."},{"badge":"Câu 140 · Đáp án C","opt":"C","isCorrect":true,"quote":"This can be done at the information desk at any branch location.","viQuote":"Việc này có thể được thực hiện tại quầy thông tin ở bất kỳ chi nhánh nào."}],"evQuotes":["must be renewed if you intend to keep your membership for the coming year.","This can be done at the information desk at any branch location."]},{"q":141,"part":6,"group_id":"E25_T01_G139_142","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc06.webp"],"stem_en":"Select the best answer for blank (141) in the passage.","stem_vi":"Chọn đáp án phù hợp nhất để điền vào chỗ trống (141) trong đoạn văn.","options":{"A":{"en":"Also","vi":"Ngoài ra, cũng (trạng từ)"},"B":{"en":"Should","vi":"Nếu (đảo ngữ câu điều kiện với Should)"},"C":{"en":"Because","vi":"Bởi vì (liên từ chỉ nguyên nhân)"},"D":{"en":"Although","vi":"Mặc dù (liên từ chỉ sự nhượng bộ)"}},"ans":"B","explanation":"Đáp án đúng: (B) Should (Nếu) — tạo cấu trúc đảo ngữ câu điều kiện loại 1 (\"Should you decide\" = \"If you should decide\"), diễn tả giả thiết nếu ông quyết định đóng tài khoản.\nDẫn chứng: \"[141] ------- you decide to close your account, no action is necessary.\" (Nếu ông quyết định đóng tài khoản của mình, ông không cần thực hiện bất kỳ thao tác nào).\nPhân tích bẫy:\n- (A) Sai chức năng liên kết: \"Also\" là trạng từ chuyển tiếp, không thể nối hai mệnh đề độc lập (\"you decide to close your account\" và \"no action is necessary\") chỉ bằng dấu phẩy mà thiếu liên từ.\n- (C) Sai logic giả định: \"Because\" khẳng định chắc chắn người nhận đã chọn đóng tài khoản, mâu thuẫn với ngữ cảnh thư đưa ra hai phương án lựa chọn (gia hạn hoặc đóng tài khoản).\n- (D) Sai nghĩa tương phản: \"Although\" (mặc dù) tạo quan hệ đối lập vô lý giữa việc đóng tài khoản và việc không cần thao tác gì.","lines":[{"speaker":"","en":"From: Patron Services <patronservices@menachinlibrary.org>","vi":"Từ: Bộ phận Dịch vụ Bạn đọc <patronservices@menachinlibrary.org>","units":[{"en":"From: Patron Services <patronservices@menachinlibrary.org>","vi":"Từ: Bộ phận Dịch vụ Bạn đọc <patronservices@menachinlibrary.org>"}]},{"speaker":"","en":"To: Edgar Hughes <hughese98@villachesta.com>","vi":"Đến: Edgar Hughes <hughese98@villachesta.com>","units":[{"en":"To: Edgar Hughes <hughese98@villachesta.com>","vi":"Đến: Edgar Hughes <hughese98@villachesta.com>"}]},{"speaker":"","en":"Subject: Card expiration date approaching","vi":"Chủ đề: Ngày hết hạn thẻ đang đến gần","units":[{"en":"Subject: Card expiration date approaching","vi":"Chủ đề: Ngày hết hạn thẻ đang đến gần"}]},{"speaker":"","en":"Date: December 3","vi":"Ngày: 3 tháng 12","units":[{"en":"Date: December 3","vi":"Ngày: 3 tháng 12"}]},{"speaker":"","en":"Dear Mr. Hughes,","vi":"Kính gửi ông Hughes,","units":[{"en":"Dear Mr. Hughes,","vi":"Kính gửi ông Hughes,"}]},{"speaker":"","en":"Please be advised that your Mena Chin Library card will expire one month from today. [139] ------- must be renewed if you intend to keep your membership for the coming year. [140] -------. This can be done at the information desk at any branch location.","vi":"Xin thông báo rằng thẻ thư viện Mena Chin Library của ông sẽ hết hạn sau một tháng kể từ hôm nay. [139] phải được gia hạn nếu ông dự định duy trì tư cách thành viên cho năm tới. [140]. Việc này có thể được thực hiện tại quầy thông tin ở bất kỳ chi nhánh nào.","units":[{"en":"Please be advised that your Mena Chin Library card will expire one month from today.","vi":"Xin thông báo rằng thẻ thư viện Mena Chin Library của ông sẽ hết hạn sau một tháng kể từ hôm nay."},{"en":"[139] ------- must be renewed if you intend to keep your membership for the coming year. [140] -------.","vi":"[139] phải được gia hạn nếu ông dự định duy trì tư cách thành viên cho năm tới. [140]."},{"en":"This can be done at the information desk at any branch location.","vi":"Việc này có thể được thực hiện tại quầy thông tin ở bất kỳ chi nhánh nào."}]},{"speaker":"","en":"[141] ------- you decide to close your account, no action is necessary. Failure to complete your renewal by the [142] ------- date will result in the expiration of your library privileges.","vi":"[141] ông quyết định đóng tài khoản của mình, không cần thực hiện bất kỳ thao tác nào. Việc không hoàn tất gia hạn trước ngày [142] sẽ khiến các quyền lợi thư viện của ông hết hiệu lực.","units":[{"en":"[141] ------- you decide to close your account, no action is necessary.","vi":"[141] ông quyết định đóng tài khoản của mình, không cần thực hiện bất kỳ thao tác nào."},{"en":"Failure to complete your renewal by the [142] ------- date will result in the expiration of your library privileges.","vi":"Việc không hoàn tất gia hạn trước ngày [142] sẽ khiến các quyền lợi thư viện của ông hết hiệu lực."}]},{"speaker":"","en":"If you have any questions about this notice, or about general library services, you may reply directly to this e-mail.","vi":"Nếu ông có bất kỳ thắc mắc nào về thông báo này hoặc về các dịch vụ chung của thư viện, ông có thể trả lời trực tiếp vào email này.","units":[{"en":"If you have any questions about this notice, or about general library services, you may reply directly to this e-mail.","vi":"Nếu ông có bất kỳ thắc mắc nào về thông báo này hoặc về các dịch vụ chung của thư viện, ông có thể trả lời trực tiếp vào email này."}]},{"speaker":"","en":"Sincerely, Patron Services","vi":"Trân trọng, Bộ phận Dịch vụ Bạn đọc","units":[{"en":"Sincerely, Patron Services","vi":"Trân trọng, Bộ phận Dịch vụ Bạn đọc"}]}],"vocab":[{"word":"close an account","pos":"phr","ipa":"/kloʊz ən əˈkaʊnt/","meaning":"đóng tài khoản"},{"word":"be advised","pos":"phr","ipa":"/biː ədˈvaɪzd/","meaning":"xin lưu ý, được thông báo"},{"word":"reply","pos":"v","ipa":"/rɪˈplaɪ/","meaning":"trả lời, hồi âm"}],"isScanBacked":false,"docTypeLabel":"e-mail","context":"E-mail from Mena Chin Library Patron Services to Edgar Hughes regarding library card expiration","grammarType":"Liên từ / Trạng từ liên kết (Conjunction / Conjunctive Adverb)","formula":"CÔNG THỨC PART 6 (Đảo ngữ câu điều kiện loại 1 với Should): Cấu trúc \"[141] ___ + S (you) + V nguyên mẫu (decide), mệnh đề chính (no action is necessary)\" -> Áp dụng đảo ngữ điều kiện \"Should + S + V-inf\" thay cho \"If\".","optionAnalysis":{"A":"Sai ngữ pháp nối mệnh đề: \"Also\" là trạng từ bổ sung ý (cần dấu phẩy sau nó hoặc đứng riêng), không có chức năng liên từ phụ thuộc để nối hai mệnh đề trước và sau dấu phẩy.","B":"Đáp án chính xác: \"Should\" đứng đầu câu tạo phép đảo ngữ câu điều kiện loại 1 (\"Should you decide\" = \"If you decide\"), phù hợp với giả thiết mở cho người nhận.","C":"Sai ngữ nghĩa tình huống: \"Because\" (bởi vì) khẳng định sự việc đã quyết định xảy ra, trái với văn phong thông báo đưa ra hai khả năng lựa chọn cho bạn đọc.","D":"Sai quan hệ logic: \"Although\" (mặc dù) diễn tả sự nhượng bộ trái ngược, không hợp nghĩa vì việc không cần làm gì là hệ quả tự nhiên nếu quyết định đóng tài khoản."},"evDocIdx":0,"evTargets":[{"badge":"Câu 141 · Đáp án B","opt":"B","isCorrect":true,"quote":"you decide to close your account, no action is necessary.","viQuote":"ông quyết định đóng tài khoản của mình, không cần thực hiện bất kỳ thao tác nào."}],"evQuotes":["you decide to close your account, no action is necessary."]},{"q":142,"part":6,"group_id":"E25_T01_G139_142","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc06.webp"],"stem_en":"Select the best answer for blank (142) in the passage.","stem_vi":"Chọn đáp án phù hợp nhất để điền vào chỗ trống (142) trong đoạn văn.","options":{"A":{"en":"specifically","vi":"một cách cụ thể (adv)"},"B":{"en":"specifics","vi":"các chi tiết cụ thể (n, số nhiều)"},"C":{"en":"specified","vi":"được quy định, đã chỉ định (adj / quá khứ phân từ)"},"D":{"en":"specificity","vi":"tính cụ thể, độ đặc hiệu (n)"}},"ans":"C","explanation":"Đáp án đúng: (C) specified (được quy định, đã chỉ định) — quá khứ phân từ đóng vai trò tính từ bổ nghĩa cho danh từ \"date\", ám chỉ hạn chót đã nêu ở câu 140.\nDẫn chứng: \"Failure to complete your renewal by the [142] ------- date will result in the expiration of your library privileges.\" (Việc không hoàn tất gia hạn trước ngày đã quy định sẽ dẫn đến việc hết hiệu lực quyền lợi thư viện).\nPhân tích bẫy:\n- (A) Sai từ loại: \"specifically\" là trạng từ (\"một cách cụ thể\"), không thể đứng giữa mạo từ \"the\" và danh từ \"date\" để bổ nghĩa cho danh từ.\n- (B) Sai từ loại: \"specifics\" là danh từ số nhiều (\"những chi tiết cụ thể\"), không phù hợp làm tính từ bổ nghĩa cho danh từ \"date\".\n- (D) Sai từ loại: \"specificity\" là danh từ trừu tượng (\"tính cụ thể\"), không tạo được cụm danh từ hợp nghĩa với \"date\" trong văn cảnh hạn chót.","lines":[{"speaker":"","en":"From: Patron Services <patronservices@menachinlibrary.org>","vi":"Từ: Bộ phận Dịch vụ Bạn đọc <patronservices@menachinlibrary.org>","units":[{"en":"From: Patron Services <patronservices@menachinlibrary.org>","vi":"Từ: Bộ phận Dịch vụ Bạn đọc <patronservices@menachinlibrary.org>"}]},{"speaker":"","en":"To: Edgar Hughes <hughese98@villachesta.com>","vi":"Đến: Edgar Hughes <hughese98@villachesta.com>","units":[{"en":"To: Edgar Hughes <hughese98@villachesta.com>","vi":"Đến: Edgar Hughes <hughese98@villachesta.com>"}]},{"speaker":"","en":"Subject: Card expiration date approaching","vi":"Chủ đề: Ngày hết hạn thẻ đang đến gần","units":[{"en":"Subject: Card expiration date approaching","vi":"Chủ đề: Ngày hết hạn thẻ đang đến gần"}]},{"speaker":"","en":"Date: December 3","vi":"Ngày: 3 tháng 12","units":[{"en":"Date: December 3","vi":"Ngày: 3 tháng 12"}]},{"speaker":"","en":"Dear Mr. Hughes,","vi":"Kính gửi ông Hughes,","units":[{"en":"Dear Mr. Hughes,","vi":"Kính gửi ông Hughes,"}]},{"speaker":"","en":"Please be advised that your Mena Chin Library card will expire one month from today. [139] ------- must be renewed if you intend to keep your membership for the coming year. [140] -------. This can be done at the information desk at any branch location.","vi":"Xin thông báo rằng thẻ thư viện Mena Chin Library của ông sẽ hết hạn sau một tháng kể từ hôm nay. [139] phải được gia hạn nếu ông dự định duy trì tư cách thành viên cho năm tới. [140]. Việc này có thể được thực hiện tại quầy thông tin ở bất kỳ chi nhánh nào.","units":[{"en":"Please be advised that your Mena Chin Library card will expire one month from today.","vi":"Xin thông báo rằng thẻ thư viện Mena Chin Library của ông sẽ hết hạn sau một tháng kể từ hôm nay."},{"en":"[139] ------- must be renewed if you intend to keep your membership for the coming year. [140] -------.","vi":"[139] phải được gia hạn nếu ông dự định duy trì tư cách thành viên cho năm tới. [140]."},{"en":"This can be done at the information desk at any branch location.","vi":"Việc này có thể được thực hiện tại quầy thông tin ở bất kỳ chi nhánh nào."}]},{"speaker":"","en":"[141] ------- you decide to close your account, no action is necessary. Failure to complete your renewal by the [142] ------- date will result in the expiration of your library privileges.","vi":"[141] ông quyết định đóng tài khoản của mình, không cần thực hiện bất kỳ thao tác nào. Việc không hoàn tất gia hạn trước ngày [142] sẽ khiến các quyền lợi thư viện của ông hết hiệu lực.","units":[{"en":"[141] ------- you decide to close your account, no action is necessary.","vi":"[141] ông quyết định đóng tài khoản của mình, không cần thực hiện bất kỳ thao tác nào."},{"en":"Failure to complete your renewal by the [142] ------- date will result in the expiration of your library privileges.","vi":"Việc không hoàn tất gia hạn trước ngày [142] sẽ khiến các quyền lợi thư viện của ông hết hiệu lực."}]},{"speaker":"","en":"If you have any questions about this notice, or about general library services, you may reply directly to this e-mail.","vi":"Nếu ông có bất kỳ thắc mắc nào về thông báo này hoặc về các dịch vụ chung của thư viện, ông có thể trả lời trực tiếp vào email này.","units":[{"en":"If you have any questions about this notice, or about general library services, you may reply directly to this e-mail.","vi":"Nếu ông có bất kỳ thắc mắc nào về thông báo này hoặc về các dịch vụ chung của thư viện, ông có thể trả lời trực tiếp vào email này."}]},{"speaker":"","en":"Sincerely, Patron Services","vi":"Trân trọng, Bộ phận Dịch vụ Bạn đọc","units":[{"en":"Sincerely, Patron Services","vi":"Trân trọng, Bộ phận Dịch vụ Bạn đọc"}]}],"vocab":[{"word":"specified","pos":"adj","ipa":"/ˈspesɪfaɪd/","meaning":"được quy định, được chỉ định rõ"},{"word":"expiration","pos":"n","ipa":"/ˌekspəˈreɪʃən/","meaning":"sự hết hạn, sự hết hiệu lực"},{"word":"privilege","pos":"n","ipa":"/ˈprɪvəlɪdʒ/","meaning":"quyền lợi, đặc quyền"},{"word":"result in","pos":"phr. v","ipa":"/rɪˈzʌlt ɪn/","meaning":"dẫn đến, gây ra"}],"isScanBacked":false,"docTypeLabel":"e-mail","context":"E-mail from Mena Chin Library Patron Services to Edgar Hughes regarding library card expiration","grammarType":"Từ loại (Word Form: Danh từ / Động từ / Tính từ / Trạng từ)","formula":"CÔNG THỨC PART 6 (Tờ A3 Màu — Mạo từ + Tính từ/Phân từ + Danh từ): Sau mạo từ xác định \"the\" và trước danh từ \"date\" cần Tính từ hoặc Quá khứ phân từ V3/ed mang nghĩa bị động (\"ngày đã được quy định\") -> Chọn \"specified\".","optionAnalysis":{"A":"Sai từ loại: \"specifically\" là trạng từ (\"một cách cụ thể\"), không đứng trước để bổ nghĩa trực tiếp cho danh từ \"date\" trong cụm \"the ___ date\".","B":"Sai từ loại: \"specifics\" là danh từ số nhiều (\"các điểm chi tiết\"), không dùng để bổ nghĩa trước danh từ \"date\" thay cho tính từ.","C":"Đáp án chính xác: phân từ quá khứ \"specified\" dùng như tính từ (\"đã được quy định/chỉ định\"), đứng sau \"the\" để bổ nghĩa chuẩn cho danh từ \"date\".","D":"Sai từ loại: \"specificity\" là danh từ chỉ tính chất (\"độ cụ thể\"), không kết hợp hợp nghĩa vào vị trí tính từ đứng trước \"date\"."},"evDocIdx":0,"evTargets":[{"badge":"Câu 142 · Đáp án C","opt":"C","isCorrect":true,"quote":"Failure to complete your renewal by the","viQuote":"Việc không hoàn tất gia hạn trước ngày"},{"badge":"Câu 142 · Đáp án C","opt":"C","isCorrect":true,"quote":"date will result in the expiration of your library privileges.","viQuote":"sẽ khiến các quyền lợi thư viện của ông hết hiệu lực."}],"evQuotes":["Failure to complete your renewal by the","date will result in the expiration of your library privileges."]},{"q":143,"part":6,"group_id":"E25_T01_G143_146","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc07.webp"],"stem_en":"Select the best answer for blank (143) in the passage.","stem_vi":"143. Chọn câu phù hợp nhất điền vào chỗ trống [143].","options":{"A":{"en":"I would like to introduce you to our business.","vi":"Tôi xin trân trọng giới thiệu với bà về doanh nghiệp của chúng tôi."},"B":{"en":"Great photographs can make your property stand out.","vi":"Những bức ảnh đẹp có thể giúp bất động sản của bà trở nên nổi bật."},"C":{"en":"We are looking forward to your visit.","vi":"Chúng tôi rất mong chờ chuyến ghé thăm của bà."},"D":{"en":"It was the first studio of its kind to open in this area.","vi":"Đó là studio đầu tiên thuộc loại hình này mở cửa tại khu vực này."}},"ans":"A","explanation":"Đáp án đúng: (A) Tôi xin trân trọng giới thiệu với bà về doanh nghiệp của chúng tôi — đóng vai trò câu chuyển tiếp tự nhiên từ lời tự giới thiệu cá nhân sang phần mô tả chi tiết các dịch vụ của studio ở câu liền sau.\nDẫn chứng: \"I am Omar Ridha, the manager of Droplight Studio. [143] -------. We offer a full range of photography services for real estate professionals like you.\" (Cụm \"our business\" liên kết lùi với \"Droplight Studio\" và liên kết tiến với \"We offer a full range of photography services\").\nPhân tích bẫy:\n- (B) Thiếu bước chuyển tiếp: nhảy ngay sang nhận xét về ảnh đẹp làm nổi bật bất động sản khiến câu đầu (\"I am Omar Ridha, the manager of Droplight Studio\") chưa có câu nêu mục đích viết thư trước khi sang \"We offer a full range of photography services\".\n- (C) Sai ngữ cảnh bức thư: đây là thư tiếp thị chào hàng dịch vụ chụp ảnh bất động sản và cuối thư hướng dẫn xem trang web (\"visit our Web site\"), không phải thư hẹn khách đến tham quan.\n- (D) Lạc mạch mở đầu: đề cập lịch sử là studio đầu tiên mở tại khu vực quá đột ngột ngay sau câu xưng tên, không bắc cầu hợp lý bằng câu giới thiệu doanh nghiệp.","lines":[{"speaker":"","en":"April 7","vi":"Ngày 7 tháng 4","units":[{"en":"April 7","vi":"Ngày 7 tháng 4"}]},{"speaker":"","en":"Naomi Burwell, 43 Waymire Road, South Portland, ME 04109","vi":"Người nhận: Naomi Burwell, 43 Waymire Road, South Portland, ME 04109","units":[{"en":"Naomi Burwell, 43 Waymire Road, South Portland, ME 04109","vi":"Người nhận: Naomi Burwell, 43 Waymire Road, South Portland, ME 04109"}]},{"speaker":"","en":"Dear Ms. Burwell,","vi":"Kính gửi bà Burwell,","units":[{"en":"Dear Ms. Burwell,","vi":"Kính gửi bà Burwell,"}]},{"speaker":"","en":"I am Omar Ridha, the manager of Droplight Studio. [143] -------. We offer a full range of photography services for real estate professionals like you. We take pride in composing interior and exterior shots that make a property look its best. Droplight Studio spares no effort in [144] ------- superior digital images. [145] -------, our professional-grade equipment, lighting, and staging techniques allow us to highlight the best features of a property. And once the photo shoot is over, every image [146] ------- expert editing. All these services come standard in every package.","vi":"Tôi là Omar Ridha, quản lý của Droplight Studio. [143]. Chúng tôi cung cấp đầy đủ các dịch vụ nhiếp ảnh dành cho những chuyên gia bất động sản như bà. Chúng tôi tự hào trong việc bố cục những bức ảnh nội thất và ngoại thất giúp mỗi bất động sản trông đẹp nhất. Droplight Studio luôn nỗ lực hết mình trong việc [144] những hình ảnh kỹ thuật số chất lượng vượt trội. [145], trang thiết bị chuẩn chuyên nghiệp cùng kỹ thuật ánh sáng và bài trí không gian của chúng tôi cho phép làm nổi bật những ưu điểm tốt nhất của bất động sản. Và ngay khi buổi chụp ảnh kết thúc, mỗi bức ảnh đều [146] sự chỉnh sửa chuyên nghiệp. Tất cả những dịch vụ này đều là hạng mục tiêu chuẩn đi kèm trong mọi gói dịch vụ.","units":[{"en":"I am Omar Ridha, the manager of Droplight Studio. [143] -------.","vi":"Tôi là Omar Ridha, quản lý của Droplight Studio. [143]."},{"en":"We offer a full range of photography services for real estate professionals like you.","vi":"Chúng tôi cung cấp đầy đủ các dịch vụ nhiếp ảnh dành cho những chuyên gia bất động sản như bà."},{"en":"We take pride in composing interior and exterior shots that make a property look its best.","vi":"Chúng tôi tự hào trong việc bố cục những bức ảnh nội thất và ngoại thất giúp mỗi bất động sản trông đẹp nhất."},{"en":"Droplight Studio spares no effort in [144] ------- superior digital images.","vi":"Droplight Studio luôn nỗ lực hết mình trong việc [144] những hình ảnh kỹ thuật số chất lượng vượt trội."},{"en":"[145] -------, our professional-grade equipment, lighting, and staging techniques allow us to highlight the best features of a property.","vi":"[145], trang thiết bị chuẩn chuyên nghiệp cùng kỹ thuật ánh sáng và bài trí không gian của chúng tôi cho phép làm nổi bật những ưu điểm tốt nhất của bất động sản."},{"en":"And once the photo shoot is over, every image [146] ------- expert editing.","vi":"Và ngay khi buổi chụp ảnh kết thúc, mỗi bức ảnh đều [146] sự chỉnh sửa chuyên nghiệp."},{"en":"All these services come standard in every package.","vi":"Tất cả những dịch vụ này đều là hạng mục tiêu chuẩn đi kèm trong mọi gói dịch vụ."}]},{"speaker":"","en":"Please visit our Web site to view our work as well as our pricing and scheduling information. We are happy to work with you to customize orders.","vi":"Vui lòng truy cập trang web của chúng tôi để xem các sản phẩm đã thực hiện cũng như bảng giá và thông tin đặt lịch. Chúng tôi rất sẵn lòng phối hợp với bà để thiết kế các đơn hàng theo yêu cầu riêng.","units":[{"en":"Please visit our Web site to view our work as well as our pricing and scheduling information.","vi":"Vui lòng truy cập trang web của chúng tôi để xem các sản phẩm đã thực hiện cũng như bảng giá và thông tin đặt lịch."},{"en":"We are happy to work with you to customize orders.","vi":"Chúng tôi rất sẵn lòng phối hợp với bà để thiết kế các đơn hàng theo yêu cầu riêng."}]},{"speaker":"","en":"Sincerely,","vi":"Trân trọng,","units":[{"en":"Sincerely,","vi":"Trân trọng,"}]},{"speaker":"","en":"Omar Ridha, Droplight Studio","vi":"Omar Ridha, Droplight Studio","units":[{"en":"Omar Ridha, Droplight Studio","vi":"Omar Ridha, Droplight Studio"}]}],"vocab":[{"word":"real estate","pos":"n","ipa":"/ˈriːəl ɪˈsteɪt/","meaning":"bất động sản"},{"word":"property","pos":"n","ipa":"/ˈprɑːpərti/","meaning":"tài sản, bất động sản"},{"word":"stand out","pos":"phr. v","ipa":"/stænd aʊt/","meaning":"nổi bật, thu hút sự chú ý"}],"isScanBacked":false,"docTypeLabel":"letter","context":"Promotional letter from Omar Ridha at Droplight Studio to Naomi Burwell offering real estate photography","grammarType":"Điền câu hoàn chỉnh vào mạch đoạn văn (Sentence Insertion)","formula":"CÔNG THỨC PART 6 (6. PART 6 THUỘC LÒNG — Câu mở đầu thư chào hàng): Đọc câu trước [143] (tự giới thiệu tên và chức danh người gửi) và câu sau [143] (\"We offer a full range of photography services for real estate professionals like you\") -> Cần câu dẫn nhập mục đích viết thư giới thiệu doanh nghiệp.","optionAnalysis":{"A":"Đáp án chính xác: nêu mục đích bức thư là giới thiệu \"our business\" (Droplight Studio), tạo cầu nối mượt mà giữa lời xưng danh ở câu 1 và phần giới thiệu gói dịch vụ \"We offer\" ở câu 3.","B":"Lệch nhịp chuyển ý: chưa nêu mục đích liên hệ giới thiệu công ty mà đã nhận xét về tác dụng của ảnh đẹp đối với bất động sản, làm mạch giới thiệu ở hai câu liền kề bị khựng.","C":"Sai bối cảnh thư tiếp thị: người viết đang gửi thư giới thiệu dịch vụ chụp ảnh tới chuyên gia bất động sản và mời xem website, không phải xác nhận lịch hẹn khách đến thăm studio.","D":"Kém liên kết mở đoạn: nói về việc từng là studio đầu tiên mở trong khu vực không giải thích lý do gửi thư bằng việc giới thiệu tổng quan doanh nghiệp trước khi liệt kê dịch vụ."},"evDocIdx":0,"evTargets":[{"badge":"Câu 143 · Đáp án A","opt":"A","isCorrect":true,"quote":"I am Omar Ridha, the manager of Droplight Studio.","viQuote":"Tôi là Omar Ridha, quản lý của Droplight Studio."},{"badge":"Câu 143 · Đáp án A","opt":"A","isCorrect":true,"quote":"We offer a full range of photography services for real estate professionals like you.","viQuote":"Chúng tôi cung cấp đầy đủ các dịch vụ nhiếp ảnh dành cho những chuyên gia bất động sản như bà."}],"evQuotes":["I am Omar Ridha, the manager of Droplight Studio.","We offer a full range of photography services for real estate professionals like you."]},{"q":144,"part":6,"group_id":"E25_T01_G143_146","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc07.webp"],"stem_en":"Select the best answer for blank (144) in the passage.","stem_vi":"Chọn đáp án phù hợp nhất để điền vào chỗ trống (144) trong đoạn văn.","options":{"A":{"en":"researching","vi":"nghiên cứu"},"B":{"en":"creating","vi":"tạo ra"},"C":{"en":"purchasing","vi":"mua"},"D":{"en":"displaying","vi":"trưng bày / hiển thị"}},"ans":"B","explanation":"Đáp án đúng: (B) creating (tạo ra) — phù hợp với hoạt động chuyên môn của studio nhiếp ảnh bất động sản là chụp và hậu kỳ để tạo ra những bức ảnh kỹ thuật số chất lượng cao.\nDẫn chứng: \"Droplight Studio spares no effort in [144] ------- superior digital images. [145] -------, our professional-grade equipment, lighting, and staging techniques allow us to highlight the best features of a property.\" (Droplight Studio nỗ lực hết mình trong việc tạo ra các hình ảnh kỹ thuật số chất lượng vượt trội nhờ thiết bị, ánh sáng và bài trí).\nPhân tích bẫy:\n- (A) Sai nghĩa chuyên môn: \"researching\" (nghiên cứu) không phải công việc cung cấp sản phẩm ảnh chụp bất động sản cho khách hàng.\n- (C) Sai vai trò cung ứng: \"purchasing\" (mua) trái với vai trò của studio tự chụp (\"photo shoot\") và chỉnh sửa ảnh (\"expert editing\") để bán dịch vụ.\n- (D) Sai ngữ cảnh giải thích: câu sau giải thích bằng thiết bị, ánh sáng và kỹ thuật bài trí để tạo ảnh nổi bật, không phải để \"trưng bày\" (\"displaying\") ảnh.","lines":[{"speaker":"","en":"April 7","vi":"Ngày 7 tháng 4","units":[{"en":"April 7","vi":"Ngày 7 tháng 4"}]},{"speaker":"","en":"Naomi Burwell, 43 Waymire Road, South Portland, ME 04109","vi":"Người nhận: Naomi Burwell, 43 Waymire Road, South Portland, ME 04109","units":[{"en":"Naomi Burwell, 43 Waymire Road, South Portland, ME 04109","vi":"Người nhận: Naomi Burwell, 43 Waymire Road, South Portland, ME 04109"}]},{"speaker":"","en":"Dear Ms. Burwell,","vi":"Kính gửi bà Burwell,","units":[{"en":"Dear Ms. Burwell,","vi":"Kính gửi bà Burwell,"}]},{"speaker":"","en":"I am Omar Ridha, the manager of Droplight Studio. [143] -------. We offer a full range of photography services for real estate professionals like you. We take pride in composing interior and exterior shots that make a property look its best. Droplight Studio spares no effort in [144] ------- superior digital images. [145] -------, our professional-grade equipment, lighting, and staging techniques allow us to highlight the best features of a property. And once the photo shoot is over, every image [146] ------- expert editing. All these services come standard in every package.","vi":"Tôi là Omar Ridha, quản lý của Droplight Studio. [143]. Chúng tôi cung cấp đầy đủ các dịch vụ nhiếp ảnh dành cho những chuyên gia bất động sản như bà. Chúng tôi tự hào trong việc bố cục những bức ảnh nội thất và ngoại thất giúp mỗi bất động sản trông đẹp nhất. Droplight Studio luôn nỗ lực hết mình trong việc [144] những hình ảnh kỹ thuật số chất lượng vượt trội. [145], trang thiết bị chuẩn chuyên nghiệp cùng kỹ thuật ánh sáng và bài trí không gian của chúng tôi cho phép làm nổi bật những ưu điểm tốt nhất của bất động sản. Và ngay khi buổi chụp ảnh kết thúc, mỗi bức ảnh đều [146] sự chỉnh sửa chuyên nghiệp. Tất cả những dịch vụ này đều là hạng mục tiêu chuẩn đi kèm trong mọi gói dịch vụ.","units":[{"en":"I am Omar Ridha, the manager of Droplight Studio. [143] -------.","vi":"Tôi là Omar Ridha, quản lý của Droplight Studio. [143]."},{"en":"We offer a full range of photography services for real estate professionals like you.","vi":"Chúng tôi cung cấp đầy đủ các dịch vụ nhiếp ảnh dành cho những chuyên gia bất động sản như bà."},{"en":"We take pride in composing interior and exterior shots that make a property look its best.","vi":"Chúng tôi tự hào trong việc bố cục những bức ảnh nội thất và ngoại thất giúp mỗi bất động sản trông đẹp nhất."},{"en":"Droplight Studio spares no effort in [144] ------- superior digital images.","vi":"Droplight Studio luôn nỗ lực hết mình trong việc [144] những hình ảnh kỹ thuật số chất lượng vượt trội."},{"en":"[145] -------, our professional-grade equipment, lighting, and staging techniques allow us to highlight the best features of a property.","vi":"[145], trang thiết bị chuẩn chuyên nghiệp cùng kỹ thuật ánh sáng và bài trí không gian của chúng tôi cho phép làm nổi bật những ưu điểm tốt nhất của bất động sản."},{"en":"And once the photo shoot is over, every image [146] ------- expert editing.","vi":"Và ngay khi buổi chụp ảnh kết thúc, mỗi bức ảnh đều [146] sự chỉnh sửa chuyên nghiệp."},{"en":"All these services come standard in every package.","vi":"Tất cả những dịch vụ này đều là hạng mục tiêu chuẩn đi kèm trong mọi gói dịch vụ."}]},{"speaker":"","en":"Please visit our Web site to view our work as well as our pricing and scheduling information. We are happy to work with you to customize orders.","vi":"Vui lòng truy cập trang web của chúng tôi để xem các sản phẩm đã thực hiện cũng như bảng giá và thông tin đặt lịch. Chúng tôi rất sẵn lòng phối hợp với bà để thiết kế các đơn hàng theo yêu cầu riêng.","units":[{"en":"Please visit our Web site to view our work as well as our pricing and scheduling information.","vi":"Vui lòng truy cập trang web của chúng tôi để xem các sản phẩm đã thực hiện cũng như bảng giá và thông tin đặt lịch."},{"en":"We are happy to work with you to customize orders.","vi":"Chúng tôi rất sẵn lòng phối hợp với bà để thiết kế các đơn hàng theo yêu cầu riêng."}]},{"speaker":"","en":"Sincerely,","vi":"Trân trọng,","units":[{"en":"Sincerely,","vi":"Trân trọng,"}]},{"speaker":"","en":"Omar Ridha, Droplight Studio","vi":"Omar Ridha, Droplight Studio","units":[{"en":"Omar Ridha, Droplight Studio","vi":"Omar Ridha, Droplight Studio"}]}],"vocab":[{"word":"spare no effort","pos":"phr","ipa":"/sper noʊ ˈefərt/","meaning":"nỗ lực hết mình, không tiếc công sức"},{"word":"superior","pos":"adj","ipa":"/suːˈpɪriər/","meaning":"vượt trội, chất lượng cao hơn hẳn"},{"word":"compose","pos":"v","ipa":"/kəmˈpoʊz/","meaning":"bố cục, sắp xếp khung hình"},{"word":"interior","pos":"adj","ipa":"/ɪnˈtɪriər/","meaning":"thuộc nội thất, bên trong"}],"isScanBacked":false,"docTypeLabel":"letter","context":"Promotional letter from Omar Ridha at Droplight Studio to Naomi Burwell offering real estate photography","grammarType":"Từ vựng & Ngữ cảnh TOEIC (Vocabulary in Context)","formula":"CÔNG THỨC PART 6 (Từ vựng trong ngữ cảnh nghề nghiệp): Cấu trúc \"spares no effort in + V-ing + superior digital images\" trong thư chào dịch vụ chụp và chỉnh sửa ảnh -> Chọn động từ \"creating\" (tạo ra hình ảnh chất lượng vượt trội).","optionAnalysis":{"A":"Sai ngữ nghĩa ngữ cảnh: \"researching\" (nghiên cứu) không khớp với quy trình chụp ảnh và xử lý hậu kỳ của một studio nhiếp ảnh bất động sản.","B":"Đáp án chính xác: \"creating\" (tạo ra) diễn tả đúng công việc sản xuất \"superior digital images\" của studio, được minh chứng tiếp bằng thiết bị, ánh sáng và kỹ thuật chỉnh sửa ở các câu sau.","C":"Sai logic dịch vụ: \"purchasing\" (mua) không hợp lý vì Droplight Studio là đơn vị trực tiếp thực hiện buổi chụp ảnh và chỉnh sửa ảnh chứ không đi mua ảnh.","D":"Sai trọng tâm hành động: \"displaying\" (trưng bày/hiển thị) không ăn khớp với các phương tiện tạo ảnh được liệt kê ở câu sau như thiết bị chuyên nghiệp, ánh sáng và bài trí không gian."},"evDocIdx":0,"evTargets":[{"badge":"Câu 144 · Đáp án B","opt":"B","isCorrect":true,"quote":"Droplight Studio spares no effort in","viQuote":"Droplight Studio luôn nỗ lực hết mình trong việc"},{"badge":"Câu 144 · Đáp án B","opt":"B","isCorrect":true,"quote":"superior digital images.","viQuote":"những hình ảnh kỹ thuật số chất lượng vượt trội."}],"evQuotes":["Droplight Studio spares no effort in","superior digital images."]},{"q":145,"part":6,"group_id":"E25_T01_G143_146","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc07.webp"],"stem_en":"Select the best answer for blank (145) in the passage.","stem_vi":"Chọn đáp án phù hợp nhất để điền vào chỗ trống (145) trong đoạn văn.","options":{"A":{"en":"If not","vi":"Nếu không"},"B":{"en":"By comparison","vi":"Khi so sánh"},"C":{"en":"Otherwise","vi":"Nếu không thì"},"D":{"en":"Indeed","vi":"Thật vậy"}},"ans":"D","explanation":"Đáp án đúng: (D) Indeed (Thật vậy) — trạng từ liên kết dùng để xác nhận và cụ thể hóa thêm cho nhận định về nỗ lực tạo ảnh chất lượng cao ở câu liền trước.\nDẫn chứng: \"Droplight Studio spares no effort in [144] ------- superior digital images. [145] -------, our professional-grade equipment, lighting, and staging techniques allow us to highlight the best features of a property.\" (Studio nỗ lực tạo ảnh chất lượng vượt trội. Thật vậy, thiết bị chuyên nghiệp, ánh sáng và kỹ thuật bài trí của chúng tôi giúp làm nổi bật ưu điểm bất động sản).\nPhân tích bẫy:\n- (A) Sai logic điều kiện: \"If not\" (nếu không) đặt điều kiện phủ định cho câu trước, mâu thuẫn với nội dung chứng minh tích cực ở câu sau.\n- (B) Sai quan hệ so sánh: \"By comparison\" (khi so sánh) đòi hỏi phải có sự đối chiếu hai đối tượng, trong khi đoạn văn chỉ đang mô tả năng lực của Droplight Studio.\n- (C) Sai nghĩa hệ quả trái ngược: \"Otherwise\" (nếu không thì) chỉ kết quả khác đi nếu vế trước không xảy ra, không phù hợp để củng cố ý đã nêu.","lines":[{"speaker":"","en":"April 7","vi":"Ngày 7 tháng 4","units":[{"en":"April 7","vi":"Ngày 7 tháng 4"}]},{"speaker":"","en":"Naomi Burwell, 43 Waymire Road, South Portland, ME 04109","vi":"Người nhận: Naomi Burwell, 43 Waymire Road, South Portland, ME 04109","units":[{"en":"Naomi Burwell, 43 Waymire Road, South Portland, ME 04109","vi":"Người nhận: Naomi Burwell, 43 Waymire Road, South Portland, ME 04109"}]},{"speaker":"","en":"Dear Ms. Burwell,","vi":"Kính gửi bà Burwell,","units":[{"en":"Dear Ms. Burwell,","vi":"Kính gửi bà Burwell,"}]},{"speaker":"","en":"I am Omar Ridha, the manager of Droplight Studio. [143] -------. We offer a full range of photography services for real estate professionals like you. We take pride in composing interior and exterior shots that make a property look its best. Droplight Studio spares no effort in [144] ------- superior digital images. [145] -------, our professional-grade equipment, lighting, and staging techniques allow us to highlight the best features of a property. And once the photo shoot is over, every image [146] ------- expert editing. All these services come standard in every package.","vi":"Tôi là Omar Ridha, quản lý của Droplight Studio. [143]. Chúng tôi cung cấp đầy đủ các dịch vụ nhiếp ảnh dành cho những chuyên gia bất động sản như bà. Chúng tôi tự hào trong việc bố cục những bức ảnh nội thất và ngoại thất giúp mỗi bất động sản trông đẹp nhất. Droplight Studio luôn nỗ lực hết mình trong việc [144] những hình ảnh kỹ thuật số chất lượng vượt trội. [145], trang thiết bị chuẩn chuyên nghiệp cùng kỹ thuật ánh sáng và bài trí không gian của chúng tôi cho phép làm nổi bật những ưu điểm tốt nhất của bất động sản. Và ngay khi buổi chụp ảnh kết thúc, mỗi bức ảnh đều [146] sự chỉnh sửa chuyên nghiệp. Tất cả những dịch vụ này đều là hạng mục tiêu chuẩn đi kèm trong mọi gói dịch vụ.","units":[{"en":"I am Omar Ridha, the manager of Droplight Studio. [143] -------.","vi":"Tôi là Omar Ridha, quản lý của Droplight Studio. [143]."},{"en":"We offer a full range of photography services for real estate professionals like you.","vi":"Chúng tôi cung cấp đầy đủ các dịch vụ nhiếp ảnh dành cho những chuyên gia bất động sản như bà."},{"en":"We take pride in composing interior and exterior shots that make a property look its best.","vi":"Chúng tôi tự hào trong việc bố cục những bức ảnh nội thất và ngoại thất giúp mỗi bất động sản trông đẹp nhất."},{"en":"Droplight Studio spares no effort in [144] ------- superior digital images.","vi":"Droplight Studio luôn nỗ lực hết mình trong việc [144] những hình ảnh kỹ thuật số chất lượng vượt trội."},{"en":"[145] -------, our professional-grade equipment, lighting, and staging techniques allow us to highlight the best features of a property.","vi":"[145], trang thiết bị chuẩn chuyên nghiệp cùng kỹ thuật ánh sáng và bài trí không gian của chúng tôi cho phép làm nổi bật những ưu điểm tốt nhất của bất động sản."},{"en":"And once the photo shoot is over, every image [146] ------- expert editing.","vi":"Và ngay khi buổi chụp ảnh kết thúc, mỗi bức ảnh đều [146] sự chỉnh sửa chuyên nghiệp."},{"en":"All these services come standard in every package.","vi":"Tất cả những dịch vụ này đều là hạng mục tiêu chuẩn đi kèm trong mọi gói dịch vụ."}]},{"speaker":"","en":"Please visit our Web site to view our work as well as our pricing and scheduling information. We are happy to work with you to customize orders.","vi":"Vui lòng truy cập trang web của chúng tôi để xem các sản phẩm đã thực hiện cũng như bảng giá và thông tin đặt lịch. Chúng tôi rất sẵn lòng phối hợp với bà để thiết kế các đơn hàng theo yêu cầu riêng.","units":[{"en":"Please visit our Web site to view our work as well as our pricing and scheduling information.","vi":"Vui lòng truy cập trang web của chúng tôi để xem các sản phẩm đã thực hiện cũng như bảng giá và thông tin đặt lịch."},{"en":"We are happy to work with you to customize orders.","vi":"Chúng tôi rất sẵn lòng phối hợp với bà để thiết kế các đơn hàng theo yêu cầu riêng."}]},{"speaker":"","en":"Sincerely,","vi":"Trân trọng,","units":[{"en":"Sincerely,","vi":"Trân trọng,"}]},{"speaker":"","en":"Omar Ridha, Droplight Studio","vi":"Omar Ridha, Droplight Studio","units":[{"en":"Omar Ridha, Droplight Studio","vi":"Omar Ridha, Droplight Studio"}]}],"vocab":[{"word":"indeed","pos":"adv","ipa":"/ɪnˈdiːd/","meaning":"thật vậy, quả thực"},{"word":"staging","pos":"n","ipa":"/ˈsteɪdʒɪŋ/","meaning":"kỹ thuật bài trí, dàn dựng không gian"},{"word":"highlight","pos":"v","ipa":"/ˈhaɪlaɪt/","meaning":"làm nổi bật, tôn lên"},{"word":"professional-grade","pos":"adj","ipa":"/prəˈfeʃənəl ɡreɪd/","meaning":"đạt chuẩn chuyên nghiệp"}],"isScanBacked":false,"docTypeLabel":"letter","context":"Promotional letter from Omar Ridha at Droplight Studio to Naomi Burwell offering real estate photography","grammarType":"Liên từ / Trạng từ liên kết (Conjunction / Conjunctive Adverb)","formula":"CÔNG THỨC PART 6 (6. PART 6 THUỘC LÒNG — Trạng từ liên kết khẳng định): Câu trước khẳng định studio nỗ lực tạo ảnh vượt trội; câu sau đưa ra dẫn chứng cụ thể về thiết bị, ánh sáng, kỹ thuật bài trí để xác nhận -> Chọn trạng từ nhấn mạnh \"Indeed\" (Thật vậy).","optionAnalysis":{"A":"Sai quan hệ logic: \"If not\" (nếu không) tạo giả định phủ định, trái với chức năng của câu sau là bổ sung bằng chứng khẳng định cho nỗ lực tạo ảnh đẹp ở câu trước.","B":"Sai ngữ cảnh đối chiếu: \"By comparison\" (khi so sánh) chỉ dùng khi so sánh giữa hai bên, nhưng đoạn văn không nhắc đến đối thủ hay phương án nào khác để đối chiếu.","C":"Sai mạch liên kết: \"Otherwise\" (nếu không thì) đưa ra kịch bản thay thế khi điều trước không thành, không khớp với câu đang giải thích cụ thể trang thiết bị của studio.","D":"Đáp án chính xác: \"Indeed\" (thật vậy) nhấn mạnh và củng cố khẳng định ở câu trước bằng việc liệt kê trang thiết bị chuyên nghiệp, ánh sáng và kỹ thuật bài trí."},"evDocIdx":0,"evTargets":[{"badge":"Câu 145 · Đáp án D","opt":"D","isCorrect":true,"quote":"Droplight Studio spares no effort in","viQuote":"Droplight Studio luôn nỗ lực hết mình trong việc"},{"badge":"Câu 145 · Đáp án D","opt":"D","isCorrect":true,"quote":"our professional-grade equipment, lighting, and staging techniques allow us to highlight the best features of a property.","viQuote":"trang thiết bị chuẩn chuyên nghiệp cùng kỹ thuật ánh sáng và bài trí không gian của chúng tôi cho phép làm nổi bật những ưu điểm tốt nhất của bất động sản."}],"evQuotes":["Droplight Studio spares no effort in","our professional-grade equipment, lighting, and staging techniques allow us to highlight the best features of a property."]},{"q":146,"part":6,"group_id":"E25_T01_G143_146","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc07.webp"],"stem_en":"Select the best answer for blank (146) in the passage.","stem_vi":"Chọn đáp án phù hợp nhất để điền vào chỗ trống (146) trong đoạn văn.","options":{"A":{"en":"receives","vi":"nhận được (hiện tại đơn)"},"B":{"en":"is receiving","vi":"đang nhận được (hiện tại tiếp diễn)"},"C":{"en":"had received","vi":"đã nhận được (quá khứ hoàn thành)"},"D":{"en":"had to receive","vi":"đã phải nhận được (quá khứ của have to)"}},"ans":"A","explanation":"Đáp án đúng: (A) receives (nhận được) — chia thì hiện tại đơn số ít hòa hợp với chủ ngữ \"every image\", diễn tả quy trình dịch vụ tiêu chuẩn luôn áp dụng.\nDẫn chứng: \"And once the photo shoot is over, every image [146] ------- expert editing. All these services come standard in every package.\" (Và khi buổi chụp ảnh kết thúc, mỗi bức ảnh đều nhận được sự chỉnh sửa chuyên nghiệp. Mọi dịch vụ này đều là tiêu chuẩn trong từng gói).\nPhân tích bẫy:\n- (B) Sai thì hiện tại tiếp diễn: \"is receiving\" diễn tả hành động tạm thời đang diễn ra ngay lúc nói, không dùng để mô tả quy trình cố định trong thư chào dịch vụ.\n- (C) Sai thì quá khứ hoàn thành: \"had received\" chỉ hành động đã hoàn tất trước một mốc quá khứ, trái với toàn bộ bức thư đang ở hiện tại giới thiệu gói dịch vụ.\n- (D) Sai thì quá khứ: \"had to receive\" (đã phải nhận) mang nghĩa bắt buộc trong quá khứ, không khớp với câu kết hiện tại đơn \"come standard in every package\".","lines":[{"speaker":"","en":"April 7","vi":"Ngày 7 tháng 4","units":[{"en":"April 7","vi":"Ngày 7 tháng 4"}]},{"speaker":"","en":"Naomi Burwell, 43 Waymire Road, South Portland, ME 04109","vi":"Người nhận: Naomi Burwell, 43 Waymire Road, South Portland, ME 04109","units":[{"en":"Naomi Burwell, 43 Waymire Road, South Portland, ME 04109","vi":"Người nhận: Naomi Burwell, 43 Waymire Road, South Portland, ME 04109"}]},{"speaker":"","en":"Dear Ms. Burwell,","vi":"Kính gửi bà Burwell,","units":[{"en":"Dear Ms. Burwell,","vi":"Kính gửi bà Burwell,"}]},{"speaker":"","en":"I am Omar Ridha, the manager of Droplight Studio. [143] -------. We offer a full range of photography services for real estate professionals like you. We take pride in composing interior and exterior shots that make a property look its best. Droplight Studio spares no effort in [144] ------- superior digital images. [145] -------, our professional-grade equipment, lighting, and staging techniques allow us to highlight the best features of a property. And once the photo shoot is over, every image [146] ------- expert editing. All these services come standard in every package.","vi":"Tôi là Omar Ridha, quản lý của Droplight Studio. [143]. Chúng tôi cung cấp đầy đủ các dịch vụ nhiếp ảnh dành cho những chuyên gia bất động sản như bà. Chúng tôi tự hào trong việc bố cục những bức ảnh nội thất và ngoại thất giúp mỗi bất động sản trông đẹp nhất. Droplight Studio luôn nỗ lực hết mình trong việc [144] những hình ảnh kỹ thuật số chất lượng vượt trội. [145], trang thiết bị chuẩn chuyên nghiệp cùng kỹ thuật ánh sáng và bài trí không gian của chúng tôi cho phép làm nổi bật những ưu điểm tốt nhất của bất động sản. Và ngay khi buổi chụp ảnh kết thúc, mỗi bức ảnh đều [146] sự chỉnh sửa chuyên nghiệp. Tất cả những dịch vụ này đều là hạng mục tiêu chuẩn đi kèm trong mọi gói dịch vụ.","units":[{"en":"I am Omar Ridha, the manager of Droplight Studio. [143] -------.","vi":"Tôi là Omar Ridha, quản lý của Droplight Studio. [143]."},{"en":"We offer a full range of photography services for real estate professionals like you.","vi":"Chúng tôi cung cấp đầy đủ các dịch vụ nhiếp ảnh dành cho những chuyên gia bất động sản như bà."},{"en":"We take pride in composing interior and exterior shots that make a property look its best.","vi":"Chúng tôi tự hào trong việc bố cục những bức ảnh nội thất và ngoại thất giúp mỗi bất động sản trông đẹp nhất."},{"en":"Droplight Studio spares no effort in [144] ------- superior digital images.","vi":"Droplight Studio luôn nỗ lực hết mình trong việc [144] những hình ảnh kỹ thuật số chất lượng vượt trội."},{"en":"[145] -------, our professional-grade equipment, lighting, and staging techniques allow us to highlight the best features of a property.","vi":"[145], trang thiết bị chuẩn chuyên nghiệp cùng kỹ thuật ánh sáng và bài trí không gian của chúng tôi cho phép làm nổi bật những ưu điểm tốt nhất của bất động sản."},{"en":"And once the photo shoot is over, every image [146] ------- expert editing.","vi":"Và ngay khi buổi chụp ảnh kết thúc, mỗi bức ảnh đều [146] sự chỉnh sửa chuyên nghiệp."},{"en":"All these services come standard in every package.","vi":"Tất cả những dịch vụ này đều là hạng mục tiêu chuẩn đi kèm trong mọi gói dịch vụ."}]},{"speaker":"","en":"Please visit our Web site to view our work as well as our pricing and scheduling information. We are happy to work with you to customize orders.","vi":"Vui lòng truy cập trang web của chúng tôi để xem các sản phẩm đã thực hiện cũng như bảng giá và thông tin đặt lịch. Chúng tôi rất sẵn lòng phối hợp với bà để thiết kế các đơn hàng theo yêu cầu riêng.","units":[{"en":"Please visit our Web site to view our work as well as our pricing and scheduling information.","vi":"Vui lòng truy cập trang web của chúng tôi để xem các sản phẩm đã thực hiện cũng như bảng giá và thông tin đặt lịch."},{"en":"We are happy to work with you to customize orders.","vi":"Chúng tôi rất sẵn lòng phối hợp với bà để thiết kế các đơn hàng theo yêu cầu riêng."}]},{"speaker":"","en":"Sincerely,","vi":"Trân trọng,","units":[{"en":"Sincerely,","vi":"Trân trọng,"}]},{"speaker":"","en":"Omar Ridha, Droplight Studio","vi":"Omar Ridha, Droplight Studio","units":[{"en":"Omar Ridha, Droplight Studio","vi":"Omar Ridha, Droplight Studio"}]}],"vocab":[{"word":"come standard","pos":"phr","ipa":"/kʌm ˈstændərd/","meaning":"được tích hợp sẵn như hạng mục tiêu chuẩn"},{"word":"customize","pos":"v","ipa":"/ˈkʌstəmaɪz/","meaning":"tùy chỉnh, thiết kế theo yêu cầu riêng"},{"word":"exterior","pos":"adj","ipa":"/ɪkˈstɪriər/","meaning":"thuộc ngoại thất, bên ngoài"}],"isScanBacked":false,"docTypeLabel":"letter","context":"Promotional letter from Omar Ridha at Droplight Studio to Naomi Burwell offering real estate photography","grammarType":"Chia động từ — Thì / Thể (Bị động - Chủ động) / Dạng V-ing · to V","formula":"CÔNG THỨC PART 6 (Thì Hiện tại đơn cho quy trình tiêu chuẩn): Mệnh đề thời gian \"once the photo shoot is over\" và câu sau \"All these services come standard\" đều ở hiện tại đơn -> Chọn động từ chia hiện tại đơn số ít \"receives\" hòa hợp với \"every image\".","optionAnalysis":{"A":"Đáp án chính xác: động từ thì hiện tại đơn số ít \"receives\" hòa hợp với \"every image\" và đồng bộ thì với \"is over\" lẫn \"come standard\", mô tả quy trình mặc định của studio.","B":"Sai cách dùng thì: thì hiện tại tiếp diễn \"is receiving\" chỉ sự việc đang xảy ra tại thời điểm nói, không phù hợp để trình bày quy trình tiêu chuẩn lặp lại của gói dịch vụ.","C":"Sai thì động từ: thì quá khứ hoàn thành \"had received\" diễn tả sự việc trước một thời điểm quá khứ, mâu thuẫn với mạch hiện tại đơn xuyên suốt phần mô tả dịch vụ.","D":"Sai thì và sắc thái: \"had to receive\" đặt hành động ở quá khứ và mang nghĩa bị ép buộc, không khớp với giọng văn giới thiệu quyền lợi tiêu chuẩn ở hiện tại."},"evDocIdx":0,"evTargets":[{"badge":"Câu 146 · Đáp án A","opt":"A","isCorrect":true,"quote":"And once the photo shoot is over, every image","viQuote":"Và ngay khi buổi chụp ảnh kết thúc, mỗi bức ảnh đều"},{"badge":"Câu 146 · Đáp án A","opt":"A","isCorrect":true,"quote":"All these services come standard in every package.","viQuote":"Tất cả những dịch vụ này đều là hạng mục tiêu chuẩn đi kèm trong mọi gói dịch vụ."}],"evQuotes":["And once the photo shoot is over, every image","All these services come standard in every package."]},{"q":147,"part":7,"group_id":"E25_T01_G147_148","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc08.webp"],"stem_en":"Where is the information most likely found?","stem_vi":"Thông tin này có khả năng được tìm thấy ở đâu nhất?","options":{"A":{"en":"On a door","vi":"Trên một cánh cửa"},"B":{"en":"On a receipt","vi":"Trên một tờ biên lai"},"C":{"en":"In a box","vi":"Trong một chiếc hộp"},"D":{"en":"On a Web site","vi":"Trên một trang web"}},"ans":"C","evidence_quote":"As you do the unpacking, please verify that all components are included and place them in a safe area to avoid loss or damage.","explanation":"Đáp án đúng: (C) Trong một chiếc hộp — Văn bản mở đầu bằng lời cảm ơn đã mua hàng, hướng dẫn kiểm tra linh kiện ngay khi mở bao bì (\"do the unpacking\") và lắp ráp trên vỏ hộp rỗng đã trải phẳng (\"on the flattened empty box\"), chứng tỏ tờ thông tin này được đặt bên trong hộp sản phẩm.\nDẫn chứng: \"As you do the unpacking, please verify that all components are included and place them in a safe area to avoid loss or damage. Assemble the item on a soft surface or on the flattened empty box.\" (Khi mở hộp, vui lòng kiểm tra đầy đủ bộ phận và lắp ráp sản phẩm trên bề mặt mềm hoặc vỏ hộp rỗng đã trải phẳng).\nPhân tích bẫy:\n- (A) Sai ngữ cảnh sử dụng: Tài liệu là hướng dẫn lắp ráp cho khách hàng vừa khui kiện, không phải bảng thông báo hay nội quy gắn trên cánh cửa (\"On a door\").\n- (B) Bẫy chi tiết mua hàng: Bài có câu \"Thank you for purchasing this item\", nhưng tờ biên lai (\"receipt\") chỉ ghi thông tin thanh toán chứ không chứa hướng dẫn kiểm tra ốc vít hay lắp ráp sản phẩm.\n- (D) Bẫy từ khóa xuất hiện trong bài: Đoạn cuối nhắc \"Please visit our Web site\" kèm địa chỉ www.indoordelight.com, tức trang web là kênh bổ sung để xem mẹo bảo dưỡng và đăng ký bảo hành chứ không phải nơi đặt tờ hướng dẫn mở hộp này.","lines":[{"speaker":"Document 1 — Thông tin","en":"STOP! PLEASE READ FIRST.","vi":"DỪNG LẠI! VUI LÒNG ĐỌC TRƯỚC.","units":[{"en":"STOP!","vi":"DỪNG LẠI!"},{"en":"PLEASE READ FIRST.","vi":"VUI LÒNG ĐỌC TRƯỚC."}]},{"speaker":"","en":"Thank you for purchasing this item.","vi":"Cảm ơn quý khách đã mua sản phẩm này.","units":[{"en":"Thank you for purchasing this item.","vi":"Cảm ơn quý khách đã mua sản phẩm này."}]},{"speaker":"","en":"As you do the unpacking, please verify that all components are included and place them in a safe area to avoid loss or damage. Assemble the item on a soft surface or on the flattened empty box.","vi":"Khi mở hộp, vui lòng kiểm tra để đảm bảo có đầy đủ tất cả các bộ phận và đặt chúng ở nơi an toàn nhằm tránh thất lạc hoặc hư hỏng. Hãy lắp ráp sản phẩm trên bề mặt mềm hoặc trên vỏ hộp rỗng đã trải phẳng.","units":[{"en":"As you do the unpacking, please verify that all components are included and place them in a safe area to avoid loss or damage.","vi":"Khi mở hộp, vui lòng kiểm tra để đảm bảo có đầy đủ tất cả các bộ phận và đặt chúng ở nơi an toàn nhằm tránh thất lạc hoặc hư hỏng."},{"en":"Assemble the item on a soft surface or on the flattened empty box.","vi":"Hãy lắp ráp sản phẩm trên bề mặt mềm hoặc trên vỏ hộp rỗng đã trải phẳng."}]},{"speaker":"","en":"Follow the pictures and begin the assembly by placing the main part on its side. Never overtighten any screws or bolts, or you may damage the wood or cushioning. Please visit our Web site to obtain maintenance tips and register your product for warranty coverage: www.indoordelight.com.","vi":"Làm theo hình minh họa và bắt đầu lắp ráp bằng cách đặt bộ phận chính nằm nghiêng. Không bao giờ siết quá chặt bất kỳ ốc vít hoặc bu lông nào, nếu không quý khách có thể làm hỏng phần gỗ hoặc lớp đệm. Vui lòng truy cập trang web của chúng tôi để xem hướng dẫn bảo dưỡng và đăng ký bảo hành sản phẩm: www.indoordelight.com.","units":[{"en":"Follow the pictures and begin the assembly by placing the main part on its side.","vi":"Làm theo hình minh họa và bắt đầu lắp ráp bằng cách đặt bộ phận chính nằm nghiêng."},{"en":"Never overtighten any screws or bolts, or you may damage the wood or cushioning.","vi":"Không bao giờ siết quá chặt bất kỳ ốc vít hoặc bu lông nào, nếu không quý khách có thể làm hỏng phần gỗ hoặc lớp đệm."},{"en":"Please visit our Web site to obtain maintenance tips and register your product for warranty coverage: www.indoordelight.com.","vi":"Vui lòng truy cập trang web của chúng tôi để xem hướng dẫn bảo dưỡng và đăng ký bảo hành sản phẩm: www.indoordelight.com."}]}],"vocab":[{"word":"unpacking","pos":"n","ipa":"/ʌnˈpækɪŋ/","meaning":"việc mở hộp, dỡ kiện hàng"},{"word":"component","pos":"n","ipa":"/kəmˈpoʊnənt/","meaning":"linh kiện, bộ phận cấu thành"},{"word":"verify","pos":"v","ipa":"/ˈverɪfaɪ/","meaning":"kiểm tra, xác minh"},{"word":"assemble","pos":"v","ipa":"/əˈsembəl/","meaning":"lắp ráp"}],"isScanBacked":false,"docTypeLabel":"information","context":"Thông tin lắp ráp sản phẩm từ Indoor Delight","grammarType":"Part 7 — Suy luận & Hàm ý văn bản (Inference & Implied Meaning)","formula":"CÔNG THỨC PART 7 (Thông tin hướng dẫn — Suy luận vị trí tài liệu): Đọc các động từ chỉ thao tác mở kiện hàng (\"do the unpacking\", \"flattened empty box\", \"begin the assembly\") và lời mời truy cập trang web ở cuối -> Suy ra tờ hướng dẫn nằm ngay bên trong hộp sản phẩm (\"In a box\").","optionAnalysis":{"A":"Sai ngữ cảnh sử dụng: Đây là tờ hướng dẫn kiểm tra linh kiện và lắp ráp dành cho khách vừa mua sản phẩm, không phải biển báo hay thông tin dán trên cửa (\"On a door\").","B":"Bẫy chi tiết \"purchasing this item\": Biên lai (\"receipt\") chỉ ghi giá tiền và giao dịch mua bán, không trình bày các bước mở hộp và lắp ráp đồ.","C":"Chính xác! Cụm từ \"As you do the unpacking\" (khi mở hộp) và \"on the flattened empty box\" (trên vỏ hộp rỗng trải phẳng) chứng minh tờ thông tin đi kèm bên trong hộp sản phẩm.","D":"Bẫy từ khóa \"Web site\": Đoạn cuối mời khách truy cập \"www.indoordelight.com\" để đăng ký bảo hành và xem mẹo bảo dưỡng, cho thấy trang web là kênh phụ trợ chứ không phải nơi chứa tờ hướng dẫn mở hộp này."},"evDocIdx":0,"evTargets":[{"badge":"Câu 147 · Đáp án C","opt":"C","isCorrect":true,"quote":"As you do the unpacking, please verify that all components are included and place them in a safe area to avoid loss or damage.","viQuote":"Khi mở hộp, vui lòng kiểm tra để đảm bảo có đầy đủ tất cả các bộ phận và đặt chúng ở nơi an toàn nhằm tránh thất lạc hoặc hư hỏng."},{"badge":"Câu 147 · Đáp án C","opt":"C","isCorrect":true,"quote":"Assemble the item on a soft surface or on the flattened empty box.","viQuote":"Hãy lắp ráp sản phẩm trên bề mặt mềm hoặc trên vỏ hộp rỗng đã trải phẳng."}],"evQuotes":["As you do the unpacking, please verify that all components are included and place them in a safe area to avoid loss or damage.","Assemble the item on a soft surface or on the flattened empty box."]},{"q":148,"part":7,"group_id":"E25_T01_G147_148","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc08.webp"],"stem_en":"What kind of item is most likely discussed?","stem_vi":"Loại sản phẩm nào có khả năng được đề cập nhất?","options":{"A":{"en":"A desktop computer","vi":"Một chiếc máy tính để bàn"},"B":{"en":"A piece of furniture","vi":"Một món đồ nội thất"},"C":{"en":"A household appliance","vi":"Một thiết bị gia dụng"},"D":{"en":"A power tool","vi":"Một dụng cụ điện"}},"ans":"B","evidence_quote":"Never overtighten any screws or bolts, or you may damage the wood or cushioning.","explanation":"Đáp án đúng: (B) Một món đồ nội thất — Cảnh báo không siết quá chặt ốc vít hay bu lông vì có thể làm hỏng phần gỗ (\"wood\") hoặc lớp đệm (\"cushioning\"), kết hợp tên thương hiệu \"indoordelight.com\", cho thấy sản phẩm cần lắp ráp này là đồ nội thất có khung gỗ và đệm.\nDẫn chứng: \"Follow the pictures and begin the assembly by placing the main part on its side. Never overtighten any screws or bolts, or you may damage the wood or cushioning.\" (Bắt đầu lắp ráp bằng cách đặt bộ phận chính nằm nghiêng; không siết quá chặt ốc vít hoặc bu lông để tránh làm hỏng phần gỗ hoặc lớp đệm).\nPhân tích bẫy:\n- (A) Sai vật liệu cấu tạo: Máy tính để bàn (\"desktop computer\") chủ yếu làm từ kim loại, nhựa và linh kiện điện tử, không có lớp đệm (\"cushioning\") hay khung gỗ.\n- (C) Sai đặc điểm sản phẩm: Thiết bị gia dụng (\"household appliance\" như lò vi sóng, máy giặt) dùng điện và không đòi hỏi người mua tự lắp ráp khung gỗ và đệm bằng bu lông.\n- (D) Sai đối tượng: Dụng cụ điện (\"power tool\" như máy khoan, máy cưa) không có cấu tạo từ gỗ và lớp đệm để lắp ráp; văn bản cũng không đề cập đến động cơ hay nguồn điện.","lines":[{"speaker":"Document 1 — Thông tin","en":"STOP! PLEASE READ FIRST.","vi":"DỪNG LẠI! VUI LÒNG ĐỌC TRƯỚC.","units":[{"en":"STOP!","vi":"DỪNG LẠI!"},{"en":"PLEASE READ FIRST.","vi":"VUI LÒNG ĐỌC TRƯỚC."}]},{"speaker":"","en":"Thank you for purchasing this item.","vi":"Cảm ơn quý khách đã mua sản phẩm này.","units":[{"en":"Thank you for purchasing this item.","vi":"Cảm ơn quý khách đã mua sản phẩm này."}]},{"speaker":"","en":"As you do the unpacking, please verify that all components are included and place them in a safe area to avoid loss or damage. Assemble the item on a soft surface or on the flattened empty box.","vi":"Khi mở hộp, vui lòng kiểm tra để đảm bảo có đầy đủ tất cả các bộ phận và đặt chúng ở nơi an toàn nhằm tránh thất lạc hoặc hư hỏng. Hãy lắp ráp sản phẩm trên bề mặt mềm hoặc trên vỏ hộp rỗng đã trải phẳng.","units":[{"en":"As you do the unpacking, please verify that all components are included and place them in a safe area to avoid loss or damage.","vi":"Khi mở hộp, vui lòng kiểm tra để đảm bảo có đầy đủ tất cả các bộ phận và đặt chúng ở nơi an toàn nhằm tránh thất lạc hoặc hư hỏng."},{"en":"Assemble the item on a soft surface or on the flattened empty box.","vi":"Hãy lắp ráp sản phẩm trên bề mặt mềm hoặc trên vỏ hộp rỗng đã trải phẳng."}]},{"speaker":"","en":"Follow the pictures and begin the assembly by placing the main part on its side. Never overtighten any screws or bolts, or you may damage the wood or cushioning. Please visit our Web site to obtain maintenance tips and register your product for warranty coverage: www.indoordelight.com.","vi":"Làm theo hình minh họa và bắt đầu lắp ráp bằng cách đặt bộ phận chính nằm nghiêng. Không bao giờ siết quá chặt bất kỳ ốc vít hoặc bu lông nào, nếu không quý khách có thể làm hỏng phần gỗ hoặc lớp đệm. Vui lòng truy cập trang web của chúng tôi để xem hướng dẫn bảo dưỡng và đăng ký bảo hành sản phẩm: www.indoordelight.com.","units":[{"en":"Follow the pictures and begin the assembly by placing the main part on its side.","vi":"Làm theo hình minh họa và bắt đầu lắp ráp bằng cách đặt bộ phận chính nằm nghiêng."},{"en":"Never overtighten any screws or bolts, or you may damage the wood or cushioning.","vi":"Không bao giờ siết quá chặt bất kỳ ốc vít hoặc bu lông nào, nếu không quý khách có thể làm hỏng phần gỗ hoặc lớp đệm."},{"en":"Please visit our Web site to obtain maintenance tips and register your product for warranty coverage: www.indoordelight.com.","vi":"Vui lòng truy cập trang web của chúng tôi để xem hướng dẫn bảo dưỡng và đăng ký bảo hành sản phẩm: www.indoordelight.com."}]}],"vocab":[{"word":"overtighten","pos":"v","ipa":"/ˌoʊvərˈtaɪtən/","meaning":"siết quá chặt"},{"word":"bolt","pos":"n","ipa":"/boʊlt/","meaning":"bu lông, chốt vít"},{"word":"cushioning","pos":"n","ipa":"/ˈkʊʃənɪŋ/","meaning":"lớp đệm, phần nệm lót"},{"word":"warranty coverage","pos":"phr","ipa":"/ˈwɔːrənti ˈkʌvərɪdʒ/","meaning":"phạm vi bảo hành"}],"isScanBacked":false,"docTypeLabel":"information","context":"Thông tin lắp ráp sản phẩm từ Indoor Delight","grammarType":"Part 7 — Suy luận & Hàm ý văn bản (Inference & Implied Meaning)","formula":"CÔNG THỨC PART 7 (Thông tin hướng dẫn — Nhận diện sản phẩm qua chất liệu & thao tác): Kết hợp từ khóa vật liệu (\"wood or cushioning\") với thao tác lắp ráp (\"screws or bolts\", \"placing the main part on its side\") -> Suy ra sản phẩm là đồ nội thất (\"A piece of furniture\").","optionAnalysis":{"A":"Sai đặc điểm vật lý: Máy tính để bàn dùng vỏ kim loại hoặc nhựa và linh kiện điện tử, không có chi tiết \"wood or cushioning\" (gỗ hoặc lớp đệm) để phải tránh siết chặt bu lông.","B":"Chính xác! Sự kết hợp giữa chi tiết tự lắp ráp bằng ốc vít/bu lông (\"screws or bolts\") và chất liệu \"wood or cushioning\" (gỗ hoặc lớp đệm) cùng tên miền \"indoordelight.com\" chỉ đích danh đồ nội thất.","C":"Sai loại hình sản phẩm: Thiết bị gia dụng (\"household appliance\") không có lớp đệm lót và khung gỗ tự lắp ráp, bài đọc cũng không nhắc đến điện năng hay thông số kỹ thuật điện.","D":"Sai ngữ cảnh công cụ: Dụng cụ điện (\"power tool\") dùng để thi công chứ bản thân dụng cụ điện không cấu tạo từ gỗ và đệm (\"wood or cushioning\") để người dùng lắp ráp."},"evDocIdx":0,"evTargets":[{"badge":"Câu 148 · Đáp án B","opt":"B","isCorrect":true,"quote":"Follow the pictures and begin the assembly by placing the main part on its side.","viQuote":"Làm theo hình minh họa và bắt đầu lắp ráp bằng cách đặt bộ phận chính nằm nghiêng."},{"badge":"Câu 148 · Đáp án B","opt":"B","isCorrect":true,"quote":"Never overtighten any screws or bolts, or you may damage the wood or cushioning.","viQuote":"Không bao giờ siết quá chặt bất kỳ ốc vít hoặc bu lông nào, nếu không quý khách có thể làm hỏng phần gỗ hoặc lớp đệm."}],"evQuotes":["Follow the pictures and begin the assembly by placing the main part on its side.","Never overtighten any screws or bolts, or you may damage the wood or cushioning."]},{"q":149,"part":7,"group_id":"E25_T01_G149_150","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc09.webp"],"stem_en":"What is suggested by the schedule?","stem_vi":"Lịch trình này gợi ý điều gì?","options":{"A":{"en":"A conference has been scheduled.","vi":"Một hội nghị đã được lên lịch."},"B":{"en":"A firm has offices in two time zones.","vi":"Một công ty có văn phòng ở hai múi giờ khác nhau."},"C":{"en":"Administrative assistants make travel plans.","vi":"Các trợ lý hành chính lập kế hoạch đi lại."},"D":{"en":"Some meeting times have been changed.","vi":"Một số khung giờ họp đã được thay đổi."}},"ans":"B","evidence_quote":"We are asking all Winnipeg staff to keep a copy of this schedule at their desks as a quick reference tool for scheduling interoffice meetings.","explanation":"Đáp án đúng: (B) Một công ty có văn phòng ở hai múi giờ khác nhau — Tài liệu phục vụ việc đặt lịch họp liên văn phòng (\"interoffice meetings\") và đối chiếu trực tiếp hai cột giờ chênh lệch 7 tiếng giữa Winnipeg và Toulouse.\nDẫn chứng: \"We are asking all Winnipeg staff to keep a copy of this schedule at their desks as a quick reference tool for scheduling interoffice meetings.\" kèm bảng đối chiếu \"Winnipeg | Toulouse\" với mức chênh 7 giờ (\"7:00 A.M. (underlined) | 2:00 P.M.\").\nPhân tích bẫy:\n- (A) Bẫy mở rộng quá mức: Bảng chỉ là công cụ tra cứu (\"quick reference tool\") để nhân viên tự đặt lịch họp nội bộ, không đề cập đến một hội nghị (\"conference\") cụ thể nào đã được ấn định.\n- (C) Bẫy suy diễn ngoài bài: Văn bản gửi cho toàn thể nhân viên Winnipeg (\"all Winnipeg staff\") để sắp xếp họp, không hề nhắc đến trợ lý hành chính hay kế hoạch đi lại (\"travel plans\").\n- (D) Sai trạng thái thông tin: Lịch trình đưa ra quy ước khung giờ ưu tiên từ sau 7:00 đến trước 11:00 sáng, hoàn toàn không thông báo có sự thay đổi hay dời giờ họp nào (\"have been changed\").","lines":[{"speaker":"Document 1 — Schedule","en":"We are asking all Winnipeg staff to keep a copy of this schedule at their desks as a quick reference tool for scheduling interoffice meetings. Whenever possible, please schedule these meetings during one of the underlined hours, that is, after 7:00 A.M. but before 11:00 A.M.","vi":"Chúng tôi đề nghị toàn thể nhân viên tại Winnipeg giữ một bản sao lịch trình này tại bàn làm việc để làm tài liệu tra cứu nhanh khi sắp xếp các cuộc họp giữa các văn phòng. Bất cứ khi nào có thể, vui lòng sắp xếp các cuộc họp này vào một trong các khung giờ được gạch chân, tức là sau 7:00 sáng nhưng trước 11:00 sáng.","units":[{"en":"We are asking all Winnipeg staff to keep a copy of this schedule at their desks as a quick reference tool for scheduling interoffice meetings.","vi":"Chúng tôi đề nghị toàn thể nhân viên tại Winnipeg giữ một bản sao lịch trình này tại bàn làm việc để làm tài liệu tra cứu nhanh khi sắp xếp các cuộc họp giữa các văn phòng."},{"en":"Whenever possible, please schedule these meetings during one of the underlined hours, that is, after 7:00 A.M. but before 11:00 A.M.","vi":"Bất cứ khi nào có thể, vui lòng sắp xếp các cuộc họp này vào một trong các khung giờ được gạch chân, tức là sau 7:00 sáng nhưng trước 11:00 sáng."}]},{"speaker":"","en":"Winnipeg | Toulouse","vi":"Winnipeg | Toulouse","units":[{"en":"Winnipeg | Toulouse","vi":"Winnipeg | Toulouse"}]},{"speaker":"","en":"7:00 A.M. (underlined) | 2:00 P.M.","vi":"7:00 sáng (gạch chân) | 2:00 chiều","units":[{"en":"7:00 A.M. (underlined) | 2:00 P.M.","vi":"7:00 sáng (gạch chân) | 2:00 chiều"}]},{"speaker":"","en":"8:00 A.M. (underlined) | 3:00 P.M.","vi":"8:00 sáng (gạch chân) | 3:00 chiều","units":[{"en":"8:00 A.M. (underlined) | 3:00 P.M.","vi":"8:00 sáng (gạch chân) | 3:00 chiều"}]},{"speaker":"","en":"9:00 A.M. (underlined) | 4:00 P.M.","vi":"9:00 sáng (gạch chân) | 4:00 chiều","units":[{"en":"9:00 A.M. (underlined) | 4:00 P.M.","vi":"9:00 sáng (gạch chân) | 4:00 chiều"}]},{"speaker":"","en":"10:00 A.M. (underlined) | 5:00 P.M.","vi":"10:00 sáng (gạch chân) | 5:00 chiều","units":[{"en":"10:00 A.M. (underlined) | 5:00 P.M.","vi":"10:00 sáng (gạch chân) | 5:00 chiều"}]},{"speaker":"","en":"11:00 A.M. | 6:00 P.M.","vi":"11:00 sáng | 6:00 chiều","units":[{"en":"11:00 A.M. | 6:00 P.M.","vi":"11:00 sáng | 6:00 chiều"}]},{"speaker":"","en":"12:00 noon | 7:00 P.M.","vi":"12:00 trưa | 7:00 tối","units":[{"en":"12:00 noon | 7:00 P.M.","vi":"12:00 trưa | 7:00 tối"}]}],"vocab":[{"word":"interoffice","pos":"adj","ipa":"/ˌɪntərˈɔːfɪs/","meaning":"giữa các văn phòng, nội bộ liên văn phòng"},{"word":"reference tool","pos":"phr","ipa":"/ˈrefərəns tuːl/","meaning":"tài liệu tra cứu, công cụ tham khảo"},{"word":"time zone","pos":"n","ipa":"/ˈtaɪm zoʊn/","meaning":"múi giờ"}],"isScanBacked":false,"docTypeLabel":"schedule","context":"Interoffice meeting schedule comparing Winnipeg and Toulouse time zones","grammarType":"Part 7 — Suy luận & Hàm ý văn bản (Inference & Implied Meaning)","formula":"CÔNG THỨC PART 7 (Lịch trình — Suy luận từ bảng đối chiếu múi giờ): Nhận diện cụm \"interoffice meetings\" (họp giữa các văn phòng) + bảng quy đổi giờ song song 2 thành phố chênh nhau 7 tiếng (Winnipeg 7:00 A.M. = Toulouse 2:00 P.M.) -> Suy ra công ty có văn phòng ở hai múi giờ khác nhau.","optionAnalysis":{"A":"Bẫy phóng đại: Tài liệu chỉ cung cấp bảng quy đổi giờ tham khảo cho các cuộc họp giữa các văn phòng, không thông báo một hội nghị (\"conference\") nào đã được lên lịch.","B":"Chính xác! Cụm \"interoffice meetings\" (họp giữa các văn phòng) kết hợp với bảng quy đổi giờ song song giữa Winnipeg và Toulouse (lệch nhau 7 tiếng) chứng tỏ công ty có văn phòng tại hai múi giờ.","C":"Thông tin không có cơ sở trong bài: Lịch trình hướng dẫn toàn bộ nhân viên tại Winnipeg xếp lịch họp, không nhắc tới \"administrative assistants\" hay việc lập kế hoạch đi lại.","D":"Sai nội dung văn bản: Bảng chỉ nêu khung giờ gợi ý để đặt lịch họp, không hề nói rằng các khung giờ họp trước đây đã bị điều chỉnh hay thay đổi."},"evDocIdx":0,"evTargets":[{"badge":"Câu 149 · Đáp án B","opt":"B","isCorrect":true,"quote":"We are asking all Winnipeg staff to keep a copy of this schedule at their desks as a quick reference tool for scheduling interoffice meetings.","viQuote":"Chúng tôi đề nghị toàn thể nhân viên tại Winnipeg giữ một bản sao lịch trình này tại bàn làm việc để làm tài liệu tra cứu nhanh khi sắp xếp các cuộc họp giữa các văn phòng."},{"badge":"Câu 149 · Đáp án B","opt":"B","isCorrect":true,"quote":"7:00 A.M. (underlined)","viQuote":"7:00 sáng (gạch chân)"},{"badge":"Câu 149 · Đáp án B","opt":"B","isCorrect":true,"quote":"2:00 P.M.","viQuote":"2:00 chiều"}],"evQuotes":["We are asking all Winnipeg staff to keep a copy of this schedule at their desks as a quick reference tool for scheduling interoffice meetings.","7:00 A.M. (underlined)","2:00 P.M."]},{"q":150,"part":7,"group_id":"E25_T01_G149_150","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc09.webp"],"stem_en":"What is indicated about 11:00 A.M. Winnipeg time?","stem_vi":"Thông tin nào được nêu về khung giờ 11:00 sáng theo giờ Winnipeg?","options":{"A":{"en":"It is when the Winnipeg office closes for lunch.","vi":"Đó là lúc văn phòng Winnipeg đóng cửa nghỉ trưa."},"B":{"en":"It is when staff in Toulouse begin their workday.","vi":"Đó là lúc nhân viên tại Toulouse bắt đầu ngày làm việc."},"C":{"en":"It is not a preferred time to schedule a meeting.","vi":"Đó không phải là khung giờ ưu tiên để sắp xếp cuộc họp."},"D":{"en":"It has just been added to the schedule.","vi":"Khung giờ này vừa mới được bổ sung vào lịch trình."}},"ans":"C","evidence_quote":"Whenever possible, please schedule these meetings during one of the underlined hours, that is, after 7:00 A.M. but before 11:00 A.M.","explanation":"Đáp án đúng: (C) Đó không phải là khung giờ ưu tiên để sắp xếp cuộc họp — Thông báo quy định rõ các cuộc họp liên văn phòng nên đặt vào giờ được gạch chân, tức là sau 7:00 sáng nhưng trước 11:00 sáng (\"before 11:00 A.M.\"), và trên bảng dòng \"11:00 A.M.\" cũng không được gạch chân.\nDẫn chứng: \"Whenever possible, please schedule these meetings during one of the underlined hours, that is, after 7:00 A.M. but before 11:00 A.M.\" kết hợp dòng bảng \"11:00 A.M. | 6:00 P.M.\" không gạch chân (các giờ gạch chân chỉ từ 7:00 đến 10:00 A.M.).\nPhân tích bẫy:\n- (A) Suy diễn sai giờ nghỉ trưa: Văn bản không đề cập văn phòng Winnipeg đóng cửa nghỉ trưa lúc 11:00 sáng; lý do tránh mốc này là vì bên Toulouse đã là 6:00 chiều.\n- (B) Ngược thời gian thực tế: Khi Winnipeg là 11:00 A.M. thì Toulouse tương ứng là 6:00 P.M. (buổi tối/tan làm), không phải lúc nhân viên bắt đầu ngày làm việc (\"begin their workday\").\n- (D) Chi tiết bịa đặt: Mốc 11:00 A.M. nằm sẵn trong bảng đối chiếu múi giờ như các mốc khác, hoàn toàn không có thông tin nào nói khung giờ này vừa mới được bổ sung (\"just been added\").","lines":[{"speaker":"Document 1 — Schedule","en":"We are asking all Winnipeg staff to keep a copy of this schedule at their desks as a quick reference tool for scheduling interoffice meetings. Whenever possible, please schedule these meetings during one of the underlined hours, that is, after 7:00 A.M. but before 11:00 A.M.","vi":"Chúng tôi đề nghị toàn thể nhân viên tại Winnipeg giữ một bản sao lịch trình này tại bàn làm việc để làm tài liệu tra cứu nhanh khi sắp xếp các cuộc họp giữa các văn phòng. Bất cứ khi nào có thể, vui lòng sắp xếp các cuộc họp này vào một trong các khung giờ được gạch chân, tức là sau 7:00 sáng nhưng trước 11:00 sáng.","units":[{"en":"We are asking all Winnipeg staff to keep a copy of this schedule at their desks as a quick reference tool for scheduling interoffice meetings.","vi":"Chúng tôi đề nghị toàn thể nhân viên tại Winnipeg giữ một bản sao lịch trình này tại bàn làm việc để làm tài liệu tra cứu nhanh khi sắp xếp các cuộc họp giữa các văn phòng."},{"en":"Whenever possible, please schedule these meetings during one of the underlined hours, that is, after 7:00 A.M. but before 11:00 A.M.","vi":"Bất cứ khi nào có thể, vui lòng sắp xếp các cuộc họp này vào một trong các khung giờ được gạch chân, tức là sau 7:00 sáng nhưng trước 11:00 sáng."}]},{"speaker":"","en":"Winnipeg | Toulouse","vi":"Winnipeg | Toulouse","units":[{"en":"Winnipeg | Toulouse","vi":"Winnipeg | Toulouse"}]},{"speaker":"","en":"7:00 A.M. (underlined) | 2:00 P.M.","vi":"7:00 sáng (gạch chân) | 2:00 chiều","units":[{"en":"7:00 A.M. (underlined) | 2:00 P.M.","vi":"7:00 sáng (gạch chân) | 2:00 chiều"}]},{"speaker":"","en":"8:00 A.M. (underlined) | 3:00 P.M.","vi":"8:00 sáng (gạch chân) | 3:00 chiều","units":[{"en":"8:00 A.M. (underlined) | 3:00 P.M.","vi":"8:00 sáng (gạch chân) | 3:00 chiều"}]},{"speaker":"","en":"9:00 A.M. (underlined) | 4:00 P.M.","vi":"9:00 sáng (gạch chân) | 4:00 chiều","units":[{"en":"9:00 A.M. (underlined) | 4:00 P.M.","vi":"9:00 sáng (gạch chân) | 4:00 chiều"}]},{"speaker":"","en":"10:00 A.M. (underlined) | 5:00 P.M.","vi":"10:00 sáng (gạch chân) | 5:00 chiều","units":[{"en":"10:00 A.M. (underlined) | 5:00 P.M.","vi":"10:00 sáng (gạch chân) | 5:00 chiều"}]},{"speaker":"","en":"11:00 A.M. | 6:00 P.M.","vi":"11:00 sáng | 6:00 chiều","units":[{"en":"11:00 A.M. | 6:00 P.M.","vi":"11:00 sáng | 6:00 chiều"}]},{"speaker":"","en":"12:00 noon | 7:00 P.M.","vi":"12:00 trưa | 7:00 tối","units":[{"en":"12:00 noon | 7:00 P.M.","vi":"12:00 trưa | 7:00 tối"}]}],"vocab":[{"word":"underlined","pos":"adj","ipa":"/ˌʌndərˈlaɪnd/","meaning":"được gạch chân"},{"word":"whenever possible","pos":"phr","ipa":"/wenˈevər ˈpɑːsəbəl/","meaning":"bất cứ khi nào có thể"},{"word":"preferred","pos":"adj","ipa":"/prɪˈfɜːrd/","meaning":"được ưu tiên, được ưa thích hơn"}],"isScanBacked":false,"docTypeLabel":"schedule","context":"Interoffice meeting schedule comparing Winnipeg and Toulouse time zones","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 (Lịch trình — Đọc điều kiện biên \"after X but before Y\"): Đối chiếu quy tắc \"after 7:00 A.M. but before 11:00 A.M.\" với dòng \"11:00 A.M. | 6:00 P.M.\" (không gạch chân) -> Loại trừ mốc 11:00 A.M. khỏi nhóm giờ ưu tiên (\"not a preferred time\").","optionAnalysis":{"A":"Suy diễn sai thực tế văn bản: Bài đọc không hề nhắc đến giờ nghỉ trưa hay việc đóng cửa văn phòng tại Winnipeg vào lúc 11:00 sáng.","B":"Ngược nghĩa múi giờ trên bảng: Theo bảng, 11:00 A.M. ở Winnipeg ứng với 6:00 P.M. ở Toulouse (buổi tối/tan làm), chứ không phải giờ bắt đầu ngày làm việc buổi sáng.","C":"Chính xác! Yêu cầu xếp lịch \"before 11:00 A.M.\" và việc dòng \"11:00 A.M.\" không được gạch chân (underlined) xác nhận đây không phải khung giờ ưu tiên để họp.","D":"Sai hoàn toàn: Mốc 11:00 A.M. là một hàng bình thường trong bảng quy đổi giờ, không có bất kỳ chú thích nào cho thấy nó vừa được thêm vào lịch trình."},"evDocIdx":0,"evTargets":[{"badge":"Câu 150 · Đáp án C","opt":"C","isCorrect":true,"quote":"Whenever possible, please schedule these meetings during one of the underlined hours, that is, after 7:00 A.M. but before 11:00 A.M.","viQuote":"Bất cứ khi nào có thể, vui lòng sắp xếp các cuộc họp này vào một trong các khung giờ được gạch chân, tức là sau 7:00 sáng nhưng trước 11:00 sáng."}],"evQuotes":["Whenever possible, please schedule these meetings during one of the underlined hours, that is, after 7:00 A.M. but before 11:00 A.M."]},{"q":151,"part":7,"group_id":"E25_T01_G151_152","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc10.webp"],"stem_en":"What is indicated about the Bryant Foyer?","stem_vi":"Điều gì được nêu về Bryant Foyer?","options":{"A":{"en":"It is located on the shores of a lake.","vi":"Nơi đây nằm bên bờ một hồ nước."},"B":{"en":"It has recently been renovated.","vi":"Nơi đây gần đây đã được cải tạo."},"C":{"en":"It will build a botanical garden for guests.","vi":"Nơi đây sẽ xây dựng một vườn bách thảo cho khách."},"D":{"en":"It is reserved solely for corporate events.","vi":"Nơi đây chỉ dành riêng cho các sự kiện doanh nghiệp."}},"ans":"B","evidence_quote":"Built in 1897, it was the home of the Francona Charitable Trust until its renovation just over a year ago.","explanation":"Đáp án đúng: (B) Nơi đây gần đây đã được cải tạo — Đoạn quảng cáo nêu rõ tòa nhà xây năm 1897 này từng là trụ sở của Francona Charitable Trust cho đến khi được tu sửa cách đây chỉ hơn một năm (\"its renovation just over a year ago\"), được paraphrase thành \"has recently been renovated\".\nDẫn chứng: \"Built in 1897, it was the home of the Francona Charitable Trust until its renovation just over a year ago.\" (Được xây dựng năm 1897, nơi đây từng là trụ sở của Quỹ từ thiện Francona cho đến đợt cải tạo chỉ hơn một năm trước).\nPhân tích bẫy:\n- (A) Sai vị trí địa lý: Bài ghi địa điểm nằm trên một ngọn đồi (\"Set on a hill\") nhìn ra vườn bách thảo và dòng sông (\"the river\"), không phải bên bờ hồ (\"shores of a lake\").\n- (C) Sai thì và chủ thể: Vườn bách thảo đã nằm liền kề sẵn có (\"adjacent botanical gardens\"), không phải Bryant Foyer \"sẽ xây dựng\" (\"will build\") một khu vườn mới.\n- (D) Bẫy từ cực đoan \"solely\": Địa điểm phục vụ cả tiệc cưới (\"wedding receptions\") lẫn tiệc công ty và thuyết trình chuyên đề (\"office parties, and panel presentations\"), không dành riêng (\"solely\") cho sự kiện doanh nghiệp.","lines":[{"speaker":"Document 1 — Advertisement","en":"The Bryant Foyer is one of the premier event spaces in our area. Set on a hill, it has expansive windows that provide sweeping views of the adjacent botanical gardens and the river. Built in 1897, it was the home of the Francona Charitable Trust until its renovation just over a year ago. Today, the space can accommodate up to 200 guests and is ideal for wedding receptions, office parties, and panel presentations. With its marble floors, cathedral ceiling, and stunning artwork, the Bryant Foyer is the ideal location for your next gathering.","vi":"The Bryant Foyer là một trong những không gian tổ chức sự kiện hàng đầu trong khu vực của chúng tôi. Tọa lạc trên một ngọn đồi, nơi đây sở hữu hệ thống cửa sổ rộng lớn mang đến tầm nhìn bao quát vườn bách thảo liền kề và dòng sông. Được xây dựng vào năm 1897, nơi đây từng là trụ sở của quỹ từ thiện Francona Charitable Trust cho đến khi được cải tạo cách đây chỉ hơn một năm. Ngày nay, không gian này có sức chứa lên đến 200 khách và rất lý tưởng cho các buổi tiệc cưới, tiệc công ty và các buổi thuyết trình chuyên đề. Với sàn đá cẩm thạch, trần vòm cao và các tác phẩm nghệ thuật ấn tượng, Bryant Foyer là địa điểm lý tưởng cho buổi họp mặt tiếp theo của bạn.","units":[{"en":"The Bryant Foyer is one of the premier event spaces in our area.","vi":"The Bryant Foyer là một trong những không gian tổ chức sự kiện hàng đầu trong khu vực của chúng tôi."},{"en":"Set on a hill, it has expansive windows that provide sweeping views of the adjacent botanical gardens and the river.","vi":"Tọa lạc trên một ngọn đồi, nơi đây sở hữu hệ thống cửa sổ rộng lớn mang đến tầm nhìn bao quát vườn bách thảo liền kề và dòng sông."},{"en":"Built in 1897, it was the home of the Francona Charitable Trust until its renovation just over a year ago.","vi":"Được xây dựng vào năm 1897, nơi đây từng là trụ sở của quỹ từ thiện Francona Charitable Trust cho đến khi được cải tạo cách đây chỉ hơn một năm."},{"en":"Today, the space can accommodate up to 200 guests and is ideal for wedding receptions, office parties, and panel presentations.","vi":"Ngày nay, không gian này có sức chứa lên đến 200 khách và rất lý tưởng cho các buổi tiệc cưới, tiệc công ty và các buổi thuyết trình chuyên đề."},{"en":"With its marble floors, cathedral ceiling, and stunning artwork, the Bryant Foyer is the ideal location for your next gathering.","vi":"Với sàn đá cẩm thạch, trần vòm cao và các tác phẩm nghệ thuật ấn tượng, Bryant Foyer là địa điểm lý tưởng cho buổi họp mặt tiếp theo của bạn."}]},{"speaker":"","en":"The on-site restaurant, Andito's, caters our events and also operates as its own business. This farm-to-table restaurant, headed by chef Michaela Rymond, meets all dietary needs and has revolutionized the local food scene. Area residents know to plan far in advance to get a seat.","vi":"Nhà hàng trong khuôn viên, Andito's, phục vụ ẩm thực cho các sự kiện của chúng tôi đồng thời hoạt động như một cơ sở kinh doanh độc lập. Nhà hàng theo mô hình từ nông trại đến bàn ăn này, do bếp trưởng Michaela Rymond đứng đầu, đáp ứng mọi nhu cầu về chế độ ăn uống và đã tạo nên cuộc cách mạng cho nền ẩm thực địa phương. Cư dân trong khu vực đều biết cần lên kế hoạch từ rất sớm để có được chỗ ngồi.","units":[{"en":"The on-site restaurant, Andito's, caters our events and also operates as its own business.","vi":"Nhà hàng trong khuôn viên, Andito's, phục vụ ẩm thực cho các sự kiện của chúng tôi đồng thời hoạt động như một cơ sở kinh doanh độc lập."},{"en":"This farm-to-table restaurant, headed by chef Michaela Rymond, meets all dietary needs and has revolutionized the local food scene.","vi":"Nhà hàng theo mô hình từ nông trại đến bàn ăn này, do bếp trưởng Michaela Rymond đứng đầu, đáp ứng mọi nhu cầu về chế độ ăn uống và đã tạo nên cuộc cách mạng cho nền ẩm thực địa phương."},{"en":"Area residents know to plan far in advance to get a seat.","vi":"Cư dân trong khu vực đều biết cần lên kế hoạch từ rất sớm để có được chỗ ngồi."}]},{"speaker":"","en":"To reserve the event space or to make a dinner reservation, give us a call at 216-555-0157.","vi":"Để đặt thuê không gian tổ chức sự kiện hoặc đặt bàn ăn tối, vui lòng gọi cho chúng tôi theo số 216-555-0157.","units":[{"en":"To reserve the event space or to make a dinner reservation, give us a call at 216-555-0157.","vi":"Để đặt thuê không gian tổ chức sự kiện hoặc đặt bàn ăn tối, vui lòng gọi cho chúng tôi theo số 216-555-0157."}]}],"vocab":[{"word":"renovation","pos":"n","ipa":"/ˌrenəˈveɪʃən/","meaning":"việc cải tạo, tu sửa"},{"word":"adjacent","pos":"adj","ipa":"/əˈdʒeɪsənt/","meaning":"liền kề, kề bên"},{"word":"expansive","pos":"adj","ipa":"/ɪkˈspænsɪv/","meaning":"rộng lớn, bao quát"},{"word":"accommodate","pos":"v","ipa":"/əˈkɑːmədeɪt/","meaning":"chứa được, đáp ứng chỗ cho"}],"isScanBacked":false,"docTypeLabel":"advertisement","context":"Advertisement for The Bryant Foyer event space and Andito's restaurant","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 (Quảng cáo địa điểm — Paraphrase danh từ thành bị động): Chuyển đổi cụm danh từ \"until its renovation just over a year ago\" (cho đến đợt cải tạo hơn một năm trước) -> \"has recently been renovated\" (gần đây đã được cải tạo).","optionAnalysis":{"A":"Sai chi tiết địa hình: Tòa nhà tọa lạc trên đồi (\"Set on a hill\") và có tầm nhìn ra sông (\"the river\"), chứ không nằm bên bờ hồ (\"shores of a lake\").","B":"Chính xác! Cụm \"its renovation just over a year ago\" (được cải tạo cách đây hơn một năm) khớp nghĩa trực tiếp với \"has recently been renovated\".","C":"Sai thì động từ và sự thật: Khu vườn bách thảo (\"adjacent botanical gardens\") đã tồn tại ngay kế bên để khách ngắm qua cửa sổ, không phải công trình sắp xây.","D":"Bẫy từ giới hạn \"solely\" (chỉ riêng): Ngoài tiệc công ty và tọa đàm, nơi đây còn lý tưởng cho tiệc cưới (\"wedding receptions\"), nên không dành riêng cho doanh nghiệp."},"evDocIdx":0,"evTargets":[{"badge":"Câu 151 · Đáp án B","opt":"B","isCorrect":true,"quote":"Built in 1897, it was the home of the Francona Charitable Trust until its renovation just over a year ago.","viQuote":"Được xây dựng vào năm 1897, nơi đây từng là trụ sở của quỹ từ thiện Francona Charitable Trust cho đến khi được cải tạo cách đây chỉ hơn một năm."}],"evQuotes":["Built in 1897, it was the home of the Francona Charitable Trust until its renovation just over a year ago."]},{"q":152,"part":7,"group_id":"E25_T01_G151_152","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc10.webp"],"stem_en":"What is suggested about Andito's?","stem_vi":"Điều gì được gợi ý về nhà hàng Andito's?","options":{"A":{"en":"It was started by an international chef.","vi":"Nhà hàng này do một đầu bếp quốc tế sáng lập."},"B":{"en":"It offers limited menu options.","vi":"Nhà hàng này có các lựa chọn thực đơn hạn chế."},"C":{"en":"It is now funded by a charitable organization.","vi":"Nhà hàng này hiện được một tổ chức từ thiện tài trợ."},"D":{"en":"It is very popular with local residents.","vi":"Nhà hàng này rất được cư dân địa phương ưa chuộng."}},"ans":"D","evidence_quote":"The on-site restaurant, Andito's, caters our events and also operates as its own business. Area residents know to plan far in advance to get a seat.","explanation":"Đáp án đúng: (D) Nhà hàng này rất được cư dân địa phương ưa chuộng — Văn bản cho biết Andito's đã tạo bước ngoặt cho ẩm thực địa phương và cư dân trong vùng đều biết phải lên kế hoạch đặt bàn từ rất sớm mới có chỗ ngồi (\"plan far in advance to get a seat\"), chứng tỏ mức độ đông khách và ưa chuộng rất cao.\nDẫn chứng: \"This farm-to-table restaurant, headed by chef Michaela Rymond, meets all dietary needs and has revolutionized the local food scene. Area residents know to plan far in advance to get a seat.\" (Nhà hàng này đã cách mạng hóa nền ẩm thực địa phương; cư dân trong khu vực đều biết cần lên kế hoạch từ rất sớm để có chỗ ngồi).\nPhân tích bẫy:\n- (A) Chi tiết bịa đặt: Bài chỉ nêu bếp trưởng hiện tại là Michaela Rymond (\"headed by chef Michaela Rymond\"), không đề cập bà là đầu bếp quốc tế hay người sáng lập nhà hàng.\n- (B) Ngược nghĩa văn bản: Trái với \"limited menu options\", nhà hàng đáp ứng mọi nhu cầu về chế độ ăn uống (\"meets all dietary needs\").\n- (C) Bẫy ghép nhầm thực thể: Quỹ từ thiện Francona Charitable Trust là chủ cũ của tòa nhà Bryant Foyer trước khi cải tạo, còn Andito's hiện hoạt động kinh doanh độc lập (\"operates as its own business\"), không được quỹ từ thiện tài trợ.","lines":[{"speaker":"Document 1 — Advertisement","en":"The Bryant Foyer is one of the premier event spaces in our area. Set on a hill, it has expansive windows that provide sweeping views of the adjacent botanical gardens and the river. Built in 1897, it was the home of the Francona Charitable Trust until its renovation just over a year ago. Today, the space can accommodate up to 200 guests and is ideal for wedding receptions, office parties, and panel presentations. With its marble floors, cathedral ceiling, and stunning artwork, the Bryant Foyer is the ideal location for your next gathering.","vi":"The Bryant Foyer là một trong những không gian tổ chức sự kiện hàng đầu trong khu vực của chúng tôi. Tọa lạc trên một ngọn đồi, nơi đây sở hữu hệ thống cửa sổ rộng lớn mang đến tầm nhìn bao quát vườn bách thảo liền kề và dòng sông. Được xây dựng vào năm 1897, nơi đây từng là trụ sở của quỹ từ thiện Francona Charitable Trust cho đến khi được cải tạo cách đây chỉ hơn một năm. Ngày nay, không gian này có sức chứa lên đến 200 khách và rất lý tưởng cho các buổi tiệc cưới, tiệc công ty và các buổi thuyết trình chuyên đề. Với sàn đá cẩm thạch, trần vòm cao và các tác phẩm nghệ thuật ấn tượng, Bryant Foyer là địa điểm lý tưởng cho buổi họp mặt tiếp theo của bạn.","units":[{"en":"The Bryant Foyer is one of the premier event spaces in our area.","vi":"The Bryant Foyer là một trong những không gian tổ chức sự kiện hàng đầu trong khu vực của chúng tôi."},{"en":"Set on a hill, it has expansive windows that provide sweeping views of the adjacent botanical gardens and the river.","vi":"Tọa lạc trên một ngọn đồi, nơi đây sở hữu hệ thống cửa sổ rộng lớn mang đến tầm nhìn bao quát vườn bách thảo liền kề và dòng sông."},{"en":"Built in 1897, it was the home of the Francona Charitable Trust until its renovation just over a year ago.","vi":"Được xây dựng vào năm 1897, nơi đây từng là trụ sở của quỹ từ thiện Francona Charitable Trust cho đến khi được cải tạo cách đây chỉ hơn một năm."},{"en":"Today, the space can accommodate up to 200 guests and is ideal for wedding receptions, office parties, and panel presentations.","vi":"Ngày nay, không gian này có sức chứa lên đến 200 khách và rất lý tưởng cho các buổi tiệc cưới, tiệc công ty và các buổi thuyết trình chuyên đề."},{"en":"With its marble floors, cathedral ceiling, and stunning artwork, the Bryant Foyer is the ideal location for your next gathering.","vi":"Với sàn đá cẩm thạch, trần vòm cao và các tác phẩm nghệ thuật ấn tượng, Bryant Foyer là địa điểm lý tưởng cho buổi họp mặt tiếp theo của bạn."}]},{"speaker":"","en":"The on-site restaurant, Andito's, caters our events and also operates as its own business. This farm-to-table restaurant, headed by chef Michaela Rymond, meets all dietary needs and has revolutionized the local food scene. Area residents know to plan far in advance to get a seat.","vi":"Nhà hàng trong khuôn viên, Andito's, phục vụ ẩm thực cho các sự kiện của chúng tôi đồng thời hoạt động như một cơ sở kinh doanh độc lập. Nhà hàng theo mô hình từ nông trại đến bàn ăn này, do bếp trưởng Michaela Rymond đứng đầu, đáp ứng mọi nhu cầu về chế độ ăn uống và đã tạo nên cuộc cách mạng cho nền ẩm thực địa phương. Cư dân trong khu vực đều biết cần lên kế hoạch từ rất sớm để có được chỗ ngồi.","units":[{"en":"The on-site restaurant, Andito's, caters our events and also operates as its own business.","vi":"Nhà hàng trong khuôn viên, Andito's, phục vụ ẩm thực cho các sự kiện của chúng tôi đồng thời hoạt động như một cơ sở kinh doanh độc lập."},{"en":"This farm-to-table restaurant, headed by chef Michaela Rymond, meets all dietary needs and has revolutionized the local food scene.","vi":"Nhà hàng theo mô hình từ nông trại đến bàn ăn này, do bếp trưởng Michaela Rymond đứng đầu, đáp ứng mọi nhu cầu về chế độ ăn uống và đã tạo nên cuộc cách mạng cho nền ẩm thực địa phương."},{"en":"Area residents know to plan far in advance to get a seat.","vi":"Cư dân trong khu vực đều biết cần lên kế hoạch từ rất sớm để có được chỗ ngồi."}]},{"speaker":"","en":"To reserve the event space or to make a dinner reservation, give us a call at 216-555-0157.","vi":"Để đặt thuê không gian tổ chức sự kiện hoặc đặt bàn ăn tối, vui lòng gọi cho chúng tôi theo số 216-555-0157.","units":[{"en":"To reserve the event space or to make a dinner reservation, give us a call at 216-555-0157.","vi":"Để đặt thuê không gian tổ chức sự kiện hoặc đặt bàn ăn tối, vui lòng gọi cho chúng tôi theo số 216-555-0157."}]}],"vocab":[{"word":"on-site","pos":"adj","ipa":"/ˌɑːnˈsaɪt/","meaning":"tại chỗ, trong khuôn viên"},{"word":"cater","pos":"v","ipa":"/ˈkeɪtər/","meaning":"phục vụ ăn uống (cho sự kiện)"},{"word":"dietary","pos":"adj","ipa":"/ˈdaɪəteri/","meaning":"thuộc chế độ ăn uống"},{"word":"revolutionize","pos":"v","ipa":"/ˌrevəˈluːʃənaɪz/","meaning":"tạo nên cuộc cách mạng, đổi mới hoàn toàn"}],"isScanBacked":false,"docTypeLabel":"advertisement","context":"Advertisement for The Bryant Foyer event space and Andito's restaurant","grammarType":"Part 7 — Suy luận & Hàm ý văn bản (Inference & Implied Meaning)","formula":"CÔNG THỨC PART 7 (Quảng cáo nhà hàng — Suy luận mức độ đông khách): Gặp dấu hiệu hành vi \"Area residents know to plan far in advance to get a seat\" (cư dân phải đặt bàn từ rất sớm mới có chỗ) + \"revolutionized the local food scene\" -> Suy ra nhà hàng rất được dân địa phương ưa chuộng (\"very popular with local residents\").","optionAnalysis":{"A":"Suy diễn ngoài văn bản: Bếp trưởng Michaela Rymond được nhắc đến với vai trò điều hành (\"headed by\"), không có thông tin bà là \"international chef\" hay người sáng lập.","B":"Ngược nghĩa với bài đọc: Quảng cáo khẳng định nhà hàng \"meets all dietary needs\" (đáp ứng mọi nhu cầu ăn uống), hoàn toàn không phải thực đơn hạn chế.","C":"Bẫy đánh tráo đối tượng: Quỹ từ thiện \"Francona Charitable Trust\" gắn với lịch sử tòa nhà trước năm ngoái, còn nhà hàng Andito's hoạt động như một doanh nghiệp độc lập (\"operates as its own business\").","D":"Chính xác! Chi tiết \"Area residents know to plan far in advance to get a seat\" (dân địa phương biết phải đặt trước từ rất lâu mới có chỗ) chứng minh độ nổi tiếng và được ưa chuộng cao."},"evDocIdx":0,"evTargets":[{"badge":"Câu 152 · Đáp án D","opt":"D","isCorrect":true,"quote":"This farm-to-table restaurant, headed by chef Michaela Rymond, meets all dietary needs and has revolutionized the local food scene.","viQuote":"Nhà hàng theo mô hình từ nông trại đến bàn ăn này, do bếp trưởng Michaela Rymond đứng đầu, đáp ứng mọi nhu cầu về chế độ ăn uống và đã tạo nên cuộc cách mạng cho nền ẩm thực địa phương."},{"badge":"Câu 152 · Đáp án D","opt":"D","isCorrect":true,"quote":"Area residents know to plan far in advance to get a seat.","viQuote":"Cư dân trong khu vực đều biết cần lên kế hoạch từ rất sớm để có được chỗ ngồi."}],"evQuotes":["This farm-to-table restaurant, headed by chef Michaela Rymond, meets all dietary needs and has revolutionized the local food scene.","Area residents know to plan far in advance to get a seat."]},{"q":153,"part":7,"group_id":"E25_T01_G153_154","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc11.webp"],"stem_en":"At 1:00 P.M., what does Ms. Chi most likely mean when she writes, \"Sure thing, Mina\"?","stem_vi":"Lúc 1:00 chiều, cô Chi có khả năng muốn nói gì nhất khi viết \"Sure thing, Mina\"?","options":{"A":{"en":"She will bring lunch for Ms. Evers.","vi":"Cô ấy sẽ mang bữa trưa về cho cô Evers."},"B":{"en":"She can provide a tool that Ms. Evers needs.","vi":"Cô ấy có thể cung cấp một dụng cụ mà cô Evers cần."},"C":{"en":"Some site coordinates are correct.","vi":"Một số tọa độ địa điểm là chính xác."},"D":{"en":"Some measurements must be double-checked.","vi":"Một số số liệu đo đạc cần được kiểm tra lại."}},"ans":"A","evidence_quote":"- I'm afraid you and Ms. Lim will have to go to lunch without me today. - Should we bring something back for you? - Get me a chicken sandwich. - Sure thing, Mina.","explanation":"Đáp án đúng: (A) Cô ấy sẽ mang bữa trưa về cho cô Evers — Câu \"Sure thing, Mina.\" lúc 1:00 P.M. là lời xác nhận đồng ý ngay sau yêu cầu gọi món ăn trưa \"Get me a chicken sandwich.\" của Mina Evers (lúc 12:59 P.M.) và lời đề nghị mang đồ ăn về trước đó của Joan.\nDẫn chứng: \"Joan Chi (12:51 P.M.): Should we bring something back for you?\" và \"Mina Evers (12:59 P.M.): Get me a chicken sandwich.\" rồi \"Joan Chi (1:00 P.M.): Sure thing, Mina.\" (Chúng tôi có cần mang gì về cho bạn không? - Lấy giúp tôi bánh mì kẹp thịt gà. - Chắc chắn rồi, Mina).\nPhân tích bẫy:\n- (B) Bẫy nhầm ngữ cảnh công việc: Không có tin nhắn nào nhắc đến dụng cụ (\"a tool\"); yêu cầu ngay trước đó là mua bánh mì kẹp thịt gà cho bữa trưa.\n- (C) Ngược nội dung tin nhắn: Lúc 12:40 P.M., Mina báo tọa độ địa điểm đang gặp trục trặc (\"There's a problem with the site coordinates\"), không phải tọa độ đúng, và Joan cũng không bàn về tọa độ lúc 1:00 P.M.\n- (D) Bẫy lặp từ \"measurements\": Joan hỏi thăm việc đo đạc thực địa (\"field measurements\") lúc 12:39 P.M. nhưng câu \"Sure thing\" không liên quan đến việc kiểm tra lại số đo.","lines":[{"speaker":"Joan Chi (12:39 P.M.)","en":"Hello Mina. Are you almost finished with the field measurements? I'm getting hungry.","vi":"Chào Mina. Bạn sắp hoàn thành việc đo đạc ngoài thực địa chưa? Tôi bắt đầu thấy đói rồi.","units":[{"en":"Hello Mina.","vi":"Chào Mina."},{"en":"Are you almost finished with the field measurements?","vi":"Bạn sắp hoàn thành việc đo đạc ngoài thực địa chưa?"},{"en":"I'm getting hungry.","vi":"Tôi bắt đầu thấy đói rồi."}]},{"speaker":"Mina Evers (12:40 P.M.)","en":"Sorry, Joan. I'm afraid you and Ms. Lim will have to go to lunch without me today. There's a problem with the site coordinates. This is going to take some time.","vi":"Xin lỗi nhé, Joan. Rất tiếc là hôm nay bạn và cô Lim sẽ phải đi ăn trưa mà không có tôi rồi. Tọa độ địa điểm đang có vấn đề. Việc này sẽ mất khá nhiều thời gian đấy.","units":[{"en":"Sorry, Joan.","vi":"Xin lỗi nhé, Joan."},{"en":"I'm afraid you and Ms. Lim will have to go to lunch without me today.","vi":"Rất tiếc là hôm nay bạn và cô Lim sẽ phải đi ăn trưa mà không có tôi rồi."},{"en":"There's a problem with the site coordinates.","vi":"Tọa độ địa điểm đang có vấn đề."},{"en":"This is going to take some time.","vi":"Việc này sẽ mất khá nhiều thời gian đấy."}]},{"speaker":"Joan Chi (12:51 P.M.)","en":"Oh no. Should we bring something back for you?","vi":"Ôi tiếc quá. Chúng tôi có cần mang gì về cho bạn không?","units":[{"en":"Oh no.","vi":"Ôi tiếc quá."},{"en":"Should we bring something back for you?","vi":"Chúng tôi có cần mang gì về cho bạn không?"}]},{"speaker":"Mina Evers (12:59 P.M.)","en":"Get me a chicken sandwich.","vi":"Lấy giúp tôi một phần bánh mì kẹp thịt gà nhé.","units":[{"en":"Get me a chicken sandwich.","vi":"Lấy giúp tôi một phần bánh mì kẹp thịt gà nhé."}]},{"speaker":"Joan Chi (1:00 P.M.)","en":"Sure thing, Mina. See you in a while.","vi":"Chắc chắn rồi, Mina. Lát nữa gặp lại bạn nhé.","units":[{"en":"Sure thing, Mina.","vi":"Chắc chắn rồi, Mina."},{"en":"See you in a while.","vi":"Lát nữa gặp lại bạn nhé."}]}],"vocab":[{"word":"field measurement","pos":"phr","ipa":"/fiːld ˈmeʒərmənt/","meaning":"phép đo đạc ngoài thực địa"},{"word":"coordinates","pos":"n","ipa":"/koʊˈɔːrdɪnəts/","meaning":"tọa độ (vị trí địa lý)"},{"word":"sure thing","pos":"phr","ipa":"/ʃʊr θɪŋ/","meaning":"chắc chắn rồi, đồng ý ngay"}],"isScanBacked":false,"docTypeLabel":"text-message chain","context":"Text-message chain between Joan Chi and Mina Evers about lunch and field measurements","grammarType":"Part 7 — Suy luận & Hàm ý văn bản (Inference & Implied Meaning)","formula":"CÔNG THỨC PART 7 (Tin nhắn chat — Giải mã câu nói trong ngoặc kép): Luôn đọc 2 tin nhắn liền trước câu trích! Joan hỏi \"Should we bring something back for you?\" -> Mina đáp \"Get me a chicken sandwich.\" -> Joan chốt \"Sure thing, Mina\" = đồng ý mua/mang bữa trưa về cho Mina.","optionAnalysis":{"A":"Chính xác! Đọc liền mạch 3 lượt nhắn (12:51 -> 12:59 -> 1:00 P.M.), \"Sure thing, Mina\" là lời đồng ý mua và mang về chiếc bánh mì kẹp gà (\"chicken sandwich\") cho bữa trưa của cô Evers.","B":"Bẫy đánh tráo nội dung: Cô Evers nhờ mua đồ ăn trưa (\"chicken sandwich\"), hoàn toàn không hỏi mượn hay yêu cầu cung cấp dụng cụ làm việc nào.","C":"Ngược sự thật và sai mạch hội thoại: Cô Evers nói tọa độ địa điểm có vấn đề (\"problem with the site coordinates\"), còn câu lúc 1:00 P.M. chỉ phản hồi việc mua bánh mì.","D":"Bẫy lặp từ khóa \"measurements\": Từ này xuất hiện ở tin nhắn mở đầu lúc 12:39 P.M., nhưng không có chi tiết nào bảo phải kiểm tra lại số đo."},"evDocIdx":0,"evTargets":[{"badge":"Câu 153 · Đáp án A","opt":"A","isCorrect":true,"quote":"Should we bring something back for you?","viQuote":"Chúng tôi có cần mang gì về cho bạn không?"},{"badge":"Câu 153 · Đáp án A","opt":"A","isCorrect":true,"quote":"Get me a chicken sandwich.","viQuote":"Lấy giúp tôi một phần bánh mì kẹp thịt gà nhé."},{"badge":"Câu 153 · Đáp án A","opt":"A","isCorrect":true,"quote":"Sure thing, Mina.","viQuote":"Chắc chắn rồi, Mina."}],"evQuotes":["Should we bring something back for you?","Get me a chicken sandwich.","Sure thing, Mina."]},{"q":154,"part":7,"group_id":"E25_T01_G153_154","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc11.webp"],"stem_en":"What will happen next?","stem_vi":"Điều gì sẽ xảy ra tiếp theo?","options":{"A":{"en":"Ms. Chi will get new site coordinates.","vi":"Cô Chi sẽ lấy các tọa độ địa điểm mới."},"B":{"en":"Ms. Chi and Ms. Lim will be out for a while.","vi":"Cô Chi và cô Lim sẽ ra ngoài một lát."},"C":{"en":"Ms. Evers will share a recipe.","vi":"Cô Evers sẽ chia sẻ một công thức nấu ăn."},"D":{"en":"Ms. Lim will begin taking measurements.","vi":"Cô Lim sẽ bắt đầu tiến hành đo đạc."}},"ans":"B","evidence_quote":"- I'm afraid you and Ms. Lim will have to go to lunch without me today. - See you in a while.","explanation":"Đáp án đúng: (B) Cô Chi và cô Lim sẽ ra ngoài một lát — Mina nhắn rằng cô Chi và cô Lim phải đi ăn trưa mà không có mình, sau đó cô Chi đồng ý mang bánh mì gà về cho Mina và chào tạm biệt \"See you in a while.\" (Lát nữa gặp lại nhé), cho thấy cả hai người sẽ ra ngoài đi ăn trưa.\nDẫn chứng: \"I'm afraid you and Ms. Lim will have to go to lunch without me today.\" kết hợp câu cuối \"Sure thing, Mina. See you in a while.\" (Rất tiếc hôm nay bạn và cô Lim sẽ phải đi ăn trưa mà không có tôi rồi. - Chắc chắn rồi, Mina. Lát nữa gặp lại bạn nhé).\nPhân tích bẫy:\n- (A) Sai người phụ trách: Mina Evers mới là người ở lại xử lý sự cố tọa độ (\"There's a problem with the site coordinates. This is going to take some time\"), không phải cô Chi đi lấy tọa độ mới.\n- (C) Bẫy liên tưởng từ \"chicken sandwich\": Có nhắc món bánh mì gà để mua ăn trưa, nhưng không ai bàn đến công thức nấu ăn (\"recipe\").\n- (D) Sai nhân vật thực hiện: Mina Evers đang làm dở việc đo đạc thực địa và tiếp tục ở lại xử lý tọa độ, còn cô Lim sẽ đi ăn trưa cùng cô Chi.","lines":[{"speaker":"Joan Chi (12:39 P.M.)","en":"Hello Mina. Are you almost finished with the field measurements? I'm getting hungry.","vi":"Chào Mina. Bạn sắp hoàn thành việc đo đạc ngoài thực địa chưa? Tôi bắt đầu thấy đói rồi.","units":[{"en":"Hello Mina.","vi":"Chào Mina."},{"en":"Are you almost finished with the field measurements?","vi":"Bạn sắp hoàn thành việc đo đạc ngoài thực địa chưa?"},{"en":"I'm getting hungry.","vi":"Tôi bắt đầu thấy đói rồi."}]},{"speaker":"Mina Evers (12:40 P.M.)","en":"Sorry, Joan. I'm afraid you and Ms. Lim will have to go to lunch without me today. There's a problem with the site coordinates. This is going to take some time.","vi":"Xin lỗi nhé, Joan. Rất tiếc là hôm nay bạn và cô Lim sẽ phải đi ăn trưa mà không có tôi rồi. Tọa độ địa điểm đang có vấn đề. Việc này sẽ mất khá nhiều thời gian đấy.","units":[{"en":"Sorry, Joan.","vi":"Xin lỗi nhé, Joan."},{"en":"I'm afraid you and Ms. Lim will have to go to lunch without me today.","vi":"Rất tiếc là hôm nay bạn và cô Lim sẽ phải đi ăn trưa mà không có tôi rồi."},{"en":"There's a problem with the site coordinates.","vi":"Tọa độ địa điểm đang có vấn đề."},{"en":"This is going to take some time.","vi":"Việc này sẽ mất khá nhiều thời gian đấy."}]},{"speaker":"Joan Chi (12:51 P.M.)","en":"Oh no. Should we bring something back for you?","vi":"Ôi tiếc quá. Chúng tôi có cần mang gì về cho bạn không?","units":[{"en":"Oh no.","vi":"Ôi tiếc quá."},{"en":"Should we bring something back for you?","vi":"Chúng tôi có cần mang gì về cho bạn không?"}]},{"speaker":"Mina Evers (12:59 P.M.)","en":"Get me a chicken sandwich.","vi":"Lấy giúp tôi một phần bánh mì kẹp thịt gà nhé.","units":[{"en":"Get me a chicken sandwich.","vi":"Lấy giúp tôi một phần bánh mì kẹp thịt gà nhé."}]},{"speaker":"Joan Chi (1:00 P.M.)","en":"Sure thing, Mina. See you in a while.","vi":"Chắc chắn rồi, Mina. Lát nữa gặp lại bạn nhé.","units":[{"en":"Sure thing, Mina.","vi":"Chắc chắn rồi, Mina."},{"en":"See you in a while.","vi":"Lát nữa gặp lại bạn nhé."}]}],"vocab":[{"word":"in a while","pos":"phr","ipa":"/ɪn ə waɪl/","meaning":"sau một lát nữa, một chốc nữa"},{"word":"take some time","pos":"phr","ipa":"/teɪk sʌm taɪm/","meaning":"mất khá nhiều thời gian"},{"word":"double-check","pos":"v","ipa":"/ˌdʌbəlˈtʃek/","meaning":"kiểm tra lại cho chắc chắn"}],"isScanBacked":false,"docTypeLabel":"text-message chain","context":"Text-message chain between Joan Chi and Mina Evers about lunch and field measurements","grammarType":"Part 7 — Suy luận & Hàm ý văn bản (Inference & Implied Meaning)","formula":"CÔNG THỨC PART 7 (Tin nhắn chat — Dự đoán hành động tiếp theo): Kết hợp lời nhường đi ăn trưa (\"you and Ms. Lim will have to go to lunch without me\") + lời tạm biệt cuối (\"See you in a while.\") -> Suy ra cô Chi và cô Lim sẽ ra ngoài đi ăn trưa một lúc.","optionAnalysis":{"A":"Đổi vai nhân vật: Người đang làm việc với tọa độ gặp lỗi là cô Evers, còn cô Chi chuẩn bị đi ăn trưa cùng cô Lim.","B":"Chính xác! Cụm \"go to lunch without me\" kết hợp với lời chào \"See you in a while\" chứng tỏ cô Chi và cô Lim sẽ đi ra ngoài ăn trưa một khoảng thời gian rồi quay lại.","C":"Bẫy liên tưởng thực phẩm: Hội thoại có nhắc \"chicken sandwich\" nhưng là để mua sẵn mang về, hoàn toàn không có chuyện chia sẻ công thức nấu ăn (\"recipe\").","D":"Sai người thực hiện: Cô Lim đi ăn trưa với cô Chi (\"you and Ms. Lim will have to go to lunch\"), không phải người bắt đầu tiến hành đo đạc."},"evDocIdx":0,"evTargets":[{"badge":"Câu 154 · Đáp án B","opt":"B","isCorrect":true,"quote":"I'm afraid you and Ms. Lim will have to go to lunch without me today.","viQuote":"Rất tiếc là hôm nay bạn và cô Lim sẽ phải đi ăn trưa mà không có tôi rồi."},{"badge":"Câu 154 · Đáp án B","opt":"B","isCorrect":true,"quote":"See you in a while.","viQuote":"Lát nữa gặp lại bạn nhé."}],"evQuotes":["I'm afraid you and Ms. Lim will have to go to lunch without me today.","See you in a while."]},{"q":155,"part":7,"group_id":"E25_T01_G155_157","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc12.webp"],"stem_en":"For whom is the notice most likely intended?","stem_vi":"Thông báo này có khả năng dành cho đối tượng nào nhất?","options":{"A":{"en":"Farmers","vi":"Nông dân"},"B":{"en":"Professional chefs","vi":"Đầu bếp chuyên nghiệp"},"C":{"en":"Truck drivers","vi":"Tài xế xe tải"},"D":{"en":"Supermarket managers","vi":"Quản lý siêu thị"}},"ans":"A","evidence_quote":"- This season's excellent weather has yielded a substantial harvest of fruits and vegetables - Those of you wishing to donate surplus produce to community organizations can do so by visiting Vosey Farm and Garden's Web site ( www.vfgrdn.org), where you will find our list of drop-off locations.","explanation":"Đáp án đúng: (A) Nông dân — Thông báo nhắm đến những người trồng trọt (\"growers\") đang có vụ thu hoạch bội thu vượt mức tiêu thụ (\"more than growers may find buyers for\") và muốn quyên góp nông sản dư thừa (\"surplus produce\"), tức là các nông dân.\nDẫn chứng: \"This season's excellent weather has yielded a substantial harvest of fruits and vegetables, in many cases more than growers may find buyers for. Those of you wishing to donate surplus produce to community organizations can do so by visiting Vosey Farm and Garden's Web site (www.vfgrdn.org), where you will find our list of drop-off locations.\" (Vụ thu hoạch lớn vượt lượng người trồng tìm được người mua; những ai trong quý vị muốn quyên góp nông sản dư thừa có thể truy cập trang web để xem điểm tiếp nhận).\nPhân tích bẫy:\n- (B) Bẫy liên tưởng thực phẩm: Bài nhắc đến \"fruits and vegetables\" và \"food donations\", nhưng không đề cập đến nhà hàng, bếp ăn hay đầu bếp chuyên nghiệp (\"Professional chefs\").\n- (C) Bẫy từ khóa xuất hiện trong bài: \"independent truck drivers\" được nhắc ở đoạn 2 với vai trò là lực lượng tình nguyện viên chở hàng được tổ chức liên hệ hỗ trợ (\"We will reach out to one of the many independent truck drivers\"), không phải đối tượng \"you\" đang có nông sản dư cần quyên góp.\n- (D) Bẫy suy diễn từ \"buyers\": Người trồng không tìm đủ người mua hàng (\"find buyers\"), nhưng thông báo hướng dẫn trực tiếp người trồng (\"growers\") cách đem cho nông sản chứ không viết cho quản lý siêu thị.","lines":[{"speaker":"Document 1 — Notice","en":"This season's excellent weather has yielded a substantial harvest of fruits and vegetables, in many cases more than growers may find buyers for. Those of you wishing to donate surplus produce to community organizations can do so by visiting Vosey Farm and Garden's Web site (www.vfgrdn.org), where you will find our list of drop-off locations.","vi":"Thời tiết tuyệt vời mùa này đã mang lại vụ thu hoạch trái cây và rau củ dồi dào, trong nhiều trường hợp vượt quá lượng mà người trồng có thể tìm được người mua. Những ai mong muốn quyên góp nông sản dư thừa cho các tổ chức cộng đồng có thể thực hiện bằng cách truy cập trang web của Vosey Farm and Garden (www.vfgrdn.org), nơi bạn sẽ tìm thấy danh sách các điểm tiếp nhận của chúng tôi.","units":[{"en":"This season's excellent weather has yielded a substantial harvest of fruits and vegetables, in many cases more than growers may find buyers for.","vi":"Thời tiết tuyệt vời mùa này đã mang lại vụ thu hoạch trái cây và rau củ dồi dào, trong nhiều trường hợp vượt quá lượng mà người trồng có thể tìm được người mua."},{"en":"Those of you wishing to donate surplus produce to community organizations can do so by visiting Vosey Farm and Garden's Web site (www.vfgrdn.org), where you will find our list of drop-off locations.","vi":"Những ai mong muốn quyên góp nông sản dư thừa cho các tổ chức cộng đồng có thể thực hiện bằng cách truy cập trang web của Vosey Farm and Garden (www.vfgrdn.org), nơi bạn sẽ tìm thấy danh sách các điểm tiếp nhận của chúng tôi."}]},{"speaker":"","en":"If you need us to come to you instead, please contact us. We will reach out to one of the many independent truck drivers who have kindly volunteered to transport and quickly distribute your food donations to vetted groups that need it. Check our Web site for more information about this service as well as for insights into topics related to farming and gardening in the Northern Great Plains region.","vi":"Nếu thay vào đó bạn cần chúng tôi đến tận nơi, vui lòng liên hệ với chúng tôi. Chúng tôi sẽ liên hệ với một trong số rất nhiều tài xế xe tải độc lập đã sẵn lòng tình nguyện vận chuyển và phân phối nhanh chóng lượng thực phẩm quyên góp của bạn đến các tổ chức đã được thẩm định đang có nhu cầu. Hãy xem trang web của chúng tôi để biết thêm thông tin về dịch vụ này cũng như những kiến thức chuyên sâu về các chủ đề liên quan đến nông nghiệp và làm vườn tại khu vực Northern Great Plains.","units":[{"en":"If you need us to come to you instead, please contact us.","vi":"Nếu thay vào đó bạn cần chúng tôi đến tận nơi, vui lòng liên hệ với chúng tôi."},{"en":"We will reach out to one of the many independent truck drivers who have kindly volunteered to transport and quickly distribute your food donations to vetted groups that need it.","vi":"Chúng tôi sẽ liên hệ với một trong số rất nhiều tài xế xe tải độc lập đã sẵn lòng tình nguyện vận chuyển và phân phối nhanh chóng lượng thực phẩm quyên góp của bạn đến các tổ chức đã được thẩm định đang có nhu cầu."},{"en":"Check our Web site for more information about this service as well as for insights into topics related to farming and gardening in the Northern Great Plains region.","vi":"Hãy xem trang web của chúng tôi để biết thêm thông tin về dịch vụ này cũng như những kiến thức chuyên sâu về các chủ đề liên quan đến nông nghiệp và làm vườn tại khu vực Northern Great Plains."}]}],"vocab":[{"word":"yield","pos":"v","ipa":"/jiːld/","meaning":"mang lại, tạo ra (sản lượng, mùa màng)"},{"word":"substantial","pos":"adj","ipa":"/səbˈstænʃəl/","meaning":"đáng kể, dồi dào"},{"word":"surplus","pos":"adj","ipa":"/ˈsɜːrpləs/","meaning":"dư thừa, thặng dư"},{"word":"produce","pos":"n","ipa":"/ˈprɑːduːs/","meaning":"nông sản tươi (rau, củ, quả)"}],"isScanBacked":false,"docTypeLabel":"notice","context":"Notice from Vosey Farm and Garden about donating surplus produce","grammarType":"Part 7 — Ý chính, Mục đích & Đối tượng đọc (Main Idea & Purpose)","formula":"CÔNG THỨC PART 7 (Thông báo — Xác định đối tượng độc giả qua từ chỉ nghề nghiệp): Gặp nhóm từ \"growers\", \"surplus produce\", \"harvest of fruits and vegetables\" gắn trực tiếp với đối tượng \"Those of you wishing to donate\" -> Độc giả mục tiêu là nông dân (\"Farmers\").","optionAnalysis":{"A":"Chính xác! Cụm \"growers\" (người trồng trọt) kết hợp với \"harvest of fruits and vegetables\" và lời kêu gọi \"Those of you wishing to donate surplus produce\" cho thấy người nhận thông báo là nông dân.","B":"Bẫy chủ đề thực phẩm: Văn bản nói về thu hoạch và quyên góp rau củ quả từ vườn/trang trại, không hề đề cập đến việc chế biến món ăn hay đầu bếp chuyên nghiệp.","C":"Bẫy nhắc tên trong bài: Tài xế xe tải (\"truck drivers\") là nhóm tình nguyện viên bên thứ ba được tổ chức nhờ chở hàng giúp (\"We will reach out to\"), không phải người trồng cây có nông sản thừa.","D":"Suy diễn ngoài ngữ cảnh: Dù bài có nhắc việc tìm người mua (\"buyers\"), thông báo không nhắm tới quản lý siêu thị mà kêu gọi người sản xuất quyên tặng nông sản dư."},"evDocIdx":0,"evTargets":[{"badge":"Câu 155 · Đáp án A","opt":"A","isCorrect":true,"quote":"This season's excellent weather has yielded a substantial harvest of fruits and vegetables, in many cases more than growers may find buyers for.","viQuote":"Thời tiết tuyệt vời mùa này đã mang lại vụ thu hoạch trái cây và rau củ dồi dào, trong nhiều trường hợp vượt quá lượng mà người trồng có thể tìm được người mua."},{"badge":"Câu 155 · Đáp án A","opt":"A","isCorrect":true,"quote":"Those of you wishing to donate surplus produce to community organizations can do so by visiting Vosey Farm and Garden's Web site (www.vfgrdn.org), where you will find our list of drop-off locations.","viQuote":"Những ai mong muốn quyên góp nông sản dư thừa cho các tổ chức cộng đồng có thể thực hiện bằng cách truy cập trang web của Vosey Farm and Garden (www.vfgrdn.org), nơi bạn sẽ tìm thấy danh sách các điểm tiếp nhận của chúng tôi."}],"evQuotes":["This season's excellent weather has yielded a substantial harvest of fruits and vegetables, in many cases more than growers may find buyers for.","Those of you wishing to donate surplus produce to community organizations can do so by visiting Vosey Farm and Garden's Web site (www.vfgrdn.org), where you will find our list of drop-off locations."]},{"q":156,"part":7,"group_id":"E25_T01_G155_157","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc12.webp"],"stem_en":"What does the notice indicate about the weather?","stem_vi":"Thông báo nêu điều gì về thời tiết?","options":{"A":{"en":"It caused transportation delays.","vi":"Thời tiết đã gây ra tình trạng chậm trễ vận chuyển."},"B":{"en":"It included heavier rain than usual.","vi":"Thời tiết có lượng mưa lớn hơn bình thường."},"C":{"en":"It was frequently a topic in the local news.","vi":"Thời tiết thường xuyên là chủ đề trên tin tức địa phương."},"D":{"en":"It was beneficial for crops.","vi":"Thời tiết có lợi cho mùa màng."}},"ans":"D","evidence_quote":"This season's excellent weather has yielded a substantial harvest of fruits and vegetables","explanation":"Đáp án đúng: (D) Thời tiết có lợi cho mùa màng — Câu đầu tiên nêu rõ thời tiết tuyệt vời của mùa này đã mang lại một vụ thu hoạch rau quả dồi dào (\"excellent weather has yielded a substantial harvest of fruits and vegetables\"), đồng nghĩa với việc thời tiết thuận lợi cho cây trồng.\nDẫn chứng: \"This season's excellent weather has yielded a substantial harvest of fruits and vegetables, in many cases more than growers may find buyers for.\" (Thời tiết tuyệt vời mùa này đã mang lại vụ thu hoạch trái cây và rau củ dồi dào).\nPhân tích bẫy:\n- (A) Ngược ngữ cảnh: Thời tiết được khen là \"excellent\" (tuyệt vời), và việc vận chuyển cũng được mô tả là nhanh chóng (\"quickly distribute\"), hoàn toàn không có sự chậm trễ do thời tiết.\n- (B) Chi tiết bịa đặt: Văn bản chỉ đánh giá chung là thời tiết tuyệt vời (\"excellent weather\"), không hề đề cập đến lượng mưa (\"heavier rain\") hay yếu tố khí hậu cụ thể nào.\n- (C) Suy diễn ngoài bài: Không có thông tin nào nói thời tiết hay vụ mùa này được đưa tin thường xuyên trên báo đài địa phương (\"local news\").","lines":[{"speaker":"Document 1 — Notice","en":"This season's excellent weather has yielded a substantial harvest of fruits and vegetables, in many cases more than growers may find buyers for. Those of you wishing to donate surplus produce to community organizations can do so by visiting Vosey Farm and Garden's Web site (www.vfgrdn.org), where you will find our list of drop-off locations.","vi":"Thời tiết tuyệt vời mùa này đã mang lại vụ thu hoạch trái cây và rau củ dồi dào, trong nhiều trường hợp vượt quá lượng mà người trồng có thể tìm được người mua. Những ai mong muốn quyên góp nông sản dư thừa cho các tổ chức cộng đồng có thể thực hiện bằng cách truy cập trang web của Vosey Farm and Garden (www.vfgrdn.org), nơi bạn sẽ tìm thấy danh sách các điểm tiếp nhận của chúng tôi.","units":[{"en":"This season's excellent weather has yielded a substantial harvest of fruits and vegetables, in many cases more than growers may find buyers for.","vi":"Thời tiết tuyệt vời mùa này đã mang lại vụ thu hoạch trái cây và rau củ dồi dào, trong nhiều trường hợp vượt quá lượng mà người trồng có thể tìm được người mua."},{"en":"Those of you wishing to donate surplus produce to community organizations can do so by visiting Vosey Farm and Garden's Web site (www.vfgrdn.org), where you will find our list of drop-off locations.","vi":"Những ai mong muốn quyên góp nông sản dư thừa cho các tổ chức cộng đồng có thể thực hiện bằng cách truy cập trang web của Vosey Farm and Garden (www.vfgrdn.org), nơi bạn sẽ tìm thấy danh sách các điểm tiếp nhận của chúng tôi."}]},{"speaker":"","en":"If you need us to come to you instead, please contact us. We will reach out to one of the many independent truck drivers who have kindly volunteered to transport and quickly distribute your food donations to vetted groups that need it. Check our Web site for more information about this service as well as for insights into topics related to farming and gardening in the Northern Great Plains region.","vi":"Nếu thay vào đó bạn cần chúng tôi đến tận nơi, vui lòng liên hệ với chúng tôi. Chúng tôi sẽ liên hệ với một trong số rất nhiều tài xế xe tải độc lập đã sẵn lòng tình nguyện vận chuyển và phân phối nhanh chóng lượng thực phẩm quyên góp của bạn đến các tổ chức đã được thẩm định đang có nhu cầu. Hãy xem trang web của chúng tôi để biết thêm thông tin về dịch vụ này cũng như những kiến thức chuyên sâu về các chủ đề liên quan đến nông nghiệp và làm vườn tại khu vực Northern Great Plains.","units":[{"en":"If you need us to come to you instead, please contact us.","vi":"Nếu thay vào đó bạn cần chúng tôi đến tận nơi, vui lòng liên hệ với chúng tôi."},{"en":"We will reach out to one of the many independent truck drivers who have kindly volunteered to transport and quickly distribute your food donations to vetted groups that need it.","vi":"Chúng tôi sẽ liên hệ với một trong số rất nhiều tài xế xe tải độc lập đã sẵn lòng tình nguyện vận chuyển và phân phối nhanh chóng lượng thực phẩm quyên góp của bạn đến các tổ chức đã được thẩm định đang có nhu cầu."},{"en":"Check our Web site for more information about this service as well as for insights into topics related to farming and gardening in the Northern Great Plains region.","vi":"Hãy xem trang web của chúng tôi để biết thêm thông tin về dịch vụ này cũng như những kiến thức chuyên sâu về các chủ đề liên quan đến nông nghiệp và làm vườn tại khu vực Northern Great Plains."}]}],"vocab":[{"word":"harvest","pos":"n","ipa":"/ˈhɑːrvɪst/","meaning":"vụ thu hoạch, mùa gặt"},{"word":"grower","pos":"n","ipa":"/ˈɡroʊər/","meaning":"người trồng trọt, nhà nông"},{"word":"crop","pos":"n","ipa":"/krɑːp/","meaning":"cây trồng, mùa màng"}],"isScanBacked":false,"docTypeLabel":"notice","context":"Notice from Vosey Farm and Garden about donating surplus produce","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 (Thông báo — Paraphrase quan hệ nhân quả): Gặp cụm nguyên nhân-kết quả \"excellent weather has yielded a substantial harvest of fruits and vegetables\" -> Đổi thành tính từ đánh giá tác động tích cực \"beneficial for crops\" (có lợi cho mùa màng).","optionAnalysis":{"A":"Trái ngược hoàn toàn: Bài gọi đây là \"excellent weather\" (thời tiết tuyệt vời) và các tài xế phân phối thực phẩm nhanh chóng (\"quickly distribute\"), không có chuyện chậm trễ giao thông.","B":"Thông tin không có trong bài: Đoạn văn không đề cập đến mưa hay lượng mưa lớn hơn bình thường (\"heavier rain\").","C":"Suy diễn ngoài văn bản: Thông báo không nhắc gì đến tin tức địa phương (\"local news\") hay việc truyền thông bàn luận về thời tiết.","D":"Chính xác! \"excellent weather has yielded a substantial harvest\" (thời tiết tuyệt vời tạo ra vụ mùa bội thu) được diễn đạt lại thành \"beneficial for crops\"."},"evDocIdx":0,"evTargets":[{"badge":"Câu 156 · Đáp án D","opt":"D","isCorrect":true,"quote":"This season's excellent weather has yielded a substantial harvest of fruits and vegetables","viQuote":"Thời tiết tuyệt vời mùa này đã mang lại vụ thu hoạch trái cây và rau củ dồi dào"}],"evQuotes":["This season's excellent weather has yielded a substantial harvest of fruits and vegetables"]},{"q":157,"part":7,"group_id":"E25_T01_G155_157","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc12.webp"],"stem_en":"What service does the notice mention?","stem_vi":"Thông báo đề cập đến dịch vụ nào?","options":{"A":{"en":"Staffing for local businesses","vi":"Cung ứng nhân sự cho các doanh nghiệp địa phương"},"B":{"en":"Food collection and distribution","vi":"Thu gom và phân phối thực phẩm"},"C":{"en":"Farm machinery repair","vi":"Sửa chữa máy móc nông nghiệp"},"D":{"en":"Gardening workshops","vi":"Các buổi hội thảo về làm vườn"}},"ans":"B","evidence_quote":"If you need us to come to you instead, please contact us. We will reach out to one of the many independent truck drivers who have","explanation":"Đáp án đúng: (B) Thu gom và phân phối thực phẩm — Đoạn 2 đề cập đến dịch vụ (\"this service\") trong đó tổ chức cử tài xế tình nguyện đến tận nơi lấy nông sản (\"come to you\", \"transport\") và phân phát nhanh cho các nhóm cần hỗ trợ (\"quickly distribute your food donations\").\nDẫn chứng: \"If you need us to come to you instead, please contact us. We will reach out to one of the many independent truck drivers who have kindly volunteered to transport and quickly distribute your food donations to vetted groups that need it. Check our Web site for more information about this service as well as for insights into topics related to farming and gardening in the Northern Great Plains region.\" (Nếu cần chúng tôi đến tận nơi, hãy liên hệ; chúng tôi sẽ nhờ tài xế vận chuyển và phân phối nhanh thực phẩm quyên góp; xem trang web để biết thêm về dịch vụ này).\nPhân tích bẫy:\n- (A) Sai lĩnh vực hoạt động: Tổ chức kết nối tài xế tình nguyện chở đồ quyên góp cho các hội nhóm cộng đồng, không phải dịch vụ cung ứng nhân sự (\"Staffing\") cho doanh nghiệp địa phương.\n- (C) Bẫy liên tưởng chủ đề nông nghiệp: Dù nội dung nói về trang trại và người trồng trọt, thông báo không đề cập đến máy móc hay dịch vụ sửa chữa máy nông nghiệp (\"Farm machinery repair\").\n- (D) Bẫy biến tấu từ \"gardening\": Trang web chỉ chia sẻ bài viết/kiến thức chuyên sâu (\"insights into topics related to farming and gardening\"), không phải mở các buổi hội thảo thực hành (\"workshops\").","lines":[{"speaker":"Document 1 — Notice","en":"This season's excellent weather has yielded a substantial harvest of fruits and vegetables, in many cases more than growers may find buyers for. Those of you wishing to donate surplus produce to community organizations can do so by visiting Vosey Farm and Garden's Web site (www.vfgrdn.org), where you will find our list of drop-off locations.","vi":"Thời tiết tuyệt vời mùa này đã mang lại vụ thu hoạch trái cây và rau củ dồi dào, trong nhiều trường hợp vượt quá lượng mà người trồng có thể tìm được người mua. Những ai mong muốn quyên góp nông sản dư thừa cho các tổ chức cộng đồng có thể thực hiện bằng cách truy cập trang web của Vosey Farm and Garden (www.vfgrdn.org), nơi bạn sẽ tìm thấy danh sách các điểm tiếp nhận của chúng tôi.","units":[{"en":"This season's excellent weather has yielded a substantial harvest of fruits and vegetables, in many cases more than growers may find buyers for.","vi":"Thời tiết tuyệt vời mùa này đã mang lại vụ thu hoạch trái cây và rau củ dồi dào, trong nhiều trường hợp vượt quá lượng mà người trồng có thể tìm được người mua."},{"en":"Those of you wishing to donate surplus produce to community organizations can do so by visiting Vosey Farm and Garden's Web site (www.vfgrdn.org), where you will find our list of drop-off locations.","vi":"Những ai mong muốn quyên góp nông sản dư thừa cho các tổ chức cộng đồng có thể thực hiện bằng cách truy cập trang web của Vosey Farm and Garden (www.vfgrdn.org), nơi bạn sẽ tìm thấy danh sách các điểm tiếp nhận của chúng tôi."}]},{"speaker":"","en":"If you need us to come to you instead, please contact us. We will reach out to one of the many independent truck drivers who have kindly volunteered to transport and quickly distribute your food donations to vetted groups that need it. Check our Web site for more information about this service as well as for insights into topics related to farming and gardening in the Northern Great Plains region.","vi":"Nếu thay vào đó bạn cần chúng tôi đến tận nơi, vui lòng liên hệ với chúng tôi. Chúng tôi sẽ liên hệ với một trong số rất nhiều tài xế xe tải độc lập đã sẵn lòng tình nguyện vận chuyển và phân phối nhanh chóng lượng thực phẩm quyên góp của bạn đến các tổ chức đã được thẩm định đang có nhu cầu. Hãy xem trang web của chúng tôi để biết thêm thông tin về dịch vụ này cũng như những kiến thức chuyên sâu về các chủ đề liên quan đến nông nghiệp và làm vườn tại khu vực Northern Great Plains.","units":[{"en":"If you need us to come to you instead, please contact us.","vi":"Nếu thay vào đó bạn cần chúng tôi đến tận nơi, vui lòng liên hệ với chúng tôi."},{"en":"We will reach out to one of the many independent truck drivers who have kindly volunteered to transport and quickly distribute your food donations to vetted groups that need it.","vi":"Chúng tôi sẽ liên hệ với một trong số rất nhiều tài xế xe tải độc lập đã sẵn lòng tình nguyện vận chuyển và phân phối nhanh chóng lượng thực phẩm quyên góp của bạn đến các tổ chức đã được thẩm định đang có nhu cầu."},{"en":"Check our Web site for more information about this service as well as for insights into topics related to farming and gardening in the Northern Great Plains region.","vi":"Hãy xem trang web của chúng tôi để biết thêm thông tin về dịch vụ này cũng như những kiến thức chuyên sâu về các chủ đề liên quan đến nông nghiệp và làm vườn tại khu vực Northern Great Plains."}]}],"vocab":[{"word":"distribute","pos":"v","ipa":"/dɪˈstrɪbjuːt/","meaning":"phân phối, phân phát"},{"word":"vetted","pos":"adj","ipa":"/ˈvetɪd/","meaning":"đã được thẩm định, kiểm tra kỹ lưỡng"},{"word":"drop-off location","pos":"phr","ipa":"/ˈdrɑːp ɔːf loʊˈkeɪʃən/","meaning":"điểm tiếp nhận, điểm giao nộp hàng"},{"word":"insight","pos":"n","ipa":"/ˈɪnsaɪt/","meaning":"kiến thức chuyên sâu, góc nhìn sâu sắc"}],"isScanBacked":false,"docTypeLabel":"notice","context":"Notice from Vosey Farm and Garden about donating surplus produce","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 (Thông báo — Đối chiếu cụm \"this service\" với câu liền trước): Khi câu hỏi hỏi \"What service\", tìm cụm \"this service\" ở cuối đoạn 2 và truy ngược lên hành động ngay trước đó (\"come to you\", \"transport and quickly distribute your food donations\").","optionAnalysis":{"A":"Sai mục đích dịch vụ: Tổ chức kêu gọi tài xế tình nguyện vận chuyển thực phẩm từ thiện, không cung cấp nhân sự (\"Staffing\") cho các công ty.","B":"Chính xác! Cụm \"come to you\", \"transport\" và \"quickly distribute your food donations\" được gọi tên lại ở câu sau là \"this service\", khớp hoàn toàn với \"Food collection and distribution\".","C":"Suy diễn ngoài văn bản: Bài viết về nông sản dư thừa nhưng không hề nhắc đến máy móc nông nghiệp hay dịch vụ sửa chữa (\"machinery repair\").","D":"Bẫy ghép từ \"gardening\": Trang web chỉ cung cấp kiến thức tham khảo (\"insights into topics related to farming and gardening\"), không tổ chức lớp học hay hội thảo (\"workshops\")."},"evDocIdx":0,"evTargets":[{"badge":"Câu 157 · Đáp án B","opt":"B","isCorrect":true,"quote":"If you need us to come to you instead, please contact us.","viQuote":"Nếu thay vào đó bạn cần chúng tôi đến tận nơi, vui lòng liên hệ với chúng tôi."},{"badge":"Câu 157 · Đáp án B","opt":"B","isCorrect":true,"quote":"We will reach out to one of the many independent truck drivers who have kindly volunteered to transport and quickly distribute your food donations to vetted groups that need it.","viQuote":"Chúng tôi sẽ liên hệ với một trong số rất nhiều tài xế xe tải độc lập đã sẵn lòng tình nguyện vận chuyển và phân phối nhanh chóng lượng thực phẩm quyên góp của bạn đến các tổ chức đã được thẩm định đang có nhu cầu."}],"evQuotes":["If you need us to come to you instead, please contact us.","We will reach out to one of the many independent truck drivers who have kindly volunteered to transport and quickly distribute your food donations to vetted groups that need it."]},{"q":158,"part":7,"group_id":"E25_T01_G158_160","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc13.webp"],"stem_en":"Where most likely is the notice posted?","stem_vi":"Thông báo này có khả năng được niêm yết ở đâu nhất?","options":{"A":{"en":"In an airplane","vi":"Trên máy bay"},"B":{"en":"In a concert hall","vi":"Trong phòng hòa nhạc"},"C":{"en":"At a restaurant","vi":"Tại một nhà hàng"},"D":{"en":"At a post office","vi":"Tại một bưu điện"}},"ans":"B","evidence_quote":"Upon entering the venue, please put any and all electronic devices in silent mode. Ringtones and lit screens are very distracting to both the performers and your fellow audience members.","explanation":"Đáp án đúng: (B) Trong phòng hòa nhạc — Thông báo nhắc đến các nghệ sĩ biểu diễn (\"performers\"), khán giả (\"audience members\"), lệnh cấm ghi âm quay hình buổi biểu diễn (\"recording of the performance\") và quy định để túi dưới ghế ngồi (\"under a seat\") tránh chắn lối đi (\"aisles\"), đặc trưng của phòng hòa nhạc.\nDẫn chứng: \"Ringtones and lit screens are very distracting to both the performers and your fellow audience members.\" và \"Moreover, audience members are not allowed to make an audio or visual recording of the performance.\" (Nhạc chuông và màn hình sáng gây mất tập trung cho cả nghệ sĩ biểu diễn và khán giả; hơn nữa khán giả không được ghi âm hay quay hình buổi biểu diễn).\nPhân tích bẫy:\n- (A) Bẫy chi tiết \"under a seat\" và \"aisles\": Trên máy bay cũng có lối đi và ghế ngồi, nhưng máy bay không có \"performers\" (nghệ sĩ biểu diễn), \"audience members\" hay buổi biểu diễn (\"performance\").\n- (C) Sai bối cảnh: Nhà hàng (\"restaurant\") phục vụ ăn uống cho thực khách, không có khán giả xem biểu diễn hay tủ khóa đồ $2 dành cho người tham dự sự kiện.\n- (D) Sai hoàn toàn bối cảnh: Bưu điện (\"post office\") không có ghế khán giả, lối đi rạp, nhân viên phục vụ sự kiện hay nghệ sĩ biểu diễn.","lines":[{"speaker":"Document 1 — Notice","en":"We are delighted that you are joining us for today's event. — [1] —. We ask that you adhere to the following guidelines to ensure that all attendees have an enjoyable experience.","vi":"Chúng tôi rất vui mừng được chào đón quý khách tham dự sự kiện hôm nay. — [1] —. Chúng tôi đề nghị quý khách tuân thủ các quy định sau đây nhằm đảm bảo tất cả người tham dự đều có một trải nghiệm thú vị.","units":[{"en":"We are delighted that you are joining us for today's event. — [1] —.","vi":"Chúng tôi rất vui mừng được chào đón quý khách tham dự sự kiện hôm nay. — [1] —."},{"en":"We ask that you adhere to the following guidelines to ensure that all attendees have an enjoyable experience.","vi":"Chúng tôi đề nghị quý khách tuân thủ các quy định sau đây nhằm đảm bảo tất cả người tham dự đều có một trải nghiệm thú vị."}]},{"speaker":"","en":"Upon entering the venue, please put any and all electronic devices in silent mode. Ringtones and lit screens are very distracting to both the performers and your fellow audience members. — [2] —. Moreover, audience members are not allowed to make an audio or visual recording of the performance.","vi":"Khi bước vào địa điểm tổ chức, vui lòng chuyển toàn bộ các thiết bị điện tử sang chế độ im lặng. Tiếng chuông và ánh sáng màn hình gây mất tập trung rất nhiều cho cả nghệ sĩ biểu diễn lẫn những khán giả xung quanh. — [2] —. Hơn nữa, khán giả không được phép ghi âm hoặc quay hình buổi biểu diễn.","units":[{"en":"Upon entering the venue, please put any and all electronic devices in silent mode.","vi":"Khi bước vào địa điểm tổ chức, vui lòng chuyển toàn bộ các thiết bị điện tử sang chế độ im lặng."},{"en":"Ringtones and lit screens are very distracting to both the performers and your fellow audience members. — [2] —.","vi":"Tiếng chuông và ánh sáng màn hình gây mất tập trung rất nhiều cho cả nghệ sĩ biểu diễn lẫn những khán giả xung quanh. — [2] —."},{"en":"Moreover, audience members are not allowed to make an audio or visual recording of the performance.","vi":"Hơn nữa, khán giả không được phép ghi âm hoặc quay hình buổi biểu diễn."}]},{"speaker":"","en":"Bags and other items in the aisles pose a safety concern. — [3] —. If your bag is too big to fit properly under a seat, consider storing it in a locker for just $2. — [4] —. One of our attendants will gladly assist you with that.","vi":"Túi xách và các vật dụng khác đặt trên lối đi gây ra mối lo ngại về an toàn. — [3] —. Nếu túi của quý khách quá lớn để đặt gọn dưới ghế ngồi, hãy cân nhắc cất giữ trong tủ khóa chỉ với $2. — [4] —. Nhân viên phục vụ của chúng tôi sẽ sẵn lòng hỗ trợ quý khách việc này.","units":[{"en":"Bags and other items in the aisles pose a safety concern. — [3] —.","vi":"Túi xách và các vật dụng khác đặt trên lối đi gây ra mối lo ngại về an toàn. — [3] —."},{"en":"If your bag is too big to fit properly under a seat, consider storing it in a locker for just $2. — [4] —.","vi":"Nếu túi của quý khách quá lớn để đặt gọn dưới ghế ngồi, hãy cân nhắc cất giữ trong tủ khóa chỉ với $2. — [4] —."},{"en":"One of our attendants will gladly assist you with that.","vi":"Nhân viên phục vụ của chúng tôi sẽ sẵn lòng hỗ trợ quý khách việc này."}]},{"speaker":"","en":"Thank you for your cooperation.","vi":"Cảm ơn sự hợp tác của quý khách.","units":[{"en":"Thank you for your cooperation.","vi":"Cảm ơn sự hợp tác của quý khách."}]}],"vocab":[{"word":"adhere to","pos":"phr. v","ipa":"/ədˈhɪr tuː/","meaning":"tuân thủ, chấp hành"},{"word":"venue","pos":"n","ipa":"/ˈvenjuː/","meaning":"địa điểm tổ chức sự kiện"},{"word":"distracting","pos":"adj","ipa":"/dɪˈstræktɪŋ/","meaning":"gây mất tập trung, gây xao nhãng"},{"word":"performer","pos":"n","ipa":"/pərˈfɔːrmər/","meaning":"nghệ sĩ biểu diễn"}],"isScanBacked":false,"docTypeLabel":"notice","context":"Event venue notice outlining audience guidelines on electronic devices and large bags","grammarType":"Part 7 — Suy luận & Hàm ý văn bản (Inference & Implied Meaning)","formula":"CÔNG THỨC PART 7 (Thông báo — Suy luận địa điểm qua cụm từ bối cảnh đặc thù): Gặp chuỗi từ khóa \"performers\", \"audience members\", \"recording of the performance\", \"aisles\", \"under a seat\" -> Chỉ có phòng hòa nhạc hoặc nhà hát (\"In a concert hall\") hội tụ đủ nghệ sĩ biểu diễn, khán giả và hàng ghế.","optionAnalysis":{"A":"Bẫy chi tiết \"aisles\" và \"under a seat\": Máy bay có lối đi và chỗ để túi dưới ghế, nhưng không có nghệ sĩ biểu diễn (\"performers\") và khán giả (\"audience members\").","B":"Chính xác! Sự xuất hiện đồng thời của \"performers\", \"audience members\", \"performance\" và quy định tắt chuông/không quay phim chỉ đích danh không gian phòng hòa nhạc.","C":"Sai đối tượng và hoạt động: Nhà hàng phục vụ thực khách ăn uống, không có buổi biểu diễn nghệ thuật hay nội quy cấm ghi hình như thông báo này.","D":"Sai hoàn toàn bối cảnh: Bưu điện không tổ chức sự kiện biểu diễn cho khán giả ngồi xem theo hàng ghế (\"aisles\", \"seat\")."},"evDocIdx":0,"evTargets":[{"badge":"Câu 158 · Đáp án B","opt":"B","isCorrect":true,"quote":"Ringtones and lit screens are very distracting to both the performers and your fellow audience members.","viQuote":"Tiếng chuông và ánh sáng màn hình gây mất tập trung rất nhiều cho cả nghệ sĩ biểu diễn lẫn những khán giả xung quanh."},{"badge":"Câu 158 · Đáp án B","opt":"B","isCorrect":true,"quote":"Moreover, audience members are not allowed to make an audio or visual recording of the performance.","viQuote":"Hơn nữa, khán giả không được phép ghi âm hoặc quay hình buổi biểu diễn."}],"evQuotes":["Ringtones and lit screens are very distracting to both the performers and your fellow audience members.","Moreover, audience members are not allowed to make an audio or visual recording of the performance."]},{"q":159,"part":7,"group_id":"E25_T01_G158_160","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc13.webp"],"stem_en":"What is stated about large bags?","stem_vi":"Thông tin nào được nêu về những chiếc túi cỡ lớn?","options":{"A":{"en":"They can be put in a locked box for a fee.","vi":"Chúng có thể được cất trong hộp có khóa với một khoản phí."},"B":{"en":"They must be left outside the building.","vi":"Chúng bắt buộc phải để bên ngoài tòa nhà."},"C":{"en":"They will be inspected by an attendant.","vi":"Chúng sẽ được nhân viên phục vụ kiểm tra."},"D":{"en":"They must be stored under a seat.","vi":"Chúng bắt buộc phải được đặt dưới ghế ngồi."}},"ans":"A","evidence_quote":"If your bag is too big to fit properly under a seat, consider storing it in a locker for just $2.","explanation":"Đáp án đúng: (A) Chúng có thể được cất trong hộp có khóa với một khoản phí — Đoạn 3 hướng dẫn nếu túi quá lớn không để vừa dưới gầm ghế, khách có thể cân nhắc gửi vào tủ khóa (\"locker\") với mức phí $2, được paraphrase thành \"a locked box for a fee\".\nDẫn chứng: \"If your bag is too big to fit properly under a seat, consider storing it in a locker for just $2.\" (Nếu túi của quý khách quá lớn để đặt gọn dưới ghế ngồi, hãy cân nhắc cất giữ trong tủ khóa chỉ với $2).\nPhân tích bẫy:\n- (B) Sai nơi gửi đồ: Túi cỡ lớn được gợi ý cất trong tủ khóa (\"locker\") có nhân viên phục vụ hỗ trợ ngay tại địa điểm, không bắt buộc để bên ngoài tòa nhà (\"outside the building\").\n- (C) Bẫy từ khóa \"attendant\": Bài có nhắc \"One of our attendants will gladly assist you with that\", tức là nhân viên giúp khách cất đồ vào tủ khóa, không phải để kiểm tra túi (\"inspected\").\n- (D) Ngược điều kiện trong bài: Túi cỡ lớn (\"too big to fit properly under a seat\") KHÔNG thể nhét vừa dưới ghế ngồi, nên mới phải gửi tủ khóa với giá $2.","lines":[{"speaker":"Document 1 — Notice","en":"We are delighted that you are joining us for today's event. — [1] —. We ask that you adhere to the following guidelines to ensure that all attendees have an enjoyable experience.","vi":"Chúng tôi rất vui mừng được chào đón quý khách tham dự sự kiện hôm nay. — [1] —. Chúng tôi đề nghị quý khách tuân thủ các quy định sau đây nhằm đảm bảo tất cả người tham dự đều có một trải nghiệm thú vị.","units":[{"en":"We are delighted that you are joining us for today's event. — [1] —.","vi":"Chúng tôi rất vui mừng được chào đón quý khách tham dự sự kiện hôm nay. — [1] —."},{"en":"We ask that you adhere to the following guidelines to ensure that all attendees have an enjoyable experience.","vi":"Chúng tôi đề nghị quý khách tuân thủ các quy định sau đây nhằm đảm bảo tất cả người tham dự đều có một trải nghiệm thú vị."}]},{"speaker":"","en":"Upon entering the venue, please put any and all electronic devices in silent mode. Ringtones and lit screens are very distracting to both the performers and your fellow audience members. — [2] —. Moreover, audience members are not allowed to make an audio or visual recording of the performance.","vi":"Khi bước vào địa điểm tổ chức, vui lòng chuyển toàn bộ các thiết bị điện tử sang chế độ im lặng. Tiếng chuông và ánh sáng màn hình gây mất tập trung rất nhiều cho cả nghệ sĩ biểu diễn lẫn những khán giả xung quanh. — [2] —. Hơn nữa, khán giả không được phép ghi âm hoặc quay hình buổi biểu diễn.","units":[{"en":"Upon entering the venue, please put any and all electronic devices in silent mode.","vi":"Khi bước vào địa điểm tổ chức, vui lòng chuyển toàn bộ các thiết bị điện tử sang chế độ im lặng."},{"en":"Ringtones and lit screens are very distracting to both the performers and your fellow audience members. — [2] —.","vi":"Tiếng chuông và ánh sáng màn hình gây mất tập trung rất nhiều cho cả nghệ sĩ biểu diễn lẫn những khán giả xung quanh. — [2] —."},{"en":"Moreover, audience members are not allowed to make an audio or visual recording of the performance.","vi":"Hơn nữa, khán giả không được phép ghi âm hoặc quay hình buổi biểu diễn."}]},{"speaker":"","en":"Bags and other items in the aisles pose a safety concern. — [3] —. If your bag is too big to fit properly under a seat, consider storing it in a locker for just $2. — [4] —. One of our attendants will gladly assist you with that.","vi":"Túi xách và các vật dụng khác đặt trên lối đi gây ra mối lo ngại về an toàn. — [3] —. Nếu túi của quý khách quá lớn để đặt gọn dưới ghế ngồi, hãy cân nhắc cất giữ trong tủ khóa chỉ với $2. — [4] —. Nhân viên phục vụ của chúng tôi sẽ sẵn lòng hỗ trợ quý khách việc này.","units":[{"en":"Bags and other items in the aisles pose a safety concern. — [3] —.","vi":"Túi xách và các vật dụng khác đặt trên lối đi gây ra mối lo ngại về an toàn. — [3] —."},{"en":"If your bag is too big to fit properly under a seat, consider storing it in a locker for just $2. — [4] —.","vi":"Nếu túi của quý khách quá lớn để đặt gọn dưới ghế ngồi, hãy cân nhắc cất giữ trong tủ khóa chỉ với $2. — [4] —."},{"en":"One of our attendants will gladly assist you with that.","vi":"Nhân viên phục vụ của chúng tôi sẽ sẵn lòng hỗ trợ quý khách việc này."}]},{"speaker":"","en":"Thank you for your cooperation.","vi":"Cảm ơn sự hợp tác của quý khách.","units":[{"en":"Thank you for your cooperation.","vi":"Cảm ơn sự hợp tác của quý khách."}]}],"vocab":[{"word":"aisle","pos":"n","ipa":"/aɪl/","meaning":"lối đi (giữa các hàng ghế)"},{"word":"pose a concern","pos":"phr","ipa":"/poʊz ə kənˈsɜːrn/","meaning":"gây ra mối lo ngại"},{"word":"locker","pos":"n","ipa":"/ˈlɑːkər/","meaning":"tủ khóa gửi đồ"},{"word":"attendant","pos":"n","ipa":"/əˈtendənt/","meaning":"nhân viên phục vụ, nhân viên hỗ trợ"}],"isScanBacked":false,"docTypeLabel":"notice","context":"Event venue notice outlining audience guidelines on electronic devices and large bags","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 (Thông báo — Paraphrase danh từ & chi phí): Đối chiếu cụm \"too big to fit properly under a seat\" (= large bags) -> \"storing it in a locker for just $2\" được diễn đạt lại thành \"put in a locked box for a fee\" (cất trong hộp có khóa với một khoản phí).","optionAnalysis":{"A":"Chính xác! \"storing it in a locker for just $2\" đối với túi \"too big to fit properly under a seat\" khớp hoàn toàn với \"put in a locked box for a fee\".","B":"Thông tin sai lệch: Thông báo gợi ý gửi túi quá khổ vào tủ khóa với giá $2, hoàn toàn không yêu cầu để túi bên ngoài tòa nhà.","C":"Bẫy đánh tráo hành động của \"attendant\": Nhân viên phục vụ chỉ hỗ trợ khách cất túi vào tủ khóa (\"assist you with that\"), không hề thực hiện kiểm tra túi (\"inspected\").","D":"Trái ngược thông tin bài đọc: Bài nói túi cỡ lớn quá to nên không đặt vừa dưới ghế (\"too big to fit properly under a seat\"), chứ không bắt buộc để dưới ghế."},"evDocIdx":0,"evTargets":[{"badge":"Câu 159 · Đáp án A","opt":"A","isCorrect":true,"quote":"If your bag is too big to fit properly under a seat, consider storing it in a locker for just $2.","viQuote":"Nếu túi của quý khách quá lớn để đặt gọn dưới ghế ngồi, hãy cân nhắc cất giữ trong tủ khóa chỉ với $2."}],"evQuotes":["If your bag is too big to fit properly under a seat, consider storing it in a locker for just $2."]},{"q":160,"part":7,"group_id":"E25_T01_G158_160","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc13.webp"],"stem_en":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? \"Please refrain from making phone calls or texting at all times.\"","stem_vi":"Câu sau đây phù hợp nhất với vị trí nào trong các vị trí được đánh dấu [1], [2], [3] và [4]? \"Vui lòng không gọi điện thoại hoặc nhắn tin vào bất kỳ lúc nào.\"","options":{"A":{"en":"[1]","vi":"Vị trí [1]"},"B":{"en":"[2]","vi":"Vị trí [2]"},"C":{"en":"[3]","vi":"Vị trí [3]"},"D":{"en":"[4]","vi":"Vị trí [4]"}},"ans":"B","evidence_quote":"Ringtones and lit screens are very distracting to both the performers and your fellow audience members. Please","explanation":"Đáp án đúng: (B) Vị trí [2] — Câu cần chèn yêu cầu không gọi điện thoại hoặc nhắn tin (\"phone calls or texting\") bổ sung trực tiếp cho đoạn 2 đang quy định về thiết bị điện tử: ngay trước [2] giải thích chuông điện thoại và màn hình sáng gây mất tập trung (\"Ringtones and lit screens\"), và ngay sau [2] dùng từ nối \"Moreover\" để nêu thêm lệnh cấm ghi âm hoặc quay hình.\nDẫn chứng: \"Upon entering the venue, please put any and all electronic devices in silent mode. Ringtones and lit screens are very distracting to both the performers and your fellow audience members. — [2] —. Moreover, audience members are not allowed to make an audio or visual recording of the performance.\" (Nhạc chuông và màn hình sáng gây mất tập trung cho nghệ sĩ và khán giả; đặt câu cấm gọi điện/nhắn tin vào [2] rồi nối sang lệnh cấm ghi hình bằng \"Moreover\").\nPhân tích bẫy:\n- (A) Vị trí [1] sai mạch mở đầu: Đoạn 1 là lời chào mừng chung và dẫn nhập vào danh sách quy định (\"adhere to the following guidelines\"); chưa bắt đầu liệt kê nội quy cụ thể về điện thoại.\n- (C) Vị trí [3] sai chủ đề đoạn: Đoạn 3 chuyển hẳn sang quy định về túi xách trên lối đi (\"Bags and other items in the aisles\"), nếu chèn lệnh cấm gọi điện vào đây sẽ làm đứt mạch văn.\n- (D) Vị trí [4] phá vỡ liên kết đại từ: Ngay sau [4] là \"assist you with that\" trong đó \"that\" chỉ việc gửi túi vào tủ khóa (\"storing it in a locker\"); chèn câu về điện thoại vào [4] sẽ làm sai nghĩa của \"that\".","lines":[{"speaker":"Document 1 — Notice","en":"We are delighted that you are joining us for today's event. — [1] —. We ask that you adhere to the following guidelines to ensure that all attendees have an enjoyable experience.","vi":"Chúng tôi rất vui mừng được chào đón quý khách tham dự sự kiện hôm nay. — [1] —. Chúng tôi đề nghị quý khách tuân thủ các quy định sau đây nhằm đảm bảo tất cả người tham dự đều có một trải nghiệm thú vị.","units":[{"en":"We are delighted that you are joining us for today's event. — [1] —.","vi":"Chúng tôi rất vui mừng được chào đón quý khách tham dự sự kiện hôm nay. — [1] —."},{"en":"We ask that you adhere to the following guidelines to ensure that all attendees have an enjoyable experience.","vi":"Chúng tôi đề nghị quý khách tuân thủ các quy định sau đây nhằm đảm bảo tất cả người tham dự đều có một trải nghiệm thú vị."}]},{"speaker":"","en":"Upon entering the venue, please put any and all electronic devices in silent mode. Ringtones and lit screens are very distracting to both the performers and your fellow audience members. — [2] —. Moreover, audience members are not allowed to make an audio or visual recording of the performance.","vi":"Khi bước vào địa điểm tổ chức, vui lòng chuyển toàn bộ các thiết bị điện tử sang chế độ im lặng. Tiếng chuông và ánh sáng màn hình gây mất tập trung rất nhiều cho cả nghệ sĩ biểu diễn lẫn những khán giả xung quanh. — [2] —. Hơn nữa, khán giả không được phép ghi âm hoặc quay hình buổi biểu diễn.","units":[{"en":"Upon entering the venue, please put any and all electronic devices in silent mode.","vi":"Khi bước vào địa điểm tổ chức, vui lòng chuyển toàn bộ các thiết bị điện tử sang chế độ im lặng."},{"en":"Ringtones and lit screens are very distracting to both the performers and your fellow audience members. — [2] —.","vi":"Tiếng chuông và ánh sáng màn hình gây mất tập trung rất nhiều cho cả nghệ sĩ biểu diễn lẫn những khán giả xung quanh. — [2] —."},{"en":"Moreover, audience members are not allowed to make an audio or visual recording of the performance.","vi":"Hơn nữa, khán giả không được phép ghi âm hoặc quay hình buổi biểu diễn."}]},{"speaker":"","en":"Bags and other items in the aisles pose a safety concern. — [3] —. If your bag is too big to fit properly under a seat, consider storing it in a locker for just $2. — [4] —. One of our attendants will gladly assist you with that.","vi":"Túi xách và các vật dụng khác đặt trên lối đi gây ra mối lo ngại về an toàn. — [3] —. Nếu túi của quý khách quá lớn để đặt gọn dưới ghế ngồi, hãy cân nhắc cất giữ trong tủ khóa chỉ với $2. — [4] —. Nhân viên phục vụ của chúng tôi sẽ sẵn lòng hỗ trợ quý khách việc này.","units":[{"en":"Bags and other items in the aisles pose a safety concern. — [3] —.","vi":"Túi xách và các vật dụng khác đặt trên lối đi gây ra mối lo ngại về an toàn. — [3] —."},{"en":"If your bag is too big to fit properly under a seat, consider storing it in a locker for just $2. — [4] —.","vi":"Nếu túi của quý khách quá lớn để đặt gọn dưới ghế ngồi, hãy cân nhắc cất giữ trong tủ khóa chỉ với $2. — [4] —."},{"en":"One of our attendants will gladly assist you with that.","vi":"Nhân viên phục vụ của chúng tôi sẽ sẵn lòng hỗ trợ quý khách việc này."}]},{"speaker":"","en":"Thank you for your cooperation.","vi":"Cảm ơn sự hợp tác của quý khách.","units":[{"en":"Thank you for your cooperation.","vi":"Cảm ơn sự hợp tác của quý khách."}]}],"vocab":[{"word":"refrain from","pos":"phr. v","ipa":"/rɪˈfreɪn frʌm/","meaning":"kiềm chế, tránh làm (điều gì)"},{"word":"moreover","pos":"adv","ipa":"/mɔːrˈoʊvər/","meaning":"hơn nữa, ngoài ra"},{"word":"cooperation","pos":"n","ipa":"/koʊˌɑːpəˈreɪʃən/","meaning":"sự hợp tác"}],"isScanBacked":false,"docTypeLabel":"notice","context":"Event venue notice outlining audience guidelines on electronic devices and large bags","grammarType":"Part 7 — Điền câu vào vị trí thích hợp (Sentence Insertion)","formula":"CÔNG THỨC PART 7 (Điền câu vào vị trí [1]–[4] — Neo chủ đề thiết bị điện tử): Xác định từ khóa câu cần điền (\"phone calls or texting\") -> Đặt ngay sau câu giải thích tác hại của tiếng chuông và màn hình sáng (\"Ringtones and lit screens\") tại [2], trước câu chuyển tiếp \"Moreover\" về lệnh cấm ghi hình.","optionAnalysis":{"A":"Đứt mạch đoạn mở đầu: Trước [1] mới chỉ là câu chào mừng đến sự kiện và sau [1] mới giới thiệu chung về \"the following guidelines\", chưa đi vào quy định điện thoại.","B":"Chính xác! Đoạn 2 bàn riêng về thiết bị điện tử; câu \"making phone calls or texting\" nối trực tiếp ý \"Ringtones and lit screens\" phía trước và đứng trước \"Moreover\" ở [2].","C":"Lạc chủ đề đoạn 3: Đoạn 3 đang nói về túi xách và vật dụng chắn lối đi (\"Bags and other items in the aisles\"), hoàn toàn không liên quan đến nghe gọi hay nhắn tin.","D":"Phá vỡ quy chiếu đại từ \"that\": Câu sau [4] viết \"assist you with that\" nhằm chỉ việc cất túi vào tủ khóa ở câu trước [4]; chèn câu về điện thoại sẽ làm hỏng liên kết này."},"evDocIdx":0,"evTargets":[{"badge":"Câu 160 · Đáp án B","opt":"B","isCorrect":true,"quote":"Upon entering the venue, please put any and all electronic devices in silent mode.","viQuote":"Khi bước vào địa điểm tổ chức, vui lòng chuyển toàn bộ các thiết bị điện tử sang chế độ im lặng."},{"badge":"Câu 160 · Đáp án B","opt":"B","isCorrect":true,"quote":"Ringtones and lit screens are very distracting to both the performers and your fellow audience members.","viQuote":"Tiếng chuông và ánh sáng màn hình gây mất tập trung rất nhiều cho cả nghệ sĩ biểu diễn lẫn những khán giả xung quanh."},{"badge":"Câu 160 · Đáp án B","opt":"B","isCorrect":true,"quote":"Moreover, audience members are not allowed to make an audio or visual recording of the performance.","viQuote":"Hơn nữa, khán giả không được phép ghi âm hoặc quay hình buổi biểu diễn."}],"evQuotes":["Upon entering the venue, please put any and all electronic devices in silent mode.","Ringtones and lit screens are very distracting to both the performers and your fellow audience members.","Moreover, audience members are not allowed to make an audio or visual recording of the performance."]},{"q":161,"part":7,"group_id":"E25_T01_G161_164","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc14.webp"],"stem_en":"What is the main purpose of the e-mail?","stem_vi":"Mục đích chính của e-mail này là gì?","options":{"A":{"en":"To request confirmation of an order","vi":"Để yêu cầu xác nhận một đơn đặt hàng"},"B":{"en":"To adjust some delivery dates","vi":"Để điều chỉnh một số ngày giao hàng"},"C":{"en":"To announce the expansion of a business","vi":"Để thông báo về việc mở rộng hoạt động kinh doanh"},"D":{"en":"To promote new dessert products","vi":"Để quảng bá các sản phẩm tráng miệng mới"}},"ans":"A","evidence_quote":"Please review the attached order form and return it to me within seven days.","explanation":"Đáp án đúng: (A) Để yêu cầu xác nhận một đơn đặt hàng — chủ sở hữu cửa hàng bánh gửi kèm phiếu yêu cầu và đề nghị bà Ayala kiểm tra rồi gửi lại trong vòng 7 ngày để chốt đơn đặt hàng cho sự kiện.\nDẫn chứng: \"Subject: Event order\", \"Attachment: Sweeter Specialties Request Form\" và \"Please review the attached order form and return it to me within seven days.\" (Paraphrase: \"review the attached order form and return it\" tương đương với \"request confirmation of an order\").\nPhân tích bẫy:\n- (B) Bẫy sai hành động: bài nêu cố định lịch giao bánh vào ngày 29 tháng 3 và ngày hôm sau (30 tháng 3), không hề đề cập việc điều chỉnh hay thay đổi ngày giao hàng.\n- (C) Bẫy suy diễn ngoài bài: tác giả cảm ơn khách hàng chọn dịch vụ năm thứ tư liên tiếp chứ không thông báo mở rộng quy mô kinh doanh của Sweeter Specialties.\n- (D) Bẫy biến tấu chi tiết món bánh: mẫu bánh kem hạnh nhân nhân mâm xôi là bánh đặt làm riêng theo yêu cầu có sẵn của bà Ayala (\"according to your specifications\"), không phải chiến dịch quảng bá sản phẩm tráng miệng mới.","lines":[{"speaker":"Document 1 — E-mail","en":"To: Camille Ayala <ayala@esplinelectronics.com>","vi":"Đến: Camille Ayala <ayala@esplinelectronics.com>","units":[{"en":"To: Camille Ayala <ayala@esplinelectronics.com>","vi":"Đến: Camille Ayala <ayala@esplinelectronics.com>"}]},{"speaker":"","en":"From: Masae Adachi <madachi@sweeterspecialties.com>","vi":"Từ: Masae Adachi <madachi@sweeterspecialties.com>","units":[{"en":"From: Masae Adachi <madachi@sweeterspecialties.com>","vi":"Từ: Masae Adachi <madachi@sweeterspecialties.com>"}]},{"speaker":"","en":"Date: February 12","vi":"Ngày: 12 tháng 2","units":[{"en":"Date: February 12","vi":"Ngày: 12 tháng 2"}]},{"speaker":"","en":"Subject: Event order","vi":"Chủ đề: Đơn đặt hàng sự kiện","units":[{"en":"Subject: Event order","vi":"Chủ đề: Đơn đặt hàng sự kiện"}]},{"speaker":"","en":"Attachment: Sweeter Specialties Request Form","vi":"Tệp đính kèm: Phiếu yêu cầu của Sweeter Specialties","units":[{"en":"Attachment: Sweeter Specialties Request Form","vi":"Tệp đính kèm: Phiếu yêu cầu của Sweeter Specialties"}]},{"speaker":"","en":"Dear Ms. Ayala,","vi":"Kính gửi bà Ayala,","units":[{"en":"Dear Ms. Ayala,","vi":"Kính gửi bà Ayala,"}]},{"speaker":"","en":"Thank you for selecting our business to provide baked goods for the Esplin Electronics conference event in March. We are honored that you chose us for a fourth year in a row! On March 29, we will provide a large vanilla cake for each of the ten venues you indicated, and we will deliver a custom-baked multilayer cake on the following day. You will be billed on March 28. Please review the attached order form and return it to me within seven days.","vi":"Cảm ơn bà đã lựa chọn cửa hàng chúng tôi cung cấp các loại bánh nướng cho sự kiện hội nghị của Esplin Electronics vào tháng 3 tới. Chúng tôi vô cùng vinh dự khi được bà tin chọn năm thứ tư liên tiếp! Vào ngày 29 tháng 3, chúng tôi sẽ cung cấp một chiếc bánh vani cỡ lớn cho từng địa điểm trong số mười địa điểm bà đã chỉ định, và vào ngày hôm sau chúng tôi sẽ giao một chiếc bánh nhiều tầng nướng theo yêu cầu riêng. Hóa đơn thanh toán sẽ được xuất cho bà vào ngày 28 tháng 3. Vui lòng xem lại phiếu đặt hàng đính kèm và gửi lại cho tôi trong vòng bảy ngày.","units":[{"en":"Thank you for selecting our business to provide baked goods for the Esplin Electronics conference event in March.","vi":"Cảm ơn bà đã lựa chọn cửa hàng chúng tôi cung cấp các loại bánh nướng cho sự kiện hội nghị của Esplin Electronics vào tháng 3 tới."},{"en":"We are honored that you chose us for a fourth year in a row!","vi":"Chúng tôi vô cùng vinh dự khi được bà tin chọn năm thứ tư liên tiếp!"},{"en":"On March 29, we will provide a large vanilla cake for each of the ten venues you indicated, and we will deliver a custom-baked multilayer cake on the following day.","vi":"Vào ngày 29 tháng 3, chúng tôi sẽ cung cấp một chiếc bánh vani cỡ lớn cho từng địa điểm trong số mười địa điểm bà đã chỉ định, và vào ngày hôm sau chúng tôi sẽ giao một chiếc bánh nhiều tầng nướng theo yêu cầu riêng."},{"en":"You will be billed on March 28.","vi":"Hóa đơn thanh toán sẽ được xuất cho bà vào ngày 28 tháng 3."},{"en":"Please review the attached order form and return it to me within seven days.","vi":"Vui lòng xem lại phiếu đặt hàng đính kèm và gửi lại cho tôi trong vòng bảy ngày."}]},{"speaker":"","en":"Regarding the cake you ordered for March 30, our head pastry chef will produce it according to your specifications. In fact, he created a sample of the complete recipe earlier today—almond crème cake with fresh raspberry filling. We have judged it to be a delectable treat, and we are sure that you will be pleased.","vi":"Về chiếc bánh bà đặt cho ngày 30 tháng 3, bếp trưởng bánh ngọt của chúng tôi sẽ thực hiện đúng theo các yêu cầu chi tiết của bà. Thực tế, đầu ngày hôm nay anh ấy đã làm thử một mẫu theo công thức hoàn chỉnh—bánh kem hạnh nhân với nhân quả mâm xôi tươi. Chúng tôi đánh giá đây là một món bánh tuyệt hảo và chắc chắn bà sẽ hài lòng.","units":[{"en":"Regarding the cake you ordered for March 30, our head pastry chef will produce it according to your specifications.","vi":"Về chiếc bánh bà đặt cho ngày 30 tháng 3, bếp trưởng bánh ngọt của chúng tôi sẽ thực hiện đúng theo các yêu cầu chi tiết của bà."},{"en":"In fact, he created a sample of the complete recipe earlier today—almond crème cake with fresh raspberry filling.","vi":"Thực tế, đầu ngày hôm nay anh ấy đã làm thử một mẫu theo công thức hoàn chỉnh—bánh kem hạnh nhân với nhân quả mâm xôi tươi."},{"en":"We have judged it to be a delectable treat, and we are sure that you will be pleased.","vi":"Chúng tôi đánh giá đây là một món bánh tuyệt hảo và chắc chắn bà sẽ hài lòng."}]},{"speaker":"","en":"If you have any concerns, just send me an e-mail. As always, we value your business.","vi":"Nếu bà có bất kỳ băn khoăn nào, chỉ cần gửi e-mail cho tôi. Như mọi khi, chúng tôi luôn trân trọng sự tin tưởng và hợp tác của bà.","units":[{"en":"If you have any concerns, just send me an e-mail.","vi":"Nếu bà có bất kỳ băn khoăn nào, chỉ cần gửi e-mail cho tôi."},{"en":"As always, we value your business.","vi":"Như mọi khi, chúng tôi luôn trân trọng sự tin tưởng và hợp tác của bà."}]},{"speaker":"","en":"Masae Adachi, Owner","vi":"Masae Adachi, Chủ sở hữu","units":[{"en":"Masae Adachi, Owner","vi":"Masae Adachi, Chủ sở hữu"}]},{"speaker":"","en":"Sweeter Specialties","vi":"Sweeter Specialties","units":[{"en":"Sweeter Specialties","vi":"Sweeter Specialties"}]}],"vocab":[{"word":"confirmation","pos":"n","ipa":"/ˌkɑːnfərˈmeɪʃən/","meaning":"sự xác nhận"},{"word":"indicate","pos":"v","ipa":"/ˈɪndɪkeɪt/","meaning":"chỉ định, nêu rõ"},{"word":"bill","pos":"v","ipa":"/bɪl/","meaning":"gửi hóa đơn thanh toán, tính tiền"}],"isScanBacked":false,"docTypeLabel":"e-mail","context":"E-mail from Masae Adachi at Sweeter Specialties to Camille Ayala regarding an event cake order","grammarType":"Part 7 — Ý chính, Mục đích & Đối tượng đọc (Main Idea & Purpose)","formula":"CÔNG THỨC PART 7 (Chủ đề & Mục đích E-mail — Dạng 31 & Câu hỏi 22): Đọc tiêu đề (Subject: Event order), tệp đính kèm và câu kêu gọi hành động (Please review and return) -> Chốt mục đích xác nhận đơn hàng.","optionAnalysis":{"A":"Chính xác: Câu cuối đoạn 1 yêu cầu 'review the attached order form and return it to me within seven days' (xem lại phiếu đặt hàng đính kèm và gửi lại trong 7 ngày), khớp với mục đích yêu cầu xác nhận đơn hàng.","B":"Sai hành động: Các mốc giao hàng ngày 29/3 và 30/3 đã được xác nhận trong e-mail, không có đề xuất điều chỉnh ngày giao nào.","C":"Sai nội dung: E-mail chỉ nhắc đến đơn đặt bánh cho sự kiện của khách hàng, không thông báo việc mở rộng kinh doanh của tiệm bánh.","D":"Bẫy chi tiết món tráng miệng: Tiệm bánh làm thử mẫu bánh theo thông số riêng khách đã đặt, không nhằm quảng bá dòng sản phẩm mới."},"evDocIdx":0,"evTargets":[{"badge":"Câu 161 · Đáp án A","opt":"A","isCorrect":true,"quote":"Please review the attached order form and return it to me within seven days.","viQuote":"Vui lòng xem lại phiếu đặt hàng đính kèm và gửi lại cho tôi trong vòng bảy ngày."}],"evQuotes":["Please review the attached order form and return it to me within seven days."]},{"q":162,"part":7,"group_id":"E25_T01_G161_164","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc14.webp"],"stem_en":"What is suggested about Ms. Ayala?","stem_vi":"Điều gì được ngụ ý về bà Ayala?","options":{"A":{"en":"She is receiving a professional award.","vi":"Bà ấy sắp nhận một giải thưởng chuyên môn."},"B":{"en":"She has worked as a pastry chef.","vi":"Bà ấy từng làm đầu bếp bánh ngọt."},"C":{"en":"She has been a Sweeter Specialties client in the past.","vi":"Bà ấy từng là khách hàng của Sweeter Specialties trước đây."},"D":{"en":"She received a positive recommendation about a chef.","vi":"Bà ấy đã nhận được một lời giới thiệu tích cực về một đầu bếp."}},"ans":"C","evidence_quote":"We are honored that you chose us for a fourth year in a row!","explanation":"Đáp án đúng: (C) Bà ấy từng là khách hàng của Sweeter Specialties trước đây — chi tiết bà Ayala chọn cửa hàng năm thứ tư liên tiếp chứng tỏ hai bên đã hợp tác nhiều lần trong quá khứ.\nDẫn chứng: \"We are honored that you chose us for a fourth year in a row!\" và \"As always, we value your business.\" (Paraphrase: \"chose us for a fourth year in a row\" ngụ ý bà đã là khách hàng quen từ các năm trước).\nPhân tích bẫy:\n- (A) Bẫy thông tin ngoài bài: e-mail chỉ nhắc đến sự kiện hội nghị tháng 3 của Esplin Electronics (\"conference event in March\"), không có chi tiết bà Ayala nhận giải thưởng chuyên môn nào.\n- (B) Bẫy tráo chủ thể: \"head pastry chef\" (bếp trưởng bánh ngọt) là nhân sự thuộc Sweeter Specialties làm bánh theo đơn đặt hàng, không phải nghề nghiệp trước đây của bà Ayala.\n- (D) Bẫy đánh tráo ý khen ngợi: cửa hàng tự nhận xét mẫu bánh do bếp trưởng của họ làm thử là món tuyệt hảo (\"judged it to be a delectable treat\"), không phải bà Ayala nhận lời giới thiệu từ ai về một đầu bếp.","lines":[{"speaker":"Document 1 — E-mail","en":"To: Camille Ayala <ayala@esplinelectronics.com>","vi":"Đến: Camille Ayala <ayala@esplinelectronics.com>","units":[{"en":"To: Camille Ayala <ayala@esplinelectronics.com>","vi":"Đến: Camille Ayala <ayala@esplinelectronics.com>"}]},{"speaker":"","en":"From: Masae Adachi <madachi@sweeterspecialties.com>","vi":"Từ: Masae Adachi <madachi@sweeterspecialties.com>","units":[{"en":"From: Masae Adachi <madachi@sweeterspecialties.com>","vi":"Từ: Masae Adachi <madachi@sweeterspecialties.com>"}]},{"speaker":"","en":"Date: February 12","vi":"Ngày: 12 tháng 2","units":[{"en":"Date: February 12","vi":"Ngày: 12 tháng 2"}]},{"speaker":"","en":"Subject: Event order","vi":"Chủ đề: Đơn đặt hàng sự kiện","units":[{"en":"Subject: Event order","vi":"Chủ đề: Đơn đặt hàng sự kiện"}]},{"speaker":"","en":"Attachment: Sweeter Specialties Request Form","vi":"Tệp đính kèm: Phiếu yêu cầu của Sweeter Specialties","units":[{"en":"Attachment: Sweeter Specialties Request Form","vi":"Tệp đính kèm: Phiếu yêu cầu của Sweeter Specialties"}]},{"speaker":"","en":"Dear Ms. Ayala,","vi":"Kính gửi bà Ayala,","units":[{"en":"Dear Ms. Ayala,","vi":"Kính gửi bà Ayala,"}]},{"speaker":"","en":"Thank you for selecting our business to provide baked goods for the Esplin Electronics conference event in March. We are honored that you chose us for a fourth year in a row! On March 29, we will provide a large vanilla cake for each of the ten venues you indicated, and we will deliver a custom-baked multilayer cake on the following day. You will be billed on March 28. Please review the attached order form and return it to me within seven days.","vi":"Cảm ơn bà đã lựa chọn cửa hàng chúng tôi cung cấp các loại bánh nướng cho sự kiện hội nghị của Esplin Electronics vào tháng 3 tới. Chúng tôi vô cùng vinh dự khi được bà tin chọn năm thứ tư liên tiếp! Vào ngày 29 tháng 3, chúng tôi sẽ cung cấp một chiếc bánh vani cỡ lớn cho từng địa điểm trong số mười địa điểm bà đã chỉ định, và vào ngày hôm sau chúng tôi sẽ giao một chiếc bánh nhiều tầng nướng theo yêu cầu riêng. Hóa đơn thanh toán sẽ được xuất cho bà vào ngày 28 tháng 3. Vui lòng xem lại phiếu đặt hàng đính kèm và gửi lại cho tôi trong vòng bảy ngày.","units":[{"en":"Thank you for selecting our business to provide baked goods for the Esplin Electronics conference event in March.","vi":"Cảm ơn bà đã lựa chọn cửa hàng chúng tôi cung cấp các loại bánh nướng cho sự kiện hội nghị của Esplin Electronics vào tháng 3 tới."},{"en":"We are honored that you chose us for a fourth year in a row!","vi":"Chúng tôi vô cùng vinh dự khi được bà tin chọn năm thứ tư liên tiếp!"},{"en":"On March 29, we will provide a large vanilla cake for each of the ten venues you indicated, and we will deliver a custom-baked multilayer cake on the following day.","vi":"Vào ngày 29 tháng 3, chúng tôi sẽ cung cấp một chiếc bánh vani cỡ lớn cho từng địa điểm trong số mười địa điểm bà đã chỉ định, và vào ngày hôm sau chúng tôi sẽ giao một chiếc bánh nhiều tầng nướng theo yêu cầu riêng."},{"en":"You will be billed on March 28.","vi":"Hóa đơn thanh toán sẽ được xuất cho bà vào ngày 28 tháng 3."},{"en":"Please review the attached order form and return it to me within seven days.","vi":"Vui lòng xem lại phiếu đặt hàng đính kèm và gửi lại cho tôi trong vòng bảy ngày."}]},{"speaker":"","en":"Regarding the cake you ordered for March 30, our head pastry chef will produce it according to your specifications. In fact, he created a sample of the complete recipe earlier today—almond crème cake with fresh raspberry filling. We have judged it to be a delectable treat, and we are sure that you will be pleased.","vi":"Về chiếc bánh bà đặt cho ngày 30 tháng 3, bếp trưởng bánh ngọt của chúng tôi sẽ thực hiện đúng theo các yêu cầu chi tiết của bà. Thực tế, đầu ngày hôm nay anh ấy đã làm thử một mẫu theo công thức hoàn chỉnh—bánh kem hạnh nhân với nhân quả mâm xôi tươi. Chúng tôi đánh giá đây là một món bánh tuyệt hảo và chắc chắn bà sẽ hài lòng.","units":[{"en":"Regarding the cake you ordered for March 30, our head pastry chef will produce it according to your specifications.","vi":"Về chiếc bánh bà đặt cho ngày 30 tháng 3, bếp trưởng bánh ngọt của chúng tôi sẽ thực hiện đúng theo các yêu cầu chi tiết của bà."},{"en":"In fact, he created a sample of the complete recipe earlier today—almond crème cake with fresh raspberry filling.","vi":"Thực tế, đầu ngày hôm nay anh ấy đã làm thử một mẫu theo công thức hoàn chỉnh—bánh kem hạnh nhân với nhân quả mâm xôi tươi."},{"en":"We have judged it to be a delectable treat, and we are sure that you will be pleased.","vi":"Chúng tôi đánh giá đây là một món bánh tuyệt hảo và chắc chắn bà sẽ hài lòng."}]},{"speaker":"","en":"If you have any concerns, just send me an e-mail. As always, we value your business.","vi":"Nếu bà có bất kỳ băn khoăn nào, chỉ cần gửi e-mail cho tôi. Như mọi khi, chúng tôi luôn trân trọng sự tin tưởng và hợp tác của bà.","units":[{"en":"If you have any concerns, just send me an e-mail.","vi":"Nếu bà có bất kỳ băn khoăn nào, chỉ cần gửi e-mail cho tôi."},{"en":"As always, we value your business.","vi":"Như mọi khi, chúng tôi luôn trân trọng sự tin tưởng và hợp tác của bà."}]},{"speaker":"","en":"Masae Adachi, Owner","vi":"Masae Adachi, Chủ sở hữu","units":[{"en":"Masae Adachi, Owner","vi":"Masae Adachi, Chủ sở hữu"}]},{"speaker":"","en":"Sweeter Specialties","vi":"Sweeter Specialties","units":[{"en":"Sweeter Specialties","vi":"Sweeter Specialties"}]}],"vocab":[{"word":"in a row","pos":"phr","ipa":"/ɪn ə roʊ/","meaning":"liên tiếp, nối tiếp nhau"},{"word":"value","pos":"v","ipa":"/ˈvæljuː/","meaning":"trân trọng, đánh giá cao"},{"word":"client","pos":"n","ipa":"/ˈklaɪənt/","meaning":"khách hàng (dịch vụ, đối tác)"}],"isScanBacked":false,"docTypeLabel":"e-mail","context":"E-mail from Masae Adachi at Sweeter Specialties to Camille Ayala regarding an event cake order","grammarType":"Part 7 — Suy luận & Hàm ý văn bản (Inference & Implied Meaning)","formula":"CÔNG THỨC PART 7 (Câu hỏi Suy luận về Nhân vật — Dạng 27): Tìm từ khóa chỉ tần suất lặp lại ('for a fourth year in a row', 'As always') -> Suy ra khách hàng đã từng sử dụng dịch vụ trước đây.","optionAnalysis":{"A":"Thông tin bịa đặt: Bài chỉ nói về hội nghị tháng 3 của Esplin Electronics, hoàn toàn không nhắc tới việc bà Ayala nhận giải thưởng chuyên môn.","B":"Tráo đổi vai trò nhân vật: Bếp trưởng bánh ngọt ('head pastry chef') là nhân viên của Sweeter Specialties, còn bà Ayala là người đặt bánh phía Esplin Electronics.","C":"Chính xác: Cụm 'chose us for a fourth year in a row' (chọn chúng tôi 4 năm liên tiếp) và 'As always' khẳng định bà Ayala đã là khách hàng của tiệm từ trước.","D":"Bóp méo thông tin đầu bếp: Chủ tiệm Masae Adachi khen bánh thử do đầu bếp của tiệm làm ngon, chứ bà Ayala không nhận lời giới thiệu nào về đầu bếp."},"evDocIdx":0,"evTargets":[{"badge":"Câu 162 · Đáp án C","opt":"C","isCorrect":true,"quote":"We are honored that you chose us for a fourth year in a row!","viQuote":"Chúng tôi vô cùng vinh dự khi được bà tin chọn năm thứ tư liên tiếp!"},{"badge":"Câu 162 · Đáp án C","opt":"C","isCorrect":true,"quote":"As always, we value your business.","viQuote":"Như mọi khi, chúng tôi luôn trân trọng sự tin tưởng và hợp tác của bà."}],"evQuotes":["We are honored that you chose us for a fourth year in a row!","As always, we value your business."]},{"q":163,"part":7,"group_id":"E25_T01_G161_164","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc14.webp"],"stem_en":"What is indicated about the multilayer cake?","stem_vi":"Điều gì được nêu rõ về chiếc bánh nhiều tầng?","options":{"A":{"en":"It has been a best-selling product with clients.","vi":"Đây là sản phẩm bán chạy nhất đối với khách hàng."},"B":{"en":"It is the most expensive cake at Sweeter Specialties.","vi":"Đây là chiếc bánh đắt nhất tại Sweeter Specialties."},"C":{"en":"It is baked for Esplin Electronics annually.","vi":"Chiếc bánh này được nướng hằng năm cho Esplin Electronics."},"D":{"en":"It is a new flavor combination for Sweeter Specialties.","vi":"Đây là sự kết hợp hương vị mới của Sweeter Specialties."}},"ans":"D","evidence_quote":"- On March 29, we will provide a large vanilla cake for each of the ten venues you indicated, and we will deliver a custom-baked multilayer cake on the following day. - Regarding the cake you ordered for March 30, our head pastry chef will produce it according to your specifications.","explanation":"Đáp án đúng: (D) Đây là sự kết hợp hương vị mới của Sweeter Specialties — chiếc bánh nhiều tầng ngày 30/3 được nướng riêng theo thông số của khách và bếp trưởng vừa phải làm thử mẫu công thức hoàn chỉnh gồm bánh kem hạnh nhân nhân mâm xôi tươi.\nDẫn chứng: \"we will deliver a custom-baked multilayer cake on the following day\" và \"our head pastry chef will produce it according to your specifications. In fact, he created a sample of the complete recipe earlier today—almond crème cake with fresh raspberry filling.\" (Việc làm mẫu thử theo thông số riêng của khách cho thấy đây là sự kết hợp hương vị mới đối với tiệm).\nPhân tích bẫy:\n- (A) Bẫy suy diễn phổ biến: bài không hề nói chiếc bánh nhiều tầng này là sản phẩm bán chạy nhất, trái lại nó là bánh đặt riêng (\"custom-baked\") mới được làm thử mẫu trong ngày.\n- (B) Bẫy so sánh cực đại không căn cứ: e-mail chỉ nhắc đến việc xuất hóa đơn ngày 28/3 (\"You will be billed on March 28\"), tuyệt đối không đề cập giá tiền hay chiếc bánh đắt nhất.\n- (C) Bẫy đánh tráo mốc lặp lại: dù Esplin Electronics đặt hàng của tiệm 4 năm liên tiếp, bài không nói năm nào họ cũng đặt chiếc bánh nhiều tầng này mà nhấn mạnh nó được làm theo yêu cầu riêng lần này.","lines":[{"speaker":"Document 1 — E-mail","en":"To: Camille Ayala <ayala@esplinelectronics.com>","vi":"Đến: Camille Ayala <ayala@esplinelectronics.com>","units":[{"en":"To: Camille Ayala <ayala@esplinelectronics.com>","vi":"Đến: Camille Ayala <ayala@esplinelectronics.com>"}]},{"speaker":"","en":"From: Masae Adachi <madachi@sweeterspecialties.com>","vi":"Từ: Masae Adachi <madachi@sweeterspecialties.com>","units":[{"en":"From: Masae Adachi <madachi@sweeterspecialties.com>","vi":"Từ: Masae Adachi <madachi@sweeterspecialties.com>"}]},{"speaker":"","en":"Date: February 12","vi":"Ngày: 12 tháng 2","units":[{"en":"Date: February 12","vi":"Ngày: 12 tháng 2"}]},{"speaker":"","en":"Subject: Event order","vi":"Chủ đề: Đơn đặt hàng sự kiện","units":[{"en":"Subject: Event order","vi":"Chủ đề: Đơn đặt hàng sự kiện"}]},{"speaker":"","en":"Attachment: Sweeter Specialties Request Form","vi":"Tệp đính kèm: Phiếu yêu cầu của Sweeter Specialties","units":[{"en":"Attachment: Sweeter Specialties Request Form","vi":"Tệp đính kèm: Phiếu yêu cầu của Sweeter Specialties"}]},{"speaker":"","en":"Dear Ms. Ayala,","vi":"Kính gửi bà Ayala,","units":[{"en":"Dear Ms. Ayala,","vi":"Kính gửi bà Ayala,"}]},{"speaker":"","en":"Thank you for selecting our business to provide baked goods for the Esplin Electronics conference event in March. We are honored that you chose us for a fourth year in a row! On March 29, we will provide a large vanilla cake for each of the ten venues you indicated, and we will deliver a custom-baked multilayer cake on the following day. You will be billed on March 28. Please review the attached order form and return it to me within seven days.","vi":"Cảm ơn bà đã lựa chọn cửa hàng chúng tôi cung cấp các loại bánh nướng cho sự kiện hội nghị của Esplin Electronics vào tháng 3 tới. Chúng tôi vô cùng vinh dự khi được bà tin chọn năm thứ tư liên tiếp! Vào ngày 29 tháng 3, chúng tôi sẽ cung cấp một chiếc bánh vani cỡ lớn cho từng địa điểm trong số mười địa điểm bà đã chỉ định, và vào ngày hôm sau chúng tôi sẽ giao một chiếc bánh nhiều tầng nướng theo yêu cầu riêng. Hóa đơn thanh toán sẽ được xuất cho bà vào ngày 28 tháng 3. Vui lòng xem lại phiếu đặt hàng đính kèm và gửi lại cho tôi trong vòng bảy ngày.","units":[{"en":"Thank you for selecting our business to provide baked goods for the Esplin Electronics conference event in March.","vi":"Cảm ơn bà đã lựa chọn cửa hàng chúng tôi cung cấp các loại bánh nướng cho sự kiện hội nghị của Esplin Electronics vào tháng 3 tới."},{"en":"We are honored that you chose us for a fourth year in a row!","vi":"Chúng tôi vô cùng vinh dự khi được bà tin chọn năm thứ tư liên tiếp!"},{"en":"On March 29, we will provide a large vanilla cake for each of the ten venues you indicated, and we will deliver a custom-baked multilayer cake on the following day.","vi":"Vào ngày 29 tháng 3, chúng tôi sẽ cung cấp một chiếc bánh vani cỡ lớn cho từng địa điểm trong số mười địa điểm bà đã chỉ định, và vào ngày hôm sau chúng tôi sẽ giao một chiếc bánh nhiều tầng nướng theo yêu cầu riêng."},{"en":"You will be billed on March 28.","vi":"Hóa đơn thanh toán sẽ được xuất cho bà vào ngày 28 tháng 3."},{"en":"Please review the attached order form and return it to me within seven days.","vi":"Vui lòng xem lại phiếu đặt hàng đính kèm và gửi lại cho tôi trong vòng bảy ngày."}]},{"speaker":"","en":"Regarding the cake you ordered for March 30, our head pastry chef will produce it according to your specifications. In fact, he created a sample of the complete recipe earlier today—almond crème cake with fresh raspberry filling. We have judged it to be a delectable treat, and we are sure that you will be pleased.","vi":"Về chiếc bánh bà đặt cho ngày 30 tháng 3, bếp trưởng bánh ngọt của chúng tôi sẽ thực hiện đúng theo các yêu cầu chi tiết của bà. Thực tế, đầu ngày hôm nay anh ấy đã làm thử một mẫu theo công thức hoàn chỉnh—bánh kem hạnh nhân với nhân quả mâm xôi tươi. Chúng tôi đánh giá đây là một món bánh tuyệt hảo và chắc chắn bà sẽ hài lòng.","units":[{"en":"Regarding the cake you ordered for March 30, our head pastry chef will produce it according to your specifications.","vi":"Về chiếc bánh bà đặt cho ngày 30 tháng 3, bếp trưởng bánh ngọt của chúng tôi sẽ thực hiện đúng theo các yêu cầu chi tiết của bà."},{"en":"In fact, he created a sample of the complete recipe earlier today—almond crème cake with fresh raspberry filling.","vi":"Thực tế, đầu ngày hôm nay anh ấy đã làm thử một mẫu theo công thức hoàn chỉnh—bánh kem hạnh nhân với nhân quả mâm xôi tươi."},{"en":"We have judged it to be a delectable treat, and we are sure that you will be pleased.","vi":"Chúng tôi đánh giá đây là một món bánh tuyệt hảo và chắc chắn bà sẽ hài lòng."}]},{"speaker":"","en":"If you have any concerns, just send me an e-mail. As always, we value your business.","vi":"Nếu bà có bất kỳ băn khoăn nào, chỉ cần gửi e-mail cho tôi. Như mọi khi, chúng tôi luôn trân trọng sự tin tưởng và hợp tác của bà.","units":[{"en":"If you have any concerns, just send me an e-mail.","vi":"Nếu bà có bất kỳ băn khoăn nào, chỉ cần gửi e-mail cho tôi."},{"en":"As always, we value your business.","vi":"Như mọi khi, chúng tôi luôn trân trọng sự tin tưởng và hợp tác của bà."}]},{"speaker":"","en":"Masae Adachi, Owner","vi":"Masae Adachi, Chủ sở hữu","units":[{"en":"Masae Adachi, Owner","vi":"Masae Adachi, Chủ sở hữu"}]},{"speaker":"","en":"Sweeter Specialties","vi":"Sweeter Specialties","units":[{"en":"Sweeter Specialties","vi":"Sweeter Specialties"}]}],"vocab":[{"word":"custom-baked","pos":"adj","ipa":"/ˈkʌstəm beɪkt/","meaning":"được nướng làm riêng theo yêu cầu"},{"word":"specification","pos":"n","ipa":"/ˌspesɪfɪˈkeɪʃən/","meaning":"yêu cầu chi tiết, thông số đặt hàng"},{"word":"pastry chef","pos":"n","ipa":"/ˈpeɪstri ʃef/","meaning":"đầu bếp làm bánh ngọt"},{"word":"recipe","pos":"n","ipa":"/ˈresəpi/","meaning":"công thức làm bánh/nấu ăn"}],"isScanBacked":false,"docTypeLabel":"e-mail","context":"E-mail from Masae Adachi at Sweeter Specialties to Camille Ayala regarding an event cake order","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 (Chi tiết Sản phẩm Đặt riêng — Dạng 23 & 27): Ghép cụm 'custom-baked multilayer cake' với chi tiết đầu bếp phải làm thử công thức theo yêu cầu riêng ('created a sample') -> Kết luận công thức hương vị mới.","optionAnalysis":{"A":"Không có dẫn chứng: Bánh nhiều tầng được nướng theo yêu cầu riêng ('custom-baked'), bài không hề mô tả đây là sản phẩm bán chạy nhất của tiệm.","B":"So sánh sai sự thật: E-mail không nhắc đến giá bán của bất kỳ loại bánh nào nên không có cơ sở kết luận đây là bánh đắt nhất.","C":"Đánh tráo thông tin 4 năm: Hãng đặt hàng 4 năm liên tiếp nhưng không có chi tiết chiếc bánh nhiều tầng đặc biệt này được nướng hằng năm.","D":"Chính xác: Chi tiết 'custom-baked', làm theo 'specifications' và bếp trưởng phải 'created a sample of the complete recipe earlier today' (kem hạnh nhân nhân mâm xôi) chứng tỏ đây là sự kết hợp hương vị mới."},"evDocIdx":0,"evTargets":[{"badge":"Câu 163 · Đáp án D","opt":"D","isCorrect":true,"quote":"Regarding the cake you ordered for March 30, our head pastry chef will produce it according to your specifications.","viQuote":"Về chiếc bánh bà đặt cho ngày 30 tháng 3, bếp trưởng bánh ngọt của chúng tôi sẽ thực hiện đúng theo các yêu cầu chi tiết của bà."},{"badge":"Câu 163 · Đáp án D","opt":"D","isCorrect":true,"quote":"In fact, he created a sample of the complete recipe earlier today—almond crème cake with fresh raspberry filling.","viQuote":"Thực tế, đầu ngày hôm nay anh ấy đã làm thử một mẫu theo công thức hoàn chỉnh—bánh kem hạnh nhân với nhân quả mâm xôi tươi."}],"evQuotes":["Regarding the cake you ordered for March 30, our head pastry chef will produce it according to your specifications.","In fact, he created a sample of the complete recipe earlier today—almond crème cake with fresh raspberry filling."]},{"q":164,"part":7,"group_id":"E25_T01_G161_164","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc14.webp"],"stem_en":"The word \"judged\" in paragraph 2, line 3, is closest in meaning to","stem_vi":"Từ \"judged\" trong đoạn 2, dòng 3 gần nghĩa nhất với","options":{"A":{"en":"criticized","vi":"chỉ trích, phê bình"},"B":{"en":"settled","vi":"giải quyết, ổn định"},"C":{"en":"determined","vi":"xác định, kết luận"},"D":{"en":"described","vi":"mô tả"}},"ans":"C","evidence_quote":"We have judged it to be a delectable treat, and we are sure that you will be pleased.","explanation":"Đáp án đúng: (C) determined (xác định, đánh giá / kết luận) — trong ngữ cảnh nếm thử mẫu bánh mới, \"judged it to be a delectable treat\" có nghĩa là tiệm bánh đã đánh giá, xác định món bánh rất ngon.\nDẫn chứng: \"We have judged it to be a delectable treat, and we are sure that you will be pleased.\" (Thay \"determined\" vào vị trí \"judged\": \"We have determined it to be a delectable treat\" giữ nguyên sắc thái đi đến kết luận đánh giá tích cực).\nPhân tích bẫy:\n- (A) Bẫy nghĩa trái chiều: \"criticized\" (chỉ trích, phê bình) mang nghĩa tiêu cực, hoàn toàn mâu thuẫn với cụm \"delectable treat\" (món ngon tuyệt hảo) và sự tự tin khách sẽ hài lòng.\n- (B) Bẫy nghĩa từ điển khác ngữ cảnh: \"settled\" (giải quyết tranh chấp hoặc ổn định chỗ ở) không đi với cấu trúc \"sth to be a treat\" để diễn đạt sự đánh giá chất lượng.\n- (D) Bẫy lệch sắc thái động từ: \"described\" (mô tả, miêu tả) không diễn đạt hành động đưa ra phán quyết hay nhận định chất lượng như \"judged / determined it to be\".","lines":[{"speaker":"Document 1 — E-mail","en":"To: Camille Ayala <ayala@esplinelectronics.com>","vi":"Đến: Camille Ayala <ayala@esplinelectronics.com>","units":[{"en":"To: Camille Ayala <ayala@esplinelectronics.com>","vi":"Đến: Camille Ayala <ayala@esplinelectronics.com>"}]},{"speaker":"","en":"From: Masae Adachi <madachi@sweeterspecialties.com>","vi":"Từ: Masae Adachi <madachi@sweeterspecialties.com>","units":[{"en":"From: Masae Adachi <madachi@sweeterspecialties.com>","vi":"Từ: Masae Adachi <madachi@sweeterspecialties.com>"}]},{"speaker":"","en":"Date: February 12","vi":"Ngày: 12 tháng 2","units":[{"en":"Date: February 12","vi":"Ngày: 12 tháng 2"}]},{"speaker":"","en":"Subject: Event order","vi":"Chủ đề: Đơn đặt hàng sự kiện","units":[{"en":"Subject: Event order","vi":"Chủ đề: Đơn đặt hàng sự kiện"}]},{"speaker":"","en":"Attachment: Sweeter Specialties Request Form","vi":"Tệp đính kèm: Phiếu yêu cầu của Sweeter Specialties","units":[{"en":"Attachment: Sweeter Specialties Request Form","vi":"Tệp đính kèm: Phiếu yêu cầu của Sweeter Specialties"}]},{"speaker":"","en":"Dear Ms. Ayala,","vi":"Kính gửi bà Ayala,","units":[{"en":"Dear Ms. Ayala,","vi":"Kính gửi bà Ayala,"}]},{"speaker":"","en":"Thank you for selecting our business to provide baked goods for the Esplin Electronics conference event in March. We are honored that you chose us for a fourth year in a row! On March 29, we will provide a large vanilla cake for each of the ten venues you indicated, and we will deliver a custom-baked multilayer cake on the following day. You will be billed on March 28. Please review the attached order form and return it to me within seven days.","vi":"Cảm ơn bà đã lựa chọn cửa hàng chúng tôi cung cấp các loại bánh nướng cho sự kiện hội nghị của Esplin Electronics vào tháng 3 tới. Chúng tôi vô cùng vinh dự khi được bà tin chọn năm thứ tư liên tiếp! Vào ngày 29 tháng 3, chúng tôi sẽ cung cấp một chiếc bánh vani cỡ lớn cho từng địa điểm trong số mười địa điểm bà đã chỉ định, và vào ngày hôm sau chúng tôi sẽ giao một chiếc bánh nhiều tầng nướng theo yêu cầu riêng. Hóa đơn thanh toán sẽ được xuất cho bà vào ngày 28 tháng 3. Vui lòng xem lại phiếu đặt hàng đính kèm và gửi lại cho tôi trong vòng bảy ngày.","units":[{"en":"Thank you for selecting our business to provide baked goods for the Esplin Electronics conference event in March.","vi":"Cảm ơn bà đã lựa chọn cửa hàng chúng tôi cung cấp các loại bánh nướng cho sự kiện hội nghị của Esplin Electronics vào tháng 3 tới."},{"en":"We are honored that you chose us for a fourth year in a row!","vi":"Chúng tôi vô cùng vinh dự khi được bà tin chọn năm thứ tư liên tiếp!"},{"en":"On March 29, we will provide a large vanilla cake for each of the ten venues you indicated, and we will deliver a custom-baked multilayer cake on the following day.","vi":"Vào ngày 29 tháng 3, chúng tôi sẽ cung cấp một chiếc bánh vani cỡ lớn cho từng địa điểm trong số mười địa điểm bà đã chỉ định, và vào ngày hôm sau chúng tôi sẽ giao một chiếc bánh nhiều tầng nướng theo yêu cầu riêng."},{"en":"You will be billed on March 28.","vi":"Hóa đơn thanh toán sẽ được xuất cho bà vào ngày 28 tháng 3."},{"en":"Please review the attached order form and return it to me within seven days.","vi":"Vui lòng xem lại phiếu đặt hàng đính kèm và gửi lại cho tôi trong vòng bảy ngày."}]},{"speaker":"","en":"Regarding the cake you ordered for March 30, our head pastry chef will produce it according to your specifications. In fact, he created a sample of the complete recipe earlier today—almond crème cake with fresh raspberry filling. We have judged it to be a delectable treat, and we are sure that you will be pleased.","vi":"Về chiếc bánh bà đặt cho ngày 30 tháng 3, bếp trưởng bánh ngọt của chúng tôi sẽ thực hiện đúng theo các yêu cầu chi tiết của bà. Thực tế, đầu ngày hôm nay anh ấy đã làm thử một mẫu theo công thức hoàn chỉnh—bánh kem hạnh nhân với nhân quả mâm xôi tươi. Chúng tôi đánh giá đây là một món bánh tuyệt hảo và chắc chắn bà sẽ hài lòng.","units":[{"en":"Regarding the cake you ordered for March 30, our head pastry chef will produce it according to your specifications.","vi":"Về chiếc bánh bà đặt cho ngày 30 tháng 3, bếp trưởng bánh ngọt của chúng tôi sẽ thực hiện đúng theo các yêu cầu chi tiết của bà."},{"en":"In fact, he created a sample of the complete recipe earlier today—almond crème cake with fresh raspberry filling.","vi":"Thực tế, đầu ngày hôm nay anh ấy đã làm thử một mẫu theo công thức hoàn chỉnh—bánh kem hạnh nhân với nhân quả mâm xôi tươi."},{"en":"We have judged it to be a delectable treat, and we are sure that you will be pleased.","vi":"Chúng tôi đánh giá đây là một món bánh tuyệt hảo và chắc chắn bà sẽ hài lòng."}]},{"speaker":"","en":"If you have any concerns, just send me an e-mail. As always, we value your business.","vi":"Nếu bà có bất kỳ băn khoăn nào, chỉ cần gửi e-mail cho tôi. Như mọi khi, chúng tôi luôn trân trọng sự tin tưởng và hợp tác của bà.","units":[{"en":"If you have any concerns, just send me an e-mail.","vi":"Nếu bà có bất kỳ băn khoăn nào, chỉ cần gửi e-mail cho tôi."},{"en":"As always, we value your business.","vi":"Như mọi khi, chúng tôi luôn trân trọng sự tin tưởng và hợp tác của bà."}]},{"speaker":"","en":"Masae Adachi, Owner","vi":"Masae Adachi, Chủ sở hữu","units":[{"en":"Masae Adachi, Owner","vi":"Masae Adachi, Chủ sở hữu"}]},{"speaker":"","en":"Sweeter Specialties","vi":"Sweeter Specialties","units":[{"en":"Sweeter Specialties","vi":"Sweeter Specialties"}]}],"vocab":[{"word":"judge","pos":"v","ipa":"/dʒʌdʒ/","meaning":"đánh giá, nhận định, kết luận"},{"word":"delectable","pos":"adj","ipa":"/dɪˈlektəbəl/","meaning":"thơm ngon tuyệt hảo"},{"word":"determine","pos":"v","ipa":"/dɪˈtɜːrmɪn/","meaning":"xác định, kết luận"},{"word":"concern","pos":"n","ipa":"/kənˈsɜːrn/","meaning":"mối băn khoăn, điều lo ngại"}],"isScanBacked":false,"docTypeLabel":"e-mail","context":"E-mail from Masae Adachi at Sweeter Specialties to Camille Ayala regarding an event cake order","grammarType":"Part 7 — Từ vựng trong ngữ cảnh (Vocabulary in Context)","formula":"CÔNG THỨC PART 7 (Từ đồng nghĩa theo Ngữ cảnh — Dạng 28): Thay thử cả 4 phương án vào câu 'We have [judged] it to be a delectable treat' -> Cấu trúc 'judge/determine sth to be + N' mang nghĩa đánh giá, xác định.","optionAnalysis":{"A":"Trái nghĩa ngữ cảnh: 'criticized' (chỉ trích) mang nghĩa chê bai, đối lập hoàn toàn với lời khen 'delectable treat' ngay phía sau.","B":"Sai nghĩa và cấu trúc: 'settled' nghĩa là giải quyết hoặc ổn định, không diễn đạt hành động nếm thử và đánh giá món bánh.","C":"Chính xác: 'determined' (xác định, đi đến kết luận) khớp cả về nghĩa đánh giá chất lượng lẫn cấu trúc 'determine sth to be + N'.","D":"Lệch nghĩa và cấu trúc: 'described' chỉ việc tường thuật lại đặc điểm, không mang sắc thái đưa ra nhận định hay đánh giá như 'judged'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 164 · Đáp án C","opt":"C","isCorrect":true,"quote":"We have judged it to be a delectable treat, and we are sure that you will be pleased.","viQuote":"Chúng tôi đánh giá đây là một món bánh tuyệt hảo và chắc chắn bà sẽ hài lòng."}],"evQuotes":["We have judged it to be a delectable treat, and we are sure that you will be pleased."]},{"q":165,"part":7,"group_id":"E25_T01_G165_167","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc15.webp"],"stem_en":"Why did Ms. Yakovleva choose the Dish Magic 300 dishwasher?","stem_vi":"Tại sao bà Yakovleva lại chọn máy rửa bát Dish Magic 300?","options":{"A":{"en":"It was less expensive than most models.","vi":"Nó có giá rẻ hơn hầu hết các mẫu máy khác."},"B":{"en":"It was the largest model available.","vi":"Đây là mẫu máy có kích thước lớn nhất hiện có."},"C":{"en":"It was rated very highly.","vi":"Nó nhận được đánh giá rất cao."},"D":{"en":"It was the same brand as her other appliances.","vi":"Nó cùng thương hiệu với các thiết bị gia dụng khác của bà ấy."}},"ans":"C","evidence_quote":"I did a lot of research, and the Dish Magic 300 seemed to be the best choice. It was pricier than other models, but all of the reviews were excellent.","explanation":"Đáp án đúng: (C) Nó nhận được đánh giá rất cao — bà Yakovleva chấp nhận chi thêm tiền chọn Dish Magic 300 vì mọi đánh giá về mẫu máy này đều xuất sắc.\nDẫn chứng: \"I did a lot of research, and the Dish Magic 300 seemed to be the best choice. It was pricier than other models, but all of the reviews were excellent.\" (Paraphrase: \"all of the reviews were excellent\" tương đương \"rated very highly\").\nPhân tích bẫy:\n- (A) Bẫy ngược nghĩa: bài viết nói rõ máy này \"pricier than other models\" (đắt hơn các mẫu khác), nên việc nói nó rẻ hơn hầu hết các mẫu là hoàn toàn sai.\n- (B) Bẫy ngược nghĩa kích thước: bà ấy chọn một chiếc máy nhỏ gọn (\"compact dishwasher\") vì căn bếp mới chỉ đủ chỗ cho cỡ nhỏ, không phải mẫu lớn nhất.\n- (D) Bẫy suy diễn không có trong bài: bà viết \"I never had a dishwasher before\" và hoàn toàn không nhắc tới thương hiệu của các thiết bị gia dụng khác trong nhà.","lines":[{"speaker":"Document 1 — Review","en":"Great Dishwasher!","vi":"Chiếc máy rửa bát tuyệt vời!","units":[{"en":"Great Dishwasher!","vi":"Chiếc máy rửa bát tuyệt vời!"}]},{"speaker":"","en":"I never had a dishwasher before. After remodeling my kitchen, I finally had room for a compact dishwasher. I did a lot of research, and the Dish Magic 300 seemed to be the best choice. It was pricier than other models, but all of the reviews were excellent. So, I decided to spend the extra money. I have had the dishwasher for one month now, and I could not be happier with my decision. Most importantly, the dishes come out sparkling clean, no matter how dirty they were going in. Also, the machine is so quiet, you do not even know it is running. Lastly, it is designed to use water efficiently, which is very important to me. Overall, I am very pleased with this dishwasher.","vi":"Trước đây tôi chưa từng sử dụng máy rửa bát. Sau khi cải tạo lại căn bếp, cuối cùng tôi cũng có đủ không gian cho một chiếc máy rửa bát nhỏ gọn. Tôi đã tìm hiểu rất kỹ và mẫu Dish Magic 300 dường như là lựa chọn tốt nhất. Mẫu này có giá cao hơn các dòng máy khác, nhưng tất cả các đánh giá đều xuất sắc. Vì vậy, tôi quyết định chi thêm tiền để mua. Tính đến nay tôi đã dùng chiếc máy rửa bát này được một tháng và không thể hài lòng hơn với quyết định của mình. Quan trọng nhất là bát đĩa rửa xong sạch bóng loáng, bất kể trước khi cho vào máy chúng bẩn đến mức nào. Ngoài ra, máy vận hành êm đến mức bạn thậm chí không nhận ra nó đang chạy. Cuối cùng, máy được thiết kế sử dụng nước tiết kiệm và hiệu quả, điều này rất quan trọng đối với tôi. Nhìn chung, tôi vô cùng hài lòng với chiếc máy rửa bát này.","units":[{"en":"I never had a dishwasher before.","vi":"Trước đây tôi chưa từng sử dụng máy rửa bát."},{"en":"After remodeling my kitchen, I finally had room for a compact dishwasher.","vi":"Sau khi cải tạo lại căn bếp, cuối cùng tôi cũng có đủ không gian cho một chiếc máy rửa bát nhỏ gọn."},{"en":"I did a lot of research, and the Dish Magic 300 seemed to be the best choice.","vi":"Tôi đã tìm hiểu rất kỹ và mẫu Dish Magic 300 dường như là lựa chọn tốt nhất."},{"en":"It was pricier than other models, but all of the reviews were excellent.","vi":"Mẫu này có giá cao hơn các dòng máy khác, nhưng tất cả các đánh giá đều xuất sắc."},{"en":"So, I decided to spend the extra money.","vi":"Vì vậy, tôi quyết định chi thêm tiền để mua."},{"en":"I have had the dishwasher for one month now, and I could not be happier with my decision.","vi":"Tính đến nay tôi đã dùng chiếc máy rửa bát này được một tháng và không thể hài lòng hơn với quyết định của mình."},{"en":"Most importantly, the dishes come out sparkling clean, no matter how dirty they were going in.","vi":"Quan trọng nhất là bát đĩa rửa xong sạch bóng loáng, bất kể trước khi cho vào máy chúng bẩn đến mức nào."},{"en":"Also, the machine is so quiet, you do not even know it is running.","vi":"Ngoài ra, máy vận hành êm đến mức bạn thậm chí không nhận ra nó đang chạy."},{"en":"Lastly, it is designed to use water efficiently, which is very important to me.","vi":"Cuối cùng, máy được thiết kế sử dụng nước tiết kiệm và hiệu quả, điều này rất quan trọng đối với tôi."},{"en":"Overall, I am very pleased with this dishwasher.","vi":"Nhìn chung, tôi vô cùng hài lòng với chiếc máy rửa bát này."}]},{"speaker":"","en":"— Anna Yakovleva","vi":"— Anna Yakovleva","units":[{"en":"— Anna Yakovleva","vi":"— Anna Yakovleva"}]}],"vocab":[{"word":"remodel","pos":"v","ipa":"/ˌriːˈmɑːdəl/","meaning":"cải tạo, sửa sang lại"},{"word":"compact","pos":"adj","ipa":"/kəmˈpækt/","meaning":"nhỏ gọn, tiết kiệm không gian"},{"word":"pricey","pos":"adj","ipa":"/ˈpraɪsi/","meaning":"đắt đỏ, có giá cao"},{"word":"excellent","pos":"adj","ipa":"/ˈeksələnt/","meaning":"xuất sắc, tuyệt vời"}],"isScanBacked":false,"docTypeLabel":"review","context":"Customer review of the Dish Magic 300 dishwasher by Anna Yakovleva","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 (Câu hỏi Lý do — Dạng 25): Tìm từ khóa lý do chọn mua ('best choice', 'So, I decided') -> Paraphrase 'all of the reviews were excellent' thành 'rated very highly'.","optionAnalysis":{"A":"Ngược thông tin giá cả: Văn bản nêu rõ 'It was pricier than other models' (đắt hơn các mẫu khác), trái ngược với 'less expensive'.","B":"Ngược thông tin kích thước: Tác giả tìm mua 'a compact dishwasher' (máy nhỏ gọn), không phải mẫu lớn nhất hiện có.","C":"Chính xác: Cụm 'all of the reviews were excellent' (tất cả đánh giá đều xuất sắc) được paraphrase chính xác thành 'rated very highly'.","D":"Thông tin không có trong bài: Bài đánh giá không hề đề cập đến thương hiệu của các thiết bị gia dụng khác mà bà Yakovleva sở hữu."},"evDocIdx":0,"evTargets":[{"badge":"Câu 165 · Đáp án C","opt":"C","isCorrect":true,"quote":"I did a lot of research, and the Dish Magic 300 seemed to be the best choice.","viQuote":"Tôi đã tìm hiểu rất kỹ và mẫu Dish Magic 300 dường như là lựa chọn tốt nhất."},{"badge":"Câu 165 · Đáp án C","opt":"C","isCorrect":true,"quote":"It was pricier than other models, but all of the reviews were excellent.","viQuote":"Mẫu này có giá cao hơn các dòng máy khác, nhưng tất cả các đánh giá đều xuất sắc."}],"evQuotes":["I did a lot of research, and the Dish Magic 300 seemed to be the best choice.","It was pricier than other models, but all of the reviews were excellent."]},{"q":166,"part":7,"group_id":"E25_T01_G165_167","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc15.webp"],"stem_en":"The word \"running\" in paragraph 1, line 7, is closest in meaning to","stem_vi":"Từ \"running\" trong đoạn 1, dòng 7 gần nghĩa nhất với","options":{"A":{"en":"adjusting","vi":"điều chỉnh"},"B":{"en":"controlling","vi":"kiểm soát, điều khiển"},"C":{"en":"moving","vi":"di chuyển"},"D":{"en":"operating","vi":"hoạt động, vận hành"}},"ans":"D","evidence_quote":"Also, the machine is so quiet, you do not even know it is running.","explanation":"Đáp án đúng: (D) operating (hoạt động, vận hành) — với chủ ngữ là chiếc máy rửa bát (\"the machine\"), \"it is running\" diễn tả máy đang chạy/vận hành êm đến mức không nghe thấy tiếng.\nDẫn chứng: \"Also, the machine is so quiet, you do not even know it is running.\" (Thay thế \"operating\" vào câu: \"you do not even know it is operating\" giữ nguyên nghĩa máy đang vận hành).\nPhân tích bẫy:\n- (A) Bẫy lệch nghĩa động từ: \"adjusting\" (điều chỉnh, chỉnh sửa) thường dùng cho hành động của người dùng điều chỉnh thông số, không mô tả trạng thái máy đang chạy êm.\n- (B) Bẫy lệch nghĩa động từ: \"controlling\" (kiểm soát, điều khiển) mang nghĩa chủ động tác động lên vật khác, không phù hợp khi nói chiếc máy rửa bát tự hoạt động.\n- (C) Bẫy nghĩa đen của 'run': \"moving\" (di chuyển vị trí) là nghĩa thông thường khi người hoặc xe chạy, nhưng máy rửa bát đặt cố định trong bếp thì không di chuyển.","lines":[{"speaker":"Document 1 — Review","en":"Great Dishwasher!","vi":"Chiếc máy rửa bát tuyệt vời!","units":[{"en":"Great Dishwasher!","vi":"Chiếc máy rửa bát tuyệt vời!"}]},{"speaker":"","en":"I never had a dishwasher before. After remodeling my kitchen, I finally had room for a compact dishwasher. I did a lot of research, and the Dish Magic 300 seemed to be the best choice. It was pricier than other models, but all of the reviews were excellent. So, I decided to spend the extra money. I have had the dishwasher for one month now, and I could not be happier with my decision. Most importantly, the dishes come out sparkling clean, no matter how dirty they were going in. Also, the machine is so quiet, you do not even know it is running. Lastly, it is designed to use water efficiently, which is very important to me. Overall, I am very pleased with this dishwasher.","vi":"Trước đây tôi chưa từng sử dụng máy rửa bát. Sau khi cải tạo lại căn bếp, cuối cùng tôi cũng có đủ không gian cho một chiếc máy rửa bát nhỏ gọn. Tôi đã tìm hiểu rất kỹ và mẫu Dish Magic 300 dường như là lựa chọn tốt nhất. Mẫu này có giá cao hơn các dòng máy khác, nhưng tất cả các đánh giá đều xuất sắc. Vì vậy, tôi quyết định chi thêm tiền để mua. Tính đến nay tôi đã dùng chiếc máy rửa bát này được một tháng và không thể hài lòng hơn với quyết định của mình. Quan trọng nhất là bát đĩa rửa xong sạch bóng loáng, bất kể trước khi cho vào máy chúng bẩn đến mức nào. Ngoài ra, máy vận hành êm đến mức bạn thậm chí không nhận ra nó đang chạy. Cuối cùng, máy được thiết kế sử dụng nước tiết kiệm và hiệu quả, điều này rất quan trọng đối với tôi. Nhìn chung, tôi vô cùng hài lòng với chiếc máy rửa bát này.","units":[{"en":"I never had a dishwasher before.","vi":"Trước đây tôi chưa từng sử dụng máy rửa bát."},{"en":"After remodeling my kitchen, I finally had room for a compact dishwasher.","vi":"Sau khi cải tạo lại căn bếp, cuối cùng tôi cũng có đủ không gian cho một chiếc máy rửa bát nhỏ gọn."},{"en":"I did a lot of research, and the Dish Magic 300 seemed to be the best choice.","vi":"Tôi đã tìm hiểu rất kỹ và mẫu Dish Magic 300 dường như là lựa chọn tốt nhất."},{"en":"It was pricier than other models, but all of the reviews were excellent.","vi":"Mẫu này có giá cao hơn các dòng máy khác, nhưng tất cả các đánh giá đều xuất sắc."},{"en":"So, I decided to spend the extra money.","vi":"Vì vậy, tôi quyết định chi thêm tiền để mua."},{"en":"I have had the dishwasher for one month now, and I could not be happier with my decision.","vi":"Tính đến nay tôi đã dùng chiếc máy rửa bát này được một tháng và không thể hài lòng hơn với quyết định của mình."},{"en":"Most importantly, the dishes come out sparkling clean, no matter how dirty they were going in.","vi":"Quan trọng nhất là bát đĩa rửa xong sạch bóng loáng, bất kể trước khi cho vào máy chúng bẩn đến mức nào."},{"en":"Also, the machine is so quiet, you do not even know it is running.","vi":"Ngoài ra, máy vận hành êm đến mức bạn thậm chí không nhận ra nó đang chạy."},{"en":"Lastly, it is designed to use water efficiently, which is very important to me.","vi":"Cuối cùng, máy được thiết kế sử dụng nước tiết kiệm và hiệu quả, điều này rất quan trọng đối với tôi."},{"en":"Overall, I am very pleased with this dishwasher.","vi":"Nhìn chung, tôi vô cùng hài lòng với chiếc máy rửa bát này."}]},{"speaker":"","en":"— Anna Yakovleva","vi":"— Anna Yakovleva","units":[{"en":"— Anna Yakovleva","vi":"— Anna Yakovleva"}]}],"vocab":[{"word":"run","pos":"v","ipa":"/rʌn/","meaning":"vận hành, hoạt động (máy móc)"},{"word":"operate","pos":"v","ipa":"/ˈɑːpəreɪt/","meaning":"vận hành, chạy"},{"word":"sparkling","pos":"adj","ipa":"/ˈspɑːrklɪŋ/","meaning":"sạch bóng loáng, lấp lánh"}],"isScanBacked":false,"docTypeLabel":"review","context":"Customer review of the Dish Magic 300 dishwasher by Anna Yakovleva","grammarType":"Part 7 — Từ vựng trong ngữ cảnh (Vocabulary in Context)","formula":"CÔNG THỨC PART 7 (Từ vựng Đa nghĩa về Thiết bị — Dạng 28): Khi chủ ngữ là máy móc ('the machine is so quiet'), 'is running' mang nghĩa đang vận hành -> Chọn 'operating'.","optionAnalysis":{"A":"Sai nghĩa ngữ cảnh: 'adjusting' (điều chỉnh) không thể hiện trạng thái một thiết bị gia dụng đang bật và chạy chu trình rửa.","B":"Sai nghĩa và vai trò: 'controlling' (kiểm soát) không đồng nghĩa với việc chiếc máy đang tự vận hành trong câu.","C":"Bẫy nghĩa đen 'chạy = di chuyển': Máy rửa bát lắp cố định trong bếp, nên 'moving' (dịch chuyển vị trí) sai với ngữ cảnh máy đang hoạt động.","D":"Chính xác: Khi nói về máy móc ('the machine is running'), nghĩa chuẩn là đang vận hành/chạy, đồng nghĩa hoàn toàn với 'operating'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 166 · Đáp án D","opt":"D","isCorrect":true,"quote":"Also, the machine is so quiet, you do not even know it is running.","viQuote":"Ngoài ra, máy vận hành êm đến mức bạn thậm chí không nhận ra nó đang chạy."}],"evQuotes":["Also, the machine is so quiet, you do not even know it is running."]},{"q":167,"part":7,"group_id":"E25_T01_G165_167","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc15.webp"],"stem_en":"What is indicated about Ms. Yakovleva?","stem_vi":"Điều gì được nêu rõ về bà Yakovleva?","options":{"A":{"en":"She cares about saving water.","vi":"Bà ấy quan tâm đến việc tiết kiệm nước."},"B":{"en":"She recently moved to a new home.","vi":"Gần đây bà ấy mới chuyển đến nhà mới."},"C":{"en":"She bought the dishwasher a year ago.","vi":"Bà ấy đã mua chiếc máy rửa bát này từ một năm trước."},"D":{"en":"She remodels kitchens professionally.","vi":"Bà ấy làm nghề cải tạo nhà bếp chuyên nghiệp."}},"ans":"A","evidence_quote":"Lastly, it is designed to use water efficiently, which is very important to me.","explanation":"Đáp án đúng: (A) Bà ấy quan tâm đến việc tiết kiệm nước — bà Yakovleva nhấn mạnh việc máy rửa bát được thiết kế sử dụng nước hiệu quả là điều rất quan trọng đối với mình.\nDẫn chứng: \"Lastly, it is designed to use water efficiently, which is very important to me.\" (Paraphrase: \"use water efficiently\" + \"very important to me\" = \"cares about saving water\").\nPhân tích bẫy:\n- (B) Bẫy suy diễn sai từ 'remodeling': bài nói bà cải tạo lại nhà bếp (\"remodeling my kitchen\"), chứ không nói bà mới chuyển đến một ngôi nhà mới.\n- (C) Bẫy sai mốc thời gian: bài viết ghi rõ \"I have had the dishwasher for one month now\" (mới dùng được 1 tháng), không phải mua từ một năm trước (\"a year ago\").\n- (D) Bẫy mở rộng quá mức từ 'remodeling': bà tự cải tạo bếp nhà mình (\"my kitchen\"), không có chi tiết nào cho thấy bà làm nghề cải tạo nhà bếp chuyên nghiệp.","lines":[{"speaker":"Document 1 — Review","en":"Great Dishwasher!","vi":"Chiếc máy rửa bát tuyệt vời!","units":[{"en":"Great Dishwasher!","vi":"Chiếc máy rửa bát tuyệt vời!"}]},{"speaker":"","en":"I never had a dishwasher before. After remodeling my kitchen, I finally had room for a compact dishwasher. I did a lot of research, and the Dish Magic 300 seemed to be the best choice. It was pricier than other models, but all of the reviews were excellent. So, I decided to spend the extra money. I have had the dishwasher for one month now, and I could not be happier with my decision. Most importantly, the dishes come out sparkling clean, no matter how dirty they were going in. Also, the machine is so quiet, you do not even know it is running. Lastly, it is designed to use water efficiently, which is very important to me. Overall, I am very pleased with this dishwasher.","vi":"Trước đây tôi chưa từng sử dụng máy rửa bát. Sau khi cải tạo lại căn bếp, cuối cùng tôi cũng có đủ không gian cho một chiếc máy rửa bát nhỏ gọn. Tôi đã tìm hiểu rất kỹ và mẫu Dish Magic 300 dường như là lựa chọn tốt nhất. Mẫu này có giá cao hơn các dòng máy khác, nhưng tất cả các đánh giá đều xuất sắc. Vì vậy, tôi quyết định chi thêm tiền để mua. Tính đến nay tôi đã dùng chiếc máy rửa bát này được một tháng và không thể hài lòng hơn với quyết định của mình. Quan trọng nhất là bát đĩa rửa xong sạch bóng loáng, bất kể trước khi cho vào máy chúng bẩn đến mức nào. Ngoài ra, máy vận hành êm đến mức bạn thậm chí không nhận ra nó đang chạy. Cuối cùng, máy được thiết kế sử dụng nước tiết kiệm và hiệu quả, điều này rất quan trọng đối với tôi. Nhìn chung, tôi vô cùng hài lòng với chiếc máy rửa bát này.","units":[{"en":"I never had a dishwasher before.","vi":"Trước đây tôi chưa từng sử dụng máy rửa bát."},{"en":"After remodeling my kitchen, I finally had room for a compact dishwasher.","vi":"Sau khi cải tạo lại căn bếp, cuối cùng tôi cũng có đủ không gian cho một chiếc máy rửa bát nhỏ gọn."},{"en":"I did a lot of research, and the Dish Magic 300 seemed to be the best choice.","vi":"Tôi đã tìm hiểu rất kỹ và mẫu Dish Magic 300 dường như là lựa chọn tốt nhất."},{"en":"It was pricier than other models, but all of the reviews were excellent.","vi":"Mẫu này có giá cao hơn các dòng máy khác, nhưng tất cả các đánh giá đều xuất sắc."},{"en":"So, I decided to spend the extra money.","vi":"Vì vậy, tôi quyết định chi thêm tiền để mua."},{"en":"I have had the dishwasher for one month now, and I could not be happier with my decision.","vi":"Tính đến nay tôi đã dùng chiếc máy rửa bát này được một tháng và không thể hài lòng hơn với quyết định của mình."},{"en":"Most importantly, the dishes come out sparkling clean, no matter how dirty they were going in.","vi":"Quan trọng nhất là bát đĩa rửa xong sạch bóng loáng, bất kể trước khi cho vào máy chúng bẩn đến mức nào."},{"en":"Also, the machine is so quiet, you do not even know it is running.","vi":"Ngoài ra, máy vận hành êm đến mức bạn thậm chí không nhận ra nó đang chạy."},{"en":"Lastly, it is designed to use water efficiently, which is very important to me.","vi":"Cuối cùng, máy được thiết kế sử dụng nước tiết kiệm và hiệu quả, điều này rất quan trọng đối với tôi."},{"en":"Overall, I am very pleased with this dishwasher.","vi":"Nhìn chung, tôi vô cùng hài lòng với chiếc máy rửa bát này."}]},{"speaker":"","en":"— Anna Yakovleva","vi":"— Anna Yakovleva","units":[{"en":"— Anna Yakovleva","vi":"— Anna Yakovleva"}]}],"vocab":[{"word":"efficiently","pos":"adv","ipa":"/ɪˈfɪʃəntli/","meaning":"một cách hiệu quả, tiết kiệm"},{"word":"overall","pos":"adv","ipa":"/ˌoʊvərˈɔːl/","meaning":"nhìn chung, tổng thể"},{"word":"appliance","pos":"n","ipa":"/əˈplaɪəns/","meaning":"thiết bị gia dụng"}],"isScanBacked":false,"docTypeLabel":"review","context":"Customer review of the Dish Magic 300 dishwasher by Anna Yakovleva","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 (Chi tiết Nhân vật & Paraphrase — Dạng 23): Tìm cụm chỉ thái độ cá nhân ('very important to me') -> Paraphrase 'use water efficiently' thành 'cares about saving water'.","optionAnalysis":{"A":"Chính xác: Câu 'use water efficiently, which is very important to me' (dùng nước hiệu quả là điều rất quan trọng với tôi) khớp nghĩa với 'cares about saving water'.","B":"Suy diễn sai chi tiết: Tác giả chỉ cải tạo lại căn bếp ('remodeling my kitchen'), không nói đã chuyển đến nhà mới.","C":"Bẫy sai đơn vị thời gian: Bài viết nêu 'for one month now' (một tháng), nhưng đáp án đổi thành 'a year ago' (một năm trước).","D":"Bẫy biến tấu nghề nghiệp: Việc bà cải tạo bếp riêng ('my kitchen') không đồng nghĩa bà là thợ cải tạo bếp chuyên nghiệp."},"evDocIdx":0,"evTargets":[{"badge":"Câu 167 · Đáp án A","opt":"A","isCorrect":true,"quote":"Lastly, it is designed to use water efficiently, which is very important to me.","viQuote":"Cuối cùng, máy được thiết kế sử dụng nước tiết kiệm và hiệu quả, điều này rất quan trọng đối với tôi."}],"evQuotes":["Lastly, it is designed to use water efficiently, which is very important to me."]},{"q":168,"part":7,"group_id":"E25_T01_G168_171","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc16.webp"],"stem_en":"For whom is the information intended?","stem_vi":"Thông tin này hướng đến đối tượng nào?","options":{"A":{"en":"Skyler Airlines employees","vi":"Nhân viên của Skyler Airlines"},"B":{"en":"Skyler Airlines customers","vi":"Khách hàng của Skyler Airlines"},"C":{"en":"Potential journal subscribers","vi":"Người đăng ký đặt mua tạp chí tiềm năng"},"D":{"en":"Current job seekers","vi":"Những người hiện đang tìm kiếm việc làm"}},"ans":"D","evidence_quote":"Skyler Airlines employs more than 20,000 people from all over the world. We're growing fast and have many positions available. So regardless of your background, there's probably a place for you on our team.","explanation":"Đáp án đúng: (D) Những người hiện đang tìm kiếm việc làm — đoạn thông tin quảng bá hãng có nhiều vị trí tuyển dụng mở, chào đón mọi nền tảng ứng viên và liệt kê hàng loạt phúc lợi cho nhân viên mới.\nDẫn chứng: \"We're growing fast and have many positions available. So regardless of your background, there's probably a place for you on our team.\" (Lời kêu gọi trực tiếp \"for you on our team\" nhắm vào người đang tìm việc).\nPhân tích bẫy:\n- (A) Bẫy đối tượng ngôi thứ ba: đoạn văn luôn gọi nhân viên hiện tại ở ngôi thứ ba (\"Skyler employees enjoy many perks\", \"enables them to fly\"), chứng tỏ họ không phải người đọc mục tiêu mà là minh chứng phúc lợi để thu hút ứng viên.\n- (B) Bẫy chủ đề ngành hàng không: dù nhắc đến hãng bay và điểm đến (\"destinations\", \"ticket price\"), nội dung xoay quanh tuyển dụng và chế độ đãi ngộ nhân sự, không bán vé cho hành khách.\n- (C) Bẫy nhiễu từ 'Journal': tạp chí Travel Vista Journal chỉ được nhắc ở câu cuối như bên trao danh hiệu \"Best Airline to Work For\", văn bản không hề mời gọi độc giả đặt mua tạp chí.","lines":[{"speaker":"Document 1 — Thông tin","en":"Skyler Airlines employs more than 20,000 people from all over the world. We're growing fast and have many positions available. — [1] —. So regardless of your background, there's probably a place for you on our team. Skyler employees enjoy many perks. — [2] —. For example, our discount program enables them to fly to any of our destinations for a fraction of the average ticket price. — [3] —. We offer upward and global mobility, tuition reimbursement, a mentorship program, and a generous compensation package. — [4] —. Annual paid vacations enable a comfortable work-life balance. It's no wonder that Skyler Airlines was named \"Best Airline to Work For\" by Travel Vista Journal three years in a row.","vi":"Skyler Airlines hiện có đội ngũ hơn 20.000 nhân viên đến từ khắp nơi trên thế giới. Chúng tôi đang phát triển nhanh chóng và có rất nhiều vị trí tuyển dụng đang mở. — [1] —. Vì vậy, bất kể nền tảng chuyên môn của bạn là gì, rất có thể vẫn luôn có một vị trí dành cho bạn trong đội ngũ của chúng tôi. Nhân viên của Skyler được hưởng rất nhiều đặc quyền hấp dẫn. — [2] —. Chẳng hạn, chương trình ưu đãi cho phép họ bay tới bất kỳ điểm đến nào trong mạng lưới của hãng với mức chi phí chỉ bằng một phần nhỏ so với giá vé trung bình. — [3] —. Chúng tôi mang đến cơ hội thăng tiến và luân chuyển công tác toàn cầu, chính sách hoàn trả học phí, chương trình cố vấn nghề nghiệp cùng gói đãi ngộ hào phóng. — [4] —. Chế độ nghỉ phép có hưởng lương hằng năm giúp nhân viên duy trì sự cân bằng thoải mái giữa công việc và cuộc sống. Không có gì ngạc nhiên khi Skyler Airlines được tạp chí Travel Vista Journal bình chọn là \"Hãng hàng không đáng làm việc nhất\" ba năm liên tiếp.","units":[{"en":"Skyler Airlines employs more than 20,000 people from all over the world.","vi":"Skyler Airlines hiện có đội ngũ hơn 20.000 nhân viên đến từ khắp nơi trên thế giới."},{"en":"We're growing fast and have many positions available. — [1] —.","vi":"Chúng tôi đang phát triển nhanh chóng và có rất nhiều vị trí tuyển dụng đang mở. — [1] —."},{"en":"So regardless of your background, there's probably a place for you on our team.","vi":"Vì vậy, bất kể nền tảng chuyên môn của bạn là gì, rất có thể vẫn luôn có một vị trí dành cho bạn trong đội ngũ của chúng tôi."},{"en":"Skyler employees enjoy many perks. — [2] —.","vi":"Nhân viên của Skyler được hưởng rất nhiều đặc quyền hấp dẫn. — [2] —."},{"en":"For example, our discount program enables them to fly to any of our destinations for a fraction of the average ticket price. — [3] —.","vi":"Chẳng hạn, chương trình ưu đãi cho phép họ bay tới bất kỳ điểm đến nào trong mạng lưới của hãng với mức chi phí chỉ bằng một phần nhỏ so với giá vé trung bình. — [3] —."},{"en":"We offer upward and global mobility, tuition reimbursement, a mentorship program, and a generous compensation package. — [4] —.","vi":"Chúng tôi mang đến cơ hội thăng tiến và luân chuyển công tác toàn cầu, chính sách hoàn trả học phí, chương trình cố vấn nghề nghiệp cùng gói đãi ngộ hào phóng. — [4] —."},{"en":"Annual paid vacations enable a comfortable work-life balance.","vi":"Chế độ nghỉ phép có hưởng lương hằng năm giúp nhân viên duy trì sự cân bằng thoải mái giữa công việc và cuộc sống."},{"en":"It's no wonder that Skyler Airlines was named \"Best Airline to Work For\" by Travel Vista Journal three years in a row.","vi":"Không có gì ngạc nhiên khi Skyler Airlines được tạp chí Travel Vista Journal bình chọn là \"Hãng hàng không đáng làm việc nhất\" ba năm liên tiếp."}]}],"vocab":[{"word":"employ","pos":"v","ipa":"/ɪmˈplɔɪ/","meaning":"tuyển dụng, thuê (nhân viên)"},{"word":"position","pos":"n","ipa":"/pəˈzɪʃən/","meaning":"vị trí công việc, chức vụ"},{"word":"regardless of","pos":"prep","ipa":"/rɪˈɡɑːrdləs əv/","meaning":"bất kể, không phụ thuộc vào"},{"word":"background","pos":"n","ipa":"/ˈbækɡraʊnd/","meaning":"nền tảng chuyên môn, kinh nghiệm"}],"isScanBacked":false,"docTypeLabel":"information","context":"Thông tin tuyển dụng và phúc lợi nhân viên của Skyler Airlines","grammarType":"Part 7 — Ý chính, Mục đích & Đối tượng đọc (Main Idea & Purpose)","formula":"CÔNG THỨC PART 7 (Xác định Đối tượng Độc giả — Dạng 22 & 35): Tìm dấu hiệu chiêu mộ ('have many positions available', 'place for you on our team') và cách xưng hô ngôi thứ hai ('your background') -> Chốt ứng viên tìm việc.","optionAnalysis":{"A":"Bẫy sai ngôi xưng hô: Nhân viên Skyler được nhắc bằng ngôi thứ ba ('Skyler employees', 'enables them'), còn người đọc ('your background', 'for you') chính là ứng viên bên ngoài.","B":"Lệch trọng tâm bài viết: Bài giới thiệu cơ hội nghề nghiệp và đãi ngộ nhân sự, không quảng bá dịch vụ bay cho hành khách.","C":"Lặp từ gây nhiễu: 'Travel Vista Journal' chỉ là tờ tạp chí bình chọn hãng hàng không đáng làm việc nhất, không có nội dung mời đăng ký tạp chí.","D":"Chính xác: Các cụm 'have many positions available' và 'a place for you on our team' cùng danh sách phúc lợi hướng thẳng tới người đang tìm việc."},"evDocIdx":0,"evTargets":[{"badge":"Câu 168 · Đáp án D","opt":"D","isCorrect":true,"quote":"We're growing fast and have many positions available.","viQuote":"Chúng tôi đang phát triển nhanh chóng và có rất nhiều vị trí tuyển dụng đang mở."},{"badge":"Câu 168 · Đáp án D","opt":"D","isCorrect":true,"quote":"So regardless of your background, there's probably a place for you on our team.","viQuote":"Vì vậy, bất kể nền tảng chuyên môn của bạn là gì, rất có thể vẫn luôn có một vị trí dành cho bạn trong đội ngũ của chúng tôi."}],"evQuotes":["We're growing fast and have many positions available.","So regardless of your background, there's probably a place for you on our team."]},{"q":169,"part":7,"group_id":"E25_T01_G168_171","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc16.webp"],"stem_en":"In the information, what is NOT mentioned as being offered to employees?","stem_vi":"Trong đoạn thông tin, điều nào KHÔNG được đề cập là được cung cấp cho nhân viên?","options":{"A":{"en":"Payment for educational expenses","vi":"Chi trả chi phí học tập"},"B":{"en":"Free airline tickets","vi":"Vé máy bay miễn phí"},"C":{"en":"Opportunities for mentoring","vi":"Cơ hội tham gia hoạt động cố vấn"},"D":{"en":"Paid days off","vi":"Những ngày nghỉ có hưởng lương"}},"ans":"B","evidence_quote":"- We offer upward and global mobility, tuition reimbursement, a mentorship program, and a generous compensation package. - Annual paid vacations enable a comfortable work- life balance.","explanation":"Đáp án đúng: (B) Vé máy bay miễn phí — nhân viên chỉ được hưởng chương trình giảm giá vé (\"discount program\") với chi phí bằng một phần nhỏ giá vé trung bình, chứ không phải miễn phí hoàn toàn.\nDẫn chứng: \"our discount program enables them to fly to any of our destinations for a fraction of the average ticket price.\" (Từ \"a fraction of the average ticket price\" chứng minh nhân viên vẫn phải trả một phần tiền, không miễn phí).\nPhân tích bẫy:\n- (A) ĐÚNG theo bài (loại vì hỏi NOT): \"tuition reimbursement\" (hoàn trả học phí) tương ứng với \"Payment for educational expenses\".\n- (C) ĐÚNG theo bài (loại vì hỏi NOT): \"a mentorship program\" (chương trình cố vấn) tương ứng với \"Opportunities for mentoring\".\n- (D) ĐÚNG theo bài (loại vì hỏi NOT): \"Annual paid vacations\" (kỳ nghỉ phép có lương hằng năm) tương ứng với \"Paid days off\".","lines":[{"speaker":"Document 1 — Thông tin","en":"Skyler Airlines employs more than 20,000 people from all over the world. We're growing fast and have many positions available. — [1] —. So regardless of your background, there's probably a place for you on our team. Skyler employees enjoy many perks. — [2] —. For example, our discount program enables them to fly to any of our destinations for a fraction of the average ticket price. — [3] —. We offer upward and global mobility, tuition reimbursement, a mentorship program, and a generous compensation package. — [4] —. Annual paid vacations enable a comfortable work-life balance. It's no wonder that Skyler Airlines was named \"Best Airline to Work For\" by Travel Vista Journal three years in a row.","vi":"Skyler Airlines hiện có đội ngũ hơn 20.000 nhân viên đến từ khắp nơi trên thế giới. Chúng tôi đang phát triển nhanh chóng và có rất nhiều vị trí tuyển dụng đang mở. — [1] —. Vì vậy, bất kể nền tảng chuyên môn của bạn là gì, rất có thể vẫn luôn có một vị trí dành cho bạn trong đội ngũ của chúng tôi. Nhân viên của Skyler được hưởng rất nhiều đặc quyền hấp dẫn. — [2] —. Chẳng hạn, chương trình ưu đãi cho phép họ bay tới bất kỳ điểm đến nào trong mạng lưới của hãng với mức chi phí chỉ bằng một phần nhỏ so với giá vé trung bình. — [3] —. Chúng tôi mang đến cơ hội thăng tiến và luân chuyển công tác toàn cầu, chính sách hoàn trả học phí, chương trình cố vấn nghề nghiệp cùng gói đãi ngộ hào phóng. — [4] —. Chế độ nghỉ phép có hưởng lương hằng năm giúp nhân viên duy trì sự cân bằng thoải mái giữa công việc và cuộc sống. Không có gì ngạc nhiên khi Skyler Airlines được tạp chí Travel Vista Journal bình chọn là \"Hãng hàng không đáng làm việc nhất\" ba năm liên tiếp.","units":[{"en":"Skyler Airlines employs more than 20,000 people from all over the world.","vi":"Skyler Airlines hiện có đội ngũ hơn 20.000 nhân viên đến từ khắp nơi trên thế giới."},{"en":"We're growing fast and have many positions available. — [1] —.","vi":"Chúng tôi đang phát triển nhanh chóng và có rất nhiều vị trí tuyển dụng đang mở. — [1] —."},{"en":"So regardless of your background, there's probably a place for you on our team.","vi":"Vì vậy, bất kể nền tảng chuyên môn của bạn là gì, rất có thể vẫn luôn có một vị trí dành cho bạn trong đội ngũ của chúng tôi."},{"en":"Skyler employees enjoy many perks. — [2] —.","vi":"Nhân viên của Skyler được hưởng rất nhiều đặc quyền hấp dẫn. — [2] —."},{"en":"For example, our discount program enables them to fly to any of our destinations for a fraction of the average ticket price. — [3] —.","vi":"Chẳng hạn, chương trình ưu đãi cho phép họ bay tới bất kỳ điểm đến nào trong mạng lưới của hãng với mức chi phí chỉ bằng một phần nhỏ so với giá vé trung bình. — [3] —."},{"en":"We offer upward and global mobility, tuition reimbursement, a mentorship program, and a generous compensation package. — [4] —.","vi":"Chúng tôi mang đến cơ hội thăng tiến và luân chuyển công tác toàn cầu, chính sách hoàn trả học phí, chương trình cố vấn nghề nghiệp cùng gói đãi ngộ hào phóng. — [4] —."},{"en":"Annual paid vacations enable a comfortable work-life balance.","vi":"Chế độ nghỉ phép có hưởng lương hằng năm giúp nhân viên duy trì sự cân bằng thoải mái giữa công việc và cuộc sống."},{"en":"It's no wonder that Skyler Airlines was named \"Best Airline to Work For\" by Travel Vista Journal three years in a row.","vi":"Không có gì ngạc nhiên khi Skyler Airlines được tạp chí Travel Vista Journal bình chọn là \"Hãng hàng không đáng làm việc nhất\" ba năm liên tiếp."}]}],"vocab":[{"word":"perk","pos":"n","ipa":"/pɜːrk/","meaning":"đặc quyền, phúc lợi bổ sung"},{"word":"fraction","pos":"n","ipa":"/ˈfrækʃən/","meaning":"một phần nhỏ"},{"word":"tuition reimbursement","pos":"phr","ipa":"/tuˈɪʃən ˌriːɪmˈbɜːrsmənt/","meaning":"chính sách hoàn trả học phí"},{"word":"compensation package","pos":"phr","ipa":"/ˌkɑːmpənˈseɪʃən ˈpækɪdʒ/","meaning":"gói lương thưởng và đãi ngộ"}],"isScanBacked":false,"docTypeLabel":"information","context":"Thông tin tuyển dụng và phúc lợi nhân viên của Skyler Airlines","grammarType":"Part 7 — Câu hỏi phủ định / Ngoại trừ (NOT / TRUE Detail)","formula":"CÔNG THỨC PART 7 (Câu hỏi NOT / Ngoại trừ — Dạng 26): Đối chiếu từng phương án A–D vào đoạn liệt kê phúc lợi; chú ý bẫy biến đổi mức độ từ 'giảm giá / trả một phần nhỏ' thành 'miễn phí' (free).","optionAnalysis":{"A":"Có đề cập (loại): 'tuition reimbursement' (hoàn trả học phí) trong bài khớp chính xác với 'Payment for educational expenses'.","B":"Chính xác (KHÔNG đúng/không có): Bài nói có 'discount program' với mức giá 'a fraction of the average ticket price' (giảm giá chỉ trả một phần nhỏ), không phải vé miễn phí ('Free').","C":"Có đề cập (loại): 'a mentorship program' được nêu trực tiếp trong danh sách phúc lợi, khớp với 'Opportunities for mentoring'.","D":"Có đề cập (loại): 'Annual paid vacations' (nghỉ phép có hưởng lương hằng năm) đồng nghĩa với 'Paid days off'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 169 · Có A","opt":"A","isCorrect":false,"quote":"tuition reimbursement","viQuote":"chính sách hoàn trả học phí"},{"badge":"Câu 169 · Có C","opt":"C","isCorrect":false,"quote":"a mentorship program","viQuote":"chương trình cố vấn nghề nghiệp"},{"badge":"Câu 169 · Có D","opt":"D","isCorrect":false,"quote":"Annual paid vacations enable a comfortable work-life balance.","viQuote":"Chế độ nghỉ phép có hưởng lương hằng năm giúp nhân viên duy trì sự cân bằng thoải mái giữa công việc và cuộc sống."},{"badge":"Câu 169 · Đáp án B","opt":"B","isCorrect":true,"quote":"our discount program enables them to fly to any of our destinations for a fraction of the average ticket price.","viQuote":"chương trình ưu đãi cho phép họ bay tới bất kỳ điểm đến nào trong mạng lưới của hãng với mức chi phí chỉ bằng một phần nhỏ so với giá vé trung bình."}],"evQuotes":["tuition reimbursement","a mentorship program","Annual paid vacations enable a comfortable work-life balance.","our discount program enables them to fly to any of our destinations for a fraction of the average ticket price."]},{"q":170,"part":7,"group_id":"E25_T01_G168_171","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc16.webp"],"stem_en":"What is mentioned about Skyler Airlines?","stem_vi":"Điều gì được đề cập về Skyler Airlines?","options":{"A":{"en":"It flies to the most destinations around the world.","vi":"Hãng bay tới nhiều điểm đến nhất trên toàn thế giới."},"B":{"en":"It is planning to merge with another airline.","vi":"Hãng đang lên kế hoạch sáp nhập với một hãng hàng không khác."},"C":{"en":"It has been praised by a trade publication.","vi":"Hãng đã được một ấn phẩm chuyên ngành khen ngợi."},"D":{"en":"It has replaced its seats with more comfortable ones.","vi":"Hãng đã thay thế ghế ngồi bằng loại ghế thoải mái hơn."}},"ans":"C","evidence_quote":"It's no wonder that Skyler Airlines was named \"Best Airline to Work For\" by Travel Vista Journal three years in a row.","explanation":"Đáp án đúng: (C) Hãng đã được một ấn phẩm chuyên ngành khen ngợi — Skyler Airlines được tạp chí Travel Vista Journal vinh danh là \"Hãng hàng không đáng làm việc nhất\" 3 năm liên tiếp.\nDẫn chứng: \"It's no wonder that Skyler Airlines was named \\\"Best Airline to Work For\\\" by Travel Vista Journal three years in a row.\" (Paraphrase: \"Travel Vista Journal\" là \"a trade publication\", còn \"named Best Airline to Work For\" là \"praised\").\nPhân tích bẫy:\n- (A) Bẫy so sánh cực đại: bài chỉ nói chương trình giảm giá cho phép bay tới bất kỳ điểm đến nào của hãng (\"any of our destinations\"), không khẳng định đây là hãng bay tới nhiều điểm đến nhất thế giới.\n- (B) Bẫy bịa đặt kế hoạch: văn bản không có bất kỳ thông tin nào về việc sáp nhập (\"merge\") với hãng hàng không khác.\n- (D) Bẫy suy diễn từ 'comfortable': từ \"comfortable\" trong bài nằm trong cụm \"comfortable work-life balance\" (cân bằng công việc và cuộc sống thoải mái), không phải ghế ngồi trên máy bay.","lines":[{"speaker":"Document 1 — Thông tin","en":"Skyler Airlines employs more than 20,000 people from all over the world. We're growing fast and have many positions available. — [1] —. So regardless of your background, there's probably a place for you on our team. Skyler employees enjoy many perks. — [2] —. For example, our discount program enables them to fly to any of our destinations for a fraction of the average ticket price. — [3] —. We offer upward and global mobility, tuition reimbursement, a mentorship program, and a generous compensation package. — [4] —. Annual paid vacations enable a comfortable work-life balance. It's no wonder that Skyler Airlines was named \"Best Airline to Work For\" by Travel Vista Journal three years in a row.","vi":"Skyler Airlines hiện có đội ngũ hơn 20.000 nhân viên đến từ khắp nơi trên thế giới. Chúng tôi đang phát triển nhanh chóng và có rất nhiều vị trí tuyển dụng đang mở. — [1] —. Vì vậy, bất kể nền tảng chuyên môn của bạn là gì, rất có thể vẫn luôn có một vị trí dành cho bạn trong đội ngũ của chúng tôi. Nhân viên của Skyler được hưởng rất nhiều đặc quyền hấp dẫn. — [2] —. Chẳng hạn, chương trình ưu đãi cho phép họ bay tới bất kỳ điểm đến nào trong mạng lưới của hãng với mức chi phí chỉ bằng một phần nhỏ so với giá vé trung bình. — [3] —. Chúng tôi mang đến cơ hội thăng tiến và luân chuyển công tác toàn cầu, chính sách hoàn trả học phí, chương trình cố vấn nghề nghiệp cùng gói đãi ngộ hào phóng. — [4] —. Chế độ nghỉ phép có hưởng lương hằng năm giúp nhân viên duy trì sự cân bằng thoải mái giữa công việc và cuộc sống. Không có gì ngạc nhiên khi Skyler Airlines được tạp chí Travel Vista Journal bình chọn là \"Hãng hàng không đáng làm việc nhất\" ba năm liên tiếp.","units":[{"en":"Skyler Airlines employs more than 20,000 people from all over the world.","vi":"Skyler Airlines hiện có đội ngũ hơn 20.000 nhân viên đến từ khắp nơi trên thế giới."},{"en":"We're growing fast and have many positions available. — [1] —.","vi":"Chúng tôi đang phát triển nhanh chóng và có rất nhiều vị trí tuyển dụng đang mở. — [1] —."},{"en":"So regardless of your background, there's probably a place for you on our team.","vi":"Vì vậy, bất kể nền tảng chuyên môn của bạn là gì, rất có thể vẫn luôn có một vị trí dành cho bạn trong đội ngũ của chúng tôi."},{"en":"Skyler employees enjoy many perks. — [2] —.","vi":"Nhân viên của Skyler được hưởng rất nhiều đặc quyền hấp dẫn. — [2] —."},{"en":"For example, our discount program enables them to fly to any of our destinations for a fraction of the average ticket price. — [3] —.","vi":"Chẳng hạn, chương trình ưu đãi cho phép họ bay tới bất kỳ điểm đến nào trong mạng lưới của hãng với mức chi phí chỉ bằng một phần nhỏ so với giá vé trung bình. — [3] —."},{"en":"We offer upward and global mobility, tuition reimbursement, a mentorship program, and a generous compensation package. — [4] —.","vi":"Chúng tôi mang đến cơ hội thăng tiến và luân chuyển công tác toàn cầu, chính sách hoàn trả học phí, chương trình cố vấn nghề nghiệp cùng gói đãi ngộ hào phóng. — [4] —."},{"en":"Annual paid vacations enable a comfortable work-life balance.","vi":"Chế độ nghỉ phép có hưởng lương hằng năm giúp nhân viên duy trì sự cân bằng thoải mái giữa công việc và cuộc sống."},{"en":"It's no wonder that Skyler Airlines was named \"Best Airline to Work For\" by Travel Vista Journal three years in a row.","vi":"Không có gì ngạc nhiên khi Skyler Airlines được tạp chí Travel Vista Journal bình chọn là \"Hãng hàng không đáng làm việc nhất\" ba năm liên tiếp."}]}],"vocab":[{"word":"mobility","pos":"n","ipa":"/moʊˈbɪləti/","meaning":"khả năng luân chuyển, cơ hội thăng tiến"},{"word":"mentorship","pos":"n","ipa":"/ˈmentɔːrʃɪp/","meaning":"chương trình cố vấn, hướng dẫn nghề nghiệp"},{"word":"work-life balance","pos":"phr","ipa":"/ˌwɜːrk ˈlaɪf ˈbæləns/","meaning":"sự cân bằng giữa công việc và cuộc sống"},{"word":"trade publication","pos":"phr","ipa":"/treɪd ˌpʌblɪˈkeɪʃən/","meaning":"ấn phẩm chuyên ngành"}],"isScanBacked":false,"docTypeLabel":"information","context":"Thông tin tuyển dụng và phúc lợi nhân viên của Skyler Airlines","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 (Chi tiết Tổ chức & Paraphrase — Dạng 23): Tìm tên riêng xuất hiện cuối đoạn ('Travel Vista Journal') -> Paraphrase 'named Best Airline to Work For' thành 'praised by a trade publication'.","optionAnalysis":{"A":"Phóng đại chi tiết: Bài chỉ nhắc nhân viên được bay tới 'any of our destinations', không nói hãng có mạng lưới nhiều điểm đến nhất thế giới.","B":"Thông tin không có trong bài: Hoàn toàn không có chi tiết nào đề cập đến kế hoạch sáp nhập với hãng hàng không khác.","C":"Chính xác: Danh hiệu 'Best Airline to Work For' từ 'Travel Vista Journal' khớp nghĩa với được một ấn phẩm chuyên ngành khen ngợi.","D":"Bẫy ghép sai danh từ: Từ 'comfortable' đi với 'work-life balance' (cân bằng cuộc sống), không phải nâng cấp ghế ngồi ('seats')."},"evDocIdx":0,"evTargets":[{"badge":"Câu 170 · Đáp án C","opt":"C","isCorrect":true,"quote":"It's no wonder that Skyler Airlines was named \"Best Airline to Work For\" by Travel Vista Journal three years in a row.","viQuote":"Không có gì ngạc nhiên khi Skyler Airlines được tạp chí Travel Vista Journal bình chọn là \"Hãng hàng không đáng làm việc nhất\" ba năm liên tiếp."}],"evQuotes":["It's no wonder that Skyler Airlines was named \"Best Airline to Work For\" by Travel Vista Journal three years in a row."]},{"q":171,"part":7,"group_id":"E25_T01_G168_171","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc16.webp"],"stem_en":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? \"Our openings cover a broad range of skill sets.\"","stem_vi":"Câu sau đây phù hợp nhất ở vị trí nào trong các vị trí được đánh dấu [1], [2], [3] và [4]? \"Các vị trí đang tuyển của chúng tôi bao quát nhiều nhóm kỹ năng đa dạng.\"","options":{"A":{"en":"[1]","vi":"Vị trí [1]"},"B":{"en":"[2]","vi":"Vị trí [2]"},"C":{"en":"[3]","vi":"Vị trí [3]"},"D":{"en":"[4]","vi":"Vị trí [4]"}},"ans":"A","evidence_quote":"We're growing fast and have many positions available. Our openings cover a broad range of skill sets. So regardless of your background, there's probably a place for you on our team.","explanation":"Đáp án đúng: (A) Vị trí [1] — câu cần điền đóng vai trò cầu nối logic hoàn hảo giữa việc hãng có nhiều vị trí trống và kết luận rằng dù ứng viên có nền tảng nào cũng có cơ hội.\nDẫn chứng: \"We're growing fast and have many positions available. [Our openings cover a broad range of skill sets.] So regardless of your background, there's probably a place for you on our team.\" (\"Our openings\" nối trực tiếp \"many positions available\"; \"broad range of skill sets\" giải thích cho \"regardless of your background\").\nPhân tích bẫy:\n- (B) Vị trí [2] sai mạch ý: câu trước là \"Skyler employees enjoy many perks.\" và câu sau bắt đầu bằng \"For example, our discount program\" để lấy ví dụ về đặc quyền; chèn câu về vị trí tuyển dụng vào giữa sẽ cắt đứt ví dụ.\n- (C) Vị trí [3] sai mạch ý: câu trước nói về vé máy bay ưu đãi và câu sau liệt kê tiếp các phúc lợi khác (hoàn trả học phí, cố vấn nghề nghiệp), không còn nói về yêu cầu kỹ năng tuyển dụng.\n- (D) Vị trí [4] sai mạch ý: nằm giữa phần liệt kê đãi ngộ (\"generous compensation package\") và câu tiếp theo về kỳ nghỉ phép (\"Annual paid vacations\"), hoàn toàn lạc chủ đề so với \"openings\".","lines":[{"speaker":"Document 1 — Thông tin","en":"Skyler Airlines employs more than 20,000 people from all over the world. We're growing fast and have many positions available. — [1] —. So regardless of your background, there's probably a place for you on our team. Skyler employees enjoy many perks. — [2] —. For example, our discount program enables them to fly to any of our destinations for a fraction of the average ticket price. — [3] —. We offer upward and global mobility, tuition reimbursement, a mentorship program, and a generous compensation package. — [4] —. Annual paid vacations enable a comfortable work-life balance. It's no wonder that Skyler Airlines was named \"Best Airline to Work For\" by Travel Vista Journal three years in a row.","vi":"Skyler Airlines hiện có đội ngũ hơn 20.000 nhân viên đến từ khắp nơi trên thế giới. Chúng tôi đang phát triển nhanh chóng và có rất nhiều vị trí tuyển dụng đang mở. — [1] —. Vì vậy, bất kể nền tảng chuyên môn của bạn là gì, rất có thể vẫn luôn có một vị trí dành cho bạn trong đội ngũ của chúng tôi. Nhân viên của Skyler được hưởng rất nhiều đặc quyền hấp dẫn. — [2] —. Chẳng hạn, chương trình ưu đãi cho phép họ bay tới bất kỳ điểm đến nào trong mạng lưới của hãng với mức chi phí chỉ bằng một phần nhỏ so với giá vé trung bình. — [3] —. Chúng tôi mang đến cơ hội thăng tiến và luân chuyển công tác toàn cầu, chính sách hoàn trả học phí, chương trình cố vấn nghề nghiệp cùng gói đãi ngộ hào phóng. — [4] —. Chế độ nghỉ phép có hưởng lương hằng năm giúp nhân viên duy trì sự cân bằng thoải mái giữa công việc và cuộc sống. Không có gì ngạc nhiên khi Skyler Airlines được tạp chí Travel Vista Journal bình chọn là \"Hãng hàng không đáng làm việc nhất\" ba năm liên tiếp.","units":[{"en":"Skyler Airlines employs more than 20,000 people from all over the world.","vi":"Skyler Airlines hiện có đội ngũ hơn 20.000 nhân viên đến từ khắp nơi trên thế giới."},{"en":"We're growing fast and have many positions available. — [1] —.","vi":"Chúng tôi đang phát triển nhanh chóng và có rất nhiều vị trí tuyển dụng đang mở. — [1] —."},{"en":"So regardless of your background, there's probably a place for you on our team.","vi":"Vì vậy, bất kể nền tảng chuyên môn của bạn là gì, rất có thể vẫn luôn có một vị trí dành cho bạn trong đội ngũ của chúng tôi."},{"en":"Skyler employees enjoy many perks. — [2] —.","vi":"Nhân viên của Skyler được hưởng rất nhiều đặc quyền hấp dẫn. — [2] —."},{"en":"For example, our discount program enables them to fly to any of our destinations for a fraction of the average ticket price. — [3] —.","vi":"Chẳng hạn, chương trình ưu đãi cho phép họ bay tới bất kỳ điểm đến nào trong mạng lưới của hãng với mức chi phí chỉ bằng một phần nhỏ so với giá vé trung bình. — [3] —."},{"en":"We offer upward and global mobility, tuition reimbursement, a mentorship program, and a generous compensation package. — [4] —.","vi":"Chúng tôi mang đến cơ hội thăng tiến và luân chuyển công tác toàn cầu, chính sách hoàn trả học phí, chương trình cố vấn nghề nghiệp cùng gói đãi ngộ hào phóng. — [4] —."},{"en":"Annual paid vacations enable a comfortable work-life balance.","vi":"Chế độ nghỉ phép có hưởng lương hằng năm giúp nhân viên duy trì sự cân bằng thoải mái giữa công việc và cuộc sống."},{"en":"It's no wonder that Skyler Airlines was named \"Best Airline to Work For\" by Travel Vista Journal three years in a row.","vi":"Không có gì ngạc nhiên khi Skyler Airlines được tạp chí Travel Vista Journal bình chọn là \"Hãng hàng không đáng làm việc nhất\" ba năm liên tiếp."}]}],"vocab":[{"word":"opening","pos":"n","ipa":"/ˈoʊpənɪŋ/","meaning":"vị trí tuyển dụng còn trống"},{"word":"skill set","pos":"n","ipa":"/ˈskɪl set/","meaning":"bộ kỹ năng, nhóm năng lực"},{"word":"broad range","pos":"phr","ipa":"/brɔːd reɪndʒ/","meaning":"phạm vi rộng lớn, đa dạng"}],"isScanBacked":false,"docTypeLabel":"information","context":"Thông tin tuyển dụng và phúc lợi nhân viên của Skyler Airlines","grammarType":"Part 7 — Điền câu vào vị trí thích hợp (Sentence Insertion)","formula":"CÔNG THỨC PART 7 (Điền câu vào Vị trí [1]–[4] — Dạng 30): Soi liên kết 2 chiều tại [1]: Câu trước có 'many positions available' (= 'Our openings'), câu sau có 'So regardless of your background' (hệ quả của 'broad range of skill sets').","optionAnalysis":{"A":"Chính xác: 'Our openings' liên kết lùi với 'many positions available' ở câu trước và 'broad range of skill sets' dẫn thẳng tới 'So regardless of your background' ở câu sau.","B":"Phá vỡ mạch ví dụ: Đứng ngay sau 'enjoy many perks' và trước 'For example, our discount program', chèn câu tuyển dụng vào [2] làm đứt liên kết ví dụ.","C":"Lạc chủ đề phúc lợi: Vị trí [3] nằm giữa đoạn liệt kê ưu đãi vé bay và các chính sách đãi ngộ (học phí, cố vấn), không khớp nội dung vị trí mở.","D":"Sai ngữ cảnh đoạn: Vị trí [4] ngăn cách giữa 'compensation package' và 'Annual paid vacations', đều đang nói về quyền lợi nhân viên chứ không phải kỹ năng tuyển dụng."},"evDocIdx":0,"evTargets":[{"badge":"Câu 171 · Đáp án A","opt":"A","isCorrect":true,"quote":"We're growing fast and have many positions available.","viQuote":"Chúng tôi đang phát triển nhanh chóng và có rất nhiều vị trí tuyển dụng đang mở."},{"badge":"Câu 171 · Đáp án A","opt":"A","isCorrect":true,"quote":"So regardless of your background, there's probably a place for you on our team.","viQuote":"Vì vậy, bất kể nền tảng chuyên môn của bạn là gì, rất có thể vẫn luôn có một vị trí dành cho bạn trong đội ngũ của chúng tôi."}],"evQuotes":["We're growing fast and have many positions available.","So regardless of your background, there's probably a place for you on our team."]},{"q":172,"part":7,"group_id":"E25_T01_G172_175","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc17.webp"],"stem_en":"What is indicated about a presentation?","stem_vi":"Điều gì được nêu rõ về bài thuyết trình?","options":{"A":{"en":"It will be expensive to produce.","vi":"Chi phí thực hiện bài thuyết trình sẽ rất tốn kém."},"B":{"en":"It will highlight some best-selling products.","vi":"Bài thuyết trình sẽ làm nổi bật một số sản phẩm bán chạy nhất."},"C":{"en":"It will be Ms. Gowan's first project.","vi":"Đây sẽ là dự án đầu tiên của bà Gowan."},"D":{"en":"It will be sent to multiple locations.","vi":"Bài thuyết trình sẽ được gửi đến nhiều địa điểm khác nhau."}},"ans":"D","evidence_quote":"The presentation slides about the new line of headphones are almost ready for distribution to our many partner stores.","explanation":"Đáp án đúng: (D) Bài thuyết trình sẽ được gửi đến nhiều địa điểm khác nhau — bà Gowan thông báo bộ slide về dòng tai nghe mới sắp sẵn sàng để gửi tới nhiều cửa hàng đối tác của công ty.\nDẫn chứng: Susan Gowan (9:16 A.M.): \"The presentation slides about the new line of headphones are almost ready for distribution to our many partner stores. We are on track to send them out next Monday.\" (Paraphrase: \"for distribution to our many partner stores\" = \"be sent to multiple locations\").\nPhân tích bẫy:\n- (A) Bẫy thông tin ngoài bài: cuộc trò chuyện hoàn toàn không đề cập đến chi phí hay ngân sách thực hiện bộ slide.\n- (B) Bẫy sai đặc điểm sản phẩm: bộ slide giới thiệu dòng tai nghe mới (\"the new line of headphones\"), không phải các sản phẩm bán chạy nhất (\"best-selling products\").\n- (C) Bẫy suy diễn sai về nhân sự: không có chi tiết nào cho thấy đây là dự án đầu tiên của bà Susan Gowan tại công ty.","lines":[{"speaker":"Susan Gowan (9:16 A.M.)","en":"Good morning. The presentation slides about the new line of headphones are almost ready for distribution to our many partner stores. We are on track to send them out next Monday.","vi":"Chào buổi sáng mọi người. Bộ slide thuyết trình về dòng tai nghe mới gần như đã sẵn sàng để gửi tới nhiều cửa hàng đối tác của chúng ta. Chúng ta đang đi đúng tiến độ để gửi bộ slide này vào thứ Hai tuần tới.","units":[{"en":"Good morning.","vi":"Chào buổi sáng mọi người."},{"en":"The presentation slides about the new line of headphones are almost ready for distribution to our many partner stores.","vi":"Bộ slide thuyết trình về dòng tai nghe mới gần như đã sẵn sàng để gửi tới nhiều cửa hàng đối tác của chúng ta."},{"en":"We are on track to send them out next Monday.","vi":"Chúng ta đang đi đúng tiến độ để gửi bộ slide này vào thứ Hai tuần tới."}]},{"speaker":"Maggie Lorenz (9:17 A.M.)","en":"How do they look?","vi":"Các slide trông thế nào rồi?","units":[{"en":"How do they look?","vi":"Các slide trông thế nào rồi?"}]},{"speaker":"Susan Gowan (9:20 A.M.)","en":"There are still some missing elements.","vi":"Vẫn còn thiếu một vài phần nội dung.","units":[{"en":"There are still some missing elements.","vi":"Vẫn còn thiếu một vài phần nội dung."}]},{"speaker":"Alan Woodson (9:21 A.M.)","en":"We mainly need the information from the user studies that reviewed the headphones for sport use. We should have that report from the research and development office by Wednesday.","vi":"Chúng ta chủ yếu cần thông tin từ các nghiên cứu người dùng đánh giá mẫu tai nghe này khi sử dụng cho mục đích thể thao. Chậm nhất đến thứ Tư chúng ta sẽ nhận được báo cáo đó từ bộ phận nghiên cứu và phát triển.","units":[{"en":"We mainly need the information from the user studies that reviewed the headphones for sport use.","vi":"Chúng ta chủ yếu cần thông tin từ các nghiên cứu người dùng đánh giá mẫu tai nghe này khi sử dụng cho mục đích thể thao."},{"en":"We should have that report from the research and development office by Wednesday.","vi":"Chậm nhất đến thứ Tư chúng ta sẽ nhận được báo cáo đó từ bộ phận nghiên cứu và phát triển."}]},{"speaker":"Maggie Lorenz (9:22 A.M.)","en":"Yes, let's not overlook that. And if you're concerned about the report not arriving by Wednesday, please contact Matt Harven and remind him to expedite a summary to us.","vi":"Đúng vậy, chúng ta đừng bỏ sót phần đó. Và nếu lo ngại báo cáo sẽ không đến kịp thứ Tư, hãy liên hệ với Matt Harven và nhắc anh ấy khẩn trương gửi trước bản tóm tắt cho chúng ta.","units":[{"en":"Yes, let's not overlook that.","vi":"Đúng vậy, chúng ta đừng bỏ sót phần đó."},{"en":"And if you're concerned about the report not arriving by Wednesday, please contact Matt Harven and remind him to expedite a summary to us.","vi":"Và nếu lo ngại báo cáo sẽ không đến kịp thứ Tư, hãy liên hệ với Matt Harven và nhắc anh ấy khẩn trương gửi trước bản tóm tắt cho chúng ta."}]},{"speaker":"Susan Gowan (9:23 A.M.)","en":"Assuming we receive that summary soon enough to incorporate its findings into the slides, should the three of us schedule a trial run through the presentation on Thursday or Friday?","vi":"Giả sử chúng ta nhận được bản tóm tắt đó đủ sớm để đưa các kết quả nghiên cứu vào slide, liệu ba người chúng ta nên lên lịch chạy thử bài thuyết trình vào thứ Năm hay thứ Sáu?","units":[{"en":"Assuming we receive that summary soon enough to incorporate its findings into the slides, should the three of us schedule a trial run through the presentation on Thursday or Friday?","vi":"Giả sử chúng ta nhận được bản tóm tắt đó đủ sớm để đưa các kết quả nghiên cứu vào slide, liệu ba người chúng ta nên lên lịch chạy thử bài thuyết trình vào thứ Năm hay thứ Sáu?"}]},{"speaker":"Maggie Lorenz (9:24 A.M.)","en":"Let's try for Thursday afternoon. Then we will still have Friday to make any necessary changes.","vi":"Hãy thu xếp vào chiều thứ Năm nhé. Như vậy chúng ta vẫn còn ngày thứ Sáu để thực hiện bất kỳ chỉnh sửa cần thiết nào.","units":[{"en":"Let's try for Thursday afternoon.","vi":"Hãy thu xếp vào chiều thứ Năm nhé."},{"en":"Then we will still have Friday to make any necessary changes.","vi":"Như vậy chúng ta vẫn còn ngày thứ Sáu để thực hiện bất kỳ chỉnh sửa cần thiết nào."}]},{"speaker":"Alan Woodson (9:25 A.M.)","en":"Fine by me. I'm free after 2 P.M.","vi":"Tôi thấy ổn thôi. Tôi rảnh sau 2 giờ chiều.","units":[{"en":"Fine by me.","vi":"Tôi thấy ổn thôi."},{"en":"I'm free after 2 P.M.","vi":"Tôi rảnh sau 2 giờ chiều."}]}],"vocab":[{"word":"distribution","pos":"n","ipa":"/ˌdɪstrɪˈbjuːʃən/","meaning":"việc phân phối, gửi phát hành"},{"word":"on track","pos":"phr","ipa":"/ɑːn træk/","meaning":"đi đúng tiến độ, đúng kế hoạch"},{"word":"partner store","pos":"phr","ipa":"/ˈpɑːrtnər stɔːr/","meaning":"cửa hàng đối tác"}],"isScanBacked":false,"docTypeLabel":"online chat discussion","context":"Online chat discussion among Susan Gowan, Maggie Lorenz, and Alan Woodson about headphone presentation slides","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 (Tin nhắn Chat — Chi tiết Phân phối — Dạng 42 & 23): Đọc câu mở đầu thiết lập bối cảnh ('distribution to our many partner stores') -> Paraphrase 'many partner stores' thành 'multiple locations'.","optionAnalysis":{"A":"Không được đề cập: Đoạn chat chỉ bàn về tiến độ nội dung và lịch gửi slide, không hề nhắc tới chi phí sản xuất.","B":"Lệch thông tin sản phẩm: Bài thuyết trình giới thiệu 'the new line of headphones' (dòng tai nghe mới), không phải sản phẩm bán chạy nhất.","C":"Thông tin bịa đặt: Không có dòng tin nhắn nào nói đây là dự án đầu tiên mà bà Gowan đảm nhận.","D":"Chính xác: Cụm 'distribution to our many partner stores' (phân phát tới nhiều cửa hàng đối tác) tương ứng với 'sent to multiple locations'."},"evDocIdx":0,"evTargets":[{"badge":"Câu 172 · Đáp án D","opt":"D","isCorrect":true,"quote":"The presentation slides about the new line of headphones are almost ready for distribution to our many partner stores.","viQuote":"Bộ slide thuyết trình về dòng tai nghe mới gần như đã sẵn sàng để gửi tới nhiều cửa hàng đối tác của chúng ta."},{"badge":"Câu 172 · Đáp án D","opt":"D","isCorrect":true,"quote":"We are on track to send them out next Monday.","viQuote":"Chúng ta đang đi đúng tiến độ để gửi bộ slide này vào thứ Hai tuần tới."}],"evQuotes":["The presentation slides about the new line of headphones are almost ready for distribution to our many partner stores.","We are on track to send them out next Monday."]},{"q":173,"part":7,"group_id":"E25_T01_G172_175","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc17.webp"],"stem_en":"At 9:22 A.M., what does Ms. Lorenz imply when she writes, \"let's not overlook that\"?","stem_vi":"Lúc 9:22 sáng, bà Lorenz ngụ ý gì khi viết \"let's not overlook that\"?","options":{"A":{"en":"More staff should attend a meeting.","vi":"Cần có thêm nhân viên tham dự một cuộc họp."},"B":{"en":"Information from the user studies is important.","vi":"Thông tin từ các nghiên cứu người dùng là rất quan trọng."},"C":{"en":"The presentation must run smoothly.","vi":"Buổi thuyết trình phải diễn ra suôn sẻ."},"D":{"en":"Partner stores must be notified about an upcoming report.","vi":"Các cửa hàng đối tác phải được thông báo về một báo cáo sắp ra mắt."}},"ans":"B","evidence_quote":"- We mainly need the information from the user studies that reviewed the headphones for sport use. We should have that report from the research and development office by Wednesday. - Yes, let's not overlook that.","explanation":"Đáp án đúng: (B) Thông tin từ các nghiên cứu người dùng là rất quan trọng — bà Lorenz đồng tình với tin nhắn lúc 9:21 sáng của ông Woodson và nhấn mạnh cả nhóm không được bỏ sót dữ liệu nghiên cứu người dùng này.\nDẫn chứng: Alan Woodson (9:21 A.M.): \"We mainly need the information from the user studies that reviewed the headphones for sport use.\" và Maggie Lorenz (9:22 A.M.): \"Yes, let's not overlook that.\" (\"that\" thay cho thông tin nghiên cứu người dùng, \"not overlook\" = xem trọng, không bỏ qua).\nPhân tích bẫy:\n- (A) Bẫy sai thành phần họp: sau đó bà Gowan chỉ đề xuất ba người họ (\"the three of us\") chạy thử bài thuyết trình, không hề nhắc tới việc mời thêm nhân viên khác.\n- (C) Bẫy suy diễn lệch đối tượng của 'that': \"let's not overlook that\" ám chỉ dữ liệu nghiên cứu người dùng từ tin nhắn 9:21 sáng, chưa bàn đến việc buổi thuyết trình diễn ra suôn sẻ.\n- (D) Bẫy trộn đối tượng: báo cáo được gửi từ phòng R&D cho nhóm nội bộ để đưa vào slide (\"incorporate its findings into the slides\"), chứ không phải thông báo cho các cửa hàng đối tác về báo cáo này.","lines":[{"speaker":"Susan Gowan (9:16 A.M.)","en":"Good morning. The presentation slides about the new line of headphones are almost ready for distribution to our many partner stores. We are on track to send them out next Monday.","vi":"Chào buổi sáng mọi người. Bộ slide thuyết trình về dòng tai nghe mới gần như đã sẵn sàng để gửi tới nhiều cửa hàng đối tác của chúng ta. Chúng ta đang đi đúng tiến độ để gửi bộ slide này vào thứ Hai tuần tới.","units":[{"en":"Good morning.","vi":"Chào buổi sáng mọi người."},{"en":"The presentation slides about the new line of headphones are almost ready for distribution to our many partner stores.","vi":"Bộ slide thuyết trình về dòng tai nghe mới gần như đã sẵn sàng để gửi tới nhiều cửa hàng đối tác của chúng ta."},{"en":"We are on track to send them out next Monday.","vi":"Chúng ta đang đi đúng tiến độ để gửi bộ slide này vào thứ Hai tuần tới."}]},{"speaker":"Maggie Lorenz (9:17 A.M.)","en":"How do they look?","vi":"Các slide trông thế nào rồi?","units":[{"en":"How do they look?","vi":"Các slide trông thế nào rồi?"}]},{"speaker":"Susan Gowan (9:20 A.M.)","en":"There are still some missing elements.","vi":"Vẫn còn thiếu một vài phần nội dung.","units":[{"en":"There are still some missing elements.","vi":"Vẫn còn thiếu một vài phần nội dung."}]},{"speaker":"Alan Woodson (9:21 A.M.)","en":"We mainly need the information from the user studies that reviewed the headphones for sport use. We should have that report from the research and development office by Wednesday.","vi":"Chúng ta chủ yếu cần thông tin từ các nghiên cứu người dùng đánh giá mẫu tai nghe này khi sử dụng cho mục đích thể thao. Chậm nhất đến thứ Tư chúng ta sẽ nhận được báo cáo đó từ bộ phận nghiên cứu và phát triển.","units":[{"en":"We mainly need the information from the user studies that reviewed the headphones for sport use.","vi":"Chúng ta chủ yếu cần thông tin từ các nghiên cứu người dùng đánh giá mẫu tai nghe này khi sử dụng cho mục đích thể thao."},{"en":"We should have that report from the research and development office by Wednesday.","vi":"Chậm nhất đến thứ Tư chúng ta sẽ nhận được báo cáo đó từ bộ phận nghiên cứu và phát triển."}]},{"speaker":"Maggie Lorenz (9:22 A.M.)","en":"Yes, let's not overlook that. And if you're concerned about the report not arriving by Wednesday, please contact Matt Harven and remind him to expedite a summary to us.","vi":"Đúng vậy, chúng ta đừng bỏ sót phần đó. Và nếu lo ngại báo cáo sẽ không đến kịp thứ Tư, hãy liên hệ với Matt Harven và nhắc anh ấy khẩn trương gửi trước bản tóm tắt cho chúng ta.","units":[{"en":"Yes, let's not overlook that.","vi":"Đúng vậy, chúng ta đừng bỏ sót phần đó."},{"en":"And if you're concerned about the report not arriving by Wednesday, please contact Matt Harven and remind him to expedite a summary to us.","vi":"Và nếu lo ngại báo cáo sẽ không đến kịp thứ Tư, hãy liên hệ với Matt Harven và nhắc anh ấy khẩn trương gửi trước bản tóm tắt cho chúng ta."}]},{"speaker":"Susan Gowan (9:23 A.M.)","en":"Assuming we receive that summary soon enough to incorporate its findings into the slides, should the three of us schedule a trial run through the presentation on Thursday or Friday?","vi":"Giả sử chúng ta nhận được bản tóm tắt đó đủ sớm để đưa các kết quả nghiên cứu vào slide, liệu ba người chúng ta nên lên lịch chạy thử bài thuyết trình vào thứ Năm hay thứ Sáu?","units":[{"en":"Assuming we receive that summary soon enough to incorporate its findings into the slides, should the three of us schedule a trial run through the presentation on Thursday or Friday?","vi":"Giả sử chúng ta nhận được bản tóm tắt đó đủ sớm để đưa các kết quả nghiên cứu vào slide, liệu ba người chúng ta nên lên lịch chạy thử bài thuyết trình vào thứ Năm hay thứ Sáu?"}]},{"speaker":"Maggie Lorenz (9:24 A.M.)","en":"Let's try for Thursday afternoon. Then we will still have Friday to make any necessary changes.","vi":"Hãy thu xếp vào chiều thứ Năm nhé. Như vậy chúng ta vẫn còn ngày thứ Sáu để thực hiện bất kỳ chỉnh sửa cần thiết nào.","units":[{"en":"Let's try for Thursday afternoon.","vi":"Hãy thu xếp vào chiều thứ Năm nhé."},{"en":"Then we will still have Friday to make any necessary changes.","vi":"Như vậy chúng ta vẫn còn ngày thứ Sáu để thực hiện bất kỳ chỉnh sửa cần thiết nào."}]},{"speaker":"Alan Woodson (9:25 A.M.)","en":"Fine by me. I'm free after 2 P.M.","vi":"Tôi thấy ổn thôi. Tôi rảnh sau 2 giờ chiều.","units":[{"en":"Fine by me.","vi":"Tôi thấy ổn thôi."},{"en":"I'm free after 2 P.M.","vi":"Tôi rảnh sau 2 giờ chiều."}]}],"vocab":[{"word":"missing element","pos":"phr","ipa":"/ˈmɪsɪŋ ˈelɪmənt/","meaning":"thành phần còn thiếu, nội dung bị sót"},{"word":"user study","pos":"phr","ipa":"/ˈjuːzər ˈstʌdi/","meaning":"nghiên cứu trải nghiệm người dùng"},{"word":"overlook","pos":"v","ipa":"/ˌoʊvərˈlʊk/","meaning":"bỏ sót, xem nhẹ"}],"isScanBacked":false,"docTypeLabel":"online chat discussion","context":"Online chat discussion among Susan Gowan, Maggie Lorenz, and Alan Woodson about headphone presentation slides","grammarType":"Part 7 — Suy luận & Hàm ý văn bản (Inference & Implied Meaning)","formula":"CÔNG THỨC PART 7 (Câu hỏi Ngoặc kép trong Tin nhắn Chat — Dạng 29 & 42): Neo vào đại từ 'that' ở tin nhắn ngay trước (9:21 A.M. của Alan về 'information from the user studies') -> 'let's not overlook that' nhấn mạnh dữ liệu đó rất quan trọng.","optionAnalysis":{"A":"Sai nội dung cuộc họp: Nhóm chỉ bàn việc 3 người ('the three of us') chạy thử slide vào thứ Năm, không yêu cầu thêm nhân viên dự họp.","B":"Chính xác: Đại từ 'that' quy chiếu thẳng về 'information from the user studies' lúc 9:21 A.M., và 'not overlook' nhấn mạnh tầm quan trọng không thể thiếu của nó.","C":"Hiểu sai đối tượng 'that': Câu lúc 9:22 A.M. phản hồi trực tiếp về báo cáo nghiên cứu người dùng còn thiếu, không nói về tính suôn sẻ của buổi trình bày.","D":"Trộn lẫn vai trò đối tượng: Các cửa hàng đối tác chỉ nhận bộ slide hoàn chỉnh vào thứ Hai tuần tới, không nhận thông báo về báo cáo nghiên cứu."},"evDocIdx":0,"evTargets":[{"badge":"Câu 173 · Đáp án B","opt":"B","isCorrect":true,"quote":"We mainly need the information from the user studies that reviewed the headphones for sport use.","viQuote":"Chúng ta chủ yếu cần thông tin từ các nghiên cứu người dùng đánh giá mẫu tai nghe này khi sử dụng cho mục đích thể thao."},{"badge":"Câu 173 · Đáp án B","opt":"B","isCorrect":true,"quote":"Yes, let's not overlook that.","viQuote":"Đúng vậy, chúng ta đừng bỏ sót phần đó."}],"evQuotes":["We mainly need the information from the user studies that reviewed the headphones for sport use.","Yes, let's not overlook that."]},{"q":174,"part":7,"group_id":"E25_T01_G172_175","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc17.webp"],"stem_en":"Who most likely is Mr. Harven?","stem_vi":"Ông Harven có khả năng cao nhất là ai?","options":{"A":{"en":"A store manager","vi":"Quản lý cửa hàng"},"B":{"en":"An amateur athlete","vi":"Vận động viên nghiệp dư"},"C":{"en":"A product researcher","vi":"Chuyên viên nghiên cứu sản phẩm"},"D":{"en":"An advertising executive","vi":"Giám đốc điều hành quảng cáo"}},"ans":"C","evidence_quote":"- We should have that report from the research and development office by Wednesday - And if you're concerned about the report not arriving by Wednesday, please contact Matt Harven and remind him to expedite a summary to us.","explanation":"Đáp án đúng: (C) Chuyên viên nghiên cứu sản phẩm — vì nhóm đang chờ báo cáo nghiên cứu người dùng về tai nghe từ văn phòng Nghiên cứu & Phát triển (R&D), việc bà Lorenz bảo liên hệ Matt Harven để hối gửi bản tóm tắt cho thấy ông làm việc tại bộ phận nghiên cứu này.\nDẫn chứng: \"We should have that report from the research and development office by Wednesday.\" và \"if you're concerned about the report not arriving by Wednesday, please contact Matt Harven and remind him to expedite a summary to us.\" (Matt Harven là đầu mối phụ trách báo cáo từ R&D).\nPhân tích bẫy:\n- (A) Bẫy trộn từ 'partner stores': các cửa hàng đối tác là nơi nhận slide vào thứ Hai tuần tới, không phải nơi gửi báo cáo R&D về tai nghe.\n- (B) Bẫy từ 'sport use': cụm \"for sport use\" chỉ mục đích sử dụng tai nghe được đánh giá trong nghiên cứu người dùng, không phải nghề nghiệp hay vai trò vận động viên nghiệp dư của ông Harven.\n- (D) Bẫy suy diễn chức danh: cuộc trò chuyện nói về việc chuyển slide cho cửa hàng đối tác và nhận báo cáo từ phòng R&D, không nhắc tới bộ phận hay giám đốc quảng cáo.","lines":[{"speaker":"Susan Gowan (9:16 A.M.)","en":"Good morning. The presentation slides about the new line of headphones are almost ready for distribution to our many partner stores. We are on track to send them out next Monday.","vi":"Chào buổi sáng mọi người. Bộ slide thuyết trình về dòng tai nghe mới gần như đã sẵn sàng để gửi tới nhiều cửa hàng đối tác của chúng ta. Chúng ta đang đi đúng tiến độ để gửi bộ slide này vào thứ Hai tuần tới.","units":[{"en":"Good morning.","vi":"Chào buổi sáng mọi người."},{"en":"The presentation slides about the new line of headphones are almost ready for distribution to our many partner stores.","vi":"Bộ slide thuyết trình về dòng tai nghe mới gần như đã sẵn sàng để gửi tới nhiều cửa hàng đối tác của chúng ta."},{"en":"We are on track to send them out next Monday.","vi":"Chúng ta đang đi đúng tiến độ để gửi bộ slide này vào thứ Hai tuần tới."}]},{"speaker":"Maggie Lorenz (9:17 A.M.)","en":"How do they look?","vi":"Các slide trông thế nào rồi?","units":[{"en":"How do they look?","vi":"Các slide trông thế nào rồi?"}]},{"speaker":"Susan Gowan (9:20 A.M.)","en":"There are still some missing elements.","vi":"Vẫn còn thiếu một vài phần nội dung.","units":[{"en":"There are still some missing elements.","vi":"Vẫn còn thiếu một vài phần nội dung."}]},{"speaker":"Alan Woodson (9:21 A.M.)","en":"We mainly need the information from the user studies that reviewed the headphones for sport use. We should have that report from the research and development office by Wednesday.","vi":"Chúng ta chủ yếu cần thông tin từ các nghiên cứu người dùng đánh giá mẫu tai nghe này khi sử dụng cho mục đích thể thao. Chậm nhất đến thứ Tư chúng ta sẽ nhận được báo cáo đó từ bộ phận nghiên cứu và phát triển.","units":[{"en":"We mainly need the information from the user studies that reviewed the headphones for sport use.","vi":"Chúng ta chủ yếu cần thông tin từ các nghiên cứu người dùng đánh giá mẫu tai nghe này khi sử dụng cho mục đích thể thao."},{"en":"We should have that report from the research and development office by Wednesday.","vi":"Chậm nhất đến thứ Tư chúng ta sẽ nhận được báo cáo đó từ bộ phận nghiên cứu và phát triển."}]},{"speaker":"Maggie Lorenz (9:22 A.M.)","en":"Yes, let's not overlook that. And if you're concerned about the report not arriving by Wednesday, please contact Matt Harven and remind him to expedite a summary to us.","vi":"Đúng vậy, chúng ta đừng bỏ sót phần đó. Và nếu lo ngại báo cáo sẽ không đến kịp thứ Tư, hãy liên hệ với Matt Harven và nhắc anh ấy khẩn trương gửi trước bản tóm tắt cho chúng ta.","units":[{"en":"Yes, let's not overlook that.","vi":"Đúng vậy, chúng ta đừng bỏ sót phần đó."},{"en":"And if you're concerned about the report not arriving by Wednesday, please contact Matt Harven and remind him to expedite a summary to us.","vi":"Và nếu lo ngại báo cáo sẽ không đến kịp thứ Tư, hãy liên hệ với Matt Harven và nhắc anh ấy khẩn trương gửi trước bản tóm tắt cho chúng ta."}]},{"speaker":"Susan Gowan (9:23 A.M.)","en":"Assuming we receive that summary soon enough to incorporate its findings into the slides, should the three of us schedule a trial run through the presentation on Thursday or Friday?","vi":"Giả sử chúng ta nhận được bản tóm tắt đó đủ sớm để đưa các kết quả nghiên cứu vào slide, liệu ba người chúng ta nên lên lịch chạy thử bài thuyết trình vào thứ Năm hay thứ Sáu?","units":[{"en":"Assuming we receive that summary soon enough to incorporate its findings into the slides, should the three of us schedule a trial run through the presentation on Thursday or Friday?","vi":"Giả sử chúng ta nhận được bản tóm tắt đó đủ sớm để đưa các kết quả nghiên cứu vào slide, liệu ba người chúng ta nên lên lịch chạy thử bài thuyết trình vào thứ Năm hay thứ Sáu?"}]},{"speaker":"Maggie Lorenz (9:24 A.M.)","en":"Let's try for Thursday afternoon. Then we will still have Friday to make any necessary changes.","vi":"Hãy thu xếp vào chiều thứ Năm nhé. Như vậy chúng ta vẫn còn ngày thứ Sáu để thực hiện bất kỳ chỉnh sửa cần thiết nào.","units":[{"en":"Let's try for Thursday afternoon.","vi":"Hãy thu xếp vào chiều thứ Năm nhé."},{"en":"Then we will still have Friday to make any necessary changes.","vi":"Như vậy chúng ta vẫn còn ngày thứ Sáu để thực hiện bất kỳ chỉnh sửa cần thiết nào."}]},{"speaker":"Alan Woodson (9:25 A.M.)","en":"Fine by me. I'm free after 2 P.M.","vi":"Tôi thấy ổn thôi. Tôi rảnh sau 2 giờ chiều.","units":[{"en":"Fine by me.","vi":"Tôi thấy ổn thôi."},{"en":"I'm free after 2 P.M.","vi":"Tôi rảnh sau 2 giờ chiều."}]}],"vocab":[{"word":"research and development","pos":"phr","ipa":"/rɪˈsɜːrtʃ ənd dɪˈveləpmənt/","meaning":"nghiên cứu và phát triển"},{"word":"expedite","pos":"v","ipa":"/ˈekspədaɪt/","meaning":"xúc tiến, đẩy nhanh tiến độ gửi"},{"word":"summary","pos":"n","ipa":"/ˈsʌməri/","meaning":"bản tóm tắt"}],"isScanBacked":false,"docTypeLabel":"online chat discussion","context":"Online chat discussion among Susan Gowan, Maggie Lorenz, and Alan Woodson about headphone presentation slides","grammarType":"Part 7 — Suy luận & Hàm ý văn bản (Inference & Implied Meaning)","formula":"CÔNG THỨC PART 7 (Suy luận Nghề nghiệp / Vai trò — Dạng 27): Nối nguồn tài liệu ('report from the research and development office') với người phụ trách thúc đẩy gửi bản tóm tắt ('contact Matt Harven') -> Suy ra chuyên viên nghiên cứu sản phẩm.","optionAnalysis":{"A":"Nhầm ngữ cảnh 'stores': Cửa hàng đối tác là bên nhận slide thành phẩm, không phải đầu mối gửi báo cáo nghiên cứu từ văn phòng R&D.","B":"Bẫy liên tưởng từ 'sport use': Tai nghe được thử nghiệm 'for sport use', nhưng Matt Harven là người nắm giữ báo cáo R&D chứ không phải vận động viên.","C":"Chính xác: Ông Harven là người cần liên hệ để gửi gấp bản tóm tắt báo cáo từ 'research and development office', nên nhiều khả năng nhất ông là chuyên viên nghiên cứu sản phẩm.","D":"Suy diễn không căn cứ: Không có chi tiết nào về hoạt động quảng cáo hay chức danh giám đốc điều hành quảng cáo gắn với ông Harven."},"evDocIdx":0,"evTargets":[{"badge":"Câu 174 · Đáp án C","opt":"C","isCorrect":true,"quote":"We should have that report from the research and development office by Wednesday.","viQuote":"Chậm nhất đến thứ Tư chúng ta sẽ nhận được báo cáo đó từ bộ phận nghiên cứu và phát triển."},{"badge":"Câu 174 · Đáp án C","opt":"C","isCorrect":true,"quote":"And if you're concerned about the report not arriving by Wednesday, please contact Matt Harven and remind him to expedite a summary to us.","viQuote":"Và nếu lo ngại báo cáo sẽ không đến kịp thứ Tư, hãy liên hệ với Matt Harven và nhắc anh ấy khẩn trương gửi trước bản tóm tắt cho chúng ta."}],"evQuotes":["We should have that report from the research and development office by Wednesday.","And if you're concerned about the report not arriving by Wednesday, please contact Matt Harven and remind him to expedite a summary to us."]},{"q":175,"part":7,"group_id":"E25_T01_G172_175","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc17.webp"],"stem_en":"When do the writers plan to meet to review a slide presentation?","stem_vi":"Những người tham gia trao đổi dự định gặp nhau khi nào để xem lại bài thuyết trình slide?","options":{"A":{"en":"On Monday","vi":"Vào thứ Hai"},"B":{"en":"On Wednesday","vi":"Vào thứ Tư"},"C":{"en":"On Thursday","vi":"Vào thứ Năm"},"D":{"en":"On Friday","vi":"Vào thứ Sáu"}},"ans":"C","evidence_quote":"- Assuming we receive that summary soon enough to incorporate its findings into the slides, should the three of us schedule a trial run through the presentation on Thursday or Friday? - Let's try for Thursday afternoon. - Fine by me. I'm free after 2 P.M.","explanation":"Đáp án đúng: (C) Vào thứ Năm — bà Gowan hỏi nên chạy thử vào thứ Năm hay thứ Sáu, bà Lorenz đề xuất chiều thứ Năm và ông Woodson đồng ý mình rảnh sau 2 giờ chiều.\nDẫn chứng: Susan Gowan (9:23 A.M.): \"schedule a trial run through the presentation on Thursday or Friday?\" -> Maggie Lorenz (9:24 A.M.): \"Let's try for Thursday afternoon.\" -> Alan Woodson (9:25 A.M.): \"Fine by me. I'm free after 2 P.M.\" (Chốt lịch họp chạy thử vào chiều thứ Năm).\nPhân tích bẫy:\n- (A) Bẫy mốc ngày gửi đi: thứ Hai tuần tới (\"next Monday\") là ngày dự kiến gửi bộ slide cho các cửa hàng đối tác, không phải ngày nhóm gặp xem lại.\n- (B) Bẫy mốc ngày nhận báo cáo: thứ Tư (\"by Wednesday\") là hạn chót nhận báo cáo từ bộ phận R&D.\n- (D) Bẫy phương án bị loại trong thương lượng: thứ Sáu được bà Gowan đưa ra như một lựa chọn dự phòng và được bà Lorenz giữ lại để chỉnh sửa sau (\"have Friday to make any necessary changes\"), không phải ngày hẹn gặp chạy thử.","lines":[{"speaker":"Susan Gowan (9:16 A.M.)","en":"Good morning. The presentation slides about the new line of headphones are almost ready for distribution to our many partner stores. We are on track to send them out next Monday.","vi":"Chào buổi sáng mọi người. Bộ slide thuyết trình về dòng tai nghe mới gần như đã sẵn sàng để gửi tới nhiều cửa hàng đối tác của chúng ta. Chúng ta đang đi đúng tiến độ để gửi bộ slide này vào thứ Hai tuần tới.","units":[{"en":"Good morning.","vi":"Chào buổi sáng mọi người."},{"en":"The presentation slides about the new line of headphones are almost ready for distribution to our many partner stores.","vi":"Bộ slide thuyết trình về dòng tai nghe mới gần như đã sẵn sàng để gửi tới nhiều cửa hàng đối tác của chúng ta."},{"en":"We are on track to send them out next Monday.","vi":"Chúng ta đang đi đúng tiến độ để gửi bộ slide này vào thứ Hai tuần tới."}]},{"speaker":"Maggie Lorenz (9:17 A.M.)","en":"How do they look?","vi":"Các slide trông thế nào rồi?","units":[{"en":"How do they look?","vi":"Các slide trông thế nào rồi?"}]},{"speaker":"Susan Gowan (9:20 A.M.)","en":"There are still some missing elements.","vi":"Vẫn còn thiếu một vài phần nội dung.","units":[{"en":"There are still some missing elements.","vi":"Vẫn còn thiếu một vài phần nội dung."}]},{"speaker":"Alan Woodson (9:21 A.M.)","en":"We mainly need the information from the user studies that reviewed the headphones for sport use. We should have that report from the research and development office by Wednesday.","vi":"Chúng ta chủ yếu cần thông tin từ các nghiên cứu người dùng đánh giá mẫu tai nghe này khi sử dụng cho mục đích thể thao. Chậm nhất đến thứ Tư chúng ta sẽ nhận được báo cáo đó từ bộ phận nghiên cứu và phát triển.","units":[{"en":"We mainly need the information from the user studies that reviewed the headphones for sport use.","vi":"Chúng ta chủ yếu cần thông tin từ các nghiên cứu người dùng đánh giá mẫu tai nghe này khi sử dụng cho mục đích thể thao."},{"en":"We should have that report from the research and development office by Wednesday.","vi":"Chậm nhất đến thứ Tư chúng ta sẽ nhận được báo cáo đó từ bộ phận nghiên cứu và phát triển."}]},{"speaker":"Maggie Lorenz (9:22 A.M.)","en":"Yes, let's not overlook that. And if you're concerned about the report not arriving by Wednesday, please contact Matt Harven and remind him to expedite a summary to us.","vi":"Đúng vậy, chúng ta đừng bỏ sót phần đó. Và nếu lo ngại báo cáo sẽ không đến kịp thứ Tư, hãy liên hệ với Matt Harven và nhắc anh ấy khẩn trương gửi trước bản tóm tắt cho chúng ta.","units":[{"en":"Yes, let's not overlook that.","vi":"Đúng vậy, chúng ta đừng bỏ sót phần đó."},{"en":"And if you're concerned about the report not arriving by Wednesday, please contact Matt Harven and remind him to expedite a summary to us.","vi":"Và nếu lo ngại báo cáo sẽ không đến kịp thứ Tư, hãy liên hệ với Matt Harven và nhắc anh ấy khẩn trương gửi trước bản tóm tắt cho chúng ta."}]},{"speaker":"Susan Gowan (9:23 A.M.)","en":"Assuming we receive that summary soon enough to incorporate its findings into the slides, should the three of us schedule a trial run through the presentation on Thursday or Friday?","vi":"Giả sử chúng ta nhận được bản tóm tắt đó đủ sớm để đưa các kết quả nghiên cứu vào slide, liệu ba người chúng ta nên lên lịch chạy thử bài thuyết trình vào thứ Năm hay thứ Sáu?","units":[{"en":"Assuming we receive that summary soon enough to incorporate its findings into the slides, should the three of us schedule a trial run through the presentation on Thursday or Friday?","vi":"Giả sử chúng ta nhận được bản tóm tắt đó đủ sớm để đưa các kết quả nghiên cứu vào slide, liệu ba người chúng ta nên lên lịch chạy thử bài thuyết trình vào thứ Năm hay thứ Sáu?"}]},{"speaker":"Maggie Lorenz (9:24 A.M.)","en":"Let's try for Thursday afternoon. Then we will still have Friday to make any necessary changes.","vi":"Hãy thu xếp vào chiều thứ Năm nhé. Như vậy chúng ta vẫn còn ngày thứ Sáu để thực hiện bất kỳ chỉnh sửa cần thiết nào.","units":[{"en":"Let's try for Thursday afternoon.","vi":"Hãy thu xếp vào chiều thứ Năm nhé."},{"en":"Then we will still have Friday to make any necessary changes.","vi":"Như vậy chúng ta vẫn còn ngày thứ Sáu để thực hiện bất kỳ chỉnh sửa cần thiết nào."}]},{"speaker":"Alan Woodson (9:25 A.M.)","en":"Fine by me. I'm free after 2 P.M.","vi":"Tôi thấy ổn thôi. Tôi rảnh sau 2 giờ chiều.","units":[{"en":"Fine by me.","vi":"Tôi thấy ổn thôi."},{"en":"I'm free after 2 P.M.","vi":"Tôi rảnh sau 2 giờ chiều."}]}],"vocab":[{"word":"incorporate","pos":"v","ipa":"/ɪnˈkɔːrpəreɪt/","meaning":"đưa vào, lồng ghép, tích hợp"},{"word":"findings","pos":"n","ipa":"/ˈfaɪndɪŋz/","meaning":"kết quả nghiên cứu, phát hiện"},{"word":"trial run","pos":"n","ipa":"/ˈtraɪəl rʌn/","meaning":"buổi chạy thử, diễn tập thử"},{"word":"assuming","pos":"conj","ipa":"/əˈsuːmɪŋ/","meaning":"giả sử rằng, với điều kiện là"}],"isScanBacked":false,"docTypeLabel":"online chat discussion","context":"Online chat discussion among Susan Gowan, Maggie Lorenz, and Alan Woodson about headphone presentation slides","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 (Tin nhắn Chat — Chốt Lịch hẹn — Dạng 42 & 23): Đọc trọn chuỗi đề xuất và xác nhận ở cuối đoạn chat (9:23 đến 9:25 A.M.) để phân biệt ngày chốt gặp mặt với các mốc ngày khác.","optionAnalysis":{"A":"Bẫy sai sự kiện: Thứ Hai tuần tới là lịch gửi bộ slide hoàn chỉnh tới các cửa hàng đối tác ('send them out next Monday').","B":"Bẫy sai sự kiện: Thứ Tư là hạn nhận báo cáo nghiên cứu từ phòng R&D ('by Wednesday'), chưa phải buổi chạy thử bài thuyết trình.","C":"Chính xác: Bà Lorenz đề xuất 'Thursday afternoon' để kịp thứ Sáu chỉnh sửa và ông Woodson chốt 'Fine by me. I'm free after 2 P.M.'.","D":"Bẫy lựa chọn bị gạt: Thứ Sáu chỉ được giữ lại làm ngày dự phòng chỉnh sửa ('make any necessary changes') sau buổi chạy thử chiều thứ Năm."},"evDocIdx":0,"evTargets":[{"badge":"Câu 175 · Đáp án C","opt":"C","isCorrect":true,"quote":"Assuming we receive that summary soon enough to incorporate its findings into the slides, should the three of us schedule a trial run through the presentation on Thursday or Friday?","viQuote":"Giả sử chúng ta nhận được bản tóm tắt đó đủ sớm để đưa các kết quả nghiên cứu vào slide, liệu ba người chúng ta nên lên lịch chạy thử bài thuyết trình vào thứ Năm hay thứ Sáu?"},{"badge":"Câu 175 · Đáp án C","opt":"C","isCorrect":true,"quote":"Let's try for Thursday afternoon.","viQuote":"Hãy thu xếp vào chiều thứ Năm nhé."},{"badge":"Câu 175 · Đáp án C","opt":"C","isCorrect":true,"quote":"I'm free after 2 P.M.","viQuote":"Tôi rảnh sau 2 giờ chiều."}],"evQuotes":["Assuming we receive that summary soon enough to incorporate its findings into the slides, should the three of us schedule a trial run through the presentation on Thursday or Friday?","Let's try for Thursday afternoon.","I'm free after 2 P.M."]},{"q":176,"part":7,"group_id":"E25_T01_G176_180","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc19.webp","web_assets/ets2025/p67/E25_T01_rc20.webp"],"stem_en":"What is the purpose of the press release?","stem_vi":"Mục đích của thông cáo báo chí này là gì?","options":{"A":{"en":"To promote the opening of a restaurant","vi":"Quảng bá lễ khai trương một nhà hàng"},"B":{"en":"To announce a business partnership","vi":"Thông báo về một quan hệ hợp tác kinh doanh"},"C":{"en":"To introduce a travel program","vi":"Giới thiệu một chương trình du lịch"},"D":{"en":"To congratulate an award recipient","vi":"Chúc mừng một người nhận giải thưởng"}},"ans":"B","evidence_quote":"Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience.","explanation":"Đáp án đúng: (B) Thông báo về một quan hệ hợp tác kinh doanh — ngay câu mở đầu thông cáo báo chí (Document 1) công bố Kitchen Swifts và Đầu bếp Darius Cordero bắt tay hợp tác (\"joining together\" / \"the partnership\") để mang đến công thức nấu ăn mới cho người nội trợ.\nDẫn chứng: \"SYDNEY (4 June)—Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience.\" và \"Current customers will see no price increase with the partnership.\" (Document 1 — Press Release: Kitchen Swifts và Đầu bếp Darius Cordero hợp tác cùng nhau; sự hợp tác này không làm tăng giá với khách hiện tại).\nPhân tích bẫy:\n- (A) Sai bối cảnh chi tiết phụ: Nhà hàng Enriqua's chỉ được nhắc thoáng qua là \"recently opened\" để giới thiệu lý lịch của đầu bếp Cordero, không phải mục đích quảng bá lễ khai trương nhà hàng.\n- (C) Bẫy hiểu nhầm nghĩa bóng: Cụm \"feel like you are travelling the world with me\" chỉ là lời ví von của đầu bếp về hương vị đa văn hóa của các bữa ăn, không phải giới thiệu chương trình du lịch.\n- (D) Bóp méo thông tin tiểu sử: Bài dùng cụm \"award-winning chef\" (đầu bếp từng đoạt giải) để giới thiệu ông Cordero, hoàn toàn không nhằm chúc mừng một người mới nhận giải thưởng.","lines":[{"speaker":"Document 1 — Press Release","en":"Aparna Kothari, Media Contact","vi":"Aparna Kothari, Đầu mối liên hệ truyền thông","units":[{"en":"Aparna Kothari, Media Contact","vi":"Aparna Kothari, Đầu mối liên hệ truyền thông"}]},{"speaker":"Document 1 — Press Release","en":"Kitchen Swifts","vi":"Kitchen Swifts","units":[{"en":"Kitchen Swifts","vi":"Kitchen Swifts"}]},{"speaker":"Document 1 — Press Release","en":"akothari@kitchenswifts.com.au","vi":"akothari@kitchenswifts.com.au","units":[{"en":"akothari@kitchenswifts.com.au","vi":"akothari@kitchenswifts.com.au"}]},{"speaker":"Document 1 — Press Release","en":"FOR IMMEDIATE RELEASE","vi":"THÔNG CÁO PHÁT HÀNH NGAY","units":[{"en":"FOR IMMEDIATE RELEASE","vi":"THÔNG CÁO PHÁT HÀNH NGAY"}]},{"speaker":"Document 1 — Press Release","en":"SYDNEY (4 June)—Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience. The award-winning chef is the owner of restaurants in both the Philippines and Australia, including the recently opened Enriqua's. He says his cooking reflects his Filipino heritage, which is a blend of many cultures.","vi":"SYDNEY (ngày 4 tháng 6)—Kitchen Swifts và Đầu bếp Darius Cordero đang hợp tác cùng nhau nhằm mang đến cho những người nấu ăn tại nhà một trải nghiệm ẩm thực mới mẻ. Vị đầu bếp từng đoạt giải thưởng này là chủ sở hữu của nhiều nhà hàng tại cả Philippines và Úc, trong đó có nhà hàng Enriqua's vừa khai trương gần đây. Ông cho biết phong cách nấu nướng của mình phản ánh di sản văn hóa Philippines — sự giao thoa của nhiều nền văn hóa.","units":[{"en":"SYDNEY (4 June)—Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience.","vi":"SYDNEY (ngày 4 tháng 6)—Kitchen Swifts và Đầu bếp Darius Cordero đang hợp tác cùng nhau nhằm mang đến cho những người nấu ăn tại nhà một trải nghiệm ẩm thực mới mẻ."},{"en":"The award-winning chef is the owner of restaurants in both the Philippines and Australia, including the recently opened Enriqua's.","vi":"Vị đầu bếp từng đoạt giải thưởng này là chủ sở hữu của nhiều nhà hàng tại cả Philippines và Úc, trong đó có nhà hàng Enriqua's vừa khai trương gần đây."},{"en":"He says his cooking reflects his Filipino heritage, which is a blend of many cultures.","vi":"Ông cho biết phong cách nấu nướng của mình phản ánh di sản văn hóa Philippines — sự giao thoa của nhiều nền văn hóa."}]},{"speaker":"Document 1 — Press Release","en":"\"I've designed these simplified recipes for Kitchen Swifts so that cooks at home can enjoy new and exciting flavours with ease,\" he said. \"While preparing and eating these meals, you can feel like you are travelling the world with me.\"","vi":"\"Tôi đã thiết kế những công thức đơn giản hóa này cho Kitchen Swifts để những người nấu ăn tại nhà có thể dễ dàng thưởng thức những hương vị mới lạ và hấp dẫn,\" ông chia sẻ. \"Khi chế biến và thưởng thức những bữa ăn này, bạn có thể cảm nhận như đang cùng tôi chu du khắp thế giới.\"","units":[{"en":"\"I've designed these simplified recipes for Kitchen Swifts so that cooks at home can enjoy new and exciting flavours with ease,\" he said.","vi":"\"Tôi đã thiết kế những công thức đơn giản hóa này cho Kitchen Swifts để những người nấu ăn tại nhà có thể dễ dàng thưởng thức những hương vị mới lạ và hấp dẫn,\" ông chia sẻ."},{"en":"\"While preparing and eating these meals, you can feel like you are travelling the world with me.\"","vi":"\"Khi chế biến và thưởng thức những bữa ăn này, bạn có thể cảm nhận như đang cùng tôi chu du khắp thế giới.\""}]},{"speaker":"Document 1 — Press Release","en":"Zahra Chambers, vice president of Kitchen Swifts, says she is pleased to work with Chef Cordero and to offer delicious new recipes to their customers. Kitchen Swifts supplies menus, recipes, and ingredients for two people, four people, or six people, including a range of vegetarian selections. Customers choose the most appropriate meal options, and then a box is delivered weekly. Current customers will see no price increase with the partnership. To find out more, visit the Kitchen Swifts Web site at www.kitchenswifts.com.au.","vi":"Bà Zahra Chambers, Phó Chủ tịch của Kitchen Swifts, cho biết bà rất vui mừng được hợp tác với Đầu bếp Cordero và mang đến những công thức mới thơm ngon cho khách hàng của mình. Kitchen Swifts cung cấp thực đơn, công thức nấu ăn và nguyên liệu dành cho hai người, bốn người hoặc sáu người, bao gồm nhiều lựa chọn món chay phong phú. Khách hàng lựa chọn các gói bữa ăn phù hợp nhất, sau đó một hộp nguyên liệu sẽ được giao tận nơi hằng tuần. Các khách hàng hiện tại sẽ không phải chịu bất kỳ mức tăng giá nào từ sự hợp tác này. Để tìm hiểu thêm thông tin, vui lòng truy cập trang web của Kitchen Swifts tại địa chỉ www.kitchenswifts.com.au.","units":[{"en":"Zahra Chambers, vice president of Kitchen Swifts, says she is pleased to work with Chef Cordero and to offer delicious new recipes to their customers.","vi":"Bà Zahra Chambers, Phó Chủ tịch của Kitchen Swifts, cho biết bà rất vui mừng được hợp tác với Đầu bếp Cordero và mang đến những công thức mới thơm ngon cho khách hàng của mình."},{"en":"Kitchen Swifts supplies menus, recipes, and ingredients for two people, four people, or six people, including a range of vegetarian selections.","vi":"Kitchen Swifts cung cấp thực đơn, công thức nấu ăn và nguyên liệu dành cho hai người, bốn người hoặc sáu người, bao gồm nhiều lựa chọn món chay phong phú."},{"en":"Customers choose the most appropriate meal options, and then a box is delivered weekly.","vi":"Khách hàng lựa chọn các gói bữa ăn phù hợp nhất, sau đó một hộp nguyên liệu sẽ được giao tận nơi hằng tuần."},{"en":"Current customers will see no price increase with the partnership.","vi":"Các khách hàng hiện tại sẽ không phải chịu bất kỳ mức tăng giá nào từ sự hợp tác này."},{"en":"To find out more, visit the Kitchen Swifts Web site at www.kitchenswifts.com.au.","vi":"Để tìm hiểu thêm thông tin, vui lòng truy cập trang web của Kitchen Swifts tại địa chỉ www.kitchenswifts.com.au."}]},{"speaker":"Document 2 — Review","en":"https://www.sydneyrestaurants.com.au","vi":"https://www.sydneyrestaurants.com.au","units":[{"en":"https://www.sydneyrestaurants.com.au","vi":"https://www.sydneyrestaurants.com.au"}]},{"speaker":"Document 2 — Review","en":"A colleague arranged for us to eat at Enriqua's while I was at a conference in Sydney. It is usually fully booked for dinner; you may need to call months in advance for a table. We had a wonderful lunch there instead. Everything was delicious, and the bread and desserts are baked on-site! It was a worthwhile treat before I flew back to Hong Kong.","vi":"Một đồng nghiệp đã thu xếp cho chúng tôi dùng bữa tại Enriqua's trong thời gian tôi tham dự một hội nghị ở Sydney. Nhà hàng thường kín chỗ vào bữa tối; bạn có thể cần phải gọi điện đặt bàn trước nhiều tháng. Thay vào đó, chúng tôi đã có một bữa trưa tuyệt vời tại đây. Món nào cũng rất ngon, hơn nữa bánh mì và các món tráng miệng đều được nướng ngay tại chỗ! Đó thực sự là một bữa ăn thật đáng giá trước khi tôi bay về Hong Kong.","units":[{"en":"A colleague arranged for us to eat at Enriqua's while I was at a conference in Sydney.","vi":"Một đồng nghiệp đã thu xếp cho chúng tôi dùng bữa tại Enriqua's trong thời gian tôi tham dự một hội nghị ở Sydney."},{"en":"It is usually fully booked for dinner; you may need to call months in advance for a table.","vi":"Nhà hàng thường kín chỗ vào bữa tối; bạn có thể cần phải gọi điện đặt bàn trước nhiều tháng."},{"en":"We had a wonderful lunch there instead.","vi":"Thay vào đó, chúng tôi đã có một bữa trưa tuyệt vời tại đây."},{"en":"Everything was delicious, and the bread and desserts are baked on-site!","vi":"Món nào cũng rất ngon, hơn nữa bánh mì và các món tráng miệng đều được nướng ngay tại chỗ!"},{"en":"It was a worthwhile treat before I flew back to Hong Kong.","vi":"Đó thực sự là một bữa ăn thật đáng giá trước khi tôi bay về Hong Kong."}]},{"speaker":"Document 2 — Review","en":"—Meili Guan","vi":"—Meili Guan","units":[{"en":"—Meili Guan","vi":"—Meili Guan"}]}],"vocab":[{"word":"press release","pos":"n","ipa":"/ˈpres rɪˌliːs/","meaning":"thông cáo báo chí"},{"word":"partnership","pos":"n","ipa":"/ˈpɑːrtnərʃɪp/","meaning":"quan hệ hợp tác, sự liên kết kinh doanh"},{"word":"culinary","pos":"adj","ipa":"/ˈkʌlɪneri/","meaning":"thuộc về ẩm thực, nấu nướng"},{"word":"join together","pos":"phr. v","ipa":"/dʒɔɪn təˈɡeðər/","meaning":"hợp tác, bắt tay cùng nhau"}],"isScanBacked":false,"docTypeLabel":"press release and review","context":"Press release and review — Kitchen Swifts & Chef Darius Cordero / Enriqua's","grammarType":"Part 7 — Ý chính, Mục đích & Đối tượng đọc (Main Idea & Purpose)","formula":"CÔNG THỨC PART 7 (Thông cáo báo chí — Xác định mục đích văn bản): Đọc câu mở đầu ngay sau FOR IMMEDIATE RELEASE để chốt sự kiện trọng tâm — 'joining together' / 'the partnership' = 'business partnership' (B).","optionAnalysis":{"A":"Bẫy chi tiết phụ: Enriqua's chỉ được nhắc là nhà hàng 'recently opened' của đầu bếp Cordero nhằm giới thiệu ông, không phải mục tiêu quảng bá khai trương của thông cáo.","B":"Chính xác: Câu mở đầu 'joining together' và đoạn cuối 'with the partnership' ở Document 1 khẳng định mục đích thông cáo là công bố hợp tác giữa Kitchen Swifts và Đầu bếp Cordero.","C":"Bẫy ẩn dụ từ vựng: Cụm 'travelling the world with me' chỉ là cách ví von trải nghiệm hương vị ẩm thực khi nấu ăn tại nhà, không phải giới thiệu chương trình du lịch.","D":"Sai mục đích: Văn bản chỉ dùng cụm 'award-winning chef' làm danh xưng giới thiệu ông Cordero, hoàn toàn không có nội dung chúc mừng người nhận giải thưởng."},"evDocIdx":0,"evTargets":[{"badge":"Câu 176 · Đáp án B","opt":"B","isCorrect":true,"quote":"Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience.","viQuote":"Kitchen Swifts và Đầu bếp Darius Cordero đang hợp tác cùng nhau nhằm mang đến cho những người nấu ăn tại nhà một trải nghiệm ẩm thực mới mẻ."},{"badge":"Câu 176 · Đáp án B","opt":"B","isCorrect":true,"quote":"Current customers will see no price increase with the partnership.","viQuote":"Các khách hàng hiện tại sẽ không phải chịu bất kỳ mức tăng giá nào từ sự hợp tác này."}],"evQuotes":["Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience.","Current customers will see no price increase with the partnership."]},{"q":177,"part":7,"group_id":"E25_T01_G176_180","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc19.webp","web_assets/ets2025/p67/E25_T01_rc20.webp"],"stem_en":"In the press release, the word \"reflects\" in paragraph 1, line 4, is closest in meaning to","stem_vi":"Trong thông cáo báo chí, từ \"reflects\" ở đoạn 1, dòng 4 gần nghĩa nhất với","options":{"A":{"en":"results in","vi":"dẫn đến, gây ra"},"B":{"en":"changes","vi":"thay đổi"},"C":{"en":"shows","vi":"thể hiện, cho thấy"},"D":{"en":"thinks about","vi":"suy nghĩ về"}},"ans":"C","evidence_quote":"He says his cooking reflects his Filipino heritage, which is a blend of many cultures.","explanation":"Đáp án đúng: (C) shows (thể hiện, cho thấy) — trong ngữ cảnh phong cách ẩm thực, động từ \"reflects\" mang nghĩa phản ánh, bộc lộ bản sắc văn hóa qua món ăn, đồng nghĩa trực tiếp với \"shows\".\nDẫn chứng: \"He says his cooking reflects his Filipino heritage, which is a blend of many cultures.\" (Document 1 — Press Release: Ông cho biết phong cách nấu nướng của mình phản ánh/thể hiện di sản văn hóa Philippines — sự giao thoa của nhiều nền văn hóa).\nPhân tích bẫy:\n- (A) Sai quan hệ nhân quả: \"results in\" nghĩa là dẫn đến hoặc gây ra; cách nấu ăn không thể tạo ra di sản văn hóa vốn có của ông ấy.\n- (B) Sai sắc thái nghĩa: \"changes\" nghĩa là làm thay đổi di sản, trái ngược với ý bộc lộ và giữ gìn bản sắc Philippines trong câu gốc.\n- (D) Bẫy nghĩa khác của động từ \"reflect\": Phải đi với giới từ \"reflect on\" mới mang nghĩa suy nghĩ về (\"thinks about\"), hơn nữa chủ ngữ \"his cooking\" (phong cách nấu nướng) không thể thực hiện hành động suy nghĩ.","lines":[{"speaker":"Document 1 — Press Release","en":"Aparna Kothari, Media Contact","vi":"Aparna Kothari, Đầu mối liên hệ truyền thông","units":[{"en":"Aparna Kothari, Media Contact","vi":"Aparna Kothari, Đầu mối liên hệ truyền thông"}]},{"speaker":"Document 1 — Press Release","en":"Kitchen Swifts","vi":"Kitchen Swifts","units":[{"en":"Kitchen Swifts","vi":"Kitchen Swifts"}]},{"speaker":"Document 1 — Press Release","en":"akothari@kitchenswifts.com.au","vi":"akothari@kitchenswifts.com.au","units":[{"en":"akothari@kitchenswifts.com.au","vi":"akothari@kitchenswifts.com.au"}]},{"speaker":"Document 1 — Press Release","en":"FOR IMMEDIATE RELEASE","vi":"THÔNG CÁO PHÁT HÀNH NGAY","units":[{"en":"FOR IMMEDIATE RELEASE","vi":"THÔNG CÁO PHÁT HÀNH NGAY"}]},{"speaker":"Document 1 — Press Release","en":"SYDNEY (4 June)—Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience. The award-winning chef is the owner of restaurants in both the Philippines and Australia, including the recently opened Enriqua's. He says his cooking reflects his Filipino heritage, which is a blend of many cultures.","vi":"SYDNEY (ngày 4 tháng 6)—Kitchen Swifts và Đầu bếp Darius Cordero đang hợp tác cùng nhau nhằm mang đến cho những người nấu ăn tại nhà một trải nghiệm ẩm thực mới mẻ. Vị đầu bếp từng đoạt giải thưởng này là chủ sở hữu của nhiều nhà hàng tại cả Philippines và Úc, trong đó có nhà hàng Enriqua's vừa khai trương gần đây. Ông cho biết phong cách nấu nướng của mình phản ánh di sản văn hóa Philippines — sự giao thoa của nhiều nền văn hóa.","units":[{"en":"SYDNEY (4 June)—Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience.","vi":"SYDNEY (ngày 4 tháng 6)—Kitchen Swifts và Đầu bếp Darius Cordero đang hợp tác cùng nhau nhằm mang đến cho những người nấu ăn tại nhà một trải nghiệm ẩm thực mới mẻ."},{"en":"The award-winning chef is the owner of restaurants in both the Philippines and Australia, including the recently opened Enriqua's.","vi":"Vị đầu bếp từng đoạt giải thưởng này là chủ sở hữu của nhiều nhà hàng tại cả Philippines và Úc, trong đó có nhà hàng Enriqua's vừa khai trương gần đây."},{"en":"He says his cooking reflects his Filipino heritage, which is a blend of many cultures.","vi":"Ông cho biết phong cách nấu nướng của mình phản ánh di sản văn hóa Philippines — sự giao thoa của nhiều nền văn hóa."}]},{"speaker":"Document 1 — Press Release","en":"\"I've designed these simplified recipes for Kitchen Swifts so that cooks at home can enjoy new and exciting flavours with ease,\" he said. \"While preparing and eating these meals, you can feel like you are travelling the world with me.\"","vi":"\"Tôi đã thiết kế những công thức đơn giản hóa này cho Kitchen Swifts để những người nấu ăn tại nhà có thể dễ dàng thưởng thức những hương vị mới lạ và hấp dẫn,\" ông chia sẻ. \"Khi chế biến và thưởng thức những bữa ăn này, bạn có thể cảm nhận như đang cùng tôi chu du khắp thế giới.\"","units":[{"en":"\"I've designed these simplified recipes for Kitchen Swifts so that cooks at home can enjoy new and exciting flavours with ease,\" he said.","vi":"\"Tôi đã thiết kế những công thức đơn giản hóa này cho Kitchen Swifts để những người nấu ăn tại nhà có thể dễ dàng thưởng thức những hương vị mới lạ và hấp dẫn,\" ông chia sẻ."},{"en":"\"While preparing and eating these meals, you can feel like you are travelling the world with me.\"","vi":"\"Khi chế biến và thưởng thức những bữa ăn này, bạn có thể cảm nhận như đang cùng tôi chu du khắp thế giới.\""}]},{"speaker":"Document 1 — Press Release","en":"Zahra Chambers, vice president of Kitchen Swifts, says she is pleased to work with Chef Cordero and to offer delicious new recipes to their customers. Kitchen Swifts supplies menus, recipes, and ingredients for two people, four people, or six people, including a range of vegetarian selections. Customers choose the most appropriate meal options, and then a box is delivered weekly. Current customers will see no price increase with the partnership. To find out more, visit the Kitchen Swifts Web site at www.kitchenswifts.com.au.","vi":"Bà Zahra Chambers, Phó Chủ tịch của Kitchen Swifts, cho biết bà rất vui mừng được hợp tác với Đầu bếp Cordero và mang đến những công thức mới thơm ngon cho khách hàng của mình. Kitchen Swifts cung cấp thực đơn, công thức nấu ăn và nguyên liệu dành cho hai người, bốn người hoặc sáu người, bao gồm nhiều lựa chọn món chay phong phú. Khách hàng lựa chọn các gói bữa ăn phù hợp nhất, sau đó một hộp nguyên liệu sẽ được giao tận nơi hằng tuần. Các khách hàng hiện tại sẽ không phải chịu bất kỳ mức tăng giá nào từ sự hợp tác này. Để tìm hiểu thêm thông tin, vui lòng truy cập trang web của Kitchen Swifts tại địa chỉ www.kitchenswifts.com.au.","units":[{"en":"Zahra Chambers, vice president of Kitchen Swifts, says she is pleased to work with Chef Cordero and to offer delicious new recipes to their customers.","vi":"Bà Zahra Chambers, Phó Chủ tịch của Kitchen Swifts, cho biết bà rất vui mừng được hợp tác với Đầu bếp Cordero và mang đến những công thức mới thơm ngon cho khách hàng của mình."},{"en":"Kitchen Swifts supplies menus, recipes, and ingredients for two people, four people, or six people, including a range of vegetarian selections.","vi":"Kitchen Swifts cung cấp thực đơn, công thức nấu ăn và nguyên liệu dành cho hai người, bốn người hoặc sáu người, bao gồm nhiều lựa chọn món chay phong phú."},{"en":"Customers choose the most appropriate meal options, and then a box is delivered weekly.","vi":"Khách hàng lựa chọn các gói bữa ăn phù hợp nhất, sau đó một hộp nguyên liệu sẽ được giao tận nơi hằng tuần."},{"en":"Current customers will see no price increase with the partnership.","vi":"Các khách hàng hiện tại sẽ không phải chịu bất kỳ mức tăng giá nào từ sự hợp tác này."},{"en":"To find out more, visit the Kitchen Swifts Web site at www.kitchenswifts.com.au.","vi":"Để tìm hiểu thêm thông tin, vui lòng truy cập trang web của Kitchen Swifts tại địa chỉ www.kitchenswifts.com.au."}]},{"speaker":"Document 2 — Review","en":"https://www.sydneyrestaurants.com.au","vi":"https://www.sydneyrestaurants.com.au","units":[{"en":"https://www.sydneyrestaurants.com.au","vi":"https://www.sydneyrestaurants.com.au"}]},{"speaker":"Document 2 — Review","en":"A colleague arranged for us to eat at Enriqua's while I was at a conference in Sydney. It is usually fully booked for dinner; you may need to call months in advance for a table. We had a wonderful lunch there instead. Everything was delicious, and the bread and desserts are baked on-site! It was a worthwhile treat before I flew back to Hong Kong.","vi":"Một đồng nghiệp đã thu xếp cho chúng tôi dùng bữa tại Enriqua's trong thời gian tôi tham dự một hội nghị ở Sydney. Nhà hàng thường kín chỗ vào bữa tối; bạn có thể cần phải gọi điện đặt bàn trước nhiều tháng. Thay vào đó, chúng tôi đã có một bữa trưa tuyệt vời tại đây. Món nào cũng rất ngon, hơn nữa bánh mì và các món tráng miệng đều được nướng ngay tại chỗ! Đó thực sự là một bữa ăn thật đáng giá trước khi tôi bay về Hong Kong.","units":[{"en":"A colleague arranged for us to eat at Enriqua's while I was at a conference in Sydney.","vi":"Một đồng nghiệp đã thu xếp cho chúng tôi dùng bữa tại Enriqua's trong thời gian tôi tham dự một hội nghị ở Sydney."},{"en":"It is usually fully booked for dinner; you may need to call months in advance for a table.","vi":"Nhà hàng thường kín chỗ vào bữa tối; bạn có thể cần phải gọi điện đặt bàn trước nhiều tháng."},{"en":"We had a wonderful lunch there instead.","vi":"Thay vào đó, chúng tôi đã có một bữa trưa tuyệt vời tại đây."},{"en":"Everything was delicious, and the bread and desserts are baked on-site!","vi":"Món nào cũng rất ngon, hơn nữa bánh mì và các món tráng miệng đều được nướng ngay tại chỗ!"},{"en":"It was a worthwhile treat before I flew back to Hong Kong.","vi":"Đó thực sự là một bữa ăn thật đáng giá trước khi tôi bay về Hong Kong."}]},{"speaker":"Document 2 — Review","en":"—Meili Guan","vi":"—Meili Guan","units":[{"en":"—Meili Guan","vi":"—Meili Guan"}]}],"vocab":[{"word":"reflect","pos":"v","ipa":"/rɪˈflekt/","meaning":"phản ánh, thể hiện"},{"word":"heritage","pos":"n","ipa":"/ˈherɪtɪdʒ/","meaning":"di sản, truyền thống văn hóa"},{"word":"blend","pos":"n","ipa":"/blend/","meaning":"sự pha trộn, sự giao thoa"},{"word":"award-winning","pos":"adj","ipa":"/əˈwɔːrd ˌwɪnɪŋ/","meaning":"từng đoạt giải thưởng"}],"isScanBacked":false,"docTypeLabel":"press release and review","context":"Press release and review — Kitchen Swifts & Chef Darius Cordero / Enriqua's","grammarType":"Part 7 — Từ vựng trong ngữ cảnh (Vocabulary in Context)","formula":"CÔNG THỨC PART 7 (Từ vựng trong ngữ cảnh — Phép thế trực tiếp): Đặt từng phương án vào vị trí động từ trong 'his cooking ___ his Filipino heritage' để kiểm tra nghĩa 'phản ánh, bộc lộ bản sắc' -> 'reflects' = 'shows' (C).","optionAnalysis":{"A":"Sai logic nhân quả: 'results in' (dẫn đến) khiến câu mang nghĩa việc nấu nướng tạo ra di sản văn hóa, sai hoàn toàn so với ý phản ánh bản sắc sẵn có.","B":"Sai nghĩa ngữ cảnh: 'changes' (thay đổi) làm biến dạng ý gốc là phong cách nấu ăn thể hiện di sản Philippines chứ không làm thay đổi di sản đó.","C":"Chính xác: Thay 'shows' vào câu 'his cooking shows his Filipino heritage' giữ nguyên trọn vẹn nghĩa phong cách nấu nướng phản ánh, thể hiện rõ nguồn cội văn hóa.","D":"Bẫy đa nghĩa của 'reflect': 'reflect on' mới gần nghĩa 'thinks about' (suy nghĩ về), nhưng chủ ngữ là 'his cooking' (khái niệm) nên không thể suy nghĩ."},"evDocIdx":0,"evTargets":[{"badge":"Câu 177 · Đáp án C","opt":"C","isCorrect":true,"quote":"He says his cooking reflects his Filipino heritage, which is a blend of many cultures.","viQuote":"Ông cho biết phong cách nấu nướng của mình phản ánh di sản văn hóa Philippines — sự giao thoa của nhiều nền văn hóa."}],"evQuotes":["He says his cooking reflects his Filipino heritage, which is a blend of many cultures."]},{"q":178,"part":7,"group_id":"E25_T01_G176_180","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc19.webp","web_assets/ets2025/p67/E25_T01_rc20.webp"],"stem_en":"What is indicated about Kitchen Swifts?","stem_vi":"Điều gì được đề cập về Kitchen Swifts?","options":{"A":{"en":"It raised its prices for all customers.","vi":"Công ty đã tăng giá đối với tất cả khách hàng."},"B":{"en":"It revised its delivery schedule.","vi":"Công ty đã điều chỉnh lịch trình giao hàng."},"C":{"en":"It offers several meal options.","vi":"Công ty cung cấp nhiều lựa chọn bữa ăn."},"D":{"en":"It has a new vice president.","vi":"Công ty có một phó chủ tịch mới."}},"ans":"C","evidence_quote":"Kitchen Swifts supplies menus, recipes, and ingredients for two people, four people, or six people, including a range of","explanation":"Đáp án đúng: (C) Công ty cung cấp nhiều lựa chọn bữa ăn — đoạn 3 của Document 1 nêu rõ Kitchen Swifts cung cấp thực đơn cho 2, 4 hoặc 6 người, kèm nhiều món chay và cho phép khách hàng chọn gói bữa ăn phù hợp nhất (\"the most appropriate meal options\").\nDẫn chứng: \"Kitchen Swifts supplies menus, recipes, and ingredients for two people, four people, or six people, including a range of vegetarian selections. Customers choose the most appropriate meal options, and then a box is delivered weekly.\" (Document 1 — Press Release: Kitchen Swifts cung cấp thực đơn cho 2, 4 hoặc 6 người kèm nhiều món chay để khách chọn lựa chọn bữa ăn phù hợp nhất).\nPhân tích bẫy:\n- (A) Trái ngược trực tiếp với bài đọc: Văn bản khẳng định \"Current customers will see no price increase with the partnership\" (khách hàng hiện tại không bị tăng giá).\n- (B) Suy diễn sai từ chi tiết giao hàng: Bài chỉ nêu hộp nguyên liệu \"is delivered weekly\" (được giao hằng tuần), không có thông tin nào nói công ty đã điều chỉnh lại lịch giao.\n- (D) Suy diễn sai về chức danh: Bà Zahra Chambers được giới thiệu là \"vice president of Kitchen Swifts\", không có dữ kiện nào cho biết bà là phó chủ tịch mới được bổ nhiệm.","lines":[{"speaker":"Document 1 — Press Release","en":"Aparna Kothari, Media Contact","vi":"Aparna Kothari, Đầu mối liên hệ truyền thông","units":[{"en":"Aparna Kothari, Media Contact","vi":"Aparna Kothari, Đầu mối liên hệ truyền thông"}]},{"speaker":"Document 1 — Press Release","en":"Kitchen Swifts","vi":"Kitchen Swifts","units":[{"en":"Kitchen Swifts","vi":"Kitchen Swifts"}]},{"speaker":"Document 1 — Press Release","en":"akothari@kitchenswifts.com.au","vi":"akothari@kitchenswifts.com.au","units":[{"en":"akothari@kitchenswifts.com.au","vi":"akothari@kitchenswifts.com.au"}]},{"speaker":"Document 1 — Press Release","en":"FOR IMMEDIATE RELEASE","vi":"THÔNG CÁO PHÁT HÀNH NGAY","units":[{"en":"FOR IMMEDIATE RELEASE","vi":"THÔNG CÁO PHÁT HÀNH NGAY"}]},{"speaker":"Document 1 — Press Release","en":"SYDNEY (4 June)—Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience. The award-winning chef is the owner of restaurants in both the Philippines and Australia, including the recently opened Enriqua's. He says his cooking reflects his Filipino heritage, which is a blend of many cultures.","vi":"SYDNEY (ngày 4 tháng 6)—Kitchen Swifts và Đầu bếp Darius Cordero đang hợp tác cùng nhau nhằm mang đến cho những người nấu ăn tại nhà một trải nghiệm ẩm thực mới mẻ. Vị đầu bếp từng đoạt giải thưởng này là chủ sở hữu của nhiều nhà hàng tại cả Philippines và Úc, trong đó có nhà hàng Enriqua's vừa khai trương gần đây. Ông cho biết phong cách nấu nướng của mình phản ánh di sản văn hóa Philippines — sự giao thoa của nhiều nền văn hóa.","units":[{"en":"SYDNEY (4 June)—Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience.","vi":"SYDNEY (ngày 4 tháng 6)—Kitchen Swifts và Đầu bếp Darius Cordero đang hợp tác cùng nhau nhằm mang đến cho những người nấu ăn tại nhà một trải nghiệm ẩm thực mới mẻ."},{"en":"The award-winning chef is the owner of restaurants in both the Philippines and Australia, including the recently opened Enriqua's.","vi":"Vị đầu bếp từng đoạt giải thưởng này là chủ sở hữu của nhiều nhà hàng tại cả Philippines và Úc, trong đó có nhà hàng Enriqua's vừa khai trương gần đây."},{"en":"He says his cooking reflects his Filipino heritage, which is a blend of many cultures.","vi":"Ông cho biết phong cách nấu nướng của mình phản ánh di sản văn hóa Philippines — sự giao thoa của nhiều nền văn hóa."}]},{"speaker":"Document 1 — Press Release","en":"\"I've designed these simplified recipes for Kitchen Swifts so that cooks at home can enjoy new and exciting flavours with ease,\" he said. \"While preparing and eating these meals, you can feel like you are travelling the world with me.\"","vi":"\"Tôi đã thiết kế những công thức đơn giản hóa này cho Kitchen Swifts để những người nấu ăn tại nhà có thể dễ dàng thưởng thức những hương vị mới lạ và hấp dẫn,\" ông chia sẻ. \"Khi chế biến và thưởng thức những bữa ăn này, bạn có thể cảm nhận như đang cùng tôi chu du khắp thế giới.\"","units":[{"en":"\"I've designed these simplified recipes for Kitchen Swifts so that cooks at home can enjoy new and exciting flavours with ease,\" he said.","vi":"\"Tôi đã thiết kế những công thức đơn giản hóa này cho Kitchen Swifts để những người nấu ăn tại nhà có thể dễ dàng thưởng thức những hương vị mới lạ và hấp dẫn,\" ông chia sẻ."},{"en":"\"While preparing and eating these meals, you can feel like you are travelling the world with me.\"","vi":"\"Khi chế biến và thưởng thức những bữa ăn này, bạn có thể cảm nhận như đang cùng tôi chu du khắp thế giới.\""}]},{"speaker":"Document 1 — Press Release","en":"Zahra Chambers, vice president of Kitchen Swifts, says she is pleased to work with Chef Cordero and to offer delicious new recipes to their customers. Kitchen Swifts supplies menus, recipes, and ingredients for two people, four people, or six people, including a range of vegetarian selections. Customers choose the most appropriate meal options, and then a box is delivered weekly. Current customers will see no price increase with the partnership. To find out more, visit the Kitchen Swifts Web site at www.kitchenswifts.com.au.","vi":"Bà Zahra Chambers, Phó Chủ tịch của Kitchen Swifts, cho biết bà rất vui mừng được hợp tác với Đầu bếp Cordero và mang đến những công thức mới thơm ngon cho khách hàng của mình. Kitchen Swifts cung cấp thực đơn, công thức nấu ăn và nguyên liệu dành cho hai người, bốn người hoặc sáu người, bao gồm nhiều lựa chọn món chay phong phú. Khách hàng lựa chọn các gói bữa ăn phù hợp nhất, sau đó một hộp nguyên liệu sẽ được giao tận nơi hằng tuần. Các khách hàng hiện tại sẽ không phải chịu bất kỳ mức tăng giá nào từ sự hợp tác này. Để tìm hiểu thêm thông tin, vui lòng truy cập trang web của Kitchen Swifts tại địa chỉ www.kitchenswifts.com.au.","units":[{"en":"Zahra Chambers, vice president of Kitchen Swifts, says she is pleased to work with Chef Cordero and to offer delicious new recipes to their customers.","vi":"Bà Zahra Chambers, Phó Chủ tịch của Kitchen Swifts, cho biết bà rất vui mừng được hợp tác với Đầu bếp Cordero và mang đến những công thức mới thơm ngon cho khách hàng của mình."},{"en":"Kitchen Swifts supplies menus, recipes, and ingredients for two people, four people, or six people, including a range of vegetarian selections.","vi":"Kitchen Swifts cung cấp thực đơn, công thức nấu ăn và nguyên liệu dành cho hai người, bốn người hoặc sáu người, bao gồm nhiều lựa chọn món chay phong phú."},{"en":"Customers choose the most appropriate meal options, and then a box is delivered weekly.","vi":"Khách hàng lựa chọn các gói bữa ăn phù hợp nhất, sau đó một hộp nguyên liệu sẽ được giao tận nơi hằng tuần."},{"en":"Current customers will see no price increase with the partnership.","vi":"Các khách hàng hiện tại sẽ không phải chịu bất kỳ mức tăng giá nào từ sự hợp tác này."},{"en":"To find out more, visit the Kitchen Swifts Web site at www.kitchenswifts.com.au.","vi":"Để tìm hiểu thêm thông tin, vui lòng truy cập trang web của Kitchen Swifts tại địa chỉ www.kitchenswifts.com.au."}]},{"speaker":"Document 2 — Review","en":"https://www.sydneyrestaurants.com.au","vi":"https://www.sydneyrestaurants.com.au","units":[{"en":"https://www.sydneyrestaurants.com.au","vi":"https://www.sydneyrestaurants.com.au"}]},{"speaker":"Document 2 — Review","en":"A colleague arranged for us to eat at Enriqua's while I was at a conference in Sydney. It is usually fully booked for dinner; you may need to call months in advance for a table. We had a wonderful lunch there instead. Everything was delicious, and the bread and desserts are baked on-site! It was a worthwhile treat before I flew back to Hong Kong.","vi":"Một đồng nghiệp đã thu xếp cho chúng tôi dùng bữa tại Enriqua's trong thời gian tôi tham dự một hội nghị ở Sydney. Nhà hàng thường kín chỗ vào bữa tối; bạn có thể cần phải gọi điện đặt bàn trước nhiều tháng. Thay vào đó, chúng tôi đã có một bữa trưa tuyệt vời tại đây. Món nào cũng rất ngon, hơn nữa bánh mì và các món tráng miệng đều được nướng ngay tại chỗ! Đó thực sự là một bữa ăn thật đáng giá trước khi tôi bay về Hong Kong.","units":[{"en":"A colleague arranged for us to eat at Enriqua's while I was at a conference in Sydney.","vi":"Một đồng nghiệp đã thu xếp cho chúng tôi dùng bữa tại Enriqua's trong thời gian tôi tham dự một hội nghị ở Sydney."},{"en":"It is usually fully booked for dinner; you may need to call months in advance for a table.","vi":"Nhà hàng thường kín chỗ vào bữa tối; bạn có thể cần phải gọi điện đặt bàn trước nhiều tháng."},{"en":"We had a wonderful lunch there instead.","vi":"Thay vào đó, chúng tôi đã có một bữa trưa tuyệt vời tại đây."},{"en":"Everything was delicious, and the bread and desserts are baked on-site!","vi":"Món nào cũng rất ngon, hơn nữa bánh mì và các món tráng miệng đều được nướng ngay tại chỗ!"},{"en":"It was a worthwhile treat before I flew back to Hong Kong.","vi":"Đó thực sự là một bữa ăn thật đáng giá trước khi tôi bay về Hong Kong."}]},{"speaker":"Document 2 — Review","en":"—Meili Guan","vi":"—Meili Guan","units":[{"en":"—Meili Guan","vi":"—Meili Guan"}]}],"vocab":[{"word":"ingredient","pos":"n","ipa":"/ɪnˈɡriːdiənt/","meaning":"nguyên liệu, thành phần món ăn"},{"word":"selection","pos":"n","ipa":"/sɪˈlekʃən/","meaning":"sự lựa chọn, danh mục món"},{"word":"appropriate","pos":"adj","ipa":"/əˈproʊpriət/","meaning":"phù hợp, thích hợp"},{"word":"vegetarian","pos":"adj","ipa":"/ˌvedʒəˈteriən/","meaning":"chay, dành cho người ăn chay"}],"isScanBacked":false,"docTypeLabel":"press release and review","context":"Press release and review — Kitchen Swifts & Chef Darius Cordero / Enriqua's","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 (Chi tiết văn bản — Quét từ khóa & Paraphrase): Quét đoạn 3 Document 1 quanh từ khóa 'Kitchen Swifts supplies', nối 'for two, four, or six people / vegetarian selections / meal options' -> 'offers several meal options' (C).","optionAnalysis":{"A":"Trái ngược văn bản: Đoạn 3 Document 1 khẳng định rõ 'Current customers will see no price increase with the partnership', tức là không hề tăng giá.","B":"Bẫy từ khóa 'delivered': Văn bản chỉ nêu hộp nguyên liệu được giao hằng tuần ('delivered weekly'), không hề nhắc đến việc sửa đổi lịch giao hàng ('revised').","C":"Chính xác: Document 1 ghi Kitchen Swifts cung cấp thực đơn cho 2, 4 hoặc 6 người kèm nhiều món chay ('a range of vegetarian selections') và cho khách chọn 'meal options'.","D":"Suy diễn không căn cứ: Bà Zahra Chambers được nêu là 'vice president', nhưng bài không có chi tiết nào cho thấy bà là phó chủ tịch mới nhậm chức."},"evDocIdx":0,"evTargets":[{"badge":"Câu 178 · Đáp án C","opt":"C","isCorrect":true,"quote":"Kitchen Swifts supplies menus, recipes, and ingredients for two people, four people, or six people, including a range of vegetarian selections.","viQuote":"Kitchen Swifts cung cấp thực đơn, công thức nấu ăn và nguyên liệu dành cho hai người, bốn người hoặc sáu người, bao gồm nhiều lựa chọn món chay phong phú."},{"badge":"Câu 178 · Đáp án C","opt":"C","isCorrect":true,"quote":"Customers choose the most appropriate meal options, and then a box is delivered weekly.","viQuote":"Khách hàng lựa chọn các gói bữa ăn phù hợp nhất, sau đó một hộp nguyên liệu sẽ được giao tận nơi hằng tuần."}],"evQuotes":["Kitchen Swifts supplies menus, recipes, and ingredients for two people, four people, or six people, including a range of vegetarian selections.","Customers choose the most appropriate meal options, and then a box is delivered weekly."]},{"q":179,"part":7,"group_id":"E25_T01_G176_180","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc19.webp","web_assets/ets2025/p67/E25_T01_rc20.webp"],"stem_en":"What is most likely true about Ms. Guan?","stem_vi":"Điều nào sau đây có khả năng đúng nhất về bà Guan?","options":{"A":{"en":"She went to Mr. Cordero's restaurant.","vi":"Bà ấy đã đến ăn tại nhà hàng của ông Cordero."},"B":{"en":"She recently went to Sydney for a vacation.","vi":"Gần đây bà ấy đã đến Sydney để đi nghỉ mát."},"C":{"en":"She is a colleague of Ms. Chambers.","vi":"Bà ấy là đồng nghiệp của bà Chambers."},"D":{"en":"She regularly orders from Kitchen Swifts.","vi":"Bà ấy thường xuyên đặt hàng từ Kitchen Swifts."}},"ans":"A","evidence_quote":"- In the review: A colleague arranged for us to eat at Enriqua's while I was at a conference in Sydney. - In the press release: Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience. The award-winning chef is the owner of restaurants in both the Philippines and Australia, including the recently opened Enriqua's.","explanation":"Đáp án đúng: (A) Bà ấy đã đến ăn tại nhà hàng của ông Cordero — câu hỏi liên kết chéo hai văn bản: Document 2 cho biết Meili Guan đã dùng bữa trưa tại Enriqua's, còn Document 1 xác nhận Enriqua's là nhà hàng thuộc sở hữu của Đầu bếp Darius Cordero.\nDẫn chứng: Document 2 — Review: \"A colleague arranged for us to eat at Enriqua's while I was at a conference in Sydney.\" kết hợp Document 1 — Press Release: \"The award-winning chef is the owner of restaurants in both the Philippines and Australia, including the recently opened Enriqua's.\" (Bà Guan đã ăn tại Enriqua's — nhà hàng do Đầu bếp Darius Cordero làm chủ).\nPhân tích bẫy:\n- (B) Sai mục đích chuyến đi: Bà Guan đến Sydney để tham dự một hội nghị (\"while I was at a conference in Sydney\"), không phải đi nghỉ mát (\"for a vacation\").\n- (C) Ghép nhầm nhân vật giữa 2 văn bản: Bà Guan chỉ nhắc \"A colleague\" thu xếp bữa ăn, không có cơ sở nào cho thấy đồng nghiệp đó là bà Zahra Chambers (Phó Chủ tịch Kitchen Swifts ở Document 1).\n- (D) Suy diễn sai đối tượng dịch vụ: Bài đánh giá của bà Guan chỉ viết về bữa ăn tại nhà hàng Enriqua's, hoàn toàn không nhắc đến việc bà đặt hộp nguyên liệu từ Kitchen Swifts.","lines":[{"speaker":"Document 1 — Press Release","en":"Aparna Kothari, Media Contact","vi":"Aparna Kothari, Đầu mối liên hệ truyền thông","units":[{"en":"Aparna Kothari, Media Contact","vi":"Aparna Kothari, Đầu mối liên hệ truyền thông"}]},{"speaker":"Document 1 — Press Release","en":"Kitchen Swifts","vi":"Kitchen Swifts","units":[{"en":"Kitchen Swifts","vi":"Kitchen Swifts"}]},{"speaker":"Document 1 — Press Release","en":"akothari@kitchenswifts.com.au","vi":"akothari@kitchenswifts.com.au","units":[{"en":"akothari@kitchenswifts.com.au","vi":"akothari@kitchenswifts.com.au"}]},{"speaker":"Document 1 — Press Release","en":"FOR IMMEDIATE RELEASE","vi":"THÔNG CÁO PHÁT HÀNH NGAY","units":[{"en":"FOR IMMEDIATE RELEASE","vi":"THÔNG CÁO PHÁT HÀNH NGAY"}]},{"speaker":"Document 1 — Press Release","en":"SYDNEY (4 June)—Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience. The award-winning chef is the owner of restaurants in both the Philippines and Australia, including the recently opened Enriqua's. He says his cooking reflects his Filipino heritage, which is a blend of many cultures.","vi":"SYDNEY (ngày 4 tháng 6)—Kitchen Swifts và Đầu bếp Darius Cordero đang hợp tác cùng nhau nhằm mang đến cho những người nấu ăn tại nhà một trải nghiệm ẩm thực mới mẻ. Vị đầu bếp từng đoạt giải thưởng này là chủ sở hữu của nhiều nhà hàng tại cả Philippines và Úc, trong đó có nhà hàng Enriqua's vừa khai trương gần đây. Ông cho biết phong cách nấu nướng của mình phản ánh di sản văn hóa Philippines — sự giao thoa của nhiều nền văn hóa.","units":[{"en":"SYDNEY (4 June)—Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience.","vi":"SYDNEY (ngày 4 tháng 6)—Kitchen Swifts và Đầu bếp Darius Cordero đang hợp tác cùng nhau nhằm mang đến cho những người nấu ăn tại nhà một trải nghiệm ẩm thực mới mẻ."},{"en":"The award-winning chef is the owner of restaurants in both the Philippines and Australia, including the recently opened Enriqua's.","vi":"Vị đầu bếp từng đoạt giải thưởng này là chủ sở hữu của nhiều nhà hàng tại cả Philippines và Úc, trong đó có nhà hàng Enriqua's vừa khai trương gần đây."},{"en":"He says his cooking reflects his Filipino heritage, which is a blend of many cultures.","vi":"Ông cho biết phong cách nấu nướng của mình phản ánh di sản văn hóa Philippines — sự giao thoa của nhiều nền văn hóa."}]},{"speaker":"Document 1 — Press Release","en":"\"I've designed these simplified recipes for Kitchen Swifts so that cooks at home can enjoy new and exciting flavours with ease,\" he said. \"While preparing and eating these meals, you can feel like you are travelling the world with me.\"","vi":"\"Tôi đã thiết kế những công thức đơn giản hóa này cho Kitchen Swifts để những người nấu ăn tại nhà có thể dễ dàng thưởng thức những hương vị mới lạ và hấp dẫn,\" ông chia sẻ. \"Khi chế biến và thưởng thức những bữa ăn này, bạn có thể cảm nhận như đang cùng tôi chu du khắp thế giới.\"","units":[{"en":"\"I've designed these simplified recipes for Kitchen Swifts so that cooks at home can enjoy new and exciting flavours with ease,\" he said.","vi":"\"Tôi đã thiết kế những công thức đơn giản hóa này cho Kitchen Swifts để những người nấu ăn tại nhà có thể dễ dàng thưởng thức những hương vị mới lạ và hấp dẫn,\" ông chia sẻ."},{"en":"\"While preparing and eating these meals, you can feel like you are travelling the world with me.\"","vi":"\"Khi chế biến và thưởng thức những bữa ăn này, bạn có thể cảm nhận như đang cùng tôi chu du khắp thế giới.\""}]},{"speaker":"Document 1 — Press Release","en":"Zahra Chambers, vice president of Kitchen Swifts, says she is pleased to work with Chef Cordero and to offer delicious new recipes to their customers. Kitchen Swifts supplies menus, recipes, and ingredients for two people, four people, or six people, including a range of vegetarian selections. Customers choose the most appropriate meal options, and then a box is delivered weekly. Current customers will see no price increase with the partnership. To find out more, visit the Kitchen Swifts Web site at www.kitchenswifts.com.au.","vi":"Bà Zahra Chambers, Phó Chủ tịch của Kitchen Swifts, cho biết bà rất vui mừng được hợp tác với Đầu bếp Cordero và mang đến những công thức mới thơm ngon cho khách hàng của mình. Kitchen Swifts cung cấp thực đơn, công thức nấu ăn và nguyên liệu dành cho hai người, bốn người hoặc sáu người, bao gồm nhiều lựa chọn món chay phong phú. Khách hàng lựa chọn các gói bữa ăn phù hợp nhất, sau đó một hộp nguyên liệu sẽ được giao tận nơi hằng tuần. Các khách hàng hiện tại sẽ không phải chịu bất kỳ mức tăng giá nào từ sự hợp tác này. Để tìm hiểu thêm thông tin, vui lòng truy cập trang web của Kitchen Swifts tại địa chỉ www.kitchenswifts.com.au.","units":[{"en":"Zahra Chambers, vice president of Kitchen Swifts, says she is pleased to work with Chef Cordero and to offer delicious new recipes to their customers.","vi":"Bà Zahra Chambers, Phó Chủ tịch của Kitchen Swifts, cho biết bà rất vui mừng được hợp tác với Đầu bếp Cordero và mang đến những công thức mới thơm ngon cho khách hàng của mình."},{"en":"Kitchen Swifts supplies menus, recipes, and ingredients for two people, four people, or six people, including a range of vegetarian selections.","vi":"Kitchen Swifts cung cấp thực đơn, công thức nấu ăn và nguyên liệu dành cho hai người, bốn người hoặc sáu người, bao gồm nhiều lựa chọn món chay phong phú."},{"en":"Customers choose the most appropriate meal options, and then a box is delivered weekly.","vi":"Khách hàng lựa chọn các gói bữa ăn phù hợp nhất, sau đó một hộp nguyên liệu sẽ được giao tận nơi hằng tuần."},{"en":"Current customers will see no price increase with the partnership.","vi":"Các khách hàng hiện tại sẽ không phải chịu bất kỳ mức tăng giá nào từ sự hợp tác này."},{"en":"To find out more, visit the Kitchen Swifts Web site at www.kitchenswifts.com.au.","vi":"Để tìm hiểu thêm thông tin, vui lòng truy cập trang web của Kitchen Swifts tại địa chỉ www.kitchenswifts.com.au."}]},{"speaker":"Document 2 — Review","en":"https://www.sydneyrestaurants.com.au","vi":"https://www.sydneyrestaurants.com.au","units":[{"en":"https://www.sydneyrestaurants.com.au","vi":"https://www.sydneyrestaurants.com.au"}]},{"speaker":"Document 2 — Review","en":"A colleague arranged for us to eat at Enriqua's while I was at a conference in Sydney. It is usually fully booked for dinner; you may need to call months in advance for a table. We had a wonderful lunch there instead. Everything was delicious, and the bread and desserts are baked on-site! It was a worthwhile treat before I flew back to Hong Kong.","vi":"Một đồng nghiệp đã thu xếp cho chúng tôi dùng bữa tại Enriqua's trong thời gian tôi tham dự một hội nghị ở Sydney. Nhà hàng thường kín chỗ vào bữa tối; bạn có thể cần phải gọi điện đặt bàn trước nhiều tháng. Thay vào đó, chúng tôi đã có một bữa trưa tuyệt vời tại đây. Món nào cũng rất ngon, hơn nữa bánh mì và các món tráng miệng đều được nướng ngay tại chỗ! Đó thực sự là một bữa ăn thật đáng giá trước khi tôi bay về Hong Kong.","units":[{"en":"A colleague arranged for us to eat at Enriqua's while I was at a conference in Sydney.","vi":"Một đồng nghiệp đã thu xếp cho chúng tôi dùng bữa tại Enriqua's trong thời gian tôi tham dự một hội nghị ở Sydney."},{"en":"It is usually fully booked for dinner; you may need to call months in advance for a table.","vi":"Nhà hàng thường kín chỗ vào bữa tối; bạn có thể cần phải gọi điện đặt bàn trước nhiều tháng."},{"en":"We had a wonderful lunch there instead.","vi":"Thay vào đó, chúng tôi đã có một bữa trưa tuyệt vời tại đây."},{"en":"Everything was delicious, and the bread and desserts are baked on-site!","vi":"Món nào cũng rất ngon, hơn nữa bánh mì và các món tráng miệng đều được nướng ngay tại chỗ!"},{"en":"It was a worthwhile treat before I flew back to Hong Kong.","vi":"Đó thực sự là một bữa ăn thật đáng giá trước khi tôi bay về Hong Kong."}]},{"speaker":"Document 2 — Review","en":"—Meili Guan","vi":"—Meili Guan","units":[{"en":"—Meili Guan","vi":"—Meili Guan"}]}],"vocab":[{"word":"colleague","pos":"n","ipa":"/ˈkɑːliːɡ/","meaning":"đồng nghiệp"},{"word":"arrange","pos":"v","ipa":"/əˈreɪndʒ/","meaning":"thu xếp, sắp đặt"},{"word":"conference","pos":"n","ipa":"/ˈkɑːnfərəns/","meaning":"hội nghị, hội thảo"},{"word":"owner","pos":"n","ipa":"/ˈoʊnər/","meaning":"chủ sở hữu"}],"isScanBacked":false,"docTypeLabel":"press release and review","context":"Press release and review — Kitchen Swifts & Chef Darius Cordero / Enriqua's","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 LIÊN KẾT ĐA VĂN BẢN (TEXT 1 + TEXT 2): Nối thông tin sở hữu ở Document 1 ('owner of restaurantsin Australia, including Enriqua's') với trải nghiệm của Ms. Guan ở Document 2 ('eat at Enriqua's') -> Chốt (A).","optionAnalysis":{"A":"Chính xác (liên kết 2 văn bản): Document 2 cho biết bà Guan đã ăn tại Enriqua's, kết hợp Document 1 xác nhận Đầu bếp Cordero là chủ sở hữu nhà hàng Enriqua's.","B":"Sai mục đích chuyến đi: Document 2 nêu rõ bà Guan đến Sydney để dự hội nghị ('while I was at a conference in Sydney'), không phải đi nghỉ mát ('vacation').","C":"Bẫy ghép tên nhân vật: Bà Guan chỉ nói đi ăn cùng 'A colleague', hoàn toàn không có liên hệ nào với bà Zahra Chambers của Kitchen Swifts ở Document 1.","D":"Nhầm đối tượng giữa 2 văn bản: Bà Guan đánh giá trải nghiệm ăn trưa tại nhà hàng Enriqua's chứ không hề nhắc đến việc đặt hàng từ Kitchen Swifts."},"evDocIdx":1,"evTargets":[{"badge":"Câu 179 · Đáp án A","opt":"A","isCorrect":true,"quote":"A colleague arranged for us to eat at Enriqua's while I was at a conference in Sydney.","viQuote":"Một đồng nghiệp đã thu xếp cho chúng tôi dùng bữa tại Enriqua's trong thời gian tôi tham dự một hội nghị ở Sydney."},{"badge":"Câu 179 · Đáp án A","opt":"A","isCorrect":true,"quote":"The award-winning chef is the owner of restaurants in both the Philippines and Australia, including the recently opened Enriqua's.","viQuote":"Vị đầu bếp từng đoạt giải thưởng này là chủ sở hữu của nhiều nhà hàng tại cả Philippines và Úc, trong đó có nhà hàng Enriqua's vừa khai trương gần đây."}],"evQuotes":["A colleague arranged for us to eat at Enriqua's while I was at a conference in Sydney.","The award-winning chef is the owner of restaurants in both the Philippines and Australia, including the recently opened Enriqua's."]},{"q":180,"part":7,"group_id":"E25_T01_G176_180","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc19.webp","web_assets/ets2025/p67/E25_T01_rc20.webp"],"stem_en":"What did Ms. Guan suggest about Enriqua's in the review?","stem_vi":"Bà Guan đã ngụ ý điều gì về nhà hàng Enriqua's trong bài đánh giá?","options":{"A":{"en":"It has a limited lunch menu.","vi":"Nhà hàng có thực đơn bữa trưa hạn chế."},"B":{"en":"It takes dinner reservations.","vi":"Nhà hàng có nhận đặt bàn cho bữa tối."},"C":{"en":"It serves bread from a local bakery.","vi":"Nhà hàng phục vụ bánh mì mua từ một tiệm bánh địa phương."},"D":{"en":"It has a location in Hong Kong.","vi":"Nhà hàng có một chi nhánh tại Hong Kong."}},"ans":"B","evidence_quote":"It is usually fully booked for dinner; you may need to call months in advance for a table.","explanation":"Đáp án đúng: (B) Nhà hàng có nhận đặt bàn cho bữa tối — trong bài đánh giá (Document 2), bà Guan viết nhà hàng thường kín chỗ vào bữa tối và khuyên thực khách gọi điện trước nhiều tháng để có bàn (\"call months in advance for a table\"), ngụ ý rõ ràng rằng Enriqua's nhận đặt chỗ trước cho bữa tối.\nDẫn chứng: \"It is usually fully booked for dinner; you may need to call months in advance for a table.\" (Document 2 — Review: Bữa tối thường kín chỗ; bạn có thể cần gọi điện đặt bàn trước nhiều tháng).\nPhân tích bẫy:\n- (A) Sai thông tin về bữa trưa: Bà Guan chỉ khen \"We had a wonderful lunch there instead\" và \"Everything was delicious\", không hề chê thực đơn bữa trưa hạn chế.\n- (C) Trái ngược chi tiết bánh mì: Bài đánh giá khẳng định \"the bread and desserts are baked on-site!\" (bánh mì và tráng miệng được nướng ngay tại chỗ), không phải mua từ tiệm bánh địa phương.\n- (D) Bẫy đánh tráo địa danh: Hong Kong là nơi bà Guan bay trở về sau chuyến công tác (\"before I flew back to Hong Kong\"), còn nhà hàng của ông Cordero chỉ có ở Philippines và Úc.","lines":[{"speaker":"Document 1 — Press Release","en":"Aparna Kothari, Media Contact","vi":"Aparna Kothari, Đầu mối liên hệ truyền thông","units":[{"en":"Aparna Kothari, Media Contact","vi":"Aparna Kothari, Đầu mối liên hệ truyền thông"}]},{"speaker":"Document 1 — Press Release","en":"Kitchen Swifts","vi":"Kitchen Swifts","units":[{"en":"Kitchen Swifts","vi":"Kitchen Swifts"}]},{"speaker":"Document 1 — Press Release","en":"akothari@kitchenswifts.com.au","vi":"akothari@kitchenswifts.com.au","units":[{"en":"akothari@kitchenswifts.com.au","vi":"akothari@kitchenswifts.com.au"}]},{"speaker":"Document 1 — Press Release","en":"FOR IMMEDIATE RELEASE","vi":"THÔNG CÁO PHÁT HÀNH NGAY","units":[{"en":"FOR IMMEDIATE RELEASE","vi":"THÔNG CÁO PHÁT HÀNH NGAY"}]},{"speaker":"Document 1 — Press Release","en":"SYDNEY (4 June)—Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience. The award-winning chef is the owner of restaurants in both the Philippines and Australia, including the recently opened Enriqua's. He says his cooking reflects his Filipino heritage, which is a blend of many cultures.","vi":"SYDNEY (ngày 4 tháng 6)—Kitchen Swifts và Đầu bếp Darius Cordero đang hợp tác cùng nhau nhằm mang đến cho những người nấu ăn tại nhà một trải nghiệm ẩm thực mới mẻ. Vị đầu bếp từng đoạt giải thưởng này là chủ sở hữu của nhiều nhà hàng tại cả Philippines và Úc, trong đó có nhà hàng Enriqua's vừa khai trương gần đây. Ông cho biết phong cách nấu nướng của mình phản ánh di sản văn hóa Philippines — sự giao thoa của nhiều nền văn hóa.","units":[{"en":"SYDNEY (4 June)—Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience.","vi":"SYDNEY (ngày 4 tháng 6)—Kitchen Swifts và Đầu bếp Darius Cordero đang hợp tác cùng nhau nhằm mang đến cho những người nấu ăn tại nhà một trải nghiệm ẩm thực mới mẻ."},{"en":"The award-winning chef is the owner of restaurants in both the Philippines and Australia, including the recently opened Enriqua's.","vi":"Vị đầu bếp từng đoạt giải thưởng này là chủ sở hữu của nhiều nhà hàng tại cả Philippines và Úc, trong đó có nhà hàng Enriqua's vừa khai trương gần đây."},{"en":"He says his cooking reflects his Filipino heritage, which is a blend of many cultures.","vi":"Ông cho biết phong cách nấu nướng của mình phản ánh di sản văn hóa Philippines — sự giao thoa của nhiều nền văn hóa."}]},{"speaker":"Document 1 — Press Release","en":"\"I've designed these simplified recipes for Kitchen Swifts so that cooks at home can enjoy new and exciting flavours with ease,\" he said. \"While preparing and eating these meals, you can feel like you are travelling the world with me.\"","vi":"\"Tôi đã thiết kế những công thức đơn giản hóa này cho Kitchen Swifts để những người nấu ăn tại nhà có thể dễ dàng thưởng thức những hương vị mới lạ và hấp dẫn,\" ông chia sẻ. \"Khi chế biến và thưởng thức những bữa ăn này, bạn có thể cảm nhận như đang cùng tôi chu du khắp thế giới.\"","units":[{"en":"\"I've designed these simplified recipes for Kitchen Swifts so that cooks at home can enjoy new and exciting flavours with ease,\" he said.","vi":"\"Tôi đã thiết kế những công thức đơn giản hóa này cho Kitchen Swifts để những người nấu ăn tại nhà có thể dễ dàng thưởng thức những hương vị mới lạ và hấp dẫn,\" ông chia sẻ."},{"en":"\"While preparing and eating these meals, you can feel like you are travelling the world with me.\"","vi":"\"Khi chế biến và thưởng thức những bữa ăn này, bạn có thể cảm nhận như đang cùng tôi chu du khắp thế giới.\""}]},{"speaker":"Document 1 — Press Release","en":"Zahra Chambers, vice president of Kitchen Swifts, says she is pleased to work with Chef Cordero and to offer delicious new recipes to their customers. Kitchen Swifts supplies menus, recipes, and ingredients for two people, four people, or six people, including a range of vegetarian selections. Customers choose the most appropriate meal options, and then a box is delivered weekly. Current customers will see no price increase with the partnership. To find out more, visit the Kitchen Swifts Web site at www.kitchenswifts.com.au.","vi":"Bà Zahra Chambers, Phó Chủ tịch của Kitchen Swifts, cho biết bà rất vui mừng được hợp tác với Đầu bếp Cordero và mang đến những công thức mới thơm ngon cho khách hàng của mình. Kitchen Swifts cung cấp thực đơn, công thức nấu ăn và nguyên liệu dành cho hai người, bốn người hoặc sáu người, bao gồm nhiều lựa chọn món chay phong phú. Khách hàng lựa chọn các gói bữa ăn phù hợp nhất, sau đó một hộp nguyên liệu sẽ được giao tận nơi hằng tuần. Các khách hàng hiện tại sẽ không phải chịu bất kỳ mức tăng giá nào từ sự hợp tác này. Để tìm hiểu thêm thông tin, vui lòng truy cập trang web của Kitchen Swifts tại địa chỉ www.kitchenswifts.com.au.","units":[{"en":"Zahra Chambers, vice president of Kitchen Swifts, says she is pleased to work with Chef Cordero and to offer delicious new recipes to their customers.","vi":"Bà Zahra Chambers, Phó Chủ tịch của Kitchen Swifts, cho biết bà rất vui mừng được hợp tác với Đầu bếp Cordero và mang đến những công thức mới thơm ngon cho khách hàng của mình."},{"en":"Kitchen Swifts supplies menus, recipes, and ingredients for two people, four people, or six people, including a range of vegetarian selections.","vi":"Kitchen Swifts cung cấp thực đơn, công thức nấu ăn và nguyên liệu dành cho hai người, bốn người hoặc sáu người, bao gồm nhiều lựa chọn món chay phong phú."},{"en":"Customers choose the most appropriate meal options, and then a box is delivered weekly.","vi":"Khách hàng lựa chọn các gói bữa ăn phù hợp nhất, sau đó một hộp nguyên liệu sẽ được giao tận nơi hằng tuần."},{"en":"Current customers will see no price increase with the partnership.","vi":"Các khách hàng hiện tại sẽ không phải chịu bất kỳ mức tăng giá nào từ sự hợp tác này."},{"en":"To find out more, visit the Kitchen Swifts Web site at www.kitchenswifts.com.au.","vi":"Để tìm hiểu thêm thông tin, vui lòng truy cập trang web của Kitchen Swifts tại địa chỉ www.kitchenswifts.com.au."}]},{"speaker":"Document 2 — Review","en":"https://www.sydneyrestaurants.com.au","vi":"https://www.sydneyrestaurants.com.au","units":[{"en":"https://www.sydneyrestaurants.com.au","vi":"https://www.sydneyrestaurants.com.au"}]},{"speaker":"Document 2 — Review","en":"A colleague arranged for us to eat at Enriqua's while I was at a conference in Sydney. It is usually fully booked for dinner; you may need to call months in advance for a table. We had a wonderful lunch there instead. Everything was delicious, and the bread and desserts are baked on-site! It was a worthwhile treat before I flew back to Hong Kong.","vi":"Một đồng nghiệp đã thu xếp cho chúng tôi dùng bữa tại Enriqua's trong thời gian tôi tham dự một hội nghị ở Sydney. Nhà hàng thường kín chỗ vào bữa tối; bạn có thể cần phải gọi điện đặt bàn trước nhiều tháng. Thay vào đó, chúng tôi đã có một bữa trưa tuyệt vời tại đây. Món nào cũng rất ngon, hơn nữa bánh mì và các món tráng miệng đều được nướng ngay tại chỗ! Đó thực sự là một bữa ăn thật đáng giá trước khi tôi bay về Hong Kong.","units":[{"en":"A colleague arranged for us to eat at Enriqua's while I was at a conference in Sydney.","vi":"Một đồng nghiệp đã thu xếp cho chúng tôi dùng bữa tại Enriqua's trong thời gian tôi tham dự một hội nghị ở Sydney."},{"en":"It is usually fully booked for dinner; you may need to call months in advance for a table.","vi":"Nhà hàng thường kín chỗ vào bữa tối; bạn có thể cần phải gọi điện đặt bàn trước nhiều tháng."},{"en":"We had a wonderful lunch there instead.","vi":"Thay vào đó, chúng tôi đã có một bữa trưa tuyệt vời tại đây."},{"en":"Everything was delicious, and the bread and desserts are baked on-site!","vi":"Món nào cũng rất ngon, hơn nữa bánh mì và các món tráng miệng đều được nướng ngay tại chỗ!"},{"en":"It was a worthwhile treat before I flew back to Hong Kong.","vi":"Đó thực sự là một bữa ăn thật đáng giá trước khi tôi bay về Hong Kong."}]},{"speaker":"Document 2 — Review","en":"—Meili Guan","vi":"—Meili Guan","units":[{"en":"—Meili Guan","vi":"—Meili Guan"}]}],"vocab":[{"word":"fully booked","pos":"adj","ipa":"/ˈfʊli bʊkt/","meaning":"đã kín chỗ, hết bàn"},{"word":"in advance","pos":"phr","ipa":"/ɪn ədˈvæns/","meaning":"trước (về thời gian)"},{"word":"on-site","pos":"adv","ipa":"/ˌɑːn ˈsaɪt/","meaning":"ngay tại chỗ, tại địa điểm"},{"word":"worthwhile","pos":"adj","ipa":"/ˌwɜːrθˈwaɪl/","meaning":"đáng giá, bỏ công"}],"isScanBacked":false,"docTypeLabel":"press release and review","context":"Press release and review — Kitchen Swifts & Chef Darius Cordero / Enriqua's","grammarType":"Part 7 — Suy luận & Hàm ý văn bản (Inference & Implied Meaning)","formula":"CÔNG THỨC PART 7 (Suy luận từ hàm ý — Paraphrase ngữ cảnh): Từ chi tiết 'fully booked for dinner; call months in advance for a table' suy ra nhà hàng nhận đặt bàn bữa tối -> 'takes dinner reservations' (B).","optionAnalysis":{"A":"Bẫy suy diễn ngược: Bà Guan khen bữa trưa tuyệt vời ('wonderful lunch') và món nào cũng ngon, không hề đề cập thực đơn bữa trưa bị hạn chế.","B":"Chính xác: Câu 'fully booked for dinner; you may need to call months in advance for a table' ở Document 2 đồng nghĩa trực tiếp với việc nhận đặt bàn bữa tối.","C":"Trái ngược bài đọc: Document 2 ghi rõ 'the bread and desserts are baked on-site!' (tự nướng tại nhà hàng), không phải nhập từ tiệm bánh bên ngoài.","D":"Bẫy đánh tráo địa điểm: Hong Kong là nơi bà Guan bay về sau hội nghị, còn Document 1 nêu ông Cordero chỉ có nhà hàng ở Philippines và Úc."},"evDocIdx":1,"evTargets":[{"badge":"Câu 180 · Đáp án B","opt":"B","isCorrect":true,"quote":"It is usually fully booked for dinner; you may need to call months in advance for a table.","viQuote":"Nhà hàng thường kín chỗ vào bữa tối; bạn có thể cần phải gọi điện đặt bàn trước nhiều tháng."}],"evQuotes":["It is usually fully booked for dinner; you may need to call months in advance for a table."]},{"q":181,"part":7,"group_id":"E25_T01_G181_185","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc21.webp","web_assets/ets2025/p67/E25_T01_rc22.webp"],"stem_en":"What is the purpose of the e-mail?","stem_vi":"Mục đích của email này là gì?","options":{"A":{"en":"To finalize a plan","vi":"Hoàn tất một kế hoạch"},"B":{"en":"To accept an invitation","vi":"Chấp nhận một lời mời"},"C":{"en":"To promote a new service","vi":"Quảng bá một dịch vụ mới"},"D":{"en":"To request feedback on a policy","vi":"Yêu cầu phản hồi về một chính sách"}},"ans":"A","evidence_quote":"Thank you for your kind offer to either pick up your online order from my shop or to pay extra for air or train transport. Neither arrangement is necessary, as I am happy to deliver your items to you in Stranraer myself.","explanation":"Đáp án đúng: (A) Hoàn tất một kế hoạch — tiêu đề \"RE: Some suggestions\" cho thấy ông Boyle trả lời các gợi ý giao nhận của bà Savard, nêu rõ cả hai phương án cũ đều không cần thiết và chốt kế hoạch tự lái xe thuê đến giao tận tay tại Stranraer vào ngày 5 tháng 6, chậm nhất 5 giờ chiều.\nDẫn chứng: \"Neither arrangement is necessary, as I am happy to deliver your items to you in Stranraer myself.\" và \"Before seeing them, I will drive my rental car to your house and hand deliver the items to you.\" cùng \"I look forward to meeting you on 5 June. I expect to arrive at your house no later than 5 p.m.\" (Document 1 — E-mail: Tự giao tận tay bằng xe thuê vào 5/6 trước 5 giờ chiều).\nPhân tích bẫy:\n- (B) Bẫy hiểu nhầm từ \"kind offer\": Bà Savard đề nghị (\"offer\") tự đến cửa hàng lấy hoặc trả thêm phí vận chuyển, chứ không gửi lời mời (\"invitation\"), và ông Boyle cũng không chọn đề xuất đó.\n- (C) Sai bản chất thông điệp: Việc tự giao hàng hoặc thuê đơn vị chuyển phát đường bộ/biển tin cậy là chính sách sẵn có của ông (\"My policy\"), không phải quảng bá dịch vụ mới.\n- (D) Bẫy từ khóa \"policy\": Đoạn 2 chỉ giải thích nguyên tắc vận chuyển của Ceoleire Classics để tránh hư hỏng hàng thủ công, hoàn toàn không hỏi ý kiến phản hồi của bà Savard về chính sách này.","lines":[{"speaker":"Document 1 — E-mail","en":"To: laura.savard@orbitmail.scot","vi":"Đến: laura.savard@orbitmail.scot","units":[{"en":"To: laura.savard@orbitmail.scot","vi":"Đến: laura.savard@orbitmail.scot"}]},{"speaker":"Document 1 — E-mail","en":"From: cboyle@ceoleire.co.uk","vi":"Từ: cboyle@ceoleire.co.uk","units":[{"en":"From: cboyle@ceoleire.co.uk","vi":"Từ: cboyle@ceoleire.co.uk"}]},{"speaker":"Document 1 — E-mail","en":"Date: 25 May","vi":"Ngày: 25 tháng 5","units":[{"en":"Date: 25 May","vi":"Ngày: 25 tháng 5"}]},{"speaker":"Document 1 — E-mail","en":"Subject: RE: Some suggestions","vi":"Chủ đề: RE: Một số đề xuất","units":[{"en":"Subject: RE: Some suggestions","vi":"Chủ đề: RE: Một số đề xuất"}]},{"speaker":"Document 1 — E-mail","en":"Dear Ms. Savard,","vi":"Kính gửi bà Savard,","units":[{"en":"Dear Ms. Savard,","vi":"Kính gửi bà Savard,"}]},{"speaker":"Document 1 — E-mail","en":"Thank you for your kind offer to either pick up your online order from my shop or to pay extra for air or train transport. Neither arrangement is necessary, as I am happy to deliver your items to you in Stranraer myself. It so happens that my sister and her children live nearby in Kirkcolm. Before seeing them, I will drive my rental car to your house and hand deliver the items to you.","vi":"Cảm ơn bà đã nhã ý đề nghị tự đến cửa hàng của tôi nhận đơn đặt hàng trực tuyến hoặc trả thêm phí vận chuyển bằng đường hàng không hay tàu hỏa. Cả hai phương án đó đều không cần thiết, vì tôi rất sẵn lòng tự mình giao hàng đến tận nơi cho bà tại Stranraer. Thật tình cờ là chị gái tôi và các con của chị ấy cũng sống ngay gần đó ở Kirkcolm. Trước khi đến thăm họ, tôi sẽ lái xe thuê ghé qua nhà bà và giao tận tay các món hàng.","units":[{"en":"Thank you for your kind offer to either pick up your online order from my shop or to pay extra for air or train transport.","vi":"Cảm ơn bà đã nhã ý đề nghị tự đến cửa hàng của tôi nhận đơn đặt hàng trực tuyến hoặc trả thêm phí vận chuyển bằng đường hàng không hay tàu hỏa."},{"en":"Neither arrangement is necessary, as I am happy to deliver your items to you in Stranraer myself.","vi":"Cả hai phương án đó đều không cần thiết, vì tôi rất sẵn lòng tự mình giao hàng đến tận nơi cho bà tại Stranraer."},{"en":"It so happens that my sister and her children live nearby in Kirkcolm.","vi":"Thật tình cờ là chị gái tôi và các con của chị ấy cũng sống ngay gần đó ở Kirkcolm."},{"en":"Before seeing them, I will drive my rental car to your house and hand deliver the items to you.","vi":"Trước khi đến thăm họ, tôi sẽ lái xe thuê ghé qua nhà bà và giao tận tay các món hàng."}]},{"speaker":"Document 1 — E-mail","en":"As you know, my merchandise is 100 percent handcrafted. If any damage occurs in transit, the repair turns into an expensive, time-consuming ordeal. Over the years, I've seen too much damage done by inattentive baggage handlers. My policy is to deliver items personally whenever feasible or hire a ground- or sea-based courier service I trust.","vi":"Như bà đã biết, sản phẩm của tôi được chế tác thủ công 100 phần trăm. Nếu xảy ra bất kỳ hư hại nào trong quá trình vận chuyển, việc sửa chữa sẽ trở thành một quá trình cực kỳ tốn kém và mất nhiều thời gian. Suốt nhiều năm qua, tôi đã chứng kiến quá nhiều hư hỏng do các nhân viên bốc xếp hành lý bất cẩn gây ra. Chính sách của tôi là tự tay giao hàng bất cứ khi nào khả thi, hoặc thuê một dịch vụ chuyển phát đường bộ hay đường biển mà tôi tin tưởng.","units":[{"en":"As you know, my merchandise is 100 percent handcrafted.","vi":"Như bà đã biết, sản phẩm của tôi được chế tác thủ công 100 phần trăm."},{"en":"If any damage occurs in transit, the repair turns into an expensive, time-consuming ordeal.","vi":"Nếu xảy ra bất kỳ hư hại nào trong quá trình vận chuyển, việc sửa chữa sẽ trở thành một quá trình cực kỳ tốn kém và mất nhiều thời gian."},{"en":"Over the years, I've seen too much damage done by inattentive baggage handlers.","vi":"Suốt nhiều năm qua, tôi đã chứng kiến quá nhiều hư hỏng do các nhân viên bốc xếp hành lý bất cẩn gây ra."},{"en":"My policy is to deliver items personally whenever feasible or hire a ground- or sea-based courier service I trust.","vi":"Chính sách của tôi là tự tay giao hàng bất cứ khi nào khả thi, hoặc thuê một dịch vụ chuyển phát đường bộ hay đường biển mà tôi tin tưởng."}]},{"speaker":"Document 1 — E-mail","en":"I look forward to meeting you on 5 June. I expect to arrive at your house no later than 5 p.m.","vi":"Tôi rất mong được gặp bà vào ngày 5 tháng 6. Tôi dự kiến sẽ đến nhà bà chậm nhất là 5 giờ chiều.","units":[{"en":"I look forward to meeting you on 5 June.","vi":"Tôi rất mong được gặp bà vào ngày 5 tháng 6."},{"en":"I expect to arrive at your house no later than 5 p.m.","vi":"Tôi dự kiến sẽ đến nhà bà chậm nhất là 5 giờ chiều."}]},{"speaker":"Document 1 — E-mail","en":"Sincerely,","vi":"Trân trọng,","units":[{"en":"Sincerely,","vi":"Trân trọng,"}]},{"speaker":"Document 1 — E-mail","en":"Conor Boyle, Ceoleire Classics","vi":"Conor Boyle, Ceoleire Classics","units":[{"en":"Conor Boyle, Ceoleire Classics","vi":"Conor Boyle, Ceoleire Classics"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Northern Ireland Ferry Service","vi":"Dịch vụ Phà Bắc Ireland","units":[{"en":"Northern Ireland Ferry Service","vi":"Dịch vụ Phà Bắc Ireland"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Date of Issuance: 26 May","vi":"Ngày phát hành: 26 tháng 5","units":[{"en":"Date of Issuance: 26 May","vi":"Ngày phát hành: 26 tháng 5"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Passenger Name: Conor Boyle","vi":"Tên hành khách: Conor Boyle","units":[{"en":"Passenger Name: Conor Boyle","vi":"Tên hành khách: Conor Boyle"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Departing Belfast: Friday, 5 June, 1:05 PM","vi":"Khởi hành từ Belfast: Thứ Sáu, ngày 5 tháng 6, 1:05 chiều","units":[{"en":"Departing Belfast: Friday, 5 June, 1:05 PM","vi":"Khởi hành từ Belfast: Thứ Sáu, ngày 5 tháng 6, 1:05 chiều"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Docking at Cairnryan: Friday, 5 June, 3:20 PM","vi":"Cập bến tại Cairnryan: Thứ Sáu, ngày 5 tháng 6, 3:20 chiều","units":[{"en":"Docking at Cairnryan: Friday, 5 June, 3:20 PM","vi":"Cập bến tại Cairnryan: Thứ Sáu, ngày 5 tháng 6, 3:20 chiều"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Baggage: 1 suitcase (small), 2 instrument cases (1 mandolin, 1 guitar)","vi":"Hành lý: 1 vali (cỡ nhỏ), 2 hộp đựng nhạc cụ (1 đàn mandolin, 1 đàn guitar)","units":[{"en":"Baggage: 1 suitcase (small), 2 instrument cases (1 mandolin, 1 guitar)","vi":"Hành lý: 1 vali (cỡ nhỏ), 2 hộp đựng nhạc cụ (1 đàn mandolin, 1 đàn guitar)"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Vehicle transport: No","vi":"Vận chuyển phương tiện: Không","units":[{"en":"Vehicle transport: No","vi":"Vận chuyển phương tiện: Không"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Adult Standard Class: £55.00","vi":"Vé người lớn hạng Phổ thông: £55.00","units":[{"en":"Adult Standard Class: £55.00","vi":"Vé người lớn hạng Phổ thông: £55.00"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Please arrive 30 minutes prior to departure.","vi":"Vui lòng có mặt trước giờ khởi hành 30 phút.","units":[{"en":"Please arrive 30 minutes prior to departure.","vi":"Vui lòng có mặt trước giờ khởi hành 30 phút."}]}],"vocab":[{"word":"finalize","pos":"v","ipa":"/ˈfaɪnəlaɪz/","meaning":"hoàn tất, chốt lại"},{"word":"arrangement","pos":"n","ipa":"/əˈreɪndʒmənt/","meaning":"sự thu xếp, phương án sắp đặt"},{"word":"hand deliver","pos":"v","ipa":"/ˈhænd dɪˌlɪvər/","meaning":"giao tận tay"},{"word":"no later than","pos":"phr","ipa":"/noʊ ˈleɪtər ðæn/","meaning":"chậm nhất là, không muộn hơn"}],"isScanBacked":false,"docTypeLabel":"e-mail and ferry ticket","context":"E-mail and ferry ticket — Ceoleire Classics delivery to Stranraer","grammarType":"Part 7 — Ý chính, Mục đích & Đối tượng đọc (Main Idea & Purpose)","formula":"CÔNG THỨC PART 7 (Email phản hồi 'RE:' — Xác định mục đích): Email 'RE: Some suggestions' gạt bỏ các đề xuất cũ và chốt phương án cụ thể ('hand deliver' bằng xe thuê vào ngày 5/6 trước 5 giờ chiều) -> 'To finalize a plan' (A).","optionAnalysis":{"A":"Chính xác: Trả lời email 'RE: Some suggestions', ông Boyle chốt phương án tự lái xe thuê giao tận tay tại Stranraer vào ngày 5/6 chậm nhất 5 giờ chiều.","B":"Sai sắc thái từ vựng: Bà Savard đưa ra đề xuất phương án giao nhận ('kind offer'), không phải lời mời ('invitation'), và ông Boyle đã chọn cách tự giao.","C":"Bẫy đánh tráo thông tin: Đoạn 2 chỉ giải thích chính sách bảo vệ hàng thủ công sẵn có ('My policy'), không hề quảng bá dịch vụ mới nào.","D":"Bẫy lặp từ 'policy': Ông Boyle trình bày chính sách vận chuyển của mình để khách yên tâm chứ không hề yêu cầu bà Savard góp ý hay phản hồi."},"evDocIdx":0,"evTargets":[{"badge":"Câu 181 · Đáp án A","opt":"A","isCorrect":true,"quote":"Neither arrangement is necessary, as I am happy to deliver your items to you in Stranraer myself.","viQuote":"Cả hai phương án đó đều không cần thiết, vì tôi rất sẵn lòng tự mình giao hàng đến tận nơi cho bà tại Stranraer."},{"badge":"Câu 181 · Đáp án A","opt":"A","isCorrect":true,"quote":"I expect to arrive at your house no later than 5 p.m.","viQuote":"Tôi dự kiến sẽ đến nhà bà chậm nhất là 5 giờ chiều."}],"evQuotes":["Neither arrangement is necessary, as I am happy to deliver your items to you in Stranraer myself.","I expect to arrive at your house no later than 5 p.m."]},{"q":182,"part":7,"group_id":"E25_T01_G181_185","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc21.webp","web_assets/ets2025/p67/E25_T01_rc22.webp"],"stem_en":"Why will Mr. Boyle travel from Stranraer to Kirkcolm?","stem_vi":"Tại sao ông Boyle sẽ di chuyển từ Stranraer đến Kirkcolm?","options":{"A":{"en":"To make a delivery","vi":"Để giao hàng"},"B":{"en":"To attend a meeting","vi":"Để tham dự một cuộc họp"},"C":{"en":"To drop off a rental car","vi":"Để trả xe thuê"},"D":{"en":"To visit with family members","vi":"Để thăm các thành viên trong gia đình"}},"ans":"D","evidence_quote":"Neither arrangement is necessary, as I am happy to deliver your items to you in Stranraer myself. It so happens that my sister and her children live nearby in Kirkcolm. Before seeing them, I will drive my rental car to your house and hand deliver the items to you.","explanation":"Đáp án đúng: (D) Để thăm các thành viên trong gia đình — ông Boyle cho biết chị gái và các con của chị ấy (\"my sister and her children\") sống ở Kirkcolm, và trước khi gặp họ ông sẽ ghé nhà bà Savard ở Stranraer để giao hàng.\nDẫn chứng: \"It so happens that my sister and her children live nearby in Kirkcolm. Before seeing them, I will drive my rental car to your house and hand deliver the items to you.\" (Document 1 — E-mail: Chị gái tôi và các con của chị ấy sống gần đó ở Kirkcolm; trước khi đến gặp họ, tôi sẽ lái xe thuê ghé nhà bà giao hàng tại Stranraer).\nPhân tích bẫy:\n- (A) Nhầm lẫn giữa hai địa danh: Việc giao hàng (\"deliver your items\") diễn ra tại nhà bà Savard ở Stranraer, rồi sau đó ông mới đi sang Kirkcolm.\n- (B) Bẫy ngữ nghĩa sai từ \"meeting\": Cuối thư có câu \"I look forward to meeting you on 5 June\", dùng để hẹn gặp bà Savard khi giao hàng ở Stranraer, không phải họp ở Kirkcolm.\n- (C) Bẫy từ khóa \"rental car\": Ông Boyle lái xe thuê (\"drive my rental car\") để đi giao hàng và thăm người thân, bài không nói ông đến Kirkcolm để trả xe.","lines":[{"speaker":"Document 1 — E-mail","en":"To: laura.savard@orbitmail.scot","vi":"Đến: laura.savard@orbitmail.scot","units":[{"en":"To: laura.savard@orbitmail.scot","vi":"Đến: laura.savard@orbitmail.scot"}]},{"speaker":"Document 1 — E-mail","en":"From: cboyle@ceoleire.co.uk","vi":"Từ: cboyle@ceoleire.co.uk","units":[{"en":"From: cboyle@ceoleire.co.uk","vi":"Từ: cboyle@ceoleire.co.uk"}]},{"speaker":"Document 1 — E-mail","en":"Date: 25 May","vi":"Ngày: 25 tháng 5","units":[{"en":"Date: 25 May","vi":"Ngày: 25 tháng 5"}]},{"speaker":"Document 1 — E-mail","en":"Subject: RE: Some suggestions","vi":"Chủ đề: RE: Một số đề xuất","units":[{"en":"Subject: RE: Some suggestions","vi":"Chủ đề: RE: Một số đề xuất"}]},{"speaker":"Document 1 — E-mail","en":"Dear Ms. Savard,","vi":"Kính gửi bà Savard,","units":[{"en":"Dear Ms. Savard,","vi":"Kính gửi bà Savard,"}]},{"speaker":"Document 1 — E-mail","en":"Thank you for your kind offer to either pick up your online order from my shop or to pay extra for air or train transport. Neither arrangement is necessary, as I am happy to deliver your items to you in Stranraer myself. It so happens that my sister and her children live nearby in Kirkcolm. Before seeing them, I will drive my rental car to your house and hand deliver the items to you.","vi":"Cảm ơn bà đã nhã ý đề nghị tự đến cửa hàng của tôi nhận đơn đặt hàng trực tuyến hoặc trả thêm phí vận chuyển bằng đường hàng không hay tàu hỏa. Cả hai phương án đó đều không cần thiết, vì tôi rất sẵn lòng tự mình giao hàng đến tận nơi cho bà tại Stranraer. Thật tình cờ là chị gái tôi và các con của chị ấy cũng sống ngay gần đó ở Kirkcolm. Trước khi đến thăm họ, tôi sẽ lái xe thuê ghé qua nhà bà và giao tận tay các món hàng.","units":[{"en":"Thank you for your kind offer to either pick up your online order from my shop or to pay extra for air or train transport.","vi":"Cảm ơn bà đã nhã ý đề nghị tự đến cửa hàng của tôi nhận đơn đặt hàng trực tuyến hoặc trả thêm phí vận chuyển bằng đường hàng không hay tàu hỏa."},{"en":"Neither arrangement is necessary, as I am happy to deliver your items to you in Stranraer myself.","vi":"Cả hai phương án đó đều không cần thiết, vì tôi rất sẵn lòng tự mình giao hàng đến tận nơi cho bà tại Stranraer."},{"en":"It so happens that my sister and her children live nearby in Kirkcolm.","vi":"Thật tình cờ là chị gái tôi và các con của chị ấy cũng sống ngay gần đó ở Kirkcolm."},{"en":"Before seeing them, I will drive my rental car to your house and hand deliver the items to you.","vi":"Trước khi đến thăm họ, tôi sẽ lái xe thuê ghé qua nhà bà và giao tận tay các món hàng."}]},{"speaker":"Document 1 — E-mail","en":"As you know, my merchandise is 100 percent handcrafted. If any damage occurs in transit, the repair turns into an expensive, time-consuming ordeal. Over the years, I've seen too much damage done by inattentive baggage handlers. My policy is to deliver items personally whenever feasible or hire a ground- or sea-based courier service I trust.","vi":"Như bà đã biết, sản phẩm của tôi được chế tác thủ công 100 phần trăm. Nếu xảy ra bất kỳ hư hại nào trong quá trình vận chuyển, việc sửa chữa sẽ trở thành một quá trình cực kỳ tốn kém và mất nhiều thời gian. Suốt nhiều năm qua, tôi đã chứng kiến quá nhiều hư hỏng do các nhân viên bốc xếp hành lý bất cẩn gây ra. Chính sách của tôi là tự tay giao hàng bất cứ khi nào khả thi, hoặc thuê một dịch vụ chuyển phát đường bộ hay đường biển mà tôi tin tưởng.","units":[{"en":"As you know, my merchandise is 100 percent handcrafted.","vi":"Như bà đã biết, sản phẩm của tôi được chế tác thủ công 100 phần trăm."},{"en":"If any damage occurs in transit, the repair turns into an expensive, time-consuming ordeal.","vi":"Nếu xảy ra bất kỳ hư hại nào trong quá trình vận chuyển, việc sửa chữa sẽ trở thành một quá trình cực kỳ tốn kém và mất nhiều thời gian."},{"en":"Over the years, I've seen too much damage done by inattentive baggage handlers.","vi":"Suốt nhiều năm qua, tôi đã chứng kiến quá nhiều hư hỏng do các nhân viên bốc xếp hành lý bất cẩn gây ra."},{"en":"My policy is to deliver items personally whenever feasible or hire a ground- or sea-based courier service I trust.","vi":"Chính sách của tôi là tự tay giao hàng bất cứ khi nào khả thi, hoặc thuê một dịch vụ chuyển phát đường bộ hay đường biển mà tôi tin tưởng."}]},{"speaker":"Document 1 — E-mail","en":"I look forward to meeting you on 5 June. I expect to arrive at your house no later than 5 p.m.","vi":"Tôi rất mong được gặp bà vào ngày 5 tháng 6. Tôi dự kiến sẽ đến nhà bà chậm nhất là 5 giờ chiều.","units":[{"en":"I look forward to meeting you on 5 June.","vi":"Tôi rất mong được gặp bà vào ngày 5 tháng 6."},{"en":"I expect to arrive at your house no later than 5 p.m.","vi":"Tôi dự kiến sẽ đến nhà bà chậm nhất là 5 giờ chiều."}]},{"speaker":"Document 1 — E-mail","en":"Sincerely,","vi":"Trân trọng,","units":[{"en":"Sincerely,","vi":"Trân trọng,"}]},{"speaker":"Document 1 — E-mail","en":"Conor Boyle, Ceoleire Classics","vi":"Conor Boyle, Ceoleire Classics","units":[{"en":"Conor Boyle, Ceoleire Classics","vi":"Conor Boyle, Ceoleire Classics"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Northern Ireland Ferry Service","vi":"Dịch vụ Phà Bắc Ireland","units":[{"en":"Northern Ireland Ferry Service","vi":"Dịch vụ Phà Bắc Ireland"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Date of Issuance: 26 May","vi":"Ngày phát hành: 26 tháng 5","units":[{"en":"Date of Issuance: 26 May","vi":"Ngày phát hành: 26 tháng 5"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Passenger Name: Conor Boyle","vi":"Tên hành khách: Conor Boyle","units":[{"en":"Passenger Name: Conor Boyle","vi":"Tên hành khách: Conor Boyle"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Departing Belfast: Friday, 5 June, 1:05 PM","vi":"Khởi hành từ Belfast: Thứ Sáu, ngày 5 tháng 6, 1:05 chiều","units":[{"en":"Departing Belfast: Friday, 5 June, 1:05 PM","vi":"Khởi hành từ Belfast: Thứ Sáu, ngày 5 tháng 6, 1:05 chiều"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Docking at Cairnryan: Friday, 5 June, 3:20 PM","vi":"Cập bến tại Cairnryan: Thứ Sáu, ngày 5 tháng 6, 3:20 chiều","units":[{"en":"Docking at Cairnryan: Friday, 5 June, 3:20 PM","vi":"Cập bến tại Cairnryan: Thứ Sáu, ngày 5 tháng 6, 3:20 chiều"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Baggage: 1 suitcase (small), 2 instrument cases (1 mandolin, 1 guitar)","vi":"Hành lý: 1 vali (cỡ nhỏ), 2 hộp đựng nhạc cụ (1 đàn mandolin, 1 đàn guitar)","units":[{"en":"Baggage: 1 suitcase (small), 2 instrument cases (1 mandolin, 1 guitar)","vi":"Hành lý: 1 vali (cỡ nhỏ), 2 hộp đựng nhạc cụ (1 đàn mandolin, 1 đàn guitar)"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Vehicle transport: No","vi":"Vận chuyển phương tiện: Không","units":[{"en":"Vehicle transport: No","vi":"Vận chuyển phương tiện: Không"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Adult Standard Class: £55.00","vi":"Vé người lớn hạng Phổ thông: £55.00","units":[{"en":"Adult Standard Class: £55.00","vi":"Vé người lớn hạng Phổ thông: £55.00"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Please arrive 30 minutes prior to departure.","vi":"Vui lòng có mặt trước giờ khởi hành 30 phút.","units":[{"en":"Please arrive 30 minutes prior to departure.","vi":"Vui lòng có mặt trước giờ khởi hành 30 phút."}]}],"vocab":[{"word":"nearby","pos":"adv","ipa":"/ˌnɪrˈbaɪ/","meaning":"ở gần đó, lân cận"},{"word":"rental car","pos":"n","ipa":"/ˈrentəl kɑːr/","meaning":"xe ô tô thuê"},{"word":"pick up","pos":"phr. v","ipa":"/pɪk ʌp/","meaning":"đến nhận, lấy (hàng)"},{"word":"it so happens","pos":"phr","ipa":"/ɪt soʊ ˈhæpənz/","meaning":"thật tình cờ là"}],"isScanBacked":false,"docTypeLabel":"e-mail and ferry ticket","context":"E-mail and ferry ticket — Ceoleire Classics delivery to Stranraer","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 (Câu hỏi Why & Trình tự địa danh): Tách bạch 2 địa danh Stranraer (giao hàng cho khách) và Kirkcolm (nơi chị gái và các cháu sống) — 'Before seeing them' chốt lý do đi Kirkcolm là thăm gia đình (D).","optionAnalysis":{"A":"Bẫy đảo địa điểm: Việc giao hàng diễn ra tại Stranraer ('deliver your items to you in Stranraer'), còn đi Kirkcolm là để ghé thăm người thân sau đó.","B":"Bẫy từ khóa 'meeting': Cụm 'meeting you on 5 June' là hẹn gặp bà Savard ở Stranraer khi giao hàng, không phải tham dự cuộc họp tại Kirkcolm.","C":"Bẫy từ khóa 'rental car': Email chỉ nói ông sẽ lái xe thuê đến nhà bà Savard, hoàn toàn không có chi tiết trả xe thuê ('drop off') ở Kirkcolm.","D":"Chính xác: Document 1 nêu rõ 'my sister and her children live nearby in Kirkcolm' (chị gái và các cháu — thành viên gia đình) và ông sẽ ghé thăm họ sau khi giao hàng."},"evDocIdx":0,"evTargets":[{"badge":"Câu 182 · Đáp án D","opt":"D","isCorrect":true,"quote":"It so happens that my sister and her children live nearby in Kirkcolm.","viQuote":"Thật tình cờ là chị gái tôi và các con của chị ấy cũng sống ngay gần đó ở Kirkcolm."},{"badge":"Câu 182 · Đáp án D","opt":"D","isCorrect":true,"quote":"Before seeing them, I will drive my rental car to your house and hand deliver the items to you.","viQuote":"Trước khi đến thăm họ, tôi sẽ lái xe thuê ghé qua nhà bà và giao tận tay các món hàng."}],"evQuotes":["It so happens that my sister and her children live nearby in Kirkcolm.","Before seeing them, I will drive my rental car to your house and hand deliver the items to you."]},{"q":183,"part":7,"group_id":"E25_T01_G181_185","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc21.webp","web_assets/ets2025/p67/E25_T01_rc22.webp"],"stem_en":"What is indicated in the e-mail?","stem_vi":"Điều gì được đề cập trong email?","options":{"A":{"en":"Mr. Boyle's sister is a cofounder of Ceoleire Classics.","vi":"Chị gái của ông Boyle là người đồng sáng lập Ceoleire Classics."},"B":{"en":"Mr. Boyle has been disappointed by air- and train-freight companies.","vi":"Ông Boyle từng thất vọng với các công ty vận chuyển hàng hóa bằng đường hàng không và đường sắt."},"C":{"en":"Ms. Savard has purchased items from Mr. Boyle in the past.","vi":"Bà Savard đã từng mua hàng của ông Boyle trước đây."},"D":{"en":"Ms. Savard prefers a specific brand of luggage.","vi":"Bà Savard ưa chuộng một thương hiệu hành lý cụ thể."}},"ans":"B","evidence_quote":"If any damage occurs in transit, the repair turns into an expensive, time- consuming ordeal. Over the years, I've seen too much damage done by inattentive baggage handlers.","explanation":"Đáp án đúng: (B) Ông Boyle từng thất vọng với các công ty vận chuyển hàng hóa bằng đường hàng không và đường sắt — ông từ chối đề nghị gửi hàng qua đường hàng không/tàu hỏa của bà Savard và giải thích suốt nhiều năm đã chứng kiến quá nhiều hư hỏng do nhân viên bốc xếp hành lý bất cẩn gây ra, nên chỉ tự giao hoặc dùng chuyển phát đường bộ/biển tin cậy.\nDẫn chứng: \"Thank you for your kind offer to either pick up your online order from my shop or to pay extra for air or train transport.\" kết hợp đoạn 2: \"Over the years, I've seen too much damage done by inattentive baggage handlers. My policy is to deliver items personally whenever feasible or hire a ground- or sea-based courier service I trust.\" (Document 1 — E-mail).\nPhân tích bẫy:\n- (A) Suy diễn sai về người thân: Email chỉ nhắc chị gái ông Boyle sống ở Kirkcolm, không có chi tiết nào nói bà ấy là người đồng sáng lập Ceoleire Classics.\n- (C) Suy diễn quá mức từ cụm \"As you know\": Câu \"As you know, my merchandise is 100 percent handcrafted\" chỉ phản ánh thông tin bà Savard đã biết khi đặt đơn hiện tại, không chứng minh bà từng mua hàng trong quá khứ.\n- (D) Bẫy hiểu nhầm từ \"baggage\": Email nhắc đến \"baggage handlers\" (nhân viên xếp dỡ hành lý/kiện hàng làm hư hại sản phẩm), không liên quan đến sở thích thương hiệu hành lý của bà Savard.","lines":[{"speaker":"Document 1 — E-mail","en":"To: laura.savard@orbitmail.scot","vi":"Đến: laura.savard@orbitmail.scot","units":[{"en":"To: laura.savard@orbitmail.scot","vi":"Đến: laura.savard@orbitmail.scot"}]},{"speaker":"Document 1 — E-mail","en":"From: cboyle@ceoleire.co.uk","vi":"Từ: cboyle@ceoleire.co.uk","units":[{"en":"From: cboyle@ceoleire.co.uk","vi":"Từ: cboyle@ceoleire.co.uk"}]},{"speaker":"Document 1 — E-mail","en":"Date: 25 May","vi":"Ngày: 25 tháng 5","units":[{"en":"Date: 25 May","vi":"Ngày: 25 tháng 5"}]},{"speaker":"Document 1 — E-mail","en":"Subject: RE: Some suggestions","vi":"Chủ đề: RE: Một số đề xuất","units":[{"en":"Subject: RE: Some suggestions","vi":"Chủ đề: RE: Một số đề xuất"}]},{"speaker":"Document 1 — E-mail","en":"Dear Ms. Savard,","vi":"Kính gửi bà Savard,","units":[{"en":"Dear Ms. Savard,","vi":"Kính gửi bà Savard,"}]},{"speaker":"Document 1 — E-mail","en":"Thank you for your kind offer to either pick up your online order from my shop or to pay extra for air or train transport. Neither arrangement is necessary, as I am happy to deliver your items to you in Stranraer myself. It so happens that my sister and her children live nearby in Kirkcolm. Before seeing them, I will drive my rental car to your house and hand deliver the items to you.","vi":"Cảm ơn bà đã nhã ý đề nghị tự đến cửa hàng của tôi nhận đơn đặt hàng trực tuyến hoặc trả thêm phí vận chuyển bằng đường hàng không hay tàu hỏa. Cả hai phương án đó đều không cần thiết, vì tôi rất sẵn lòng tự mình giao hàng đến tận nơi cho bà tại Stranraer. Thật tình cờ là chị gái tôi và các con của chị ấy cũng sống ngay gần đó ở Kirkcolm. Trước khi đến thăm họ, tôi sẽ lái xe thuê ghé qua nhà bà và giao tận tay các món hàng.","units":[{"en":"Thank you for your kind offer to either pick up your online order from my shop or to pay extra for air or train transport.","vi":"Cảm ơn bà đã nhã ý đề nghị tự đến cửa hàng của tôi nhận đơn đặt hàng trực tuyến hoặc trả thêm phí vận chuyển bằng đường hàng không hay tàu hỏa."},{"en":"Neither arrangement is necessary, as I am happy to deliver your items to you in Stranraer myself.","vi":"Cả hai phương án đó đều không cần thiết, vì tôi rất sẵn lòng tự mình giao hàng đến tận nơi cho bà tại Stranraer."},{"en":"It so happens that my sister and her children live nearby in Kirkcolm.","vi":"Thật tình cờ là chị gái tôi và các con của chị ấy cũng sống ngay gần đó ở Kirkcolm."},{"en":"Before seeing them, I will drive my rental car to your house and hand deliver the items to you.","vi":"Trước khi đến thăm họ, tôi sẽ lái xe thuê ghé qua nhà bà và giao tận tay các món hàng."}]},{"speaker":"Document 1 — E-mail","en":"As you know, my merchandise is 100 percent handcrafted. If any damage occurs in transit, the repair turns into an expensive, time-consuming ordeal. Over the years, I've seen too much damage done by inattentive baggage handlers. My policy is to deliver items personally whenever feasible or hire a ground- or sea-based courier service I trust.","vi":"Như bà đã biết, sản phẩm của tôi được chế tác thủ công 100 phần trăm. Nếu xảy ra bất kỳ hư hại nào trong quá trình vận chuyển, việc sửa chữa sẽ trở thành một quá trình cực kỳ tốn kém và mất nhiều thời gian. Suốt nhiều năm qua, tôi đã chứng kiến quá nhiều hư hỏng do các nhân viên bốc xếp hành lý bất cẩn gây ra. Chính sách của tôi là tự tay giao hàng bất cứ khi nào khả thi, hoặc thuê một dịch vụ chuyển phát đường bộ hay đường biển mà tôi tin tưởng.","units":[{"en":"As you know, my merchandise is 100 percent handcrafted.","vi":"Như bà đã biết, sản phẩm của tôi được chế tác thủ công 100 phần trăm."},{"en":"If any damage occurs in transit, the repair turns into an expensive, time-consuming ordeal.","vi":"Nếu xảy ra bất kỳ hư hại nào trong quá trình vận chuyển, việc sửa chữa sẽ trở thành một quá trình cực kỳ tốn kém và mất nhiều thời gian."},{"en":"Over the years, I've seen too much damage done by inattentive baggage handlers.","vi":"Suốt nhiều năm qua, tôi đã chứng kiến quá nhiều hư hỏng do các nhân viên bốc xếp hành lý bất cẩn gây ra."},{"en":"My policy is to deliver items personally whenever feasible or hire a ground- or sea-based courier service I trust.","vi":"Chính sách của tôi là tự tay giao hàng bất cứ khi nào khả thi, hoặc thuê một dịch vụ chuyển phát đường bộ hay đường biển mà tôi tin tưởng."}]},{"speaker":"Document 1 — E-mail","en":"I look forward to meeting you on 5 June. I expect to arrive at your house no later than 5 p.m.","vi":"Tôi rất mong được gặp bà vào ngày 5 tháng 6. Tôi dự kiến sẽ đến nhà bà chậm nhất là 5 giờ chiều.","units":[{"en":"I look forward to meeting you on 5 June.","vi":"Tôi rất mong được gặp bà vào ngày 5 tháng 6."},{"en":"I expect to arrive at your house no later than 5 p.m.","vi":"Tôi dự kiến sẽ đến nhà bà chậm nhất là 5 giờ chiều."}]},{"speaker":"Document 1 — E-mail","en":"Sincerely,","vi":"Trân trọng,","units":[{"en":"Sincerely,","vi":"Trân trọng,"}]},{"speaker":"Document 1 — E-mail","en":"Conor Boyle, Ceoleire Classics","vi":"Conor Boyle, Ceoleire Classics","units":[{"en":"Conor Boyle, Ceoleire Classics","vi":"Conor Boyle, Ceoleire Classics"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Northern Ireland Ferry Service","vi":"Dịch vụ Phà Bắc Ireland","units":[{"en":"Northern Ireland Ferry Service","vi":"Dịch vụ Phà Bắc Ireland"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Date of Issuance: 26 May","vi":"Ngày phát hành: 26 tháng 5","units":[{"en":"Date of Issuance: 26 May","vi":"Ngày phát hành: 26 tháng 5"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Passenger Name: Conor Boyle","vi":"Tên hành khách: Conor Boyle","units":[{"en":"Passenger Name: Conor Boyle","vi":"Tên hành khách: Conor Boyle"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Departing Belfast: Friday, 5 June, 1:05 PM","vi":"Khởi hành từ Belfast: Thứ Sáu, ngày 5 tháng 6, 1:05 chiều","units":[{"en":"Departing Belfast: Friday, 5 June, 1:05 PM","vi":"Khởi hành từ Belfast: Thứ Sáu, ngày 5 tháng 6, 1:05 chiều"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Docking at Cairnryan: Friday, 5 June, 3:20 PM","vi":"Cập bến tại Cairnryan: Thứ Sáu, ngày 5 tháng 6, 3:20 chiều","units":[{"en":"Docking at Cairnryan: Friday, 5 June, 3:20 PM","vi":"Cập bến tại Cairnryan: Thứ Sáu, ngày 5 tháng 6, 3:20 chiều"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Baggage: 1 suitcase (small), 2 instrument cases (1 mandolin, 1 guitar)","vi":"Hành lý: 1 vali (cỡ nhỏ), 2 hộp đựng nhạc cụ (1 đàn mandolin, 1 đàn guitar)","units":[{"en":"Baggage: 1 suitcase (small), 2 instrument cases (1 mandolin, 1 guitar)","vi":"Hành lý: 1 vali (cỡ nhỏ), 2 hộp đựng nhạc cụ (1 đàn mandolin, 1 đàn guitar)"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Vehicle transport: No","vi":"Vận chuyển phương tiện: Không","units":[{"en":"Vehicle transport: No","vi":"Vận chuyển phương tiện: Không"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Adult Standard Class: £55.00","vi":"Vé người lớn hạng Phổ thông: £55.00","units":[{"en":"Adult Standard Class: £55.00","vi":"Vé người lớn hạng Phổ thông: £55.00"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Please arrive 30 minutes prior to departure.","vi":"Vui lòng có mặt trước giờ khởi hành 30 phút.","units":[{"en":"Please arrive 30 minutes prior to departure.","vi":"Vui lòng có mặt trước giờ khởi hành 30 phút."}]}],"vocab":[{"word":"handcrafted","pos":"adj","ipa":"/ˌhændˈkræftɪd/","meaning":"được chế tác thủ công"},{"word":"inattentive","pos":"adj","ipa":"/ˌɪnəˈtentɪv/","meaning":"bất cẩn, thiếu chú ý"},{"word":"feasible","pos":"adj","ipa":"/ˈfiːzəbəl/","meaning":"khả thi, có thể thực hiện được"},{"word":"courier service","pos":"n","ipa":"/ˈkʊriər ˈsɜːrvɪs/","meaning":"dịch vụ chuyển phát"}],"isScanBacked":false,"docTypeLabel":"e-mail and ferry ticket","context":"E-mail and ferry ticket — Ceoleire Classics delivery to Stranraer","grammarType":"Part 7 — Suy luận & Hàm ý văn bản (Inference & Implied Meaning)","formula":"CÔNG THỨC PART 7 (Suy luận nguyên nhân — Nối ý đoạn 1 & đoạn 2): Đoạn 1 từ chối 'air or train transport' + Đoạn 2 nêu 'too much damage done by inattentive baggage handlers' -> suy ra ông từng thất vọng với các hãng vận chuyển đường hàng không và đường sắt (B).","optionAnalysis":{"A":"Suy diễn vô căn cứ: Chị gái ông Boyle chỉ được nhắc đến là sống gần đó ở Kirkcolm, không có chi tiết nào nói bà đồng sáng lập Ceoleire Classics.","B":"Chính xác: Ông từ chối vận chuyển bằng máy bay/tàu hỏa và nêu rõ nhiều năm chứng kiến quá nhiều hư hỏng do nhân viên bốc xếp bất cẩn ('inattentive baggage handlers').","C":"Suy diễn quá mức: Bà Savard đặt hàng trực tuyến lần này và biết hàng làm thủ công ('As you know'), không có bằng chứng bà từng mua trước đây.","D":"Bẫy đánh tráo từ 'baggage': Từ 'baggage handlers' nói về nhân viên xếp dỡ làm hỏng nhạc cụ khi vận chuyển, không phải thương hiệu vali/hành lý bà Savard thích."},"evDocIdx":0,"evTargets":[{"badge":"Câu 183 · Đáp án B","opt":"B","isCorrect":true,"quote":"Over the years, I've seen too much damage done by inattentive baggage handlers.","viQuote":"Suốt nhiều năm qua, tôi đã chứng kiến quá nhiều hư hỏng do các nhân viên bốc xếp hành lý bất cẩn gây ra."},{"badge":"Câu 183 · Đáp án B","opt":"B","isCorrect":true,"quote":"My policy is to deliver items personally whenever feasible or hire a ground- or sea-based courier service I trust.","viQuote":"Chính sách của tôi là tự tay giao hàng bất cứ khi nào khả thi, hoặc thuê một dịch vụ chuyển phát đường bộ hay đường biển mà tôi tin tưởng."}],"evQuotes":["Over the years, I've seen too much damage done by inattentive baggage handlers.","My policy is to deliver items personally whenever feasible or hire a ground- or sea-based courier service I trust."]},{"q":184,"part":7,"group_id":"E25_T01_G181_185","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc21.webp","web_assets/ets2025/p67/E25_T01_rc22.webp"],"stem_en":"What is most likely true about Ms. Savard?","stem_vi":"Điều nào sau đây có khả năng đúng nhất về bà Savard?","options":{"A":{"en":"She often travels for her job.","vi":"Bà ấy thường xuyên đi công tác."},"B":{"en":"She paid extra to have items hand delivered.","vi":"Bà ấy đã trả thêm phí để được giao hàng tận tay."},"C":{"en":"She recently purchased musical instruments.","vi":"Gần đây bà ấy đã mua các nhạc cụ."},"D":{"en":"She will meet Mr. Boyle at the rental car office.","vi":"Bà ấy sẽ gặp ông Boyle tại văn phòng cho thuê xe."}},"ans":"C","evidence_quote":"- In the email: I will drive my rental car to your house and hand deliver the items to you. - On the ticket: Baggage: 1 suitcase (small), 2 instrument cases ( 1 mandolin, 1 guitar)","explanation":"Đáp án đúng: (C) Gần đây bà ấy đã mua các nhạc cụ — liên kết chéo hai văn bản: trong email ngày 25/5 (Document 1), ông Boyle xác nhận sẽ tự mang đơn hàng trực tuyến đến giao tận tay cho bà Savard vào ngày 5/6; đối chiếu vé phà ngày 5/6 của hành khách Conor Boyle (Document 2), hành lý mang theo gồm 2 hộp đựng nhạc cụ (1 đàn mandolin và 1 đàn guitar).\nDẫn chứng: Document 1 — E-mail: \"Thank you for your kind offer to either pick up your online order from my shop\" và \"I look forward to meeting you on 5 June.\" kết hợp Document 2 — Ticket (Receipt): \"Passenger Name: Conor Boyle\", \"Departing Belfast: Friday, 5 June, 1:05 PM\" và \"Baggage: 1 suitcase (small), 2 instrument cases (1 mandolin, 1 guitar)\".\nPhân tích bẫy:\n- (A) Suy diễn không căn cứ: Cả hai văn bản không đề cập nghề nghiệp hay việc bà Savard thường xuyên đi công tác.\n- (B) Sai thông tin chi phí: Bà Savard từng đề nghị trả thêm phí cho vận chuyển đường hàng không hoặc tàu hỏa, nhưng ông Boyle đã từ chối (\"Neither arrangement is necessary\") và tự đi giao.\n- (D) Sai địa điểm gặp mặt: Ông Boyle viết rõ sẽ lái xe thuê đến tận nhà bà (\"drive my rental car to your house\" và \"arrive at your house\"), không hẹn gặp ở văn phòng cho thuê xe.","lines":[{"speaker":"Document 1 — E-mail","en":"To: laura.savard@orbitmail.scot","vi":"Đến: laura.savard@orbitmail.scot","units":[{"en":"To: laura.savard@orbitmail.scot","vi":"Đến: laura.savard@orbitmail.scot"}]},{"speaker":"Document 1 — E-mail","en":"From: cboyle@ceoleire.co.uk","vi":"Từ: cboyle@ceoleire.co.uk","units":[{"en":"From: cboyle@ceoleire.co.uk","vi":"Từ: cboyle@ceoleire.co.uk"}]},{"speaker":"Document 1 — E-mail","en":"Date: 25 May","vi":"Ngày: 25 tháng 5","units":[{"en":"Date: 25 May","vi":"Ngày: 25 tháng 5"}]},{"speaker":"Document 1 — E-mail","en":"Subject: RE: Some suggestions","vi":"Chủ đề: RE: Một số đề xuất","units":[{"en":"Subject: RE: Some suggestions","vi":"Chủ đề: RE: Một số đề xuất"}]},{"speaker":"Document 1 — E-mail","en":"Dear Ms. Savard,","vi":"Kính gửi bà Savard,","units":[{"en":"Dear Ms. Savard,","vi":"Kính gửi bà Savard,"}]},{"speaker":"Document 1 — E-mail","en":"Thank you for your kind offer to either pick up your online order from my shop or to pay extra for air or train transport. Neither arrangement is necessary, as I am happy to deliver your items to you in Stranraer myself. It so happens that my sister and her children live nearby in Kirkcolm. Before seeing them, I will drive my rental car to your house and hand deliver the items to you.","vi":"Cảm ơn bà đã nhã ý đề nghị tự đến cửa hàng của tôi nhận đơn đặt hàng trực tuyến hoặc trả thêm phí vận chuyển bằng đường hàng không hay tàu hỏa. Cả hai phương án đó đều không cần thiết, vì tôi rất sẵn lòng tự mình giao hàng đến tận nơi cho bà tại Stranraer. Thật tình cờ là chị gái tôi và các con của chị ấy cũng sống ngay gần đó ở Kirkcolm. Trước khi đến thăm họ, tôi sẽ lái xe thuê ghé qua nhà bà và giao tận tay các món hàng.","units":[{"en":"Thank you for your kind offer to either pick up your online order from my shop or to pay extra for air or train transport.","vi":"Cảm ơn bà đã nhã ý đề nghị tự đến cửa hàng của tôi nhận đơn đặt hàng trực tuyến hoặc trả thêm phí vận chuyển bằng đường hàng không hay tàu hỏa."},{"en":"Neither arrangement is necessary, as I am happy to deliver your items to you in Stranraer myself.","vi":"Cả hai phương án đó đều không cần thiết, vì tôi rất sẵn lòng tự mình giao hàng đến tận nơi cho bà tại Stranraer."},{"en":"It so happens that my sister and her children live nearby in Kirkcolm.","vi":"Thật tình cờ là chị gái tôi và các con của chị ấy cũng sống ngay gần đó ở Kirkcolm."},{"en":"Before seeing them, I will drive my rental car to your house and hand deliver the items to you.","vi":"Trước khi đến thăm họ, tôi sẽ lái xe thuê ghé qua nhà bà và giao tận tay các món hàng."}]},{"speaker":"Document 1 — E-mail","en":"As you know, my merchandise is 100 percent handcrafted. If any damage occurs in transit, the repair turns into an expensive, time-consuming ordeal. Over the years, I've seen too much damage done by inattentive baggage handlers. My policy is to deliver items personally whenever feasible or hire a ground- or sea-based courier service I trust.","vi":"Như bà đã biết, sản phẩm của tôi được chế tác thủ công 100 phần trăm. Nếu xảy ra bất kỳ hư hại nào trong quá trình vận chuyển, việc sửa chữa sẽ trở thành một quá trình cực kỳ tốn kém và mất nhiều thời gian. Suốt nhiều năm qua, tôi đã chứng kiến quá nhiều hư hỏng do các nhân viên bốc xếp hành lý bất cẩn gây ra. Chính sách của tôi là tự tay giao hàng bất cứ khi nào khả thi, hoặc thuê một dịch vụ chuyển phát đường bộ hay đường biển mà tôi tin tưởng.","units":[{"en":"As you know, my merchandise is 100 percent handcrafted.","vi":"Như bà đã biết, sản phẩm của tôi được chế tác thủ công 100 phần trăm."},{"en":"If any damage occurs in transit, the repair turns into an expensive, time-consuming ordeal.","vi":"Nếu xảy ra bất kỳ hư hại nào trong quá trình vận chuyển, việc sửa chữa sẽ trở thành một quá trình cực kỳ tốn kém và mất nhiều thời gian."},{"en":"Over the years, I've seen too much damage done by inattentive baggage handlers.","vi":"Suốt nhiều năm qua, tôi đã chứng kiến quá nhiều hư hỏng do các nhân viên bốc xếp hành lý bất cẩn gây ra."},{"en":"My policy is to deliver items personally whenever feasible or hire a ground- or sea-based courier service I trust.","vi":"Chính sách của tôi là tự tay giao hàng bất cứ khi nào khả thi, hoặc thuê một dịch vụ chuyển phát đường bộ hay đường biển mà tôi tin tưởng."}]},{"speaker":"Document 1 — E-mail","en":"I look forward to meeting you on 5 June. I expect to arrive at your house no later than 5 p.m.","vi":"Tôi rất mong được gặp bà vào ngày 5 tháng 6. Tôi dự kiến sẽ đến nhà bà chậm nhất là 5 giờ chiều.","units":[{"en":"I look forward to meeting you on 5 June.","vi":"Tôi rất mong được gặp bà vào ngày 5 tháng 6."},{"en":"I expect to arrive at your house no later than 5 p.m.","vi":"Tôi dự kiến sẽ đến nhà bà chậm nhất là 5 giờ chiều."}]},{"speaker":"Document 1 — E-mail","en":"Sincerely,","vi":"Trân trọng,","units":[{"en":"Sincerely,","vi":"Trân trọng,"}]},{"speaker":"Document 1 — E-mail","en":"Conor Boyle, Ceoleire Classics","vi":"Conor Boyle, Ceoleire Classics","units":[{"en":"Conor Boyle, Ceoleire Classics","vi":"Conor Boyle, Ceoleire Classics"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Northern Ireland Ferry Service","vi":"Dịch vụ Phà Bắc Ireland","units":[{"en":"Northern Ireland Ferry Service","vi":"Dịch vụ Phà Bắc Ireland"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Date of Issuance: 26 May","vi":"Ngày phát hành: 26 tháng 5","units":[{"en":"Date of Issuance: 26 May","vi":"Ngày phát hành: 26 tháng 5"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Passenger Name: Conor Boyle","vi":"Tên hành khách: Conor Boyle","units":[{"en":"Passenger Name: Conor Boyle","vi":"Tên hành khách: Conor Boyle"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Departing Belfast: Friday, 5 June, 1:05 PM","vi":"Khởi hành từ Belfast: Thứ Sáu, ngày 5 tháng 6, 1:05 chiều","units":[{"en":"Departing Belfast: Friday, 5 June, 1:05 PM","vi":"Khởi hành từ Belfast: Thứ Sáu, ngày 5 tháng 6, 1:05 chiều"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Docking at Cairnryan: Friday, 5 June, 3:20 PM","vi":"Cập bến tại Cairnryan: Thứ Sáu, ngày 5 tháng 6, 3:20 chiều","units":[{"en":"Docking at Cairnryan: Friday, 5 June, 3:20 PM","vi":"Cập bến tại Cairnryan: Thứ Sáu, ngày 5 tháng 6, 3:20 chiều"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Baggage: 1 suitcase (small), 2 instrument cases (1 mandolin, 1 guitar)","vi":"Hành lý: 1 vali (cỡ nhỏ), 2 hộp đựng nhạc cụ (1 đàn mandolin, 1 đàn guitar)","units":[{"en":"Baggage: 1 suitcase (small), 2 instrument cases (1 mandolin, 1 guitar)","vi":"Hành lý: 1 vali (cỡ nhỏ), 2 hộp đựng nhạc cụ (1 đàn mandolin, 1 đàn guitar)"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Vehicle transport: No","vi":"Vận chuyển phương tiện: Không","units":[{"en":"Vehicle transport: No","vi":"Vận chuyển phương tiện: Không"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Adult Standard Class: £55.00","vi":"Vé người lớn hạng Phổ thông: £55.00","units":[{"en":"Adult Standard Class: £55.00","vi":"Vé người lớn hạng Phổ thông: £55.00"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Please arrive 30 minutes prior to departure.","vi":"Vui lòng có mặt trước giờ khởi hành 30 phút.","units":[{"en":"Please arrive 30 minutes prior to departure.","vi":"Vui lòng có mặt trước giờ khởi hành 30 phút."}]}],"vocab":[{"word":"musical instrument","pos":"n","ipa":"/ˈmjuːzɪkəl ˈɪnstrəmənt/","meaning":"nhạc cụ"},{"word":"merchandise","pos":"n","ipa":"/ˈmɜːrtʃəndaɪz/","meaning":"hàng hóa"},{"word":"in transit","pos":"phr","ipa":"/ɪn ˈtrænzɪt/","meaning":"trong quá trình vận chuyển"},{"word":"ordeal","pos":"n","ipa":"/ɔːrˈdiːl/","meaning":"trải nghiệm gian nan, quá trình rắc rối"}],"isScanBacked":false,"docTypeLabel":"e-mail and ferry ticket","context":"E-mail and ferry ticket — Ceoleire Classics delivery to Stranraer","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 LIÊN KẾT ĐA VĂN BẢN (EMAIL + VÉ PHÀ): Email ngày 25/5 xác nhận giao 'your online order' vào ngày 5/6 -> Tra mục Baggage trên vé phà ngày 5/6 của Conor Boyle thấy '2 instrument cases (1 mandolin, 1 guitar)' -> Chốt (C).","optionAnalysis":{"A":"Suy diễn không căn cứ: Cả hai văn bản không hề nhắc đến công việc hay thói quen đi công tác của bà Savard.","B":"Bẫy từ khóa 'pay extra': Bà Savard chỉ đề nghị trả thêm phí cho vận chuyển đường hàng không/tàu hỏa và ông Boyle đã nói không cần thiết ('Neither arrangement is necessary').","C":"Chính xác (liên kết 2 văn bản): Email ngày 25/5 hẹn giao 'online order' ngày 5/6, khớp với vé phà ngày 5/6 của ông Boyle mang theo '2 instrument cases (1 mandolin, 1 guitar)'.","D":"Bẫy ghép từ 'rental car': Ông Boyle tự lái xe thuê đến tận nhà bà Savard ('arrive at your house'), không hẹn gặp tại văn phòng cho thuê xe."},"evDocIdx":1,"evTargets":[{"badge":"Câu 184 · Đáp án C","opt":"C","isCorrect":true,"quote":"Baggage: 1 suitcase (small), 2 instrument cases (1 mandolin, 1 guitar)","viQuote":"Hành lý: 1 vali (cỡ nhỏ), 2 hộp đựng nhạc cụ (1 đàn mandolin, 1 đàn guitar)"},{"badge":"Câu 184 · Đáp án C","opt":"C","isCorrect":true,"quote":"Thank you for your kind offer to either pick up your online order from my shop or to pay extra for air or train transport.","viQuote":"Cảm ơn bà đã nhã ý đề nghị tự đến cửa hàng của tôi nhận đơn đặt hàng trực tuyến hoặc trả thêm phí vận chuyển bằng đường hàng không hay tàu hỏa."}],"evQuotes":["Baggage: 1 suitcase (small), 2 instrument cases (1 mandolin, 1 guitar)","Thank you for your kind offer to either pick up your online order from my shop or to pay extra for air or train transport."]},{"q":185,"part":7,"group_id":"E25_T01_G181_185","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc21.webp","web_assets/ets2025/p67/E25_T01_rc22.webp"],"stem_en":"How is Mr. Boyle traveling to Cairnryan on June 5?","stem_vi":"Ông Boyle sẽ di chuyển đến Cairnryan vào ngày 5 tháng 6 bằng phương tiện gì?","options":{"A":{"en":"By car","vi":"Bằng ô tô"},"B":{"en":"By train","vi":"Bằng tàu hỏa"},"C":{"en":"By boat","vi":"Bằng tàu thủy"},"D":{"en":"By plane","vi":"Bằng máy bay"}},"ans":"C","evidence_quote":"Northern Ireland Ferry Service Departing Belfast: Friday, 5 June","explanation":"Đáp án đúng: (C) Bằng tàu thủy — theo vé ở Document 2, vào ngày 5 tháng 6 ông Boyle đi dịch vụ phà \"Northern Ireland Ferry Service\" khởi hành từ Belfast lúc 1:05 PM và cập bến tại Cairnryan lúc 3:20 PM; mục \"Vehicle transport: No\" cũng xác nhận ông đi phà không mang theo ô tô.\nDẫn chứng: \"Northern Ireland Ferry Service / Departing Belfast: Friday, 5 June, 1:05 PM / Docking at Cairnryan: Friday, 5 June, 3:20 PM / Vehicle transport: No\" (Document 2 — Ticket (Receipt): Đi phà cập bến tại Cairnryan, không vận chuyển phương tiện).\nPhân tích bẫy:\n- (A) Bẫy đánh tráo chặng đường: Vé phà ghi rõ \"Vehicle transport: No\", nghĩa là ông đi phà sang Cairnryan rồi mới lấy xe thuê (\"rental car\") lái tới Stranraer và Kirkcolm.\n- (B) Bẫy phương tiện bị từ chối: \"train transport\" chỉ là phương án gửi hàng mà bà Savard từng gợi ý trong Document 1 và đã bị ông Boyle gạt bỏ.\n- (D) Bẫy phương tiện bị từ chối: Cũng như tàu hỏa, \"air transport\" là gợi ý gửi hàng đã bị từ chối ở đầu Document 1, không phải phương tiện ông Boyle dùng ngày 5/6.","lines":[{"speaker":"Document 1 — E-mail","en":"To: laura.savard@orbitmail.scot","vi":"Đến: laura.savard@orbitmail.scot","units":[{"en":"To: laura.savard@orbitmail.scot","vi":"Đến: laura.savard@orbitmail.scot"}]},{"speaker":"Document 1 — E-mail","en":"From: cboyle@ceoleire.co.uk","vi":"Từ: cboyle@ceoleire.co.uk","units":[{"en":"From: cboyle@ceoleire.co.uk","vi":"Từ: cboyle@ceoleire.co.uk"}]},{"speaker":"Document 1 — E-mail","en":"Date: 25 May","vi":"Ngày: 25 tháng 5","units":[{"en":"Date: 25 May","vi":"Ngày: 25 tháng 5"}]},{"speaker":"Document 1 — E-mail","en":"Subject: RE: Some suggestions","vi":"Chủ đề: RE: Một số đề xuất","units":[{"en":"Subject: RE: Some suggestions","vi":"Chủ đề: RE: Một số đề xuất"}]},{"speaker":"Document 1 — E-mail","en":"Dear Ms. Savard,","vi":"Kính gửi bà Savard,","units":[{"en":"Dear Ms. Savard,","vi":"Kính gửi bà Savard,"}]},{"speaker":"Document 1 — E-mail","en":"Thank you for your kind offer to either pick up your online order from my shop or to pay extra for air or train transport. Neither arrangement is necessary, as I am happy to deliver your items to you in Stranraer myself. It so happens that my sister and her children live nearby in Kirkcolm. Before seeing them, I will drive my rental car to your house and hand deliver the items to you.","vi":"Cảm ơn bà đã nhã ý đề nghị tự đến cửa hàng của tôi nhận đơn đặt hàng trực tuyến hoặc trả thêm phí vận chuyển bằng đường hàng không hay tàu hỏa. Cả hai phương án đó đều không cần thiết, vì tôi rất sẵn lòng tự mình giao hàng đến tận nơi cho bà tại Stranraer. Thật tình cờ là chị gái tôi và các con của chị ấy cũng sống ngay gần đó ở Kirkcolm. Trước khi đến thăm họ, tôi sẽ lái xe thuê ghé qua nhà bà và giao tận tay các món hàng.","units":[{"en":"Thank you for your kind offer to either pick up your online order from my shop or to pay extra for air or train transport.","vi":"Cảm ơn bà đã nhã ý đề nghị tự đến cửa hàng của tôi nhận đơn đặt hàng trực tuyến hoặc trả thêm phí vận chuyển bằng đường hàng không hay tàu hỏa."},{"en":"Neither arrangement is necessary, as I am happy to deliver your items to you in Stranraer myself.","vi":"Cả hai phương án đó đều không cần thiết, vì tôi rất sẵn lòng tự mình giao hàng đến tận nơi cho bà tại Stranraer."},{"en":"It so happens that my sister and her children live nearby in Kirkcolm.","vi":"Thật tình cờ là chị gái tôi và các con của chị ấy cũng sống ngay gần đó ở Kirkcolm."},{"en":"Before seeing them, I will drive my rental car to your house and hand deliver the items to you.","vi":"Trước khi đến thăm họ, tôi sẽ lái xe thuê ghé qua nhà bà và giao tận tay các món hàng."}]},{"speaker":"Document 1 — E-mail","en":"As you know, my merchandise is 100 percent handcrafted. If any damage occurs in transit, the repair turns into an expensive, time-consuming ordeal. Over the years, I've seen too much damage done by inattentive baggage handlers. My policy is to deliver items personally whenever feasible or hire a ground- or sea-based courier service I trust.","vi":"Như bà đã biết, sản phẩm của tôi được chế tác thủ công 100 phần trăm. Nếu xảy ra bất kỳ hư hại nào trong quá trình vận chuyển, việc sửa chữa sẽ trở thành một quá trình cực kỳ tốn kém và mất nhiều thời gian. Suốt nhiều năm qua, tôi đã chứng kiến quá nhiều hư hỏng do các nhân viên bốc xếp hành lý bất cẩn gây ra. Chính sách của tôi là tự tay giao hàng bất cứ khi nào khả thi, hoặc thuê một dịch vụ chuyển phát đường bộ hay đường biển mà tôi tin tưởng.","units":[{"en":"As you know, my merchandise is 100 percent handcrafted.","vi":"Như bà đã biết, sản phẩm của tôi được chế tác thủ công 100 phần trăm."},{"en":"If any damage occurs in transit, the repair turns into an expensive, time-consuming ordeal.","vi":"Nếu xảy ra bất kỳ hư hại nào trong quá trình vận chuyển, việc sửa chữa sẽ trở thành một quá trình cực kỳ tốn kém và mất nhiều thời gian."},{"en":"Over the years, I've seen too much damage done by inattentive baggage handlers.","vi":"Suốt nhiều năm qua, tôi đã chứng kiến quá nhiều hư hỏng do các nhân viên bốc xếp hành lý bất cẩn gây ra."},{"en":"My policy is to deliver items personally whenever feasible or hire a ground- or sea-based courier service I trust.","vi":"Chính sách của tôi là tự tay giao hàng bất cứ khi nào khả thi, hoặc thuê một dịch vụ chuyển phát đường bộ hay đường biển mà tôi tin tưởng."}]},{"speaker":"Document 1 — E-mail","en":"I look forward to meeting you on 5 June. I expect to arrive at your house no later than 5 p.m.","vi":"Tôi rất mong được gặp bà vào ngày 5 tháng 6. Tôi dự kiến sẽ đến nhà bà chậm nhất là 5 giờ chiều.","units":[{"en":"I look forward to meeting you on 5 June.","vi":"Tôi rất mong được gặp bà vào ngày 5 tháng 6."},{"en":"I expect to arrive at your house no later than 5 p.m.","vi":"Tôi dự kiến sẽ đến nhà bà chậm nhất là 5 giờ chiều."}]},{"speaker":"Document 1 — E-mail","en":"Sincerely,","vi":"Trân trọng,","units":[{"en":"Sincerely,","vi":"Trân trọng,"}]},{"speaker":"Document 1 — E-mail","en":"Conor Boyle, Ceoleire Classics","vi":"Conor Boyle, Ceoleire Classics","units":[{"en":"Conor Boyle, Ceoleire Classics","vi":"Conor Boyle, Ceoleire Classics"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Northern Ireland Ferry Service","vi":"Dịch vụ Phà Bắc Ireland","units":[{"en":"Northern Ireland Ferry Service","vi":"Dịch vụ Phà Bắc Ireland"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Date of Issuance: 26 May","vi":"Ngày phát hành: 26 tháng 5","units":[{"en":"Date of Issuance: 26 May","vi":"Ngày phát hành: 26 tháng 5"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Passenger Name: Conor Boyle","vi":"Tên hành khách: Conor Boyle","units":[{"en":"Passenger Name: Conor Boyle","vi":"Tên hành khách: Conor Boyle"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Departing Belfast: Friday, 5 June, 1:05 PM","vi":"Khởi hành từ Belfast: Thứ Sáu, ngày 5 tháng 6, 1:05 chiều","units":[{"en":"Departing Belfast: Friday, 5 June, 1:05 PM","vi":"Khởi hành từ Belfast: Thứ Sáu, ngày 5 tháng 6, 1:05 chiều"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Docking at Cairnryan: Friday, 5 June, 3:20 PM","vi":"Cập bến tại Cairnryan: Thứ Sáu, ngày 5 tháng 6, 3:20 chiều","units":[{"en":"Docking at Cairnryan: Friday, 5 June, 3:20 PM","vi":"Cập bến tại Cairnryan: Thứ Sáu, ngày 5 tháng 6, 3:20 chiều"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Baggage: 1 suitcase (small), 2 instrument cases (1 mandolin, 1 guitar)","vi":"Hành lý: 1 vali (cỡ nhỏ), 2 hộp đựng nhạc cụ (1 đàn mandolin, 1 đàn guitar)","units":[{"en":"Baggage: 1 suitcase (small), 2 instrument cases (1 mandolin, 1 guitar)","vi":"Hành lý: 1 vali (cỡ nhỏ), 2 hộp đựng nhạc cụ (1 đàn mandolin, 1 đàn guitar)"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Vehicle transport: No","vi":"Vận chuyển phương tiện: Không","units":[{"en":"Vehicle transport: No","vi":"Vận chuyển phương tiện: Không"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Adult Standard Class: £55.00","vi":"Vé người lớn hạng Phổ thông: £55.00","units":[{"en":"Adult Standard Class: £55.00","vi":"Vé người lớn hạng Phổ thông: £55.00"}]},{"speaker":"Document 2 — Ticket (Receipt)","en":"Please arrive 30 minutes prior to departure.","vi":"Vui lòng có mặt trước giờ khởi hành 30 phút.","units":[{"en":"Please arrive 30 minutes prior to departure.","vi":"Vui lòng có mặt trước giờ khởi hành 30 phút."}]}],"vocab":[{"word":"ferry","pos":"n","ipa":"/ˈferi/","meaning":"phà, tàu chở khách qua eo biển"},{"word":"dock","pos":"v","ipa":"/dɑːk/","meaning":"cập bến, cập cảng"},{"word":"issuance","pos":"n","ipa":"/ˈɪʃuəns/","meaning":"sự phát hành, cấp vé"},{"word":"prior to","pos":"prep","ipa":"/ˈpraɪər tuː/","meaning":"trước khi"}],"isScanBacked":false,"docTypeLabel":"e-mail and ferry ticket","context":"E-mail and ferry ticket — Ceoleire Classics delivery to Stranraer","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 LIÊN KẾT ĐA VĂN BẢN (CHỐNG BẪY PHƯƠNG TIỆN): Quét điểm đến 'Cairnryan' ở Document 2 (Vé phà: Northern Ireland Ferry Service + Vehicle transport: No) -> 'ferry' = 'By boat' (C), tránh bẫy 'rental car' dùng cho chặng tiếp theo ở Document 1.","optionAnalysis":{"A":"Bẫy chặng đường sau: Vé phà Document 2 ghi 'Vehicle transport: No', tức ông đi phà sang Cairnryan trước rồi mới thuê xe lái tới nhà bà Savard ở Stranraer.","B":"Bẫy chi tiết bị bác bỏ: 'train transport' là phương án vận chuyển hàng hóa bà Savard đề nghị ở Document 1 nhưng ông Boyle đã từ chối.","C":"Chính xác: Document 2 là vé của 'Northern Ireland Ferry Service' khởi hành từ Belfast và cập bến ('Docking at') Cairnryan vào ngày 5/6, tức đi bằng phà/tàu thủy.","D":"Bẫy chi tiết bị bác bỏ: 'air transport' chỉ được nhắc ở Document 1 như phương án gửi hàng mà ông Boyle không lựa chọn."},"evDocIdx":1,"evTargets":[{"badge":"Câu 185 · Đáp án C","opt":"C","isCorrect":true,"quote":"Northern Ireland Ferry Service","viQuote":"Dịch vụ Phà Bắc Ireland"},{"badge":"Câu 185 · Đáp án C","opt":"C","isCorrect":true,"quote":"Docking at Cairnryan: Friday, 5 June, 3:20 PM","viQuote":"Cập bến tại Cairnryan: Thứ Sáu, ngày 5 tháng 6, 3:20 chiều"}],"evQuotes":["Northern Ireland Ferry Service","Docking at Cairnryan: Friday, 5 June, 3:20 PM"]},{"q":186,"part":7,"group_id":"E25_T01_G186_190","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc23.webp","web_assets/ets2025/p67/E25_T01_rc24.webp"],"stem_en":"What is indicated about TTA?","stem_vi":"Điều gì được cho biết về TTA?","options":{"A":{"en":"It was founded by a graphic designer.","vi":"Tổ chức này được thành lập bởi một nhà thiết kế đồ họa."},"B":{"en":"It publishes its own online newsletter.","vi":"Tổ chức này tự xuất bản bản tin trực tuyến riêng."},"C":{"en":"It offers classes led by industry professionals.","vi":"Tổ chức này cung cấp các lớp học do những chuyên gia trong ngành giảng dạy."},"D":{"en":"It has classroom facilities in cities across West Africa.","vi":"Tổ chức này có các cơ sở phòng học tại nhiều thành phố khắp Tây Phi."}},"ans":"C","evidence_quote":"All classes include individualized instruction and are taught by recognized professionals in their respective fields.","explanation":"Đáp án đúng: (C) Tổ chức này cung cấp các lớp học do những chuyên gia trong ngành giảng dạy — Quảng cáo khẳng định mọi lớp học tại TTA đều do các chuyên gia có uy tín trong lĩnh vực của họ đứng lớp.\nDẫn chứng: \"All classes include individualized instruction and are taught by recognized professionals in their respective fields.\" (Document 1 — Advertisement: 'recognized professionals in their respective fields' được paraphrase thành 'industry professionals', 'taught by' thành 'led by').\nPhân tích bẫy:\n- (A) Bẫy đánh tráo vai trò: Document 1 chỉ nhắc Doug Umaru là nhà thiết kế đồ họa kỳ cựu (veteran graphic designer) giảng dạy lớp TTA7633, không nói ông là người sáng lập TTA.\n- (B) Bẫy đảo chủ thể: TTA được giới thiệu trên bản tin Business Directions Nigeria ('Profiled in the latest Business Directions Nigeria newsletter'), chứ không phải TTA tự xuất bản bản tin riêng.\n- (D) Bẫy trái ngược thông tin: Document 1 nêu rõ các lớp học tổ chức hoàn toàn trực tuyến ('entirely in online format'), không có hệ thống phòng học vật lý khắp Tây Phi.","lines":[{"speaker":"Document 1 — Advertisement","en":"Train to Achieve (TTA)—Our classes prepare you to succeed!","vi":"Train to Achieve (TTA) — Các lớp học của chúng tôi trang bị hành trang để bạn thành công!","units":[{"en":"Train to Achieve (TTA)—Our classes prepare you to succeed!","vi":"Train to Achieve (TTA) — Các lớp học của chúng tôi trang bị hành trang để bạn thành công!"}]},{"speaker":"Document 1 — Advertisement","en":"Profiled in the latest Business Directions Nigeria newsletter, Train to Achieve (TTA) is one of the most innovative training providers in West Africa. By offering our classes entirely in online format, we bring the classroom to your home.","vi":"Được giới thiệu trên số mới nhất của bản tin Business Directions Nigeria, Train to Achieve (TTA) là một trong những đơn vị đào tạo đổi mới sáng tạo hàng đầu tại Tây Phi. Bằng việc tổ chức toàn bộ các lớp học theo hình thức trực tuyến, chúng tôi mang lớp học đến ngay tại nhà bạn.","units":[{"en":"Profiled in the latest Business Directions Nigeria newsletter, Train to Achieve (TTA) is one of the most innovative training providers in West Africa.","vi":"Được giới thiệu trên số mới nhất của bản tin Business Directions Nigeria, Train to Achieve (TTA) là một trong những đơn vị đào tạo đổi mới sáng tạo hàng đầu tại Tây Phi."},{"en":"By offering our classes entirely in online format, we bring the classroom to your home.","vi":"Bằng việc tổ chức toàn bộ các lớp học theo hình thức trực tuyến, chúng tôi mang lớp học đến ngay tại nhà bạn."}]},{"speaker":"Document 1 — Advertisement","en":"All classes include individualized instruction and are taught by recognized professionals in their respective fields. Upon successful completion of a class, you will receive an official Certificate of Training, a valuable addition to any résumé.","vi":"Mọi lớp học đều có phần hướng dẫn cá nhân hóa và do các chuyên gia uy tín trong từng lĩnh vực trực tiếp giảng dạy. Khi hoàn thành tốt khóa học, bạn sẽ nhận được Chứng chỉ Đào tạo chính thức — một điểm cộng giá trị cho bất kỳ hồ sơ xin việc nào.","units":[{"en":"All classes include individualized instruction and are taught by recognized professionals in their respective fields.","vi":"Mọi lớp học đều có phần hướng dẫn cá nhân hóa và do các chuyên gia uy tín trong từng lĩnh vực trực tiếp giảng dạy."},{"en":"Upon successful completion of a class, you will receive an official Certificate of Training, a valuable addition to any résumé.","vi":"Khi hoàn thành tốt khóa học, bạn sẽ nhận được Chứng chỉ Đào tạo chính thức — một điểm cộng giá trị cho bất kỳ hồ sơ xin việc nào."}]},{"speaker":"Document 1 — Advertisement","en":"For a complete list of class fees and schedules, visit our Web site at www.traintoachieve.org.ng. The following are some of our most popular classes.","vi":"Để xem danh sách đầy đủ về học phí và lịch học, vui lòng truy cập trang web của chúng tôi tại www.traintoachieve.org.ng. Dưới đây là một số lớp học được ưa chuộng nhất của chúng tôi.","units":[{"en":"For a complete list of class fees and schedules, visit our Web site at www.traintoachieve.org.ng.","vi":"Để xem danh sách đầy đủ về học phí và lịch học, vui lòng truy cập trang web của chúng tôi tại www.traintoachieve.org.ng."},{"en":"The following are some of our most popular classes.","vi":"Dưới đây là một số lớp học được ưa chuộng nhất của chúng tôi."}]},{"speaker":"Document 1 — Advertisement","en":"Introduction to Social Media Marketing (TTA1504): Taught by marketing consultant Marcus Akpan, the class equips you with the know-how to promote your business online.","vi":"Nhập môn Tiếp thị Mạng xã hội (TTA1504): Do chuyên gia tư vấn tiếp thị Marcus Akpan giảng dạy, lớp học trang bị cho bạn bí quyết để quảng bá doanh nghiệp trực tuyến.","units":[{"en":"Introduction to Social Media Marketing (TTA1504): Taught by marketing consultant Marcus Akpan, the class equips you with the know-how to promote your business online.","vi":"Nhập môn Tiếp thị Mạng xã hội (TTA1504): Do chuyên gia tư vấn tiếp thị Marcus Akpan giảng dạy, lớp học trang bị cho bạn bí quyết để quảng bá doanh nghiệp trực tuyến."}]},{"speaker":"Document 1 — Advertisement","en":"Become a Successful Freelance Writer (TTA3283): Business writer Brenda Akande gives you expert guidance on how to hone your writing skills and sell your writing services.","vi":"Trở thành Cây viết Tự do Thành công (TTA3283): Tác giả chuyên mảng kinh doanh Brenda Akande sẽ hướng dẫn chuyên sâu cách mài giũa kỹ năng viết và chào bán dịch vụ viết lách của bạn.","units":[{"en":"Become a Successful Freelance Writer (TTA3283): Business writer Brenda Akande gives you expert guidance on how to hone your writing skills and sell your writing services.","vi":"Trở thành Cây viết Tự do Thành công (TTA3283): Tác giả chuyên mảng kinh doanh Brenda Akande sẽ hướng dẫn chuyên sâu cách mài giũa kỹ năng viết và chào bán dịch vụ viết lách của bạn."}]},{"speaker":"Document 1 — Advertisement","en":"Starting an Internet Radio Station (TTA7629): Online radio host Natalie Kabiru shows you how to appeal to your target market and gives practical tips for setting up your broadcast service.","vi":"Khởi tạo Đài Phát thanh Trực tuyến (TTA7629): Người dẫn chương trình phát thanh trực tuyến Natalie Kabiru sẽ chỉ cho bạn cách thu hút thị trường mục tiêu và chia sẻ những mẹo thực tế để thiết lập dịch vụ phát sóng.","units":[{"en":"Starting an Internet Radio Station (TTA7629): Online radio host Natalie Kabiru shows you how to appeal to your target market and gives practical tips for setting up your broadcast service.","vi":"Khởi tạo Đài Phát thanh Trực tuyến (TTA7629): Người dẫn chương trình phát thanh trực tuyến Natalie Kabiru sẽ chỉ cho bạn cách thu hút thị trường mục tiêu và chia sẻ những mẹo thực tế để thiết lập dịch vụ phát sóng."}]},{"speaker":"Document 1 — Advertisement","en":"Basics of Graphic Design (TTA7633): Veteran graphic designer Doug Umaru helps you acquire the basic skills needed to start a graphic design business.","vi":"Kiến thức Cơ bản về Thiết kế Đồ họa (TTA7633): Nhà thiết kế đồ họa kỳ cựu Doug Umaru giúp bạn nắm vững các kỹ năng nền tảng cần thiết để khởi nghiệp kinh doanh thiết kế đồ họa.","units":[{"en":"Basics of Graphic Design (TTA7633): Veteran graphic designer Doug Umaru helps you acquire the basic skills needed to start a graphic design business.","vi":"Kiến thức Cơ bản về Thiết kế Đồ họa (TTA7633): Nhà thiết kế đồ họa kỳ cựu Doug Umaru giúp bạn nắm vững các kỹ năng nền tảng cần thiết để khởi nghiệp kinh doanh thiết kế đồ họa."}]},{"speaker":"Document 2 — Discussion Forum","en":"Discussion forum for students enrolled in Train to Achieve Class TTA1504","vi":"Diễn đàn thảo luận dành cho học viên đăng ký lớp TTA1504 của Train to Achieve","units":[{"en":"Discussion forum for students enrolled in Train to Achieve Class TTA1504","vi":"Diễn đàn thảo luận dành cho học viên đăng ký lớp TTA1504 của Train to Achieve"}]},{"speaker":"Document 2 — Discussion Forum","en":"Posted on: 21 May, 9:41 A.M. | Posted by: Joseph Egbe | Subject: Presentations","vi":"Đăng lúc: 21 tháng 5, 9:41 sáng | Người đăng: Joseph Egbe | Chủ đề: Bài thuyết trình","units":[{"en":"Posted on: 21 May, 9:41 A.M. | Posted by: Joseph Egbe | Subject: Presentations","vi":"Đăng lúc: 21 tháng 5, 9:41 sáng | Người đăng: Joseph Egbe | Chủ đề: Bài thuyết trình"}]},{"speaker":"Document 2 — Discussion Forum","en":"Viewing the list of students enrolled in this class, I remembered chatting with some of you on the forum for January's poster design class. I look forward to sharing our learning experiences again for this class. Yesterday I was the second student to meet with Mr. Akpan for an individual videoconference about my business. I own a food truck from which I sell baked goods, and when I shared with Mr. Akpan the outline for my Web site, he suggested that I add a section with vivid images of all my baked goods. It was helpful advice.","vi":"Khi xem danh sách học viên đăng ký lớp này, tôi nhớ lại lần từng trò chuyện với một vài bạn trên diễn đàn của lớp thiết kế áp phích hồi tháng 1. Tôi rất mong được tiếp tục chia sẻ kinh nghiệm học tập cùng mọi người trong khóa học này. Hôm qua, tôi là học viên thứ hai có buổi họp trực tuyến riêng với thầy Akpan để trao đổi về công việc kinh doanh của mình. Tôi sở hữu một xe tải bán đồ ăn chuyên các món bánh nướng, và khi tôi chia sẻ dàn ý trang web với thầy Akpan, thầy gợi ý tôi nên bổ sung thêm một mục có hình ảnh sinh động về tất cả các loại bánh của mình. Đó thực sự là một lời khuyên hữu ích.","units":[{"en":"Viewing the list of students enrolled in this class, I remembered chatting with some of you on the forum for January's poster design class.","vi":"Khi xem danh sách học viên đăng ký lớp này, tôi nhớ lại lần từng trò chuyện với một vài bạn trên diễn đàn của lớp thiết kế áp phích hồi tháng 1."},{"en":"I look forward to sharing our learning experiences again for this class.","vi":"Tôi rất mong được tiếp tục chia sẻ kinh nghiệm học tập cùng mọi người trong khóa học này."},{"en":"Yesterday I was the second student to meet with Mr. Akpan for an individual videoconference about my business.","vi":"Hôm qua, tôi là học viên thứ hai có buổi họp trực tuyến riêng với thầy Akpan để trao đổi về công việc kinh doanh của mình."},{"en":"I own a food truck from which I sell baked goods, and when I shared with Mr. Akpan the outline for my Web site, he suggested that I add a section with vivid images of all my baked goods.","vi":"Tôi sở hữu một xe tải bán đồ ăn chuyên các món bánh nướng, và khi tôi chia sẻ dàn ý trang web với thầy Akpan, thầy gợi ý tôi nên bổ sung thêm một mục có hình ảnh sinh động về tất cả các loại bánh của mình."},{"en":"It was helpful advice.","vi":"Đó thực sự là một lời khuyên hữu ích."}]},{"speaker":"Document 3 — Outline","en":"Egbe's Bakery—Unique baked-in flavours in every bite!","vi":"Egbe's Bakery — Hương vị nướng độc đáo đậm đà trong từng miếng bánh!","units":[{"en":"Egbe's Bakery—Unique baked-in flavours in every bite!","vi":"Egbe's Bakery — Hương vị nướng độc đáo đậm đà trong từng miếng bánh!"}]},{"speaker":"Document 3 — Outline","en":"• Section 1: Explore our menu and price list","vi":"• Mục 1: Khám phá thực đơn và bảng giá của chúng tôi","units":[{"en":"• Section 1: Explore our menu and price list","vi":"• Mục 1: Khám phá thực đơn và bảng giá của chúng tôi"}]},{"speaker":"Document 3 — Outline","en":"• Section 2: Browse photos of our delicious treats","vi":"• Mục 2: Xem hình ảnh những món bánh thơm ngon của chúng tôi","units":[{"en":"• Section 2: Browse photos of our delicious treats","vi":"• Mục 2: Xem hình ảnh những món bánh thơm ngon của chúng tôi"}]},{"speaker":"Document 3 — Outline","en":"• Section 3: Learn about our catering services","vi":"• Mục 3: Tìm hiểu về dịch vụ đặt tiệc của chúng tôi","units":[{"en":"• Section 3: Learn about our catering services","vi":"• Mục 3: Tìm hiểu về dịch vụ đặt tiệc của chúng tôi"}]},{"speaker":"Document 3 — Outline","en":"• Section 4: View lists of ingredients","vi":"• Mục 4: Xem danh sách nguyên liệu","units":[{"en":"• Section 4: View lists of ingredients","vi":"• Mục 4: Xem danh sách nguyên liệu"}]}],"vocab":[{"word":"individualized","pos":"adj","ipa":"/ˌɪndɪˈvɪdʒuəlaɪzd/","meaning":"được cá nhân hóa"},{"word":"respective","pos":"adj","ipa":"/rɪˈspektɪv/","meaning":"tương ứng, riêng từng (lĩnh vực)"},{"word":"innovative","pos":"adj","ipa":"/ˈɪnəveɪtɪv/","meaning":"đổi mới, sáng tạo"},{"word":"profile","pos":"v","ipa":"/ˈproʊfaɪl/","meaning":"giới thiệu, khắc họa tiểu sử"}],"isScanBacked":false,"docTypeLabel":"advertisement, discussion forum post, and outline","context":"Advertisement, discussion forum post, and Web site outline — Train to Achieve (TTA) & Egbe's Bakery","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 — ĐỌC HIỂU CHI TIẾT & PARAPHRASE (QUẢNG CÁO): Quét từ khóa chủ thể 'TTA' ở phần giới thiệu chung -> Đối chiếu cụm 'taught by recognized professionals in their respective fields' với phương án paraphrase 'led by industry professionals'.","optionAnalysis":{"A":"Sai vì Document 1 chỉ giới thiệu Doug Umaru là nhà thiết kế đồ họa kỳ cựu dạy lớp TTA7633, không hề nói ông là nhà sáng lập TTA.","B":"Sai vì TTA được đưa tin trên bản tin Business Directions Nigeria ('Profiled in the latest Business Directions Nigeria newsletter'), chứ không phải TTA tự xuất bản bản tin.","C":"Đúng vì Document 1 nêu rõ mọi lớp học đều được giảng dạy bởi các chuyên gia được công nhận trong từng lĩnh vực ('taught by recognized professionals in their respective fields').","D":"Sai vì trái ngược với Document 1: TTA dạy hoàn toàn trực tuyến ('entirely in online format, we bring the classroom to your home'), không có phòng học vật lý."},"evDocIdx":0,"evTargets":[{"badge":"Câu 186 · Đáp án C","opt":"C","isCorrect":true,"quote":"All classes include individualized instruction and are taught by recognized professionals in their respective fields.","viQuote":"Mọi lớp học đều có phần hướng dẫn cá nhân hóa và do các chuyên gia uy tín trong từng lĩnh vực trực tiếp giảng dạy."}],"evQuotes":["All classes include individualized instruction and are taught by recognized professionals in their respective fields."]},{"q":187,"part":7,"group_id":"E25_T01_G186_190","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc23.webp","web_assets/ets2025/p67/E25_T01_rc24.webp"],"stem_en":"According to the advertisement, what does TTA provide to students who finish a class?","stem_vi":"Theo quảng cáo, TTA cung cấp gì cho học viên hoàn thành một khóa học?","options":{"A":{"en":"A resume-writing workshop","vi":"Một buổi hội thảo viết sơ yếu lý lịch"},"B":{"en":"A discount on a follow-up class","vi":"Một khoản giảm giá cho khóa học tiếp theo"},"C":{"en":"A list of current job postings","vi":"Danh sách các tin tuyển dụng hiện có"},"D":{"en":"A certification document","vi":"Một văn bằng chứng nhận"}},"ans":"D","evidence_quote":"Upon successful completion of a class, you will receive an official Certificate of Training, a valuable addition to any resume.","explanation":"Đáp án đúng: (D) Một văn bằng chứng nhận — Theo quảng cáo, học viên hoàn thành tốt một lớp học sẽ được cấp Chứng chỉ Đào tạo chính thức.\nDẫn chứng: \"Upon successful completion of a class, you will receive an official Certificate of Training, a valuable addition to any résumé.\" (Document 1 — Advertisement: 'finish a class' = 'completion of a class'; 'Certificate of Training' = 'certification document').\nPhân tích bẫy:\n- (A) Bẫy ghép từ khóa 'résumé': Quảng cáo chỉ nói chứng chỉ là điểm cộng cho hồ sơ xin việc ('addition to any résumé'), không có hội thảo hướng dẫn viết sơ yếu lý lịch.\n- (B) Bẫy tự suy diễn ưu đãi: Quảng cáo chỉ dẫn đường link xem học phí và lịch học ('class fees and schedules'), không nhắc đến mã giảm giá cho khóa sau.\n- (C) Bẫy sai mục đích dịch vụ: TTA cung cấp khóa học kỹ năng kinh doanh và nghề tự do, không cung cấp danh sách tin tuyển dụng việc làm.","lines":[{"speaker":"Document 1 — Advertisement","en":"Train to Achieve (TTA)—Our classes prepare you to succeed!","vi":"Train to Achieve (TTA) — Các lớp học của chúng tôi trang bị hành trang để bạn thành công!","units":[{"en":"Train to Achieve (TTA)—Our classes prepare you to succeed!","vi":"Train to Achieve (TTA) — Các lớp học của chúng tôi trang bị hành trang để bạn thành công!"}]},{"speaker":"Document 1 — Advertisement","en":"Profiled in the latest Business Directions Nigeria newsletter, Train to Achieve (TTA) is one of the most innovative training providers in West Africa. By offering our classes entirely in online format, we bring the classroom to your home.","vi":"Được giới thiệu trên số mới nhất của bản tin Business Directions Nigeria, Train to Achieve (TTA) là một trong những đơn vị đào tạo đổi mới sáng tạo hàng đầu tại Tây Phi. Bằng việc tổ chức toàn bộ các lớp học theo hình thức trực tuyến, chúng tôi mang lớp học đến ngay tại nhà bạn.","units":[{"en":"Profiled in the latest Business Directions Nigeria newsletter, Train to Achieve (TTA) is one of the most innovative training providers in West Africa.","vi":"Được giới thiệu trên số mới nhất của bản tin Business Directions Nigeria, Train to Achieve (TTA) là một trong những đơn vị đào tạo đổi mới sáng tạo hàng đầu tại Tây Phi."},{"en":"By offering our classes entirely in online format, we bring the classroom to your home.","vi":"Bằng việc tổ chức toàn bộ các lớp học theo hình thức trực tuyến, chúng tôi mang lớp học đến ngay tại nhà bạn."}]},{"speaker":"Document 1 — Advertisement","en":"All classes include individualized instruction and are taught by recognized professionals in their respective fields. Upon successful completion of a class, you will receive an official Certificate of Training, a valuable addition to any résumé.","vi":"Mọi lớp học đều có phần hướng dẫn cá nhân hóa và do các chuyên gia uy tín trong từng lĩnh vực trực tiếp giảng dạy. Khi hoàn thành tốt khóa học, bạn sẽ nhận được Chứng chỉ Đào tạo chính thức — một điểm cộng giá trị cho bất kỳ hồ sơ xin việc nào.","units":[{"en":"All classes include individualized instruction and are taught by recognized professionals in their respective fields.","vi":"Mọi lớp học đều có phần hướng dẫn cá nhân hóa và do các chuyên gia uy tín trong từng lĩnh vực trực tiếp giảng dạy."},{"en":"Upon successful completion of a class, you will receive an official Certificate of Training, a valuable addition to any résumé.","vi":"Khi hoàn thành tốt khóa học, bạn sẽ nhận được Chứng chỉ Đào tạo chính thức — một điểm cộng giá trị cho bất kỳ hồ sơ xin việc nào."}]},{"speaker":"Document 1 — Advertisement","en":"For a complete list of class fees and schedules, visit our Web site at www.traintoachieve.org.ng. The following are some of our most popular classes.","vi":"Để xem danh sách đầy đủ về học phí và lịch học, vui lòng truy cập trang web của chúng tôi tại www.traintoachieve.org.ng. Dưới đây là một số lớp học được ưa chuộng nhất của chúng tôi.","units":[{"en":"For a complete list of class fees and schedules, visit our Web site at www.traintoachieve.org.ng.","vi":"Để xem danh sách đầy đủ về học phí và lịch học, vui lòng truy cập trang web của chúng tôi tại www.traintoachieve.org.ng."},{"en":"The following are some of our most popular classes.","vi":"Dưới đây là một số lớp học được ưa chuộng nhất của chúng tôi."}]},{"speaker":"Document 1 — Advertisement","en":"Introduction to Social Media Marketing (TTA1504): Taught by marketing consultant Marcus Akpan, the class equips you with the know-how to promote your business online.","vi":"Nhập môn Tiếp thị Mạng xã hội (TTA1504): Do chuyên gia tư vấn tiếp thị Marcus Akpan giảng dạy, lớp học trang bị cho bạn bí quyết để quảng bá doanh nghiệp trực tuyến.","units":[{"en":"Introduction to Social Media Marketing (TTA1504): Taught by marketing consultant Marcus Akpan, the class equips you with the know-how to promote your business online.","vi":"Nhập môn Tiếp thị Mạng xã hội (TTA1504): Do chuyên gia tư vấn tiếp thị Marcus Akpan giảng dạy, lớp học trang bị cho bạn bí quyết để quảng bá doanh nghiệp trực tuyến."}]},{"speaker":"Document 1 — Advertisement","en":"Become a Successful Freelance Writer (TTA3283): Business writer Brenda Akande gives you expert guidance on how to hone your writing skills and sell your writing services.","vi":"Trở thành Cây viết Tự do Thành công (TTA3283): Tác giả chuyên mảng kinh doanh Brenda Akande sẽ hướng dẫn chuyên sâu cách mài giũa kỹ năng viết và chào bán dịch vụ viết lách của bạn.","units":[{"en":"Become a Successful Freelance Writer (TTA3283): Business writer Brenda Akande gives you expert guidance on how to hone your writing skills and sell your writing services.","vi":"Trở thành Cây viết Tự do Thành công (TTA3283): Tác giả chuyên mảng kinh doanh Brenda Akande sẽ hướng dẫn chuyên sâu cách mài giũa kỹ năng viết và chào bán dịch vụ viết lách của bạn."}]},{"speaker":"Document 1 — Advertisement","en":"Starting an Internet Radio Station (TTA7629): Online radio host Natalie Kabiru shows you how to appeal to your target market and gives practical tips for setting up your broadcast service.","vi":"Khởi tạo Đài Phát thanh Trực tuyến (TTA7629): Người dẫn chương trình phát thanh trực tuyến Natalie Kabiru sẽ chỉ cho bạn cách thu hút thị trường mục tiêu và chia sẻ những mẹo thực tế để thiết lập dịch vụ phát sóng.","units":[{"en":"Starting an Internet Radio Station (TTA7629): Online radio host Natalie Kabiru shows you how to appeal to your target market and gives practical tips for setting up your broadcast service.","vi":"Khởi tạo Đài Phát thanh Trực tuyến (TTA7629): Người dẫn chương trình phát thanh trực tuyến Natalie Kabiru sẽ chỉ cho bạn cách thu hút thị trường mục tiêu và chia sẻ những mẹo thực tế để thiết lập dịch vụ phát sóng."}]},{"speaker":"Document 1 — Advertisement","en":"Basics of Graphic Design (TTA7633): Veteran graphic designer Doug Umaru helps you acquire the basic skills needed to start a graphic design business.","vi":"Kiến thức Cơ bản về Thiết kế Đồ họa (TTA7633): Nhà thiết kế đồ họa kỳ cựu Doug Umaru giúp bạn nắm vững các kỹ năng nền tảng cần thiết để khởi nghiệp kinh doanh thiết kế đồ họa.","units":[{"en":"Basics of Graphic Design (TTA7633): Veteran graphic designer Doug Umaru helps you acquire the basic skills needed to start a graphic design business.","vi":"Kiến thức Cơ bản về Thiết kế Đồ họa (TTA7633): Nhà thiết kế đồ họa kỳ cựu Doug Umaru giúp bạn nắm vững các kỹ năng nền tảng cần thiết để khởi nghiệp kinh doanh thiết kế đồ họa."}]},{"speaker":"Document 2 — Discussion Forum","en":"Discussion forum for students enrolled in Train to Achieve Class TTA1504","vi":"Diễn đàn thảo luận dành cho học viên đăng ký lớp TTA1504 của Train to Achieve","units":[{"en":"Discussion forum for students enrolled in Train to Achieve Class TTA1504","vi":"Diễn đàn thảo luận dành cho học viên đăng ký lớp TTA1504 của Train to Achieve"}]},{"speaker":"Document 2 — Discussion Forum","en":"Posted on: 21 May, 9:41 A.M. | Posted by: Joseph Egbe | Subject: Presentations","vi":"Đăng lúc: 21 tháng 5, 9:41 sáng | Người đăng: Joseph Egbe | Chủ đề: Bài thuyết trình","units":[{"en":"Posted on: 21 May, 9:41 A.M. | Posted by: Joseph Egbe | Subject: Presentations","vi":"Đăng lúc: 21 tháng 5, 9:41 sáng | Người đăng: Joseph Egbe | Chủ đề: Bài thuyết trình"}]},{"speaker":"Document 2 — Discussion Forum","en":"Viewing the list of students enrolled in this class, I remembered chatting with some of you on the forum for January's poster design class. I look forward to sharing our learning experiences again for this class. Yesterday I was the second student to meet with Mr. Akpan for an individual videoconference about my business. I own a food truck from which I sell baked goods, and when I shared with Mr. Akpan the outline for my Web site, he suggested that I add a section with vivid images of all my baked goods. It was helpful advice.","vi":"Khi xem danh sách học viên đăng ký lớp này, tôi nhớ lại lần từng trò chuyện với một vài bạn trên diễn đàn của lớp thiết kế áp phích hồi tháng 1. Tôi rất mong được tiếp tục chia sẻ kinh nghiệm học tập cùng mọi người trong khóa học này. Hôm qua, tôi là học viên thứ hai có buổi họp trực tuyến riêng với thầy Akpan để trao đổi về công việc kinh doanh của mình. Tôi sở hữu một xe tải bán đồ ăn chuyên các món bánh nướng, và khi tôi chia sẻ dàn ý trang web với thầy Akpan, thầy gợi ý tôi nên bổ sung thêm một mục có hình ảnh sinh động về tất cả các loại bánh của mình. Đó thực sự là một lời khuyên hữu ích.","units":[{"en":"Viewing the list of students enrolled in this class, I remembered chatting with some of you on the forum for January's poster design class.","vi":"Khi xem danh sách học viên đăng ký lớp này, tôi nhớ lại lần từng trò chuyện với một vài bạn trên diễn đàn của lớp thiết kế áp phích hồi tháng 1."},{"en":"I look forward to sharing our learning experiences again for this class.","vi":"Tôi rất mong được tiếp tục chia sẻ kinh nghiệm học tập cùng mọi người trong khóa học này."},{"en":"Yesterday I was the second student to meet with Mr. Akpan for an individual videoconference about my business.","vi":"Hôm qua, tôi là học viên thứ hai có buổi họp trực tuyến riêng với thầy Akpan để trao đổi về công việc kinh doanh của mình."},{"en":"I own a food truck from which I sell baked goods, and when I shared with Mr. Akpan the outline for my Web site, he suggested that I add a section with vivid images of all my baked goods.","vi":"Tôi sở hữu một xe tải bán đồ ăn chuyên các món bánh nướng, và khi tôi chia sẻ dàn ý trang web với thầy Akpan, thầy gợi ý tôi nên bổ sung thêm một mục có hình ảnh sinh động về tất cả các loại bánh của mình."},{"en":"It was helpful advice.","vi":"Đó thực sự là một lời khuyên hữu ích."}]},{"speaker":"Document 3 — Outline","en":"Egbe's Bakery—Unique baked-in flavours in every bite!","vi":"Egbe's Bakery — Hương vị nướng độc đáo đậm đà trong từng miếng bánh!","units":[{"en":"Egbe's Bakery—Unique baked-in flavours in every bite!","vi":"Egbe's Bakery — Hương vị nướng độc đáo đậm đà trong từng miếng bánh!"}]},{"speaker":"Document 3 — Outline","en":"• Section 1: Explore our menu and price list","vi":"• Mục 1: Khám phá thực đơn và bảng giá của chúng tôi","units":[{"en":"• Section 1: Explore our menu and price list","vi":"• Mục 1: Khám phá thực đơn và bảng giá của chúng tôi"}]},{"speaker":"Document 3 — Outline","en":"• Section 2: Browse photos of our delicious treats","vi":"• Mục 2: Xem hình ảnh những món bánh thơm ngon của chúng tôi","units":[{"en":"• Section 2: Browse photos of our delicious treats","vi":"• Mục 2: Xem hình ảnh những món bánh thơm ngon của chúng tôi"}]},{"speaker":"Document 3 — Outline","en":"• Section 3: Learn about our catering services","vi":"• Mục 3: Tìm hiểu về dịch vụ đặt tiệc của chúng tôi","units":[{"en":"• Section 3: Learn about our catering services","vi":"• Mục 3: Tìm hiểu về dịch vụ đặt tiệc của chúng tôi"}]},{"speaker":"Document 3 — Outline","en":"• Section 4: View lists of ingredients","vi":"• Mục 4: Xem danh sách nguyên liệu","units":[{"en":"• Section 4: View lists of ingredients","vi":"• Mục 4: Xem danh sách nguyên liệu"}]}],"vocab":[{"word":"completion","pos":"n","ipa":"/kəmˈpliːʃən/","meaning":"sự hoàn thành"},{"word":"certificate","pos":"n","ipa":"/sərˈtɪfɪkət/","meaning":"chứng chỉ, văn bằng chứng nhận"},{"word":"résumé","pos":"n","ipa":"/ˈrezəmeɪ/","meaning":"sơ yếu lý lịch, hồ sơ xin việc"},{"word":"upon","pos":"prep","ipa":"/əˈpɑːn/","meaning":"ngay sau khi"}],"isScanBacked":false,"docTypeLabel":"advertisement, discussion forum post, and outline","context":"Advertisement, discussion forum post, and Web site outline — Train to Achieve (TTA) & Egbe's Bakery","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 — TÌM CHI TIẾT QUYỀN LỢI / ĐIỀU KIỆN (QUẢNG CÁO): Định vị mốc điều kiện 'students who finish a class' -> Tìm cụm tương đương 'Upon successful completion of a class' -> Ánh xạ 'Certificate of Training' sang 'certification document'.","optionAnalysis":{"A":"Sai vì dính bẫy từ khóa 'résumé': văn bản chỉ nói chứng chỉ làm đẹp thêm sơ yếu lý lịch, không hề tổ chức hội thảo viết CV.","B":"Sai vì Document 1 chỉ đề cập đường link xem bảng học phí và lịch học, hoàn toàn không có chính sách giảm giá cho lớp tiếp theo.","C":"Sai vì TTA đào tạo kỹ năng để học viên phát triển kinh doanh hoặc tự làm việc, không cung cấp danh sách tin tuyển dụng.","D":"Đúng vì Document 1 ghi rõ khi hoàn thành lớp học ('completion of a class'), học viên nhận được 'official Certificate of Training' (tương đương 'certification document')."},"evDocIdx":0,"evTargets":[{"badge":"Câu 187 · Đáp án D","opt":"D","isCorrect":true,"quote":"Upon successful completion of a class, you will receive an official Certificate of Training, a valuable addition to any résumé.","viQuote":"Khi hoàn thành tốt khóa học, bạn sẽ nhận được Chứng chỉ Đào tạo chính thức — một điểm cộng giá trị cho bất kỳ hồ sơ xin việc nào."}],"evQuotes":["Upon successful completion of a class, you will receive an official Certificate of Training, a valuable addition to any résumé."]},{"q":188,"part":7,"group_id":"E25_T01_G186_190","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc23.webp","web_assets/ets2025/p67/E25_T01_rc24.webp"],"stem_en":"What is most likely true about Mr. Egbe?","stem_vi":"Điều gì có khả năng đúng nhất về ông Egbe?","options":{"A":{"en":"He helped design a discussion forum.","vi":"Ông ấy đã hỗ trợ thiết kế một diễn đàn thảo luận."},"B":{"en":"He has previously taken a TTA class.","vi":"Trước đây ông ấy từng tham gia một lớp học của TTA."},"C":{"en":"He develops videoconferencing software.","vi":"Ông ấy phát triển phần mềm hội nghị truyền hình."},"D":{"en":"He recently sold a bakery food truck.","vi":"Gần đây ông ấy đã bán một xe tải bán đồ ăn chuyên các món bánh nướng."}},"ans":"B","evidence_quote":"Viewing the list of students enrolled in this class, I remembered chatting with some of you on the forum for January's poster design class. I look forward to sharing our learning experiences again for this class.","explanation":"Đáp án đúng: (B) Trước đây ông ấy từng tham gia một lớp học của TTA — Ông Egbe nhớ lại việc từng trò chuyện với vài bạn học trên diễn đàn lớp thiết kế áp phích hồi tháng 1 và mong lại được chia sẻ kinh nghiệm học tập trong khóa này.\nDẫn chứng: \"Viewing the list of students enrolled in this class, I remembered chatting with some of you on the forum for January's poster design class. I look forward to sharing our learning experiences again for this class.\" (Document 2 — Discussion Forum: 'January's poster design class' + 'again for this class' chứng minh ông từng học lớp trước đó).\nPhân tích bẫy:\n- (A) Bẫy đánh tráo hành động: Ông Egbe chỉ là thành viên đăng bài và trò chuyện trên diễn đàn ('chatting with some of you on the forum'), không phải người thiết kế diễn đàn.\n- (C) Bẫy từ khóa 'videoconference': Ông Egbe chỉ họp trực tuyến 1-1 với thầy Akpan ('meet with Mr. Akpan for an individual videoconference'), không phải người lập trình phần mềm.\n- (D) Bẫy hiểu sai nghĩa cụm từ: Ông ấy viết 'I own a food truck from which I sell baked goods' (sở hữu xe bán bánh nướng), chứ không phải bán chiếc xe tải đó.","lines":[{"speaker":"Document 1 — Advertisement","en":"Train to Achieve (TTA)—Our classes prepare you to succeed!","vi":"Train to Achieve (TTA) — Các lớp học của chúng tôi trang bị hành trang để bạn thành công!","units":[{"en":"Train to Achieve (TTA)—Our classes prepare you to succeed!","vi":"Train to Achieve (TTA) — Các lớp học của chúng tôi trang bị hành trang để bạn thành công!"}]},{"speaker":"Document 1 — Advertisement","en":"Profiled in the latest Business Directions Nigeria newsletter, Train to Achieve (TTA) is one of the most innovative training providers in West Africa. By offering our classes entirely in online format, we bring the classroom to your home.","vi":"Được giới thiệu trên số mới nhất của bản tin Business Directions Nigeria, Train to Achieve (TTA) là một trong những đơn vị đào tạo đổi mới sáng tạo hàng đầu tại Tây Phi. Bằng việc tổ chức toàn bộ các lớp học theo hình thức trực tuyến, chúng tôi mang lớp học đến ngay tại nhà bạn.","units":[{"en":"Profiled in the latest Business Directions Nigeria newsletter, Train to Achieve (TTA) is one of the most innovative training providers in West Africa.","vi":"Được giới thiệu trên số mới nhất của bản tin Business Directions Nigeria, Train to Achieve (TTA) là một trong những đơn vị đào tạo đổi mới sáng tạo hàng đầu tại Tây Phi."},{"en":"By offering our classes entirely in online format, we bring the classroom to your home.","vi":"Bằng việc tổ chức toàn bộ các lớp học theo hình thức trực tuyến, chúng tôi mang lớp học đến ngay tại nhà bạn."}]},{"speaker":"Document 1 — Advertisement","en":"All classes include individualized instruction and are taught by recognized professionals in their respective fields. Upon successful completion of a class, you will receive an official Certificate of Training, a valuable addition to any résumé.","vi":"Mọi lớp học đều có phần hướng dẫn cá nhân hóa và do các chuyên gia uy tín trong từng lĩnh vực trực tiếp giảng dạy. Khi hoàn thành tốt khóa học, bạn sẽ nhận được Chứng chỉ Đào tạo chính thức — một điểm cộng giá trị cho bất kỳ hồ sơ xin việc nào.","units":[{"en":"All classes include individualized instruction and are taught by recognized professionals in their respective fields.","vi":"Mọi lớp học đều có phần hướng dẫn cá nhân hóa và do các chuyên gia uy tín trong từng lĩnh vực trực tiếp giảng dạy."},{"en":"Upon successful completion of a class, you will receive an official Certificate of Training, a valuable addition to any résumé.","vi":"Khi hoàn thành tốt khóa học, bạn sẽ nhận được Chứng chỉ Đào tạo chính thức — một điểm cộng giá trị cho bất kỳ hồ sơ xin việc nào."}]},{"speaker":"Document 1 — Advertisement","en":"For a complete list of class fees and schedules, visit our Web site at www.traintoachieve.org.ng. The following are some of our most popular classes.","vi":"Để xem danh sách đầy đủ về học phí và lịch học, vui lòng truy cập trang web của chúng tôi tại www.traintoachieve.org.ng. Dưới đây là một số lớp học được ưa chuộng nhất của chúng tôi.","units":[{"en":"For a complete list of class fees and schedules, visit our Web site at www.traintoachieve.org.ng.","vi":"Để xem danh sách đầy đủ về học phí và lịch học, vui lòng truy cập trang web của chúng tôi tại www.traintoachieve.org.ng."},{"en":"The following are some of our most popular classes.","vi":"Dưới đây là một số lớp học được ưa chuộng nhất của chúng tôi."}]},{"speaker":"Document 1 — Advertisement","en":"Introduction to Social Media Marketing (TTA1504): Taught by marketing consultant Marcus Akpan, the class equips you with the know-how to promote your business online.","vi":"Nhập môn Tiếp thị Mạng xã hội (TTA1504): Do chuyên gia tư vấn tiếp thị Marcus Akpan giảng dạy, lớp học trang bị cho bạn bí quyết để quảng bá doanh nghiệp trực tuyến.","units":[{"en":"Introduction to Social Media Marketing (TTA1504): Taught by marketing consultant Marcus Akpan, the class equips you with the know-how to promote your business online.","vi":"Nhập môn Tiếp thị Mạng xã hội (TTA1504): Do chuyên gia tư vấn tiếp thị Marcus Akpan giảng dạy, lớp học trang bị cho bạn bí quyết để quảng bá doanh nghiệp trực tuyến."}]},{"speaker":"Document 1 — Advertisement","en":"Become a Successful Freelance Writer (TTA3283): Business writer Brenda Akande gives you expert guidance on how to hone your writing skills and sell your writing services.","vi":"Trở thành Cây viết Tự do Thành công (TTA3283): Tác giả chuyên mảng kinh doanh Brenda Akande sẽ hướng dẫn chuyên sâu cách mài giũa kỹ năng viết và chào bán dịch vụ viết lách của bạn.","units":[{"en":"Become a Successful Freelance Writer (TTA3283): Business writer Brenda Akande gives you expert guidance on how to hone your writing skills and sell your writing services.","vi":"Trở thành Cây viết Tự do Thành công (TTA3283): Tác giả chuyên mảng kinh doanh Brenda Akande sẽ hướng dẫn chuyên sâu cách mài giũa kỹ năng viết và chào bán dịch vụ viết lách của bạn."}]},{"speaker":"Document 1 — Advertisement","en":"Starting an Internet Radio Station (TTA7629): Online radio host Natalie Kabiru shows you how to appeal to your target market and gives practical tips for setting up your broadcast service.","vi":"Khởi tạo Đài Phát thanh Trực tuyến (TTA7629): Người dẫn chương trình phát thanh trực tuyến Natalie Kabiru sẽ chỉ cho bạn cách thu hút thị trường mục tiêu và chia sẻ những mẹo thực tế để thiết lập dịch vụ phát sóng.","units":[{"en":"Starting an Internet Radio Station (TTA7629): Online radio host Natalie Kabiru shows you how to appeal to your target market and gives practical tips for setting up your broadcast service.","vi":"Khởi tạo Đài Phát thanh Trực tuyến (TTA7629): Người dẫn chương trình phát thanh trực tuyến Natalie Kabiru sẽ chỉ cho bạn cách thu hút thị trường mục tiêu và chia sẻ những mẹo thực tế để thiết lập dịch vụ phát sóng."}]},{"speaker":"Document 1 — Advertisement","en":"Basics of Graphic Design (TTA7633): Veteran graphic designer Doug Umaru helps you acquire the basic skills needed to start a graphic design business.","vi":"Kiến thức Cơ bản về Thiết kế Đồ họa (TTA7633): Nhà thiết kế đồ họa kỳ cựu Doug Umaru giúp bạn nắm vững các kỹ năng nền tảng cần thiết để khởi nghiệp kinh doanh thiết kế đồ họa.","units":[{"en":"Basics of Graphic Design (TTA7633): Veteran graphic designer Doug Umaru helps you acquire the basic skills needed to start a graphic design business.","vi":"Kiến thức Cơ bản về Thiết kế Đồ họa (TTA7633): Nhà thiết kế đồ họa kỳ cựu Doug Umaru giúp bạn nắm vững các kỹ năng nền tảng cần thiết để khởi nghiệp kinh doanh thiết kế đồ họa."}]},{"speaker":"Document 2 — Discussion Forum","en":"Discussion forum for students enrolled in Train to Achieve Class TTA1504","vi":"Diễn đàn thảo luận dành cho học viên đăng ký lớp TTA1504 của Train to Achieve","units":[{"en":"Discussion forum for students enrolled in Train to Achieve Class TTA1504","vi":"Diễn đàn thảo luận dành cho học viên đăng ký lớp TTA1504 của Train to Achieve"}]},{"speaker":"Document 2 — Discussion Forum","en":"Posted on: 21 May, 9:41 A.M. | Posted by: Joseph Egbe | Subject: Presentations","vi":"Đăng lúc: 21 tháng 5, 9:41 sáng | Người đăng: Joseph Egbe | Chủ đề: Bài thuyết trình","units":[{"en":"Posted on: 21 May, 9:41 A.M. | Posted by: Joseph Egbe | Subject: Presentations","vi":"Đăng lúc: 21 tháng 5, 9:41 sáng | Người đăng: Joseph Egbe | Chủ đề: Bài thuyết trình"}]},{"speaker":"Document 2 — Discussion Forum","en":"Viewing the list of students enrolled in this class, I remembered chatting with some of you on the forum for January's poster design class. I look forward to sharing our learning experiences again for this class. Yesterday I was the second student to meet with Mr. Akpan for an individual videoconference about my business. I own a food truck from which I sell baked goods, and when I shared with Mr. Akpan the outline for my Web site, he suggested that I add a section with vivid images of all my baked goods. It was helpful advice.","vi":"Khi xem danh sách học viên đăng ký lớp này, tôi nhớ lại lần từng trò chuyện với một vài bạn trên diễn đàn của lớp thiết kế áp phích hồi tháng 1. Tôi rất mong được tiếp tục chia sẻ kinh nghiệm học tập cùng mọi người trong khóa học này. Hôm qua, tôi là học viên thứ hai có buổi họp trực tuyến riêng với thầy Akpan để trao đổi về công việc kinh doanh của mình. Tôi sở hữu một xe tải bán đồ ăn chuyên các món bánh nướng, và khi tôi chia sẻ dàn ý trang web với thầy Akpan, thầy gợi ý tôi nên bổ sung thêm một mục có hình ảnh sinh động về tất cả các loại bánh của mình. Đó thực sự là một lời khuyên hữu ích.","units":[{"en":"Viewing the list of students enrolled in this class, I remembered chatting with some of you on the forum for January's poster design class.","vi":"Khi xem danh sách học viên đăng ký lớp này, tôi nhớ lại lần từng trò chuyện với một vài bạn trên diễn đàn của lớp thiết kế áp phích hồi tháng 1."},{"en":"I look forward to sharing our learning experiences again for this class.","vi":"Tôi rất mong được tiếp tục chia sẻ kinh nghiệm học tập cùng mọi người trong khóa học này."},{"en":"Yesterday I was the second student to meet with Mr. Akpan for an individual videoconference about my business.","vi":"Hôm qua, tôi là học viên thứ hai có buổi họp trực tuyến riêng với thầy Akpan để trao đổi về công việc kinh doanh của mình."},{"en":"I own a food truck from which I sell baked goods, and when I shared with Mr. Akpan the outline for my Web site, he suggested that I add a section with vivid images of all my baked goods.","vi":"Tôi sở hữu một xe tải bán đồ ăn chuyên các món bánh nướng, và khi tôi chia sẻ dàn ý trang web với thầy Akpan, thầy gợi ý tôi nên bổ sung thêm một mục có hình ảnh sinh động về tất cả các loại bánh của mình."},{"en":"It was helpful advice.","vi":"Đó thực sự là một lời khuyên hữu ích."}]},{"speaker":"Document 3 — Outline","en":"Egbe's Bakery—Unique baked-in flavours in every bite!","vi":"Egbe's Bakery — Hương vị nướng độc đáo đậm đà trong từng miếng bánh!","units":[{"en":"Egbe's Bakery—Unique baked-in flavours in every bite!","vi":"Egbe's Bakery — Hương vị nướng độc đáo đậm đà trong từng miếng bánh!"}]},{"speaker":"Document 3 — Outline","en":"• Section 1: Explore our menu and price list","vi":"• Mục 1: Khám phá thực đơn và bảng giá của chúng tôi","units":[{"en":"• Section 1: Explore our menu and price list","vi":"• Mục 1: Khám phá thực đơn và bảng giá của chúng tôi"}]},{"speaker":"Document 3 — Outline","en":"• Section 2: Browse photos of our delicious treats","vi":"• Mục 2: Xem hình ảnh những món bánh thơm ngon của chúng tôi","units":[{"en":"• Section 2: Browse photos of our delicious treats","vi":"• Mục 2: Xem hình ảnh những món bánh thơm ngon của chúng tôi"}]},{"speaker":"Document 3 — Outline","en":"• Section 3: Learn about our catering services","vi":"• Mục 3: Tìm hiểu về dịch vụ đặt tiệc của chúng tôi","units":[{"en":"• Section 3: Learn about our catering services","vi":"• Mục 3: Tìm hiểu về dịch vụ đặt tiệc của chúng tôi"}]},{"speaker":"Document 3 — Outline","en":"• Section 4: View lists of ingredients","vi":"• Mục 4: Xem danh sách nguyên liệu","units":[{"en":"• Section 4: View lists of ingredients","vi":"• Mục 4: Xem danh sách nguyên liệu"}]}],"vocab":[{"word":"enroll","pos":"v","ipa":"/ɪnˈroʊl/","meaning":"đăng ký tham gia (khóa học)"},{"word":"forum","pos":"n","ipa":"/ˈfɔːrəm/","meaning":"diễn đàn thảo luận"},{"word":"videoconference","pos":"n","ipa":"/ˈvɪdioʊˌkɑːnfərəns/","meaning":"cuộc họp trực tuyến qua video"},{"word":"previously","pos":"adv","ipa":"/ˈpriːviəsli/","meaning":"trước đây, trước đó"}],"isScanBacked":false,"docTypeLabel":"advertisement, discussion forum post, and outline","context":"Advertisement, discussion forum post, and Web site outline — Train to Achieve (TTA) & Egbe's Bakery","grammarType":"Part 7 — Suy luận & Hàm ý văn bản (Inference & Implied Meaning)","formula":"CÔNG THỨC PART 7 — SUY LUẬN TỪ MỐC THỜI GIAN QUÁ KHỨ (DIỄN ĐÀN): Bắt dấu hiệu 'remembered chatting with some of you on the forum for January's poster design class' và 'again for this class' -> Suy ra học viên đã từng học một khóa trước đó.","optionAnalysis":{"A":"Sai vì ông Egbe chỉ tham gia trò chuyện và đăng bài trên diễn đàn lớp học, không hề thiết kế nền tảng diễn đàn.","B":"Đúng vì trong Document 2 ông Egbe nhớ lại từng trao đổi trên diễn đàn lớp thiết kế áp phích tháng 1 và mong chia sẻ kinh nghiệm lần nữa ('again for this class').","C":"Sai vì dính bẫy từ khóa 'videoconference': ông chỉ tham gia buổi họp trực tuyến riêng với giảng viên chứ không phát triển phần mềm.","D":"Sai vì hiểu nhầm cấu trúc câu: 'a food truck from which I sell baked goods' nghĩa là bán bánh từ xe tải mình sở hữu, không phải bán chiếc xe tải."},"evDocIdx":1,"evTargets":[{"badge":"Câu 188 · Đáp án B","opt":"B","isCorrect":true,"quote":"Viewing the list of students enrolled in this class, I remembered chatting with some of you on the forum for January's poster design class.","viQuote":"Khi xem danh sách học viên đăng ký lớp này, tôi nhớ lại lần từng trò chuyện với một vài bạn trên diễn đàn của lớp thiết kế áp phích hồi tháng 1."},{"badge":"Câu 188 · Đáp án B","opt":"B","isCorrect":true,"quote":"I look forward to sharing our learning experiences again for this class.","viQuote":"Tôi rất mong được tiếp tục chia sẻ kinh nghiệm học tập cùng mọi người trong khóa học này."}],"evQuotes":["Viewing the list of students enrolled in this class, I remembered chatting with some of you on the forum for January's poster design class.","I look forward to sharing our learning experiences again for this class."]},{"q":189,"part":7,"group_id":"E25_T01_G186_190","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc23.webp","web_assets/ets2025/p67/E25_T01_rc24.webp"],"stem_en":"What TTA class is Mr. Egbe enrolled in?","stem_vi":"Ông Egbe đang theo học lớp nào của TTA?","options":{"A":{"en":"Introduction to Social Media Marketing","vi":"Nhập môn Tiếp thị Mạng xã hội"},"B":{"en":"Become a Successful Freelance Writer","vi":"Trở thành Cây viết Tự do Thành công"},"C":{"en":"Starting an Internet Radio Station","vi":"Khởi tạo Đài Phát thanh Trực tuyến"},"D":{"en":"Basics of Graphic Design","vi":"Kiến thức Cơ bản về Thiết kế Đồ họa"}},"ans":"A","evidence_quote":"- In the posting: Yesterday I was the second student to meet with Mr. Akpan for an individual videoconference about my business. - In the advertisement: Introduction to Social Media Marketing (TTA1504): Taught by marketing consultant Marcus Akpan, the class equips you with the know- how to promote your business online.","explanation":"Đáp án đúng: (A) Nhập môn Tiếp thị Mạng xã hội (Introduction to Social Media Marketing) — Diễn đàn xác định lớp học mang mã TTA1504 với giảng viên là ông Akpan, khớp hoàn toàn với thông tin khóa học trong quảng cáo.\nDẫn chứng: Document 2 ghi \"Discussion forum for students enrolled in Train to Achieve Class TTA1504\" và \"meet with Mr. Akpan\"; đối chiếu Document 1 ghi \"Introduction to Social Media Marketing (TTA1504): Taught by marketing consultant Marcus Akpan\".\nPhân tích bẫy:\n- (B) Bẫy nhầm mã lớp: Lớp 'Become a Successful Freelance Writer' mang mã TTA3283 do Brenda Akande dạy, không phải mã TTA1504.\n- (C) Bẫy nhầm mã lớp: Lớp 'Starting an Internet Radio Station' mang mã TTA7629 do Natalie Kabiru dạy, không khớp giảng viên Marcus Akpan.\n- (D) Bẫy nhiễu thông tin cũ: Lớp 'Basics of Graphic Design' mang mã TTA7633 do Doug Umaru dạy; lớp thiết kế hồi tháng 1 ông Egbe nhắc tới chỉ là khóa cũ, không phải lớp đang học.","lines":[{"speaker":"Document 1 — Advertisement","en":"Train to Achieve (TTA)—Our classes prepare you to succeed!","vi":"Train to Achieve (TTA) — Các lớp học của chúng tôi trang bị hành trang để bạn thành công!","units":[{"en":"Train to Achieve (TTA)—Our classes prepare you to succeed!","vi":"Train to Achieve (TTA) — Các lớp học của chúng tôi trang bị hành trang để bạn thành công!"}]},{"speaker":"Document 1 — Advertisement","en":"Profiled in the latest Business Directions Nigeria newsletter, Train to Achieve (TTA) is one of the most innovative training providers in West Africa. By offering our classes entirely in online format, we bring the classroom to your home.","vi":"Được giới thiệu trên số mới nhất của bản tin Business Directions Nigeria, Train to Achieve (TTA) là một trong những đơn vị đào tạo đổi mới sáng tạo hàng đầu tại Tây Phi. Bằng việc tổ chức toàn bộ các lớp học theo hình thức trực tuyến, chúng tôi mang lớp học đến ngay tại nhà bạn.","units":[{"en":"Profiled in the latest Business Directions Nigeria newsletter, Train to Achieve (TTA) is one of the most innovative training providers in West Africa.","vi":"Được giới thiệu trên số mới nhất của bản tin Business Directions Nigeria, Train to Achieve (TTA) là một trong những đơn vị đào tạo đổi mới sáng tạo hàng đầu tại Tây Phi."},{"en":"By offering our classes entirely in online format, we bring the classroom to your home.","vi":"Bằng việc tổ chức toàn bộ các lớp học theo hình thức trực tuyến, chúng tôi mang lớp học đến ngay tại nhà bạn."}]},{"speaker":"Document 1 — Advertisement","en":"All classes include individualized instruction and are taught by recognized professionals in their respective fields. Upon successful completion of a class, you will receive an official Certificate of Training, a valuable addition to any résumé.","vi":"Mọi lớp học đều có phần hướng dẫn cá nhân hóa và do các chuyên gia uy tín trong từng lĩnh vực trực tiếp giảng dạy. Khi hoàn thành tốt khóa học, bạn sẽ nhận được Chứng chỉ Đào tạo chính thức — một điểm cộng giá trị cho bất kỳ hồ sơ xin việc nào.","units":[{"en":"All classes include individualized instruction and are taught by recognized professionals in their respective fields.","vi":"Mọi lớp học đều có phần hướng dẫn cá nhân hóa và do các chuyên gia uy tín trong từng lĩnh vực trực tiếp giảng dạy."},{"en":"Upon successful completion of a class, you will receive an official Certificate of Training, a valuable addition to any résumé.","vi":"Khi hoàn thành tốt khóa học, bạn sẽ nhận được Chứng chỉ Đào tạo chính thức — một điểm cộng giá trị cho bất kỳ hồ sơ xin việc nào."}]},{"speaker":"Document 1 — Advertisement","en":"For a complete list of class fees and schedules, visit our Web site at www.traintoachieve.org.ng. The following are some of our most popular classes.","vi":"Để xem danh sách đầy đủ về học phí và lịch học, vui lòng truy cập trang web của chúng tôi tại www.traintoachieve.org.ng. Dưới đây là một số lớp học được ưa chuộng nhất của chúng tôi.","units":[{"en":"For a complete list of class fees and schedules, visit our Web site at www.traintoachieve.org.ng.","vi":"Để xem danh sách đầy đủ về học phí và lịch học, vui lòng truy cập trang web của chúng tôi tại www.traintoachieve.org.ng."},{"en":"The following are some of our most popular classes.","vi":"Dưới đây là một số lớp học được ưa chuộng nhất của chúng tôi."}]},{"speaker":"Document 1 — Advertisement","en":"Introduction to Social Media Marketing (TTA1504): Taught by marketing consultant Marcus Akpan, the class equips you with the know-how to promote your business online.","vi":"Nhập môn Tiếp thị Mạng xã hội (TTA1504): Do chuyên gia tư vấn tiếp thị Marcus Akpan giảng dạy, lớp học trang bị cho bạn bí quyết để quảng bá doanh nghiệp trực tuyến.","units":[{"en":"Introduction to Social Media Marketing (TTA1504): Taught by marketing consultant Marcus Akpan, the class equips you with the know-how to promote your business online.","vi":"Nhập môn Tiếp thị Mạng xã hội (TTA1504): Do chuyên gia tư vấn tiếp thị Marcus Akpan giảng dạy, lớp học trang bị cho bạn bí quyết để quảng bá doanh nghiệp trực tuyến."}]},{"speaker":"Document 1 — Advertisement","en":"Become a Successful Freelance Writer (TTA3283): Business writer Brenda Akande gives you expert guidance on how to hone your writing skills and sell your writing services.","vi":"Trở thành Cây viết Tự do Thành công (TTA3283): Tác giả chuyên mảng kinh doanh Brenda Akande sẽ hướng dẫn chuyên sâu cách mài giũa kỹ năng viết và chào bán dịch vụ viết lách của bạn.","units":[{"en":"Become a Successful Freelance Writer (TTA3283): Business writer Brenda Akande gives you expert guidance on how to hone your writing skills and sell your writing services.","vi":"Trở thành Cây viết Tự do Thành công (TTA3283): Tác giả chuyên mảng kinh doanh Brenda Akande sẽ hướng dẫn chuyên sâu cách mài giũa kỹ năng viết và chào bán dịch vụ viết lách của bạn."}]},{"speaker":"Document 1 — Advertisement","en":"Starting an Internet Radio Station (TTA7629): Online radio host Natalie Kabiru shows you how to appeal to your target market and gives practical tips for setting up your broadcast service.","vi":"Khởi tạo Đài Phát thanh Trực tuyến (TTA7629): Người dẫn chương trình phát thanh trực tuyến Natalie Kabiru sẽ chỉ cho bạn cách thu hút thị trường mục tiêu và chia sẻ những mẹo thực tế để thiết lập dịch vụ phát sóng.","units":[{"en":"Starting an Internet Radio Station (TTA7629): Online radio host Natalie Kabiru shows you how to appeal to your target market and gives practical tips for setting up your broadcast service.","vi":"Khởi tạo Đài Phát thanh Trực tuyến (TTA7629): Người dẫn chương trình phát thanh trực tuyến Natalie Kabiru sẽ chỉ cho bạn cách thu hút thị trường mục tiêu và chia sẻ những mẹo thực tế để thiết lập dịch vụ phát sóng."}]},{"speaker":"Document 1 — Advertisement","en":"Basics of Graphic Design (TTA7633): Veteran graphic designer Doug Umaru helps you acquire the basic skills needed to start a graphic design business.","vi":"Kiến thức Cơ bản về Thiết kế Đồ họa (TTA7633): Nhà thiết kế đồ họa kỳ cựu Doug Umaru giúp bạn nắm vững các kỹ năng nền tảng cần thiết để khởi nghiệp kinh doanh thiết kế đồ họa.","units":[{"en":"Basics of Graphic Design (TTA7633): Veteran graphic designer Doug Umaru helps you acquire the basic skills needed to start a graphic design business.","vi":"Kiến thức Cơ bản về Thiết kế Đồ họa (TTA7633): Nhà thiết kế đồ họa kỳ cựu Doug Umaru giúp bạn nắm vững các kỹ năng nền tảng cần thiết để khởi nghiệp kinh doanh thiết kế đồ họa."}]},{"speaker":"Document 2 — Discussion Forum","en":"Discussion forum for students enrolled in Train to Achieve Class TTA1504","vi":"Diễn đàn thảo luận dành cho học viên đăng ký lớp TTA1504 của Train to Achieve","units":[{"en":"Discussion forum for students enrolled in Train to Achieve Class TTA1504","vi":"Diễn đàn thảo luận dành cho học viên đăng ký lớp TTA1504 của Train to Achieve"}]},{"speaker":"Document 2 — Discussion Forum","en":"Posted on: 21 May, 9:41 A.M. | Posted by: Joseph Egbe | Subject: Presentations","vi":"Đăng lúc: 21 tháng 5, 9:41 sáng | Người đăng: Joseph Egbe | Chủ đề: Bài thuyết trình","units":[{"en":"Posted on: 21 May, 9:41 A.M. | Posted by: Joseph Egbe | Subject: Presentations","vi":"Đăng lúc: 21 tháng 5, 9:41 sáng | Người đăng: Joseph Egbe | Chủ đề: Bài thuyết trình"}]},{"speaker":"Document 2 — Discussion Forum","en":"Viewing the list of students enrolled in this class, I remembered chatting with some of you on the forum for January's poster design class. I look forward to sharing our learning experiences again for this class. Yesterday I was the second student to meet with Mr. Akpan for an individual videoconference about my business. I own a food truck from which I sell baked goods, and when I shared with Mr. Akpan the outline for my Web site, he suggested that I add a section with vivid images of all my baked goods. It was helpful advice.","vi":"Khi xem danh sách học viên đăng ký lớp này, tôi nhớ lại lần từng trò chuyện với một vài bạn trên diễn đàn của lớp thiết kế áp phích hồi tháng 1. Tôi rất mong được tiếp tục chia sẻ kinh nghiệm học tập cùng mọi người trong khóa học này. Hôm qua, tôi là học viên thứ hai có buổi họp trực tuyến riêng với thầy Akpan để trao đổi về công việc kinh doanh của mình. Tôi sở hữu một xe tải bán đồ ăn chuyên các món bánh nướng, và khi tôi chia sẻ dàn ý trang web với thầy Akpan, thầy gợi ý tôi nên bổ sung thêm một mục có hình ảnh sinh động về tất cả các loại bánh của mình. Đó thực sự là một lời khuyên hữu ích.","units":[{"en":"Viewing the list of students enrolled in this class, I remembered chatting with some of you on the forum for January's poster design class.","vi":"Khi xem danh sách học viên đăng ký lớp này, tôi nhớ lại lần từng trò chuyện với một vài bạn trên diễn đàn của lớp thiết kế áp phích hồi tháng 1."},{"en":"I look forward to sharing our learning experiences again for this class.","vi":"Tôi rất mong được tiếp tục chia sẻ kinh nghiệm học tập cùng mọi người trong khóa học này."},{"en":"Yesterday I was the second student to meet with Mr. Akpan for an individual videoconference about my business.","vi":"Hôm qua, tôi là học viên thứ hai có buổi họp trực tuyến riêng với thầy Akpan để trao đổi về công việc kinh doanh của mình."},{"en":"I own a food truck from which I sell baked goods, and when I shared with Mr. Akpan the outline for my Web site, he suggested that I add a section with vivid images of all my baked goods.","vi":"Tôi sở hữu một xe tải bán đồ ăn chuyên các món bánh nướng, và khi tôi chia sẻ dàn ý trang web với thầy Akpan, thầy gợi ý tôi nên bổ sung thêm một mục có hình ảnh sinh động về tất cả các loại bánh của mình."},{"en":"It was helpful advice.","vi":"Đó thực sự là một lời khuyên hữu ích."}]},{"speaker":"Document 3 — Outline","en":"Egbe's Bakery—Unique baked-in flavours in every bite!","vi":"Egbe's Bakery — Hương vị nướng độc đáo đậm đà trong từng miếng bánh!","units":[{"en":"Egbe's Bakery—Unique baked-in flavours in every bite!","vi":"Egbe's Bakery — Hương vị nướng độc đáo đậm đà trong từng miếng bánh!"}]},{"speaker":"Document 3 — Outline","en":"• Section 1: Explore our menu and price list","vi":"• Mục 1: Khám phá thực đơn và bảng giá của chúng tôi","units":[{"en":"• Section 1: Explore our menu and price list","vi":"• Mục 1: Khám phá thực đơn và bảng giá của chúng tôi"}]},{"speaker":"Document 3 — Outline","en":"• Section 2: Browse photos of our delicious treats","vi":"• Mục 2: Xem hình ảnh những món bánh thơm ngon của chúng tôi","units":[{"en":"• Section 2: Browse photos of our delicious treats","vi":"• Mục 2: Xem hình ảnh những món bánh thơm ngon của chúng tôi"}]},{"speaker":"Document 3 — Outline","en":"• Section 3: Learn about our catering services","vi":"• Mục 3: Tìm hiểu về dịch vụ đặt tiệc của chúng tôi","units":[{"en":"• Section 3: Learn about our catering services","vi":"• Mục 3: Tìm hiểu về dịch vụ đặt tiệc của chúng tôi"}]},{"speaker":"Document 3 — Outline","en":"• Section 4: View lists of ingredients","vi":"• Mục 4: Xem danh sách nguyên liệu","units":[{"en":"• Section 4: View lists of ingredients","vi":"• Mục 4: Xem danh sách nguyên liệu"}]}],"vocab":[{"word":"consultant","pos":"n","ipa":"/kənˈsʌltənt/","meaning":"chuyên gia tư vấn"},{"word":"equip","pos":"v","ipa":"/ɪˈkwɪp/","meaning":"trang bị (kiến thức, kỹ năng)"},{"word":"know-how","pos":"n","ipa":"/ˈnoʊ haʊ/","meaning":"bí quyết, kiến thức thực tế"},{"word":"promote","pos":"v","ipa":"/prəˈmoʊt/","meaning":"quảng bá, xúc tiến"}],"isScanBacked":false,"docTypeLabel":"advertisement, discussion forum post, and outline","context":"Advertisement, discussion forum post, and Web site outline — Train to Achieve (TTA) & Egbe's Bakery","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 — LIÊN KẾT ĐA VĂN BẢN (DOCUMENT 1 + DOCUMENT 2): Ghép mã lớp 'TTA1504' và tên giảng viên 'Mr. Akpan' trong Document 2 với danh mục khóa học ở Document 1 -> Chốt tên lớp chính xác.","optionAnalysis":{"A":"Đúng vì đối chiếu Document 2 (lớp TTA1504, giảng viên Mr. Akpan) với Document 1 cho thấy TTA1504 chính là 'Introduction to Social Media Marketing' do Marcus Akpan dạy.","B":"Sai vì 'Become a Successful Freelance Writer' là lớp TTA3283 do Brenda Akande giảng dạy, không khớp lớp TTA1504 của ông Egbe.","C":"Sai vì 'Starting an Internet Radio Station' là lớp TTA7629 do Natalie Kabiru giảng dạy, không liên quan đến Mr. Akpan.","D":"Sai vì 'Basics of Graphic Design' là lớp TTA7633 do Doug Umaru dạy; lớp thiết kế ông Egbe nhắc đến là lớp áp phích cũ từ tháng 1."},"evDocIdx":1,"evTargets":[{"badge":"Câu 189 · Đáp án A","opt":"A","isCorrect":true,"quote":"Discussion forum for students enrolled in Train to Achieve Class TTA1504","viQuote":"Diễn đàn thảo luận dành cho học viên đăng ký lớp TTA1504 của Train to Achieve"},{"badge":"Câu 189 · Đáp án A","opt":"A","isCorrect":true,"quote":"Introduction to Social Media Marketing (TTA1504): Taught by marketing consultant Marcus Akpan, the class equips you with the know-how to promote your business online.","viQuote":"Nhập môn Tiếp thị Mạng xã hội (TTA1504): Do chuyên gia tư vấn tiếp thị Marcus Akpan giảng dạy, lớp học trang bị cho bạn bí quyết để quảng bá doanh nghiệp trực tuyến."}],"evQuotes":["Discussion forum for students enrolled in Train to Achieve Class TTA1504","Introduction to Social Media Marketing (TTA1504): Taught by marketing consultant Marcus Akpan, the class equips you with the know-how to promote your business online."]},{"q":190,"part":7,"group_id":"E25_T01_G186_190","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc23.webp","web_assets/ets2025/p67/E25_T01_rc24.webp"],"stem_en":"What section did Mr. Egbe most likely add to the outline after speaking with Mr. Akpan?","stem_vi":"Ông Egbe có khả năng đã thêm mục nào vào dàn ý trang web sau khi trao đổi với ông Akpan?","options":{"A":{"en":"Section 1","vi":"Mục 1"},"B":{"en":"Section 2","vi":"Mục 2"},"C":{"en":"Section 3","vi":"Mục 3"},"D":{"en":"Section 4","vi":"Mục 4"}},"ans":"B","evidence_quote":"- In the posting: I own a food truck from which I sell baked goods, and when I shared with Mr. Akpan the outline for my Web site, he suggested that I add a section with vivid images of all my baked goods. It was helpful advice. - In the outline: Section 2: Browse photos of our delicious treats","explanation":"Đáp án đúng: (B) Mục 2 (Section 2) — Thầy Akpan khuyên ông Egbe thêm một mục có hình ảnh sinh động về các món bánh nướng, khớp với nội dung xem ảnh các món bánh ngọt ở Mục 2.\nDẫn chứng: Document 2 (Forum) viết \"he suggested that I add a section with vivid images of all my baked goods\"; đối chiếu Document 3 (Outline) ghi \"• Section 2: Browse photos of our delicious treats\" ('vivid images of all my baked goods' = 'photos of our delicious treats').\nPhân tích bẫy:\n- (A) Bẫy sai nội dung mục: Section 1 trong Document 3 là xem thực đơn và bảng giá ('Explore our menu and price list'), không phải xem ảnh bánh.\n- (C) Bẫy sai nội dung mục: Section 3 trong Document 3 giới thiệu dịch vụ đặt tiệc ('Learn about our catering services'), không khớp gợi ý thêm hình ảnh.\n- (D) Bẫy sai nội dung mục: Section 4 trong Document 3 trình bày danh sách nguyên liệu ('View lists of ingredients'), không phải thư viện ảnh món bánh.","lines":[{"speaker":"Document 1 — Advertisement","en":"Train to Achieve (TTA)—Our classes prepare you to succeed!","vi":"Train to Achieve (TTA) — Các lớp học của chúng tôi trang bị hành trang để bạn thành công!","units":[{"en":"Train to Achieve (TTA)—Our classes prepare you to succeed!","vi":"Train to Achieve (TTA) — Các lớp học của chúng tôi trang bị hành trang để bạn thành công!"}]},{"speaker":"Document 1 — Advertisement","en":"Profiled in the latest Business Directions Nigeria newsletter, Train to Achieve (TTA) is one of the most innovative training providers in West Africa. By offering our classes entirely in online format, we bring the classroom to your home.","vi":"Được giới thiệu trên số mới nhất của bản tin Business Directions Nigeria, Train to Achieve (TTA) là một trong những đơn vị đào tạo đổi mới sáng tạo hàng đầu tại Tây Phi. Bằng việc tổ chức toàn bộ các lớp học theo hình thức trực tuyến, chúng tôi mang lớp học đến ngay tại nhà bạn.","units":[{"en":"Profiled in the latest Business Directions Nigeria newsletter, Train to Achieve (TTA) is one of the most innovative training providers in West Africa.","vi":"Được giới thiệu trên số mới nhất của bản tin Business Directions Nigeria, Train to Achieve (TTA) là một trong những đơn vị đào tạo đổi mới sáng tạo hàng đầu tại Tây Phi."},{"en":"By offering our classes entirely in online format, we bring the classroom to your home.","vi":"Bằng việc tổ chức toàn bộ các lớp học theo hình thức trực tuyến, chúng tôi mang lớp học đến ngay tại nhà bạn."}]},{"speaker":"Document 1 — Advertisement","en":"All classes include individualized instruction and are taught by recognized professionals in their respective fields. Upon successful completion of a class, you will receive an official Certificate of Training, a valuable addition to any résumé.","vi":"Mọi lớp học đều có phần hướng dẫn cá nhân hóa và do các chuyên gia uy tín trong từng lĩnh vực trực tiếp giảng dạy. Khi hoàn thành tốt khóa học, bạn sẽ nhận được Chứng chỉ Đào tạo chính thức — một điểm cộng giá trị cho bất kỳ hồ sơ xin việc nào.","units":[{"en":"All classes include individualized instruction and are taught by recognized professionals in their respective fields.","vi":"Mọi lớp học đều có phần hướng dẫn cá nhân hóa và do các chuyên gia uy tín trong từng lĩnh vực trực tiếp giảng dạy."},{"en":"Upon successful completion of a class, you will receive an official Certificate of Training, a valuable addition to any résumé.","vi":"Khi hoàn thành tốt khóa học, bạn sẽ nhận được Chứng chỉ Đào tạo chính thức — một điểm cộng giá trị cho bất kỳ hồ sơ xin việc nào."}]},{"speaker":"Document 1 — Advertisement","en":"For a complete list of class fees and schedules, visit our Web site at www.traintoachieve.org.ng. The following are some of our most popular classes.","vi":"Để xem danh sách đầy đủ về học phí và lịch học, vui lòng truy cập trang web của chúng tôi tại www.traintoachieve.org.ng. Dưới đây là một số lớp học được ưa chuộng nhất của chúng tôi.","units":[{"en":"For a complete list of class fees and schedules, visit our Web site at www.traintoachieve.org.ng.","vi":"Để xem danh sách đầy đủ về học phí và lịch học, vui lòng truy cập trang web của chúng tôi tại www.traintoachieve.org.ng."},{"en":"The following are some of our most popular classes.","vi":"Dưới đây là một số lớp học được ưa chuộng nhất của chúng tôi."}]},{"speaker":"Document 1 — Advertisement","en":"Introduction to Social Media Marketing (TTA1504): Taught by marketing consultant Marcus Akpan, the class equips you with the know-how to promote your business online.","vi":"Nhập môn Tiếp thị Mạng xã hội (TTA1504): Do chuyên gia tư vấn tiếp thị Marcus Akpan giảng dạy, lớp học trang bị cho bạn bí quyết để quảng bá doanh nghiệp trực tuyến.","units":[{"en":"Introduction to Social Media Marketing (TTA1504): Taught by marketing consultant Marcus Akpan, the class equips you with the know-how to promote your business online.","vi":"Nhập môn Tiếp thị Mạng xã hội (TTA1504): Do chuyên gia tư vấn tiếp thị Marcus Akpan giảng dạy, lớp học trang bị cho bạn bí quyết để quảng bá doanh nghiệp trực tuyến."}]},{"speaker":"Document 1 — Advertisement","en":"Become a Successful Freelance Writer (TTA3283): Business writer Brenda Akande gives you expert guidance on how to hone your writing skills and sell your writing services.","vi":"Trở thành Cây viết Tự do Thành công (TTA3283): Tác giả chuyên mảng kinh doanh Brenda Akande sẽ hướng dẫn chuyên sâu cách mài giũa kỹ năng viết và chào bán dịch vụ viết lách của bạn.","units":[{"en":"Become a Successful Freelance Writer (TTA3283): Business writer Brenda Akande gives you expert guidance on how to hone your writing skills and sell your writing services.","vi":"Trở thành Cây viết Tự do Thành công (TTA3283): Tác giả chuyên mảng kinh doanh Brenda Akande sẽ hướng dẫn chuyên sâu cách mài giũa kỹ năng viết và chào bán dịch vụ viết lách của bạn."}]},{"speaker":"Document 1 — Advertisement","en":"Starting an Internet Radio Station (TTA7629): Online radio host Natalie Kabiru shows you how to appeal to your target market and gives practical tips for setting up your broadcast service.","vi":"Khởi tạo Đài Phát thanh Trực tuyến (TTA7629): Người dẫn chương trình phát thanh trực tuyến Natalie Kabiru sẽ chỉ cho bạn cách thu hút thị trường mục tiêu và chia sẻ những mẹo thực tế để thiết lập dịch vụ phát sóng.","units":[{"en":"Starting an Internet Radio Station (TTA7629): Online radio host Natalie Kabiru shows you how to appeal to your target market and gives practical tips for setting up your broadcast service.","vi":"Khởi tạo Đài Phát thanh Trực tuyến (TTA7629): Người dẫn chương trình phát thanh trực tuyến Natalie Kabiru sẽ chỉ cho bạn cách thu hút thị trường mục tiêu và chia sẻ những mẹo thực tế để thiết lập dịch vụ phát sóng."}]},{"speaker":"Document 1 — Advertisement","en":"Basics of Graphic Design (TTA7633): Veteran graphic designer Doug Umaru helps you acquire the basic skills needed to start a graphic design business.","vi":"Kiến thức Cơ bản về Thiết kế Đồ họa (TTA7633): Nhà thiết kế đồ họa kỳ cựu Doug Umaru giúp bạn nắm vững các kỹ năng nền tảng cần thiết để khởi nghiệp kinh doanh thiết kế đồ họa.","units":[{"en":"Basics of Graphic Design (TTA7633): Veteran graphic designer Doug Umaru helps you acquire the basic skills needed to start a graphic design business.","vi":"Kiến thức Cơ bản về Thiết kế Đồ họa (TTA7633): Nhà thiết kế đồ họa kỳ cựu Doug Umaru giúp bạn nắm vững các kỹ năng nền tảng cần thiết để khởi nghiệp kinh doanh thiết kế đồ họa."}]},{"speaker":"Document 2 — Discussion Forum","en":"Discussion forum for students enrolled in Train to Achieve Class TTA1504","vi":"Diễn đàn thảo luận dành cho học viên đăng ký lớp TTA1504 của Train to Achieve","units":[{"en":"Discussion forum for students enrolled in Train to Achieve Class TTA1504","vi":"Diễn đàn thảo luận dành cho học viên đăng ký lớp TTA1504 của Train to Achieve"}]},{"speaker":"Document 2 — Discussion Forum","en":"Posted on: 21 May, 9:41 A.M. | Posted by: Joseph Egbe | Subject: Presentations","vi":"Đăng lúc: 21 tháng 5, 9:41 sáng | Người đăng: Joseph Egbe | Chủ đề: Bài thuyết trình","units":[{"en":"Posted on: 21 May, 9:41 A.M. | Posted by: Joseph Egbe | Subject: Presentations","vi":"Đăng lúc: 21 tháng 5, 9:41 sáng | Người đăng: Joseph Egbe | Chủ đề: Bài thuyết trình"}]},{"speaker":"Document 2 — Discussion Forum","en":"Viewing the list of students enrolled in this class, I remembered chatting with some of you on the forum for January's poster design class. I look forward to sharing our learning experiences again for this class. Yesterday I was the second student to meet with Mr. Akpan for an individual videoconference about my business. I own a food truck from which I sell baked goods, and when I shared with Mr. Akpan the outline for my Web site, he suggested that I add a section with vivid images of all my baked goods. It was helpful advice.","vi":"Khi xem danh sách học viên đăng ký lớp này, tôi nhớ lại lần từng trò chuyện với một vài bạn trên diễn đàn của lớp thiết kế áp phích hồi tháng 1. Tôi rất mong được tiếp tục chia sẻ kinh nghiệm học tập cùng mọi người trong khóa học này. Hôm qua, tôi là học viên thứ hai có buổi họp trực tuyến riêng với thầy Akpan để trao đổi về công việc kinh doanh của mình. Tôi sở hữu một xe tải bán đồ ăn chuyên các món bánh nướng, và khi tôi chia sẻ dàn ý trang web với thầy Akpan, thầy gợi ý tôi nên bổ sung thêm một mục có hình ảnh sinh động về tất cả các loại bánh của mình. Đó thực sự là một lời khuyên hữu ích.","units":[{"en":"Viewing the list of students enrolled in this class, I remembered chatting with some of you on the forum for January's poster design class.","vi":"Khi xem danh sách học viên đăng ký lớp này, tôi nhớ lại lần từng trò chuyện với một vài bạn trên diễn đàn của lớp thiết kế áp phích hồi tháng 1."},{"en":"I look forward to sharing our learning experiences again for this class.","vi":"Tôi rất mong được tiếp tục chia sẻ kinh nghiệm học tập cùng mọi người trong khóa học này."},{"en":"Yesterday I was the second student to meet with Mr. Akpan for an individual videoconference about my business.","vi":"Hôm qua, tôi là học viên thứ hai có buổi họp trực tuyến riêng với thầy Akpan để trao đổi về công việc kinh doanh của mình."},{"en":"I own a food truck from which I sell baked goods, and when I shared with Mr. Akpan the outline for my Web site, he suggested that I add a section with vivid images of all my baked goods.","vi":"Tôi sở hữu một xe tải bán đồ ăn chuyên các món bánh nướng, và khi tôi chia sẻ dàn ý trang web với thầy Akpan, thầy gợi ý tôi nên bổ sung thêm một mục có hình ảnh sinh động về tất cả các loại bánh của mình."},{"en":"It was helpful advice.","vi":"Đó thực sự là một lời khuyên hữu ích."}]},{"speaker":"Document 3 — Outline","en":"Egbe's Bakery—Unique baked-in flavours in every bite!","vi":"Egbe's Bakery — Hương vị nướng độc đáo đậm đà trong từng miếng bánh!","units":[{"en":"Egbe's Bakery—Unique baked-in flavours in every bite!","vi":"Egbe's Bakery — Hương vị nướng độc đáo đậm đà trong từng miếng bánh!"}]},{"speaker":"Document 3 — Outline","en":"• Section 1: Explore our menu and price list","vi":"• Mục 1: Khám phá thực đơn và bảng giá của chúng tôi","units":[{"en":"• Section 1: Explore our menu and price list","vi":"• Mục 1: Khám phá thực đơn và bảng giá của chúng tôi"}]},{"speaker":"Document 3 — Outline","en":"• Section 2: Browse photos of our delicious treats","vi":"• Mục 2: Xem hình ảnh những món bánh thơm ngon của chúng tôi","units":[{"en":"• Section 2: Browse photos of our delicious treats","vi":"• Mục 2: Xem hình ảnh những món bánh thơm ngon của chúng tôi"}]},{"speaker":"Document 3 — Outline","en":"• Section 3: Learn about our catering services","vi":"• Mục 3: Tìm hiểu về dịch vụ đặt tiệc của chúng tôi","units":[{"en":"• Section 3: Learn about our catering services","vi":"• Mục 3: Tìm hiểu về dịch vụ đặt tiệc của chúng tôi"}]},{"speaker":"Document 3 — Outline","en":"• Section 4: View lists of ingredients","vi":"• Mục 4: Xem danh sách nguyên liệu","units":[{"en":"• Section 4: View lists of ingredients","vi":"• Mục 4: Xem danh sách nguyên liệu"}]}],"vocab":[{"word":"outline","pos":"n","ipa":"/ˈaʊtlaɪn/","meaning":"dàn ý, bản phác thảo"},{"word":"vivid","pos":"adj","ipa":"/ˈvɪvɪd/","meaning":"sinh động, sống động"},{"word":"baked goods","pos":"n","ipa":"/beɪkt ɡʊdz/","meaning":"các món bánh nướng"},{"word":"browse","pos":"v","ipa":"/braʊz/","meaning":"xem qua, lướt xem"}],"isScanBacked":false,"docTypeLabel":"advertisement, discussion forum post, and outline","context":"Advertisement, discussion forum post, and Web site outline — Train to Achieve (TTA) & Egbe's Bakery","grammarType":"Part 7 — Suy luận & Hàm ý văn bản (Inference & Implied Meaning)","formula":"CÔNG THỨC PART 7 — LIÊN KẾT GỢI Ý ↔ DÀN Ý (DOCUMENT 2 + DOCUMENT 3): Đọc lời khuyên của giảng viên ở Document 2 ('add a section with vivid images of all my baked goods') -> Đối chiếu từng đầu mục ở Document 3.","optionAnalysis":{"A":"Sai vì Section 1 của Document 3 nói về thực đơn và bảng giá ('menu and price list'), không khớp với lời khuyên thêm hình ảnh bánh.","B":"Đúng vì Document 2 nêu thầy Akpan khuyên thêm mục hình ảnh sinh động các món bánh ('vivid images of all my baked goods'), khớp với Section 2 ('Browse photos of our delicious treats') ở Document 3.","C":"Sai vì Section 3 của Document 3 giới thiệu dịch vụ đặt tiệc ('catering services'), không phải nội dung được thầy Akpan gợi ý thêm.","D":"Sai vì Section 4 của Document 3 là danh sách nguyên liệu ('lists of ingredients'), không chứa hình ảnh các món bánh nướng."},"evDocIdx":2,"evTargets":[{"badge":"Câu 190 · Đáp án B","opt":"B","isCorrect":true,"quote":"Section 2: Browse photos of our delicious treats","viQuote":"Mục 2: Xem hình ảnh những món bánh thơm ngon của chúng tôi"},{"badge":"Câu 190 · Đáp án B","opt":"B","isCorrect":true,"quote":"I own a food truck from which I sell baked goods, and when I shared with Mr. Akpan the outline for my Web site, he suggested that I add a section with vivid images of all my baked goods.","viQuote":"Tôi sở hữu một xe tải bán đồ ăn chuyên các món bánh nướng, và khi tôi chia sẻ dàn ý trang web với thầy Akpan, thầy gợi ý tôi nên bổ sung thêm một mục có hình ảnh sinh động về tất cả các loại bánh của mình."}],"evQuotes":["Section 2: Browse photos of our delicious treats","I own a food truck from which I sell baked goods, and when I shared with Mr. Akpan the outline for my Web site, he suggested that I add a section with vivid images of all my baked goods."]},{"q":191,"part":7,"group_id":"E25_T01_G191_195","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc25.webp","web_assets/ets2025/p67/E25_T01_rc26.webp"],"stem_en":"What does the article mention about Orange Bay Kitchen?","stem_vi":"Bài báo đề cập điều gì về Orange Bay Kitchen?","options":{"A":{"en":"It is currently hiring servers.","vi":"Nhà hàng hiện đang tuyển nhân viên phục vụ."},"B":{"en":"It is located on a quiet street.","vi":"Nhà hàng tọa lạc trên một con phố yên tĩnh."},"C":{"en":"It has another location in Jamaica.","vi":"Nhà hàng có một chi nhánh khác tại Jamaica."},"D":{"en":"It opened six months ago.","vi":"Nhà hàng đã khai trương cách đây sáu tháng."}},"ans":"D","evidence_quote":"Orange Bay Kitchen has been serving up an infusion of Jamaican flavours in a laid-back Caribbean atmosphere for six months now.","explanation":"Đáp án đúng: (D) Nhà hàng đã khai trương cách đây sáu tháng — Bài báo cho biết Orange Bay Kitchen đã phục vụ các món ăn hương vị Jamaica được sáu tháng tính đến thời điểm viết bài.\nDẫn chứng: \"Orange Bay Kitchen has been serving up an infusion of Jamaican flavours in a laid-back Caribbean atmosphere for six months now.\" (Document 1 — Article: cụm 'has been serving up' kèm mốc 'for six months now' được paraphrase thành 'opened six months ago').\nPhân tích bẫy:\n- (A) Bẫy từ khóa 'servers': Bài báo chỉ khen nhân viên phục vụ luôn vui vẻ hỗ trợ khách chọn món ('The servers are always happy to help diners'), không nói đang tuyển nhân viên.\n- (B) Bẫy trái nghĩa: Bài báo mô tả nhà hàng nằm giữa các cửa hàng và quán ăn nhộn nhịp ('amid the bustling shops and eateries in Wester Square'), không phải phố yên tĩnh.\n- (C) Bẫy đánh tráo địa danh: 'Jamaican flavours' chỉ phong cách ẩm thực Jamaica của quán tại Nottingham, không đề cập chi nhánh nào tại Jamaica.","lines":[{"speaker":"Document 1 — Article","en":"Caribbean Flavours Abound","vi":"Tràn ngập hương vị vùng Caribe","units":[{"en":"Caribbean Flavours Abound","vi":"Tràn ngập hương vị vùng Caribe"}]},{"speaker":"Document 1 — Article","en":"By Rebecca Roats","vi":"Tác giả: Rebecca Roats","units":[{"en":"By Rebecca Roats","vi":"Tác giả: Rebecca Roats"}]},{"speaker":"Document 1 — Article","en":"NOTTINGHAM (1 August)—Orange Bay Kitchen has been serving up an infusion of Jamaican flavours in a laid-back Caribbean atmosphere for six months now. Managed by Keron Deslandes, the 150-seat restaurant is an aromatic jewel amid the bustling shops and eateries in Wester Square. The servers are always happy to help diners select from the variety of delights on the extensive menu, which includes curried goat, oxtail soup, and red snapper. The restaurant is most famous for its jerk chicken. Marinated for 24 hours prior to grilling and served with sides of stewed cabbage and coconut rice, the dish is a good deal at £12.","vi":"NOTTINGHAM (ngày 1 tháng 8) — Suốt sáu tháng qua, Orange Bay Kitchen đã mang đến sự hòa quyện đậm đà của hương vị Jamaica trong không gian vùng Caribe đầy thư thái. Do Keron Deslandes quản lý, nhà hàng 150 chỗ ngồi này tựa như một viên ngọc ngát hương giữa khu mua sắm và ăn uống nhộn nhịp tại Quảng trường Wester. Đội ngũ phục vụ luôn sẵn lòng hỗ trợ thực khách lựa chọn từ thực đơn phong phú các món ngon, bao gồm cà ri dê, súp đuôi bò và cá hồng. Nhà hàng nổi tiếng nhất với món gà nướng kiểu Jamaica. Được tẩm ướp suốt 24 giờ trước khi nướng và dùng kèm bắp cải hầm cùng cơm cốt dừa, món ăn này có mức giá rất hợp lý là £12.","units":[{"en":"NOTTINGHAM (1 August)—Orange Bay Kitchen has been serving up an infusion of Jamaican flavours in a laid-back Caribbean atmosphere for six months now.","vi":"NOTTINGHAM (ngày 1 tháng 8) — Suốt sáu tháng qua, Orange Bay Kitchen đã mang đến sự hòa quyện đậm đà của hương vị Jamaica trong không gian vùng Caribe đầy thư thái."},{"en":"Managed by Keron Deslandes, the 150-seat restaurant is an aromatic jewel amid the bustling shops and eateries in Wester Square.","vi":"Do Keron Deslandes quản lý, nhà hàng 150 chỗ ngồi này tựa như một viên ngọc ngát hương giữa khu mua sắm và ăn uống nhộn nhịp tại Quảng trường Wester."},{"en":"The servers are always happy to help diners select from the variety of delights on the extensive menu, which includes curried goat, oxtail soup, and red snapper.","vi":"Đội ngũ phục vụ luôn sẵn lòng hỗ trợ thực khách lựa chọn từ thực đơn phong phú các món ngon, bao gồm cà ri dê, súp đuôi bò và cá hồng."},{"en":"The restaurant is most famous for its jerk chicken.","vi":"Nhà hàng nổi tiếng nhất với món gà nướng kiểu Jamaica."},{"en":"Marinated for 24 hours prior to grilling and served with sides of stewed cabbage and coconut rice, the dish is a good deal at £12.","vi":"Được tẩm ướp suốt 24 giờ trước khi nướng và dùng kèm bắp cải hầm cùng cơm cốt dừa, món ăn này có mức giá rất hợp lý là £12."}]},{"speaker":"Document 1 — Article","en":"If you stop in on any Friday night between 7 and 11 P.M., you will enjoy live reggae music.","vi":"Nếu ghé quán vào bất kỳ tối thứ Sáu nào từ 7 đến 11 giờ tối, bạn sẽ được thưởng thức nhạc reggae biểu diễn trực tiếp.","units":[{"en":"If you stop in on any Friday night between 7 and 11 P.M., you will enjoy live reggae music.","vi":"Nếu ghé quán vào bất kỳ tối thứ Sáu nào từ 7 đến 11 giờ tối, bạn sẽ được thưởng thức nhạc reggae biểu diễn trực tiếp."}]},{"speaker":"Document 2 — Review","en":"https://www.dinerreviews.co.uk/orangebaykitchen","vi":"https://www.dinerreviews.co.uk/orangebaykitchen","units":[{"en":"https://www.dinerreviews.co.uk/orangebaykitchen","vi":"https://www.dinerreviews.co.uk/orangebaykitchen"}]},{"speaker":"Document 2 — Review","en":"Posted on 22 August by Tamika Peterkin, tpeterkin@sunmail.co.uk","vi":"Đăng ngày 22 tháng 8 bởi Tamika Peterkin, tpeterkin@sunmail.co.uk","units":[{"en":"Posted on 22 August by Tamika Peterkin, tpeterkin@sunmail.co.uk","vi":"Đăng ngày 22 tháng 8 bởi Tamika Peterkin, tpeterkin@sunmail.co.uk"}]},{"speaker":"Document 2 — Review","en":"Orange Bay Kitchen: 2/5 Stars","vi":"Orange Bay Kitchen: 2/5 Sao","units":[{"en":"Orange Bay Kitchen: 2/5 Stars","vi":"Orange Bay Kitchen: 2/5 Sao"}]},{"speaker":"Document 2 — Review","en":"After reading a glowing article about Orange Bay Kitchen by Rebecca Roats, I was eager to give this place a try. My husband and I arrived there at 7 P.M. yesterday, keen to enjoy live music with our dinner. Unfortunately, the band's performance that night had been cancelled. Undeterred, we stayed and both ordered the jerk chicken. While the chicken's smoky flavour was outstanding, the stewed cabbage was lacking in flavour. Also, the portion size was smaller than we had anticipated, so we ordered another appetiser to avoid going home hungry. The head chef came out to apologise and was extremely nice, but we will probably not go back anytime soon.","vi":"Sau khi đọc bài viết khen ngợi hết lời về Orange Bay Kitchen của Rebecca Roats, tôi rất háo hức muốn đến trải nghiệm thử. Chồng tôi và tôi đến quán lúc 7 giờ tối hôm qua, mong chờ được thưởng thức nhạc sống cùng bữa tối. Thật không may, buổi biểu diễn tối hôm đó của ban nhạc đã bị hủy. Không nản lòng, chúng tôi vẫn nán lại và cả hai đều gọi món gà nướng kiểu Jamaica. Dù hương vị khói của thịt gà rất xuất sắc, món bắp cải hầm lại khá nhạt nhòa. Ngoài ra, khẩu phần ăn cũng nhỏ hơn dự kiến của chúng tôi, nên chúng tôi đã gọi thêm một món khai vị nữa để khỏi phải về nhà với cái bụng đói. Bếp trưởng đã ra tận bàn xin lỗi và rất nhã nhặn, nhưng có lẽ chúng tôi sẽ chưa quay lại trong thời gian tới.","units":[{"en":"After reading a glowing article about Orange Bay Kitchen by Rebecca Roats, I was eager to give this place a try.","vi":"Sau khi đọc bài viết khen ngợi hết lời về Orange Bay Kitchen của Rebecca Roats, tôi rất háo hức muốn đến trải nghiệm thử."},{"en":"My husband and I arrived there at 7 P.M. yesterday, keen to enjoy live music with our dinner.","vi":"Chồng tôi và tôi đến quán lúc 7 giờ tối hôm qua, mong chờ được thưởng thức nhạc sống cùng bữa tối."},{"en":"Unfortunately, the band's performance that night had been cancelled.","vi":"Thật không may, buổi biểu diễn tối hôm đó của ban nhạc đã bị hủy."},{"en":"Undeterred, we stayed and both ordered the jerk chicken.","vi":"Không nản lòng, chúng tôi vẫn nán lại và cả hai đều gọi món gà nướng kiểu Jamaica."},{"en":"While the chicken's smoky flavour was outstanding, the stewed cabbage was lacking in flavour.","vi":"Dù hương vị khói của thịt gà rất xuất sắc, món bắp cải hầm lại khá nhạt nhòa."},{"en":"Also, the portion size was smaller than we had anticipated, so we ordered another appetiser to avoid going home hungry.","vi":"Ngoài ra, khẩu phần ăn cũng nhỏ hơn dự kiến của chúng tôi, nên chúng tôi đã gọi thêm một món khai vị nữa để khỏi phải về nhà với cái bụng đói."},{"en":"The head chef came out to apologise and was extremely nice, but we will probably not go back anytime soon.","vi":"Bếp trưởng đã ra tận bàn xin lỗi và rất nhã nhặn, nhưng có lẽ chúng tôi sẽ chưa quay lại trong thời gian tới."}]},{"speaker":"Document 3 — E-mail","en":"To: tpeterkin@sunmail.co.uk","vi":"Đến: tpeterkin@sunmail.co.uk","units":[{"en":"To: tpeterkin@sunmail.co.uk","vi":"Đến: tpeterkin@sunmail.co.uk"}]},{"speaker":"Document 3 — E-mail","en":"From: vsmith@orangebaykitchen.co.uk","vi":"Từ: vsmith@orangebaykitchen.co.uk","units":[{"en":"From: vsmith@orangebaykitchen.co.uk","vi":"Từ: vsmith@orangebaykitchen.co.uk"}]},{"speaker":"Document 3 — E-mail","en":"Date: 24 August","vi":"Ngày: 24 tháng 8","units":[{"en":"Date: 24 August","vi":"Ngày: 24 tháng 8"}]},{"speaker":"Document 3 — E-mail","en":"Subject: Your review","vi":"Chủ đề: Đánh giá của bạn","units":[{"en":"Subject: Your review","vi":"Chủ đề: Đánh giá của bạn"}]},{"speaker":"Document 3 — E-mail","en":"Attachment: 0258","vi":"Tệp đính kèm: 0258","units":[{"en":"Attachment: 0258","vi":"Tệp đính kèm: 0258"}]},{"speaker":"Document 3 — E-mail","en":"Dear Ms. Peterkin,","vi":"Kính gửi bà Peterkin,","units":[{"en":"Dear Ms. Peterkin,","vi":"Kính gửi bà Peterkin,"}]},{"speaker":"Document 3 — E-mail","en":"Thank you for visiting Orange Bay Kitchen and leaving a review. Our manager, Keron Deslandes, told me more about your visit and our failure to live up to your expectations that evening. Please accept the attached £20 gift certificate; I do hope that you will give us another try.","vi":"Cảm ơn bà đã ghé thăm Orange Bay Kitchen và để lại đánh giá. Quản lý của chúng tôi, Keron Deslandes, đã trao đổi với tôi về chuyến ghé thăm của bà cũng như việc chúng tôi đã chưa đáp ứng được kỳ vọng của bà vào tối hôm đó. Xin bà vui lòng nhận phiếu quà tặng trị giá £20 đính kèm; tôi rất hy vọng bà sẽ cho chúng tôi một cơ hội phục vụ lại.","units":[{"en":"Thank you for visiting Orange Bay Kitchen and leaving a review.","vi":"Cảm ơn bà đã ghé thăm Orange Bay Kitchen và để lại đánh giá."},{"en":"Our manager, Keron Deslandes, told me more about your visit and our failure to live up to your expectations that evening.","vi":"Quản lý của chúng tôi, Keron Deslandes, đã trao đổi với tôi về chuyến ghé thăm của bà cũng như việc chúng tôi đã chưa đáp ứng được kỳ vọng của bà vào tối hôm đó."},{"en":"Please accept the attached £20 gift certificate; I do hope that you will give us another try.","vi":"Xin bà vui lòng nhận phiếu quà tặng trị giá £20 đính kèm; tôi rất hy vọng bà sẽ cho chúng tôi một cơ hội phục vụ lại."}]},{"speaker":"Document 3 — E-mail","en":"During your visit, our band had an equipment malfunction, which is what led to the last-minute cancellation. However, the band will be back performing weekly beginning in September. Also, I want you to know that Head Chef Adio Brown has changed the spices he uses in the stewed cabbage. I am sure you will find them delightful.","vi":"Vào buổi tối bà ghé quán, ban nhạc của chúng tôi gặp sự cố thiết bị nên buộc phải hủy buổi diễn vào phút chót. Tuy nhiên, ban nhạc sẽ trở lại biểu diễn hằng tuần bắt đầu từ tháng 9. Bên cạnh đó, tôi cũng xin thông báo rằng Bếp trưởng Adio Brown đã điều chỉnh lại gia vị cho món bắp cải hầm. Tôi tin chắc bà sẽ thấy hương vị mới rất tuyệt vời.","units":[{"en":"During your visit, our band had an equipment malfunction, which is what led to the last-minute cancellation.","vi":"Vào buổi tối bà ghé quán, ban nhạc của chúng tôi gặp sự cố thiết bị nên buộc phải hủy buổi diễn vào phút chót."},{"en":"However, the band will be back performing weekly beginning in September.","vi":"Tuy nhiên, ban nhạc sẽ trở lại biểu diễn hằng tuần bắt đầu từ tháng 9."},{"en":"Also, I want you to know that Head Chef Adio Brown has changed the spices he uses in the stewed cabbage.","vi":"Bên cạnh đó, tôi cũng xin thông báo rằng Bếp trưởng Adio Brown đã điều chỉnh lại gia vị cho món bắp cải hầm."},{"en":"I am sure you will find them delightful.","vi":"Tôi tin chắc bà sẽ thấy hương vị mới rất tuyệt vời."}]},{"speaker":"Document 3 — E-mail","en":"Sincerely,","vi":"Trân trọng,","units":[{"en":"Sincerely,","vi":"Trân trọng,"}]},{"speaker":"Document 3 — E-mail","en":"Vea Smith, Owner, Orange Bay Kitchen","vi":"Vea Smith, Chủ sở hữu, Orange Bay Kitchen","units":[{"en":"Vea Smith, Owner, Orange Bay Kitchen","vi":"Vea Smith, Chủ sở hữu, Orange Bay Kitchen"}]}],"vocab":[{"word":"infusion","pos":"n","ipa":"/ɪnˈfjuːʒən/","meaning":"sự hòa quyện, sự pha trộn"},{"word":"laid-back","pos":"adj","ipa":"/ˌleɪdˈbæk/","meaning":"thư thái, thoải mái"},{"word":"bustling","pos":"adj","ipa":"/ˈbʌslɪŋ/","meaning":"nhộn nhịp, hối hả"},{"word":"extensive","pos":"adj","ipa":"/ɪkˈstensɪv/","meaning":"phong phú, đa dạng, rộng lớn"}],"isScanBacked":false,"docTypeLabel":"article, review, and e-mail","context":"Article, review, and e-mail — Orange Bay Kitchen","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 — ĐỌC HIỂU THỜI GIAN HOẠT ĐỘNG (BÀI BÁO): Quy đổi thì hiện tại hoàn thành tiếp diễn 'has been serving up an infusion of Jamaican flavours in a laid-back Caribbean atmosphere for six months now' -> Nghĩa tương đương 'opened six months ago'.","optionAnalysis":{"A":"Sai vì dính bẫy từ khóa 'servers': bài báo khen nhân viên phục vụ nhiệt tình hỗ trợ thực khách, không hề đề cập tin tuyển dụng.","B":"Sai vì trái nghĩa với Document 1: quán nằm giữa khu Wester Square sầm uất ('amid the bustling shops and eateries'), không phải con phố yên tĩnh.","C":"Sai vì Jamaica chỉ xuất hiện trong cụm phong cách ẩm thực ('Jamaican flavours'), bài báo không nhắc đến chi nhánh nào ở Jamaica.","D":"Đúng vì câu mở đầu Document 1 nêu quán đã phục vụ được sáu tháng ('for six months now'), tức khai trương cách đây sáu tháng."},"evDocIdx":0,"evTargets":[{"badge":"Câu 191 · Đáp án D","opt":"D","isCorrect":true,"quote":"Orange Bay Kitchen has been serving up an infusion of Jamaican flavours in a laid-back Caribbean atmosphere for six months now.","viQuote":"Suốt sáu tháng qua, Orange Bay Kitchen đã mang đến sự hòa quyện đậm đà của hương vị Jamaica trong không gian vùng Caribe đầy thư thái."}],"evQuotes":["Orange Bay Kitchen has been serving up an infusion of Jamaican flavours in a laid-back Caribbean atmosphere for six months now."]},{"q":192,"part":7,"group_id":"E25_T01_G191_195","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc25.webp","web_assets/ets2025/p67/E25_T01_rc26.webp"],"stem_en":"According to the article, what is the most popular menu item at Orange Bay Kitchen?","stem_vi":"Theo bài báo, món ăn nào trong thực đơn được yêu thích nhất tại Orange Bay Kitchen?","options":{"A":{"en":"Red snapper","vi":"Cá hồng"},"B":{"en":"Oxtail soup","vi":"Súp đuôi bò"},"C":{"en":"Jerk chicken","vi":"Gà nướng kiểu Jamaica"},"D":{"en":"Curried goat","vi":"Cà ri dê"}},"ans":"C","evidence_quote":"The restaurant is most famous for its jerk chicken.","explanation":"Đáp án đúng: (C) Gà nướng kiểu Jamaica (Jerk chicken) — Bài báo nhấn mạnh đây là món nổi tiếng nhất tại nhà hàng Orange Bay Kitchen.\nDẫn chứng: \"The restaurant is most famous for its jerk chicken.\" (Document 1 — Article: 'most famous for' được paraphrase thành 'the most popular menu item').\nPhân tích bẫy:\n- (A) Bẫy liệt kê đồng hạng: 'Red snapper' (cá hồng) chỉ là một ví dụ trong danh sách thực đơn đa dạng ('which includes curried goat, oxtail soup, and red snapper'), không phải món nổi tiếng nhất.\n- (B) Bẫy liệt kê đồng hạng: 'Oxtail soup' (súp đuôi bò) chỉ được nhắc kèm các món khác trong thực đơn, không có chi tiết chứng tỏ được ưa chuộng nhất.\n- (D) Bẫy liệt kê đồng hạng: 'Curried goat' (cà ri dê) cũng nằm trong chuỗi liệt kê thực đơn chung, đứng trước câu tách riêng nhấn mạnh món 'jerk chicken'.","lines":[{"speaker":"Document 1 — Article","en":"Caribbean Flavours Abound","vi":"Tràn ngập hương vị vùng Caribe","units":[{"en":"Caribbean Flavours Abound","vi":"Tràn ngập hương vị vùng Caribe"}]},{"speaker":"Document 1 — Article","en":"By Rebecca Roats","vi":"Tác giả: Rebecca Roats","units":[{"en":"By Rebecca Roats","vi":"Tác giả: Rebecca Roats"}]},{"speaker":"Document 1 — Article","en":"NOTTINGHAM (1 August)—Orange Bay Kitchen has been serving up an infusion of Jamaican flavours in a laid-back Caribbean atmosphere for six months now. Managed by Keron Deslandes, the 150-seat restaurant is an aromatic jewel amid the bustling shops and eateries in Wester Square. The servers are always happy to help diners select from the variety of delights on the extensive menu, which includes curried goat, oxtail soup, and red snapper. The restaurant is most famous for its jerk chicken. Marinated for 24 hours prior to grilling and served with sides of stewed cabbage and coconut rice, the dish is a good deal at £12.","vi":"NOTTINGHAM (ngày 1 tháng 8) — Suốt sáu tháng qua, Orange Bay Kitchen đã mang đến sự hòa quyện đậm đà của hương vị Jamaica trong không gian vùng Caribe đầy thư thái. Do Keron Deslandes quản lý, nhà hàng 150 chỗ ngồi này tựa như một viên ngọc ngát hương giữa khu mua sắm và ăn uống nhộn nhịp tại Quảng trường Wester. Đội ngũ phục vụ luôn sẵn lòng hỗ trợ thực khách lựa chọn từ thực đơn phong phú các món ngon, bao gồm cà ri dê, súp đuôi bò và cá hồng. Nhà hàng nổi tiếng nhất với món gà nướng kiểu Jamaica. Được tẩm ướp suốt 24 giờ trước khi nướng và dùng kèm bắp cải hầm cùng cơm cốt dừa, món ăn này có mức giá rất hợp lý là £12.","units":[{"en":"NOTTINGHAM (1 August)—Orange Bay Kitchen has been serving up an infusion of Jamaican flavours in a laid-back Caribbean atmosphere for six months now.","vi":"NOTTINGHAM (ngày 1 tháng 8) — Suốt sáu tháng qua, Orange Bay Kitchen đã mang đến sự hòa quyện đậm đà của hương vị Jamaica trong không gian vùng Caribe đầy thư thái."},{"en":"Managed by Keron Deslandes, the 150-seat restaurant is an aromatic jewel amid the bustling shops and eateries in Wester Square.","vi":"Do Keron Deslandes quản lý, nhà hàng 150 chỗ ngồi này tựa như một viên ngọc ngát hương giữa khu mua sắm và ăn uống nhộn nhịp tại Quảng trường Wester."},{"en":"The servers are always happy to help diners select from the variety of delights on the extensive menu, which includes curried goat, oxtail soup, and red snapper.","vi":"Đội ngũ phục vụ luôn sẵn lòng hỗ trợ thực khách lựa chọn từ thực đơn phong phú các món ngon, bao gồm cà ri dê, súp đuôi bò và cá hồng."},{"en":"The restaurant is most famous for its jerk chicken.","vi":"Nhà hàng nổi tiếng nhất với món gà nướng kiểu Jamaica."},{"en":"Marinated for 24 hours prior to grilling and served with sides of stewed cabbage and coconut rice, the dish is a good deal at £12.","vi":"Được tẩm ướp suốt 24 giờ trước khi nướng và dùng kèm bắp cải hầm cùng cơm cốt dừa, món ăn này có mức giá rất hợp lý là £12."}]},{"speaker":"Document 1 — Article","en":"If you stop in on any Friday night between 7 and 11 P.M., you will enjoy live reggae music.","vi":"Nếu ghé quán vào bất kỳ tối thứ Sáu nào từ 7 đến 11 giờ tối, bạn sẽ được thưởng thức nhạc reggae biểu diễn trực tiếp.","units":[{"en":"If you stop in on any Friday night between 7 and 11 P.M., you will enjoy live reggae music.","vi":"Nếu ghé quán vào bất kỳ tối thứ Sáu nào từ 7 đến 11 giờ tối, bạn sẽ được thưởng thức nhạc reggae biểu diễn trực tiếp."}]},{"speaker":"Document 2 — Review","en":"https://www.dinerreviews.co.uk/orangebaykitchen","vi":"https://www.dinerreviews.co.uk/orangebaykitchen","units":[{"en":"https://www.dinerreviews.co.uk/orangebaykitchen","vi":"https://www.dinerreviews.co.uk/orangebaykitchen"}]},{"speaker":"Document 2 — Review","en":"Posted on 22 August by Tamika Peterkin, tpeterkin@sunmail.co.uk","vi":"Đăng ngày 22 tháng 8 bởi Tamika Peterkin, tpeterkin@sunmail.co.uk","units":[{"en":"Posted on 22 August by Tamika Peterkin, tpeterkin@sunmail.co.uk","vi":"Đăng ngày 22 tháng 8 bởi Tamika Peterkin, tpeterkin@sunmail.co.uk"}]},{"speaker":"Document 2 — Review","en":"Orange Bay Kitchen: 2/5 Stars","vi":"Orange Bay Kitchen: 2/5 Sao","units":[{"en":"Orange Bay Kitchen: 2/5 Stars","vi":"Orange Bay Kitchen: 2/5 Sao"}]},{"speaker":"Document 2 — Review","en":"After reading a glowing article about Orange Bay Kitchen by Rebecca Roats, I was eager to give this place a try. My husband and I arrived there at 7 P.M. yesterday, keen to enjoy live music with our dinner. Unfortunately, the band's performance that night had been cancelled. Undeterred, we stayed and both ordered the jerk chicken. While the chicken's smoky flavour was outstanding, the stewed cabbage was lacking in flavour. Also, the portion size was smaller than we had anticipated, so we ordered another appetiser to avoid going home hungry. The head chef came out to apologise and was extremely nice, but we will probably not go back anytime soon.","vi":"Sau khi đọc bài viết khen ngợi hết lời về Orange Bay Kitchen của Rebecca Roats, tôi rất háo hức muốn đến trải nghiệm thử. Chồng tôi và tôi đến quán lúc 7 giờ tối hôm qua, mong chờ được thưởng thức nhạc sống cùng bữa tối. Thật không may, buổi biểu diễn tối hôm đó của ban nhạc đã bị hủy. Không nản lòng, chúng tôi vẫn nán lại và cả hai đều gọi món gà nướng kiểu Jamaica. Dù hương vị khói của thịt gà rất xuất sắc, món bắp cải hầm lại khá nhạt nhòa. Ngoài ra, khẩu phần ăn cũng nhỏ hơn dự kiến của chúng tôi, nên chúng tôi đã gọi thêm một món khai vị nữa để khỏi phải về nhà với cái bụng đói. Bếp trưởng đã ra tận bàn xin lỗi và rất nhã nhặn, nhưng có lẽ chúng tôi sẽ chưa quay lại trong thời gian tới.","units":[{"en":"After reading a glowing article about Orange Bay Kitchen by Rebecca Roats, I was eager to give this place a try.","vi":"Sau khi đọc bài viết khen ngợi hết lời về Orange Bay Kitchen của Rebecca Roats, tôi rất háo hức muốn đến trải nghiệm thử."},{"en":"My husband and I arrived there at 7 P.M. yesterday, keen to enjoy live music with our dinner.","vi":"Chồng tôi và tôi đến quán lúc 7 giờ tối hôm qua, mong chờ được thưởng thức nhạc sống cùng bữa tối."},{"en":"Unfortunately, the band's performance that night had been cancelled.","vi":"Thật không may, buổi biểu diễn tối hôm đó của ban nhạc đã bị hủy."},{"en":"Undeterred, we stayed and both ordered the jerk chicken.","vi":"Không nản lòng, chúng tôi vẫn nán lại và cả hai đều gọi món gà nướng kiểu Jamaica."},{"en":"While the chicken's smoky flavour was outstanding, the stewed cabbage was lacking in flavour.","vi":"Dù hương vị khói của thịt gà rất xuất sắc, món bắp cải hầm lại khá nhạt nhòa."},{"en":"Also, the portion size was smaller than we had anticipated, so we ordered another appetiser to avoid going home hungry.","vi":"Ngoài ra, khẩu phần ăn cũng nhỏ hơn dự kiến của chúng tôi, nên chúng tôi đã gọi thêm một món khai vị nữa để khỏi phải về nhà với cái bụng đói."},{"en":"The head chef came out to apologise and was extremely nice, but we will probably not go back anytime soon.","vi":"Bếp trưởng đã ra tận bàn xin lỗi và rất nhã nhặn, nhưng có lẽ chúng tôi sẽ chưa quay lại trong thời gian tới."}]},{"speaker":"Document 3 — E-mail","en":"To: tpeterkin@sunmail.co.uk","vi":"Đến: tpeterkin@sunmail.co.uk","units":[{"en":"To: tpeterkin@sunmail.co.uk","vi":"Đến: tpeterkin@sunmail.co.uk"}]},{"speaker":"Document 3 — E-mail","en":"From: vsmith@orangebaykitchen.co.uk","vi":"Từ: vsmith@orangebaykitchen.co.uk","units":[{"en":"From: vsmith@orangebaykitchen.co.uk","vi":"Từ: vsmith@orangebaykitchen.co.uk"}]},{"speaker":"Document 3 — E-mail","en":"Date: 24 August","vi":"Ngày: 24 tháng 8","units":[{"en":"Date: 24 August","vi":"Ngày: 24 tháng 8"}]},{"speaker":"Document 3 — E-mail","en":"Subject: Your review","vi":"Chủ đề: Đánh giá của bạn","units":[{"en":"Subject: Your review","vi":"Chủ đề: Đánh giá của bạn"}]},{"speaker":"Document 3 — E-mail","en":"Attachment: 0258","vi":"Tệp đính kèm: 0258","units":[{"en":"Attachment: 0258","vi":"Tệp đính kèm: 0258"}]},{"speaker":"Document 3 — E-mail","en":"Dear Ms. Peterkin,","vi":"Kính gửi bà Peterkin,","units":[{"en":"Dear Ms. Peterkin,","vi":"Kính gửi bà Peterkin,"}]},{"speaker":"Document 3 — E-mail","en":"Thank you for visiting Orange Bay Kitchen and leaving a review. Our manager, Keron Deslandes, told me more about your visit and our failure to live up to your expectations that evening. Please accept the attached £20 gift certificate; I do hope that you will give us another try.","vi":"Cảm ơn bà đã ghé thăm Orange Bay Kitchen và để lại đánh giá. Quản lý của chúng tôi, Keron Deslandes, đã trao đổi với tôi về chuyến ghé thăm của bà cũng như việc chúng tôi đã chưa đáp ứng được kỳ vọng của bà vào tối hôm đó. Xin bà vui lòng nhận phiếu quà tặng trị giá £20 đính kèm; tôi rất hy vọng bà sẽ cho chúng tôi một cơ hội phục vụ lại.","units":[{"en":"Thank you for visiting Orange Bay Kitchen and leaving a review.","vi":"Cảm ơn bà đã ghé thăm Orange Bay Kitchen và để lại đánh giá."},{"en":"Our manager, Keron Deslandes, told me more about your visit and our failure to live up to your expectations that evening.","vi":"Quản lý của chúng tôi, Keron Deslandes, đã trao đổi với tôi về chuyến ghé thăm của bà cũng như việc chúng tôi đã chưa đáp ứng được kỳ vọng của bà vào tối hôm đó."},{"en":"Please accept the attached £20 gift certificate; I do hope that you will give us another try.","vi":"Xin bà vui lòng nhận phiếu quà tặng trị giá £20 đính kèm; tôi rất hy vọng bà sẽ cho chúng tôi một cơ hội phục vụ lại."}]},{"speaker":"Document 3 — E-mail","en":"During your visit, our band had an equipment malfunction, which is what led to the last-minute cancellation. However, the band will be back performing weekly beginning in September. Also, I want you to know that Head Chef Adio Brown has changed the spices he uses in the stewed cabbage. I am sure you will find them delightful.","vi":"Vào buổi tối bà ghé quán, ban nhạc của chúng tôi gặp sự cố thiết bị nên buộc phải hủy buổi diễn vào phút chót. Tuy nhiên, ban nhạc sẽ trở lại biểu diễn hằng tuần bắt đầu từ tháng 9. Bên cạnh đó, tôi cũng xin thông báo rằng Bếp trưởng Adio Brown đã điều chỉnh lại gia vị cho món bắp cải hầm. Tôi tin chắc bà sẽ thấy hương vị mới rất tuyệt vời.","units":[{"en":"During your visit, our band had an equipment malfunction, which is what led to the last-minute cancellation.","vi":"Vào buổi tối bà ghé quán, ban nhạc của chúng tôi gặp sự cố thiết bị nên buộc phải hủy buổi diễn vào phút chót."},{"en":"However, the band will be back performing weekly beginning in September.","vi":"Tuy nhiên, ban nhạc sẽ trở lại biểu diễn hằng tuần bắt đầu từ tháng 9."},{"en":"Also, I want you to know that Head Chef Adio Brown has changed the spices he uses in the stewed cabbage.","vi":"Bên cạnh đó, tôi cũng xin thông báo rằng Bếp trưởng Adio Brown đã điều chỉnh lại gia vị cho món bắp cải hầm."},{"en":"I am sure you will find them delightful.","vi":"Tôi tin chắc bà sẽ thấy hương vị mới rất tuyệt vời."}]},{"speaker":"Document 3 — E-mail","en":"Sincerely,","vi":"Trân trọng,","units":[{"en":"Sincerely,","vi":"Trân trọng,"}]},{"speaker":"Document 3 — E-mail","en":"Vea Smith, Owner, Orange Bay Kitchen","vi":"Vea Smith, Chủ sở hữu, Orange Bay Kitchen","units":[{"en":"Vea Smith, Owner, Orange Bay Kitchen","vi":"Vea Smith, Chủ sở hữu, Orange Bay Kitchen"}]}],"vocab":[{"word":"marinate","pos":"v","ipa":"/ˈmærɪneɪt/","meaning":"tẩm ướp gia vị"},{"word":"a good deal","pos":"phr","ipa":"/ə ɡʊd diːl/","meaning":"mức giá hời, hợp lý"},{"word":"delight","pos":"n","ipa":"/dɪˈlaɪt/","meaning":"món ngon, niềm thích thú"},{"word":"popular","pos":"adj","ipa":"/ˈpɑːpjələr/","meaning":"được ưa chuộng, phổ biến"}],"isScanBacked":false,"docTypeLabel":"article, review, and e-mail","context":"Article, review, and e-mail — Orange Bay Kitchen","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 — SO SÁNH NHẤT & PARAPHRASE MÓN ĂN (BÀI BÁO): Tìm tín hiệu so sánh nhất 'most famous for' -> Loại các món chỉ xuất hiện trong liệt kê thông thường -> Chốt 'jerk chicken'.","optionAnalysis":{"A":"Sai vì cá hồng ('red snapper') chỉ được liệt kê như một lựa chọn trong thực đơn đa dạng, không phải món nổi tiếng nhất.","B":"Sai vì súp đuôi bò ('oxtail soup') chỉ xuất hiện trong danh sách các món có sẵn, không được bài báo nhấn mạnh là nổi tiếng nhất.","C":"Đúng vì Document 1 khẳng định trực tiếp nhà hàng nổi tiếng nhất với món gà nướng kiểu Jamaica ('most famous for its jerk chicken').","D":"Sai vì cà ri dê ('curried goat') chỉ là một món được nhắc qua trong thực đơn, không phải món đặc trưng nổi tiếng nhất của quán."},"evDocIdx":0,"evTargets":[{"badge":"Câu 192 · Đáp án C","opt":"C","isCorrect":true,"quote":"The restaurant is most famous for its jerk chicken.","viQuote":"Nhà hàng nổi tiếng nhất với món gà nướng kiểu Jamaica."}],"evQuotes":["The restaurant is most famous for its jerk chicken."]},{"q":193,"part":7,"group_id":"E25_T01_G191_195","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc25.webp","web_assets/ets2025/p67/E25_T01_rc26.webp"],"stem_en":"What is suggested about Ms. Peterkin's visit to Orange Bay Kitchen?","stem_vi":"Điều gì được suy ra về lần ghé thăm Orange Bay Kitchen của bà Peterkin?","options":{"A":{"en":"She was there on a Friday.","vi":"Bà ấy đã đến đó vào một ngày thứ Sáu."},"B":{"en":"She dined alone.","vi":"Bà ấy đã dùng bữa một mình."},"C":{"en":"She requested extra rice.","vi":"Bà ấy đã gọi thêm cơm."},"D":{"en":"She ordered dessert.","vi":"Bà ấy đã gọi món tráng miệng."}},"ans":"A","evidence_quote":"- In the review: My husband and I arrived there at 7 P.M. yesterday, keen to enjoy live music with our dinner. Unfortunately, the band's performance that night had been cancelled. - In the article: If you stop in on any Friday night between 7 and 11 PM., you will enjoy live reggae music.","explanation":"Đáp án đúng: (A) Bà ấy đã đến đó vào một ngày thứ Sáu — Bà Peterkin đến nhà hàng lúc 7 giờ tối với mong muốn thưởng thức nhạc sống khi dùng bữa, mà theo bài báo thì nhạc sống chỉ biểu diễn vào tối thứ Sáu từ 7 đến 11 giờ.\nDẫn chứng: Document 2 ghi \"My husband and I arrived there at 7 P.M. yesterday, keen to enjoy live music with our dinner. Unfortunately, the band's performance that night had been cancelled\"; liên kết Document 1 ghi \"If you stop in on any Friday night between 7 and 11 P.M., you will enjoy live reggae music.\"\nPhân tích bẫy:\n- (B) Bẫy trái ngược chi tiết: Document 2 ghi rõ bà ấy đi cùng chồng ('My husband and I arrived there at 7 P.M. yesterday'), không phải đi ăn một mình.\n- (C) Bẫy thay đổi danh từ món ăn: Do phần ăn nhỏ, hai vợ chồng gọi thêm một món khai vị ('ordered another appetiser'), không phải gọi thêm cơm ('coconut rice').\n- (D) Bẫy suy diễn sai loại món: Họ gọi thêm món khai vị ('another appetiser') để khỏi đói khi ra về, bài đánh giá không hề nhắc đến món tráng miệng.","lines":[{"speaker":"Document 1 — Article","en":"Caribbean Flavours Abound","vi":"Tràn ngập hương vị vùng Caribe","units":[{"en":"Caribbean Flavours Abound","vi":"Tràn ngập hương vị vùng Caribe"}]},{"speaker":"Document 1 — Article","en":"By Rebecca Roats","vi":"Tác giả: Rebecca Roats","units":[{"en":"By Rebecca Roats","vi":"Tác giả: Rebecca Roats"}]},{"speaker":"Document 1 — Article","en":"NOTTINGHAM (1 August)—Orange Bay Kitchen has been serving up an infusion of Jamaican flavours in a laid-back Caribbean atmosphere for six months now. Managed by Keron Deslandes, the 150-seat restaurant is an aromatic jewel amid the bustling shops and eateries in Wester Square. The servers are always happy to help diners select from the variety of delights on the extensive menu, which includes curried goat, oxtail soup, and red snapper. The restaurant is most famous for its jerk chicken. Marinated for 24 hours prior to grilling and served with sides of stewed cabbage and coconut rice, the dish is a good deal at £12.","vi":"NOTTINGHAM (ngày 1 tháng 8) — Suốt sáu tháng qua, Orange Bay Kitchen đã mang đến sự hòa quyện đậm đà của hương vị Jamaica trong không gian vùng Caribe đầy thư thái. Do Keron Deslandes quản lý, nhà hàng 150 chỗ ngồi này tựa như một viên ngọc ngát hương giữa khu mua sắm và ăn uống nhộn nhịp tại Quảng trường Wester. Đội ngũ phục vụ luôn sẵn lòng hỗ trợ thực khách lựa chọn từ thực đơn phong phú các món ngon, bao gồm cà ri dê, súp đuôi bò và cá hồng. Nhà hàng nổi tiếng nhất với món gà nướng kiểu Jamaica. Được tẩm ướp suốt 24 giờ trước khi nướng và dùng kèm bắp cải hầm cùng cơm cốt dừa, món ăn này có mức giá rất hợp lý là £12.","units":[{"en":"NOTTINGHAM (1 August)—Orange Bay Kitchen has been serving up an infusion of Jamaican flavours in a laid-back Caribbean atmosphere for six months now.","vi":"NOTTINGHAM (ngày 1 tháng 8) — Suốt sáu tháng qua, Orange Bay Kitchen đã mang đến sự hòa quyện đậm đà của hương vị Jamaica trong không gian vùng Caribe đầy thư thái."},{"en":"Managed by Keron Deslandes, the 150-seat restaurant is an aromatic jewel amid the bustling shops and eateries in Wester Square.","vi":"Do Keron Deslandes quản lý, nhà hàng 150 chỗ ngồi này tựa như một viên ngọc ngát hương giữa khu mua sắm và ăn uống nhộn nhịp tại Quảng trường Wester."},{"en":"The servers are always happy to help diners select from the variety of delights on the extensive menu, which includes curried goat, oxtail soup, and red snapper.","vi":"Đội ngũ phục vụ luôn sẵn lòng hỗ trợ thực khách lựa chọn từ thực đơn phong phú các món ngon, bao gồm cà ri dê, súp đuôi bò và cá hồng."},{"en":"The restaurant is most famous for its jerk chicken.","vi":"Nhà hàng nổi tiếng nhất với món gà nướng kiểu Jamaica."},{"en":"Marinated for 24 hours prior to grilling and served with sides of stewed cabbage and coconut rice, the dish is a good deal at £12.","vi":"Được tẩm ướp suốt 24 giờ trước khi nướng và dùng kèm bắp cải hầm cùng cơm cốt dừa, món ăn này có mức giá rất hợp lý là £12."}]},{"speaker":"Document 1 — Article","en":"If you stop in on any Friday night between 7 and 11 P.M., you will enjoy live reggae music.","vi":"Nếu ghé quán vào bất kỳ tối thứ Sáu nào từ 7 đến 11 giờ tối, bạn sẽ được thưởng thức nhạc reggae biểu diễn trực tiếp.","units":[{"en":"If you stop in on any Friday night between 7 and 11 P.M., you will enjoy live reggae music.","vi":"Nếu ghé quán vào bất kỳ tối thứ Sáu nào từ 7 đến 11 giờ tối, bạn sẽ được thưởng thức nhạc reggae biểu diễn trực tiếp."}]},{"speaker":"Document 2 — Review","en":"https://www.dinerreviews.co.uk/orangebaykitchen","vi":"https://www.dinerreviews.co.uk/orangebaykitchen","units":[{"en":"https://www.dinerreviews.co.uk/orangebaykitchen","vi":"https://www.dinerreviews.co.uk/orangebaykitchen"}]},{"speaker":"Document 2 — Review","en":"Posted on 22 August by Tamika Peterkin, tpeterkin@sunmail.co.uk","vi":"Đăng ngày 22 tháng 8 bởi Tamika Peterkin, tpeterkin@sunmail.co.uk","units":[{"en":"Posted on 22 August by Tamika Peterkin, tpeterkin@sunmail.co.uk","vi":"Đăng ngày 22 tháng 8 bởi Tamika Peterkin, tpeterkin@sunmail.co.uk"}]},{"speaker":"Document 2 — Review","en":"Orange Bay Kitchen: 2/5 Stars","vi":"Orange Bay Kitchen: 2/5 Sao","units":[{"en":"Orange Bay Kitchen: 2/5 Stars","vi":"Orange Bay Kitchen: 2/5 Sao"}]},{"speaker":"Document 2 — Review","en":"After reading a glowing article about Orange Bay Kitchen by Rebecca Roats, I was eager to give this place a try. My husband and I arrived there at 7 P.M. yesterday, keen to enjoy live music with our dinner. Unfortunately, the band's performance that night had been cancelled. Undeterred, we stayed and both ordered the jerk chicken. While the chicken's smoky flavour was outstanding, the stewed cabbage was lacking in flavour. Also, the portion size was smaller than we had anticipated, so we ordered another appetiser to avoid going home hungry. The head chef came out to apologise and was extremely nice, but we will probably not go back anytime soon.","vi":"Sau khi đọc bài viết khen ngợi hết lời về Orange Bay Kitchen của Rebecca Roats, tôi rất háo hức muốn đến trải nghiệm thử. Chồng tôi và tôi đến quán lúc 7 giờ tối hôm qua, mong chờ được thưởng thức nhạc sống cùng bữa tối. Thật không may, buổi biểu diễn tối hôm đó của ban nhạc đã bị hủy. Không nản lòng, chúng tôi vẫn nán lại và cả hai đều gọi món gà nướng kiểu Jamaica. Dù hương vị khói của thịt gà rất xuất sắc, món bắp cải hầm lại khá nhạt nhòa. Ngoài ra, khẩu phần ăn cũng nhỏ hơn dự kiến của chúng tôi, nên chúng tôi đã gọi thêm một món khai vị nữa để khỏi phải về nhà với cái bụng đói. Bếp trưởng đã ra tận bàn xin lỗi và rất nhã nhặn, nhưng có lẽ chúng tôi sẽ chưa quay lại trong thời gian tới.","units":[{"en":"After reading a glowing article about Orange Bay Kitchen by Rebecca Roats, I was eager to give this place a try.","vi":"Sau khi đọc bài viết khen ngợi hết lời về Orange Bay Kitchen của Rebecca Roats, tôi rất háo hức muốn đến trải nghiệm thử."},{"en":"My husband and I arrived there at 7 P.M. yesterday, keen to enjoy live music with our dinner.","vi":"Chồng tôi và tôi đến quán lúc 7 giờ tối hôm qua, mong chờ được thưởng thức nhạc sống cùng bữa tối."},{"en":"Unfortunately, the band's performance that night had been cancelled.","vi":"Thật không may, buổi biểu diễn tối hôm đó của ban nhạc đã bị hủy."},{"en":"Undeterred, we stayed and both ordered the jerk chicken.","vi":"Không nản lòng, chúng tôi vẫn nán lại và cả hai đều gọi món gà nướng kiểu Jamaica."},{"en":"While the chicken's smoky flavour was outstanding, the stewed cabbage was lacking in flavour.","vi":"Dù hương vị khói của thịt gà rất xuất sắc, món bắp cải hầm lại khá nhạt nhòa."},{"en":"Also, the portion size was smaller than we had anticipated, so we ordered another appetiser to avoid going home hungry.","vi":"Ngoài ra, khẩu phần ăn cũng nhỏ hơn dự kiến của chúng tôi, nên chúng tôi đã gọi thêm một món khai vị nữa để khỏi phải về nhà với cái bụng đói."},{"en":"The head chef came out to apologise and was extremely nice, but we will probably not go back anytime soon.","vi":"Bếp trưởng đã ra tận bàn xin lỗi và rất nhã nhặn, nhưng có lẽ chúng tôi sẽ chưa quay lại trong thời gian tới."}]},{"speaker":"Document 3 — E-mail","en":"To: tpeterkin@sunmail.co.uk","vi":"Đến: tpeterkin@sunmail.co.uk","units":[{"en":"To: tpeterkin@sunmail.co.uk","vi":"Đến: tpeterkin@sunmail.co.uk"}]},{"speaker":"Document 3 — E-mail","en":"From: vsmith@orangebaykitchen.co.uk","vi":"Từ: vsmith@orangebaykitchen.co.uk","units":[{"en":"From: vsmith@orangebaykitchen.co.uk","vi":"Từ: vsmith@orangebaykitchen.co.uk"}]},{"speaker":"Document 3 — E-mail","en":"Date: 24 August","vi":"Ngày: 24 tháng 8","units":[{"en":"Date: 24 August","vi":"Ngày: 24 tháng 8"}]},{"speaker":"Document 3 — E-mail","en":"Subject: Your review","vi":"Chủ đề: Đánh giá của bạn","units":[{"en":"Subject: Your review","vi":"Chủ đề: Đánh giá của bạn"}]},{"speaker":"Document 3 — E-mail","en":"Attachment: 0258","vi":"Tệp đính kèm: 0258","units":[{"en":"Attachment: 0258","vi":"Tệp đính kèm: 0258"}]},{"speaker":"Document 3 — E-mail","en":"Dear Ms. Peterkin,","vi":"Kính gửi bà Peterkin,","units":[{"en":"Dear Ms. Peterkin,","vi":"Kính gửi bà Peterkin,"}]},{"speaker":"Document 3 — E-mail","en":"Thank you for visiting Orange Bay Kitchen and leaving a review. Our manager, Keron Deslandes, told me more about your visit and our failure to live up to your expectations that evening. Please accept the attached £20 gift certificate; I do hope that you will give us another try.","vi":"Cảm ơn bà đã ghé thăm Orange Bay Kitchen và để lại đánh giá. Quản lý của chúng tôi, Keron Deslandes, đã trao đổi với tôi về chuyến ghé thăm của bà cũng như việc chúng tôi đã chưa đáp ứng được kỳ vọng của bà vào tối hôm đó. Xin bà vui lòng nhận phiếu quà tặng trị giá £20 đính kèm; tôi rất hy vọng bà sẽ cho chúng tôi một cơ hội phục vụ lại.","units":[{"en":"Thank you for visiting Orange Bay Kitchen and leaving a review.","vi":"Cảm ơn bà đã ghé thăm Orange Bay Kitchen và để lại đánh giá."},{"en":"Our manager, Keron Deslandes, told me more about your visit and our failure to live up to your expectations that evening.","vi":"Quản lý của chúng tôi, Keron Deslandes, đã trao đổi với tôi về chuyến ghé thăm của bà cũng như việc chúng tôi đã chưa đáp ứng được kỳ vọng của bà vào tối hôm đó."},{"en":"Please accept the attached £20 gift certificate; I do hope that you will give us another try.","vi":"Xin bà vui lòng nhận phiếu quà tặng trị giá £20 đính kèm; tôi rất hy vọng bà sẽ cho chúng tôi một cơ hội phục vụ lại."}]},{"speaker":"Document 3 — E-mail","en":"During your visit, our band had an equipment malfunction, which is what led to the last-minute cancellation. However, the band will be back performing weekly beginning in September. Also, I want you to know that Head Chef Adio Brown has changed the spices he uses in the stewed cabbage. I am sure you will find them delightful.","vi":"Vào buổi tối bà ghé quán, ban nhạc của chúng tôi gặp sự cố thiết bị nên buộc phải hủy buổi diễn vào phút chót. Tuy nhiên, ban nhạc sẽ trở lại biểu diễn hằng tuần bắt đầu từ tháng 9. Bên cạnh đó, tôi cũng xin thông báo rằng Bếp trưởng Adio Brown đã điều chỉnh lại gia vị cho món bắp cải hầm. Tôi tin chắc bà sẽ thấy hương vị mới rất tuyệt vời.","units":[{"en":"During your visit, our band had an equipment malfunction, which is what led to the last-minute cancellation.","vi":"Vào buổi tối bà ghé quán, ban nhạc của chúng tôi gặp sự cố thiết bị nên buộc phải hủy buổi diễn vào phút chót."},{"en":"However, the band will be back performing weekly beginning in September.","vi":"Tuy nhiên, ban nhạc sẽ trở lại biểu diễn hằng tuần bắt đầu từ tháng 9."},{"en":"Also, I want you to know that Head Chef Adio Brown has changed the spices he uses in the stewed cabbage.","vi":"Bên cạnh đó, tôi cũng xin thông báo rằng Bếp trưởng Adio Brown đã điều chỉnh lại gia vị cho món bắp cải hầm."},{"en":"I am sure you will find them delightful.","vi":"Tôi tin chắc bà sẽ thấy hương vị mới rất tuyệt vời."}]},{"speaker":"Document 3 — E-mail","en":"Sincerely,","vi":"Trân trọng,","units":[{"en":"Sincerely,","vi":"Trân trọng,"}]},{"speaker":"Document 3 — E-mail","en":"Vea Smith, Owner, Orange Bay Kitchen","vi":"Vea Smith, Chủ sở hữu, Orange Bay Kitchen","units":[{"en":"Vea Smith, Owner, Orange Bay Kitchen","vi":"Vea Smith, Chủ sở hữu, Orange Bay Kitchen"}]}],"vocab":[{"word":"eager","pos":"adj","ipa":"/ˈiːɡər/","meaning":"háo hức, mong chờ"},{"word":"undeterred","pos":"adj","ipa":"/ˌʌndɪˈtɜːrd/","meaning":"không nản lòng"},{"word":"anticipate","pos":"v","ipa":"/ænˈtɪsɪpeɪt/","meaning":"dự kiến, mong đợi"},{"word":"portion size","pos":"n","ipa":"/ˈpɔːrʃən saɪz/","meaning":"kích cỡ khẩu phần ăn"}],"isScanBacked":false,"docTypeLabel":"article, review, and e-mail","context":"Article, review, and e-mail — Orange Bay Kitchen","grammarType":"Part 7 — Suy luận & Hàm ý văn bản (Inference & Implied Meaning)","formula":"CÔNG THỨC PART 7 — SUY LUẬN LỊCH BIỂU DIỄN (DOCUMENT 1 + DOCUMENT 2): Ghép lịch nhạc sống cố định ở Document 1 ('any Friday night between 7 and 11 P.M.') với giờ đến 7 P.M. để nghe nhạc sống ở Document 2 -> Chốt thứ Sáu.","optionAnalysis":{"A":"Đúng vì bà Peterkin đến lúc 7 P.M. để nghe nhạc sống (Document 2), mà theo Document 1 nhạc sống chỉ diễn ra vào tối thứ Sáu từ 7 đến 11 P.M.","B":"Sai vì trái với Document 2: bà Peterkin đi ăn tối cùng chồng ('My husband and I arrived there at 7 P.M. yesterday' và 'we stayed and both ordered').","C":"Sai vì khi thấy khẩu phần nhỏ, hai người đã gọi thêm một món khai vị ('another appetiser'), không hề yêu cầu thêm cơm.","D":"Sai vì Document 2 chỉ nhắc họ gọi thêm món khai vị ('another appetiser') cho đỡ đói, không đề cập việc gọi món tráng miệng."},"evDocIdx":1,"evTargets":[{"badge":"Câu 193 · Đáp án A","opt":"A","isCorrect":true,"quote":"My husband and I arrived there at 7 P.M. yesterday, keen to enjoy live music with our dinner.","viQuote":"Chồng tôi và tôi đến quán lúc 7 giờ tối hôm qua, mong chờ được thưởng thức nhạc sống cùng bữa tối."},{"badge":"Câu 193 · Đáp án A","opt":"A","isCorrect":true,"quote":"If you stop in on any Friday night between 7 and 11 P.M., you will enjoy live reggae music.","viQuote":"Nếu ghé quán vào bất kỳ tối thứ Sáu nào từ 7 đến 11 giờ tối, bạn sẽ được thưởng thức nhạc reggae biểu diễn trực tiếp."}],"evQuotes":["My husband and I arrived there at 7 P.M. yesterday, keen to enjoy live music with our dinner.","If you stop in on any Friday night between 7 and 11 P.M., you will enjoy live reggae music."]},{"q":194,"part":7,"group_id":"E25_T01_G191_195","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc25.webp","web_assets/ets2025/p67/E25_T01_rc26.webp"],"stem_en":"What is a purpose of the e-mail?","stem_vi":"Một trong những mục đích của e-mail là gì?","options":{"A":{"en":"To answer a question","vi":"Để giải đáp một thắc mắc"},"B":{"en":"To offer an apology","vi":"Để gửi lời xin lỗi"},"C":{"en":"To ask for feedback","vi":"Để xin ý kiến phản hồi"},"D":{"en":"To confirm a reservation","vi":"Để xác nhận lịch đặt bàn"}},"ans":"B","evidence_quote":"Our manager, Keron Deslandes, told me more about your visit and our failure to live up to your expectations that evening. Please accept the attached £20 gift certificate; I do hope that you will give us another try.","explanation":"Đáp án đúng: (B) Để gửi lời xin lỗi — Chủ nhà hàng Vea Smith gửi e-mail bày tỏ sự áy náy vì trải nghiệm chưa đạt kỳ vọng, giải thích sự cố ban nhạc, báo đã đổi gia vị món bắp cải và tặng phiếu £20 mong bà quay lại.\nDẫn chứng: \"Our manager, Keron Deslandes, told me more about your visit and our failure to live up to your expectations that evening. Please accept the attached £20 gift certificate; I do hope that you will give us another try.\" (Document 3 — E-mail: thừa nhận thiếu sót và tặng voucher đền bù là hành động xin lỗi khách hàng).\nPhân tích bẫy:\n- (A) Bẫy đoán mục đích sai: Trong bài đánh giá ở Document 2, bà Peterkin chỉ chia sẻ trải nghiệm và chấm 2/5 sao, không đặt câu hỏi nào cần giải đáp.\n- (C) Bẫy đảo trình tự sự việc: Bà Peterkin đã viết đánh giá công khai trước đó ('leaving a review'), nên e-mail không nhằm hỏi xin ý kiến nhận xét nữa.\n- (D) Bẫy từ khóa ngoài ngữ cảnh: Chủ quán chỉ hy vọng bà cho nhà hàng cơ hội thứ hai ('give us another try'), không hề xác nhận lịch đặt bàn nào.","lines":[{"speaker":"Document 1 — Article","en":"Caribbean Flavours Abound","vi":"Tràn ngập hương vị vùng Caribe","units":[{"en":"Caribbean Flavours Abound","vi":"Tràn ngập hương vị vùng Caribe"}]},{"speaker":"Document 1 — Article","en":"By Rebecca Roats","vi":"Tác giả: Rebecca Roats","units":[{"en":"By Rebecca Roats","vi":"Tác giả: Rebecca Roats"}]},{"speaker":"Document 1 — Article","en":"NOTTINGHAM (1 August)—Orange Bay Kitchen has been serving up an infusion of Jamaican flavours in a laid-back Caribbean atmosphere for six months now. Managed by Keron Deslandes, the 150-seat restaurant is an aromatic jewel amid the bustling shops and eateries in Wester Square. The servers are always happy to help diners select from the variety of delights on the extensive menu, which includes curried goat, oxtail soup, and red snapper. The restaurant is most famous for its jerk chicken. Marinated for 24 hours prior to grilling and served with sides of stewed cabbage and coconut rice, the dish is a good deal at £12.","vi":"NOTTINGHAM (ngày 1 tháng 8) — Suốt sáu tháng qua, Orange Bay Kitchen đã mang đến sự hòa quyện đậm đà của hương vị Jamaica trong không gian vùng Caribe đầy thư thái. Do Keron Deslandes quản lý, nhà hàng 150 chỗ ngồi này tựa như một viên ngọc ngát hương giữa khu mua sắm và ăn uống nhộn nhịp tại Quảng trường Wester. Đội ngũ phục vụ luôn sẵn lòng hỗ trợ thực khách lựa chọn từ thực đơn phong phú các món ngon, bao gồm cà ri dê, súp đuôi bò và cá hồng. Nhà hàng nổi tiếng nhất với món gà nướng kiểu Jamaica. Được tẩm ướp suốt 24 giờ trước khi nướng và dùng kèm bắp cải hầm cùng cơm cốt dừa, món ăn này có mức giá rất hợp lý là £12.","units":[{"en":"NOTTINGHAM (1 August)—Orange Bay Kitchen has been serving up an infusion of Jamaican flavours in a laid-back Caribbean atmosphere for six months now.","vi":"NOTTINGHAM (ngày 1 tháng 8) — Suốt sáu tháng qua, Orange Bay Kitchen đã mang đến sự hòa quyện đậm đà của hương vị Jamaica trong không gian vùng Caribe đầy thư thái."},{"en":"Managed by Keron Deslandes, the 150-seat restaurant is an aromatic jewel amid the bustling shops and eateries in Wester Square.","vi":"Do Keron Deslandes quản lý, nhà hàng 150 chỗ ngồi này tựa như một viên ngọc ngát hương giữa khu mua sắm và ăn uống nhộn nhịp tại Quảng trường Wester."},{"en":"The servers are always happy to help diners select from the variety of delights on the extensive menu, which includes curried goat, oxtail soup, and red snapper.","vi":"Đội ngũ phục vụ luôn sẵn lòng hỗ trợ thực khách lựa chọn từ thực đơn phong phú các món ngon, bao gồm cà ri dê, súp đuôi bò và cá hồng."},{"en":"The restaurant is most famous for its jerk chicken.","vi":"Nhà hàng nổi tiếng nhất với món gà nướng kiểu Jamaica."},{"en":"Marinated for 24 hours prior to grilling and served with sides of stewed cabbage and coconut rice, the dish is a good deal at £12.","vi":"Được tẩm ướp suốt 24 giờ trước khi nướng và dùng kèm bắp cải hầm cùng cơm cốt dừa, món ăn này có mức giá rất hợp lý là £12."}]},{"speaker":"Document 1 — Article","en":"If you stop in on any Friday night between 7 and 11 P.M., you will enjoy live reggae music.","vi":"Nếu ghé quán vào bất kỳ tối thứ Sáu nào từ 7 đến 11 giờ tối, bạn sẽ được thưởng thức nhạc reggae biểu diễn trực tiếp.","units":[{"en":"If you stop in on any Friday night between 7 and 11 P.M., you will enjoy live reggae music.","vi":"Nếu ghé quán vào bất kỳ tối thứ Sáu nào từ 7 đến 11 giờ tối, bạn sẽ được thưởng thức nhạc reggae biểu diễn trực tiếp."}]},{"speaker":"Document 2 — Review","en":"https://www.dinerreviews.co.uk/orangebaykitchen","vi":"https://www.dinerreviews.co.uk/orangebaykitchen","units":[{"en":"https://www.dinerreviews.co.uk/orangebaykitchen","vi":"https://www.dinerreviews.co.uk/orangebaykitchen"}]},{"speaker":"Document 2 — Review","en":"Posted on 22 August by Tamika Peterkin, tpeterkin@sunmail.co.uk","vi":"Đăng ngày 22 tháng 8 bởi Tamika Peterkin, tpeterkin@sunmail.co.uk","units":[{"en":"Posted on 22 August by Tamika Peterkin, tpeterkin@sunmail.co.uk","vi":"Đăng ngày 22 tháng 8 bởi Tamika Peterkin, tpeterkin@sunmail.co.uk"}]},{"speaker":"Document 2 — Review","en":"Orange Bay Kitchen: 2/5 Stars","vi":"Orange Bay Kitchen: 2/5 Sao","units":[{"en":"Orange Bay Kitchen: 2/5 Stars","vi":"Orange Bay Kitchen: 2/5 Sao"}]},{"speaker":"Document 2 — Review","en":"After reading a glowing article about Orange Bay Kitchen by Rebecca Roats, I was eager to give this place a try. My husband and I arrived there at 7 P.M. yesterday, keen to enjoy live music with our dinner. Unfortunately, the band's performance that night had been cancelled. Undeterred, we stayed and both ordered the jerk chicken. While the chicken's smoky flavour was outstanding, the stewed cabbage was lacking in flavour. Also, the portion size was smaller than we had anticipated, so we ordered another appetiser to avoid going home hungry. The head chef came out to apologise and was extremely nice, but we will probably not go back anytime soon.","vi":"Sau khi đọc bài viết khen ngợi hết lời về Orange Bay Kitchen của Rebecca Roats, tôi rất háo hức muốn đến trải nghiệm thử. Chồng tôi và tôi đến quán lúc 7 giờ tối hôm qua, mong chờ được thưởng thức nhạc sống cùng bữa tối. Thật không may, buổi biểu diễn tối hôm đó của ban nhạc đã bị hủy. Không nản lòng, chúng tôi vẫn nán lại và cả hai đều gọi món gà nướng kiểu Jamaica. Dù hương vị khói của thịt gà rất xuất sắc, món bắp cải hầm lại khá nhạt nhòa. Ngoài ra, khẩu phần ăn cũng nhỏ hơn dự kiến của chúng tôi, nên chúng tôi đã gọi thêm một món khai vị nữa để khỏi phải về nhà với cái bụng đói. Bếp trưởng đã ra tận bàn xin lỗi và rất nhã nhặn, nhưng có lẽ chúng tôi sẽ chưa quay lại trong thời gian tới.","units":[{"en":"After reading a glowing article about Orange Bay Kitchen by Rebecca Roats, I was eager to give this place a try.","vi":"Sau khi đọc bài viết khen ngợi hết lời về Orange Bay Kitchen của Rebecca Roats, tôi rất háo hức muốn đến trải nghiệm thử."},{"en":"My husband and I arrived there at 7 P.M. yesterday, keen to enjoy live music with our dinner.","vi":"Chồng tôi và tôi đến quán lúc 7 giờ tối hôm qua, mong chờ được thưởng thức nhạc sống cùng bữa tối."},{"en":"Unfortunately, the band's performance that night had been cancelled.","vi":"Thật không may, buổi biểu diễn tối hôm đó của ban nhạc đã bị hủy."},{"en":"Undeterred, we stayed and both ordered the jerk chicken.","vi":"Không nản lòng, chúng tôi vẫn nán lại và cả hai đều gọi món gà nướng kiểu Jamaica."},{"en":"While the chicken's smoky flavour was outstanding, the stewed cabbage was lacking in flavour.","vi":"Dù hương vị khói của thịt gà rất xuất sắc, món bắp cải hầm lại khá nhạt nhòa."},{"en":"Also, the portion size was smaller than we had anticipated, so we ordered another appetiser to avoid going home hungry.","vi":"Ngoài ra, khẩu phần ăn cũng nhỏ hơn dự kiến của chúng tôi, nên chúng tôi đã gọi thêm một món khai vị nữa để khỏi phải về nhà với cái bụng đói."},{"en":"The head chef came out to apologise and was extremely nice, but we will probably not go back anytime soon.","vi":"Bếp trưởng đã ra tận bàn xin lỗi và rất nhã nhặn, nhưng có lẽ chúng tôi sẽ chưa quay lại trong thời gian tới."}]},{"speaker":"Document 3 — E-mail","en":"To: tpeterkin@sunmail.co.uk","vi":"Đến: tpeterkin@sunmail.co.uk","units":[{"en":"To: tpeterkin@sunmail.co.uk","vi":"Đến: tpeterkin@sunmail.co.uk"}]},{"speaker":"Document 3 — E-mail","en":"From: vsmith@orangebaykitchen.co.uk","vi":"Từ: vsmith@orangebaykitchen.co.uk","units":[{"en":"From: vsmith@orangebaykitchen.co.uk","vi":"Từ: vsmith@orangebaykitchen.co.uk"}]},{"speaker":"Document 3 — E-mail","en":"Date: 24 August","vi":"Ngày: 24 tháng 8","units":[{"en":"Date: 24 August","vi":"Ngày: 24 tháng 8"}]},{"speaker":"Document 3 — E-mail","en":"Subject: Your review","vi":"Chủ đề: Đánh giá của bạn","units":[{"en":"Subject: Your review","vi":"Chủ đề: Đánh giá của bạn"}]},{"speaker":"Document 3 — E-mail","en":"Attachment: 0258","vi":"Tệp đính kèm: 0258","units":[{"en":"Attachment: 0258","vi":"Tệp đính kèm: 0258"}]},{"speaker":"Document 3 — E-mail","en":"Dear Ms. Peterkin,","vi":"Kính gửi bà Peterkin,","units":[{"en":"Dear Ms. Peterkin,","vi":"Kính gửi bà Peterkin,"}]},{"speaker":"Document 3 — E-mail","en":"Thank you for visiting Orange Bay Kitchen and leaving a review. Our manager, Keron Deslandes, told me more about your visit and our failure to live up to your expectations that evening. Please accept the attached £20 gift certificate; I do hope that you will give us another try.","vi":"Cảm ơn bà đã ghé thăm Orange Bay Kitchen và để lại đánh giá. Quản lý của chúng tôi, Keron Deslandes, đã trao đổi với tôi về chuyến ghé thăm của bà cũng như việc chúng tôi đã chưa đáp ứng được kỳ vọng của bà vào tối hôm đó. Xin bà vui lòng nhận phiếu quà tặng trị giá £20 đính kèm; tôi rất hy vọng bà sẽ cho chúng tôi một cơ hội phục vụ lại.","units":[{"en":"Thank you for visiting Orange Bay Kitchen and leaving a review.","vi":"Cảm ơn bà đã ghé thăm Orange Bay Kitchen và để lại đánh giá."},{"en":"Our manager, Keron Deslandes, told me more about your visit and our failure to live up to your expectations that evening.","vi":"Quản lý của chúng tôi, Keron Deslandes, đã trao đổi với tôi về chuyến ghé thăm của bà cũng như việc chúng tôi đã chưa đáp ứng được kỳ vọng của bà vào tối hôm đó."},{"en":"Please accept the attached £20 gift certificate; I do hope that you will give us another try.","vi":"Xin bà vui lòng nhận phiếu quà tặng trị giá £20 đính kèm; tôi rất hy vọng bà sẽ cho chúng tôi một cơ hội phục vụ lại."}]},{"speaker":"Document 3 — E-mail","en":"During your visit, our band had an equipment malfunction, which is what led to the last-minute cancellation. However, the band will be back performing weekly beginning in September. Also, I want you to know that Head Chef Adio Brown has changed the spices he uses in the stewed cabbage. I am sure you will find them delightful.","vi":"Vào buổi tối bà ghé quán, ban nhạc của chúng tôi gặp sự cố thiết bị nên buộc phải hủy buổi diễn vào phút chót. Tuy nhiên, ban nhạc sẽ trở lại biểu diễn hằng tuần bắt đầu từ tháng 9. Bên cạnh đó, tôi cũng xin thông báo rằng Bếp trưởng Adio Brown đã điều chỉnh lại gia vị cho món bắp cải hầm. Tôi tin chắc bà sẽ thấy hương vị mới rất tuyệt vời.","units":[{"en":"During your visit, our band had an equipment malfunction, which is what led to the last-minute cancellation.","vi":"Vào buổi tối bà ghé quán, ban nhạc của chúng tôi gặp sự cố thiết bị nên buộc phải hủy buổi diễn vào phút chót."},{"en":"However, the band will be back performing weekly beginning in September.","vi":"Tuy nhiên, ban nhạc sẽ trở lại biểu diễn hằng tuần bắt đầu từ tháng 9."},{"en":"Also, I want you to know that Head Chef Adio Brown has changed the spices he uses in the stewed cabbage.","vi":"Bên cạnh đó, tôi cũng xin thông báo rằng Bếp trưởng Adio Brown đã điều chỉnh lại gia vị cho món bắp cải hầm."},{"en":"I am sure you will find them delightful.","vi":"Tôi tin chắc bà sẽ thấy hương vị mới rất tuyệt vời."}]},{"speaker":"Document 3 — E-mail","en":"Sincerely,","vi":"Trân trọng,","units":[{"en":"Sincerely,","vi":"Trân trọng,"}]},{"speaker":"Document 3 — E-mail","en":"Vea Smith, Owner, Orange Bay Kitchen","vi":"Vea Smith, Chủ sở hữu, Orange Bay Kitchen","units":[{"en":"Vea Smith, Owner, Orange Bay Kitchen","vi":"Vea Smith, Chủ sở hữu, Orange Bay Kitchen"}]}],"vocab":[{"word":"live up to","pos":"phr. v","ipa":"/lɪv ʌp tuː/","meaning":"đáp ứng được (kỳ vọng)"},{"word":"gift certificate","pos":"n","ipa":"/ˈɡɪft sərˌtɪfɪkət/","meaning":"phiếu quà tặng"},{"word":"malfunction","pos":"n","ipa":"/ˌmælˈfʌŋkʃən/","meaning":"sự cố, trục trặc kỹ thuật"},{"word":"last-minute","pos":"adj","ipa":"/ˌlæst ˈmɪnɪt/","meaning":"vào phút chót"}],"isScanBacked":false,"docTypeLabel":"article, review, and e-mail","context":"Article, review, and e-mail — Orange Bay Kitchen","grammarType":"Part 7 — Ý chính, Mục đích & Đối tượng đọc (Main Idea & Purpose)","formula":"CÔNG THỨC PART 7 — XÁC ĐỊNH MỤC ĐÍCH E-MAIL CHĂM SÓC KHÁCH HÀNG (DOCUMENT 3): Nhận diện lời thừa nhận thiếu sót ('failure to live up to your expectations') + quà đền bù ('£20 gift certificate') -> Mục đích xin lỗi.","optionAnalysis":{"A":"Sai vì bài đánh giá của bà Peterkin ở Document 2 chỉ nhận xét trải nghiệm bữa tối, không nêu câu hỏi nào để chủ quán trả lời.","B":"Đúng vì Document 3 thừa nhận thiếu sót không đáp ứng kỳ vọng ('failure to live up to your expectations') và gửi kèm phiếu quà tặng £20 để xin lỗi, mong khách quay lại.","C":"Sai vì bà Peterkin đã để lại đánh giá ('leaving a review') trước đó rồi; e-mail này phản hồi và khắc phục sự cố chứ không phải khảo sát xin phản hồi.","D":"Sai vì chủ quán chỉ bày tỏ hy vọng khách sẽ quay lại lần nữa ('give us another try'), không có thông tin đặt bàn trước cần xác nhận."},"evDocIdx":2,"evTargets":[{"badge":"Câu 194 · Đáp án B","opt":"B","isCorrect":true,"quote":"Our manager, Keron Deslandes, told me more about your visit and our failure to live up to your expectations that evening.","viQuote":"Quản lý của chúng tôi, Keron Deslandes, đã trao đổi với tôi về chuyến ghé thăm của bà cũng như việc chúng tôi đã chưa đáp ứng được kỳ vọng của bà vào tối hôm đó."},{"badge":"Câu 194 · Đáp án B","opt":"B","isCorrect":true,"quote":"Please accept the attached £20 gift certificate; I do hope that you will give us another try.","viQuote":"Xin bà vui lòng nhận phiếu quà tặng trị giá £20 đính kèm; tôi rất hy vọng bà sẽ cho chúng tôi một cơ hội phục vụ lại."}],"evQuotes":["Our manager, Keron Deslandes, told me more about your visit and our failure to live up to your expectations that evening.","Please accept the attached £20 gift certificate; I do hope that you will give us another try."]},{"q":195,"part":7,"group_id":"E25_T01_G191_195","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc25.webp","web_assets/ets2025/p67/E25_T01_rc26.webp"],"stem_en":"Whom did Ms. Peterkin meet at Orange Bay Kitchen?","stem_vi":"Bà Peterkin đã gặp ai tại Orange Bay Kitchen?","options":{"A":{"en":"Ms. Roats","vi":"Bà Roats"},"B":{"en":"Mr. Deslandes","vi":"Ông Deslandes"},"C":{"en":"Mr. Brown","vi":"Ông Brown"},"D":{"en":"Ms. Smith","vi":"Bà Smith"}},"ans":"C","evidence_quote":"- In the review: The head chef came out to apologise and was extremely nice, but we will probably not go back anytime soon. - In the email: Also, I want you to know that Head Chef Adio Brown has changed the spices he uses in the stewed cabbage.","explanation":"Đáp án đúng: (C) Ông Brown (Mr. Brown) — Bài đánh giá cho biết bếp trưởng đã ra xin lỗi trực tiếp, còn e-mail của chủ quán tiết lộ tên bếp trưởng là Adio Brown.\nDẫn chứng: Document 2 ghi \"The head chef came out to apologise and was extremely nice\"; đối chiếu Document 3 ghi \"Head Chef Adio Brown has changed the spices he uses in the stewed cabbage.\"\nPhân tích bẫy:\n- (A) Bẫy nhầm tên tác giả bài báo: Rebecca Roats (Document 1 & 2) là nhà báo viết bài giới thiệu nhà hàng, không làm việc tại quán.\n- (B) Bẫy nhầm chức danh quản lý: Keron Deslandes là quản lý nhà hàng ('Our manager'), người báo lại vụ việc cho chủ quán chứ không phải bếp trưởng trực tiếp ra xin lỗi.\n- (D) Bẫy nhầm chức danh chủ quán: Vea Smith là chủ nhà hàng ('Owner') viết e-mail ở Document 3 sau khi nghe quản lý kể lại, không trực tiếp gặp bà Peterkin hôm đó.","lines":[{"speaker":"Document 1 — Article","en":"Caribbean Flavours Abound","vi":"Tràn ngập hương vị vùng Caribe","units":[{"en":"Caribbean Flavours Abound","vi":"Tràn ngập hương vị vùng Caribe"}]},{"speaker":"Document 1 — Article","en":"By Rebecca Roats","vi":"Tác giả: Rebecca Roats","units":[{"en":"By Rebecca Roats","vi":"Tác giả: Rebecca Roats"}]},{"speaker":"Document 1 — Article","en":"NOTTINGHAM (1 August)—Orange Bay Kitchen has been serving up an infusion of Jamaican flavours in a laid-back Caribbean atmosphere for six months now. Managed by Keron Deslandes, the 150-seat restaurant is an aromatic jewel amid the bustling shops and eateries in Wester Square. The servers are always happy to help diners select from the variety of delights on the extensive menu, which includes curried goat, oxtail soup, and red snapper. The restaurant is most famous for its jerk chicken. Marinated for 24 hours prior to grilling and served with sides of stewed cabbage and coconut rice, the dish is a good deal at £12.","vi":"NOTTINGHAM (ngày 1 tháng 8) — Suốt sáu tháng qua, Orange Bay Kitchen đã mang đến sự hòa quyện đậm đà của hương vị Jamaica trong không gian vùng Caribe đầy thư thái. Do Keron Deslandes quản lý, nhà hàng 150 chỗ ngồi này tựa như một viên ngọc ngát hương giữa khu mua sắm và ăn uống nhộn nhịp tại Quảng trường Wester. Đội ngũ phục vụ luôn sẵn lòng hỗ trợ thực khách lựa chọn từ thực đơn phong phú các món ngon, bao gồm cà ri dê, súp đuôi bò và cá hồng. Nhà hàng nổi tiếng nhất với món gà nướng kiểu Jamaica. Được tẩm ướp suốt 24 giờ trước khi nướng và dùng kèm bắp cải hầm cùng cơm cốt dừa, món ăn này có mức giá rất hợp lý là £12.","units":[{"en":"NOTTINGHAM (1 August)—Orange Bay Kitchen has been serving up an infusion of Jamaican flavours in a laid-back Caribbean atmosphere for six months now.","vi":"NOTTINGHAM (ngày 1 tháng 8) — Suốt sáu tháng qua, Orange Bay Kitchen đã mang đến sự hòa quyện đậm đà của hương vị Jamaica trong không gian vùng Caribe đầy thư thái."},{"en":"Managed by Keron Deslandes, the 150-seat restaurant is an aromatic jewel amid the bustling shops and eateries in Wester Square.","vi":"Do Keron Deslandes quản lý, nhà hàng 150 chỗ ngồi này tựa như một viên ngọc ngát hương giữa khu mua sắm và ăn uống nhộn nhịp tại Quảng trường Wester."},{"en":"The servers are always happy to help diners select from the variety of delights on the extensive menu, which includes curried goat, oxtail soup, and red snapper.","vi":"Đội ngũ phục vụ luôn sẵn lòng hỗ trợ thực khách lựa chọn từ thực đơn phong phú các món ngon, bao gồm cà ri dê, súp đuôi bò và cá hồng."},{"en":"The restaurant is most famous for its jerk chicken.","vi":"Nhà hàng nổi tiếng nhất với món gà nướng kiểu Jamaica."},{"en":"Marinated for 24 hours prior to grilling and served with sides of stewed cabbage and coconut rice, the dish is a good deal at £12.","vi":"Được tẩm ướp suốt 24 giờ trước khi nướng và dùng kèm bắp cải hầm cùng cơm cốt dừa, món ăn này có mức giá rất hợp lý là £12."}]},{"speaker":"Document 1 — Article","en":"If you stop in on any Friday night between 7 and 11 P.M., you will enjoy live reggae music.","vi":"Nếu ghé quán vào bất kỳ tối thứ Sáu nào từ 7 đến 11 giờ tối, bạn sẽ được thưởng thức nhạc reggae biểu diễn trực tiếp.","units":[{"en":"If you stop in on any Friday night between 7 and 11 P.M., you will enjoy live reggae music.","vi":"Nếu ghé quán vào bất kỳ tối thứ Sáu nào từ 7 đến 11 giờ tối, bạn sẽ được thưởng thức nhạc reggae biểu diễn trực tiếp."}]},{"speaker":"Document 2 — Review","en":"https://www.dinerreviews.co.uk/orangebaykitchen","vi":"https://www.dinerreviews.co.uk/orangebaykitchen","units":[{"en":"https://www.dinerreviews.co.uk/orangebaykitchen","vi":"https://www.dinerreviews.co.uk/orangebaykitchen"}]},{"speaker":"Document 2 — Review","en":"Posted on 22 August by Tamika Peterkin, tpeterkin@sunmail.co.uk","vi":"Đăng ngày 22 tháng 8 bởi Tamika Peterkin, tpeterkin@sunmail.co.uk","units":[{"en":"Posted on 22 August by Tamika Peterkin, tpeterkin@sunmail.co.uk","vi":"Đăng ngày 22 tháng 8 bởi Tamika Peterkin, tpeterkin@sunmail.co.uk"}]},{"speaker":"Document 2 — Review","en":"Orange Bay Kitchen: 2/5 Stars","vi":"Orange Bay Kitchen: 2/5 Sao","units":[{"en":"Orange Bay Kitchen: 2/5 Stars","vi":"Orange Bay Kitchen: 2/5 Sao"}]},{"speaker":"Document 2 — Review","en":"After reading a glowing article about Orange Bay Kitchen by Rebecca Roats, I was eager to give this place a try. My husband and I arrived there at 7 P.M. yesterday, keen to enjoy live music with our dinner. Unfortunately, the band's performance that night had been cancelled. Undeterred, we stayed and both ordered the jerk chicken. While the chicken's smoky flavour was outstanding, the stewed cabbage was lacking in flavour. Also, the portion size was smaller than we had anticipated, so we ordered another appetiser to avoid going home hungry. The head chef came out to apologise and was extremely nice, but we will probably not go back anytime soon.","vi":"Sau khi đọc bài viết khen ngợi hết lời về Orange Bay Kitchen của Rebecca Roats, tôi rất háo hức muốn đến trải nghiệm thử. Chồng tôi và tôi đến quán lúc 7 giờ tối hôm qua, mong chờ được thưởng thức nhạc sống cùng bữa tối. Thật không may, buổi biểu diễn tối hôm đó của ban nhạc đã bị hủy. Không nản lòng, chúng tôi vẫn nán lại và cả hai đều gọi món gà nướng kiểu Jamaica. Dù hương vị khói của thịt gà rất xuất sắc, món bắp cải hầm lại khá nhạt nhòa. Ngoài ra, khẩu phần ăn cũng nhỏ hơn dự kiến của chúng tôi, nên chúng tôi đã gọi thêm một món khai vị nữa để khỏi phải về nhà với cái bụng đói. Bếp trưởng đã ra tận bàn xin lỗi và rất nhã nhặn, nhưng có lẽ chúng tôi sẽ chưa quay lại trong thời gian tới.","units":[{"en":"After reading a glowing article about Orange Bay Kitchen by Rebecca Roats, I was eager to give this place a try.","vi":"Sau khi đọc bài viết khen ngợi hết lời về Orange Bay Kitchen của Rebecca Roats, tôi rất háo hức muốn đến trải nghiệm thử."},{"en":"My husband and I arrived there at 7 P.M. yesterday, keen to enjoy live music with our dinner.","vi":"Chồng tôi và tôi đến quán lúc 7 giờ tối hôm qua, mong chờ được thưởng thức nhạc sống cùng bữa tối."},{"en":"Unfortunately, the band's performance that night had been cancelled.","vi":"Thật không may, buổi biểu diễn tối hôm đó của ban nhạc đã bị hủy."},{"en":"Undeterred, we stayed and both ordered the jerk chicken.","vi":"Không nản lòng, chúng tôi vẫn nán lại và cả hai đều gọi món gà nướng kiểu Jamaica."},{"en":"While the chicken's smoky flavour was outstanding, the stewed cabbage was lacking in flavour.","vi":"Dù hương vị khói của thịt gà rất xuất sắc, món bắp cải hầm lại khá nhạt nhòa."},{"en":"Also, the portion size was smaller than we had anticipated, so we ordered another appetiser to avoid going home hungry.","vi":"Ngoài ra, khẩu phần ăn cũng nhỏ hơn dự kiến của chúng tôi, nên chúng tôi đã gọi thêm một món khai vị nữa để khỏi phải về nhà với cái bụng đói."},{"en":"The head chef came out to apologise and was extremely nice, but we will probably not go back anytime soon.","vi":"Bếp trưởng đã ra tận bàn xin lỗi và rất nhã nhặn, nhưng có lẽ chúng tôi sẽ chưa quay lại trong thời gian tới."}]},{"speaker":"Document 3 — E-mail","en":"To: tpeterkin@sunmail.co.uk","vi":"Đến: tpeterkin@sunmail.co.uk","units":[{"en":"To: tpeterkin@sunmail.co.uk","vi":"Đến: tpeterkin@sunmail.co.uk"}]},{"speaker":"Document 3 — E-mail","en":"From: vsmith@orangebaykitchen.co.uk","vi":"Từ: vsmith@orangebaykitchen.co.uk","units":[{"en":"From: vsmith@orangebaykitchen.co.uk","vi":"Từ: vsmith@orangebaykitchen.co.uk"}]},{"speaker":"Document 3 — E-mail","en":"Date: 24 August","vi":"Ngày: 24 tháng 8","units":[{"en":"Date: 24 August","vi":"Ngày: 24 tháng 8"}]},{"speaker":"Document 3 — E-mail","en":"Subject: Your review","vi":"Chủ đề: Đánh giá của bạn","units":[{"en":"Subject: Your review","vi":"Chủ đề: Đánh giá của bạn"}]},{"speaker":"Document 3 — E-mail","en":"Attachment: 0258","vi":"Tệp đính kèm: 0258","units":[{"en":"Attachment: 0258","vi":"Tệp đính kèm: 0258"}]},{"speaker":"Document 3 — E-mail","en":"Dear Ms. Peterkin,","vi":"Kính gửi bà Peterkin,","units":[{"en":"Dear Ms. Peterkin,","vi":"Kính gửi bà Peterkin,"}]},{"speaker":"Document 3 — E-mail","en":"Thank you for visiting Orange Bay Kitchen and leaving a review. Our manager, Keron Deslandes, told me more about your visit and our failure to live up to your expectations that evening. Please accept the attached £20 gift certificate; I do hope that you will give us another try.","vi":"Cảm ơn bà đã ghé thăm Orange Bay Kitchen và để lại đánh giá. Quản lý của chúng tôi, Keron Deslandes, đã trao đổi với tôi về chuyến ghé thăm của bà cũng như việc chúng tôi đã chưa đáp ứng được kỳ vọng của bà vào tối hôm đó. Xin bà vui lòng nhận phiếu quà tặng trị giá £20 đính kèm; tôi rất hy vọng bà sẽ cho chúng tôi một cơ hội phục vụ lại.","units":[{"en":"Thank you for visiting Orange Bay Kitchen and leaving a review.","vi":"Cảm ơn bà đã ghé thăm Orange Bay Kitchen và để lại đánh giá."},{"en":"Our manager, Keron Deslandes, told me more about your visit and our failure to live up to your expectations that evening.","vi":"Quản lý của chúng tôi, Keron Deslandes, đã trao đổi với tôi về chuyến ghé thăm của bà cũng như việc chúng tôi đã chưa đáp ứng được kỳ vọng của bà vào tối hôm đó."},{"en":"Please accept the attached £20 gift certificate; I do hope that you will give us another try.","vi":"Xin bà vui lòng nhận phiếu quà tặng trị giá £20 đính kèm; tôi rất hy vọng bà sẽ cho chúng tôi một cơ hội phục vụ lại."}]},{"speaker":"Document 3 — E-mail","en":"During your visit, our band had an equipment malfunction, which is what led to the last-minute cancellation. However, the band will be back performing weekly beginning in September. Also, I want you to know that Head Chef Adio Brown has changed the spices he uses in the stewed cabbage. I am sure you will find them delightful.","vi":"Vào buổi tối bà ghé quán, ban nhạc của chúng tôi gặp sự cố thiết bị nên buộc phải hủy buổi diễn vào phút chót. Tuy nhiên, ban nhạc sẽ trở lại biểu diễn hằng tuần bắt đầu từ tháng 9. Bên cạnh đó, tôi cũng xin thông báo rằng Bếp trưởng Adio Brown đã điều chỉnh lại gia vị cho món bắp cải hầm. Tôi tin chắc bà sẽ thấy hương vị mới rất tuyệt vời.","units":[{"en":"During your visit, our band had an equipment malfunction, which is what led to the last-minute cancellation.","vi":"Vào buổi tối bà ghé quán, ban nhạc của chúng tôi gặp sự cố thiết bị nên buộc phải hủy buổi diễn vào phút chót."},{"en":"However, the band will be back performing weekly beginning in September.","vi":"Tuy nhiên, ban nhạc sẽ trở lại biểu diễn hằng tuần bắt đầu từ tháng 9."},{"en":"Also, I want you to know that Head Chef Adio Brown has changed the spices he uses in the stewed cabbage.","vi":"Bên cạnh đó, tôi cũng xin thông báo rằng Bếp trưởng Adio Brown đã điều chỉnh lại gia vị cho món bắp cải hầm."},{"en":"I am sure you will find them delightful.","vi":"Tôi tin chắc bà sẽ thấy hương vị mới rất tuyệt vời."}]},{"speaker":"Document 3 — E-mail","en":"Sincerely,","vi":"Trân trọng,","units":[{"en":"Sincerely,","vi":"Trân trọng,"}]},{"speaker":"Document 3 — E-mail","en":"Vea Smith, Owner, Orange Bay Kitchen","vi":"Vea Smith, Chủ sở hữu, Orange Bay Kitchen","units":[{"en":"Vea Smith, Owner, Orange Bay Kitchen","vi":"Vea Smith, Chủ sở hữu, Orange Bay Kitchen"}]}],"vocab":[{"word":"apologise","pos":"v","ipa":"/əˈpɑːlədʒaɪz/","meaning":"xin lỗi"},{"word":"spice","pos":"n","ipa":"/spaɪs/","meaning":"gia vị"},{"word":"delightful","pos":"adj","ipa":"/dɪˈlaɪtfəl/","meaning":"tuyệt vời, làm hài lòng"},{"word":"outstanding","pos":"adj","ipa":"/ˌaʊtˈstændɪŋ/","meaning":"xuất sắc, nổi bật"}],"isScanBacked":false,"docTypeLabel":"article, review, and e-mail","context":"Article, review, and e-mail — Orange Bay Kitchen","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 — LIÊN KẾT CHỨC DANH ↔ TÊN RIÊNG (DOCUMENT 2 + DOCUMENT 3): Tìm chức danh người gặp ở Document 2 ('The head chef') -> Tra tên riêng tương ứng ở Document 3 ('Head Chef Adio Brown').","optionAnalysis":{"A":"Sai vì Rebecca Roats là tác giả bài báo ở Document 1 khiến bà Peterkin muốn đến thử quán, không phải nhân viên bà gặp tại nhà hàng.","B":"Sai vì Keron Deslandes là quản lý nhà hàng ('manager') báo lại chuyện cho chủ quán, trong khi người ra gặp và xin lỗi bà Peterkin là bếp trưởng ('head chef').","C":"Đúng vì Document 2 ghi 'The head chef came out to apologise' và Document 3 xác nhận danh tính vị bếp trưởng đó là 'Head Chef Adio Brown'.","D":"Sai vì Vea Smith là chủ nhà hàng viết e-mail sau khi nghe quản lý kể lại sự việc, không phải người đã ra xin lỗi trực tiếp trong bữa tối."},"evDocIdx":2,"evTargets":[{"badge":"Câu 195 · Đáp án C","opt":"C","isCorrect":true,"quote":"Also, I want you to know that Head Chef Adio Brown has changed the spices he uses in the stewed cabbage.","viQuote":"Bên cạnh đó, tôi cũng xin thông báo rằng Bếp trưởng Adio Brown đã điều chỉnh lại gia vị cho món bắp cải hầm."},{"badge":"Câu 195 · Đáp án C","opt":"C","isCorrect":true,"quote":"The head chef came out to apologise and was extremely nice, but we will probably not go back anytime soon.","viQuote":"Bếp trưởng đã ra tận bàn xin lỗi và rất nhã nhặn, nhưng có lẽ chúng tôi sẽ chưa quay lại trong thời gian tới."}],"evQuotes":["Also, I want you to know that Head Chef Adio Brown has changed the spices he uses in the stewed cabbage.","The head chef came out to apologise and was extremely nice, but we will probably not go back anytime soon."]},{"q":196,"part":7,"group_id":"E25_T01_G196_200","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc27.webp","web_assets/ets2025/p67/E25_T01_rc28.webp"],"stem_en":"What does the invoice suggest about Green Canyon?","stem_vi":"Hóa đơn gợi ý điều gì về Green Canyon?","options":{"A":{"en":"It does landscaping projects.","vi":"Công ty này thực hiện các dự án thiết kế cảnh quan."},"B":{"en":"It designs highways.","vi":"Công ty này thiết kế đường cao tốc."},"C":{"en":"It repairs old houses.","vi":"Công ty này sửa chữa nhà cũ."},"D":{"en":"It operates a farm.","vi":"Công ty này vận hành một trang trại."}},"ans":"A","evidence_quote":"Garden soil Crushed gravel Decorative stone 70 paving stones","explanation":"Đáp án đúng: (A) Công ty này thực hiện các dự án thiết kế cảnh quan — Danh mục hàng hóa Green Canyon mua đều là vật liệu làm vườn và lát sân ngoài trời.\nDẫn chứng: \"Garden soil, 33 cubic meters\", \"Crushed gravel, 30 metric tons\", \"Decorative stone, 20 metric tons\", \"70 paving stones, .6 x .6 meters\" (Document 1 — Invoice: đất trồng vườn, sỏi dăm, đá trang trí và đá lát lối đi đặc trưng cho thi công cảnh quan).\nPhân tích bẫy:\n- (B) Bẫy phóng đại quy mô: 33 m³ đất vườn, đá trang trí và 70 viên đá lát 0,6x0,6 m dùng cho sân vườn cảnh quan, không phải thi công thiết kế đường cao tốc.\n- (C) Bẫy sai loại vật tư: Hóa đơn toàn đất vườn, sỏi và đá lát sân ngoài trời, không có vật liệu sửa chữa nhà cửa.\n- (D) Bẫy suy diễn thiếu bao quát: Dù có đất vườn ('Garden soil'), nhưng đi kèm đá trang trí ('Decorative stone') và đá lát sân ('paving stones') đặc trưng cho cảnh quan chứ không phải trang trại.","lines":[{"speaker":"Document 1 — Invoice","en":"Orbys Distributors","vi":"Orbys Distributors","units":[{"en":"Orbys Distributors","vi":"Orbys Distributors"}]},{"speaker":"Document 1 — Invoice","en":"Client: Green Canyon | Date: June 10","vi":"Khách hàng: Green Canyon | Ngày: 10 tháng 6","units":[{"en":"Client: Green Canyon | Date: June 10","vi":"Khách hàng: Green Canyon | Ngày: 10 tháng 6"}]},{"speaker":"Document 1 — Invoice","en":"Account: 4352-0","vi":"Tài khoản: 4352-0","units":[{"en":"Account: 4352-0","vi":"Tài khoản: 4352-0"}]},{"speaker":"Document 1 — Invoice","en":"Item | Price","vi":"Mặt hàng | Giá tiền","units":[{"en":"Item | Price","vi":"Mặt hàng | Giá tiền"}]},{"speaker":"Document 1 — Invoice","en":"Garden soil, 33 cubic meters | $1,170.00","vi":"Đất trồng vườn, 33 mét khối | $1,170.00","units":[{"en":"Garden soil, 33 cubic meters | $1,170.00","vi":"Đất trồng vườn, 33 mét khối | $1,170.00"}]},{"speaker":"Document 1 — Invoice","en":"Crushed gravel, 30 metric tons | 1,710.00","vi":"Sỏi nghiền, 30 tấn | 1,710.00","units":[{"en":"Crushed gravel, 30 metric tons | 1,710.00","vi":"Sỏi nghiền, 30 tấn | 1,710.00"}]},{"speaker":"Document 1 — Invoice","en":"Decorative stone, 20 metric tons | 1,140.00","vi":"Đá trang trí, 20 tấn | 1,140.00","units":[{"en":"Decorative stone, 20 metric tons | 1,140.00","vi":"Đá trang trí, 20 tấn | 1,140.00"}]},{"speaker":"Document 1 — Invoice","en":"70 paving stones, .6 x .6 meters | 630.00","vi":"70 viên đá lát, 0,6 x 0,6 mét | 630.00","units":[{"en":"70 paving stones, .6 x .6 meters | 630.00","vi":"70 viên đá lát, 0,6 x 0,6 mét | 630.00"}]},{"speaker":"Document 1 — Invoice","en":"Subtotal | 4,650.00","vi":"Tạm tính | 4,650.00","units":[{"en":"Subtotal | 4,650.00","vi":"Tạm tính | 4,650.00"}]},{"speaker":"Document 1 — Invoice","en":"Discount (10%) | 465.00","vi":"Chiết khấu (10%) | 465.00","units":[{"en":"Discount (10%) | 465.00","vi":"Chiết khấu (10%) | 465.00"}]},{"speaker":"Document 1 — Invoice","en":"Delivery charge | 350.00","vi":"Phí giao hàng | 350.00","units":[{"en":"Delivery charge | 350.00","vi":"Phí giao hàng | 350.00"}]},{"speaker":"Document 1 — Invoice","en":"Grand Total | 4,535.00","vi":"Tổng cộng | 4,535.00","units":[{"en":"Grand Total | 4,535.00","vi":"Tổng cộng | 4,535.00"}]},{"speaker":"Document 1 — Invoice","en":"Please see the enclosed notice outlining important changes to your billing.","vi":"Vui lòng xem thông báo đính kèm nêu rõ những thay đổi quan trọng về việc thanh toán hóa đơn của quý khách.","units":[{"en":"Please see the enclosed notice outlining important changes to your billing.","vi":"Vui lòng xem thông báo đính kèm nêu rõ những thay đổi quan trọng về việc thanh toán hóa đơn của quý khách."}]},{"speaker":"Document 2 — Notice","en":"Orbys Distributors","vi":"Orbys Distributors","units":[{"en":"Orbys Distributors","vi":"Orbys Distributors"}]},{"speaker":"Document 2 — Notice","en":"To our valued customers:","vi":"Kính gửi quý khách hàng thân thiết:","units":[{"en":"To our valued customers:","vi":"Kính gửi quý khách hàng thân thiết:"}]},{"speaker":"Document 2 — Notice","en":"Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago. As a much-needed upgrade, we are switching to electronic invoicing. Starting August 1, invoices will be generated automatically each month and will be sent to the e-mail address associated with your company's account.","vi":"Hệ thống lập hóa đơn hiện tại của chúng tôi đã được vận hành kể từ khi Orbys Distributors thành lập cách đây hơn hai mươi năm. Để đáp ứng nhu cầu nâng cấp thiết yếu, chúng tôi sẽ chuyển sang sử dụng hóa đơn điện tử. Bắt đầu từ ngày 1 tháng 8, hóa đơn sẽ được tạo tự động hằng tháng và gửi về địa chỉ e-mail liên kết với tài khoản công ty của quý khách.","units":[{"en":"Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago.","vi":"Hệ thống lập hóa đơn hiện tại của chúng tôi đã được vận hành kể từ khi Orbys Distributors thành lập cách đây hơn hai mươi năm."},{"en":"As a much-needed upgrade, we are switching to electronic invoicing.","vi":"Để đáp ứng nhu cầu nâng cấp thiết yếu, chúng tôi sẽ chuyển sang sử dụng hóa đơn điện tử."},{"en":"Starting August 1, invoices will be generated automatically each month and will be sent to the e-mail address associated with your company's account.","vi":"Bắt đầu từ ngày 1 tháng 8, hóa đơn sẽ được tạo tự động hằng tháng và gửi về địa chỉ e-mail liên kết với tài khoản công ty của quý khách."}]},{"speaker":"Document 2 — Notice","en":"Rest assured that our long-standing incentives remain in place:","vi":"Quý khách hoàn toàn yên tâm rằng các chính sách ưu đãi lâu năm của chúng tôi vẫn được giữ nguyên:","units":[{"en":"Rest assured that our long-standing incentives remain in place:","vi":"Quý khách hoàn toàn yên tâm rằng các chính sách ưu đãi lâu năm của chúng tôi vẫn được giữ nguyên:"}]},{"speaker":"Document 2 — Notice","en":"• A 10% discount for orders of more than $4,000","vi":"• Giảm giá 10% cho các đơn hàng có giá trị trên $4,000","units":[{"en":"• A 10% discount for orders of more than $4,000","vi":"• Giảm giá 10% cho các đơn hàng có giá trị trên $4,000"}]},{"speaker":"Document 2 — Notice","en":"• A 20% discount for charitable organizations","vi":"• Giảm giá 20% dành cho các tổ chức từ thiện","units":[{"en":"• A 20% discount for charitable organizations","vi":"• Giảm giá 20% dành cho các tổ chức từ thiện"}]},{"speaker":"Document 2 — Notice","en":"• Free deliveries to locations within 5 miles of one of our supply centers","vi":"• Giao hàng miễn phí đến các địa điểm trong phạm vi 5 dặm tính từ một trong các trung tâm cung ứng của chúng tôi","units":[{"en":"• Free deliveries to locations within 5 miles of one of our supply centers","vi":"• Giao hàng miễn phí đến các địa điểm trong phạm vi 5 dặm tính từ một trong các trung tâm cung ứng của chúng tôi"}]},{"speaker":"Document 2 — Notice","en":"• Free samples for members of our Frequent Buyer Club","vi":"• Tặng mẫu dùng thử miễn phí cho thành viên Câu lạc bộ Khách hàng Thường xuyên","units":[{"en":"• Free samples for members of our Frequent Buyer Club","vi":"• Tặng mẫu dùng thử miễn phí cho thành viên Câu lạc bộ Khách hàng Thường xuyên"}]},{"speaker":"Document 2 — Notice","en":"More information about our transition to electronic invoicing is available on our Web site. Thank you for your support. Orbys Distributors appreciates your business.","vi":"Thông tin chi tiết về quá trình chuyển đổi sang hóa đơn điện tử hiện đã được đăng tải trên trang web của chúng tôi. Cảm ơn sự ủng hộ của quý khách. Orbys Distributors rất trân trọng sự đồng hành của quý khách.","units":[{"en":"More information about our transition to electronic invoicing is available on our Web site.","vi":"Thông tin chi tiết về quá trình chuyển đổi sang hóa đơn điện tử hiện đã được đăng tải trên trang web của chúng tôi."},{"en":"Thank you for your support.","vi":"Cảm ơn sự ủng hộ của quý khách."},{"en":"Orbys Distributors appreciates your business.","vi":"Orbys Distributors rất trân trọng sự đồng hành của quý khách."}]},{"speaker":"Document 3 — E-mail","en":"To: Mary Peterson, Billing Department","vi":"Đến: Mary Peterson, Phòng Thanh toán","units":[{"en":"To: Mary Peterson, Billing Department","vi":"Đến: Mary Peterson, Phòng Thanh toán"}]},{"speaker":"Document 3 — E-mail","en":"From: Tanvir Singh, Account Manager","vi":"Từ: Tanvir Singh, Quản lý Khách hàng","units":[{"en":"From: Tanvir Singh, Account Manager","vi":"Từ: Tanvir Singh, Quản lý Khách hàng"}]},{"speaker":"Document 3 — E-mail","en":"Date: September 12","vi":"Ngày: 12 tháng 9","units":[{"en":"Date: September 12","vi":"Ngày: 12 tháng 9"}]},{"speaker":"Document 3 — E-mail","en":"Subject: Account 1012-4","vi":"Chủ đề: Tài khoản 1012-4","units":[{"en":"Subject: Account 1012-4","vi":"Chủ đề: Tài khoản 1012-4"}]},{"speaker":"Document 3 — E-mail","en":"Hello Mary,","vi":"Chào Mary,","units":[{"en":"Hello Mary,","vi":"Chào Mary,"}]},{"speaker":"Document 3 — E-mail","en":"I received a query today from William Tesoriero at Tesoriero Remodeling. His monthly invoice for August never arrived.","vi":"Hôm nay tôi nhận được phản hồi thắc mắc từ ông William Tesoriero tại Công ty Tesoriero Remodeling. Hóa đơn tháng 8 của ông ấy vẫn chưa được gửi tới.","units":[{"en":"I received a query today from William Tesoriero at Tesoriero Remodeling.","vi":"Hôm nay tôi nhận được phản hồi thắc mắc từ ông William Tesoriero tại Công ty Tesoriero Remodeling."},{"en":"His monthly invoice for August never arrived.","vi":"Hóa đơn tháng 8 của ông ấy vẫn chưa được gửi tới."}]},{"speaker":"Document 3 — E-mail","en":"As you know, Mr. Tesoriero was one of our very first customers. Since we first opened for business, he has made purchases from us on a regular basis. He is also a member of the Frequent Buyer Club. This is a customer we absolutely do not want to lose. I explained to him that the rollout of our electronic invoicing system did not go as smoothly as we had hoped and promised that this would not happen again.","vi":"Như chị biết đấy, ông Tesoriero là một trong những khách hàng đầu tiên của chúng ta. Kể từ ngày đầu chúng ta đi vào hoạt động, ông ấy đã luôn đặt mua hàng thường xuyên. Ông ấy cũng là thành viên của Câu lạc bộ Khách hàng Thường xuyên. Đây là vị khách hàng mà chúng ta tuyệt đối không muốn để mất. Tôi đã giải thích với ông ấy rằng quá trình triển khai hệ thống hóa đơn điện tử của chúng ta diễn ra chưa suôn sẻ như kỳ vọng và cam kết sự việc tương tự sẽ không tái diễn.","units":[{"en":"As you know, Mr. Tesoriero was one of our very first customers.","vi":"Như chị biết đấy, ông Tesoriero là một trong những khách hàng đầu tiên của chúng ta."},{"en":"Since we first opened for business, he has made purchases from us on a regular basis.","vi":"Kể từ ngày đầu chúng ta đi vào hoạt động, ông ấy đã luôn đặt mua hàng thường xuyên."},{"en":"He is also a member of the Frequent Buyer Club.","vi":"Ông ấy cũng là thành viên của Câu lạc bộ Khách hàng Thường xuyên."},{"en":"This is a customer we absolutely do not want to lose.","vi":"Đây là vị khách hàng mà chúng ta tuyệt đối không muốn để mất."},{"en":"I explained to him that the rollout of our electronic invoicing system did not go as smoothly as we had hoped and promised that this would not happen again.","vi":"Tôi đã giải thích với ông ấy rằng quá trình triển khai hệ thống hóa đơn điện tử của chúng ta diễn ra chưa suôn sẻ như kỳ vọng và cam kết sự việc tương tự sẽ không tái diễn."}]},{"speaker":"Document 3 — E-mail","en":"I would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero.","vi":"Rất mong chị vui lòng kiểm tra ngay nguyên nhân sự cố và gửi hóa đơn tháng 8 cho ông Tesoriero.","units":[{"en":"I would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero.","vi":"Rất mong chị vui lòng kiểm tra ngay nguyên nhân sự cố và gửi hóa đơn tháng 8 cho ông Tesoriero."}]},{"speaker":"Document 3 — E-mail","en":"Tanvir","vi":"Tanvir","units":[{"en":"Tanvir","vi":"Tanvir"}]}],"vocab":[{"word":"landscaping","pos":"n","ipa":"/ˈlændskeɪpɪŋ/","meaning":"thiết kế, thi công cảnh quan"},{"word":"crushed gravel","pos":"n","ipa":"/krʌʃt ˈɡrævəl/","meaning":"sỏi nghiền, đá dăm"},{"word":"paving stone","pos":"n","ipa":"/ˈpeɪvɪŋ stoʊn/","meaning":"đá lát sân, đá lát lối đi"},{"word":"decorative","pos":"adj","ipa":"/ˈdekərətɪv/","meaning":"để trang trí"}],"isScanBacked":false,"docTypeLabel":"invoice, notice, and e-mail","context":"Invoice, notice, and e-mail — Orbys Distributors electronic invoicing transition","grammarType":"Part 7 — Suy luận & Hàm ý văn bản (Inference & Implied Meaning)","formula":"CÔNG THỨC PART 7 — SUY LUẬN NGÀNH NGHỀ TỪ DANH MỤC HÀNG HÓA (HÓA ĐƠN): Tổng hợp nhóm vật tư 'Garden soil + Crushed gravel + Decorative stone + paving stones' -> Suy ra lĩnh vực thiết kế cảnh quan sân vườn ('landscaping projects').","optionAnalysis":{"A":"Đúng vì các mặt hàng trên hóa đơn Document 1 gồm đất vườn ('Garden soil'), sỏi dăm, đá trang trí và 70 viên đá lát sân đều phục vụ dự án cảnh quan ('landscaping').","B":"Sai vì đất làm vườn, đá trang trí và số lượng nhỏ 70 viên đá lát 0,6x0,6 m không phải vật liệu dùng để thiết kế đường cao tốc.","C":"Sai vì danh mục chỉ có vật liệu sân vườn ngoài trời (đất, sỏi, đá lát), không có vật tư tu sửa kết cấu nhà cũ.","D":"Sai vì ngoài đất vườn, công ty còn mua đá trang trí ('Decorative stone') và đá lát sân ('paving stones'), phù hợp thiết kế cảnh quan hơn là vận hành trang trại."},"evDocIdx":0,"evTargets":[{"badge":"Câu 196 · Đáp án A","opt":"A","isCorrect":true,"quote":"Garden soil, 33 cubic meters","viQuote":"Đất trồng vườn, 33 mét khối"},{"badge":"Câu 196 · Đáp án A","opt":"A","isCorrect":true,"quote":"Decorative stone, 20 metric tons","viQuote":"Đá trang trí, 20 tấn"},{"badge":"Câu 196 · Đáp án A","opt":"A","isCorrect":true,"quote":"70 paving stones, .6 x .6 meters","viQuote":"70 viên đá lát, 0,6 x 0,6 mét"}],"evQuotes":["Garden soil, 33 cubic meters","Decorative stone, 20 metric tons","70 paving stones, .6 x .6 meters"]},{"q":197,"part":7,"group_id":"E25_T01_G196_200","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc27.webp","web_assets/ets2025/p67/E25_T01_rc28.webp"],"stem_en":"Why most likely did Green Canyon receive a discount on its order dated June 10?","stem_vi":"Vì sao Green Canyon có khả năng cao đã được giảm giá cho đơn hàng ngày 10 tháng 6?","options":{"A":{"en":"It is a charitable organization.","vi":"Đây là một tổ chức từ thiện."},"B":{"en":"It belongs to the Frequent Buyer Club.","vi":"Công ty này là thành viên của Câu lạc bộ Khách hàng Thường xuyên."},"C":{"en":"It spent more than $4,000 on merchandise.","vi":"Công ty này đã chi hơn $4,000 tiền mua hàng hóa."},"D":{"en":"It is located near an Orbys Distributors supply center.","vi":"Công ty này nằm gần một trung tâm cung ứng của Orbys Distributors."}},"ans":"C","evidence_quote":"- In the invoice: Subtotal: 4,650.00 - In the notice: A 10% discount for orders of more than $4,000","explanation":"Đáp án đúng: (C) Công ty này đã chi hơn $4,000 tiền mua hàng hóa — Hóa đơn ngày 10 tháng 6 có tổng tiền hàng chưa tính phí giao hàng là $4,650.00 (vượt ngưỡng $4,000) nên được áp dụng mức giảm 10% theo thông báo.\nDẫn chứng: Document 1 ghi \"Subtotal | 4,650.00\" và \"Discount (10%) | 465.00\"; đối chiếu Document 2 ghi \"• A 10% discount for orders of more than $4,000\".\nPhân tích bẫy:\n- (A) Bẫy lệch tỷ lệ phần trăm: Theo Document 2, tổ chức từ thiện được giảm 20% ('A 20% discount'), còn hóa đơn của Green Canyon chỉ giảm 10%.\n- (B) Bẫy nhầm quyền lợi hội viên: Thành viên Frequent Buyer Club nhận mẫu dùng thử miễn phí ('Free samples'), không phải giảm giá 10%.\n- (D) Bẫy mâu thuẫn số liệu hóa đơn: Khách trong bán kính 5 dặm quanh trung tâm cung ứng được miễn phí giao hàng ('Free deliveries'), nhưng Green Canyon vẫn bị thu 'Delivery charge: 350.00'.","lines":[{"speaker":"Document 1 — Invoice","en":"Orbys Distributors","vi":"Orbys Distributors","units":[{"en":"Orbys Distributors","vi":"Orbys Distributors"}]},{"speaker":"Document 1 — Invoice","en":"Client: Green Canyon | Date: June 10","vi":"Khách hàng: Green Canyon | Ngày: 10 tháng 6","units":[{"en":"Client: Green Canyon | Date: June 10","vi":"Khách hàng: Green Canyon | Ngày: 10 tháng 6"}]},{"speaker":"Document 1 — Invoice","en":"Account: 4352-0","vi":"Tài khoản: 4352-0","units":[{"en":"Account: 4352-0","vi":"Tài khoản: 4352-0"}]},{"speaker":"Document 1 — Invoice","en":"Item | Price","vi":"Mặt hàng | Giá tiền","units":[{"en":"Item | Price","vi":"Mặt hàng | Giá tiền"}]},{"speaker":"Document 1 — Invoice","en":"Garden soil, 33 cubic meters | $1,170.00","vi":"Đất trồng vườn, 33 mét khối | $1,170.00","units":[{"en":"Garden soil, 33 cubic meters | $1,170.00","vi":"Đất trồng vườn, 33 mét khối | $1,170.00"}]},{"speaker":"Document 1 — Invoice","en":"Crushed gravel, 30 metric tons | 1,710.00","vi":"Sỏi nghiền, 30 tấn | 1,710.00","units":[{"en":"Crushed gravel, 30 metric tons | 1,710.00","vi":"Sỏi nghiền, 30 tấn | 1,710.00"}]},{"speaker":"Document 1 — Invoice","en":"Decorative stone, 20 metric tons | 1,140.00","vi":"Đá trang trí, 20 tấn | 1,140.00","units":[{"en":"Decorative stone, 20 metric tons | 1,140.00","vi":"Đá trang trí, 20 tấn | 1,140.00"}]},{"speaker":"Document 1 — Invoice","en":"70 paving stones, .6 x .6 meters | 630.00","vi":"70 viên đá lát, 0,6 x 0,6 mét | 630.00","units":[{"en":"70 paving stones, .6 x .6 meters | 630.00","vi":"70 viên đá lát, 0,6 x 0,6 mét | 630.00"}]},{"speaker":"Document 1 — Invoice","en":"Subtotal | 4,650.00","vi":"Tạm tính | 4,650.00","units":[{"en":"Subtotal | 4,650.00","vi":"Tạm tính | 4,650.00"}]},{"speaker":"Document 1 — Invoice","en":"Discount (10%) | 465.00","vi":"Chiết khấu (10%) | 465.00","units":[{"en":"Discount (10%) | 465.00","vi":"Chiết khấu (10%) | 465.00"}]},{"speaker":"Document 1 — Invoice","en":"Delivery charge | 350.00","vi":"Phí giao hàng | 350.00","units":[{"en":"Delivery charge | 350.00","vi":"Phí giao hàng | 350.00"}]},{"speaker":"Document 1 — Invoice","en":"Grand Total | 4,535.00","vi":"Tổng cộng | 4,535.00","units":[{"en":"Grand Total | 4,535.00","vi":"Tổng cộng | 4,535.00"}]},{"speaker":"Document 1 — Invoice","en":"Please see the enclosed notice outlining important changes to your billing.","vi":"Vui lòng xem thông báo đính kèm nêu rõ những thay đổi quan trọng về việc thanh toán hóa đơn của quý khách.","units":[{"en":"Please see the enclosed notice outlining important changes to your billing.","vi":"Vui lòng xem thông báo đính kèm nêu rõ những thay đổi quan trọng về việc thanh toán hóa đơn của quý khách."}]},{"speaker":"Document 2 — Notice","en":"Orbys Distributors","vi":"Orbys Distributors","units":[{"en":"Orbys Distributors","vi":"Orbys Distributors"}]},{"speaker":"Document 2 — Notice","en":"To our valued customers:","vi":"Kính gửi quý khách hàng thân thiết:","units":[{"en":"To our valued customers:","vi":"Kính gửi quý khách hàng thân thiết:"}]},{"speaker":"Document 2 — Notice","en":"Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago. As a much-needed upgrade, we are switching to electronic invoicing. Starting August 1, invoices will be generated automatically each month and will be sent to the e-mail address associated with your company's account.","vi":"Hệ thống lập hóa đơn hiện tại của chúng tôi đã được vận hành kể từ khi Orbys Distributors thành lập cách đây hơn hai mươi năm. Để đáp ứng nhu cầu nâng cấp thiết yếu, chúng tôi sẽ chuyển sang sử dụng hóa đơn điện tử. Bắt đầu từ ngày 1 tháng 8, hóa đơn sẽ được tạo tự động hằng tháng và gửi về địa chỉ e-mail liên kết với tài khoản công ty của quý khách.","units":[{"en":"Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago.","vi":"Hệ thống lập hóa đơn hiện tại của chúng tôi đã được vận hành kể từ khi Orbys Distributors thành lập cách đây hơn hai mươi năm."},{"en":"As a much-needed upgrade, we are switching to electronic invoicing.","vi":"Để đáp ứng nhu cầu nâng cấp thiết yếu, chúng tôi sẽ chuyển sang sử dụng hóa đơn điện tử."},{"en":"Starting August 1, invoices will be generated automatically each month and will be sent to the e-mail address associated with your company's account.","vi":"Bắt đầu từ ngày 1 tháng 8, hóa đơn sẽ được tạo tự động hằng tháng và gửi về địa chỉ e-mail liên kết với tài khoản công ty của quý khách."}]},{"speaker":"Document 2 — Notice","en":"Rest assured that our long-standing incentives remain in place:","vi":"Quý khách hoàn toàn yên tâm rằng các chính sách ưu đãi lâu năm của chúng tôi vẫn được giữ nguyên:","units":[{"en":"Rest assured that our long-standing incentives remain in place:","vi":"Quý khách hoàn toàn yên tâm rằng các chính sách ưu đãi lâu năm của chúng tôi vẫn được giữ nguyên:"}]},{"speaker":"Document 2 — Notice","en":"• A 10% discount for orders of more than $4,000","vi":"• Giảm giá 10% cho các đơn hàng có giá trị trên $4,000","units":[{"en":"• A 10% discount for orders of more than $4,000","vi":"• Giảm giá 10% cho các đơn hàng có giá trị trên $4,000"}]},{"speaker":"Document 2 — Notice","en":"• A 20% discount for charitable organizations","vi":"• Giảm giá 20% dành cho các tổ chức từ thiện","units":[{"en":"• A 20% discount for charitable organizations","vi":"• Giảm giá 20% dành cho các tổ chức từ thiện"}]},{"speaker":"Document 2 — Notice","en":"• Free deliveries to locations within 5 miles of one of our supply centers","vi":"• Giao hàng miễn phí đến các địa điểm trong phạm vi 5 dặm tính từ một trong các trung tâm cung ứng của chúng tôi","units":[{"en":"• Free deliveries to locations within 5 miles of one of our supply centers","vi":"• Giao hàng miễn phí đến các địa điểm trong phạm vi 5 dặm tính từ một trong các trung tâm cung ứng của chúng tôi"}]},{"speaker":"Document 2 — Notice","en":"• Free samples for members of our Frequent Buyer Club","vi":"• Tặng mẫu dùng thử miễn phí cho thành viên Câu lạc bộ Khách hàng Thường xuyên","units":[{"en":"• Free samples for members of our Frequent Buyer Club","vi":"• Tặng mẫu dùng thử miễn phí cho thành viên Câu lạc bộ Khách hàng Thường xuyên"}]},{"speaker":"Document 2 — Notice","en":"More information about our transition to electronic invoicing is available on our Web site. Thank you for your support. Orbys Distributors appreciates your business.","vi":"Thông tin chi tiết về quá trình chuyển đổi sang hóa đơn điện tử hiện đã được đăng tải trên trang web của chúng tôi. Cảm ơn sự ủng hộ của quý khách. Orbys Distributors rất trân trọng sự đồng hành của quý khách.","units":[{"en":"More information about our transition to electronic invoicing is available on our Web site.","vi":"Thông tin chi tiết về quá trình chuyển đổi sang hóa đơn điện tử hiện đã được đăng tải trên trang web của chúng tôi."},{"en":"Thank you for your support.","vi":"Cảm ơn sự ủng hộ của quý khách."},{"en":"Orbys Distributors appreciates your business.","vi":"Orbys Distributors rất trân trọng sự đồng hành của quý khách."}]},{"speaker":"Document 3 — E-mail","en":"To: Mary Peterson, Billing Department","vi":"Đến: Mary Peterson, Phòng Thanh toán","units":[{"en":"To: Mary Peterson, Billing Department","vi":"Đến: Mary Peterson, Phòng Thanh toán"}]},{"speaker":"Document 3 — E-mail","en":"From: Tanvir Singh, Account Manager","vi":"Từ: Tanvir Singh, Quản lý Khách hàng","units":[{"en":"From: Tanvir Singh, Account Manager","vi":"Từ: Tanvir Singh, Quản lý Khách hàng"}]},{"speaker":"Document 3 — E-mail","en":"Date: September 12","vi":"Ngày: 12 tháng 9","units":[{"en":"Date: September 12","vi":"Ngày: 12 tháng 9"}]},{"speaker":"Document 3 — E-mail","en":"Subject: Account 1012-4","vi":"Chủ đề: Tài khoản 1012-4","units":[{"en":"Subject: Account 1012-4","vi":"Chủ đề: Tài khoản 1012-4"}]},{"speaker":"Document 3 — E-mail","en":"Hello Mary,","vi":"Chào Mary,","units":[{"en":"Hello Mary,","vi":"Chào Mary,"}]},{"speaker":"Document 3 — E-mail","en":"I received a query today from William Tesoriero at Tesoriero Remodeling. His monthly invoice for August never arrived.","vi":"Hôm nay tôi nhận được phản hồi thắc mắc từ ông William Tesoriero tại Công ty Tesoriero Remodeling. Hóa đơn tháng 8 của ông ấy vẫn chưa được gửi tới.","units":[{"en":"I received a query today from William Tesoriero at Tesoriero Remodeling.","vi":"Hôm nay tôi nhận được phản hồi thắc mắc từ ông William Tesoriero tại Công ty Tesoriero Remodeling."},{"en":"His monthly invoice for August never arrived.","vi":"Hóa đơn tháng 8 của ông ấy vẫn chưa được gửi tới."}]},{"speaker":"Document 3 — E-mail","en":"As you know, Mr. Tesoriero was one of our very first customers. Since we first opened for business, he has made purchases from us on a regular basis. He is also a member of the Frequent Buyer Club. This is a customer we absolutely do not want to lose. I explained to him that the rollout of our electronic invoicing system did not go as smoothly as we had hoped and promised that this would not happen again.","vi":"Như chị biết đấy, ông Tesoriero là một trong những khách hàng đầu tiên của chúng ta. Kể từ ngày đầu chúng ta đi vào hoạt động, ông ấy đã luôn đặt mua hàng thường xuyên. Ông ấy cũng là thành viên của Câu lạc bộ Khách hàng Thường xuyên. Đây là vị khách hàng mà chúng ta tuyệt đối không muốn để mất. Tôi đã giải thích với ông ấy rằng quá trình triển khai hệ thống hóa đơn điện tử của chúng ta diễn ra chưa suôn sẻ như kỳ vọng và cam kết sự việc tương tự sẽ không tái diễn.","units":[{"en":"As you know, Mr. Tesoriero was one of our very first customers.","vi":"Như chị biết đấy, ông Tesoriero là một trong những khách hàng đầu tiên của chúng ta."},{"en":"Since we first opened for business, he has made purchases from us on a regular basis.","vi":"Kể từ ngày đầu chúng ta đi vào hoạt động, ông ấy đã luôn đặt mua hàng thường xuyên."},{"en":"He is also a member of the Frequent Buyer Club.","vi":"Ông ấy cũng là thành viên của Câu lạc bộ Khách hàng Thường xuyên."},{"en":"This is a customer we absolutely do not want to lose.","vi":"Đây là vị khách hàng mà chúng ta tuyệt đối không muốn để mất."},{"en":"I explained to him that the rollout of our electronic invoicing system did not go as smoothly as we had hoped and promised that this would not happen again.","vi":"Tôi đã giải thích với ông ấy rằng quá trình triển khai hệ thống hóa đơn điện tử của chúng ta diễn ra chưa suôn sẻ như kỳ vọng và cam kết sự việc tương tự sẽ không tái diễn."}]},{"speaker":"Document 3 — E-mail","en":"I would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero.","vi":"Rất mong chị vui lòng kiểm tra ngay nguyên nhân sự cố và gửi hóa đơn tháng 8 cho ông Tesoriero.","units":[{"en":"I would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero.","vi":"Rất mong chị vui lòng kiểm tra ngay nguyên nhân sự cố và gửi hóa đơn tháng 8 cho ông Tesoriero."}]},{"speaker":"Document 3 — E-mail","en":"Tanvir","vi":"Tanvir","units":[{"en":"Tanvir","vi":"Tanvir"}]}],"vocab":[{"word":"merchandise","pos":"n","ipa":"/ˈmɜːrtʃəndaɪz/","meaning":"hàng hóa"},{"word":"subtotal","pos":"n","ipa":"/ˈsʌbtoʊtəl/","meaning":"tổng phụ, số tiền tạm tính"},{"word":"discount","pos":"n","ipa":"/ˈdɪskaʊnt/","meaning":"khoản giảm giá, chiết khấu"},{"word":"charitable","pos":"adj","ipa":"/ˈtʃærɪtəbəl/","meaning":"từ thiện, nhân đạo"}],"isScanBacked":false,"docTypeLabel":"invoice, notice, and e-mail","context":"Invoice, notice, and e-mail — Orbys Distributors electronic invoicing transition","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 — ĐỐI CHIẾU SỐ LIỆU HÓA ĐƠN ↔ CHÍNH SÁCH ƯU ĐÃI (DOCUMENT 1 + DOCUMENT 2): Kiểm tra tỷ lệ giảm giá 'Discount (10%)' và 'Subtotal: 4,650.00' ở Document 1 -> Khớp điều kiện '> $4,000' ở Document 2.","optionAnalysis":{"A":"Sai vì theo Document 2, tổ chức từ thiện được giảm tới 20% ('A 20% discount'), không khớp mức giảm 10% trên hóa đơn Document 1.","B":"Sai vì quyền lợi của Frequent Buyer Club theo Document 2 là mẫu dùng thử miễn phí ('Free samples'), không phải mức giảm giá 10%.","C":"Đúng vì Document 1 ghi 'Subtotal: 4,650.00' (lớn hơn $4,000) và hưởng 'Discount (10%)', khớp chính xác ưu đãi giảm 10% cho đơn trên $4,000 ở Document 2.","D":"Sai vì ở gần trung tâm cung ứng được miễn phí giao hàng ('Free deliveries'), nhưng hóa đơn Document 1 vẫn tính Green Canyon $350.00 phí giao hàng."},"evDocIdx":1,"evTargets":[{"badge":"Câu 197 · Đáp án C","opt":"C","isCorrect":true,"quote":"A 10% discount for orders of more than $4,000","viQuote":"Giảm giá 10% cho các đơn hàng có giá trị trên $4,000"},{"badge":"Câu 197 · Đáp án C","opt":"C","isCorrect":true,"quote":"Discount (10%)","viQuote":"Chiết khấu (10%)"}],"evQuotes":["A 10% discount for orders of more than $4,000","Discount (10%)"]},{"q":198,"part":7,"group_id":"E25_T01_G196_200","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc27.webp","web_assets/ets2025/p67/E25_T01_rc28.webp"],"stem_en":"According to the notice, what is changing at Orbys Distributors?","stem_vi":"Theo thông báo, điều gì đang thay đổi tại Orbys Distributors?","options":{"A":{"en":"Its e-mail address","vi":"Địa chỉ e-mail của công ty"},"B":{"en":"Its list of incentives","vi":"Danh mục các chương trình ưu đãi"},"C":{"en":"Its invoicing system","vi":"Hệ thống lập hóa đơn của công ty"},"D":{"en":"Its delivery schedule","vi":"Lịch trình giao hàng của công ty"}},"ans":"C","evidence_quote":"Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago. As a much-needed upgrade, we are switching to electronic invoicing.","explanation":"Đáp án đúng: (C) Hệ thống lập hóa đơn của công ty — Thông báo cho biết Orbys Distributors đang nâng cấp hệ thống lập hóa đơn đã dùng hơn 20 năm sang hình thức hóa đơn điện tử tự động hàng tháng.\nDẫn chứng: \"Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago. As a much-needed upgrade, we are switching to electronic invoicing.\" (Document 2 — Notice: chuyển đổi sang hệ thống hóa đơn điện tử).\nPhân tích bẫy:\n- (A) Bẫy từ khóa 'e-mail address': Thông báo chỉ nói hóa đơn sẽ gửi tới địa chỉ e-mail gắn với tài khoản khách hàng, không phải công ty đổi địa chỉ e-mail.\n- (B) Bẫy trái ngược văn bản: Document 2 khẳng định danh mục ưu đãi lâu năm vẫn giữ nguyên ('our long-standing incentives remain in place').\n- (D) Bẫy suy diễn ngoài bài: Document 2 chỉ nhắc ưu đãi miễn phí giao hàng vẫn được duy trì, không đề cập thay đổi lịch giao hàng.","lines":[{"speaker":"Document 1 — Invoice","en":"Orbys Distributors","vi":"Orbys Distributors","units":[{"en":"Orbys Distributors","vi":"Orbys Distributors"}]},{"speaker":"Document 1 — Invoice","en":"Client: Green Canyon | Date: June 10","vi":"Khách hàng: Green Canyon | Ngày: 10 tháng 6","units":[{"en":"Client: Green Canyon | Date: June 10","vi":"Khách hàng: Green Canyon | Ngày: 10 tháng 6"}]},{"speaker":"Document 1 — Invoice","en":"Account: 4352-0","vi":"Tài khoản: 4352-0","units":[{"en":"Account: 4352-0","vi":"Tài khoản: 4352-0"}]},{"speaker":"Document 1 — Invoice","en":"Item | Price","vi":"Mặt hàng | Giá tiền","units":[{"en":"Item | Price","vi":"Mặt hàng | Giá tiền"}]},{"speaker":"Document 1 — Invoice","en":"Garden soil, 33 cubic meters | $1,170.00","vi":"Đất trồng vườn, 33 mét khối | $1,170.00","units":[{"en":"Garden soil, 33 cubic meters | $1,170.00","vi":"Đất trồng vườn, 33 mét khối | $1,170.00"}]},{"speaker":"Document 1 — Invoice","en":"Crushed gravel, 30 metric tons | 1,710.00","vi":"Sỏi nghiền, 30 tấn | 1,710.00","units":[{"en":"Crushed gravel, 30 metric tons | 1,710.00","vi":"Sỏi nghiền, 30 tấn | 1,710.00"}]},{"speaker":"Document 1 — Invoice","en":"Decorative stone, 20 metric tons | 1,140.00","vi":"Đá trang trí, 20 tấn | 1,140.00","units":[{"en":"Decorative stone, 20 metric tons | 1,140.00","vi":"Đá trang trí, 20 tấn | 1,140.00"}]},{"speaker":"Document 1 — Invoice","en":"70 paving stones, .6 x .6 meters | 630.00","vi":"70 viên đá lát, 0,6 x 0,6 mét | 630.00","units":[{"en":"70 paving stones, .6 x .6 meters | 630.00","vi":"70 viên đá lát, 0,6 x 0,6 mét | 630.00"}]},{"speaker":"Document 1 — Invoice","en":"Subtotal | 4,650.00","vi":"Tạm tính | 4,650.00","units":[{"en":"Subtotal | 4,650.00","vi":"Tạm tính | 4,650.00"}]},{"speaker":"Document 1 — Invoice","en":"Discount (10%) | 465.00","vi":"Chiết khấu (10%) | 465.00","units":[{"en":"Discount (10%) | 465.00","vi":"Chiết khấu (10%) | 465.00"}]},{"speaker":"Document 1 — Invoice","en":"Delivery charge | 350.00","vi":"Phí giao hàng | 350.00","units":[{"en":"Delivery charge | 350.00","vi":"Phí giao hàng | 350.00"}]},{"speaker":"Document 1 — Invoice","en":"Grand Total | 4,535.00","vi":"Tổng cộng | 4,535.00","units":[{"en":"Grand Total | 4,535.00","vi":"Tổng cộng | 4,535.00"}]},{"speaker":"Document 1 — Invoice","en":"Please see the enclosed notice outlining important changes to your billing.","vi":"Vui lòng xem thông báo đính kèm nêu rõ những thay đổi quan trọng về việc thanh toán hóa đơn của quý khách.","units":[{"en":"Please see the enclosed notice outlining important changes to your billing.","vi":"Vui lòng xem thông báo đính kèm nêu rõ những thay đổi quan trọng về việc thanh toán hóa đơn của quý khách."}]},{"speaker":"Document 2 — Notice","en":"Orbys Distributors","vi":"Orbys Distributors","units":[{"en":"Orbys Distributors","vi":"Orbys Distributors"}]},{"speaker":"Document 2 — Notice","en":"To our valued customers:","vi":"Kính gửi quý khách hàng thân thiết:","units":[{"en":"To our valued customers:","vi":"Kính gửi quý khách hàng thân thiết:"}]},{"speaker":"Document 2 — Notice","en":"Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago. As a much-needed upgrade, we are switching to electronic invoicing. Starting August 1, invoices will be generated automatically each month and will be sent to the e-mail address associated with your company's account.","vi":"Hệ thống lập hóa đơn hiện tại của chúng tôi đã được vận hành kể từ khi Orbys Distributors thành lập cách đây hơn hai mươi năm. Để đáp ứng nhu cầu nâng cấp thiết yếu, chúng tôi sẽ chuyển sang sử dụng hóa đơn điện tử. Bắt đầu từ ngày 1 tháng 8, hóa đơn sẽ được tạo tự động hằng tháng và gửi về địa chỉ e-mail liên kết với tài khoản công ty của quý khách.","units":[{"en":"Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago.","vi":"Hệ thống lập hóa đơn hiện tại của chúng tôi đã được vận hành kể từ khi Orbys Distributors thành lập cách đây hơn hai mươi năm."},{"en":"As a much-needed upgrade, we are switching to electronic invoicing.","vi":"Để đáp ứng nhu cầu nâng cấp thiết yếu, chúng tôi sẽ chuyển sang sử dụng hóa đơn điện tử."},{"en":"Starting August 1, invoices will be generated automatically each month and will be sent to the e-mail address associated with your company's account.","vi":"Bắt đầu từ ngày 1 tháng 8, hóa đơn sẽ được tạo tự động hằng tháng và gửi về địa chỉ e-mail liên kết với tài khoản công ty của quý khách."}]},{"speaker":"Document 2 — Notice","en":"Rest assured that our long-standing incentives remain in place:","vi":"Quý khách hoàn toàn yên tâm rằng các chính sách ưu đãi lâu năm của chúng tôi vẫn được giữ nguyên:","units":[{"en":"Rest assured that our long-standing incentives remain in place:","vi":"Quý khách hoàn toàn yên tâm rằng các chính sách ưu đãi lâu năm của chúng tôi vẫn được giữ nguyên:"}]},{"speaker":"Document 2 — Notice","en":"• A 10% discount for orders of more than $4,000","vi":"• Giảm giá 10% cho các đơn hàng có giá trị trên $4,000","units":[{"en":"• A 10% discount for orders of more than $4,000","vi":"• Giảm giá 10% cho các đơn hàng có giá trị trên $4,000"}]},{"speaker":"Document 2 — Notice","en":"• A 20% discount for charitable organizations","vi":"• Giảm giá 20% dành cho các tổ chức từ thiện","units":[{"en":"• A 20% discount for charitable organizations","vi":"• Giảm giá 20% dành cho các tổ chức từ thiện"}]},{"speaker":"Document 2 — Notice","en":"• Free deliveries to locations within 5 miles of one of our supply centers","vi":"• Giao hàng miễn phí đến các địa điểm trong phạm vi 5 dặm tính từ một trong các trung tâm cung ứng của chúng tôi","units":[{"en":"• Free deliveries to locations within 5 miles of one of our supply centers","vi":"• Giao hàng miễn phí đến các địa điểm trong phạm vi 5 dặm tính từ một trong các trung tâm cung ứng của chúng tôi"}]},{"speaker":"Document 2 — Notice","en":"• Free samples for members of our Frequent Buyer Club","vi":"• Tặng mẫu dùng thử miễn phí cho thành viên Câu lạc bộ Khách hàng Thường xuyên","units":[{"en":"• Free samples for members of our Frequent Buyer Club","vi":"• Tặng mẫu dùng thử miễn phí cho thành viên Câu lạc bộ Khách hàng Thường xuyên"}]},{"speaker":"Document 2 — Notice","en":"More information about our transition to electronic invoicing is available on our Web site. Thank you for your support. Orbys Distributors appreciates your business.","vi":"Thông tin chi tiết về quá trình chuyển đổi sang hóa đơn điện tử hiện đã được đăng tải trên trang web của chúng tôi. Cảm ơn sự ủng hộ của quý khách. Orbys Distributors rất trân trọng sự đồng hành của quý khách.","units":[{"en":"More information about our transition to electronic invoicing is available on our Web site.","vi":"Thông tin chi tiết về quá trình chuyển đổi sang hóa đơn điện tử hiện đã được đăng tải trên trang web của chúng tôi."},{"en":"Thank you for your support.","vi":"Cảm ơn sự ủng hộ của quý khách."},{"en":"Orbys Distributors appreciates your business.","vi":"Orbys Distributors rất trân trọng sự đồng hành của quý khách."}]},{"speaker":"Document 3 — E-mail","en":"To: Mary Peterson, Billing Department","vi":"Đến: Mary Peterson, Phòng Thanh toán","units":[{"en":"To: Mary Peterson, Billing Department","vi":"Đến: Mary Peterson, Phòng Thanh toán"}]},{"speaker":"Document 3 — E-mail","en":"From: Tanvir Singh, Account Manager","vi":"Từ: Tanvir Singh, Quản lý Khách hàng","units":[{"en":"From: Tanvir Singh, Account Manager","vi":"Từ: Tanvir Singh, Quản lý Khách hàng"}]},{"speaker":"Document 3 — E-mail","en":"Date: September 12","vi":"Ngày: 12 tháng 9","units":[{"en":"Date: September 12","vi":"Ngày: 12 tháng 9"}]},{"speaker":"Document 3 — E-mail","en":"Subject: Account 1012-4","vi":"Chủ đề: Tài khoản 1012-4","units":[{"en":"Subject: Account 1012-4","vi":"Chủ đề: Tài khoản 1012-4"}]},{"speaker":"Document 3 — E-mail","en":"Hello Mary,","vi":"Chào Mary,","units":[{"en":"Hello Mary,","vi":"Chào Mary,"}]},{"speaker":"Document 3 — E-mail","en":"I received a query today from William Tesoriero at Tesoriero Remodeling. His monthly invoice for August never arrived.","vi":"Hôm nay tôi nhận được phản hồi thắc mắc từ ông William Tesoriero tại Công ty Tesoriero Remodeling. Hóa đơn tháng 8 của ông ấy vẫn chưa được gửi tới.","units":[{"en":"I received a query today from William Tesoriero at Tesoriero Remodeling.","vi":"Hôm nay tôi nhận được phản hồi thắc mắc từ ông William Tesoriero tại Công ty Tesoriero Remodeling."},{"en":"His monthly invoice for August never arrived.","vi":"Hóa đơn tháng 8 của ông ấy vẫn chưa được gửi tới."}]},{"speaker":"Document 3 — E-mail","en":"As you know, Mr. Tesoriero was one of our very first customers. Since we first opened for business, he has made purchases from us on a regular basis. He is also a member of the Frequent Buyer Club. This is a customer we absolutely do not want to lose. I explained to him that the rollout of our electronic invoicing system did not go as smoothly as we had hoped and promised that this would not happen again.","vi":"Như chị biết đấy, ông Tesoriero là một trong những khách hàng đầu tiên của chúng ta. Kể từ ngày đầu chúng ta đi vào hoạt động, ông ấy đã luôn đặt mua hàng thường xuyên. Ông ấy cũng là thành viên của Câu lạc bộ Khách hàng Thường xuyên. Đây là vị khách hàng mà chúng ta tuyệt đối không muốn để mất. Tôi đã giải thích với ông ấy rằng quá trình triển khai hệ thống hóa đơn điện tử của chúng ta diễn ra chưa suôn sẻ như kỳ vọng và cam kết sự việc tương tự sẽ không tái diễn.","units":[{"en":"As you know, Mr. Tesoriero was one of our very first customers.","vi":"Như chị biết đấy, ông Tesoriero là một trong những khách hàng đầu tiên của chúng ta."},{"en":"Since we first opened for business, he has made purchases from us on a regular basis.","vi":"Kể từ ngày đầu chúng ta đi vào hoạt động, ông ấy đã luôn đặt mua hàng thường xuyên."},{"en":"He is also a member of the Frequent Buyer Club.","vi":"Ông ấy cũng là thành viên của Câu lạc bộ Khách hàng Thường xuyên."},{"en":"This is a customer we absolutely do not want to lose.","vi":"Đây là vị khách hàng mà chúng ta tuyệt đối không muốn để mất."},{"en":"I explained to him that the rollout of our electronic invoicing system did not go as smoothly as we had hoped and promised that this would not happen again.","vi":"Tôi đã giải thích với ông ấy rằng quá trình triển khai hệ thống hóa đơn điện tử của chúng ta diễn ra chưa suôn sẻ như kỳ vọng và cam kết sự việc tương tự sẽ không tái diễn."}]},{"speaker":"Document 3 — E-mail","en":"I would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero.","vi":"Rất mong chị vui lòng kiểm tra ngay nguyên nhân sự cố và gửi hóa đơn tháng 8 cho ông Tesoriero.","units":[{"en":"I would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero.","vi":"Rất mong chị vui lòng kiểm tra ngay nguyên nhân sự cố và gửi hóa đơn tháng 8 cho ông Tesoriero."}]},{"speaker":"Document 3 — E-mail","en":"Tanvir","vi":"Tanvir","units":[{"en":"Tanvir","vi":"Tanvir"}]}],"vocab":[{"word":"invoicing","pos":"n","ipa":"/ˈɪnvɔɪsɪŋ/","meaning":"việc lập và gửi hóa đơn"},{"word":"upgrade","pos":"n","ipa":"/ˈʌpɡreɪd/","meaning":"sự nâng cấp, cải tiến"},{"word":"incentive","pos":"n","ipa":"/ɪnˈsentɪv/","meaning":"chính sách ưu đãi, khuyến khích"},{"word":"transition","pos":"n","ipa":"/trænˈzɪʃən/","meaning":"quá trình chuyển đổi"}],"isScanBacked":false,"docTypeLabel":"invoice, notice, and e-mail","context":"Invoice, notice, and e-mail — Orbys Distributors electronic invoicing transition","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 — XÁC ĐỊNH THAY ĐỔI CHÍNH (THÔNG BÁO): Tìm động từ chuyển đổi 'are switching to electronic invoicing' và 'transition to electronic invoicing' -> Phân biệt điểm thay đổi với các mục giữ nguyên ('remain in place').","optionAnalysis":{"A":"Sai vì e-mail được nhắc đến là địa chỉ e-mail gắn với tài khoản của khách hàng để nhận hóa đơn, không phải Orbys Distributors đổi địa chỉ e-mail.","B":"Sai vì trái ngược với Document 2: thông báo khẳng định các chương trình ưu đãi lâu năm vẫn được giữ nguyên ('remain in place').","C":"Đúng vì Document 2 thông báo công ty đang nâng cấp hệ thống lập hóa đơn hiện tại ('current invoicing system') bằng cách chuyển sang hóa đơn điện tử.","D":"Sai vì thông báo không đề cập bất kỳ thay đổi nào về lịch trình giao hàng ('delivery schedule'), chỉ xác nhận giữ nguyên ưu đãi miễn phí giao hàng."},"evDocIdx":1,"evTargets":[{"badge":"Câu 198 · Đáp án C","opt":"C","isCorrect":true,"quote":"Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago.","viQuote":"Hệ thống lập hóa đơn hiện tại của chúng tôi đã được vận hành kể từ khi Orbys Distributors thành lập cách đây hơn hai mươi năm."},{"badge":"Câu 198 · Đáp án C","opt":"C","isCorrect":true,"quote":"As a much-needed upgrade, we are switching to electronic invoicing.","viQuote":"Để đáp ứng nhu cầu nâng cấp thiết yếu, chúng tôi sẽ chuyển sang sử dụng hóa đơn điện tử."}],"evQuotes":["Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago.","As a much-needed upgrade, we are switching to electronic invoicing."]},{"q":199,"part":7,"group_id":"E25_T01_G196_200","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc27.webp","web_assets/ets2025/p67/E25_T01_rc28.webp"],"stem_en":"What is suggested about Mr. Tesoriero?","stem_vi":"Điều gì được suy ra về ông Tesoriero?","options":{"A":{"en":"He asked to meet with Mr. Singh.","vi":"Ông ấy đã đề nghị gặp mặt ông Singh."},"B":{"en":"He is interested in employment at Orbys Distributors.","vi":"Ông ấy quan tâm đến việc làm tại Orbys Distributors."},"C":{"en":"He recently placed an order for some construction machinery.","vi":"Gần đây ông ấy đã đặt mua một số máy móc xây dựng."},"D":{"en":"He has been a customer of Orbys Distributors for about twenty years.","vi":"Ông ấy đã là khách hàng của Orbys Distributors khoảng hai mươi năm."}},"ans":"D","evidence_quote":"- In the email: As you know, Mr. Tesoriero was one of our very first customers. Since we first opened for business, he has made purchases from us on a regular basis. - In the notice: Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago.","explanation":"Đáp án đúng: (D) Ông ấy đã là khách hàng của Orbys Distributors khoảng hai mươi năm — E-mail cho biết ông Tesoriero là một trong những khách hàng đầu tiên mua hàng đều đặn từ ngày công ty mới mở cửa, mà thông báo xác nhận công ty thành lập hơn hai mươi năm trước.\nDẫn chứng: Document 3 (E-mail) ghi \"Mr. Tesoriero was one of our very first customers. Since we first opened for business, he has made purchases from us on a regular basis\"; ghép Document 2 (Notice) ghi \"since Orbys Distributors was founded over twenty years ago\".\nPhân tích bẫy:\n- (A) Bẫy thay đổi hành động: Ông Tesoriero chỉ gửi thắc mắc về hóa đơn tháng 8 chưa tới ('received a query today'), không hề đề nghị gặp mặt ông Singh.\n- (B) Bẫy đánh tráo quan hệ: Ông Tesoriero là chủ/đại diện tại Tesoriero Remodeling và là khách hàng thân thiết ('Frequent Buyer Club'), không phải người xin việc.\n- (C) Bẫy suy diễn từ tên công ty: Tên 'Tesoriero Remodeling' liên quan sửa chữa/cải tạo, nhưng bài không nhắc ông đặt mua máy móc xây dựng ('construction machinery').","lines":[{"speaker":"Document 1 — Invoice","en":"Orbys Distributors","vi":"Orbys Distributors","units":[{"en":"Orbys Distributors","vi":"Orbys Distributors"}]},{"speaker":"Document 1 — Invoice","en":"Client: Green Canyon | Date: June 10","vi":"Khách hàng: Green Canyon | Ngày: 10 tháng 6","units":[{"en":"Client: Green Canyon | Date: June 10","vi":"Khách hàng: Green Canyon | Ngày: 10 tháng 6"}]},{"speaker":"Document 1 — Invoice","en":"Account: 4352-0","vi":"Tài khoản: 4352-0","units":[{"en":"Account: 4352-0","vi":"Tài khoản: 4352-0"}]},{"speaker":"Document 1 — Invoice","en":"Item | Price","vi":"Mặt hàng | Giá tiền","units":[{"en":"Item | Price","vi":"Mặt hàng | Giá tiền"}]},{"speaker":"Document 1 — Invoice","en":"Garden soil, 33 cubic meters | $1,170.00","vi":"Đất trồng vườn, 33 mét khối | $1,170.00","units":[{"en":"Garden soil, 33 cubic meters | $1,170.00","vi":"Đất trồng vườn, 33 mét khối | $1,170.00"}]},{"speaker":"Document 1 — Invoice","en":"Crushed gravel, 30 metric tons | 1,710.00","vi":"Sỏi nghiền, 30 tấn | 1,710.00","units":[{"en":"Crushed gravel, 30 metric tons | 1,710.00","vi":"Sỏi nghiền, 30 tấn | 1,710.00"}]},{"speaker":"Document 1 — Invoice","en":"Decorative stone, 20 metric tons | 1,140.00","vi":"Đá trang trí, 20 tấn | 1,140.00","units":[{"en":"Decorative stone, 20 metric tons | 1,140.00","vi":"Đá trang trí, 20 tấn | 1,140.00"}]},{"speaker":"Document 1 — Invoice","en":"70 paving stones, .6 x .6 meters | 630.00","vi":"70 viên đá lát, 0,6 x 0,6 mét | 630.00","units":[{"en":"70 paving stones, .6 x .6 meters | 630.00","vi":"70 viên đá lát, 0,6 x 0,6 mét | 630.00"}]},{"speaker":"Document 1 — Invoice","en":"Subtotal | 4,650.00","vi":"Tạm tính | 4,650.00","units":[{"en":"Subtotal | 4,650.00","vi":"Tạm tính | 4,650.00"}]},{"speaker":"Document 1 — Invoice","en":"Discount (10%) | 465.00","vi":"Chiết khấu (10%) | 465.00","units":[{"en":"Discount (10%) | 465.00","vi":"Chiết khấu (10%) | 465.00"}]},{"speaker":"Document 1 — Invoice","en":"Delivery charge | 350.00","vi":"Phí giao hàng | 350.00","units":[{"en":"Delivery charge | 350.00","vi":"Phí giao hàng | 350.00"}]},{"speaker":"Document 1 — Invoice","en":"Grand Total | 4,535.00","vi":"Tổng cộng | 4,535.00","units":[{"en":"Grand Total | 4,535.00","vi":"Tổng cộng | 4,535.00"}]},{"speaker":"Document 1 — Invoice","en":"Please see the enclosed notice outlining important changes to your billing.","vi":"Vui lòng xem thông báo đính kèm nêu rõ những thay đổi quan trọng về việc thanh toán hóa đơn của quý khách.","units":[{"en":"Please see the enclosed notice outlining important changes to your billing.","vi":"Vui lòng xem thông báo đính kèm nêu rõ những thay đổi quan trọng về việc thanh toán hóa đơn của quý khách."}]},{"speaker":"Document 2 — Notice","en":"Orbys Distributors","vi":"Orbys Distributors","units":[{"en":"Orbys Distributors","vi":"Orbys Distributors"}]},{"speaker":"Document 2 — Notice","en":"To our valued customers:","vi":"Kính gửi quý khách hàng thân thiết:","units":[{"en":"To our valued customers:","vi":"Kính gửi quý khách hàng thân thiết:"}]},{"speaker":"Document 2 — Notice","en":"Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago. As a much-needed upgrade, we are switching to electronic invoicing. Starting August 1, invoices will be generated automatically each month and will be sent to the e-mail address associated with your company's account.","vi":"Hệ thống lập hóa đơn hiện tại của chúng tôi đã được vận hành kể từ khi Orbys Distributors thành lập cách đây hơn hai mươi năm. Để đáp ứng nhu cầu nâng cấp thiết yếu, chúng tôi sẽ chuyển sang sử dụng hóa đơn điện tử. Bắt đầu từ ngày 1 tháng 8, hóa đơn sẽ được tạo tự động hằng tháng và gửi về địa chỉ e-mail liên kết với tài khoản công ty của quý khách.","units":[{"en":"Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago.","vi":"Hệ thống lập hóa đơn hiện tại của chúng tôi đã được vận hành kể từ khi Orbys Distributors thành lập cách đây hơn hai mươi năm."},{"en":"As a much-needed upgrade, we are switching to electronic invoicing.","vi":"Để đáp ứng nhu cầu nâng cấp thiết yếu, chúng tôi sẽ chuyển sang sử dụng hóa đơn điện tử."},{"en":"Starting August 1, invoices will be generated automatically each month and will be sent to the e-mail address associated with your company's account.","vi":"Bắt đầu từ ngày 1 tháng 8, hóa đơn sẽ được tạo tự động hằng tháng và gửi về địa chỉ e-mail liên kết với tài khoản công ty của quý khách."}]},{"speaker":"Document 2 — Notice","en":"Rest assured that our long-standing incentives remain in place:","vi":"Quý khách hoàn toàn yên tâm rằng các chính sách ưu đãi lâu năm của chúng tôi vẫn được giữ nguyên:","units":[{"en":"Rest assured that our long-standing incentives remain in place:","vi":"Quý khách hoàn toàn yên tâm rằng các chính sách ưu đãi lâu năm của chúng tôi vẫn được giữ nguyên:"}]},{"speaker":"Document 2 — Notice","en":"• A 10% discount for orders of more than $4,000","vi":"• Giảm giá 10% cho các đơn hàng có giá trị trên $4,000","units":[{"en":"• A 10% discount for orders of more than $4,000","vi":"• Giảm giá 10% cho các đơn hàng có giá trị trên $4,000"}]},{"speaker":"Document 2 — Notice","en":"• A 20% discount for charitable organizations","vi":"• Giảm giá 20% dành cho các tổ chức từ thiện","units":[{"en":"• A 20% discount for charitable organizations","vi":"• Giảm giá 20% dành cho các tổ chức từ thiện"}]},{"speaker":"Document 2 — Notice","en":"• Free deliveries to locations within 5 miles of one of our supply centers","vi":"• Giao hàng miễn phí đến các địa điểm trong phạm vi 5 dặm tính từ một trong các trung tâm cung ứng của chúng tôi","units":[{"en":"• Free deliveries to locations within 5 miles of one of our supply centers","vi":"• Giao hàng miễn phí đến các địa điểm trong phạm vi 5 dặm tính từ một trong các trung tâm cung ứng của chúng tôi"}]},{"speaker":"Document 2 — Notice","en":"• Free samples for members of our Frequent Buyer Club","vi":"• Tặng mẫu dùng thử miễn phí cho thành viên Câu lạc bộ Khách hàng Thường xuyên","units":[{"en":"• Free samples for members of our Frequent Buyer Club","vi":"• Tặng mẫu dùng thử miễn phí cho thành viên Câu lạc bộ Khách hàng Thường xuyên"}]},{"speaker":"Document 2 — Notice","en":"More information about our transition to electronic invoicing is available on our Web site. Thank you for your support. Orbys Distributors appreciates your business.","vi":"Thông tin chi tiết về quá trình chuyển đổi sang hóa đơn điện tử hiện đã được đăng tải trên trang web của chúng tôi. Cảm ơn sự ủng hộ của quý khách. Orbys Distributors rất trân trọng sự đồng hành của quý khách.","units":[{"en":"More information about our transition to electronic invoicing is available on our Web site.","vi":"Thông tin chi tiết về quá trình chuyển đổi sang hóa đơn điện tử hiện đã được đăng tải trên trang web của chúng tôi."},{"en":"Thank you for your support.","vi":"Cảm ơn sự ủng hộ của quý khách."},{"en":"Orbys Distributors appreciates your business.","vi":"Orbys Distributors rất trân trọng sự đồng hành của quý khách."}]},{"speaker":"Document 3 — E-mail","en":"To: Mary Peterson, Billing Department","vi":"Đến: Mary Peterson, Phòng Thanh toán","units":[{"en":"To: Mary Peterson, Billing Department","vi":"Đến: Mary Peterson, Phòng Thanh toán"}]},{"speaker":"Document 3 — E-mail","en":"From: Tanvir Singh, Account Manager","vi":"Từ: Tanvir Singh, Quản lý Khách hàng","units":[{"en":"From: Tanvir Singh, Account Manager","vi":"Từ: Tanvir Singh, Quản lý Khách hàng"}]},{"speaker":"Document 3 — E-mail","en":"Date: September 12","vi":"Ngày: 12 tháng 9","units":[{"en":"Date: September 12","vi":"Ngày: 12 tháng 9"}]},{"speaker":"Document 3 — E-mail","en":"Subject: Account 1012-4","vi":"Chủ đề: Tài khoản 1012-4","units":[{"en":"Subject: Account 1012-4","vi":"Chủ đề: Tài khoản 1012-4"}]},{"speaker":"Document 3 — E-mail","en":"Hello Mary,","vi":"Chào Mary,","units":[{"en":"Hello Mary,","vi":"Chào Mary,"}]},{"speaker":"Document 3 — E-mail","en":"I received a query today from William Tesoriero at Tesoriero Remodeling. His monthly invoice for August never arrived.","vi":"Hôm nay tôi nhận được phản hồi thắc mắc từ ông William Tesoriero tại Công ty Tesoriero Remodeling. Hóa đơn tháng 8 của ông ấy vẫn chưa được gửi tới.","units":[{"en":"I received a query today from William Tesoriero at Tesoriero Remodeling.","vi":"Hôm nay tôi nhận được phản hồi thắc mắc từ ông William Tesoriero tại Công ty Tesoriero Remodeling."},{"en":"His monthly invoice for August never arrived.","vi":"Hóa đơn tháng 8 của ông ấy vẫn chưa được gửi tới."}]},{"speaker":"Document 3 — E-mail","en":"As you know, Mr. Tesoriero was one of our very first customers. Since we first opened for business, he has made purchases from us on a regular basis. He is also a member of the Frequent Buyer Club. This is a customer we absolutely do not want to lose. I explained to him that the rollout of our electronic invoicing system did not go as smoothly as we had hoped and promised that this would not happen again.","vi":"Như chị biết đấy, ông Tesoriero là một trong những khách hàng đầu tiên của chúng ta. Kể từ ngày đầu chúng ta đi vào hoạt động, ông ấy đã luôn đặt mua hàng thường xuyên. Ông ấy cũng là thành viên của Câu lạc bộ Khách hàng Thường xuyên. Đây là vị khách hàng mà chúng ta tuyệt đối không muốn để mất. Tôi đã giải thích với ông ấy rằng quá trình triển khai hệ thống hóa đơn điện tử của chúng ta diễn ra chưa suôn sẻ như kỳ vọng và cam kết sự việc tương tự sẽ không tái diễn.","units":[{"en":"As you know, Mr. Tesoriero was one of our very first customers.","vi":"Như chị biết đấy, ông Tesoriero là một trong những khách hàng đầu tiên của chúng ta."},{"en":"Since we first opened for business, he has made purchases from us on a regular basis.","vi":"Kể từ ngày đầu chúng ta đi vào hoạt động, ông ấy đã luôn đặt mua hàng thường xuyên."},{"en":"He is also a member of the Frequent Buyer Club.","vi":"Ông ấy cũng là thành viên của Câu lạc bộ Khách hàng Thường xuyên."},{"en":"This is a customer we absolutely do not want to lose.","vi":"Đây là vị khách hàng mà chúng ta tuyệt đối không muốn để mất."},{"en":"I explained to him that the rollout of our electronic invoicing system did not go as smoothly as we had hoped and promised that this would not happen again.","vi":"Tôi đã giải thích với ông ấy rằng quá trình triển khai hệ thống hóa đơn điện tử của chúng ta diễn ra chưa suôn sẻ như kỳ vọng và cam kết sự việc tương tự sẽ không tái diễn."}]},{"speaker":"Document 3 — E-mail","en":"I would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero.","vi":"Rất mong chị vui lòng kiểm tra ngay nguyên nhân sự cố và gửi hóa đơn tháng 8 cho ông Tesoriero.","units":[{"en":"I would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero.","vi":"Rất mong chị vui lòng kiểm tra ngay nguyên nhân sự cố và gửi hóa đơn tháng 8 cho ông Tesoriero."}]},{"speaker":"Document 3 — E-mail","en":"Tanvir","vi":"Tanvir","units":[{"en":"Tanvir","vi":"Tanvir"}]}],"vocab":[{"word":"on a regular basis","pos":"phr","ipa":"/ɑːn ə ˈreɡjələr ˈbeɪsɪs/","meaning":"một cách thường xuyên, đều đặn"},{"word":"rollout","pos":"n","ipa":"/ˈroʊlaʊt/","meaning":"sự triển khai, ra mắt (hệ thống mới)"},{"word":"remodeling","pos":"n","ipa":"/ˌriːˈmɑːdəlɪŋ/","meaning":"việc cải tạo, tu sửa nhà cửa"},{"word":"purchase","pos":"n","ipa":"/ˈpɜːrtʃəs/","meaning":"lần mua hàng, đơn mua hàng"}],"isScanBacked":false,"docTypeLabel":"invoice, notice, and e-mail","context":"Invoice, notice, and e-mail — Orbys Distributors electronic invoicing transition","grammarType":"Part 7 — Suy luận & Hàm ý văn bản (Inference & Implied Meaning)","formula":"CÔNG THỨC PART 7 — SUY LUẬN MỐC THỜI GIAN QUA 2 VĂN BẢN (DOCUMENT 2 + DOCUMENT 3): Ghép chi tiết 'one of our very first customers' từ ngày mới mở (Document 3) với tuổi đời công ty 'founded over twenty years ago' (Document 2).","optionAnalysis":{"A":"Sai vì ông Tesoriero chỉ gửi câu hỏi thắc mắc về hóa đơn tháng 8 bị thiếu ('received a query'), không yêu cầu gặp trực tiếp ông Singh.","B":"Sai vì ông Tesoriero là khách hàng lâu năm đến từ Tesoriero Remodeling ('one of our very first customers'), không phải ứng viên tìm việc.","C":"Sai vì văn bản chỉ nhắc hóa đơn tháng 8 của ông bị thất lạc, không hề có thông tin nào về đơn đặt mua máy móc xây dựng.","D":"Đúng vì Document 3 nêu ông là một trong những khách hàng đầu tiên từ ngày công ty mới mở, kết hợp với Document 2 xác nhận công ty thành lập hơn 20 năm trước."},"evDocIdx":2,"evTargets":[{"badge":"Câu 199 · Đáp án D","opt":"D","isCorrect":true,"quote":"As you know, Mr. Tesoriero was one of our very first customers.","viQuote":"Như chị biết đấy, ông Tesoriero là một trong những khách hàng đầu tiên của chúng ta."},{"badge":"Câu 199 · Đáp án D","opt":"D","isCorrect":true,"quote":"Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago.","viQuote":"Hệ thống lập hóa đơn hiện tại của chúng tôi đã được vận hành kể từ khi Orbys Distributors thành lập cách đây hơn hai mươi năm."}],"evQuotes":["As you know, Mr. Tesoriero was one of our very first customers.","Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago."]},{"q":200,"part":7,"group_id":"E25_T01_G196_200","audio":null,"passageImgs":["web_assets/ets2025/p67/E25_T01_rc27.webp","web_assets/ets2025/p67/E25_T01_rc28.webp"],"stem_en":"What does Mr. Singh ask Ms. Peterson to do?","stem_vi":"Ông Singh yêu cầu bà Peterson làm gì?","options":{"A":{"en":"Make a bill payment","vi":"Thực hiện thanh toán hóa đơn"},"B":{"en":"Solve a problem","vi":"Giải quyết một sự cố"},"C":{"en":"Confirm an order","vi":"Xác nhận một đơn hàng"},"D":{"en":"Update an account number","vi":"Cập nhật số tài khoản"}},"ans":"B","evidence_quote":"I would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero.","explanation":"Đáp án đúng: (B) Giải quyết một sự cố — Ông Singh nhờ bà Peterson ở bộ phận hóa đơn khẩn trương điều tra trục trặc hệ thống khiến hóa đơn tháng 8 chưa gửi tới khách và gửi lại hóa đơn cho ông Tesoriero.\nDẫn chứng: \"I would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero.\" (Document 3 — E-mail: 'investigate the problem without delay and send the invoice' tương ứng với 'Solve a problem').\nPhân tích bẫy:\n- (A) Bẫy đảo vai trò thanh toán: Bà Peterson làm ở Bộ phận Hóa đơn ('Billing Department') có nhiệm vụ phát hành và gửi hóa đơn cho khách, không phải đi trả tiền hóa đơn.\n- (C) Bẫy sai bản chất sự việc: Sự việc phát sinh do lỗi triển khai hệ thống hóa đơn điện tử khiến hóa đơn tháng 8 không đến tay khách, không phải yêu cầu xác nhận đơn hàng mới.\n- (D) Bẫy nhiễu tiêu đề e-mail: Dòng Subject ghi sẵn mã tài khoản 'Account 1012-4', không có yêu cầu nào bảo bà Peterson cập nhật hay sửa số tài khoản.","lines":[{"speaker":"Document 1 — Invoice","en":"Orbys Distributors","vi":"Orbys Distributors","units":[{"en":"Orbys Distributors","vi":"Orbys Distributors"}]},{"speaker":"Document 1 — Invoice","en":"Client: Green Canyon | Date: June 10","vi":"Khách hàng: Green Canyon | Ngày: 10 tháng 6","units":[{"en":"Client: Green Canyon | Date: June 10","vi":"Khách hàng: Green Canyon | Ngày: 10 tháng 6"}]},{"speaker":"Document 1 — Invoice","en":"Account: 4352-0","vi":"Tài khoản: 4352-0","units":[{"en":"Account: 4352-0","vi":"Tài khoản: 4352-0"}]},{"speaker":"Document 1 — Invoice","en":"Item | Price","vi":"Mặt hàng | Giá tiền","units":[{"en":"Item | Price","vi":"Mặt hàng | Giá tiền"}]},{"speaker":"Document 1 — Invoice","en":"Garden soil, 33 cubic meters | $1,170.00","vi":"Đất trồng vườn, 33 mét khối | $1,170.00","units":[{"en":"Garden soil, 33 cubic meters | $1,170.00","vi":"Đất trồng vườn, 33 mét khối | $1,170.00"}]},{"speaker":"Document 1 — Invoice","en":"Crushed gravel, 30 metric tons | 1,710.00","vi":"Sỏi nghiền, 30 tấn | 1,710.00","units":[{"en":"Crushed gravel, 30 metric tons | 1,710.00","vi":"Sỏi nghiền, 30 tấn | 1,710.00"}]},{"speaker":"Document 1 — Invoice","en":"Decorative stone, 20 metric tons | 1,140.00","vi":"Đá trang trí, 20 tấn | 1,140.00","units":[{"en":"Decorative stone, 20 metric tons | 1,140.00","vi":"Đá trang trí, 20 tấn | 1,140.00"}]},{"speaker":"Document 1 — Invoice","en":"70 paving stones, .6 x .6 meters | 630.00","vi":"70 viên đá lát, 0,6 x 0,6 mét | 630.00","units":[{"en":"70 paving stones, .6 x .6 meters | 630.00","vi":"70 viên đá lát, 0,6 x 0,6 mét | 630.00"}]},{"speaker":"Document 1 — Invoice","en":"Subtotal | 4,650.00","vi":"Tạm tính | 4,650.00","units":[{"en":"Subtotal | 4,650.00","vi":"Tạm tính | 4,650.00"}]},{"speaker":"Document 1 — Invoice","en":"Discount (10%) | 465.00","vi":"Chiết khấu (10%) | 465.00","units":[{"en":"Discount (10%) | 465.00","vi":"Chiết khấu (10%) | 465.00"}]},{"speaker":"Document 1 — Invoice","en":"Delivery charge | 350.00","vi":"Phí giao hàng | 350.00","units":[{"en":"Delivery charge | 350.00","vi":"Phí giao hàng | 350.00"}]},{"speaker":"Document 1 — Invoice","en":"Grand Total | 4,535.00","vi":"Tổng cộng | 4,535.00","units":[{"en":"Grand Total | 4,535.00","vi":"Tổng cộng | 4,535.00"}]},{"speaker":"Document 1 — Invoice","en":"Please see the enclosed notice outlining important changes to your billing.","vi":"Vui lòng xem thông báo đính kèm nêu rõ những thay đổi quan trọng về việc thanh toán hóa đơn của quý khách.","units":[{"en":"Please see the enclosed notice outlining important changes to your billing.","vi":"Vui lòng xem thông báo đính kèm nêu rõ những thay đổi quan trọng về việc thanh toán hóa đơn của quý khách."}]},{"speaker":"Document 2 — Notice","en":"Orbys Distributors","vi":"Orbys Distributors","units":[{"en":"Orbys Distributors","vi":"Orbys Distributors"}]},{"speaker":"Document 2 — Notice","en":"To our valued customers:","vi":"Kính gửi quý khách hàng thân thiết:","units":[{"en":"To our valued customers:","vi":"Kính gửi quý khách hàng thân thiết:"}]},{"speaker":"Document 2 — Notice","en":"Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago. As a much-needed upgrade, we are switching to electronic invoicing. Starting August 1, invoices will be generated automatically each month and will be sent to the e-mail address associated with your company's account.","vi":"Hệ thống lập hóa đơn hiện tại của chúng tôi đã được vận hành kể từ khi Orbys Distributors thành lập cách đây hơn hai mươi năm. Để đáp ứng nhu cầu nâng cấp thiết yếu, chúng tôi sẽ chuyển sang sử dụng hóa đơn điện tử. Bắt đầu từ ngày 1 tháng 8, hóa đơn sẽ được tạo tự động hằng tháng và gửi về địa chỉ e-mail liên kết với tài khoản công ty của quý khách.","units":[{"en":"Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago.","vi":"Hệ thống lập hóa đơn hiện tại của chúng tôi đã được vận hành kể từ khi Orbys Distributors thành lập cách đây hơn hai mươi năm."},{"en":"As a much-needed upgrade, we are switching to electronic invoicing.","vi":"Để đáp ứng nhu cầu nâng cấp thiết yếu, chúng tôi sẽ chuyển sang sử dụng hóa đơn điện tử."},{"en":"Starting August 1, invoices will be generated automatically each month and will be sent to the e-mail address associated with your company's account.","vi":"Bắt đầu từ ngày 1 tháng 8, hóa đơn sẽ được tạo tự động hằng tháng và gửi về địa chỉ e-mail liên kết với tài khoản công ty của quý khách."}]},{"speaker":"Document 2 — Notice","en":"Rest assured that our long-standing incentives remain in place:","vi":"Quý khách hoàn toàn yên tâm rằng các chính sách ưu đãi lâu năm của chúng tôi vẫn được giữ nguyên:","units":[{"en":"Rest assured that our long-standing incentives remain in place:","vi":"Quý khách hoàn toàn yên tâm rằng các chính sách ưu đãi lâu năm của chúng tôi vẫn được giữ nguyên:"}]},{"speaker":"Document 2 — Notice","en":"• A 10% discount for orders of more than $4,000","vi":"• Giảm giá 10% cho các đơn hàng có giá trị trên $4,000","units":[{"en":"• A 10% discount for orders of more than $4,000","vi":"• Giảm giá 10% cho các đơn hàng có giá trị trên $4,000"}]},{"speaker":"Document 2 — Notice","en":"• A 20% discount for charitable organizations","vi":"• Giảm giá 20% dành cho các tổ chức từ thiện","units":[{"en":"• A 20% discount for charitable organizations","vi":"• Giảm giá 20% dành cho các tổ chức từ thiện"}]},{"speaker":"Document 2 — Notice","en":"• Free deliveries to locations within 5 miles of one of our supply centers","vi":"• Giao hàng miễn phí đến các địa điểm trong phạm vi 5 dặm tính từ một trong các trung tâm cung ứng của chúng tôi","units":[{"en":"• Free deliveries to locations within 5 miles of one of our supply centers","vi":"• Giao hàng miễn phí đến các địa điểm trong phạm vi 5 dặm tính từ một trong các trung tâm cung ứng của chúng tôi"}]},{"speaker":"Document 2 — Notice","en":"• Free samples for members of our Frequent Buyer Club","vi":"• Tặng mẫu dùng thử miễn phí cho thành viên Câu lạc bộ Khách hàng Thường xuyên","units":[{"en":"• Free samples for members of our Frequent Buyer Club","vi":"• Tặng mẫu dùng thử miễn phí cho thành viên Câu lạc bộ Khách hàng Thường xuyên"}]},{"speaker":"Document 2 — Notice","en":"More information about our transition to electronic invoicing is available on our Web site. Thank you for your support. Orbys Distributors appreciates your business.","vi":"Thông tin chi tiết về quá trình chuyển đổi sang hóa đơn điện tử hiện đã được đăng tải trên trang web của chúng tôi. Cảm ơn sự ủng hộ của quý khách. Orbys Distributors rất trân trọng sự đồng hành của quý khách.","units":[{"en":"More information about our transition to electronic invoicing is available on our Web site.","vi":"Thông tin chi tiết về quá trình chuyển đổi sang hóa đơn điện tử hiện đã được đăng tải trên trang web của chúng tôi."},{"en":"Thank you for your support.","vi":"Cảm ơn sự ủng hộ của quý khách."},{"en":"Orbys Distributors appreciates your business.","vi":"Orbys Distributors rất trân trọng sự đồng hành của quý khách."}]},{"speaker":"Document 3 — E-mail","en":"To: Mary Peterson, Billing Department","vi":"Đến: Mary Peterson, Phòng Thanh toán","units":[{"en":"To: Mary Peterson, Billing Department","vi":"Đến: Mary Peterson, Phòng Thanh toán"}]},{"speaker":"Document 3 — E-mail","en":"From: Tanvir Singh, Account Manager","vi":"Từ: Tanvir Singh, Quản lý Khách hàng","units":[{"en":"From: Tanvir Singh, Account Manager","vi":"Từ: Tanvir Singh, Quản lý Khách hàng"}]},{"speaker":"Document 3 — E-mail","en":"Date: September 12","vi":"Ngày: 12 tháng 9","units":[{"en":"Date: September 12","vi":"Ngày: 12 tháng 9"}]},{"speaker":"Document 3 — E-mail","en":"Subject: Account 1012-4","vi":"Chủ đề: Tài khoản 1012-4","units":[{"en":"Subject: Account 1012-4","vi":"Chủ đề: Tài khoản 1012-4"}]},{"speaker":"Document 3 — E-mail","en":"Hello Mary,","vi":"Chào Mary,","units":[{"en":"Hello Mary,","vi":"Chào Mary,"}]},{"speaker":"Document 3 — E-mail","en":"I received a query today from William Tesoriero at Tesoriero Remodeling. His monthly invoice for August never arrived.","vi":"Hôm nay tôi nhận được phản hồi thắc mắc từ ông William Tesoriero tại Công ty Tesoriero Remodeling. Hóa đơn tháng 8 của ông ấy vẫn chưa được gửi tới.","units":[{"en":"I received a query today from William Tesoriero at Tesoriero Remodeling.","vi":"Hôm nay tôi nhận được phản hồi thắc mắc từ ông William Tesoriero tại Công ty Tesoriero Remodeling."},{"en":"His monthly invoice for August never arrived.","vi":"Hóa đơn tháng 8 của ông ấy vẫn chưa được gửi tới."}]},{"speaker":"Document 3 — E-mail","en":"As you know, Mr. Tesoriero was one of our very first customers. Since we first opened for business, he has made purchases from us on a regular basis. He is also a member of the Frequent Buyer Club. This is a customer we absolutely do not want to lose. I explained to him that the rollout of our electronic invoicing system did not go as smoothly as we had hoped and promised that this would not happen again.","vi":"Như chị biết đấy, ông Tesoriero là một trong những khách hàng đầu tiên của chúng ta. Kể từ ngày đầu chúng ta đi vào hoạt động, ông ấy đã luôn đặt mua hàng thường xuyên. Ông ấy cũng là thành viên của Câu lạc bộ Khách hàng Thường xuyên. Đây là vị khách hàng mà chúng ta tuyệt đối không muốn để mất. Tôi đã giải thích với ông ấy rằng quá trình triển khai hệ thống hóa đơn điện tử của chúng ta diễn ra chưa suôn sẻ như kỳ vọng và cam kết sự việc tương tự sẽ không tái diễn.","units":[{"en":"As you know, Mr. Tesoriero was one of our very first customers.","vi":"Như chị biết đấy, ông Tesoriero là một trong những khách hàng đầu tiên của chúng ta."},{"en":"Since we first opened for business, he has made purchases from us on a regular basis.","vi":"Kể từ ngày đầu chúng ta đi vào hoạt động, ông ấy đã luôn đặt mua hàng thường xuyên."},{"en":"He is also a member of the Frequent Buyer Club.","vi":"Ông ấy cũng là thành viên của Câu lạc bộ Khách hàng Thường xuyên."},{"en":"This is a customer we absolutely do not want to lose.","vi":"Đây là vị khách hàng mà chúng ta tuyệt đối không muốn để mất."},{"en":"I explained to him that the rollout of our electronic invoicing system did not go as smoothly as we had hoped and promised that this would not happen again.","vi":"Tôi đã giải thích với ông ấy rằng quá trình triển khai hệ thống hóa đơn điện tử của chúng ta diễn ra chưa suôn sẻ như kỳ vọng và cam kết sự việc tương tự sẽ không tái diễn."}]},{"speaker":"Document 3 — E-mail","en":"I would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero.","vi":"Rất mong chị vui lòng kiểm tra ngay nguyên nhân sự cố và gửi hóa đơn tháng 8 cho ông Tesoriero.","units":[{"en":"I would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero.","vi":"Rất mong chị vui lòng kiểm tra ngay nguyên nhân sự cố và gửi hóa đơn tháng 8 cho ông Tesoriero."}]},{"speaker":"Document 3 — E-mail","en":"Tanvir","vi":"Tanvir","units":[{"en":"Tanvir","vi":"Tanvir"}]}],"vocab":[{"word":"investigate","pos":"v","ipa":"/ɪnˈvestɪɡeɪt/","meaning":"điều tra, kiểm tra nguyên nhân"},{"word":"without delay","pos":"phr","ipa":"/wɪˈðaʊt dɪˈleɪ/","meaning":"ngay lập tức, không chậm trễ"},{"word":"query","pos":"n","ipa":"/ˈkwɪri/","meaning":"câu hỏi, thắc mắc"},{"word":"billing","pos":"n","ipa":"/ˈbɪlɪŋ/","meaning":"bộ phận lập và thanh toán hóa đơn"}],"isScanBacked":false,"docTypeLabel":"invoice, notice, and e-mail","context":"Invoice, notice, and e-mail — Orbys Distributors electronic invoicing transition","grammarType":"Part 7 — Chi tiết văn bản & Paraphrase dẫn chứng (Detail & Cross-Reference)","formula":"CÔNG THỨC PART 7 — ĐỌC HIỂU YÊU CẦU CUỐI E-MAIL (DOCUMENT 3): Định vị cấu trúc nhờ vả lịch sự 'I would appreciate it if you could please' ở đoạn kết -> Paraphrase 'investigate the problem' thành 'Solve a problem'.","optionAnalysis":{"A":"Sai vì bà Peterson thuộc Billing Department được giao kiểm tra lỗi phát hành hóa đơn cho khách hàng, không phải thực hiện thanh toán hóa đơn.","B":"Đúng vì đoạn cuối Document 3 yêu cầu bà Peterson điều tra sự cố ngay lập tức ('investigate the problem without delay') và gửi bù hóa đơn tháng 8 cho ông Tesoriero.","C":"Sai vì khúc mắc là hóa đơn tháng 8 bị thất lạc do lỗi triển khai hệ thống hóa đơn điện tử, không phải việc xác nhận một đơn hàng.","D":"Sai vì tiêu đề e-mail chỉ cung cấp mã tài khoản 'Account 1012-4' để tra cứu, không yêu cầu cập nhật số tài khoản."},"evDocIdx":2,"evTargets":[{"badge":"Câu 200 · Đáp án B","opt":"B","isCorrect":true,"quote":"I would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero.","viQuote":"Rất mong chị vui lòng kiểm tra ngay nguyên nhân sự cố và gửi hóa đơn tháng 8 cho ông Tesoriero."}],"evQuotes":["I would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero."]}];
